    var filteredSearchResults: [SearchResultLink] {
        let filter = searchResultFilter.trimmed
        let needsKnownSources = searchResultKnownFilter != .all ||
            Self.searchResultFilterReferencesKnownSources(filter) ||
            searchResultSortMode == .done
        let knownSources = needsKnownSources ? searchKnownSources() : []
        let textFiltered = filter.isEmpty
            ? searchResults
            : Self.filteredSearchResults(searchResults, filter: filter, knownSources: knownSources)
        let filtered = Self.filteredSearchResults(
            textFiltered,
            knownFilter: searchResultKnownFilter,
            knownSources: knownSources
        )
        return Self.sortedSearchResults(
            filtered,
            mode: searchResultSortMode,
            descending: searchResultSortDescending,
            knownSources: knownSources
        )
    }

