    var queueGroupNames: [String] {
        queueGroupOptions.map(\.name)
    }

    var queueGroupOptions: [QueueGroup] {
        queueGroups.sorted {
            let comparison = $0.name.localizedStandardCompare($1.name)
            if comparison == .orderedSame {
                return $0.id.uuidString < $1.id.uuidString
            }
            return comparison == .orderedAscending
        }
    }

    var progressWindowActiveJobs: [DownloadJob] {
        jobs.filter { $0.status == .resolving || $0.status == .downloading }
    }

    var progressWindowVisibleJobs: [DownloadJob] {
        let active = progressWindowActiveJobs
        if !active.isEmpty {
            return active
        }
        return jobs.filter { $0.status != .finished }.prefix(12).map { $0 }
    }

    var progressWindowCompletedUnits: Int {
        jobs.reduce(0) { $0 + Self.progressWindowUnits(for: $1).completed }
    }

    var progressWindowTotalUnits: Int {
        jobs.reduce(0) { $0 + Self.progressWindowUnits(for: $1).total }
    }

    var progressWindowFraction: Double {
        let total = progressWindowTotalUnits
        guard total > 0 else { return 0 }
        return min(1, max(0, Double(progressWindowCompletedUnits) / Double(total)))
    }

    var progressWindowStatusText: String {
        guard !jobs.isEmpty else { return "No tasks" }
        let percent = Int((progressWindowFraction * 100).rounded())
        let activeCount = progressWindowActiveJobs.count
        let finishedCount = jobs.filter { $0.status == .finished }.count
        return "\(percent)% [\(progressWindowCompletedUnits)/\(progressWindowTotalUnits)] · \(activeCount) active · \(finishedCount)/\(jobs.count) finished"
    }

    nonisolated static func progressWindowUnits(for job: DownloadJob) -> (completed: Int, total: Int) {
        let total = max(1, job.total)
        switch job.status {
        case .finished, .failed, .cancelled:
            return (total, total)
        case .queued, .resolving:
            return (0, total)
        case .downloading:
            let clampedProgress = max(0, min(1, job.progress))
            let progressCompleted = Int((clampedProgress * Double(total)).rounded(.down))
            return (min(total, max(0, max(job.completed, progressCompleted))), total)
        }
    }

