    }

    var activePythonTheme: PythonThemeDescriptor? {
        let key = selectedPythonThemeKey.trimmed.lowercased()
        guard !key.isEmpty else { return nil }
        return availablePythonThemes.first { $0.key == key }
    }

    var preferredColorScheme: ColorScheme? {
        switch activePythonTheme?.appearance {
        case .light: return .light
        case .dark: return .dark
        case .system, .none: return Self.preferredColorScheme(for: appAppearanceMode)
        }
