    private static func themeColor(from value: String?) -> Color? {
        guard var raw = value?.trimmed, !raw.isEmpty else { return nil }
        if raw.hasPrefix("#") { raw.removeFirst() }
        guard raw.count == 6, raw.allSatisfy(\.isHexDigit),
              let red = Int(raw.prefix(2), radix: 16),
              let green = Int(raw.dropFirst(2).prefix(2), radix: 16),
              let blue = Int(raw.dropFirst(4).prefix(2), radix: 16) else {
            return nil
        }
        return Color(
            red: Double(red) / 255,
            green: Double(green) / 255,
            blue: Double(blue) / 255
        )
    }

    static func defaultAppShortcutAssignments() -> [AppShortcutCommand: AppShortcut] {
        Dictionary(uniqueKeysWithValues: AppShortcutCommand.allCases.map { command in
            (command, command.defaultShortcut)
        })
    }

    static func loadAppShortcutAssignments(defaults: UserDefaults = .standard) -> [AppShortcutCommand: AppShortcut] {
        var assignments = defaultAppShortcutAssignments()
        guard let data = defaults.data(forKey: "appShortcutAssignments"),
              let decoded = try? JSONDecoder().decode([String: AppShortcut].self, from: data) else {
            return assignments
        }
        for (rawCommand, shortcut) in decoded {
            guard let command = AppShortcutCommand(rawValue: rawCommand) else { continue }
            assignments[command] = shortcut.normalized()
        }
        return assignments
    }

    private func persistAppShortcutAssignments() {
        let rawAssignments = Dictionary(uniqueKeysWithValues: AppShortcutCommand.allCases.map { command in
            (command.rawValue, shortcut(for: command))
        })
        if let data = try? JSONEncoder().encode(rawAssignments) {
            UserDefaults.standard.set(data, forKey: "appShortcutAssignments")
        }
    }

    var interfaceFont: Font? {
        let family = Self.normalizedInterfaceFontFamily(interfaceFontFamily)
        let pointSize = CGFloat(interfaceFontSize.pointSize)
        if family.isEmpty {
            return interfaceFontSize == .defaultSize ? nil : .system(size: pointSize)
        }
        return .custom(family, size: pointSize)
    }

    var interfaceFontSummary: String {
        let family = Self.normalizedInterfaceFontFamily(interfaceFontFamily)
        let displayFamily = family.isEmpty
            ? AppLocalization.text("시스템", language: interfaceLanguage)
            : family
        return "\(displayFamily) / \(interfaceFontSize.label)"
    }

