    init(niconicoLiveResolver: NiconicoLiveResolver = NiconicoLiveResolver()) {
        self.niconicoLiveResolver = niconicoLiveResolver
        let defaults = UserDefaults.standard
        let requestedInterfaceLanguage =
            ProcessInfo.processInfo.environment["HITOMI_NATIVE_INTERFACE_LANGUAGE"]
            ?? defaults.string(forKey: AppInterfaceLanguage.defaultsKey)
        let selectedInterfaceLanguage = AppInterfaceLanguage.normalized(requestedInterfaceLanguage)
        interfaceLanguage = selectedInterfaceLanguage
        defaults.set(selectedInterfaceLanguage.rawValue, forKey: AppInterfaceLanguage.defaultsKey)
        userDataStore = UserDataStore()
        var loadedUserData = userDataStore.load()
        var removedTransientTestRecords = 0
        if Self.shouldCleanTransientTestRecordsAtStartup {
            let queueCountBeforeTestArtifactCleanup = loadedUserData.queue.count
            let historyCountBeforeTestArtifactCleanup = loadedUserData.history.count
            loadedUserData.queue.removeAll {
                Self.isTransientTestRecord(source: $0.source, outputPath: $0.outputPath)
            }
            loadedUserData.history.removeAll {
                Self.isTransientTestRecord(source: $0.source, outputPath: $0.outputPath)
            }
            removedTransientTestRecords =
                queueCountBeforeTestArtifactCleanup - loadedUserData.queue.count +
                historyCountBeforeTestArtifactCleanup - loadedUserData.history.count
        }
        let migratedQueueOrder = loadedUserData.queueOrderVersion < 2
        if migratedQueueOrder {
            loadedUserData.queue = Self.migratedNewestFirstQueue(loadedUserData.queue)
            loadedUserData.queueOrderVersion = 2
        }
        if migratedQueueOrder || removedTransientTestRecords > 0 {
            _ = userDataStore.save(loadedUserData)
        }
        var restoredJobs = loadedUserData.queue.map { job in
            Self.isPendingQueueRemoval(job) ? job : Self.restoredQueueJob(job)
        }
        let restoredGroups = Self.normalizedQueueGroups(loadedUserData.queueGroups, jobs: &restoredJobs)
        let migratedQueueGroups = restoredGroups != loadedUserData.queueGroups || restoredJobs != loadedUserData.queue
        loadedUserData.queue = restoredJobs
        loadedUserData.queueGroups = restoredGroups
        userData = loadedUserData
        inputText = userData.inputTextDraft
        inputCursorUTF16Offset = (loadedUserData.inputTextDraft as NSString).length
        bookmarks = userData.bookmarks
        history = userData.history
        jobs = restoredJobs
        queueGroups = restoredGroups
        siteRules = userData.siteRules
        queueFilterBookmarks = userData.queueFilterBookmarks
        searchBookmarks = userData.searchBookmarks
        let loadedSearchProviders = userData.searchProviders
        searchProviders = loadedSearchProviders
        selectedSearchProviderID = loadedSearchProviders.first?.id ?? SearchProvider.defaultProviders[0].id
        searchDeduplicateResults = defaults.object(forKey: "searchDeduplicateResults") as? Bool ?? true
        searchHideKnownResults = defaults.object(forKey: "searchHideKnownResults") as? Bool ?? false
        searchResultKnownFilter = SearchResultKnownFilter(rawValue: defaults.string(forKey: "searchResultKnownFilter") ?? "") ?? .all
        hitomiExcludedTagsText = defaults.string(forKey: "hitomiExcludedTagsText") ?? ""
        let environment = ProcessInfo.processInfo.environment
        let environmentDestinationPath = (
            environment["HITOMI_BADAYO_DESTINATION_PATH"] ??
                environment["HITOMI_NATIVE_DESTINATION_PATH"]
        )?.trimmed ?? ""
        let savedDestinationPath = defaults.string(forKey: "destinationPath") ?? ""
        let usableSavedDestinationPath = Self.isTransientTestDestinationPath(savedDestinationPath)
            ? ""
            : savedDestinationPath
        if environmentDestinationPath.isEmpty,
           !savedDestinationPath.isEmpty,
           usableSavedDestinationPath.isEmpty {
            defaults.removeObject(forKey: "destinationPath")
        }
        destinationPath = environmentDestinationPath.isEmpty
            ? (usableSavedDestinationPath.isEmpty ? AppPaths.defaultDownloadDirectory.path : usableSavedDestinationPath)
            : environmentDestinationPath
        let storedSourceFolderNames = defaults.dictionary(forKey: "sourceFolderNames") as? [String: String] ?? [:]
        let normalizedSourceFolderNames = Dictionary(uniqueKeysWithValues: storedSourceFolderNames.map {
            (DownloadSourceFolderProfile.normalizedSourceID($0.key), $0.value)
        })
        var migratedSourceFolderNames = normalizedSourceFolderNames
        for (sourceID, folderName) in normalizedSourceFolderNames
            where DownloadSourceFolderProfile.obsoleteDefaultFolderNames(for: sourceID).contains(folderName) {
            migratedSourceFolderNames[sourceID] = DownloadSourceFolderProfile.defaultFolderName(for: sourceID)
        }
        sourceFolderNames = migratedSourceFolderNames
        if migratedSourceFolderNames != normalizedSourceFolderNames {
            defaults.set(migratedSourceFolderNames, forKey: "sourceFolderNames")
        }
        let savedSourceFolderID = DownloadSourceFolderProfile.normalizedSourceID(
            defaults.string(forKey: "selectedSourceFolderID") ?? "hitomi"
        )
        selectedSourceFolderID = DownloadSourceFolderProfile.settingsProfiles.contains(where: {
            $0.id == savedSourceFolderID
        })
            ? savedSourceFolderID
            : "hitomi"
#if TESTING
        outputSubfolderMode = .none
        folderNameTemplate = defaults.string(forKey: "folderNameTemplate") ?? ""
#else
        let sourceFolderLayoutVersion = defaults.integer(forKey: "sourceFolderLayoutVersion")
        if sourceFolderLayoutVersion < 1 {
            outputSubfolderMode = .site
            defaults.set(OutputSubfolderMode.site.rawValue, forKey: "outputSubfolderMode")
            let savedFolderTemplate = defaults.string(forKey: "folderNameTemplate")?.trimmed ?? ""
            let migratedFolderNameTemplate = savedFolderTemplate.isEmpty
                ? DownloadSourceFolderProfile.originalDefaultFolderTemplate
                : savedFolderTemplate
            folderNameTemplate = migratedFolderNameTemplate
            defaults.set(migratedFolderNameTemplate, forKey: "folderNameTemplate")
            defaults.set(1, forKey: "sourceFolderLayoutVersion")
        } else {
            outputSubfolderMode = OutputSubfolderMode(
                rawValue: defaults.string(forKey: "outputSubfolderMode") ?? ""
            ) ?? .site
            folderNameTemplate = defaults.string(forKey: "folderNameTemplate")
                ?? DownloadSourceFolderProfile.originalDefaultFolderTemplate
        }
#endif
        let loadedFileNameTemplate = defaults.string(forKey: "fileNameTemplate") ?? ""
        fileNameTemplate = loadedFileNameTemplate
        recordingFileNameTemplate = defaults.string(forKey: "recordingFileNameTemplate") ?? ""
        let storedSourceFileNameTemplates = defaults.dictionary(forKey: "sourceFileNameTemplates") as? [String: String] ?? [:]
        var loadedSourceFileNameTemplates = Dictionary(
            uniqueKeysWithValues: storedSourceFileNameTemplates.map {
                (DownloadSourceFolderProfile.normalizedSourceID($0.key), $0.value)
            }
        )
        for sourceID in NameTemplate.originalSourceFileTemplateIDs {
            guard loadedSourceFileNameTemplates[sourceID] == nil,
                  let preferenceKey = NameTemplate.originalFilePreferenceKey(for: sourceID),
                  defaults.object(forKey: preferenceKey) != nil else {
                continue
            }
            loadedSourceFileNameTemplates[sourceID] = defaults.string(forKey: preferenceKey) ?? ""
        }
        if loadedSourceFileNameTemplates["hitomi"] == nil,
           defaults.object(forKey: "hitomiFilenameTypeNumber") != nil {
            loadedSourceFileNameTemplates["hitomi"] = NameTemplate.originalHitomiFileTemplate(
                typeNumber: defaults.integer(forKey: "hitomiFilenameTypeNumber")
            )
        }
#if !TESTING
        let sourceFileNameTemplateVersion = defaults.integer(forKey: "sourceFileNameTemplateVersion")
        if sourceFileNameTemplateVersion < 1 {
            let legacyTemplate = loadedFileNameTemplate.trimmed
            for sourceID in NameTemplate.originalSourceFileTemplateIDs
                where sourceID != "hitomi" && loadedSourceFileNameTemplates[sourceID] == nil {
                loadedSourceFileNameTemplates[sourceID] = legacyTemplate.isEmpty
                    ? NameTemplate.originalFileDefault(for: sourceID) ?? ""
                    : legacyTemplate
            }
        }
        if sourceFileNameTemplateVersion < 2,
           loadedSourceFileNameTemplates["hitomi"] == nil {
            let legacyTemplate = loadedFileNameTemplate.trimmed
            loadedSourceFileNameTemplates["hitomi"] = legacyTemplate.isEmpty
                ? NameTemplate.originalFileDefault(for: "hitomi") ?? ""
                : legacyTemplate
        }
        for sourceID in NameTemplate.originalSourceFileTemplateIDs
            where loadedSourceFileNameTemplates[sourceID] == nil {
            loadedSourceFileNameTemplates[sourceID] =
                NameTemplate.originalFileDefault(for: sourceID) ?? ""
        }
        defaults.set(2, forKey: "sourceFileNameTemplateVersion")
#endif
        sourceFileNameTemplates = loadedSourceFileNameTemplates
#if !TESTING
        defaults.set(loadedSourceFileNameTemplates, forKey: "sourceFileNameTemplates")
        for sourceID in NameTemplate.originalSourceFileTemplateIDs {
            guard let preferenceKey = NameTemplate.originalFilePreferenceKey(for: sourceID),
                  let template = loadedSourceFileNameTemplates[sourceID] else {
                continue
            }
            defaults.set(template, forKey: preferenceKey)
        }
        if let hitomiTemplate = loadedSourceFileNameTemplates["hitomi"],
           let typeNumber = NameTemplate.originalHitomiFilenameTypeNumber(for: hitomiTemplate) {
            defaults.set(typeNumber, forKey: "hitomiFilenameTypeNumber")
        }
#endif
        let loadedArchiveCompletedFolders = defaults.object(forKey: "archiveCompletedFolders") as? Bool ?? false
        let loadedArchiveFileFormat = ArchiveFileFormat(
            rawValue: defaults.string(forKey: "archiveFileFormat") ?? ""
        ) ?? .zip
        let loadedDeleteOriginalFolderAfterArchiving =
            defaults.object(forKey: "deleteOriginalFolderAfterArchiving") as? Bool ?? false
        let loadedHideArchiveIndicatorWhenFileMissing =
            defaults.object(forKey: "hideArchiveIndicatorWhenFileMissing") as? Bool ?? true
        archiveCompletedFolders = loadedArchiveCompletedFolders
        archiveFileFormat = loadedArchiveFileFormat
        deleteOriginalFolderAfterArchiving = loadedDeleteOriginalFolderAfterArchiving
        hideArchiveIndicatorWhenFileMissing = loadedHideArchiveIndicatorWhenFileMissing
        let loadedSourceArchiveSettings = Self.loadSourceArchiveSettings(
            defaults: defaults,
            legacyArchiveEnabled: loadedArchiveCompletedFolders,
            legacyFormat: loadedArchiveFileFormat,
            legacyDeleteOriginal: loadedDeleteOriginalFolderAfterArchiving
        )
        sourceArchiveModes = loadedSourceArchiveSettings.modes
        sourceArchiveDeleteOriginal = loadedSourceArchiveSettings.deleteOriginal
        if loadedSourceArchiveSettings.didMigrate {
            Self.persistSourceArchiveSettings(
                modes: loadedSourceArchiveSettings.modes,
                deleteOriginal: loadedSourceArchiveSettings.deleteOriginal,
                defaults: defaults
            )
        }
        autoRemoveFinishedJobs = defaults.object(forKey: "autoRemoveFinishedJobs") as? Bool ?? false
        let savedAutoRemoveHookCommand = defaults.string(forKey: "autoRemoveHookCommand") ?? ""
        autoRemoveHookCommand = savedAutoRemoveHookCommand
        autoRemoveHookStatus = savedAutoRemoveHookCommand.trimmed.isEmpty ? "자동 제거 후크 꺼짐" : "자동 제거 후크 준비됨"
        showDownloadDate = defaults.object(forKey: "showDownloadDate") as? Bool ?? false
        numberPlaylistFiles = defaults.object(forKey: "numberPlaylistFiles") as? Bool ?? false
        retryIncompleteAutomatically =
            defaults.object(forKey: "retryIncompleteAutomatically") as? Bool
            ?? defaults.object(forKey: "incomplete") as? Bool
            ?? false
        if let savedMinutes = defaults.object(forKey: "incompleteRetryDelayMinutes") as? Int {
            incompleteRetryDelay = IncompleteRetryDelay.normalized(minutes: savedMinutes)
        } else {
            incompleteRetryDelay = IncompleteRetryDelay.normalized(
                originalIndex: defaults.object(forKey: "incompleteTime") as? Int ?? 0
            )
        }
        let savedJobConcurrency = defaults.integer(forKey: "jobConcurrency")
        jobConcurrency = Self.normalizedJobConcurrency(
            savedJobConcurrency > 0 ? savedJobConcurrency : Self.defaultJobConcurrency
        )
        let savedConcurrency = defaults.integer(forKey: "concurrency")
        concurrency = savedConcurrency > 0 ? max(1, savedConcurrency) : 4
        preferWebP = defaults.object(forKey: "preferWebP") as? Bool ?? true
        eHentaiSourceMode = EHentaiSourceMode(
            rawValue: defaults.string(forKey: "eHentaiSourceMode") ?? ""
        ) ?? .automatic
        preferOriginalEHentaiImages = defaults.object(forKey: "preferOriginalEHentaiImages") as? Bool ?? false
        preferJapaneseEHentaiTitle =
            defaults.object(forKey: "preferJapaneseEHentaiTitle") as? Bool
            ?? defaults.object(forKey: "ehenJapanese") as? Bool
            ?? false
        imageConversionFormat = ImageConversionFormat(rawValue: defaults.string(forKey: "imageConversionFormat") ?? "") ?? .original
        saveHitomiGalleryInfoText = defaults.object(forKey: "saveHitomiGalleryInfoText") as? Bool ?? false
        skipDuplicates = defaults.object(forKey: "skipDuplicates") as? Bool ?? true
        lowPowerMode = defaults.object(forKey: "lowPowerMode") as? Bool ?? false
        showDuplicateImageThumbnails = defaults.object(forKey: "showDuplicateImageThumbnails") as? Bool ?? true
        duplicateImageSimilarityPercent = Self.normalizedDuplicateImageSimilarityPercent(
            defaults.object(forKey: "duplicateImageSimilarityPercent") as? Int ?? 100
        )
        duplicateImageExcludeSameSource = defaults.object(forKey: "duplicateImageExcludeSameSource") as? Bool ?? false
        duplicateImageFolderPaths = Self.normalizedDuplicateImageFolderPaths(
            defaults.stringArray(forKey: "duplicateImageFolderPaths") ?? []
        )
        appAppearanceMode = AppAppearanceMode(rawValue: defaults.string(forKey: "appAppearanceMode") ?? "") ?? .system
        selectedPythonThemeKey = defaults.string(forKey: "selectedPythonThemeKey")?.trimmed.lowercased() ?? ""
        uiScale = AppUIScale.normalized(rawValue: defaults.string(forKey: "uiScale"))
        queueViewMode = QueueViewMode(rawValue: defaults.string(forKey: "queueViewMode") ?? "") ?? .list
        queueThumbnailsHidden = defaults.object(forKey: "queueThumbnailsHidden") as? Bool ?? false
        queueThumbnailScale = QueueThumbnailScale.normalized(
            index: defaults.object(forKey: "queueThumbnailScaleIndex") as? Int
                ?? QueueThumbnailScale.defaultScale.rawValue
        )
        quickAccessItems = QuickAccessConfiguration.load(defaults: defaults)
        mainWindowOpacity = MainWindowAppearance.normalizedOpacity(
            defaults.object(forKey: "mainWindowOpacity") as? Double ?? MainWindowAppearance.defaultOpacity
        )
        mainWindowAlwaysOnTop = defaults.object(forKey: "mainWindowAlwaysOnTop") as? Bool ?? false
        interfaceFontFamily = Self.normalizedInterfaceFontFamily(defaults.string(forKey: "interfaceFontFamily") ?? "")
        interfaceFontSize = AppInterfaceFontSize.normalized(rawValue: defaults.string(forKey: "interfaceFontSize"))
        showingFloatingMonitor = Self.environmentBool("HITOMI_NATIVE_SHOW_FLOATING_MONITOR")
            ?? (defaults.object(forKey: "showingFloatingMonitor") as? Bool ?? false)
        floatingMonitorOpacity = Self.normalizedFloatingMonitorOpacity(
            defaults.object(forKey: "floatingMonitorOpacity") as? Double ?? 0.92
        )
        let loadedShortcutAssignments = Self.loadAppShortcutAssignments(defaults: defaults)
        appShortcutAssignments = loadedShortcutAssignments
        shortcutEditorDraft = loadedShortcutAssignments[.pasteURLs] ?? AppShortcutCommand.pasteURLs.defaultShortcut
        let loadedStatusColorPalette = Self.loadJobStatusColorPalette(defaults: defaults)
        jobStatusColorPalette = loadedStatusColorPalette
        statusColorDraftPalette = loadedStatusColorPalette
        statusColorOnlyWebColors = defaults.object(forKey: "jobStatusColorOnlyWebColors") as? Bool ?? false
        taskTagNames = Self.loadTaskTagNames(defaults: defaults)
        taskTagRestartTimers = Self.loadTaskTagRestartTimers(defaults: defaults)
        clipboardMonitorEnabled = Self.environmentBool("HITOMI_NATIVE_CLIPBOARD_MONITOR_ENABLED")
            ?? (defaults.object(forKey: "clipboardMonitorEnabled") as? Bool ?? false)
        startDownloadsOnPaste = defaults.object(forKey: "startDownloadsOnPaste") as? Bool ?? true
        launchAtLoginEnabled = LaunchAtLoginSettings.load(defaults: defaults)
        notifyWhenJobCompletes = defaults.object(forKey: "notifyWhenJobCompletes") as? Bool ?? false
        notifyWhenQueueCompletes = defaults.object(forKey: "notifyWhenQueueCompletes") as? Bool ?? false
        playSoundWhenJobCompletes = defaults.object(forKey: "playSoundWhenJobCompletes") as? Bool ?? false
        playSoundOnClipboardAdd = defaults.object(forKey: "playSoundOnClipboardAdd") as? Bool ?? false
        let savedQueueCompletionAction = QueueCompletionAction(rawValue: defaults.string(forKey: "queueCompletionAction") ?? "") ?? .none
        queueCompletionAction = savedQueueCompletionAction
        queueCompletionActionStatus = Self.queueCompletionActionStatusText(for: savedQueueCompletionAction)
        preventSleepWhileDownloading = defaults.object(forKey: "preventSleepWhileDownloading") as? Bool ?? false
        historyEnabled = defaults.object(forKey: "historyEnabled") as? Bool ?? true
        let savedHistoryLimit = defaults.integer(forKey: "historyLimit")
        historyLimitString = String(savedHistoryLimit > 0 ? savedHistoryLimit : 1_000)
        let networkSettings = NetworkSettings.load(defaults: defaults)
        proxyEnabled = networkSettings.proxyEnabled
        proxyURLString = networkSettings.proxyURLString
        proxyBypassList = networkSettings.proxyBypassList
        autoRecordEnabled = Self.environmentBool("HITOMI_NATIVE_AUTO_RECORD_ENABLED")
            ?? (defaults.object(forKey: "autoRecordEnabled") as? Bool ?? false)
        autoRecordPaused = defaults.object(forKey: "autoRecordPaused") as? Bool ?? false
        autoRecordURLsText = defaults.string(forKey: "autoRecordURLsText") ?? ""
        let savedAutoRecordInterval = defaults.object(forKey: "autoRecordIntervalMinutes") as? Int ?? 10
        autoRecordIntervalMinutesString = String(Self.normalizedAutoRecordIntervalMinutes(from: String(savedAutoRecordInterval)))
        autoRecordStatus = autoRecordEnabled
            ? (autoRecordPaused ? "자동 녹화 일시 정지" : "자동 녹화 대기 중")
            : "자동 녹화 꺼짐"
        youtubePreferredLanguage = defaults.string(forKey: "youtubePreferredLanguage") ?? ""
        youtubeDownloadThumbnail = defaults.object(forKey: "youtubeDownloadThumbnail") as? Bool ?? false
        youtubeReversePlaylist = defaults.object(forKey: "youtubeReversePlaylist") as? Bool ?? false
        youtubeUseUploadDateForFileModificationTime =
            defaults.object(forKey: "youtubeUseUploadDateForFileModificationTime") as? Bool ?? true
        youtubeDownloadAutoSubtitles = defaults.object(forKey: "youtubeDownloadAutoSubtitles") as? Bool ?? false
        youtubeSubtitleLanguages = defaults.string(forKey: "youtubeSubtitleLanguages") ?? ""
        youtubeEmbedChapters = defaults.object(forKey: "youtubeEmbedChapters") as? Bool ?? false
        let storedCodecPriority = defaults.object(forKey: "youtubeVideoCodecPriority") ??
            defaults.object(forKey: "CODECS_PRI")
        youtubeVideoCodecPriority = YouTubeVideoCodec.priority(
            fromStoredValue: storedCodecPriority,
            legacySort: defaults.string(forKey: "youtubeVideoCodecSort") ?? ""
        )
        youtubeVideoCodecSort = YouTubeVideoCodec.ytdlpSortExpression(for: youtubeVideoCodecPriority)
        youtubePreferEnhancedBitrate = defaults.object(forKey: "youtubePreferEnhancedBitrate") as? Bool ?? false
        youtubePreferredResolution = defaults.string(forKey: "youtubePreferredResolution") ?? ""
        youtubePreferredAudioLanguage = defaults.string(forKey: "youtubePreferredAudioLanguage") ?? ""
        instagramIncludeStories = defaults.object(forKey: "instagramIncludeStories") as? Bool ?? false
        soopPreferredResolution = defaults.string(forKey: "soopPreferredResolution") ?? ""
        pixivUgoiraFileFormat = PixivUgoiraFileFormat(rawValue: defaults.string(forKey: "pixivUgoiraFileFormat") ?? "") ?? .ugoira
        pixivUgoiraDither = defaults.object(forKey: "pixivUgoiraDither") as? Bool ?? true
        pixivUgoiraQuality = min(max(1, defaults.object(forKey: "pixivUgoiraQuality") as? Int ?? 90), 100)
        remuxM3U8ToMP4 = defaults.object(forKey: "remuxM3U8ToMP4") as? Bool ?? false
        hlsContinueOnSegmentFailure = defaults.object(forKey: "hlsContinueOnSegmentFailure") as? Bool ?? false
        let savedM3U8Delay = defaults.object(forKey: "m3u8SegmentDelayMilliseconds") as? Int ?? 0
        m3u8SegmentDelayMillisecondsString = savedM3U8Delay > 0 ? String(Self.normalizedM3U8SegmentDelayMilliseconds(from: String(savedM3U8Delay))) : ""
        ytdlpPath = ExternalToolSettings.path(for: .ytdlp, defaults: defaults)
        ffmpegPath = ExternalToolSettings.path(for: .ffmpeg, defaults: defaults)
        pythonPath = defaults.string(forKey: "pythonScriptPythonPath") ?? ""
        ffmpegTranscodeEnabled = defaults.object(forKey: "ffmpegTranscodeEnabled") as? Bool ?? false
        ffmpegVideoCodec = defaults.string(forKey: "ffmpegVideoCodec") ?? FFmpegTranscodeOptions.defaults.videoCodec
        ffmpegAudioCodec = defaults.string(forKey: "ffmpegAudioCodec") ?? FFmpegTranscodeOptions.defaults.audioCodec
        ffmpegVideoBitrate = defaults.string(forKey: "ffmpegVideoBitrate") ?? FFmpegTranscodeOptions.defaults.videoBitrate
        ffmpegAudioBitrate = defaults.string(forKey: "ffmpegAudioBitrate") ?? FFmpegTranscodeOptions.defaults.audioBitrate
        ffmpegCRF = defaults.string(forKey: "ffmpegCRF") ?? FFmpegTranscodeOptions.defaults.crf
        ffmpegPreset = defaults.string(forKey: "ffmpegPreset") ?? FFmpegTranscodeOptions.defaults.preset
