        aria2SeedRatio = defaults.string(forKey: "aria2SeedRatio") ?? ""
        aria2MaxDownloadLimit = defaults.string(forKey: "aria2MaxDownloadLimit") ?? ""
        aria2MaxUploadLimit = defaults.string(forKey: "aria2MaxUploadLimit") ?? ""
        aria2Trackers = defaults.string(forKey: "aria2Trackers") ?? ""
        aria2AnonymousMode = defaults.object(forKey: "aria2AnonymousMode") as? Bool ?? false
        httpAPIEnabled = Self.environmentBool("HITOMI_NATIVE_HTTP_API_ENABLED")
            ?? (defaults.object(forKey: "httpAPIEnabled") as? Bool ?? false)
        httpAPIPortString = Self.environmentPort("HITOMI_NATIVE_HTTP_API_PORT")
            ?? defaults.string(forKey: "httpAPIPortString")
            ?? "8110"
        httpAPIPassword = defaults.string(forKey: "httpAPIPassword") ?? ""
        httpViewerLazyLoading = defaults.object(forKey: "httpViewerLazyLoading") as? Bool ?? true
        queueSortMode = QueueSortMode(rawValue: defaults.string(forKey: "queueSortMode") ?? "") ?? .manual
        queueSortDescending = defaults.object(forKey: "queueSortDescending") as? Bool ?? false
        searchResultSortMode = SearchResultSortMode(rawValue: defaults.string(forKey: "searchResultSortMode") ?? "") ?? .manual
        searchResultSortDescending = defaults.object(forKey: "searchResultSortDescending") as? Bool ?? false
        initialDownloadTrafficSample = Self.networkDownloadTrafficSample(at: appStartedAt)
        _ = loadSiteRulePluginManifests()
        preparePythonScriptDirectories()
        pythonScriptPlugins = PythonScriptPluginStore.load()
        refreshPythonScriptStatus()
        Task { [weak self] in
            await self?.runEnabledPythonToolPlugins()
        }
        if migratedQueueOrder || migratedQueueGroups {
            persistUserData()
        }
        if clipboardMonitorEnabled {
