    private nonisolated static func environmentPort(_ key: String) -> String? {
        guard let raw = ProcessInfo.processInfo.environment[key]?.trimmed,
              let port = UInt16(raw),
              port > 0 else {
            return nil
        }
        return String(port)
    }

    deinit {
        queueTask?.cancel()
        runningJobTasks.values.forEach { $0.cancel() }
        aria2RuntimeProcesses.values.forEach { $0.terminate() }
        ffmpegRuntimeProcesses.values.forEach { $0.terminate() }
        ytdlpRuntimeProcesses.values.forEach { $0.terminate() }
        completedOutputMetadataBackfillTask?.cancel()
        autoRecordTask?.cancel()
        externalToolInstallTask?.cancel()
        outputPreviewLoadTask?.cancel()
        searchTask?.cancel()
        restartTasks.values.forEach { $0.cancel() }
        sleepPreventionAssertion.release()
        httpAPIServer?.stop()
        browserExtensionServer?.stop()
        clipboardTimer?.invalidate()
    }

    func prepareForTermination() {
        guard !isPreparingForTermination else { return }
        isPreparingForTermination = true
        isQueueEnabled = false
        isRunning = false

        queueTask?.cancel()
        cancelAllRunningJobTasks()
        resumeAllPixivLoginWaits()
        resumeAllChzzkLoginWaits()
        resumeAllNaverCafeLoginWaits()
        resumeAllTwitterLoginWaits()
        resumeAllPornhubLoginWaits()
        resumeAllArcaliveLoginWaits()
        queueTask = nil
        completedOutputMetadataBackfillTask?.cancel()
        completedOutputMetadataBackfillTask = nil
        autoRecordTask?.cancel()
        autoRecordTask = nil
        externalToolInstallTask?.cancel()
        externalToolInstallTask = nil
        outputPreviewLoadTask?.cancel()
        outputPreviewLoadTask = nil
        searchTask?.cancel()
        searchTask = nil
        activeSearchRequestID = nil
        isSearching = false
        cancelAllScheduledRestarts()

        let runtimeProcesses = Array(aria2RuntimeProcesses.values)
        let ffmpegProcesses = Array(ffmpegRuntimeProcesses.values)
        let ytdlpProcesses = Array(ytdlpRuntimeProcesses.values)
        aria2RuntimeProcesses.removeAll()
        ffmpegRuntimeProcesses.removeAll()
        ytdlpRuntimeProcesses.removeAll()
        aria2RuntimeRPCSessions.removeAll()
        aria2RuntimePausedJobIDs.removeAll()
        runtimeProcesses.forEach { $0.terminate() }
        ffmpegProcesses.forEach { $0.terminate() }
        ytdlpProcesses.forEach { $0.terminate() }

        releaseSleepPreventionAssertion()
        stopHTTPAPIServer()
        stopBrowserExtensionServer()
        stopClipboardMonitor()
        normalizeActiveQueueOrder()
        persistSourceFileNameTemplates()
        QuickAccessConfiguration.save(quickAccessItems)
        UserDefaults.standard.set(mainWindowAlwaysOnTop, forKey: "mainWindowAlwaysOnTop")
        persistUserData()
    }

