    func activityLogText(entries: [ActivityLogEntry]? = nil) -> String {
        Self.activityLogText(entries ?? activityLog)
    }

    func outputDirectoryEntries(fileManager: FileManager = .default) -> [OutputDirectoryEntry] {
        var directories: [String: OutputDirectoryAccumulator] = [:]

        for job in jobs {
            addOutputDirectory(
                path: job.outputPath,
                title: job.title,
                scope: "queue",
                directories: &directories,
                fileManager: fileManager
            )
        }

        for entry in history {
            addOutputDirectory(
                path: entry.outputPath,
                title: entry.title,
                scope: "history",
                directories: &directories,
                fileManager: fileManager
            )
        }

        return directories.values
            .map { accumulator in
                OutputDirectoryEntry(
                    path: accumulator.path,
                    scope: Self.outputDirectoryScope(queueCount: accumulator.queueCount, historyCount: accumulator.historyCount),
                    queueCount: accumulator.queueCount,
                    historyCount: accumulator.historyCount,
                    sampleTitle: accumulator.sampleTitle,
                    exists: accumulator.exists,
                    isDirectory: accumulator.isDirectory
                )
            }
            .sorted { $0.path.localizedStandardCompare($1.path) == .orderedAscending }
    }

    func outputDirectoriesText(entries: [OutputDirectoryEntry]? = nil) -> String {
        let entries = entries ?? outputDirectoryEntries()
        guard !entries.isEmpty else { return "No directories" }

        let lines = entries.map { entry -> String in
            let counts = Self.outputDirectoryCountText(queueCount: entry.queueCount, historyCount: entry.historyCount)
            let state = entry.exists ? (entry.isDirectory ? "exists" : "file parent") : "missing"
            let suffix = entry.sampleTitle.trimmed.isEmpty ? "" : " - \(entry.sampleTitle)"
            return "[\(entry.scope)] \(entry.path)\n  \(counts), \(state)\(suffix)"
        }
        return "Dirs (\(entries.count))\n\n" + lines.joined(separator: "\n")
    }

    func metadataFinderResults(
        field: MetadataFinderField? = nil,
        query: String? = nil,
        mode: MetadataFinderMode? = nil,
        limit: Int = 500
    ) -> [MetadataFinderResult] {
        let field = field ?? metadataFinderField
        let query = query ?? metadataFinderQuery
        let mode = mode ?? metadataFinderMode
        let normalizedQuery = query.trimmed
        let regex = Self.metadataFinderRegex(query: normalizedQuery, mode: mode)
        var values: [String: MetadataFinderAccumulator] = [:]

        for job in jobs {
            addMetadataFinderValues(
                metadata: job.metadata,
                title: job.title,
                source: job.source,
                scope: "queue",
                field: field,
                query: normalizedQuery,
                mode: mode,
                regex: regex,
                values: &values
            )
        }

        for entry in history {
            addMetadataFinderValues(
                metadata: entry.metadata,
                title: entry.title,
                source: entry.source,
                scope: "history",
                field: field,
                query: normalizedQuery,
                mode: mode,
                regex: regex,
                values: &values
            )
        }

        return values.values
            .map {
                MetadataFinderResult(
                    field: field,
                    value: $0.value,
                    queueCount: $0.queueCount,
                    historyCount: $0.historyCount,
                    sampleTitle: $0.sampleTitle,
                    sampleSource: $0.sampleSource,
                    score: $0.score
                )
            }
            .sorted { left, right in
                if (left.score ?? -1) != (right.score ?? -1) {
                    return (left.score ?? -1) > (right.score ?? -1)
                }
                if left.totalCount != right.totalCount {
                    return left.totalCount > right.totalCount
                }
                return left.value.localizedStandardCompare(right.value) == .orderedAscending
            }
            .prefix(max(1, limit))
            .map { $0 }
    }

    func metadataAnalysisEntries(
        field: MetadataAnalysisField? = nil,
        limit: Int = 500
    ) -> [MetadataAnalysisEntry] {
        let field = field ?? metadataAnalysisField
        var values: [String: MetadataFinderAccumulator] = [:]

        for job in jobs {
            addMetadataAnalysisValues(
                metadata: job.metadata,
                title: job.title,
                source: job.source,
                scope: "queue",
                field: field,
                values: &values
            )
        }

        for entry in history {
            addMetadataAnalysisValues(
                metadata: entry.metadata,
                title: entry.title,
                source: entry.source,
                scope: "history",
                field: field,
                values: &values
            )
        }

        return values.values
            .map {
                MetadataAnalysisEntry(
                    field: field,
                    value: $0.value,
                    queueCount: $0.queueCount,
                    historyCount: $0.historyCount,
                    sampleTitle: $0.sampleTitle,
                    sampleSource: $0.sampleSource
                )
            }
            .sorted { left, right in
                if left.totalCount != right.totalCount {
                    return left.totalCount > right.totalCount
                }
                if left.queueCount != right.queueCount {
                    return left.queueCount > right.queueCount
                }
                return left.value.localizedStandardCompare(right.value) == .orderedAscending
            }
            .prefix(max(1, limit))
            .map { $0 }
    }

