    private func recordActivity(_ message: String, category: String) {
        let cleaned = message.trimmed
        guard !cleaned.isEmpty else { return }

        activityLog.append(ActivityLogEntry(category: category, message: cleaned))
        if activityLog.count > Self.activityLogLimit {
            activityLog.removeFirst(activityLog.count - Self.activityLogLimit)
        }
    }

    private func addOutputDirectory(
        path: String,
        title: String,
        scope: String,
        directories: inout [String: OutputDirectoryAccumulator],
        fileManager: FileManager
    ) {
        guard let directoryPath = Self.outputDirectoryPath(forOutputPath: path, fileManager: fileManager) else { return }
        let standardizedPath = URL(fileURLWithPath: directoryPath, isDirectory: true).standardizedFileURL.path
        var isDirectoryObject = ObjCBool(false)
        let exists = fileManager.fileExists(atPath: standardizedPath, isDirectory: &isDirectoryObject)
        var accumulator = directories[standardizedPath] ?? OutputDirectoryAccumulator(path: standardizedPath)
        if scope == "queue" {
            accumulator.queueCount += 1
        } else {
            accumulator.historyCount += 1
        }
        if accumulator.sampleTitle.trimmed.isEmpty {
            accumulator.sampleTitle = title
        }
        accumulator.exists = accumulator.exists || exists
        accumulator.isDirectory = accumulator.isDirectory || (exists && isDirectoryObject.boolValue)
        directories[standardizedPath] = accumulator
    }

    private func addMetadataFinderValues(
        metadata: [String: String],
        title: String,
        source: String,
        scope: String,
        field: MetadataFinderField,
        query: String,
        mode: MetadataFinderMode,
        regex: NSRegularExpression?,
        values: inout [String: MetadataFinderAccumulator]
    ) {
        for value in Self.metadataFinderValues(field: field, metadata: metadata) {
            guard let score = Self.metadataFinderScore(value: value, query: query, mode: mode, regex: regex) else {
                continue
            }
            let key = value.lowercased()
            var accumulator = values[key] ?? MetadataFinderAccumulator(value: value)
            if scope == "queue" {
                accumulator.queueCount += 1
            } else {
                accumulator.historyCount += 1
            }
            if accumulator.sampleTitle.trimmed.isEmpty {
                accumulator.sampleTitle = title
            }
            if accumulator.sampleSource.trimmed.isEmpty {
                accumulator.sampleSource = source
            }
            accumulator.score = max(accumulator.score ?? score, score)
            values[key] = accumulator
        }
    }

    private func addMetadataAnalysisValues(
        metadata: [String: String],
        title: String,
        source: String,
        scope: String,
        field: MetadataAnalysisField,
        values: inout [String: MetadataFinderAccumulator]
    ) {
        for value in Self.metadataAnalysisValues(field: field, metadata: metadata) {
            let key = value.lowercased()
            var accumulator = values[key] ?? MetadataFinderAccumulator(value: value)
            if scope == "queue" {
                accumulator.queueCount += 1
            } else {
                accumulator.historyCount += 1
            }
            if accumulator.sampleTitle.trimmed.isEmpty {
                accumulator.sampleTitle = title
            }
            if accumulator.sampleSource.trimmed.isEmpty {
                accumulator.sampleSource = source
            }
            values[key] = accumulator
        }
    }

