    nonisolated static func outputDirectoryPath(forOutputPath outputPath: String, fileManager: FileManager = .default) -> String? {
        let cleaned = (outputPath as NSString).expandingTildeInPath.trimmed
        guard !cleaned.isEmpty else { return nil }

        let url = URL(fileURLWithPath: cleaned)
        var isDirectory = ObjCBool(false)
        if fileManager.fileExists(atPath: url.path, isDirectory: &isDirectory) {
            return isDirectory.boolValue ? url.path : url.deletingLastPathComponent().path
        }

        if !url.pathExtension.trimmed.isEmpty {
            return url.deletingLastPathComponent().path
        }
        return url.path
    }

    private nonisolated static func outputDirectoryScope(queueCount: Int, historyCount: Int) -> String {
        switch (queueCount > 0, historyCount > 0) {
        case (true, true):
            return "Queue + History"
        case (true, false):
            return "Queue"
        case (false, true):
            return "History"
        default:
            return "Unknown"
        }
    }

    private nonisolated static func outputDirectoryCountText(queueCount: Int, historyCount: Int) -> String {
        let pieces = [
            queueCount > 0 ? "\(queueCount) queue" : nil,
            historyCount > 0 ? "\(historyCount) history" : nil
        ].compactMap { $0 }
        return pieces.isEmpty ? "0 items" : pieces.joined(separator: ", ")
    }

    nonisolated static func metadataFinderKeys(for field: MetadataFinderField) -> [String] {
        switch field {
        case .artist:
            return ["artist", "artists", "author", "creator", "uploader", "channel", "username", "user"]
        case .group:
            return ["group", "groups", "circle", "circles", "team", "studio"]
        case .series:
            return ["series", "parody", "album", "collection", "playlist", "show", "work", "comic"]
        case .character:
            return ["character", "characters", "char", "chars"]
        case .tag:
            return ["tag", "tags", "genre", "genres", "category", "language", "site"]
        }
    }

    nonisolated static func metadataFinderValues(field: MetadataFinderField, metadata: [String: String]) -> [String] {
        var seen = Set<String>()
        var values: [String] = []
        for key in metadataFinderKeys(for: field) {
            guard let rawValue = metadata[key], !rawValue.trimmed.isEmpty else { continue }
            for value in metadataFinderSplit(rawValue) {
                let normalized = value.lowercased()
                guard seen.insert(normalized).inserted else { continue }
                values.append(value)
            }
        }
        return values
    }

    nonisolated static func metadataAnalysisKeys(for field: MetadataAnalysisField) -> [String] {
        switch field {
        case .artist:
            return metadataFinderKeys(for: .artist)
        case .group:
            return metadataFinderKeys(for: .group)
        case .type:
            return ["type", "types", "kind", "class", "media_type", "mediaType", "content_type", "contentType"]
        case .series:
            return metadataFinderKeys(for: .series)
        case .character:
            return metadataFinderKeys(for: .character)
        case .tag:
            return ["tag", "tags", "genre", "genres", "category", "categories"]
        case .language:
            return ["language", "languages", "lang", "langs", "locale"]
        }
    }

    nonisolated static func metadataAnalysisValues(field: MetadataAnalysisField, metadata: [String: String]) -> [String] {
        var seen = Set<String>()
        var values: [String] = []
        for key in metadataAnalysisKeys(for: field) {
            guard let rawValue = metadata[key], !rawValue.trimmed.isEmpty else { continue }
            for value in metadataFinderSplit(rawValue) {
                let normalized = value.lowercased()
                guard seen.insert(normalized).inserted else { continue }
                values.append(value)
            }
        }
        return values
    }

    private nonisolated static func metadataFinderSplit(_ value: String) -> [String] {
        value
            .components(separatedBy: CharacterSet(charactersIn: ",;|\n\t"))
            .map {
                $0.trimmingCharacters(in: CharacterSet(charactersIn: " #[](){}\"'"))
                    .trimmed
            }
            .filter { !$0.isEmpty }
    }

    private nonisolated static func metadataFinderRegex(query: String, mode: MetadataFinderMode) -> NSRegularExpression? {
        guard mode == .regex, !query.trimmed.isEmpty else { return nil }
        return try? NSRegularExpression(pattern: query, options: [.caseInsensitive])
    }

    private nonisolated static func metadataFinderScore(
        value: String,
        query: String,
        mode: MetadataFinderMode,
        regex: NSRegularExpression?
    ) -> Int? {
        let query = query.trimmed
        guard !query.isEmpty else { return 0 }
        let valueLower = value.lowercased()
        let queryLower = query.lowercased()

        switch mode {
        case .plain:
            return valueLower.contains(queryLower) ? 100 : nil
        case .regex:
            guard let regex else { return nil }
            let range = NSRange(value.startIndex..<value.endIndex, in: value)
            return regex.firstMatch(in: value, range: range) == nil ? nil : 100
        case .fuzzy:
            if valueLower.contains(queryLower) {
                return 100
            }
            let tokens = valueLower.split { !$0.isLetter && !$0.isNumber }.map(String.init)
            if tokens.contains(where: { $0.hasPrefix(queryLower) || $0.contains(queryLower) }) {
                return 90
            }
            guard isFuzzySubsequence(queryLower, in: valueLower) else { return nil }
            let compactValueCount = max(1, valueLower.filter { !$0.isWhitespace }.count)
            return max(55, min(85, Int((Double(queryLower.count) / Double(compactValueCount)) * 100.0)))
        }
    }

    private nonisolated static func isFuzzySubsequence(_ query: String, in value: String) -> Bool {
        var current = value.startIndex
        for character in query where !character.isWhitespace {
            guard let match = value[current...].firstIndex(of: character) else {
                return false
            }
            current = value.index(after: match)
        }
        return true
    }

    nonisolated static func metadataFinderSearchToken(_ result: MetadataFinderResult) -> String {
        let value = result.value
        let escaped = value.replacingOccurrences(of: "\"", with: "\\\"")
        if value.contains(where: { $0.isWhitespace }) {
            return "\(result.field.rawValue):\"\(escaped)\""
        }
        return "\(result.field.rawValue):\(value)"
    }

    nonisolated static func metadataAnalysisSearchToken(_ entry: MetadataAnalysisEntry) -> String {
        let value = entry.value
        let escaped = value.replacingOccurrences(of: "\"", with: "\\\"")
        if value.contains(where: { $0.isWhitespace }) {
            return "\(entry.field.rawValue):\"\(escaped)\""
        }
        return "\(entry.field.rawValue):\(value)"
    }

    private var queueOrderedJobIndices: [Int] {
        guard let activeQueueOrderIDs else {
            return Array(jobs.indices)
        }

        var indexByID: [UUID: Int] = [:]
        indexByID.reserveCapacity(jobs.count)
        for index in jobs.indices {
            indexByID[jobs[index].id] = index
        }

        var seen = Set<UUID>()
        var ordered: [Int] = []
        ordered.reserveCapacity(jobs.count)
        for id in activeQueueOrderIDs where seen.insert(id).inserted {
            if let index = indexByID[id] {
                ordered.append(index)
            }
        }
        for index in jobs.indices where seen.insert(jobs[index].id).inserted {
            ordered.append(index)
        }
        return ordered
    }

    private var queueOrderedJobs: [DownloadJob] {
        queueOrderedJobIndices.map { jobs[$0] }
    }

    private var visibleQueueOrderedJobIndices: [Int] {
        queueOrderedJobIndices.filter { !Self.isPendingQueueRemoval(jobs[$0]) }
    }

    private var visibleQueueOrderedJobs: [DownloadJob] {
        visibleQueueOrderedJobIndices.map { jobs[$0] }
    }

    func queueOrderIndex(for job: DownloadJob) -> Int? {
        queueOrderedJobIndices.firstIndex { jobs[$0].id == job.id }
    }

    var filteredJobs: [DownloadJob] {
        let orderedJobs = visibleQueueOrderedJobs
        let filtered: [DownloadJob]
        if let expression = Self.queueFilterExpression(from: queueFilter) {
            let context = Self.queueFilterContext(for: orderedJobs)
            filtered = orderedJobs.filter { Self.queueFilterExpression(expression, matches: $0, context: context) }
        } else {
            filtered = orderedJobs
        }
        return Self.sortedQueueJobs(filtered, mode: queueSortMode, descending: queueSortDescending)
    }

    var queueListEntries: [QueueListEntry] {
        let orderedJobs = visibleQueueOrderedJobs
        let filteredForGroups: [DownloadJob]
        if let expression = Self.queueFilterExpression(from: queueFilter) {
            let context = Self.queueFilterContext(for: orderedJobs)
            filteredForGroups = orderedJobs.filter {
                Self.queueFilterExpression(expression, matches: $0, context: context)
            }
        } else {
            filteredForGroups = orderedJobs
        }
        let visibleJobs = Self.sortedQueueJobs(
            filteredForGroups,
            mode: queueSortMode,
            descending: queueSortDescending,
            prioritizingPins: false
        )
        let allDisplayJobs = Self.sortedQueueJobs(
            orderedJobs,
            mode: queueSortMode,
            descending: queueSortDescending,
            prioritizingPins: false
        )
        let filterText = queueFilter.trimmed.lowercased()
        let filterActive = !filterText.isEmpty
        let groupsByID = Dictionary(uniqueKeysWithValues: queueGroups.map { ($0.id, $0) })

        var membersByGroupID: [UUID: [DownloadJob]] = [:]
        var visibleGroupIDs = Set<UUID>()
        for group in queueGroups {
            let groupMatchesFilter = filterActive &&
                "\(group.name) \(group.comment)".lowercased().contains(filterText)
            let sourceJobs = groupMatchesFilter ? allDisplayJobs : visibleJobs
            let members = sourceJobs.filter { Self.queueGroupID(in: $0) == group.id }
            membersByGroupID[group.id] = members
            if !members.isEmpty || groupMatchesFilter || !filterActive {
                visibleGroupIDs.insert(group.id)
            }
        }

        var units: [(isPinned: Bool, entries: [QueueListEntry])] = []
        var emittedGroupIDs = Set<UUID>()
        var emittedJobIDs = Set<UUID>()

        func emit(_ group: QueueGroup) {
            guard visibleGroupIDs.contains(group.id), emittedGroupIDs.insert(group.id).inserted else {
                return
            }
            let members = membersByGroupID[group.id] ?? []
            emittedJobIDs.formUnion(members.map(\.id))
            var groupEntries: [QueueListEntry] = [.group(group)]
            if group.isExpanded {
                let orderedMembers = members.filter(\.isPinned) + members.filter { !$0.isPinned }
                groupEntries.append(contentsOf: orderedMembers.map(QueueListEntry.job))
            }
            units.append((isPinned: group.isPinned, entries: groupEntries))
        }

        for job in visibleJobs {
            for group in queueGroups where group.anchorJobID == job.id {
                emit(group)
            }
            if emittedJobIDs.contains(job.id) {
                continue
            }
            if let groupID = Self.queueGroupID(in: job),
               let group = groupsByID[groupID] {
                emit(group)
                continue
            }
            emittedJobIDs.insert(job.id)
            units.append((isPinned: job.isPinned, entries: [.job(job)]))
        }

        for group in queueGroups {
            emit(group)
        }
        let orderedUnits = units.filter(\.isPinned) + units.filter { !$0.isPinned }
        return orderedUnits.flatMap(\.entries)
    }

    private nonisolated static func queueGroupID(in job: DownloadJob) -> UUID? {
        job.metadata[queueGroupIDMetadataKey]
            .flatMap { UUID(uuidString: $0.trimmed) }
    }

    var queueStatusGroupSummaryText: String {
        Self.queueStatusGroupSummaryText(
            jobs: jobs,
