    nonisolated static func queueStatusGroupSummaryText(
        jobs: [DownloadJob],
        filteredJobs: [DownloadJob],
        filterActive: Bool
    ) -> String {
        let totalCounts = Dictionary(grouping: jobs, by: \.status).mapValues(\.count)
        let filteredCounts = Dictionary(grouping: filteredJobs, by: \.status).mapValues(\.count)
        return queueStatusGroupOrder.compactMap { status -> String? in
            let total = totalCounts[status, default: 0]
            guard total > 0 else { return nil }
            if filterActive {
                return "\(status.label) \(filteredCounts[status, default: 0])/\(total)"
            }
            return "\(status.label) \(total)"
        }.joined(separator: " · ")
    }

