    private nonisolated static func sortedQueueJobs(
        _ jobs: [DownloadJob],
        mode: QueueSortMode,
        descending: Bool,
        prioritizingPins: Bool = true
    ) -> [DownloadJob] {
        guard mode != .manual || descending else { return jobs }
        let indexed = jobs.enumerated().map { (index: $0.offset, job: $0.element) }
        return indexed.sorted { lhs, rhs in
            if prioritizingPins, lhs.job.isPinned != rhs.job.isPinned {
                return lhs.job.isPinned && !rhs.job.isPinned
            }

            let comparison = queueSortComparison(lhs.job, rhs.job, mode: mode)
            if comparison == .orderedSame {
                return descending ? lhs.index > rhs.index : lhs.index < rhs.index
            }
            return descending ? comparison == .orderedDescending : comparison == .orderedAscending
        }.map(\.job)
    }

    private nonisolated static func queueSortComparison(_ lhs: DownloadJob, _ rhs: DownloadJob, mode: QueueSortMode) -> ComparisonResult {
        switch mode {
        case .manual:
            return .orderedSame
        case .title:
            return lhs.title.localizedStandardCompare(rhs.title)
        case .status:
            let lhsRank = queueStatusSortRank(lhs.status)
            let rhsRank = queueStatusSortRank(rhs.status)
            if lhsRank != rhsRank {
                return lhsRank < rhsRank ? .orderedAscending : .orderedDescending
            }
            return lhs.status.rawValue.localizedStandardCompare(rhs.status.rawValue)
        case .site:
            let comparison = queueFilterHost(for: lhs).localizedStandardCompare(queueFilterHost(for: rhs))
            return comparison == .orderedSame ? lhs.source.localizedStandardCompare(rhs.source) : comparison
        case .progress:
            if lhs.progress != rhs.progress {
                return lhs.progress < rhs.progress ? .orderedAscending : .orderedDescending
            }
            if lhs.completed != rhs.completed {
                return lhs.completed < rhs.completed ? .orderedAscending : .orderedDescending
            }
            return lhs.title.localizedStandardCompare(rhs.title)
        case .output:
            return lhs.outputPath.localizedStandardCompare(rhs.outputPath)
        }
    }

    private nonisolated static func queueStatusSortRank(_ status: JobStatus) -> Int {
        switch status {
        case .queued: return 0
        case .resolving: return 1
        case .downloading: return 2
        case .failed: return 3
        case .cancelled: return 4
        case .finished: return 5
        }
    }

    private nonisolated static let queueStatusGroupOrder: [JobStatus] = [
        .queued,
        .resolving,
        .downloading,
        .finished,
        .failed,
        .cancelled
    ]

    private nonisolated static func sortedSearchResults(
        _ results: [SearchResultLink],
        mode: SearchResultSortMode,
        descending: Bool,
        knownSources: Set<String>
    ) -> [SearchResultLink] {
        guard mode != .manual || descending else { return results }
        let indexed = results.enumerated().map { (index: $0.offset, result: $0.element) }
        return indexed.sorted { lhs, rhs in
            if let missingComparison = searchResultSortMissingComparison(lhs.result, rhs.result, mode: mode) {
                return missingComparison == .orderedAscending
            }

            let comparison = searchResultSortComparison(lhs.result, rhs.result, mode: mode, knownSources: knownSources)
            if comparison == .orderedSame {
                return descending ? lhs.index > rhs.index : lhs.index < rhs.index
            }
            return descending ? comparison == .orderedDescending : comparison == .orderedAscending
        }.map(\.result)
    }

    private nonisolated static func searchResultSortComparison(
        _ lhs: SearchResultLink,
        _ rhs: SearchResultLink,
        mode: SearchResultSortMode,
        knownSources: Set<String>
    ) -> ComparisonResult {
        switch mode {
        case .manual:
            return .orderedSame
        case .title:
            let comparison = lhs.title.localizedStandardCompare(rhs.title)
            return comparison == .orderedSame ? lhs.url.localizedStandardCompare(rhs.url) : comparison
        case .site:
            let comparison = searchResultFilterHost(for: lhs).localizedStandardCompare(searchResultFilterHost(for: rhs))
            return comparison == .orderedSame ? lhs.url.localizedStandardCompare(rhs.url) : comparison
        case .date:
            let comparison = (searchResultDateText(for: lhs) ?? "").localizedStandardCompare(searchResultDateText(for: rhs) ?? "")
            return comparison == .orderedSame ? lhs.title.localizedStandardCompare(rhs.title) : comparison
        case .pages:
            let lhsCount = searchResultPageCount(for: lhs) ?? 0
            let rhsCount = searchResultPageCount(for: rhs) ?? 0
            if lhsCount != rhsCount {
                return lhsCount < rhsCount ? .orderedAscending : .orderedDescending
            }
            return lhs.title.localizedStandardCompare(rhs.title)
        case .done:
            let lhsKnown = knownSources.contains(searchResultKey(lhs.url))
            let rhsKnown = knownSources.contains(searchResultKey(rhs.url))
            if lhsKnown != rhsKnown {
                return lhsKnown ? .orderedDescending : .orderedAscending
            }
            return lhs.title.localizedStandardCompare(rhs.title)
        }
    }

    private nonisolated static func searchResultSortMissingComparison(
        _ lhs: SearchResultLink,
        _ rhs: SearchResultLink,
        mode: SearchResultSortMode
    ) -> ComparisonResult? {
        switch mode {
        case .date:
            let lhsMissing = searchResultDateText(for: lhs)?.trimmed.isEmpty ?? true
            let rhsMissing = searchResultDateText(for: rhs)?.trimmed.isEmpty ?? true
            if lhsMissing != rhsMissing {
                return lhsMissing ? .orderedDescending : .orderedAscending
            }
        case .pages:
            let lhsMissing = searchResultPageCount(for: lhs) == nil
            let rhsMissing = searchResultPageCount(for: rhs) == nil
            if lhsMissing != rhsMissing {
                return lhsMissing ? .orderedDescending : .orderedAscending
            }
        default:
            break
        }
        return nil
    }

