    nonisolated static func normalizedJobConcurrency(_ value: Int) -> Int {
        max(1, min(12, value))
    }

    nonisolated static let defaultJobConcurrency = 4

    nonisolated static var shouldCleanTransientTestRecordsAtStartup: Bool {
        let environment = ProcessInfo.processInfo.environment
        if environment["HITOMI_NATIVE_ENABLE_TRANSIENT_TEST_CLEANUP"] == "1" {
            return true
        }
        return environment["HITOMI_NATIVE_SUPPORT_DIR"]?.isEmpty != false &&
            environment["HITOMI_NATIVE_USER_DATA"]?.isEmpty != false
    }

    nonisolated static func isTransientTestDestinationPath(_ path: String) -> Bool {
        let standardized = (path.trimmed as NSString).standardizingPath
        guard !standardized.isEmpty else { return false }
        if standardized.hasPrefix("/tmp/HitomiBadayo-") ||
            standardized.hasPrefix("/private/tmp/HitomiBadayo-") ||
            standardized.hasPrefix("/tmp/HitomiNative-") ||
            standardized.hasPrefix("/private/tmp/HitomiNative-") {
            return true
        }
        return ["HitomiBadayo", "HitomiNative"].contains { prefix in
            standardized.range(
                of: "^/(?:private/)?var/folders/.+/T/\(prefix)-[^/]+(?:/|$)",
                options: .regularExpression
            ) != nil
        }
    }

    nonisolated static func isTransientTestRecord(source: String, outputPath: String) -> Bool {
        if isTransientTestDestinationPath(outputPath) {
            return true
        }
        guard let host = URL(string: source.trimmed)?.host?.lowercased() else {
            return false
        }
        return host == "test" || host.hasSuffix(".test")
    }

    nonisolated static func migratedNewestFirstQueue(_ jobs: [DownloadJob]) -> [DownloadJob] {
        let pinned = jobs.filter(\.isPinned)
        let unpinned = jobs.filter { !$0.isPinned }
        return pinned + Array(unpinned.reversed())
    }

    func currentDownloadSpeedBytesPerSecond() -> Int64? {
        guard let sample = Self.networkDownloadTrafficSample() else {
            return nil
        }
        defer {
            previousDownloadTrafficSample = sample
        }
        return Self.networkSpeedBytesPerSecond(previous: previousDownloadTrafficSample, current: sample)
    }

    func downloadedSinceAppStartByteCount() -> Int64? {
        if initialDownloadTrafficSample == nil {
            initialDownloadTrafficSample = Self.networkDownloadTrafficSample(at: appStartedAt)
        }
        guard let initialDownloadTrafficSample,
              let current = Self.networkDownloadTrafficSample(),
              current.byteCount >= initialDownloadTrafficSample.byteCount else {
            return nil
        }
        return Int64(current.byteCount - initialDownloadTrafficSample.byteCount)
    }

    func currentUploadSpeedBytesPerSecond() -> Int64? {
        guard let sample = Self.networkUploadTrafficSample() else {
            return nil
        }
        defer {
            previousUploadTrafficSample = sample
        }
        return Self.networkSpeedBytesPerSecond(previous: previousUploadTrafficSample, current: sample)
    }

    nonisolated static func uploadSpeedBytesPerSecond(previous: NetworkTrafficSample?, current: NetworkTrafficSample) -> Int64? {
        networkSpeedBytesPerSecond(previous: previous, current: current)
    }

    nonisolated static func networkSpeedBytesPerSecond(previous: NetworkTrafficSample?, current: NetworkTrafficSample) -> Int64? {
        guard let previous else { return nil }
        let interval = current.timestamp.timeIntervalSince(previous.timestamp)
        guard interval > 0, current.byteCount >= previous.byteCount else {
            return nil
        }
        let delta = current.byteCount - previous.byteCount
        return Int64((Double(delta) / interval).rounded())
    }

    private nonisolated static func networkDownloadTrafficSample(at timestamp: Date = Date()) -> NetworkTrafficSample? {
        var interfaces: UnsafeMutablePointer<ifaddrs>?
        guard getifaddrs(&interfaces) == 0, let firstInterface = interfaces else {
            return nil
        }
        defer {
            freeifaddrs(interfaces)
        }

        var byteCount: UInt64 = 0
        var current: UnsafeMutablePointer<ifaddrs>? = firstInterface
        while let interface = current {
            defer {
                current = interface.pointee.ifa_next
            }

            let flags = Int32(interface.pointee.ifa_flags)
            guard (flags & IFF_UP) != 0,
                  (flags & IFF_LOOPBACK) == 0,
                  let address = interface.pointee.ifa_addr,
                  Int32(address.pointee.sa_family) == AF_LINK,
                  let data = interface.pointee.ifa_data else {
                continue
            }

            let interfaceData = data.assumingMemoryBound(to: if_data.self).pointee
            byteCount += UInt64(interfaceData.ifi_ibytes)
        }

        return NetworkTrafficSample(timestamp: timestamp, byteCount: byteCount)
    }

    private nonisolated static func networkUploadTrafficSample(at timestamp: Date = Date()) -> NetworkTrafficSample? {
        var interfaces: UnsafeMutablePointer<ifaddrs>?
        guard getifaddrs(&interfaces) == 0, let firstInterface = interfaces else {
            return nil
        }
        defer {
            freeifaddrs(interfaces)
        }

        var byteCount: UInt64 = 0
        var current: UnsafeMutablePointer<ifaddrs>? = firstInterface
        while let interface = current {
            defer {
                current = interface.pointee.ifa_next
            }

            let flags = Int32(interface.pointee.ifa_flags)
            guard (flags & IFF_UP) != 0,
                  (flags & IFF_LOOPBACK) == 0,
                  let address = interface.pointee.ifa_addr,
                  Int32(address.pointee.sa_family) == AF_LINK,
                  let data = interface.pointee.ifa_data else {
                continue
            }

            let interfaceData = data.assumingMemoryBound(to: if_data.self).pointee
            byteCount += UInt64(interfaceData.ifi_obytes)
        }

        return NetworkTrafficSample(timestamp: timestamp, byteCount: byteCount)
    }

    func artistRecommendations(limit: Int = 20) -> [ArtistRecommendation] {
        Self.artistRecommendations(jobs: jobs, history: history, bookmarks: bookmarks, limit: limit)
    }

    func visibleArtistRecommendations(limit: Int = 60) -> [ArtistRecommendation] {
        let query = artistRecommendationFilter.trimmed.lowercased()
        return artistRecommendations(limit: max(limit, 1) + hiddenArtistRecommendationIDs.count)
            .filter { recommendation in
                !hiddenArtistRecommendationIDs.contains(recommendation.id) &&
                    (query.isEmpty || recommendation.searchText.lowercased().contains(query))
            }
            .prefix(max(0, limit))
            .map { $0 }
    }

    func applyArtistRecommendation(_ recommendation: ArtistRecommendation) {
        searchQuery = recommendation.queryToken
        selectHitomiSearchProvider()
        addSummary = "Artist recommendation applied"
    }

    @discardableResult
    func copyArtistRecommendation(_ recommendation: ArtistRecommendation) -> Bool {
        let pasteboard = NSPasteboard.general
        pasteboard.clearContents()
        let copied = pasteboard.setString(recommendation.name, forType: .string)
        addSummary = copied ? "Artist copied" : "Artist copy failed"
        return copied
    }

    func hideArtistRecommendation(_ recommendation: ArtistRecommendation) {
        hiddenArtistRecommendationIDs.insert(recommendation.id)
        addSummary = "Artist recommendation hidden"
    }

    func clearHiddenArtistRecommendations() {
        hiddenArtistRecommendationIDs.removeAll()
        addSummary = "Artist recommendations restored"
    }

