        artistRecommendationFilter = ""
    }

    func openHitomiTaster() {
        hitomiTasterReferenceCount = Self.hitomiTasterReferenceCount(jobs: jobs, history: history, bookmarks: bookmarks)
        if hitomiTasterResults.isEmpty {
            hitomiTasterStatus = hitomiTasterReferenceCount > 0
                ? "\(hitomiTasterReferenceCount) reference works ready"
                : "No reference works"
            hitomiTasterProgress = 0
        }
        showingHitomiTaster = true
    }

    func trainHitomiTaster(limit: Int = 80) {
        hitomiTasterReferenceCount = Self.hitomiTasterReferenceCount(jobs: jobs, history: history, bookmarks: bookmarks)
        let model = hitomiTasterModel
        hitomiTasterTrainingLog = [
            "Model: \(model.originalLabel)",
            "Reading data...",
            "Reference works: \(hitomiTasterReferenceCount)"
        ]
        hitomiTasterProgress = 0.2

        guard hitomiTasterReferenceCount >= model.minimumReferenceCount else {
            hitomiTasterResults = []
            hitomiTasterAccuracy = 0
            hitomiTasterStatus = "Need at least \(model.minimumReferenceCount) reference works"
            hitomiTasterTrainingLog.append("[ERROR] Need at least \(model.minimumReferenceCount) works.")
            addSummary = hitomiTasterStatus
            return
        }

        hitomiTasterTrainingLog.append("Analyzing local metadata...")
        hitomiTasterProgress = 0.4
        let recommendations = artistRecommendations(limit: max(limit * 3, 120))

        hitomiTasterTrainingLog.append("Building model...")
        hitomiTasterProgress = 0.62
        hitomiTasterTrainingLog.append("Training...")
        hitomiTasterProgress = 0.82

        hitomiTasterResults = Self.hitomiTasterResults(
            recommendations: recommendations,
            model: model,
            referenceCount: hitomiTasterReferenceCount,
            limit: limit
        )
        hitomiTasterAccuracy = Self.hitomiTasterAccuracy(results: hitomiTasterResults, referenceCount: hitomiTasterReferenceCount, model: model)
        hitomiTasterProgress = 1
        hitomiTasterStatus = hitomiTasterResults.isEmpty
            ? "No artists classified"
            : "\(hitomiTasterResults.count) artists classified"
        hitomiTasterTrainingLog.append("Classifying artists...")
        hitomiTasterTrainingLog.append("Accuracy \(String(format: "%.2f", hitomiTasterAccuracy))%")
        hitomiTasterTrainingLog.append("Complete")
        addSummary = hitomiTasterStatus
    }

    func visibleHitomiTasterResults(limit: Int = 200) -> [HitomiTasterResult] {
        let query = hitomiTasterFilter.trimmed.lowercased()
        return hitomiTasterResults
            .filter { result in
                !hiddenArtistRecommendationIDs.contains(result.recommendation.id) &&
                    (query.isEmpty || result.searchText.lowercased().contains(query))
            }
            .prefix(max(0, limit))
            .map { $0 }
    }

    func applyHitomiTasterResult(_ result: HitomiTasterResult) {
        applyArtistRecommendation(result.recommendation)
        addSummary = "Hitomi Taster result applied"
    }

    @discardableResult
    func copyHitomiTasterResult(_ result: HitomiTasterResult) -> Bool {
