    private func browserWindowURLSelection() -> (url: URL?, source: String) {
        if let url = Self.firstWebURL(from: inputText) {
            return (url, "input")
        }
        for job in jobs {
            if let url = URL(string: Self.normalizedInputToken(job.source.trimmed)),
               let scheme = url.scheme?.lowercased(),
               scheme == "http" || scheme == "https" {
                return (url, "queue")
            }
        }
        return (URL(string: "https://hitomi.la"), "default")
    }

