    func openOutputPreviewForSelectedJobs() {
        let selectedIDs = selectedJobIDs
        if let selected = jobs.first(where: { selectedIDs.contains($0.id) && canOpenOutputPreview(for: $0) }) {
            openOutputPreview(for: selected)
            return
        }
        if let first = jobs.first(where: canOpenOutputPreview(for:)) {
            openOutputPreview(for: first)
            return
        }
        addSummary = "No previewable output"
    }

    func refreshOutputPreview(keepingSelection: Bool = true) {
        guard let job = outputPreviewJob else {
            outputPreviewLoadTask?.cancel()
            outputPreviewLoadTask = nil
            outputPreviewIsLoading = false
            outputPreviewFiles = []
            outputPreviewSelectedFileIndex = 0
            return
        }

        let previousSelection = outputPreviewSelectedFileIndex
        let jobID = job.id
        let outputPath = job.outputPath
        outputPreviewLoadTask?.cancel()
        outputPreviewIsLoading = true
        if !keepingSelection {
            outputPreviewFiles = []
            outputPreviewSelectedFileIndex = 0
        }

        outputPreviewLoadTask = Task { @MainActor [weak self] in
            let scanTask = Task.detached(priority: .userInitiated) {
                OutputPreviewFileScanner.files(at: outputPath)
            }
            let files = await withTaskCancellationHandler {
                await scanTask.value
            } onCancel: {
                scanTask.cancel()
            }

            guard !Task.isCancelled,
                  let self,
                  self.showingOutputPreview,
                  self.outputPreviewJobID == jobID else {
                return
            }

            self.outputPreviewFiles = files
            if keepingSelection,
               files.contains(where: { $0.originalIndex == previousSelection }) {
                self.outputPreviewSelectedFileIndex = previousSelection
            } else {
                self.outputPreviewSelectedFileIndex = files.first(where: \.isImage)?.originalIndex
                    ?? files.first?.originalIndex
                    ?? 0
            }
            self.outputPreviewIsLoading = false
            self.outputPreviewLoadTask = nil
        }
    }

    func setOutputPreviewMode(_ mode: OutputPreviewMode) {
