    func selectAdjacentOutputPreviewImage(direction: Int) {
        let images = outputPreviewImageFiles
        guard !images.isEmpty else { return }
        let current = outputPreviewSelectedFile.flatMap { selected in
            images.firstIndex(where: { $0.originalIndex == selected.originalIndex })
        } ?? 0
        let next = min(max(current + direction, 0), images.count - 1)
        outputPreviewSelectedFileIndex = images[next].originalIndex
    }

    func canSelectAdjacentOutputPreviewImage(direction: Int) -> Bool {
        let images = outputPreviewImageFiles
        guard !images.isEmpty,
              let selected = outputPreviewSelectedFile,
              let current = images.firstIndex(where: { $0.originalIndex == selected.originalIndex }) else {
            return false
        }
        let next = current + direction
        return images.indices.contains(next)
    }

