    private func textViewerEntries(for job: DownloadJob) -> [TextViewerEntry] {
        let textFiles = apiTextCandidateFiles(for: job)
        var entries = textFiles.map { file in
            TextViewerEntry(
                id: "\(job.id.uuidString):file:\(file.originalIndex)",
                jobID: job.id,
                fileIndex: file.originalIndex,
                kind: .file,
                title: job.title.isEmpty ? job.source : job.title,
                source: job.source,
                status: job.status,
                displayName: file.relativePath,
                detail: file.archiveEntry == nil ? Self.apiOutputDisplayPath(file) : "Archive entry",
                byteCount: apiOutputFileSize(file)
            )
        }

        if !job.message.trimmed.isEmpty || !job.comment.trimmed.isEmpty {
            let text = textViewerMessageText(for: job)
            entries.append(TextViewerEntry(
                id: "\(job.id.uuidString):message",
                jobID: job.id,
                fileIndex: nil,
                kind: .message,
                title: job.title.isEmpty ? job.source : job.title,
                source: job.source,
                status: job.status,
                displayName: "Task Messages",
                detail: job.message.trimmed.isEmpty ? "Comment" : "Message",
                byteCount: text.utf8.count
            ))
        }

        return entries
    }

    private func textViewerDocument(for entry: TextViewerEntry, limit: Int) -> TextViewerDocument {
        guard let job = jobs.first(where: { $0.id == entry.jobID }) else {
            return TextViewerDocument(entry: entry, text: "", bytesRead: 0, byteCount: 0, truncated: false, errorMessage: "Task not found")
        }

        if let fileIndex = entry.fileIndex {
            let files = apiOutputFiles(for: job)
            guard let file = files.first(where: { $0.originalIndex == fileIndex }),
                  apiIsTextOutputFile(file) else {
                return TextViewerDocument(entry: entry, text: "", bytesRead: 0, byteCount: 0, truncated: false, errorMessage: "Text file not found")
            }
            do {
                let read = try apiReadTextFile(file, limit: limit)
                return TextViewerDocument(
                    entry: entry,
                    text: read.text,
                    bytesRead: read.bytesRead,
                    byteCount: apiOutputFileSize(file),
                    truncated: read.truncated,
                    errorMessage: nil
                )
            } catch {
                return TextViewerDocument(entry: entry, text: "", bytesRead: 0, byteCount: apiOutputFileSize(file), truncated: false, errorMessage: error.localizedDescription)
            }
        }

        let text = textViewerMessageText(for: job)
        return TextViewerDocument(
            entry: entry,
            text: text,
            bytesRead: text.utf8.count,
            byteCount: text.utf8.count,
            truncated: false,
            errorMessage: nil
        )
    }

    private func textViewerMessageText(for job: DownloadJob) -> String {
        [
            job.message.trimmed.isEmpty ? nil : "Message: \(job.message.trimmed)",
            job.comment.trimmed.isEmpty ? nil : "Comment: \(job.comment.trimmed)"
        ].compactMap { $0 }.joined(separator: "\n\n")
    }

    nonisolated static func pasteInputText(fileURLs: [URL], string: String?) -> String? {
        let fileURLText = fileURLs
            .filter(\.isFileURL)
            .map { $0.standardizedFileURL.absoluteString }
        if !fileURLText.isEmpty {
            return fileURLText.joined(separator: "\n")
        }

        guard let string, !string.trimmed.isEmpty else { return nil }
        return string
    }

    private static func pasteboardFileURLs(from pasteboard: NSPasteboard) -> [URL] {
        let objects = pasteboard.readObjects(
            forClasses: [NSURL.self],
            options: [.urlReadingFileURLsOnly: true]
        ) ?? []
        return objects.compactMap { object in
            if let url = object as? URL {
                return url
            }
            if let url = object as? NSURL {
                return url as URL
            }
            return nil
        }
    }

    func setInputText(_ text: String) {
        let changed = inputText != text
        inputText = text
        inputCursorUTF16Offset = (text as NSString).length
        if changed {
            inputAutocompleteSelectionIndex = 0
            isInputAutocompleteDismissed = false
        }
        persistInputTextDraft()
    }

    var inputAutocompleteSuggestions: [String] {
        guard isURLInputFocused, !isInputAutocompleteDismissed else { return [] }
        return availableInputAutocompleteSuggestions
    }

    private var availableInputAutocompleteSuggestions: [String] {
        let fragment = OriginalInputAutocomplete.fragment(
            in: inputText,
            cursorUTF16Offset: inputCursorUTF16Offset
        )
        return OriginalInputAutocomplete.suggestions(forFragment: fragment)
    }

    func setURLInputFocused(_ focused: Bool) {
        isURLInputFocused = focused
        inputAutocompleteSelectionIndex = 0
        isInputAutocompleteDismissed = !focused
    }

    func setInputCursorUTF16Offset(_ offset: Int) {
        let clamped = min(max(offset, 0), (inputText as NSString).length)
        guard inputCursorUTF16Offset != clamped else { return }
        inputCursorUTF16Offset = clamped
        inputAutocompleteSelectionIndex = 0
    }

    @discardableResult
    func moveInputAutocompleteSelection(by delta: Int) -> Bool {
        let suggestions = inputAutocompleteSuggestions
        guard !suggestions.isEmpty else { return false }
        inputAutocompleteSelectionIndex = min(
            max(inputAutocompleteSelectionIndex + delta, 0),
            suggestions.count - 1
        )
        return true
    }

    func setInputAutocompleteSelection(_ index: Int) {
        let suggestions = inputAutocompleteSuggestions
        guard !suggestions.isEmpty else { return }
        inputAutocompleteSelectionIndex = min(max(index, 0), suggestions.count - 1)
    }

    @discardableResult
    func acceptInputAutocompleteSuggestion(_ explicitSuggestion: String? = nil) -> Bool {
        let suggestions = explicitSuggestion == nil
            ? inputAutocompleteSuggestions
            : availableInputAutocompleteSuggestions
        guard !suggestions.isEmpty else { return false }
        let index = min(max(inputAutocompleteSelectionIndex, 0), suggestions.count - 1)
        let suggestion = explicitSuggestion ?? suggestions[index]
        guard suggestions.contains(suggestion) else { return false }

        let replacement = OriginalInputAutocomplete.replacingFragment(
            in: inputText,
            cursorUTF16Offset: inputCursorUTF16Offset,
            with: suggestion
        )
        inputText = replacement.text
        inputCursorUTF16Offset = replacement.cursorUTF16Offset
        inputAutocompleteSelectionIndex = 0
        isInputAutocompleteDismissed = true
        persistInputTextDraft()
        return true
    }

    @discardableResult
    func dismissInputAutocomplete() -> Bool {
        guard !inputAutocompleteSuggestions.isEmpty else { return false }
        isInputAutocompleteDismissed = true
        inputAutocompleteSelectionIndex = 0
        return true
    }

    private func insertAddedJobsAtTop(_ newJobs: [DownloadJob], preservingVisualOrder: Bool = false) {
        guard !newJobs.isEmpty else { return }
        let orderedJobs = preservingVisualOrder ? newJobs : Array(newJobs.reversed())

        // Active workers retain their array position while awaiting network and file I/O.
        // Keep their physical positions stable while a UUID order preserves the visible queue.
        if isRunning {
            if activeQueueOrderIDs == nil {
                activeQueueOrderIDs = jobs.map(\.id)
            }
            let existingOrder = queueOrderedJobs
            let newIDs = Set(orderedJobs.map(\.id))
            var updatedOrder = existingOrder.map(\.id).filter { !newIDs.contains($0) }
            let insertionIndex = existingOrder.firstIndex(where: { !$0.isPinned }) ?? updatedOrder.endIndex
            updatedOrder.insert(contentsOf: orderedJobs.map(\.id), at: insertionIndex)
            activeQueueOrderIDs = updatedOrder
            jobs.append(contentsOf: orderedJobs)
            return
        }

        let insertionIndex = jobs.firstIndex(where: { !$0.isPinned }) ?? jobs.endIndex
        jobs.insert(contentsOf: orderedJobs, at: insertionIndex)
    }

    func addURLs() {
        addURLs(fallbackText: nil)
    }

    func addURLs(fallbackText: String?) {
        let sourceText = inputText.trimmed.isEmpty
            ? fallbackText ?? ""
            : inputText
        let items = inputItems(from: sourceText)
        let newJobs = jobsForAdding(items, promptForDuplicates: true)
        if !newJobs.isEmpty {
            insertAddedJobsAtTop(newJobs)
            persistQueue()
        }
        if !newJobs.isEmpty || showingDuplicateAdditionConfirmation {
            inputText = ""
            inputCursorUTF16Offset = 0
            inputAutocompleteSelectionIndex = 0
            isInputAutocompleteDismissed = true
            persistInputTextDraft()
        }
        if !newJobs.isEmpty {
            runQueuedJobsIfEnabled()
        }
    }

    func addLocalFilesAndFolders() {
        let panel = NSOpenPanel()
        panel.canChooseFiles = true
        panel.canChooseDirectories = true
        panel.allowsMultipleSelection = true

        guard panel.runModal() == .OK else { return }
        let urls = panel.urls.map { $0.standardizedFileURL.absoluteString }
        let newJobs = jobsForAdding(urls, promptForDuplicates: true)
        guard !newJobs.isEmpty else { return }
        insertAddedJobsAtTop(newJobs)
        addSummary = "\(newJobs.count) local item(s) added"
        persistQueue()
        runQueuedJobsIfEnabled()
    }

    @discardableResult
    func enqueueOpenedURLs(_ urls: [URL]) -> Int {
        let strings = urls.map { url -> String in
            if url.isFileURL {
                return url.standardizedFileURL.absoluteString
            }
            return url.absoluteString
        }
        let newJobs = jobsForAdding(strings, promptForDuplicates: true)
        guard !newJobs.isEmpty else { return 0 }
        insertAddedJobsAtTop(newJobs)
        addSummary = "\(newJobs.count) opened item(s) added"
        persistQueue()
        runQueuedJobsIfEnabled()
        return newJobs.count
    }

    @discardableResult
    func enqueueDroppedValues(_ values: [String]) -> Int {
        var inputs: [(url: String, metadata: [String: String])] = []
        for value in values {
            if let task = OriginalBrowserExtensionTask.parse(value),
               let item = inputItem(from: task, monitorableOnly: false) {
                inputs.append(item)
                continue
            }
            for line in value.components(separatedBy: .newlines) {
                let trimmed = line.trimmed
                guard !trimmed.isEmpty else { continue }

                if let fileURL = URL(string: trimmed), fileURL.isFileURL {
                    inputs.append((fileURL.standardizedFileURL.absoluteString, [:]))
                } else if trimmed.hasPrefix("/"), FileManager.default.fileExists(atPath: trimmed) {
                    inputs.append((URL(fileURLWithPath: trimmed).standardizedFileURL.absoluteString, [:]))
                } else {
                    inputs.append(contentsOf: inputItems(from: trimmed))
                }
            }
        }

        let newJobs = jobsForAdding(inputs, promptForDuplicates: true)
        guard !newJobs.isEmpty else {
            if !showingDuplicateAdditionConfirmation {
                addSummary = values.isEmpty ? "Drop did not contain a URL or file" : "No new dropped items"
            }
            return 0
        }
        insertAddedJobsAtTop(newJobs)
        addSummary = "\(newJobs.count) dropped item\(newJobs.count == 1 ? "" : "s") added"
        persistQueue()
        runQueuedJobsIfEnabled()
        return newJobs.count
    }

