    func addMP3AudioURLs(fallbackText: String?) {
        let sourceText = inputText.trimmed.isEmpty
            ? fallbackText ?? ""
            : inputText
        let urls = extractURLs(from: sourceText)
        let metadata = [
            "media_request": "audio",
            "audio_format": "mp3"
        ]
        let newJobs = jobsForAdding(
            urls,
            metadata: metadata,
            titleSuffix: " [MP3]",
            promptForDuplicates: true
        )
        if !newJobs.isEmpty {
            insertAddedJobsAtTop(newJobs)
            persistQueue()
            runQueuedJobsIfEnabled()
        }
        if !newJobs.isEmpty || showingDuplicateAdditionConfirmation {
            inputText = ""
            inputCursorUTF16Offset = 0
            inputAutocompleteSelectionIndex = 0
            isInputAutocompleteDismissed = true
            persistInputTextDraft()
        }
    }

