    @discardableResult
    func importQueueJobs(from url: URL) throws -> Int {
        let data = try Data(contentsOf: url)
        let imported: QueueImportDocument
        if url.pathExtension.caseInsensitiveCompare("hdt") == .orderedSame {
            let document = try OriginalHDT.decodeDocument(data)
            imported = QueueImportDocument(jobs: document.jobs, groups: document.groups)
        } else {
            imported = try Self.importedQueueDocument(from: data)
        }

        var importedGroups = imported.groups
        var usedGroupIDs = Set(queueGroups.map(\.id))
        var groupIDMap: [UUID: UUID] = [:]
        for index in importedGroups.indices {
            let originalID = importedGroups[index].id
            var resolvedID = originalID
            while usedGroupIDs.contains(resolvedID) {
                resolvedID = UUID()
            }
            usedGroupIDs.insert(resolvedID)
            groupIDMap[originalID] = resolvedID
            importedGroups[index].id = resolvedID
        }

        var existingIDs = Set(jobs.map(\.id))
        var jobIDMap: [UUID: UUID] = [:]
        var normalized: [DownloadJob] = []
        for var job in imported.jobs {
            let originalID = job.id
            if let oldGroupID = Self.queueGroupID(in: job),
               let newGroupID = groupIDMap[oldGroupID] {
                job.metadata[Self.queueGroupIDMetadataKey] = newGroupID.uuidString
            }
            guard let restored = normalizedImportedQueueJob(job, existingIDs: &existingIDs) else { continue }
            jobIDMap[originalID] = restored.id
            normalized.append(restored)
        }
        for index in importedGroups.indices {
            if let anchor = importedGroups[index].anchorJobID {
                importedGroups[index].anchorJobID = jobIDMap[anchor]
            }
        }
        importedGroups = Self.normalizedQueueGroups(importedGroups, jobs: &normalized)

        guard !normalized.isEmpty || !importedGroups.isEmpty else {
            addSummary = "No jobs imported"
            return 0
        }

        if !normalized.isEmpty {
            insertAddedJobsAtTop(normalized, preservingVisualOrder: true)
        }
        queueGroups.insert(contentsOf: importedGroups, at: 0)
        for jobID in normalized.map(\.id) {
            _ = restoreScheduledRetryIfNeeded(for: jobID)
        }
        addSummary = importedGroups.isEmpty
            ? "\(normalized.count) jobs imported"
            : "\(normalized.count) jobs and \(importedGroups.count) groups imported"
        persistQueue()
        return normalized.count
    }

    func exportQueueJobs(to url: URL) throws {
        let (exported, scope) = queueJobsForExport()
        let exportedGroupIDs = Set(exported.compactMap { jobGroupID(for: $0) })
        let exportedGroups: [QueueGroup]
        switch scope {
        case .all:
            exportedGroups = queueGroups
        case .selected, .filtered:
            exportedGroups = queueGroups.filter { exportedGroupIDs.contains($0.id) }
        }
        let isHDT = url.pathExtension.caseInsensitiveCompare("hdt") == .orderedSame
        let data: Data
        if isHDT {
            data = try OriginalHDT.encode(exported, groups: exportedGroups)
        } else {
            let package = QueueJobPackage(exportedAt: Date(), jobs: exported, groups: exportedGroups)
            let encoder = JSONEncoder()
            encoder.dateEncodingStrategy = .iso8601
            encoder.outputFormatting = [.prettyPrinted, .sortedKeys]
            data = try encoder.encode(package)
        }
        try data.write(to: url, options: .atomic)
        let noun = isHDT ? "original tasks" : "jobs"
        switch scope {
        case .selected:
            addSummary = "\(exported.count) selected \(noun) exported"
        case .filtered:
            addSummary = "\(exported.count) filtered \(noun) exported"
        case .all:
            addSummary = "\(exported.count) \(noun) exported"
        }
    }

