    private enum QueueExportScope {
        case selected
        case filtered
        case all
    }

    private func queueJobsForExport() -> ([DownloadJob], QueueExportScope) {
        let orderedJobs = queueOrderedJobs
        let selected = orderedJobs.filter { selectedJobIDs.contains($0.id) }
        if !selected.isEmpty {
            return (selected, .selected)
        }
        if !queueFilter.trimmed.isEmpty {
            return (filteredJobs, .filtered)
        }
        return (orderedJobs, .all)
    }

    func saveCurrentQueueFilterBookmark() {
        let query = queueFilter.trimmed
        guard !query.isEmpty else {
            addSummary = "Enter a filter"
            return
