        let normalized = query.lowercased()
        if let index = queueFilterBookmarks.firstIndex(where: { $0.query.lowercased() == normalized }) {
            queueFilterBookmarks[index].title = Self.queueFilterBookmarkTitle(for: query)
            queueFilterBookmarks[index].query = query
