    private func confirmPythonScriptExecution(metadata: PythonScriptStaticMetadata, asPlugin: Bool) -> Bool {
        let alert = NSAlert()
        alert.alertStyle = .warning
        alert.messageText = asPlugin ? "Install \(metadata.title)?" : "Run \(metadata.title)?"
        let author = metadata.author.trimmed.isEmpty ? "Unknown" : metadata.author
        let size = ByteCountFormatter.string(fromByteCount: Int64(metadata.byteCount), countStyle: .file)
        let signature = metadata.signature.trimmed.isEmpty
            ? "No script signature is present."
            : "A signature is present, but this port cannot verify the original app's signature format."
        let comment = metadata.comment.trimmed.isEmpty ? "" : "\n\n\(metadata.comment)"
        alert.informativeText = "Author: \(author)\nEncoding: \(metadata.encoding) · \(size)\n\n\(signature)\nPython scripts can read or change files and access the network. Continue only if you trust this script.\(comment)"
        alert.addButton(withTitle: asPlugin ? "Install Plugin" : "Run Script")
        alert.addButton(withTitle: "Cancel")
        return alert.runModal() == .alertFirstButtonReturn
    }

    private func sortPythonScriptPlugins() {
        pythonScriptPlugins.sort { lhs, rhs in
            if lhs.isSession != rhs.isSession {
                return !lhs.isSession
            }
            return lhs.title.localizedStandardCompare(rhs.title) == .orderedAscending
        }
    }

    private func effectivePythonThemes() -> [PythonThemeDescriptor] {
        var keyOrder: [String] = []
        var themesByKey: [String: PythonThemeDescriptor] = [:]
        let registrationOrder = pythonScriptPlugins
            .filter(\.isEnabled)
            .sorted { lhs, rhs in
                if lhs.importedAt != rhs.importedAt {
                    return lhs.importedAt < rhs.importedAt
                }
                return lhs.digest < rhs.digest
            }
        for plugin in registrationOrder {
            for rawTheme in plugin.registeredThemes {
                guard let theme = rawTheme.normalized() else { continue }
                if themesByKey[theme.key] == nil {
                    keyOrder.append(theme.key)
                }
                themesByKey[theme.key] = theme
            }
        }
        return keyOrder.compactMap { themesByKey[$0] }
    }

    private func refreshPythonThemeSelection() {
        let key = selectedPythonThemeKey.trimmed.lowercased()
        let defaultLabel = AppLocalization.text("기본", language: interfaceLanguage)
        guard !key.isEmpty else {
            selectedPythonThemeKey = ""
            pythonThemeStatus = "\(defaultLabel) · \(appAppearanceMode.label)"
            return
        }
        guard let theme = availablePythonThemes.first(where: { $0.key == key }) else {
            selectedPythonThemeKey = ""
            UserDefaults.standard.removeObject(forKey: "selectedPythonThemeKey")
            pythonThemeStatus = "\(defaultLabel) · \(appAppearanceMode.label)"
            return
        }
        selectedPythonThemeKey = theme.key
        let appearance: String
        switch theme.appearance {
        case .system: appearance = appAppearanceMode.label
        case .light: appearance = AppLocalization.text("라이트", language: interfaceLanguage)
        case .dark: appearance = AppLocalization.text("다크", language: interfaceLanguage)
        }
        pythonThemeStatus = "\(theme.displayName) · \(appearance)"
    }

    private func refreshPythonScriptStatus() {
        let enabled = pythonScriptPlugins.filter(\.isEnabled).count
        let runtimeReady = PythonScriptBridge.pythonExecutableURL(configuredPath: pythonPath) != nil
        pythonScriptStatus = runtimeReady
            ? "Python 3 준비됨 · \(enabled)/\(pythonScriptPlugins.count)개 사용"
            : "Python 3 없음 · 실행 파일을 선택하세요"
        refreshPythonThemeSelection()
    }

    private func matchingPythonScriptPlugin(
        for url: URL
    ) -> (plugin: PythonScriptPlugin, downloader: PythonDownloaderDescriptor)? {
        for plugin in pythonScriptPlugins.reversed() where plugin.isEnabled {
            if let downloader = plugin.matchingDownloader(for: url) {
                return (plugin, downloader)
            }
        }
        return nil
    }

    private func effectivePythonHookCalls(
        for event: PythonHookEvent,
        matchingNames: Set<String>? = nil
    ) -> [EffectivePythonHookCall] {
        var nameOrder: [String] = []
        var owners: [String: PythonScriptPlugin] = [:]
        let registrationOrder = pythonScriptPlugins
            .filter(\.isEnabled)
            .sorted { lhs, rhs in
                if lhs.importedAt != rhs.importedAt {
                    return lhs.importedAt < rhs.importedAt
                }
                return lhs.digest < rhs.digest
            }
        for plugin in registrationOrder {
            for hook in plugin.registeredHooks where hook.event == event && (matchingNames?.contains(hook.name) ?? true) {
                if owners[hook.name] == nil {
                    nameOrder.append(hook.name)
                }
                owners[hook.name] = plugin
            }
        }

        var calls: [EffectivePythonHookCall] = []
        for name in nameOrder {
            guard let plugin = owners[name] else { continue }
            if calls.last?.plugin.id == plugin.id {
                calls[calls.count - 1].names.append(name)
            } else {
                calls.append(EffectivePythonHookCall(plugin: plugin, names: [name]))
            }
        }
        return calls
    }

    private func runPythonHooks(
        event: PythonHookEvent,
        context initialContext: PythonHookContext,
        matchingNames: Set<String>? = nil
    ) async throws -> PythonHookContext {
        let calls = effectivePythonHookCalls(for: event, matchingNames: matchingNames)
        guard !calls.isEmpty else { return initialContext }
        var context = initialContext
        var executed = 0
        pythonHookStatus = "\(event.shortLabel) 후크 실행 중..."

        do {
            for call in calls {
                let result = try await PythonScriptBridge(configuredPythonPath: pythonPath).runHooks(
                    plugin: call.plugin,
                    event: event,
                    names: call.names,
                    context: context
                )
                context = result.context
                executed += call.names.count
                recordPythonHookLogs(result.logs, plugin: call.plugin, event: event)
            }
            pythonHookStatus = "\(event.shortLabel.capitalized): 후크 \(executed)개"
            return context
        } catch {
            pythonHookStatus = "\(event.shortLabel.capitalized) 후크 실패: \(error.localizedDescription)"
            throw error
        }
    }

    private func runSyntheticPythonDownloadHooks(
        sourceURL: URL,
        title: String,
        filename: String? = nil,
        metadata: [String: String] = [:],
        jobIndex: Int
    ) async throws -> PythonHookContext? {
        guard jobs.indices.contains(jobIndex),
              jobs[jobIndex].metadata["python_hook_download_ran"] != "true",
              !effectivePythonHookCalls(for: .taskAboutToDownload).isEmpty else {
            return nil
        }
        var context = PythonScriptBridge.hookContext(job: jobs[jobIndex], sourceURL: sourceURL)
        context.title = title
        context.metadata = DownloadMetadata.clean(jobs[jobIndex].metadata.merging(metadata) { _, new in new })
        context.type = context.metadata["type"]
        if ["http", "https", "file"].contains(sourceURL.scheme?.lowercased() ?? "") {
            let headers = requestOptions(for: sourceURL)
            context.assets = [PythonHookAssetContext(
                url: sourceURL.absoluteString,
                filename: filename?.trimmed.isEmpty == false
                    ? filename!.trimmed
                    : (sourceURL.lastPathComponent.trimmed.isEmpty ? "download" : sourceURL.lastPathComponent),
                referer: headers.referer,
                userAgent: headers.userAgent,
                metadata: metadata
            )]
            context.total = 1
        }
        context = try await runPythonHooks(event: .taskAboutToDownload, context: context)
        let formatType = context.type?.trimmed ?? ""
        let formatNames: Set<String> = formatType.isEmpty ? [] : [formatType]
        if !context.assets.isEmpty,
           !formatNames.isEmpty,
           !effectivePythonHookCalls(for: .format, matchingNames: formatNames).isEmpty {
            context = try await runPythonHooks(event: .format, context: context, matchingNames: formatNames)
        }
        applyPythonHookContext(context, toJobAt: jobIndex)
        jobs[jobIndex].metadata["python_hook_download_ran"] = "true"
        let existingKeys = jobs[jobIndex].metadata["python_hook_preserved_keys", default: ""]
            .split(separator: ",")
            .map { String($0).trimmed }
            .filter { !$0.isEmpty }
        jobs[jobIndex].metadata["python_hook_preserved_keys"] = Set(existingKeys + ["python_hook_download_ran"])
            .sorted()
            .joined(separator: ",")
        persistQueue()
        return context
    }

    private func recordPythonHookLogs(_ text: String, plugin: PythonScriptPlugin, event: PythonHookEvent) {
        let lines = text
            .components(separatedBy: .newlines)
            .map(\.trimmed)
            .filter { !$0.isEmpty }
            .suffix(12)
        for line in lines {
            recordActivity("\(plugin.title) [\(event.shortLabel)]: \(String(line.prefix(500)))", category: "Hook")
        }
    }

    private func recordPythonScriptLogs(_ text: String, plugin: PythonScriptPlugin, scope: String) {
        let lines = text
            .components(separatedBy: .newlines)
            .map(\.trimmed)
            .filter { !$0.isEmpty }
            .suffix(12)
        for line in lines {
            recordActivity("\(plugin.title) [\(scope)]: \(String(line.prefix(500)))", category: "Script")
        }
    }

    private func applyPythonHookContext(_ context: PythonHookContext, toJobAt index: Int) {
        guard jobs.indices.contains(index) else { return }
        let previousMetadata = jobs[index].metadata
        if !context.sourceURL.trimmed.isEmpty {
            jobs[index].source = context.sourceURL.trimmed
        }
        if !context.title.trimmed.isEmpty {
            jobs[index].title = context.title.trimmed
        }
        var metadata = Self.resolvedMetadataPreservingRuntimeState(
            context.metadata,
            previous: previousMetadata
        )
        let changedKeys = Set(previousMetadata.keys).union(metadata.keys).filter { key in
            key != "python_hook_preserved_keys" && previousMetadata[key] != metadata[key]
        }
        let previouslyPreserved = Set(
            previousMetadata["python_hook_preserved_keys", default: ""]
                .split(separator: ",")
                .map { String($0).trimmed }
                .filter { !$0.isEmpty }
        )
        let preserved = previouslyPreserved.union(changedKeys).sorted()
        if !preserved.isEmpty {
            metadata["python_hook_preserved_keys"] = preserved.joined(separator: ",")
        }
        jobs[index].metadata = metadata
        if !context.outputPath.trimmed.isEmpty {
            jobs[index].outputPath = context.outputPath.trimmed
        }
        jobs[index].total = max(jobs[index].total, context.total)
        jobs[index].completed = max(jobs[index].completed, context.completed)
        persistQueue()
    }

    @discardableResult
    func loadSiteRulePluginManifests(from directory: URL = AppPaths.pluginDirectory) -> Int {
        let fileManager = FileManager.default
        var isDirectory: ObjCBool = false
        guard fileManager.fileExists(atPath: directory.path, isDirectory: &isDirectory), isDirectory.boolValue else {
            return 0
        }
        guard let enumerator = fileManager.enumerator(
            at: directory,
            includingPropertiesForKeys: [.isRegularFileKey],
            options: [.skipsHiddenFiles]
        ) else {
            return 0
        }

        let manifestURLs = enumerator
            .compactMap { $0 as? URL }
            .filter { url in
                guard url.pathExtension.lowercased() == "json" else { return false }
                let resourceValues = try? url.resourceValues(forKeys: [.isRegularFileKey])
                return resourceValues?.isRegularFile == true
            }
            .sorted { lhs, rhs in
                lhs.path.localizedStandardCompare(rhs.path) == .orderedAscending
            }

        let imported = manifestURLs.flatMap { url -> [SiteRule] in
            guard let data = try? Data(contentsOf: url),
                  let rules = try? Self.siteRules(fromRuleData: data, sourceURL: url) else {
                return []
            }
            return rules
        }

        return mergeImportedSiteRules(imported)
    }

    func enqueueBookmark(_ bookmark: URLBookmark) {
        let newJobs = jobsForAdding([bookmark.url])
        guard !newJobs.isEmpty else { return }
        insertAddedJobsAtTop(newJobs)
        persistQueue()
    }

    func removeBookmark(_ bookmark: URLBookmark) {
        bookmarks.removeAll { $0.id == bookmark.id }
        userData.bookmarks = bookmarks
        persistUserData()
    }

    func sortBookmarksByTitle() {
        guard bookmarks.count > 1 else {
            addSummary = bookmarks.isEmpty ? "No bookmarks" : "Bookmarks already sorted"
            return
        }

        bookmarks.sort { lhs, rhs in
            let titleCompare = Self.bookmarkSortTitle(lhs).localizedStandardCompare(Self.bookmarkSortTitle(rhs))
            if titleCompare != .orderedSame {
                return titleCompare == .orderedAscending
            }
            return lhs.url.localizedStandardCompare(rhs.url) == .orderedAscending
        }
        userData.bookmarks = bookmarks
        persistUserData()
        addSummary = "Bookmarks sorted by name"
    }

    func clearBookmarks() {
        let removed = bookmarks.count
        guard removed > 0 else {
            addSummary = "No bookmarks"
            return
        }

        bookmarks.removeAll()
        editingBookmark = nil
        bookmarkFilter = ""
        userData.bookmarks = bookmarks
        persistUserData()
        addSummary = "\(removed) bookmarks cleared"
    }

    func beginEditingBookmark(_ bookmark: URLBookmark) {
        editingBookmark = bookmark
        bookmarkEditTitle = bookmark.title
        bookmarkEditTags = bookmark.tags.joined(separator: ", ")
        bookmarkEditNote = bookmark.note
    }

    func cancelEditingBookmark() {
        editingBookmark = nil
        bookmarkEditTitle = ""
        bookmarkEditTags = ""
        bookmarkEditNote = ""
    }

    func saveEditingBookmark() {
        guard let bookmark = editingBookmark else { return }
        updateBookmark(bookmark, title: bookmarkEditTitle, tagsText: bookmarkEditTags, note: bookmarkEditNote)
        cancelEditingBookmark()
    }

    func updateBookmark(_ bookmark: URLBookmark, title: String, tagsText: String, note: String) {
        guard let index = bookmarks.firstIndex(where: { $0.id == bookmark.id }) else { return }
        let cleanedTitle = title.trimmed
        bookmarks[index].title = cleanedTitle.isEmpty ? bookmarkTitle(for: bookmarks[index].url) : cleanedTitle
        bookmarks[index].tags = Self.bookmarkTags(from: tagsText)
        bookmarks[index].note = note.trimmed
        userData.bookmarks = bookmarks
        persistUserData()
        addSummary = "Bookmark updated"
    }

    func beginEditingJob(_ job: DownloadJob) {
        guard let current = jobs.first(where: { $0.id == job.id }) else { return }
        guard !isActive(current.status) else {
            addSummary = "Cancel active jobs before editing"
            return
        }
        editingJob = current
        jobEditTitle = current.title
        jobEditSource = current.source
        jobEditInput = current.metadata["input"] ?? current.metadata["input_url"] ?? current.metadata["source_input_url"] ?? current.source
        jobEditOutputPath = current.outputPath
        jobEditArtist = current.metadata["artist"] ?? current.metadata["artists"] ?? current.metadata["author"] ?? ""
        jobEditZipFile = current.metadata["zipfile"] ?? current.metadata["zip"] ?? current.metadata["archive"] ?? ""
        jobEditStatus = current.status
        jobEditType = current.metadata["type"] ?? current.metadata["category"] ?? current.metadata["media_type"] ?? ""
        jobEditSite = current.metadata["site"] ?? current.metadata["host"] ?? current.metadata["domain"] ?? ""
        jobEditDate = current.metadata["date"] ?? current.metadata["upload_date"] ?? current.metadata["download_completed_at"] ?? ""
        jobEditRange = current.rangeExpression
        jobEditNamesText = Self.jobEditNamesText(for: current)
        jobEditComment = current.comment
        jobEditThumbnailPNGData = nil
        jobEditThumbnailChanged = false
        jobEditOriginalThumbnailPath = current.metadata[QueueThumbnailProvider.customThumbnailMetadataKey]?.trimmed ?? ""
        jobEditThumbnailIsCustom = !jobEditOriginalThumbnailPath.isEmpty
        jobEditThumbnailImage = nil
        jobEditThumbnailMessage = jobEditThumbnailIsCustom ? "Custom thumbnail" : "Loading thumbnail"
        loadJobEditThumbnail(for: current, includeCustomOverride: true)
    }

    func cancelEditingJob() {
        jobEditThumbnailLoadTask?.cancel()
        jobEditThumbnailLoadTask = nil
        editingJob = nil
        jobEditTitle = ""
        jobEditSource = ""
        jobEditInput = ""
        jobEditOutputPath = ""
        jobEditArtist = ""
        jobEditZipFile = ""
        jobEditStatus = .queued
        jobEditType = ""
        jobEditSite = ""
        jobEditDate = ""
        jobEditRange = ""
        jobEditNamesText = ""
        jobEditComment = ""
        jobEditThumbnailImage = nil
        jobEditThumbnailIsCustom = false
        jobEditThumbnailMessage = "No thumbnail"
        jobEditThumbnailPNGData = nil
        jobEditThumbnailChanged = false
        jobEditOriginalThumbnailPath = ""
    }

    func saveEditingJob() {
        guard let job = editingJob else { return }
        var metadataUpdates = [
            "input": jobEditInput,
            "artist": jobEditArtist,
            "zipfile": jobEditZipFile,
            "type": jobEditType,
            "site": jobEditSite,
            "date": jobEditDate
        ]
        var newlyWrittenThumbnail: URL?
        if jobEditThumbnailChanged {
            do {
                if let data = jobEditThumbnailPNGData {
                    try AppPaths.ensureDirectory(AppPaths.customThumbnailDirectory)
                    let filename = "\(job.id.uuidString)-\(UUID().uuidString).png"
                    let url = AppPaths.customThumbnailDirectory.appendingPathComponent(filename)
                    try data.write(to: url, options: .atomic)
                    metadataUpdates[QueueThumbnailProvider.customThumbnailMetadataKey] = url.path
                    newlyWrittenThumbnail = url
                } else {
                    metadataUpdates[QueueThumbnailProvider.customThumbnailMetadataKey] = ""
                }
            } catch {
                addSummary = "Thumbnail update failed: \(error.localizedDescription)"
                return
            }
        }

        guard updateJob(
            job,
            title: jobEditTitle,
            source: jobEditSource,
            rangeExpression: jobEditRange,
            comment: jobEditComment,
            outputPath: jobEditOutputPath,
            status: jobEditStatus,
            metadataUpdates: metadataUpdates
        ) else {
            if let newlyWrittenThumbnail {
                try? FileManager.default.removeItem(at: newlyWrittenThumbnail)
            }
            return
        }
        if jobEditThumbnailChanged {
            removeManagedCustomThumbnail(
                at: jobEditOriginalThumbnailPath,
                keeping: newlyWrittenThumbnail
            )
            pruneManagedCustomThumbnails()
        }
        cancelEditingJob()
    }

    func selectJobEditThumbnail() {
        guard editingJob != nil else { return }
        let panel = NSOpenPanel()
        panel.title = "Select Thumbnail"
        panel.prompt = "Select"
        panel.canChooseFiles = true
        panel.canChooseDirectories = false
        panel.allowsMultipleSelection = false
        panel.allowedContentTypes = [.image]

        guard panel.runModal() == .OK, let url = panel.url else { return }
        do {
            let data = try Data(contentsOf: url, options: [.mappedIfSafe])
            guard stageJobEditThumbnail(data: data) else { return }
            addSummary = "Custom thumbnail selected"
        } catch {
            jobEditThumbnailMessage = "Could not read thumbnail"
            addSummary = "Thumbnail selection failed: \(error.localizedDescription)"
        }
    }

    @discardableResult
    func stageJobEditThumbnail(data: Data) -> Bool {
        guard editingJob != nil,
              let pngData = Self.normalizedThumbnailPNGData(from: data),
              let image = NSImage(data: pngData) else {
            jobEditThumbnailMessage = "Invalid image"
            return false
        }
        jobEditThumbnailLoadTask?.cancel()
        jobEditThumbnailLoadTask = nil
        jobEditThumbnailPNGData = pngData
        jobEditThumbnailImage = image
        jobEditThumbnailChanged = true
        jobEditThumbnailIsCustom = true
        jobEditThumbnailMessage = "Custom thumbnail"
        return true
    }

    func resetJobEditThumbnail() {
        guard let job = editingJob else { return }
        jobEditThumbnailLoadTask?.cancel()
        jobEditThumbnailPNGData = nil
        jobEditThumbnailChanged = true
        jobEditThumbnailIsCustom = false
        jobEditThumbnailImage = nil
        jobEditThumbnailMessage = "Loading automatic thumbnail"
        var automaticJob = job
        automaticJob.metadata.removeValue(forKey: QueueThumbnailProvider.customThumbnailMetadataKey)
        loadJobEditThumbnail(for: automaticJob, includeCustomOverride: false)
    }

    func saveJobEditThumbnailAs() {
        guard jobEditThumbnailImage != nil else {
            jobEditThumbnailMessage = "No thumbnail"
            return
        }
        let panel = NSSavePanel()
        panel.title = "Save Thumbnail"
        panel.prompt = "Save"
        panel.allowedContentTypes = [.png]
        panel.nameFieldStringValue = "thumbnail.png"

        guard panel.runModal() == .OK, let url = panel.url else { return }
        do {
            try exportJobEditThumbnail(to: url)
            addSummary = "Thumbnail saved"
        } catch {
            jobEditThumbnailMessage = "Could not save thumbnail"
            addSummary = "Thumbnail save failed: \(error.localizedDescription)"
        }
    }

    func exportJobEditThumbnail(to url: URL) throws {
        let data = jobEditThumbnailPNGData ?? jobEditThumbnailImage.flatMap(Self.pngData)
        guard let data else {
            throw NativeDownloadError.unsupported("No thumbnail is available.")
        }
        try data.write(to: url, options: .atomic)
    }

    private func loadJobEditThumbnail(for job: DownloadJob, includeCustomOverride: Bool) {
        jobEditThumbnailLoadTask?.cancel()
        let jobID = job.id
        let destination = destinationPath
        jobEditThumbnailLoadTask = Task { [weak self] in
            let image = await QueueThumbnailProvider.image(
                for: job,
                destinationPath: destination,
                includeCustomOverride: includeCustomOverride
            )
            guard !Task.isCancelled,
                  let self,
                  self.editingJob?.id == jobID,
                  self.jobEditThumbnailPNGData == nil else {
                return
            }
            self.jobEditThumbnailImage = image
            if image == nil {
                self.jobEditThumbnailMessage = "No thumbnail"
            } else {
                self.jobEditThumbnailMessage = self.jobEditThumbnailIsCustom
                    ? "Custom thumbnail"
                    : "Automatic thumbnail"
            }
        }
    }

    private nonisolated static func normalizedThumbnailPNGData(from data: Data) -> Data? {
        guard let source = CGImageSourceCreateWithData(data as CFData, nil) else { return nil }
        let options: [CFString: Any] = [
            kCGImageSourceCreateThumbnailFromImageAlways: true,
            kCGImageSourceCreateThumbnailWithTransform: true,
            kCGImageSourceThumbnailMaxPixelSize: 1_200,
            kCGImageSourceShouldCacheImmediately: true
        ]
        guard let image = CGImageSourceCreateThumbnailAtIndex(source, 0, options as CFDictionary) else {
            return nil
        }
        return NSBitmapImageRep(cgImage: image).representation(using: .png, properties: [:])
    }

    private nonisolated static func pngData(from image: NSImage) -> Data? {
        guard let tiff = image.tiffRepresentation,
              let representation = NSBitmapImageRep(data: tiff) else {
            return nil
        }
        return representation.representation(using: .png, properties: [:])
    }

    private func removeManagedCustomThumbnail(at rawPath: String, keeping retainedURL: URL?) {
        guard let oldURL = managedCustomThumbnailURL(from: rawPath),
              oldURL.standardizedFileURL != retainedURL?.standardizedFileURL else {
            return
        }
        try? FileManager.default.removeItem(at: oldURL)
    }

    private func managedCustomThumbnailURL(from rawPath: String) -> URL? {
        let path = rawPath.trimmed
        guard !path.isEmpty else { return nil }
        let candidate: URL
        if let url = URL(string: path), url.isFileURL {
            candidate = url.standardizedFileURL
        } else {
            candidate = URL(fileURLWithPath: (path as NSString).expandingTildeInPath).standardizedFileURL
        }
        let directory = AppPaths.customThumbnailDirectory.standardizedFileURL
        guard candidate.deletingLastPathComponent() == directory else { return nil }
        return candidate
    }

    private func pruneManagedCustomThumbnails(fileManager: FileManager = .default) {
        let directory = AppPaths.customThumbnailDirectory.standardizedFileURL
        guard let files = try? fileManager.contentsOfDirectory(
            at: directory,
            includingPropertiesForKeys: nil,
            options: [.skipsHiddenFiles]
        ) else {
            return
        }
        let referenced = Set(jobs.compactMap { job in
            managedCustomThumbnailURL(
                from: job.metadata[QueueThumbnailProvider.customThumbnailMetadataKey] ?? ""
            )?.standardizedFileURL.path
        })
        for file in files where !referenced.contains(file.standardizedFileURL.path) {
            try? fileManager.removeItem(at: file)
        }
    }

    func canOpenPageSelector(for job: DownloadJob) -> Bool {
        guard let current = jobs.first(where: { $0.id == job.id }) else { return false }
        return apiPageSelectorTotal(for: current) > 0 || !current.rangeExpression.trimmed.isEmpty
    }

    func beginPageSelector(for job: DownloadJob) {
        guard let current = jobs.first(where: { $0.id == job.id }) else { return }
        let candidates = apiPageSelectorCandidates(for: current)
        let total = apiPageSelectorTotal(for: current, candidateCount: candidates.count)
        guard total > 0 || !current.rangeExpression.trimmed.isEmpty else {
            addSummary = "No pages available"
            return
        }

        pageSelectorJob = current
        pageSelectorItems = candidates.prefix(2_000).map { candidate in
            PageSelectorItem(
                index: candidate.index,
                page: candidate.index + 1,
                title: candidate.title,
                detail: candidate.detail,
                type: candidate.type
            )
        }
        pageSelectorSelectedIndexes = Set(apiPageSelectorSelectedIndexes(range: current.rangeExpression, total: total))
        pageSelectorRangeText = current.rangeExpression
        pageSelectorMessage = pageSelectorStatusText(total: total)
    }

    func cancelPageSelector() {
        pageSelectorJob = nil
        pageSelectorItems = []
        pageSelectorSelectedIndexes = []
        pageSelectorRangeText = ""
        pageSelectorMessage = ""
    }

    func setPageSelectorItem(_ index: Int, selected: Bool) {
        if selected {
            pageSelectorSelectedIndexes.insert(index)
        } else {
            pageSelectorSelectedIndexes.remove(index)
        }
        updatePageSelectorRangeFromSelection()
    }

    func setPageSelectorRangeText(_ text: String) {
        pageSelectorRangeText = text
        syncPageSelectorSelectionFromRange()
    }

    func selectAllPageSelectorItems() {
        pageSelectorSelectedIndexes = Set(0..<pageSelectorTotal())
        pageSelectorRangeText = ""
        pageSelectorMessage = pageSelectorStatusText()
    }

    func savePageSelector() {
        guard let job = pageSelectorJob,
              let index = jobs.firstIndex(where: { $0.id == job.id }) else {
            cancelPageSelector()
            return
        }
        guard !isActive(jobs[index].status) else {
            pageSelectorMessage = "Cancel active jobs before editing pages"
            return
        }

        let range = pageSelectorRangeText.trimmed
        guard Self.isValidAssetRangeExpression(range) else {
            pageSelectorMessage = "Enter a valid range"
            return
        }
        let total = apiPageSelectorTotal(for: jobs[index])
        if total > 0, !range.isEmpty {
            do {
                _ = try Self.assetIndexes(forRangeExpression: range, total: total)
            } catch {
                pageSelectorMessage = error.localizedDescription
                return
            }
        }

        jobs[index].rangeExpression = range
        if jobs[index].status == .finished {
            scheduleRestartIfNeeded(for: jobs[index])
        } else {
            cancelScheduledRestart(for: jobs[index].id)
        }
        addSummary = range.isEmpty ? "Page range cleared" : "Page range updated"
        persistQueue()
        cancelPageSelector()
    }

    private func updatePageSelectorRangeFromSelection() {
        let total = pageSelectorTotal()
        if total > 0, pageSelectorSelectedIndexes.count == total {
            pageSelectorRangeText = ""
        } else if pageSelectorSelectedIndexes.isEmpty {
            pageSelectorRangeText = "0"
        } else {
            pageSelectorRangeText = Self.compactRangeDescription(fromZeroBasedIndexes: pageSelectorSelectedIndexes.sorted())
        }
        pageSelectorMessage = pageSelectorStatusText(total: total)
    }

    private func syncPageSelectorSelectionFromRange() {
        let total = pageSelectorTotal()
        guard total > 0 else {
            pageSelectorMessage = "No pages available"
            return
        }
        let range = pageSelectorRangeText.trimmed
        if range.isEmpty {
            pageSelectorSelectedIndexes = Set(0..<total)
            pageSelectorMessage = pageSelectorStatusText(total: total)
            return
        }
        guard Self.isValidAssetRangeExpression(range),
              let indexes = try? Self.assetIndexes(forRangeExpression: range, total: total) else {
            pageSelectorMessage = "Enter a valid range"
            return
        }
        pageSelectorSelectedIndexes = Set(indexes)
        pageSelectorMessage = pageSelectorStatusText(total: total)
    }

    private func pageSelectorTotal() -> Int {
        guard let job = pageSelectorJob,
              let current = jobs.first(where: { $0.id == job.id }) else {
            return pageSelectorItems.count
        }
        return apiPageSelectorTotal(for: current)
    }

    private func pageSelectorStatusText(total: Int? = nil) -> String {
        let total = total ?? pageSelectorTotal()
        let selected = pageSelectorSelectedIndexes.count
        if pageSelectorItems.count < total {
            return "\(selected) / \(total) selected, showing \(pageSelectorItems.count)"
        }
        return "\(selected) / \(total) selected"
    }

    @discardableResult
    func updateJob(
        _ job: DownloadJob,
        title: String,
        source: String,
        rangeExpression: String,
        comment: String,
        outputPath: String? = nil,
        status: JobStatus? = nil,
        metadataUpdates: [String: String] = [:]
    ) -> Bool {
        guard let index = jobs.firstIndex(where: { $0.id == job.id }) else { return false }
        guard !isActive(jobs[index].status) else {
            addSummary = "Cancel active jobs before editing"
            return false
        }

        let normalizedSource = Self.normalizedInputToken(source.trimmed)
        guard !normalizedSource.isEmpty else {
            addSummary = "Enter a URL"
            return false
        }

        let range = rangeExpression.trimmed
        guard Self.isValidAssetRangeExpression(range) else {
            addSummary = "Enter a valid range"
            return false
        }

        let jobID = jobs[index].id
        jobs[index].source = normalizedSource
        jobs[index].title = title.trimmed.isEmpty ? normalizedSource : title.trimmed
        jobs[index].rangeExpression = range
        jobs[index].comment = comment.trimmed
        if let outputPath {
            jobs[index].outputPath = outputPath.trimmed
        }
        if let status {
            jobs[index].status = status
        }
        for (key, value) in metadataUpdates {
            let cleanedKey = key.trimmed
            guard !cleanedKey.isEmpty else { continue }
            let cleanedValue = value.trimmed
            if cleanedValue.isEmpty {
                jobs[index].metadata.removeValue(forKey: cleanedKey)
            } else {
                jobs[index].metadata[cleanedKey] = cleanedValue
            }
        }
        jobs[index].metadata["native_changed"] = "true"
        if jobs[index].status == .finished {
            scheduleRestartIfNeeded(for: jobs[index])
        } else {
            cancelScheduledRestart(for: jobID)
        }
        addSummary = "Job updated"
        persistQueue()
        return true
    }

    private nonisolated static func jobEditNamesText(for job: DownloadJob, fileManager: FileManager = .default) -> String {
        let outputPath = job.outputPath.trimmed
        guard !outputPath.isEmpty else { return "" }

        let url = URL(fileURLWithPath: outputPath)
        var isDirectory = ObjCBool(false)
        if fileManager.fileExists(atPath: outputPath, isDirectory: &isDirectory), isDirectory.boolValue {
            let names = ((try? fileManager.contentsOfDirectory(atPath: outputPath)) ?? [])
                .sorted { $0.localizedStandardCompare($1) == .orderedAscending }
            return names.prefix(500).joined(separator: "\n")
        }
        return url.lastPathComponent
    }

    func beginEditingJobComment(_ job: DownloadJob) {
        guard let current = jobs.first(where: { $0.id == job.id }) else { return }
        editingCommentJob = current
        editingCommentJobIDs = [current.id]
        jobCommentText = current.comment
    }

    func beginEditingJobComments(for selectedJobs: [DownloadJob]) {
        let selectedIDs = Set(selectedJobs.map(\.id))
        let current = jobs.filter { selectedIDs.contains($0.id) }
        guard !current.isEmpty else { return }

        editingCommentJob = current[0]
        editingCommentJobIDs = current.map(\.id)
        let comments = Set(current.map { $0.comment })
        jobCommentText = comments.count == 1 ? current[0].comment : ""
    }

    func cancelEditingJobComment() {
        editingCommentJob = nil
        editingCommentJobIDs = []
        jobCommentText = ""
    }

    func saveEditingJobComment() {
        guard let job = editingCommentJob else { return }
        if editingCommentJobIDs.count > 1 {
            updateJobComments(editingCommentJobIDs, comment: jobCommentText)
        } else {
            updateJobComment(job, comment: jobCommentText)
        }
        cancelEditingJobComment()
    }

    func updateJobComment(_ job: DownloadJob, comment: String) {
        guard let index = jobs.firstIndex(where: { $0.id == job.id }) else { return }
        jobs[index].comment = comment.trimmed
        if jobs[index].status == .finished {
            scheduleRestartIfNeeded(for: jobs[index])
        } else {
            cancelScheduledRestart(for: jobs[index].id)
        }
        addSummary = jobs[index].comment.isEmpty ? "Comment cleared" : "Comment saved"
        persistQueue()
    }

    func updateJobComments(_ jobIDs: [UUID], comment: String) {
        let ids = Set(jobIDs)
        guard !ids.isEmpty else { return }

        let trimmed = comment.trimmed
        var updated = 0
        for index in jobs.indices where ids.contains(jobs[index].id) {
            jobs[index].comment = trimmed
            if jobs[index].status == .finished {
                scheduleRestartIfNeeded(for: jobs[index])
            } else {
                cancelScheduledRestart(for: jobs[index].id)
            }
            updated += 1
        }

        guard updated > 0 else { return }
        addSummary = trimmed.isEmpty ? "Comments cleared for \(updated) jobs" : "Comment saved for \(updated) jobs"
        persistQueue()
    }

    func clearHistory() {
        history.removeAll()
        userData.history = history
        persistUserData()
        addSummary = "History cleared"
    }

    func historyPlainText() -> String {
        guard !history.isEmpty else { return "No history" }
        let formatter = DateFormatter()
        formatter.dateStyle = .medium
        formatter.timeStyle = .medium
        return history.enumerated().map { index, entry in
            var lines = [
                "[\(index + 1)] \(entry.title.trimmed.isEmpty ? entry.source : entry.title)",
                "URL: \(entry.source)",
                "Output: \(entry.outputPath)",
                "Completed: \(formatter.string(from: entry.completedAt))"
            ]
            let metadata = entry.metadata
                .filter { !$0.key.trimmed.isEmpty && !$0.value.trimmed.isEmpty }
                .sorted { $0.key.localizedStandardCompare($1.key) == .orderedAscending }
            if !metadata.isEmpty {
                lines.append("Metadata:")
                lines.append(contentsOf: metadata.map { "  \($0.key): \($0.value)" })
            }
            return lines.joined(separator: "\n")
        }
        .joined(separator: "\n\n")
    }

