    func removeSearchProvider(_ provider: SearchProvider) {
        searchProviders.removeAll { $0.id == provider.id }
        if selectedSearchProviderID == provider.id {
            selectedSearchProviderID = searchProviders.first?.id ?? SearchProvider.defaultProviders[0].id
        }
        persistSearchProviders()
        addSummary = "Search provider removed"
