    func fetchSearchResults() {
        guard let url = builtSearchURL() else {
            addSummary = "Enter a search query"
            return
        }
        guard persistProxySettingsForUse() else { return }

        cancelSearchResultsFetch(announce: false)
        let requestID = UUID()
        activeSearchRequestID = requestID
        isSearching = true
        addSummary = "Searching"
        let headers = requestOptions(for: url)
        searchTask = Task { [weak self] in
            do {
                let html = try await HTTPClient.shared.string(from: url, referer: headers.referer, userAgent: headers.userAgent)
                try Task.checkCancellation()
                let links = SearchResultExtractor.extractLinks(from: html, baseURL: url)
                try Task.checkCancellation()
                guard let self, self.activeSearchRequestID == requestID else { return }
                let processed = Self.processedSearchResults(
                    links,
                    deduplicate: self.searchDeduplicateResults,
                    hideKnown: self.searchHideKnownResults,
                    knownSources: self.searchKnownSources(),
                    excludedHitomiTags: self.currentHitomiExcludedTags()
                )
                self.searchResults = processed
                self.finishSearchRequest(requestID)
                let hidden = max(0, links.count - processed.count)
                if processed.isEmpty {
                    self.addSummary = hidden > 0 ? "No new search results" : "No search results"
                } else {
                    self.addSummary = hidden > 0 ? "\(processed.count) search results, \(hidden) hidden" : "\(processed.count) search results"
                }
            } catch {
                guard let self, self.activeSearchRequestID == requestID else { return }
                self.finishSearchRequest(requestID)
                self.addSummary = Task.isCancelled || Self.isSearchCancellation(error)
                    ? "Search cancelled"
                    : "Search failed"
            }
        }
    }

    func cancelSearchResultsFetch() {
        cancelSearchResultsFetch(announce: true)
    }

    private func cancelSearchResultsFetch(announce: Bool) {
        guard searchTask != nil || activeSearchRequestID != nil || isSearching else { return }
        searchTask?.cancel()
        searchTask = nil
        activeSearchRequestID = nil
        isSearching = false
        if announce {
            addSummary = "Search cancelled"
        }
    }

    private func finishSearchRequest(_ requestID: UUID) {
        guard activeSearchRequestID == requestID else { return }
        searchTask = nil
        activeSearchRequestID = nil
        isSearching = false
    }

    private nonisolated static func isSearchCancellation(_ error: Error) -> Bool {
        if error is CancellationError { return true }
        return (error as? URLError)?.code == .cancelled
    }

    func enqueueSearchResult(_ result: SearchResultLink) {
        let newJobs = jobsForAddingSearchResults([result])
        guard !newJobs.isEmpty else { return }
        insertAddedJobsAtTop(newJobs)
        persistQueue()
    }

    nonisolated static func searchResultBrowserURL(for result: SearchResultLink) -> URL? {
        guard let url = URL(string: result.url),
              let scheme = url.scheme?.lowercased(),
              scheme == "http" || scheme == "https" else {
            return nil
        }
        return url
    }

    nonisolated static func searchResultCopyTitle(for result: SearchResultLink) -> String? {
