    }

    private nonisolated static func searchResultMetadataValue(for result: SearchResultLink, keys: [String]) -> String? {
        let normalizedKeys = keys.map { $0.lowercased() }
        let structured = normalizedKeys.compactMap { key -> String? in
            result.metadata.first { $0.key.lowercased() == key }?.value
        }
        let values = structured.isEmpty
            ? normalizedKeys.compactMap { searchResultMetadataTextValue(in: result.metadataText, key: $0) }
            : structured
        let cleaned = uniqueSearchResultMetadataValues(values.flatMap(splitSearchResultMetadataValues))
        return cleaned.isEmpty ? nil : cleaned.joined(separator: ", ")
    }

    private nonisolated static func uniqueSearchResultMetadataValues(_ values: [String]) -> [String] {
        var seen = Set<String>()
        var result: [String] = []
        for value in values {
            let cleaned = value.trimmed
            let key = cleaned.lowercased()
            guard !cleaned.isEmpty, seen.insert(key).inserted else { continue }
            result.append(cleaned)
        }
        return result
    }

    private nonisolated static func splitSearchResultMetadataValues(_ raw: String) -> [String] {
        raw.components(separatedBy: CharacterSet(charactersIn: ",;|"))
            .map { stripFilterQuotes($0.trimmed) }
            .filter { !$0.isEmpty }
    }

    private nonisolated static func searchResultMetadataTextValue(in text: String, key: String) -> String? {
        let escaped = NSRegularExpression.escapedPattern(for: key)
        let pattern = #"(?i)(?:^|\s)"# + escaped + #"\s*:\s*(.+?)(?=\s+[a-z_]+:|$)"#
        guard let regex = try? NSRegularExpression(pattern: pattern, options: []) else {
            return nil
        }
        let range = NSRange(text.startIndex..<text.endIndex, in: text)
        guard let match = regex.firstMatch(in: text, range: range),
              match.numberOfRanges > 1,
              let valueRange = Range(match.range(at: 1), in: text) else {
            return nil
        }
        let value = String(text[valueRange]).trimmed
        return value.isEmpty ? nil : value
    }

    private nonisolated static func searchResultPageCount(for result: SearchResultLink) -> Int? {
        let value = searchResultMetadataValue(
            for: result,
            keys: ["pages", "page", "page_count", "pagecount", "total_pages", "totalpages"]
        )
        if let value {
            for candidate in splitSearchResultMetadataValues(value) {
                if let count = queueFilterInteger(from: candidate) {
                    return count
                }
            }
        }

        let pattern = #"(?i)\b([1-9][0-9]{0,4})\s*(?:pages?|p\.)\b"#
        guard let regex = try? NSRegularExpression(pattern: pattern, options: []) else { return nil }
        let text = result.metadataText
        let range = NSRange(text.startIndex..<text.endIndex, in: text)
        guard let match = regex.firstMatch(in: text, range: range),
              let valueRange = Range(match.range(at: 1), in: text) else {
            return nil
        }
        return queueFilterInteger(from: String(text[valueRange]))
    }

    func enqueueAllSearchResults() {
        let newJobs = jobsForAddingSearchResults(filteredSearchResults)
        guard !newJobs.isEmpty else { return }
        insertAddedJobsAtTop(newJobs)
        persistQueue()
    }

    nonisolated static func filteredSearchResults(
        _ results: [SearchResultLink],
        filter: String,
        knownSources: Set<String>
    ) -> [SearchResultLink] {
        guard let expression = searchResultFilterExpression(from: filter) else { return results }
        return results.filter { result in
            searchResultFilterExpression(expression, matches: result, knownSources: knownSources)
        }
    }

    nonisolated static func filteredSearchResults(
        _ results: [SearchResultLink],
        knownFilter: SearchResultKnownFilter,
        knownSources: Set<String>
    ) -> [SearchResultLink] {
        switch knownFilter {
        case .all:
            return results
        case .notDownloaded:
            return results.filter { !knownSources.contains(searchResultKey($0.url)) }
        case .downloaded:
            return results.filter { knownSources.contains(searchResultKey($0.url)) }
        }
    }

    nonisolated static func processedSearchResults(
        _ results: [SearchResultLink],
        deduplicate: Bool,
        hideKnown: Bool,
        knownSources: Set<String>,
        excludedHitomiTags: [String] = []
    ) -> [SearchResultLink] {
        let excludedTags = excludedHitomiTags.map(normalizedHitomiTag).filter { !$0.isEmpty }
        var seen = Set<String>()
        var processed: [SearchResultLink] = []
        for result in results {
            let key = searchResultKey(result.url)
            guard !hideKnown || !knownSources.contains(key) else { continue }
            guard !matchesHitomiExcludedTags(result, excludedTags: excludedTags) else { continue }
            if deduplicate {
                guard seen.insert(key).inserted else { continue }
            }
            processed.append(result)
        }
        return processed
    }

    private nonisolated static func searchResultFilterReferencesKnownSources(_ filter: String) -> Bool {
        guard let expression = searchResultFilterExpression(from: filter) else { return false }
        return searchResultFilterExpressionReferencesKnownSources(expression)
    }

    private struct SearchResultFilterToken {
        var field: String?
        var value: String
        var isNegated: Bool
    }

    private indirect enum SearchResultFilterExpression {
        case token(SearchResultFilterToken)
        case and([SearchResultFilterExpression])
        case or([SearchResultFilterExpression])
        case not(SearchResultFilterExpression)
    }

    private struct SearchResultFilterParser {
        var lexemes: [QueueFilterLexeme]
        var index = 0

        mutating func parse() -> SearchResultFilterExpression? {
            parseOr()
        }

        private mutating func parseOr() -> SearchResultFilterExpression? {
            guard var expression = parseAnd() else { return nil }
            var expressions = [expression]
            while consume(.or) {
                if let next = parseAnd() {
                    expressions.append(next)
                }
            }
            if expressions.count > 1 {
                expression = .or(expressions)
            }
            return expression
        }

        private mutating func parseAnd() -> SearchResultFilterExpression? {
            guard let first = parseNot() else { return nil }
            var expressions = [first]
            while true {
                if consume(.and) {
                    if let next = parseNot() {
                        expressions.append(next)
                    }
                    continue
                }
                guard startsPrimary(peek()) else { break }
                if let next = parseNot() {
                    expressions.append(next)
                } else {
                    break
                }
            }
            return expressions.count == 1 ? first : .and(expressions)
        }

        private mutating func parseNot() -> SearchResultFilterExpression? {
            if consume(.not), let expression = parseNot() {
                return .not(expression)
            }
            return parsePrimary()
        }

        private mutating func parsePrimary() -> SearchResultFilterExpression? {
            guard let lexeme = peek() else { return nil }
            switch lexeme {
            case .term(let piece):
                index += 1
                return DownloadManager.searchResultFilterToken(from: piece).map(SearchResultFilterExpression.token)
            case .openGroup:
                index += 1
                let expression = parseOr()
                _ = consume(.closeGroup)
                return expression
            default:
                return nil
            }
        }

        private func peek() -> QueueFilterLexeme? {
            lexemes.indices.contains(index) ? lexemes[index] : nil
        }

        private mutating func consume(_ lexeme: QueueFilterLexeme) -> Bool {
            guard peek() == lexeme else { return false }
            index += 1
            return true
        }

        private func startsPrimary(_ lexeme: QueueFilterLexeme?) -> Bool {
            switch lexeme {
            case .term, .not, .openGroup:
                return true
            default:
                return false
            }
        }
    }

    private nonisolated static func searchResultFilterTokens(from query: String) -> [SearchResultFilterToken] {
        queueFilterPieces(from: query).compactMap(searchResultFilterToken)
    }

    private nonisolated static func searchResultFilterExpression(from query: String) -> SearchResultFilterExpression? {
        let lexemes = queueFilterLexemes(from: query)
        guard !lexemes.isEmpty else { return nil }
        var parser = SearchResultFilterParser(lexemes: lexemes)
        return parser.parse()
    }

    private nonisolated static func searchResultFilterExpression(
        _ expression: SearchResultFilterExpression,
        matches result: SearchResultLink,
        knownSources: Set<String>
    ) -> Bool {
        switch expression {
        case .token(let token):
            return searchResultFilterToken(token, matches: result, knownSources: knownSources)
        case .and(let expressions):
            return expressions.allSatisfy { searchResultFilterExpression($0, matches: result, knownSources: knownSources) }
        case .or(let expressions):
            return expressions.contains { searchResultFilterExpression($0, matches: result, knownSources: knownSources) }
        case .not(let expression):
            return !searchResultFilterExpression(expression, matches: result, knownSources: knownSources)
        }
    }

    private nonisolated static func searchResultFilterExpressionReferencesKnownSources(_ expression: SearchResultFilterExpression) -> Bool {
        switch expression {
        case .token(let token):
            let field = token.field ?? ""
            return ["done", "complete", "completed", "known", "downloaded"].contains(field)
        case .and(let expressions), .or(let expressions):
            return expressions.contains(where: searchResultFilterExpressionReferencesKnownSources)
        case .not(let expression):
            return searchResultFilterExpressionReferencesKnownSources(expression)
        }
    }

    private nonisolated static func searchResultFilterToken(from piece: String) -> SearchResultFilterToken? {
        var value = piece.trimmed
        guard !value.isEmpty else { return nil }

        var isNegated = false
        while value.hasPrefix("-") {
            isNegated = true
            value.removeFirst()
            value = value.trimmed
        }
        guard !value.isEmpty else { return nil }

        if let comparison = searchResultPageComparisonToken(from: value, isNegated: isNegated) {
            return comparison
        }

        if let separator = value.firstIndex(of: ":") {
            let field = String(value[..<separator]).trimmed.lowercased()
            let fieldValue = stripFilterQuotes(String(value[value.index(after: separator)...]).trimmed)
            guard !field.isEmpty, !fieldValue.isEmpty || searchResultFilterAllowsEmptyValue(for: field) else { return nil }
            return SearchResultFilterToken(field: field, value: fieldValue.lowercased(), isNegated: isNegated)
        }

        return SearchResultFilterToken(field: nil, value: stripFilterQuotes(value).lowercased(), isNegated: isNegated)
    }

    private nonisolated static func searchResultPageComparisonToken(from value: String, isNegated: Bool) -> SearchResultFilterToken? {
        guard let regex = try? NSRegularExpression(
            pattern: #"^(pages?|page_count|pagecount|total_pages|totalpages)\s*(<=|>=|<|>)\s*(.+)$"#,
            options: [.caseInsensitive]
        ) else {
            return nil
        }
        let range = NSRange(value.startIndex..<value.endIndex, in: value)
        guard let result = regex.firstMatch(in: value, range: range),
              result.numberOfRanges == 4,
              let opRange = Range(result.range(at: 2), in: value),
              let valueRange = Range(result.range(at: 3), in: value) else {
            return nil
        }
        let op = String(value[opRange])
        let threshold = stripFilterQuotes(String(value[valueRange]).trimmed)
        guard !threshold.isEmpty else { return nil }
        return SearchResultFilterToken(field: "pages\(op)", value: threshold.lowercased(), isNegated: isNegated)
    }

    private nonisolated static func searchResultFilterAllowsEmptyValue(for field: String) -> Bool {
        ["done", "complete", "completed", "known", "downloaded"].contains(field)
    }

    private nonisolated static func searchResultFilterToken(
        _ token: SearchResultFilterToken,
        matches result: SearchResultLink,
        knownSources: Set<String>
    ) -> Bool {
        let value = token.value
        let matched: Bool
        if value.isEmpty {
            switch token.field {
            case "done", "complete", "completed", "known", "downloaded":
                matched = searchResultFilterDone(result, knownSources: knownSources, matches: "true")
            default:
                matched = true
            }
        } else {
            switch token.field {
            case nil:
                matched = searchResultFilterHaystack(for: result).contains(value)
            case "done", "complete", "completed", "known", "downloaded":
                matched = searchResultFilterDone(result, knownSources: knownSources, matches: value)
            case "title", "name":
                matched = result.title.lowercased().contains(value)
            case "url", "source", "src":
                matched = result.url.lowercased().contains(value)
            case "site", "host", "domain":
                matched = searchResultFilterHost(for: result).contains(value)
            case "meta", "metadata":
                matched = searchResultMetadataHaystack(for: result).contains(value)
            case "tag", "tags":
                matched = (searchResultMetadataValue(for: result, keys: ["tag", "tags"]) ?? result.metadataText).lowercased().contains(value)
            case "date", "published", "posted", "created", "uploaded":
                matched = (searchResultDateText(for: result) ?? result.metadataText).lowercased().contains(value)
            case "page", "pages", "page_count", "pagecount", "total_pages", "totalpages":
                matched = searchResultFilterPageCount(result, matches: value)
            case "pages<":
                matched = searchResultFilterPageCount(result, comparison: .lessThan, threshold: value)
            case "pages<=":
                matched = searchResultFilterPageCount(result, comparison: .lessThanOrEqual, threshold: value)
            case "pages>":
                matched = searchResultFilterPageCount(result, comparison: .greaterThan, threshold: value)
            case "pages>=":
                matched = searchResultFilterPageCount(result, comparison: .greaterThanOrEqual, threshold: value)
            default:
                if let field = token.field,
                   let metadataMatched = searchResultMetadataFieldMatches(result, field: field, value: value) {
                    matched = metadataMatched
                } else if let field = token.field {
                    matched = searchResultFilterHaystack(for: result).contains("\(field):\(value)")
                } else {
                    matched = searchResultFilterHaystack(for: result).contains(value)
                }
            }
        }
        return token.isNegated ? !matched : matched
    }

    private nonisolated static func searchResultFilterDone(
        _ result: SearchResultLink,
        knownSources: Set<String>,
        matches value: String
    ) -> Bool {
        let isKnown = knownSources.contains(searchResultKey(result.url))
        return queueFilterBool(isKnown, matches: value)
    }

    private nonisolated static func searchResultFilterPageCount(
        _ result: SearchResultLink,
        comparison: QueueFilterComparison,
        threshold: String
    ) -> Bool {
        guard let count = searchResultPageCount(for: result),
              let threshold = queueFilterInteger(from: threshold) else {
            return false
        }
        switch comparison {
        case .lessThan:
            return count < threshold
        case .lessThanOrEqual:
            return count <= threshold
        case .greaterThan:
            return count > threshold
        case .greaterThanOrEqual:
            return count >= threshold
        }
    }

    private nonisolated static func searchResultFilterPageCount(
        _ result: SearchResultLink,
        matches value: String
    ) -> Bool {
        let trimmed = value.trimmed
        if let comparison = queueFilterInlineComparison(from: trimmed) {
            return searchResultFilterPageCount(result, comparison: comparison.comparison, threshold: comparison.threshold)
        }
        guard let count = searchResultPageCount(for: result),
              let expected = queueFilterInteger(from: trimmed) else {
            return false
        }
        return count == expected
    }

    private nonisolated static func searchResultFilterHaystack(for result: SearchResultLink) -> String {
        [
            result.title,
            result.url,
            result.siteIdentifier ?? "",
            searchResultFilterHost(for: result),
            result.metadataText,
            result.metadata
                .flatMap { [$0.key, $0.value] }
                .joined(separator: " ")
        ].joined(separator: " ").lowercased()
    }

    private nonisolated static func searchResultMetadataHaystack(for result: SearchResultLink) -> String {
        [
            result.metadataText,
            result.metadata
                .flatMap { [$0.key, $0.value] }
                .joined(separator: " ")
        ].joined(separator: " ").lowercased()
    }

    private nonisolated static func searchResultMetadataFieldMatches(
        _ result: SearchResultLink,
        field: String,
        value: String
    ) -> Bool? {
        let normalizedField = normalizedSearchResultMetadataKey(field)
        guard !normalizedField.isEmpty else { return nil }

        var values = result.metadata.compactMap { key, metadataValue -> String? in
            let lowercasedKey = key.lowercased()
            guard lowercasedKey == field || normalizedSearchResultMetadataKey(key) == normalizedField else {
                return nil
            }
            return metadataValue
        }
        if values.isEmpty,
           let textValue = searchResultMetadataTextValue(in: result.metadataText, key: field) {
            values.append(textValue)
        }
        guard !values.isEmpty else { return nil }

        return values
            .flatMap(splitSearchResultMetadataValues)
            .joined(separator: " ")
            .lowercased()
            .contains(value)
    }

    private nonisolated static func normalizedSearchResultMetadataKey(_ value: String) -> String {
        value.lowercased().filter { $0.isLetter || $0.isNumber }
    }

    private nonisolated static func searchResultFilterHost(for result: SearchResultLink) -> String {
        if let host = URL(string: result.url)?.host?.lowercased() {
            return host.hasPrefix("www.") ? String(host.dropFirst(4)) : host
        }
        return ""
    }

    nonisolated static func hitomiExcludedTags(from text: String) -> [String] {
        var seen = Set<String>()
        var tags: [String] = []
        for raw in text.components(separatedBy: CharacterSet(charactersIn: ",;\n\r")) {
            let tag = normalizedHitomiTag(raw.trimmingCharacters(in: CharacterSet(charactersIn: "# ")))
            guard !tag.isEmpty, seen.insert(tag).inserted else { continue }
            tags.append(tag)
        }
        return tags
    }

    private nonisolated static func matchesHitomiExcludedTags(_ result: SearchResultLink, excludedTags: [String]) -> Bool {
        guard !excludedTags.isEmpty, isHitomiSearchResult(result) else { return false }
        let text = normalizedHitomiTag([result.title, result.url, result.metadataText].joined(separator: " "))
        return excludedTags.contains { text.contains($0) }
    }

    private nonisolated static func isHitomiSearchResult(_ result: SearchResultLink) -> Bool {
        if result.siteIdentifier?.lowercased() == "hitomi" {
            return true
        }
        guard let host = URL(string: result.url)?.host?.lowercased() else { return false }
        return host == "hitomi.la" || host.hasSuffix(".hitomi.la")
    }

    private nonisolated static func normalizedHitomiTag(_ value: String) -> String {
        value
            .folding(options: [.caseInsensitive, .diacriticInsensitive], locale: Locale(identifier: "en_US_POSIX"))
            .replacingOccurrences(of: "_", with: " ")
            .replacingOccurrences(of: "-", with: " ")
            .replacingOccurrences(of: "\\s*:\\s*", with: ":", options: .regularExpression)
            .replacingOccurrences(of: "\\s+", with: " ", options: .regularExpression)
            .trimmed
    }

    private func currentHitomiExcludedTags() -> [String] {
        Self.hitomiExcludedTags(from: hitomiExcludedTagsText)
    }

    private func currentHitomiAdvancedSearchQuery() -> String {
        Self.hitomiAdvancedSearchQuery(
            title: hitomiAdvancedTitle,
            artist: hitomiAdvancedArtist,
            group: hitomiAdvancedGroup,
            series: hitomiAdvancedSeries,
            character: hitomiAdvancedCharacter,
            tag: hitomiAdvancedTag,
            language: hitomiAdvancedLanguage,
            types: hitomiAdvancedTypes,
            languagePreset: hitomiAdvancedLanguagePreset,
            excludeWebtoon: hitomiAdvancedExcludeWebtoon
        )
    }

    nonisolated static func hitomiAdvancedSearchQuery(
        title: String,
        artist: String,
        group: String,
        series: String,
        character: String,
        tag: String,
        language: String,
        types: Set<HitomiAdvancedSearchType>,
        languagePreset: HitomiAdvancedLanguagePreset = .all,
        excludeWebtoon: Bool = false
    ) -> String {
        var tokens: [String] = []

        if let token = hitomiAdvancedSearchFieldToken(prefix: "title", value: title) {
            tokens.append(token)
        }
        if let token = hitomiAdvancedSearchFieldToken(prefix: "artist", value: artist) {
            tokens.append(token)
        }
        if let token = hitomiAdvancedSearchFieldToken(prefix: "group", value: group) {
            tokens.append(token)
        }
        if let token = hitomiAdvancedSearchFieldToken(prefix: "parody", value: series) {
            tokens.append(token)
        }
        if let token = hitomiAdvancedSearchFieldToken(prefix: "character", value: character) {
            tokens.append(token)
        }

        let translatedTags = translatedSearchQueryTags(from: tag)
        if !translatedTags.isEmpty {
            tokens.append(translatedTags)
        }

        if let token = hitomiAdvancedLanguageToken(from: language) {
            tokens.append(token)
        }

        tokens.append(contentsOf: languagePreset.queryTokens)

        if excludeWebtoon {
            tokens.append("-webtoon")
        }

        for type in HitomiAdvancedSearchType.allCases where types.contains(type) {
            tokens.append(type.queryToken)
        }

        return tokens.joined(separator: " ")
    }

    nonisolated static func translatedSearchQueryTags(from text: String) -> String {
        searchTagTranslationPieces(from: text)
            .compactMap(translatedSearchTagToken)
            .joined(separator: " ")
    }

    nonisolated static func searchTagSuggestions(for text: String, limit: Int = 8) -> [SearchTagSuggestion] {
        let fragment = activeSearchTagCompletionFragment(from: text)
        guard !fragment.isEmpty else {
            return Array(searchTagSuggestionCatalog.prefix(limit))
        }

        let query = searchTagTranslationKey(fragment)
        if let separator = fragment.firstIndex(where: { $0 == ":" || $0 == "：" }) {
            let rawPrefix = String(fragment[..<separator])
            let rawValue = String(fragment[fragment.index(after: separator)...])
            let prefix = searchTagPrefixTranslations[searchTagTranslationKey(rawPrefix)] ?? hitomiQueryValue(rawPrefix)
            let valueQuery = searchTagTranslationKey(rawValue)
            let genderValues = ["maid", "school uniform", "swimsuit", "glasses"]

            if prefix == "male" || prefix == "female" {
                return genderValues
                    .map { SearchTagSuggestion(title: "\($0) (\(prefix))", token: "\(prefix):\($0)", detail: prefix) }
                    .filter { valueQuery.isEmpty || searchTagSuggestionMatches($0, query: valueQuery) }
                    .prefix(limit)
                    .map { $0 }
            }

            if freeTextSearchTagPrefixes.contains(prefix) {
                let normalizedValue = hitomiQueryValue(rawValue)
                let directSuggestion = normalizedValue.isEmpty ? [] : [
                    SearchTagSuggestion(
                        title: "\(prefix):\(normalizedValue)",
                        token: "\(prefix):\(normalizedValue)",
                        detail: prefix
                    )
                ]
                let catalogSuggestions = searchTagSuggestionCatalog(forPrefix: prefix).map { suggestion in
                    let value = suggestion.token.split(separator: ":", maxSplits: 1).last.map(String.init) ?? suggestion.token
                    return SearchTagSuggestion(title: suggestion.title, token: "\(prefix):\(value)", detail: prefix)
                }
                let matchingSuggestions = (directSuggestion + catalogSuggestions)
                    .filter { valueQuery.isEmpty || searchTagSuggestionMatches($0, query: valueQuery) }
                let suggestions = uniqueSearchTagSuggestions(matchingSuggestions)
                return suggestions
                    .prefix(limit)
                    .map { $0 }
            }

            return searchTagSuggestionCatalog(forPrefix: prefix)
                .map { suggestion in
                    let value = suggestion.token.split(separator: ":", maxSplits: 1).last.map(String.init) ?? suggestion.token
                    return SearchTagSuggestion(title: suggestion.title, token: "\(prefix):\(value)", detail: prefix)
                }
                .filter { valueQuery.isEmpty || searchTagSuggestionMatches($0, query: valueQuery) }
                .prefix(limit)
                .map { $0 }
        }

        return searchTagSuggestionCatalog
            .filter { searchTagSuggestionMatches($0, query: query) }
            .prefix(limit)
            .map { $0 }
    }

    nonisolated static func translatedSearchTagToken(_ raw: String) -> String? {
        var token = raw.trimmed.trimmingCharacters(in: CharacterSet(charactersIn: "#"))
        guard !token.isEmpty else { return nil }

        var isExcluded = false
        if token.hasPrefix("-") || token.hasPrefix("!") {
            isExcluded = true
            token.removeFirst()
            token = token.trimmed
        }

        let translated: String?
        if let separator = token.firstIndex(where: { $0 == ":" || $0 == "：" }) {
            let prefix = String(token[..<separator])
            let valueStart = token.index(after: separator)
            let value = String(token[valueStart...])
            translated = translatedSearchTag(prefix: prefix, value: value)
        } else {
            translated = translatedSearchTagValue(token)
        }

        guard let translated, !translated.isEmpty else { return nil }
        return isExcluded ? "-\(translated)" : translated
    }

    private nonisolated static func translatedSearchTag(prefix rawPrefix: String, value rawValue: String) -> String? {
        let prefix = searchTagPrefixTranslations[searchTagTranslationKey(rawPrefix)] ?? hitomiQueryValue(rawPrefix)
        guard !prefix.isEmpty else { return nil }
        let value = translatedSearchTagValue(rawValue, forPrefix: prefix) ?? hitomiQueryValue(rawValue)
        guard !value.isEmpty else { return nil }
        return "\(prefix):\(value)"
    }

    private nonisolated static func translatedSearchTagValue(_ raw: String, forPrefix prefix: String) -> String? {
        guard let mapped = translatedSearchTagValue(raw) else { return nil }
        guard let separator = mapped.firstIndex(of: ":") else { return mapped }
        let mappedPrefix = String(mapped[..<separator])
        let valueStart = mapped.index(after: separator)
        if mappedPrefix == prefix {
            return String(mapped[valueStart...])
        }
        return containsHangul(raw) ? nil : hitomiQueryValue(raw)
    }

    private nonisolated static func translatedSearchTagValue(_ raw: String) -> String? {
        let cleaned = raw.trimmed.trimmingCharacters(in: CharacterSet(charactersIn: "#"))
        guard !cleaned.isEmpty else { return nil }
        let key = searchTagTranslationKey(cleaned)
        if let mapped = searchTagValueTranslations[key] {
            return mapped
        }
        if containsHangul(cleaned) {
            return nil
        }
        return hitomiQueryValue(cleaned)
    }

    private nonisolated static func searchTagTranslationPieces(from text: String) -> [String] {
        var pieces: [String] = []
        for rawChunk in text.components(separatedBy: CharacterSet(charactersIn: ",;\n\r")) {
            let chunk = rawChunk.trimmed
            guard !chunk.isEmpty else { continue }
            if translatedSearchTagToken(chunk) != nil || chunk.contains(":") || chunk.contains("：") {
                pieces.append(chunk)
                continue
            }
            let words = chunk.components(separatedBy: .whitespacesAndNewlines).map(\.trimmed).filter { !$0.isEmpty }
            if words.count > 1 {
                pieces.append(contentsOf: words)
            } else {
                pieces.append(chunk)
            }
        }
        return pieces
    }

    private nonisolated static func activeSearchTagCompletionFragment(from text: String) -> String {
        let separators = CharacterSet(charactersIn: ",;\n\r")
        let fragments = text.components(separatedBy: separators)
        return (fragments.last ?? text).trimmed
    }

    private nonisolated static func searchTagSuggestionMatches(_ suggestion: SearchTagSuggestion, query: String) -> Bool {
        guard !query.isEmpty else { return true }
        return [suggestion.title, suggestion.token, suggestion.detail]
            .map(searchTagTranslationKey)
            .contains { $0.contains(query) }
    }

    private nonisolated static func searchTagSuggestionCatalog(forPrefix prefix: String) -> [SearchTagSuggestion] {
        switch prefix {
        case "language":
            return searchTagSuggestionCatalog.filter { $0.detail == "language" }
        case "type":
            return searchTagSuggestionCatalog.filter { $0.detail == "type" }
        case "tag":
            return searchTagSuggestionCatalog.filter { $0.detail == "tag" }
        default:
            return searchTagSuggestionCatalog.filter { $0.detail != "prefix" }
        }
    }

    private nonisolated static func uniqueSearchTagSuggestions(_ suggestions: [SearchTagSuggestion]) -> [SearchTagSuggestion] {
        var seen = Set<String>()
        var output: [SearchTagSuggestion] = []
        for suggestion in suggestions {
            let key = searchTagTranslationKey(suggestion.token)
            guard seen.insert(key).inserted else { continue }
            output.append(suggestion)
        }
        return output
    }

    private nonisolated static func appendingSearchQueryToken(_ token: String, to query: String) -> String {
        let base = query.trimmed
        return base.isEmpty ? token : "\(base) \(token)"
    }

    private nonisolated static func hitomiAdvancedSearchFieldToken(prefix: String, value: String) -> String? {
        let normalized = hitomiQueryValue(value)
        guard !normalized.isEmpty else { return nil }
        return "\(prefix):\(normalized)"
    }

    private nonisolated static func hitomiAdvancedLanguageToken(from language: String) -> String? {
        let value = language.trimmed
        guard !value.isEmpty else { return nil }

        if value.contains(":") || value.contains("："),
           let token = translatedSearchTagToken(value),
           token.hasPrefix("language:") {
            return token
        }

        if let token = translatedSearchTagToken("language:\(value)"),
           token.hasPrefix("language:") {
            return token
        }

        if let token = translatedSearchTagToken(value),
           token.hasPrefix("language:") {
            return token
        }

        let normalized = hitomiQueryValue(value)
        return normalized.isEmpty ? nil : "language:\(normalized)"
    }

    private func currentTranslatedSearchTag() -> String {
        if !searchTagTranslationOutput.trimmed.isEmpty {
            return searchTagTranslationOutput.trimmed
        }
        return Self.translatedSearchQueryTags(from: searchTagTranslationInput)
    }

    private nonisolated static func hitomiQueryValue(_ raw: String) -> String {
        raw
            .trimmed
            .trimmingCharacters(in: CharacterSet(charactersIn: "#"))
            .folding(options: [.caseInsensitive, .diacriticInsensitive], locale: Locale(identifier: "en_US_POSIX"))
            .replacingOccurrences(of: "_", with: " ")
            .replacingOccurrences(of: "-", with: " ")
            .replacingOccurrences(of: "\\s+", with: " ", options: .regularExpression)
            .trimmed
    }

    private nonisolated static func searchTagTranslationKey(_ raw: String) -> String {
        hitomiQueryValue(raw)
            .replacingOccurrences(of: " ", with: "")
    }

    private nonisolated static func containsHangul(_ text: String) -> Bool {
        text.unicodeScalars.contains { scalar in
            (0xAC00...0xD7AF).contains(Int(scalar.value)) ||
                (0x1100...0x11FF).contains(Int(scalar.value)) ||
                (0x3130...0x318F).contains(Int(scalar.value))
        }
    }

