    private func searchKnownSources() -> Set<String> {
        searchResultKnownState.sources
    }

    nonisolated static func searchKnownSources(
        jobs: [DownloadJob],
        history: [DownloadHistoryEntry],
        destinationPath: String,
        fileManager: FileManager = .default
    ) -> Set<String> {
        searchResultKnownState(
            jobs: jobs,
            history: history,
            destinationPath: destinationPath,
            fileManager: fileManager
        ).sources
    }

    nonisolated static func searchResultKnownState(
        jobs: [DownloadJob],
        history: [DownloadHistoryEntry],
        destinationPath: String,
        fileManager: FileManager = .default
    ) -> SearchResultKnownState {
        let outputPaths = searchKnownOutputPaths(
            jobs: jobs,
            history: history,
            destinationPath: destinationPath,
            fileManager: fileManager
        )
        var sources = Set(outputPaths.keys)
        for job in jobs {
            sources.formUnion(searchKnownSourceKeys(for: job.source))
        }
        for entry in history {
            sources.formUnion(searchKnownSourceKeys(for: entry.source))
        }
        return SearchResultKnownState(sources: sources, outputPaths: outputPaths)
    }

    nonisolated static func searchResultIsKnown(
        _ result: SearchResultLink,
        knownState: SearchResultKnownState
    ) -> Bool {
        knownState.sources.contains(searchResultKey(result.url))
    }

    nonisolated static func searchResultFirstOutputOpenURL(
        for result: SearchResultLink,
        knownState: SearchResultKnownState,
        fileManager: FileManager = .default
    ) -> URL? {
        guard let outputPath = knownState.outputPaths[searchResultKey(result.url)] else {
            return nil
        }
        return firstOutputOpenURL(forOutputPath: outputPath, fileManager: fileManager)
    }

    func openFirstOutputFile(forSearchResult result: SearchResultLink) {
        guard let url = Self.searchResultFirstOutputOpenURL(
            for: result,
            knownState: searchResultKnownState
        ) else {
            addSummary = "No output file found"
            return
        }
        NSWorkspace.shared.open(url)
    }

    nonisolated static func searchResultGalleryID(for result: SearchResultLink) -> String? {
        guard let url = URL(string: result.url),
              let host = url.host?.lowercased(),
              host == "hitomi.la" || host == "www.hitomi.la" else {
            return nil
        }
        return HitomiResolver.galleryID(from: url)
    }

    func copySearchResultGalleryID(_ result: SearchResultLink) {
        guard let galleryID = Self.searchResultGalleryID(for: result) else {
            addSummary = "No gallery ID"
            return
        }
        let pasteboard = NSPasteboard.general
        pasteboard.clearContents()
        addSummary = pasteboard.setString(galleryID, forType: .string) ? "Gallery ID copied" : "Copy failed"
    }

    private nonisolated static func searchKnownOutputPaths(
        jobs: [DownloadJob],
        history: [DownloadHistoryEntry],
        destinationPath: String,
        fileManager: FileManager
    ) -> [String: String] {
        var outputPaths: [String: String] = [:]
        for job in jobs where !job.outputPath.trimmed.isEmpty {
            addSearchKnownOutputPath(job.outputPath, source: job.source, to: &outputPaths)
        }
        for entry in history where !entry.outputPath.trimmed.isEmpty {
            addSearchKnownOutputPath(entry.outputPath, source: entry.source, to: &outputPaths)
        }

        let rootPath = destinationPath.trimmed
        if !rootPath.isEmpty {
            let root = URL(fileURLWithPath: rootPath, isDirectory: true)
            addHitomiSearchKnownOutputPaths(in: root, to: &outputPaths, fileManager: fileManager)
        }
        return outputPaths
    }

    private nonisolated static func addSearchKnownOutputPath(
        _ outputPath: String,
        source: String,
        to outputPaths: inout [String: String]
    ) {
        for key in searchKnownSourceKeys(for: source) where outputPaths[key] == nil {
            outputPaths[key] = outputPath
        }
    }

    private nonisolated static func addHitomiSearchKnownOutputPaths(
        in root: URL,
        to outputPaths: inout [String: String],
        fileManager: FileManager
    ) {
        var isDirectory = ObjCBool(false)
        guard fileManager.fileExists(atPath: root.path, isDirectory: &isDirectory) else {
            return
        }

        func record(_ ids: [String], output: URL) {
            for id in ids {
                for key in hitomiSearchResultKeys(forGalleryID: id) where outputPaths[key] == nil {
                    outputPaths[key] = output.path
                }
            }
        }

        if !isDirectory.boolValue {
            record(hitomiGalleryNumbers(fromOutputFile: root), output: root)
            return
        }

        record(hitomiGalleryNumbers(fromOutputName: root.lastPathComponent), output: root)
        let resourceKeys: [URLResourceKey] = [.isDirectoryKey, .isRegularFileKey]
        guard let enumerator = fileManager.enumerator(
            at: root,
            includingPropertiesForKeys: resourceKeys,
            options: [.skipsHiddenFiles, .skipsPackageDescendants],
            errorHandler: { _, _ in true }
        ) else {
            return
        }

        for case let url as URL in enumerator {
            guard let values = try? url.resourceValues(forKeys: Set(resourceKeys)) else { continue }
            if values.isDirectory == true {
                record(hitomiGalleryNumbers(fromOutputName: url.lastPathComponent), output: url)
            } else if values.isRegularFile == true {
                let ids = hitomiGalleryNumbers(fromOutputFile: url)
                let lowerName = url.lastPathComponent.lowercased()
                let output = hitomiGalleryInfoFilenames.contains(lowerName) ? url.deletingLastPathComponent() : url
                record(ids, output: output)
            }
        }
    }

    private nonisolated static func searchKnownSourceKeys(for source: String) -> Set<String> {
        var keys = Set([searchResultKey(source)])
        guard let url = URL(string: source),
              let host = url.host?.lowercased(),
              host == "hitomi.la" || host == "www.hitomi.la",
              let id = HitomiResolver.galleryID(from: url) else {
            return keys
        }
        keys.formUnion(hitomiSearchResultKeys(forGalleryID: id))
        return keys
    }

    nonisolated static func hitomiSearchResultKeys(forGalleryID id: String) -> Set<String> {
        let value = id.trimmed
        guard value.range(of: #"^[0-9]+$"#, options: .regularExpression) != nil else {
            return []
        }
        return Set([
            "https://hitomi.la/reader/\(value).html",
            "https://hitomi.la/reader/\(value)",
            "https://hitomi.la/galleries/\(value).html",
            "https://hitomi.la/galleries/\(value)",
            "https://hitomi.la/g/\(value)",
            "https://hitomi.la/lofi/\(value).html",
            "https://hitomi.la/lofi/\(value)",
            "https://hitomi.la/mpv/\(value)",
            "https://hitomi.la/mpv/\(value).html",
            "https://hitomi.la/galleryblock/\(value)"
        ].map(searchResultKey))
    }

    private nonisolated static func searchResultKey(_ value: String) -> String {
        URLIdentity.normalize(value)
    }

    @discardableResult
    func clearFinished() -> Int {
        guard !isRunning else {
            addSummary = "Stop queue before clearing finished jobs"
            return 0
        }

        let before = jobs.count
        jobs
            .filter(isRemovableFinishedJob)
            .forEach { cancelScheduledRestart(for: $0.id) }
        jobs.removeAll(where: isRemovableFinishedJob)
        let removed = before - jobs.count
        addSummary = removed == 0 ? "No removable finished jobs" : "\(removed) finished jobs cleared"
        persistQueue()
        return removed
    }

    func setSelectedJobIDs(_ ids: Set<UUID>) {
        let validIDs = Set(jobs.lazy.filter { !Self.isPendingQueueRemoval($0) }.map(\.id))
        selectedJobIDs = ids.intersection(validIDs)
    }

    var canSelectRandomVisibleJob: Bool {
        let visibleJobs = filteredJobs
        guard !visibleJobs.isEmpty else { return false }
        guard let currentID = visibleJobs.first(where: { selectedJobIDs.contains($0.id) })?.id else {
            return true
        }
        return visibleJobs.contains { $0.id != currentID }
    }

    func selectRandomVisibleJob(randomIndex: ((Int) -> Int)? = nil) {
        let visibleJobs = filteredJobs
        let currentID = visibleJobs.first(where: { selectedJobIDs.contains($0.id) })?.id
        let candidates = visibleJobs.filter { $0.id != currentID }
        guard !candidates.isEmpty else {
            addSummary = "No other visible jobs"
            return
        }

        let proposedIndex = randomIndex?(candidates.count) ?? Int.random(in: candidates.indices)
        let index = min(max(0, proposedIndex), candidates.count - 1)
        let selected = candidates[index]
        setSelectedJobIDs([selected.id])
        addSummary = "Selected \(selected.title.isEmpty ? selected.source : selected.title)"
    }

