    func setQueueViewMode(_ mode: QueueViewMode) {
        guard queueViewMode != mode else { return }
        let selectionToRestore = selectedJobIDs
        queueViewMode = mode
        UserDefaults.standard.set(mode.rawValue, forKey: "queueViewMode")
        addSummary = "Queue view: \(mode.label.lowercased())"
        guard !selectionToRestore.isEmpty else { return }
        Task { @MainActor [weak self] in
            await Task.yield()
            await Task.yield()
            guard let self,
                  self.queueViewMode == mode,
                  self.selectedJobIDs.isEmpty else {
                return
            }
            self.setSelectedJobIDs(selectionToRestore)
        }
    }

