    func setQuickAccessCommand(_ command: QuickAccessCommand, enabled: Bool) {
        guard let index = quickAccessItems.firstIndex(where: { $0.command == command }),
              quickAccessItems[index].isEnabled != enabled else {
            return
        }
        quickAccessItems[index].isEnabled = enabled
        QuickAccessConfiguration.save(quickAccessItems)
