    func toggleAllQuickAccessCommands() {
        let enabled = !areAllQuickAccessCommandsEnabled
        quickAccessItems = quickAccessItems.map {
            QuickAccessItem(command: $0.command, isEnabled: enabled)
        }
        QuickAccessConfiguration.save(quickAccessItems)
    }

    func moveQuickAccessCommand(_ command: QuickAccessCommand, relativeTo target: QuickAccessCommand) {
        guard command != target,
              let sourceIndex = quickAccessItems.firstIndex(where: { $0.command == command }),
              let targetIndex = quickAccessItems.firstIndex(where: { $0.command == target }) else {
            return
        }
        let item = quickAccessItems.remove(at: sourceIndex)
        quickAccessItems.insert(item, at: min(targetIndex, quickAccessItems.count))
        QuickAccessConfiguration.save(quickAccessItems)
    }

    func canPerformQuickAccessCommand(_ command: QuickAccessCommand) -> Bool {
        switch command {
        case .save:
            return !jobs.isEmpty || !queueGroups.isEmpty
        case .group:
            return queueSortMode == .manual && !isRunning
        case .random:
            return canSelectRandomVisibleJob
        case .view, .top, .darkMode, .loadCookie, .webBrowser:
            return true
        }
    }

    func isQuickAccessCommandActive(_ command: QuickAccessCommand) -> Bool {
        switch command {
        case .top:
            return mainWindowAlwaysOnTop
        case .darkMode:
            return appAppearanceMode == .dark
        default:
            return false
        }
    }

    func performQuickAccessCommand(_ command: QuickAccessCommand) {
        guard canPerformQuickAccessCommand(command) else { return }
        switch command {
        case .save:
            exportOriginalTasks()
        case .group:
            beginCreatingQueueGroup()
        case .view:
            toggleQueueViewMode()
        case .random:
            selectRandomVisibleJob()
        case .top:
            setMainWindowAlwaysOnTop(!mainWindowAlwaysOnTop)
        case .darkMode:
            setAppAppearanceMode(appAppearanceMode == .dark ? .light : .dark)
        case .loadCookie:
            importCookies()
        case .webBrowser:
            openBrowserWindow()
        }
    }

