    var shortcutEditorConflictCommand: AppShortcutCommand? {
        shortcutConflict(for: shortcutEditorCommand, shortcut: shortcutEditorDraft)
    }

    func shortcut(for command: AppShortcutCommand) -> AppShortcut {
        (appShortcutAssignments[command] ?? command.defaultShortcut).normalized()
    }

    func keyboardShortcut(for command: AppShortcutCommand) -> KeyboardShortcut? {
        shortcut(for: command).keyboardShortcut
    }

    func shortcutDisplay(for command: AppShortcutCommand) -> String {
        shortcut(for: command).displayText
    }

    func beginEditingShortcut(_ command: AppShortcutCommand) {
        shortcutEditorCommand = command
        shortcutEditorDraft = shortcut(for: command)
        shortcutEditorMessage = ""
    }

    func setShortcutDraftKey(_ key: AppShortcutKey) {
        shortcutEditorDraft.key = key
        if key == .none {
            shortcutEditorDraft.modifiers.removeAll()
        }
        shortcutEditorMessage = ""
    }

    func setShortcutDraftModifier(_ modifier: AppShortcutModifier, enabled: Bool) {
        if enabled {
            shortcutEditorDraft.modifiers.insert(modifier)
        } else {
            shortcutEditorDraft.modifiers.remove(modifier)
        }
        shortcutEditorMessage = ""
    }

    func recordShortcutDraft(from event: NSEvent) {
        guard let shortcut = AppShortcut.fromKeyEvent(event) else {
            shortcutEditorMessage = "Unsupported key"
            return
        }
        shortcutEditorDraft = shortcut
        shortcutEditorMessage = "\(shortcut.displayText) recorded"
    }

    func clearShortcutDraft() {
        shortcutEditorDraft = .none
        shortcutEditorMessage = "Shortcut cleared"
    }

    func resetShortcutDraft() {
        shortcutEditorDraft = shortcutEditorCommand.defaultShortcut
        shortcutEditorMessage = "Default restored for \(shortcutEditorCommand.label)"
    }

    @discardableResult
    func saveShortcutDraft() -> Bool {
        let normalized = shortcutEditorDraft.normalized()
        if let conflict = shortcutConflict(for: shortcutEditorCommand, shortcut: normalized) {
            shortcutEditorMessage = "\(normalized.displayText) conflicts with \(conflict.label)"
            addSummary = "Shortcut conflict"
            return false
        }
        appShortcutAssignments[shortcutEditorCommand] = normalized
        persistAppShortcutAssignments()
        shortcutEditorMessage = "\(shortcutEditorCommand.label) set to \(normalized.displayText)"
        addSummary = shortcutEditorMessage
        return true
    }

    func resetAllShortcuts() {
        appShortcutAssignments = Self.defaultAppShortcutAssignments()
        shortcutEditorDraft = shortcut(for: shortcutEditorCommand)
        persistAppShortcutAssignments()
        shortcutEditorMessage = "All shortcuts reset"
        addSummary = "Shortcuts reset"
    }

    func shortcutConflict(for command: AppShortcutCommand, shortcut: AppShortcut) -> AppShortcutCommand? {
        let normalized = shortcut.normalized()
        guard normalized.isActive else { return nil }
        return AppShortcutCommand.allCases.first { candidate in
            candidate != command && self.shortcut(for: candidate) == normalized
        }
    }

