    func beginRetryIncompleteJobs() {
        guard !isRunning else {
            addSummary = "Stop queue before restarting incomplete jobs"
            return
        }
        let ids = jobs.reversed().filter(isRetryableIncompleteJob).map(\.id)
        guard !ids.isEmpty else {
            addSummary = "No incomplete jobs to restart"
            return
        }
        pendingIncompleteRetryJobIDs = ids
        showingRetryIncompleteJobsConfirmation = true
    }

    func cancelPendingIncompleteJobRetry() {
        pendingIncompleteRetryJobIDs = []
        showingRetryIncompleteJobsConfirmation = false
    }

    @discardableResult
    func retryPendingIncompleteJobs() -> Int {
        let ids = pendingIncompleteRetryJobIDs
        cancelPendingIncompleteJobRetry()
        return retryIncompleteJobs(jobIDs: ids)
    }

    @discardableResult
    func retryIncompleteJobs() -> Int {
        retryIncompleteJobs(jobIDs: jobs.reversed().filter(isRetryableIncompleteJob).map(\.id))
    }

    func beginRemovingCompletedJobs() {
        guard !isRunning else {
            addSummary = "Stop queue before removing completed jobs"
            return
        }
        let ids = jobs.filter(isRemovableCompletedJob).map(\.id)
        guard !ids.isEmpty else {
            addSummary = "No completed jobs to remove"
            return
        }
        pendingCompletedRemovalJobIDs = ids
        showingCompletedJobsRemovalConfirmation = true
    }

    func cancelPendingCompletedJobRemoval() {
        pendingCompletedRemovalJobIDs = []
        showingCompletedJobsRemovalConfirmation = false
    }

    @discardableResult
    func removePendingCompletedJobs() -> Int {
        let ids = pendingCompletedRemovalJobIDs
        cancelPendingCompletedJobRemoval()
        return clearCompletedJobs(jobIDs: ids)
    }

    @discardableResult
    func clearCompletedJobs() -> Int {
        clearCompletedJobs(jobIDs: jobs.filter(isRemovableCompletedJob).map(\.id))
    }

    @discardableResult
    private func retryIncompleteJobs(jobIDs: [UUID]) -> Int {
        guard !isRunning else {
            addSummary = "Stop queue before restarting incomplete jobs"
            return 0
        }

        var retried = 0
        for id in jobIDs {
            guard let index = jobs.firstIndex(where: { $0.id == id }),
                  isRetryableIncompleteJob(jobs[index]) else {
                continue
            }
            queueJobForRetry(at: index)
            retried += 1
        }
        guard retried > 0 else {
            addSummary = "No incomplete jobs to restart"
            return 0
        }

        addSummary = "\(retried) incomplete job\(retried == 1 ? "" : "s") restarted"
        persistQueue()
        runQueuedJobsIfEnabled()
        return retried
    }

    @discardableResult
    private func clearCompletedJobs(jobIDs: [UUID]) -> Int {
        guard !isRunning else {
            addSummary = "Stop queue before removing completed jobs"
            return 0
        }

        let requested = Set(jobIDs)
        let ids = Set(jobs.lazy.filter { requested.contains($0.id) && self.isRemovableCompletedJob($0) }.map(\.id))
        ids.forEach { cancelScheduledRestart(for: $0) }
        jobs.removeAll { ids.contains($0.id) }
        selectedJobIDs.subtract(ids)
        addSummary = ids.isEmpty
            ? "No completed jobs to remove"
            : "\(ids.count) completed job\(ids.count == 1 ? "" : "s") removed"
        persistQueue()
        return ids.count
    }

    private func queueJobForRetry(at index: Int) {
        cancelScheduledRestart(for: jobs[index].id)
        retrySnapshots[jobs[index].id] = jobs[index]
        completionAlertedJobIDs.remove(jobs[index].id)
        queueRunFinishedJobIDs.remove(jobs[index].id)
        queueRunFailedJobIDs.remove(jobs[index].id)
        jobs[index].title = jobs[index].source
        jobs[index].status = .queued
        jobs[index].progress = 0
        jobs[index].completed = 0
        jobs[index].total = 0
        jobs[index].message = ""
        jobs[index].outputPath = ""
        jobs[index].metadata.removeValue(forKey: "last_error")
        jobs[index].metadata.removeValue(forKey: "reaction")
    }

    func markJobFinished(_ job: DownloadJob) {
        guard let index = jobs.firstIndex(where: { $0.id == job.id }) else { return }
        _ = markJobFinished(at: index)
    }

    func canMarkJobFinished(_ job: DownloadJob) -> Bool {
        guard let index = jobs.firstIndex(where: { $0.id == job.id }) else { return false }
        return canMarkJobFinished(at: index)
    }

    @discardableResult
    func markJobsFinished(startingAt job: DownloadJob) -> Int {
        let targetIDs = contextualJobs(startingAt: job).reversed().map(\.id)
        var marked = 0
        var skippedActive = 0

        for id in targetIDs {
            guard let index = jobs.firstIndex(where: { $0.id == id }) else { continue }
            guard canMarkJobFinished(at: index) else {
                if isActive(jobs[index].status) {
                    skippedActive += 1
                }
                continue
            }
            if markJobFinished(at: index) {
                marked += 1
            }
        }

        if marked == 0 {
            addSummary = skippedActive > 0
                ? "Pause or cancel active jobs before marking finished"
                : "No selected jobs can be marked finished"
        } else if skippedActive > 0 {
            addSummary = "\(marked) selected job\(marked == 1 ? "" : "s") marked finished, \(skippedActive) active skipped"
        } else {
            addSummary = "\(marked) selected job\(marked == 1 ? "" : "s") marked finished"
        }
        persistQueue()
        return marked
    }

    func canMarkJobsFinished(startingAt job: DownloadJob) -> Bool {
        contextualJobs(startingAt: job).contains { candidate in
            guard let index = jobs.firstIndex(where: { $0.id == candidate.id }) else { return false }
            return canMarkJobFinished(at: index)
        }
    }

