    func canRemoveJobs(startingAt job: DownloadJob) -> Bool {
        return contextualJobs(startingAt: job).contains { candidate in
            !candidate.isLocked &&
                !Self.isPendingQueueRemoval(candidate)
        }
    }

    func beginRemovingJobs(startingAt job: DownloadJob) {
        let selected = contextualJobs(startingAt: job)
        let removable = selected.filter {
            !$0.isLocked &&
                !Self.isPendingQueueRemoval($0)
        }
        guard !removable.isEmpty else {
            if selected.contains(where: \.isLocked) {
                addSummary = "Unlock jobs before removing"
            } else {
                addSummary = "No removable jobs selected"
            }
            return
        }

        jobPendingRemoval = removable.first
        jobPendingRemovalIDs = removable.map(\.id)
        showingJobRemovalConfirmation = true
    }

    var pendingJobRemovalCount: Int {
        let pending = Set(jobPendingRemovalIDs)
        return jobs.lazy.filter { pending.contains($0.id) }.count
    }

    var jobRemovalConfirmationMessage: String {
        let pending = Set(jobPendingRemovalIDs)
        let selected = jobs.filter { pending.contains($0.id) }
        let activeNote: String
        if selected.contains(where: { isActive($0.status) }) {
            activeNote = AppLocalization.text(
                "\nActive downloads will be cancelled immediately. Files already downloaded will be kept.",
                language: interfaceLanguage
            )
        } else {
            activeNote = ""
        }
        guard selected.count != 1 else {
            return AppLocalization.format(
                "Remove \"%@\" from the list only. Downloaded files will not be deleted.%@",
                language: interfaceLanguage,
                selected[0].title,
                activeNote
            )
        }

        let titles = selected.prefix(10).map { job in
            "• \(job.title.trimmed.isEmpty ? job.source : job.title)"
        }.joined(separator: "\n")
        let remainder = selected.count > 10 ? "\n• ..." : ""
        return AppLocalization.format(
            "Remove %@ tasks from the list only. Downloaded files will not be deleted.\n%@%@%@",
            language: interfaceLanguage,
            String(selected.count),
            titles,
            remainder,
            activeNote
        )
    }

    func cancelPendingJobRemoval() {
        jobPendingRemoval = nil
        jobPendingRemovalIDs = []
        showingJobRemovalConfirmation = false
    }

    @discardableResult
    func removePendingJobs() -> Int {
        let pending = Set(jobPendingRemovalIDs)
        let selected = jobs.filter { pending.contains($0.id) }
        let removed = removeJobs(selected)
        cancelPendingJobRemoval()
        return removed
    }

    @discardableResult
    func removeJobs(_ selectedJobs: [DownloadJob]) -> Int {
        let requestedIDs = Set(selectedJobs.map(\.id))
        let candidates = jobs.filter { requestedIDs.contains($0.id) }
        let removable = candidates.filter {
            !$0.isLocked &&
                !Self.isPendingQueueRemoval($0)
        }
        guard !removable.isEmpty else {
            if candidates.contains(where: \.isLocked) {
                addSummary = "Unlock jobs before removing"
            } else {
                addSummary = "No removable jobs selected"
            }
            return 0
        }

        let removedCount = removeJobsFromQueue(removable)

        let skipped = candidates.count - removable.count
        if removedCount == 1 && skipped == 0 {
            addSummary = "Job removed"
        } else if skipped > 0 {
            addSummary = "\(removedCount) selected jobs removed, \(skipped) locked skipped"
        } else {
            addSummary = "\(removedCount) selected jobs removed"
        }
        return removedCount
    }

    func removeJob(_ job: DownloadJob) {
        _ = removeJobs([job])
    }

    @discardableResult
    private func removeJobsFromQueue(_ removable: [DownloadJob]) -> Int {
        let removableIDs = Set(removable.map(\.id))
        guard !removableIDs.isEmpty else { return 0 }

        removableIDs.forEach { cancelScheduledRestart(for: $0) }
        selectedJobIDs.subtract(removableIDs)

        let requiresDeferredOutputCleanup = jobs.contains {
            removableIDs.contains($0.id) && Self.isPendingQueueOutputDeletion($0)
        }
        if isRunning || !processingJobIDs.isEmpty || requiresDeferredOutputCleanup {
            for index in jobs.indices where removableIDs.contains(jobs[index].id) {
                let jobID = jobs[index].id
                let shouldCancel = isActive(jobs[index].status) ||
                    processingJobIDs.contains(jobID) ||
                    runningJobTasks[jobID] != nil
                jobs[index].metadata[Self.pendingQueueRemovalMetadataKey] = "true"
                if jobs[index].status == .queued || shouldCancel {
                    markCancelled(index, persist: false)
                    jobs[index].message = shouldCancel
                        ? "Removed and cancelled"
                        : "Removed while queue was running"
                    jobs[index].recordMessage(jobs[index].message)
                }
                if shouldCancel {
                    cancelRunningJob(jobID)
                }
            }
            persistQueue()
            flushPendingQueueRemovals()
            persistQueue()
            return removableIDs.count
        }

        jobs.removeAll { removableIDs.contains($0.id) }
        activeQueueOrderIDs?.removeAll { removableIDs.contains($0) }
        persistQueue()
        return removableIDs.count
    }

    private func flushPendingQueueRemovals() {
        let pendingIDs = Set(
            jobs.lazy
                .filter(Self.isPendingQueueRemoval)
                .map(\.id)
        )
        guard !pendingIDs.isEmpty else { return }
        let pendingOutputDeletionIDs = Set(
            jobs.lazy
                .filter {
                    pendingIDs.contains($0.id) &&
                        Self.isPendingQueueOutputDeletion($0)
                }
                .map(\.id)
        )

        let deletedAt = ISO8601DateFormatter().string(from: Date())
        if processingJobIDs.isDisjoint(with: pendingOutputDeletionIDs) {
            for jobID in pendingOutputDeletionIDs {
                guard let index = jobs.firstIndex(where: { $0.id == jobID }) else { continue }

                let candidates = resolvedOutputDeletionCandidates(for: jobs[index])
                guard !candidates.isEmpty else {
                    jobs[index].outputPath = ""
                    jobs[index].metadata.removeValue(forKey: Self.pendingQueueOutputDeletionMetadataKey)
                    jobs[index].metadata["output_deleted_at"] = deletedAt
                    continue
                }
                guard !candidates.contains(where: {
                    let currentPendingOutputDeletionIDs = Set(
                        jobs.lazy
                            .filter(Self.isPendingQueueOutputDeletion)
                            .map(\.id)
                    )
                    return isOutputDeletionCandidateShared(
                        $0,
                        excludingJobIDs: currentPendingOutputDeletionIDs
                    )
                }) else {
                    jobs[index].metadata.removeValue(forKey: Self.pendingQueueRemovalMetadataKey)
                    jobs[index].metadata.removeValue(forKey: Self.pendingQueueOutputDeletionMetadataKey)
                    jobs[index].message = "Output is shared with another queue job"
                    continue
                }

                do {
                    let result = try trashOutputDeletionCandidates(candidates)
                    if result.failures.isEmpty {
                        if !result.resolvedPaths.isEmpty {
                            updateOutputPathAfterDeletingCandidates(at: index, trashedPaths: result.resolvedPaths)
                        }
                        jobs[index].metadata.removeValue(forKey: Self.pendingQueueOutputDeletionMetadataKey)
                        jobs[index].metadata["output_deleted_at"] = deletedAt
                        continue
                    }
                    if !result.resolvedPaths.isEmpty {
                        updateOutputPathAfterDeletingCandidates(at: index, trashedPaths: result.resolvedPaths)
                        jobs[index].metadata["output_deleted_at"] = deletedAt
                    }
                    jobs[index].metadata.removeValue(forKey: Self.pendingQueueRemovalMetadataKey)
                    jobs[index].metadata.removeValue(forKey: Self.pendingQueueOutputDeletionMetadataKey)
                    jobs[index].metadata["output_delete_partial_at"] = deletedAt
                    jobs[index].metadata["output_delete_failed_count"] = String(result.failures.count)
                    jobs[index].message = "\(result.trashedItemCount) output item(s) moved; \(result.failures.count) failed"
                } catch {
                    jobs[index].metadata.removeValue(forKey: Self.pendingQueueRemovalMetadataKey)
                    jobs[index].metadata.removeValue(forKey: Self.pendingQueueOutputDeletionMetadataKey)
                    jobs[index].metadata["output_delete_partial_at"] = deletedAt
                    jobs[index].metadata["output_delete_failed_count"] = "1"
                    jobs[index].message = "Output delete failed: \(error.localizedDescription)"
                }
            }
        }

        guard processingJobIDs.isEmpty, !isRunning else { return }
        let removableIDs = Set(
            jobs.lazy
                .filter {
                    Self.isPendingQueueRemoval($0) &&
                        !Self.isPendingQueueOutputDeletion($0)
                }
                .map(\.id)
        )
        removableIDs.forEach { cancelScheduledRestart(for: $0) }
        jobs.removeAll { removableIDs.contains($0.id) }
        activeQueueOrderIDs?.removeAll { removableIDs.contains($0) }
        selectedJobIDs.subtract(removableIDs)
    }

#if TESTING
    func flushPendingQueueRemovalsForTesting() {
        flushPendingQueueRemovals()
        persistQueue()
    }
#endif

    func toggleJobPinned(_ job: DownloadJob) {
