        jobs[index].isPinned.toggle()
        let isPinned = jobs[index].isPinned
        addSummary = isPinned ? "Job pinned" : "Job unpinned"
        persistQueue()
    }

    func toggleJobLocked(_ job: DownloadJob) {
        guard let index = jobs.firstIndex(where: { $0.id == job.id }) else { return }
        jobs[index].isLocked.toggle()
        addSummary = jobs[index].isLocked ? "Job locked" : "Job unlocked"
        persistQueue()
    }

    func jobPinActionWillPin(startingAt job: DownloadJob) -> Bool {
