    }

    func canToggleJobPins(startingAt job: DownloadJob) -> Bool {
        !isRunning && !contextualJobs(startingAt: job).isEmpty
    }

    func toggleJobPins(startingAt job: DownloadJob) {
        guard !isRunning else {
            addSummary = "Stop queue before pinning jobs"
            return
        }
        let targets = contextualJobs(startingAt: job)
        guard !targets.isEmpty else { return }
        let shouldPin = targets.contains { !$0.isPinned }
        let targetIDs = Set(targets.map(\.id))
        let indexes = jobs.indices.filter { targetIDs.contains(jobs[$0].id) }
        for index in indexes {
            jobs[index].isPinned = shouldPin
        }
        addSummary = "\(indexes.count) selected job\(indexes.count == 1 ? "" : "s") \(shouldPin ? "pinned" : "unpinned")"
        persistQueue()
    }

