    func taskTagDisplayName(_ tag: TaskTagColor) -> String {
        let custom = taskTagNames[tag.rawValue]?.trimmed ?? ""
        return custom.isEmpty ? tag.label : custom
    }

    func setTaskTagName(_ name: String, for tag: TaskTagColor) {
        let normalized = String(name.trimmed.prefix(80))
        taskTagNames[tag.rawValue] = normalized
        persistTaskTagNames()
    }

    func taskTagRestartDelay(for tag: TaskTagColor) -> TaskTagRestartDelay? {
        TaskTagRestartDelay(rawValue: taskTagRestartTimers[tag.rawValue] ?? 0)
    }

    func taskTagRestartTimerDescription(for tag: TaskTagColor) -> String {
        let seconds = taskTagRestartTimers[tag.rawValue] ?? 0
        if let delay = TaskTagRestartDelay(rawValue: seconds) {
            return delay.label
        }
        guard seconds > 0 else { return TaskTagRestartDelay.off.label }
        return "\(Self.restartDelayDescription(for: TimeInterval(seconds))) 뒤 다시 시작"
    }

    func setTaskTagRestartDelay(_ delay: TaskTagRestartDelay, for tag: TaskTagColor) {
        taskTagRestartTimers[tag.rawValue] = delay.rawValue
        persistTaskTagRestartTimers()
        rescheduleFinishedJobs(using: tag)
        addSummary = delay == .off
            ? "\(taskTagDisplayName(tag)) tag timer off"
            : "\(taskTagDisplayName(tag)) tag timer: \(delay.label)"
    }

    func resetTaskTagNames() {
        taskTagNames = Dictionary(uniqueKeysWithValues: TaskTagColor.allCases.map { ($0.rawValue, $0.label) })
        persistTaskTagNames()
        addSummary = "Task tag names reset"
    }

    func isJobTagChecked(_ tag: TaskTagColor, for job: DownloadJob) -> Bool {
        let targetIDs = selectedJobIDs.contains(job.id) ? selectedJobIDs : Set([job.id])
        let targets = jobs.filter { targetIDs.contains($0.id) }
        guard !targets.isEmpty else { return false }
        return targets.allSatisfy { $0.tags.contains(tag.rawValue) }
    }

    func toggleJobTag(_ tag: TaskTagColor, for job: DownloadJob) {
        let targetIDs = selectedJobIDs.contains(job.id) ? selectedJobIDs : Set([job.id])
        let indexes = jobs.indices.filter { targetIDs.contains(jobs[$0].id) }
        guard !indexes.isEmpty else { return }

        let shouldAdd = indexes.contains { !jobs[$0].tags.contains(tag.rawValue) }
        for index in indexes {
            var tags = TaskTagColor.normalizedRawValues(jobs[index].tags)
            if shouldAdd {
                if !tags.contains(tag.rawValue) {
                    tags.append(tag.rawValue)
                }
            } else {
                tags.removeAll { $0 == tag.rawValue }
            }
            jobs[index].tags = tags
        }
        let name = taskTagDisplayName(tag)
        addSummary = shouldAdd
            ? "\(name) tag added to \(indexes.count) job\(indexes.count == 1 ? "" : "s")"
            : "\(name) tag removed from \(indexes.count) job\(indexes.count == 1 ? "" : "s")"
        for jobID in indexes.map({ jobs[$0].id }) {
            guard let current = jobs.first(where: { $0.id == jobID }),
                  current.status == .finished else {
                continue
            }
            scheduleRestartIfNeeded(for: current)
        }
        persistQueue()
    }

    nonisolated static func loadTaskTagNames(defaults: UserDefaults = .standard) -> [String: String] {
        let stored = defaults.dictionary(forKey: "taskTagNames") as? [String: String] ?? [:]
        var normalized: [String: String] = [:]
        for tag in TaskTagColor.allCases {
            let name = stored[tag.rawValue]?.trimmed ?? ""
            normalized[tag.rawValue] = name.isEmpty ? tag.label : String(name.prefix(80))
        }
        return normalized
    }

    nonisolated static func loadTaskTagRestartTimers(defaults: UserDefaults = .standard) -> [String: Int] {
        var stored: [String: Int] = [:]
        if let dictionary = defaults.dictionary(forKey: "taskTagRestartTimers") {
            for (key, value) in dictionary {
                if let number = value as? NSNumber {
                    stored[key] = max(0, number.intValue)
                } else if let text = value as? String, let seconds = Int(text) {
                    stored[key] = max(0, seconds)
                }
            }
        } else if let originalJSON = defaults.string(forKey: "tag_timer"),
                  let data = originalJSON.data(using: .utf8),
                  let decoded = try? JSONDecoder().decode([String: Int].self, from: data) {
            stored = decoded.mapValues { max(0, $0) }
        }

        return Dictionary(uniqueKeysWithValues: TaskTagColor.allCases.map { tag in
            (tag.rawValue, stored[tag.rawValue] ?? 0)
        })
    }

    private func rescheduleFinishedJobs(using tag: TaskTagColor) {
        let jobIDs = jobs.compactMap { job in
            job.status == .finished && job.tags.contains(tag.rawValue) ? job.id : nil
        }
        for jobID in jobIDs {
            guard let current = jobs.first(where: { $0.id == jobID }) else { continue }
            scheduleRestartIfNeeded(for: current)
        }
        if !jobIDs.isEmpty {
            persistQueue()
        }
    }

    func jobGroupID(for job: DownloadJob) -> UUID? {
        if let id = Self.queueGroupID(in: job), queueGroups.contains(where: { $0.id == id }) {
            return id
        }
        let legacyName = (job.metadata["group"] ?? job.metadata["group_name"] ?? "").trimmed
        guard !legacyName.isEmpty else { return nil }
        return queueGroups.first {
            $0.name.caseInsensitiveCompare(legacyName) == .orderedSame
        }?.id
    }

    func jobGroupName(for job: DownloadJob) -> String? {
        if let groupID = jobGroupID(for: job),
           let group = queueGroups.first(where: { $0.id == groupID }) {
            return group.name
        }
        let value = (job.metadata["group"] ?? job.metadata["group_name"] ?? "").trimmed
        return value.isEmpty ? nil : value
    }

    func jobs(in group: QueueGroup) -> [DownloadJob] {
        visibleQueueOrderedJobs.filter { jobGroupID(for: $0) == group.id }
    }

    func beginCreatingQueueGroup() {
        guard queueSortMode == .manual else {
            addSummary = "기본 정렬 상태에서만 그룹을 만들 수 있습니다."
            return
        }
        guard !isRunning else {
            addSummary = "Stop queue before creating a group"
            return
        }
        let selectedIDs = selectedJobIDs.intersection(Set(jobs.map(\.id)))
        if jobs.contains(where: { selectedIDs.contains($0.id) && jobGroupID(for: $0) != nil }) {
            addSummary = "이미 포함하는 그룹이 있습니다."
            return
        }
        queueGroupPromptAction = .create(jobIDs: selectedIDs)
        jobGroupPending = nil
        jobGroupNameDraft = AppLocalization.text("New Group", language: interfaceLanguage)
        showingJobGroupPrompt = true
    }

    func beginRenamingQueueGroup(_ group: QueueGroup) {
        guard queueGroups.contains(where: { $0.id == group.id }) else { return }
        queueGroupPromptAction = .rename(groupID: group.id)
        jobGroupPending = nil
        jobGroupNameDraft = group.name
        showingJobGroupPrompt = true
    }

    func beginMovingJobToNewGroup(_ job: DownloadJob) {
        guard queueSortMode == .manual else {
            addSummary = "기본 정렬 상태에서만 그룹으로 이동할 수 있습니다."
            return
        }
        guard let current = jobs.first(where: { $0.id == job.id }) else { return }
        let jobIDs = selectedJobIDs.contains(current.id)
            ? selectedJobIDs.intersection(Set(jobs.map(\.id)))
            : Set([current.id])
        queueGroupPromptAction = .move(jobIDs: jobIDs)
        jobGroupPending = current
        jobGroupNameDraft = AppLocalization.text("New Group", language: interfaceLanguage)
        showingJobGroupPrompt = true
    }

