    func savePendingJobGroup() {
        let name = jobGroupNameDraft.trimmed
        guard !name.isEmpty, let action = queueGroupPromptAction else {
            cancelPendingJobGroup()
            return
        }

        switch action {
        case .create(let jobIDs):
            _ = createQueueGroup(named: name, jobIDs: jobIDs)
        case .move(let jobIDs):
            if let existing = queueGroups.first(where: { $0.name.caseInsensitiveCompare(name) == .orderedSame }) {
                _ = moveJobs(jobIDs, toQueueGroup: existing.id)
            } else {
                let anchor = jobs.first(where: { jobIDs.contains($0.id) })?.id
                var group = QueueGroup(name: name, anchorJobID: anchor)
                group.originalUID = group.id.uuidString
                queueGroups.append(group)
                _ = moveJobs(jobIDs, toQueueGroup: group.id)
            }
        case .rename(let groupID):
            renameQueueGroup(groupID, to: name)
        }
        cancelPendingJobGroup()
    }

    func cancelPendingJobGroup() {
        showingJobGroupPrompt = false
        queueGroupPromptAction = nil
        jobGroupPending = nil
        jobGroupNameDraft = ""
    }

    @discardableResult
    func createQueueGroup(named rawName: String, jobIDs: Set<UUID>) -> QueueGroup? {
        let name = rawName.trimmed
        guard !name.isEmpty, queueSortMode == .manual, !isRunning else { return nil }
        let selected = jobs.filter { jobIDs.contains($0.id) }
        guard !selected.contains(where: { jobGroupID(for: $0) != nil }) else {
            addSummary = "이미 포함하는 그룹이 있습니다."
            return nil
        }

        let selectedIndexes = jobs.indices.filter { jobIDs.contains(jobs[$0].id) }
        let insertionIndex = selectedIndexes.min() ?? 0
        var group = QueueGroup(
            name: name,
            anchorJobID: selected.first?.id ?? jobs.first?.id
        )
        group.originalUID = group.id.uuidString
        queueGroups.append(group)

        if !selected.isEmpty {
            jobs.removeAll { jobIDs.contains($0.id) }
            jobs.insert(contentsOf: selected, at: min(insertionIndex, jobs.count))
            applyQueueGroup(group, to: jobIDs)
            setSelectedJobIDs(jobIDs)
        }

        addSummary = selected.isEmpty
            ? "Group \(name) created"
            : "\(selected.count) jobs grouped as \(name)"
        persistQueue()
        return group
    }

    @discardableResult
    func moveJobs(_ jobIDs: Set<UUID>, toQueueGroup groupID: UUID?) -> Bool {
        guard queueSortMode == .manual else {
            addSummary = "기본 정렬 상태에서만 그룹으로 이동할 수 있습니다."
            return false
        }
        guard !isRunning else {
            addSummary = "Stop queue before moving grouped jobs"
            return false
        }
        let movingJobs = jobs.filter { jobIDs.contains($0.id) }
        guard !movingJobs.isEmpty,
              !movingJobs.contains(where: { isActive($0.status) }) else {
            return false
        }

        if let groupID {
            guard let targetIndex = queueGroups.firstIndex(where: { $0.id == groupID }) else { return false }
            if movingJobs.allSatisfy({ jobGroupID(for: $0) == groupID }) {
                return false
            }

            let target = queueGroups[targetIndex]
            let remaining = jobs.filter { !jobIDs.contains($0.id) }
            let insertionIndex = remaining.firstIndex(where: { jobGroupID(for: $0) == groupID })
                ?? target.anchorJobID.flatMap { anchor in remaining.firstIndex(where: { $0.id == anchor }) }
                ?? remaining.endIndex
            jobs = remaining
            jobs.insert(contentsOf: movingJobs, at: insertionIndex)
            applyQueueGroup(target, to: jobIDs)
            queueGroups[targetIndex].anchorJobID = movingJobs.first?.id
            setSelectedJobIDs(jobIDs)
            addSummary = "\(movingJobs.count) job\(movingJobs.count == 1 ? "" : "s") moved to \(target.name)"
        } else {
            clearQueueGroup(from: jobIDs)
            addSummary = "\(movingJobs.count) job\(movingJobs.count == 1 ? "" : "s") removed from group"
        }
        persistQueue()
        return true
    }

    func moveJob(_ job: DownloadJob, toGroup rawGroup: String?) {
        let name = rawGroup?.trimmed ?? ""
        if name.isEmpty {
            _ = moveJobs([job.id], toQueueGroup: nil)
            return
        }
        if let group = queueGroups.first(where: { $0.name.caseInsensitiveCompare(name) == .orderedSame }) {
            _ = moveJobs([job.id], toQueueGroup: group.id)
            return
        }
        var group = QueueGroup(name: name, anchorJobID: job.id)
        group.originalUID = group.id.uuidString
        queueGroups.append(group)
        _ = moveJobs([job.id], toQueueGroup: group.id)
    }

    func toggleQueueGroupExpanded(_ group: QueueGroup) {
        guard let index = queueGroups.firstIndex(where: { $0.id == group.id }) else { return }
        queueGroups[index].isExpanded.toggle()
        let updated = queueGroups[index]
        applyQueueGroup(updated, to: Set(jobs(in: updated).map(\.id)))
        if !updated.isExpanded {
            selectedJobIDs.subtract(jobs(in: updated).map(\.id))
        }
        addSummary = updated.isExpanded ? "Group expanded" : "Group collapsed"
        persistQueue()
    }

    func toggleQueueGroupPinned(_ group: QueueGroup) {
        guard !isRunning else {
            addSummary = "Stop queue before pinning groups"
            return
        }
        guard let index = queueGroups.firstIndex(where: { $0.id == group.id }) else { return }
        queueGroups[index].isPinned.toggle()
        let updated = queueGroups[index]
        applyQueueGroup(updated, to: Set(jobs(in: updated).map(\.id)))
        addSummary = updated.isPinned ? "Group pinned" : "Group unpinned"
        persistQueue()
    }

    func toggleQueueGroupTag(_ tag: TaskTagColor, for group: QueueGroup) {
        guard let index = queueGroups.firstIndex(where: { $0.id == group.id }) else { return }
        var values = Set(TaskTagColor.normalizedRawValues(queueGroups[index].tags))
        let added: Bool
        if values.remove(tag.rawValue) != nil {
            added = false
        } else {
            values.insert(tag.rawValue)
            added = true
        }
        queueGroups[index].tags = TaskTagColor.allCases.compactMap {
            values.contains($0.rawValue) ? $0.rawValue : nil
        }
        let updated = queueGroups[index]
        applyQueueGroup(updated, to: Set(jobs(in: updated).map(\.id)))
        addSummary = added ? "Group tag: \(tag.label)" : "Group tag removed: \(tag.label)"
        persistQueue()
    }

    func renameQueueGroup(_ groupID: UUID, to rawName: String) {
        let name = rawName.trimmed
        guard !name.isEmpty,
              let index = queueGroups.firstIndex(where: { $0.id == groupID }) else { return }
        queueGroups[index].name = name
        let group = queueGroups[index]
        applyQueueGroup(group, to: Set(jobs(in: group).map(\.id)))
        addSummary = "Group renamed to \(name)"
        persistQueue()
    }

    func beginRemovingQueueGroup(_ group: QueueGroup) {
        guard queueGroups.contains(where: { $0.id == group.id }) else { return }
        queueGroupPendingRemoval = group
        showingQueueGroupRemovalConfirmation = true
    }

    func removePendingQueueGroup() {
        guard let group = queueGroupPendingRemoval else { return }
        let memberIDs = Set(jobs(in: group).map(\.id))
        clearQueueGroup(from: memberIDs)
        queueGroups.removeAll { $0.id == group.id }
        queueGroupPendingRemoval = nil
        showingQueueGroupRemovalConfirmation = false
        addSummary = "Group removed; \(memberIDs.count) jobs kept"
        persistQueue()
    }

    func cancelPendingQueueGroupRemoval() {
        queueGroupPendingRemoval = nil
        showingQueueGroupRemovalConfirmation = false
    }

    func beginRetryingQueueGroup(_ group: QueueGroup) {
        guard !jobs(in: group).isEmpty else { return }
        queueGroupPendingRetry = group
        showingQueueGroupRetryConfirmation = true
    }

    func retryPendingQueueGroup() {
        guard let group = queueGroupPendingRetry else { return }
        let members = jobs(in: group)
        queueGroupPendingRetry = nil
        showingQueueGroupRetryConfirmation = false
        retryJobs(members)
    }

    func cancelPendingQueueGroupRetry() {
        queueGroupPendingRetry = nil
        showingQueueGroupRetryConfirmation = false
    }

    private func applyQueueGroup(_ group: QueueGroup, to jobIDs: Set<UUID>) {
        for index in jobs.indices where jobIDs.contains(jobs[index].id) {
            jobs[index].metadata[Self.queueGroupIDMetadataKey] = group.id.uuidString
            jobs[index].metadata["group"] = group.name
            jobs[index].metadata.removeValue(forKey: "group_name")
            jobs[index].metadata["hdt_group_uid"] = group.originalUID
            jobs[index].metadata["hdt_group_expanded"] = group.isExpanded ? "true" : "false"
            jobs[index].metadata["hdt_group_pinned"] = group.isPinned ? "true" : "false"
            if group.tags.isEmpty {
                jobs[index].metadata.removeValue(forKey: "group_tags")
                jobs[index].metadata.removeValue(forKey: "hdt_group_tags")
            } else {
                jobs[index].metadata["group_tags"] = group.tags.joined(separator: ",")
                jobs[index].metadata.removeValue(forKey: "hdt_group_tags")
            }
            if group.comment.isEmpty {
                jobs[index].metadata.removeValue(forKey: "group_comment")
            } else {
                jobs[index].metadata["group_comment"] = group.comment
            }
        }
    }

    private func clearQueueGroup(from jobIDs: Set<UUID>) {
        for index in jobs.indices where jobIDs.contains(jobs[index].id) {
            jobs[index].metadata.removeValue(forKey: Self.queueGroupIDMetadataKey)
            jobs[index].metadata.removeValue(forKey: "group")
            jobs[index].metadata.removeValue(forKey: "group_name")
            jobs[index].metadata.removeValue(forKey: "group_comment")
            jobs[index].metadata.removeValue(forKey: "hdt_group_uid")
            jobs[index].metadata.removeValue(forKey: "hdt_group_expanded")
            jobs[index].metadata.removeValue(forKey: "hdt_group_pinned")
            jobs[index].metadata.removeValue(forKey: "group_tags")
            jobs[index].metadata.removeValue(forKey: "hdt_group_tags")
        }
    }

    func jobImageConversionFormat(for job: DownloadJob) -> ImageConversionFormat? {
        guard let value = job.metadata["image_conversion_format"] else { return nil }
        return ImageConversionFormat(rawValue: value.lowercased())
    }

    func setJobImageConversionFormat(_ format: ImageConversionFormat?, for job: DownloadJob) {
        guard let index = jobs.firstIndex(where: { $0.id == job.id }) else { return }
        if let format {
            jobs[index].metadata["image_conversion_format"] = format.rawValue
            addSummary = format == .original
                ? "Job image conversion disabled"
                : "Job images will convert to \(format.label) on download"
        } else {
            jobs[index].metadata.removeValue(forKey: "image_conversion_format")
            addSummary = "Job uses the default image conversion setting"
        }
        persistQueue()
    }

    func canConvertJobImages(for job: DownloadJob) -> Bool {
        guard let current = jobs.first(where: { $0.id == job.id }) else { return false }
        return current.status == .finished && !imageConversionJobIDs.contains(current.id)
    }

    func canConvertJobImages(startingAt job: DownloadJob) -> Bool {
        contextualJobs(startingAt: job).contains { canConvertJobImages(for: $0) }
    }

    func beginConvertingImages(startingAt job: DownloadJob) {
        guard canConvertJobImages(startingAt: job) else {
            addSummary = "No completed images available for conversion"
            return
        }

        let formats = ImageConversionFormat.allCases.filter { $0 != .original }
        guard !formats.isEmpty else { return }

        let formatPopup = NSPopUpButton(frame: NSRect(x: 0, y: 0, width: 220, height: 26), pullsDown: false)
        formatPopup.addItems(withTitles: formats.map(\.label))
        let preferredFormat = imageConversionFormat == .original ? ImageConversionFormat.jpeg : imageConversionFormat
        if let selectedIndex = formats.firstIndex(of: preferredFormat) {
            formatPopup.selectItem(at: selectedIndex)
        }

        let qualitySlider = NSSlider(value: 95, minValue: 1, maxValue: 100, target: nil, action: nil)
        qualitySlider.numberOfTickMarks = 5
        qualitySlider.allowsTickMarkValuesOnly = false
        let qualityTitle = AppLocalization.text("JPEG 화질", language: interfaceLanguage)
        qualitySlider.toolTip = qualityTitle
        qualitySlider.setAccessibilityLabel(qualityTitle)

        let form = NSGridView(views: [
            [NSTextField(labelWithString: AppLocalization.text("파일 형식", language: interfaceLanguage)), formatPopup],
            [NSTextField(labelWithString: qualityTitle), qualitySlider]
        ])
        form.column(at: 0).xPlacement = .trailing
        form.column(at: 1).xPlacement = .fill
        form.rowSpacing = 8
        form.columnSpacing = 10
        form.frame = NSRect(x: 0, y: 0, width: 320, height: 62)

        let alert = NSAlert()
        alert.alertStyle = .informational
        alert.messageText = AppLocalization.text("이미지 포맷 변환", language: interfaceLanguage)
        alert.informativeText = AppLocalization.text(
            "선택한 완료 작업의 이미지 파일을 변환합니다.",
            language: interfaceLanguage
        )
        alert.accessoryView = form
        alert.addButton(withTitle: AppLocalization.text("변환", language: interfaceLanguage))
        alert.addButton(withTitle: AppLocalization.text("취소", language: interfaceLanguage))
        guard alert.runModal() == .alertFirstButtonReturn else { return }

        let selectedIndex = max(0, min(formatPopup.indexOfSelectedItem, formats.count - 1))
        convertImages(
            startingAt: job,
            to: formats[selectedIndex],
            quality: qualitySlider.integerValue
        )
    }

    func convertImages(
        startingAt job: DownloadJob,
        to format: ImageConversionFormat,
        quality: Int = 95
    ) {
        guard format != .original else {
            addSummary = "Choose a converted image format"
            return
        }

        let targets = contextualJobs(startingAt: job).filter { canConvertJobImages(for: $0) }
        guard !targets.isEmpty else {
            addSummary = "No completed images available for conversion"
            return
        }

        let requests = targets.map {
            OutputImageConversionRequest(jobID: $0.id, outputPath: $0.outputPath)
        }
        imageConversionJobIDs.formUnion(requests.map(\.jobID))
        for request in requests {
            guard let index = jobs.firstIndex(where: { $0.id == request.jobID }) else { continue }
            jobs[index].metadata["image_conversion_in_progress"] = "true"
            jobs[index].metadata.removeValue(forKey: "image_conversion_error")
            jobs[index].message = "Converting images to \(format.label)..."
        }
        addSummary = "Converting images for \(requests.count) job\(requests.count == 1 ? "" : "s")..."
        persistQueue()

        let normalizedQuality = max(1, min(quality, 100))
        let task = Task.detached(priority: .userInitiated) {
            requests.map { request in
                do {
                    return OutputImageConversionJobResult(
                        request: request,
                        result: try Self.convertOutputImages(
                            forOutputPath: request.outputPath,
                            to: format,
                            quality: normalizedQuality
                        ),
                        errorDescription: nil
                    )
                } catch {
                    return OutputImageConversionJobResult(
                        request: request,
                        result: nil,
                        errorDescription: error.localizedDescription
                    )
                }
            }
        }

        Task { @MainActor [weak self] in
            let results = await task.value
            self?.finishImageConversions(results, format: format, quality: normalizedQuality)
        }
    }

    private func finishImageConversions(
        _ results: [OutputImageConversionJobResult],
        format: ImageConversionFormat,
        quality: Int
    ) {
        var convertedJobCount = 0
        var convertedFileCount = 0
        var unchangedFileCount = 0
        var failedJobCount = 0
        let convertedAt = ISO8601DateFormatter().string(from: Date())

        for jobResult in results {
            imageConversionJobIDs.remove(jobResult.request.jobID)
            guard let index = jobs.firstIndex(where: { $0.id == jobResult.request.jobID }) else { continue }
            jobs[index].metadata.removeValue(forKey: "image_conversion_in_progress")

            if let result = jobResult.result {
                if jobs[index].outputPath == jobResult.request.outputPath,
                   let primaryOutputPath = result.primaryOutputPath {
                    jobs[index].outputPath = primaryOutputPath
                }
                jobs[index].metadata["image_conversion_format"] = format.rawValue
                jobs[index].metadata["image_conversion_quality"] = String(quality)
                jobs[index].metadata["images_converted_at"] = convertedAt
                jobs[index].metadata["images_converted_count"] = String(result.items.count)
                jobs[index].metadata.removeValue(forKey: "image_conversion_error")
                convertedJobCount += 1
                convertedFileCount += result.items.count
                unchangedFileCount += result.unchangedCount
                jobs[index].message = result.items.isEmpty
                    ? "No images needed conversion"
                    : "\(result.items.count) image\(result.items.count == 1 ? "" : "s") converted to \(format.label)"
                refreshCompletedJobByteCountSynchronously(at: index)
            } else {
                failedJobCount += 1
                let description = jobResult.errorDescription ?? "Unknown conversion error"
                jobs[index].metadata["image_conversion_error"] = description
                jobs[index].message = "Image conversion failed: \(description)"
            }
        }

        persistQueue()
        if failedJobCount > 0 {
            addSummary = "\(convertedFileCount) image(s) converted for \(convertedJobCount) job(s); \(failedJobCount) failed"
        } else if convertedFileCount > 0 {
            addSummary = "\(convertedFileCount) image(s) converted for \(convertedJobCount) job(s)"
        } else if unchangedFileCount > 0 {
            addSummary = "Selected images already use \(format.label)"
        } else {
            addSummary = "No convertible images found"
        }
    }

