    func copyGalleryNumbersInSaveFolder() {
        guard !isCopyingGalleryNumbers else { return }

        let root = URL(fileURLWithPath: destinationPath, isDirectory: true)
        var isDirectory = ObjCBool(false)
        guard FileManager.default.fileExists(atPath: root.path, isDirectory: &isDirectory), isDirectory.boolValue else {
            addSummary = "Save folder not found"
            return
        }

        isCopyingGalleryNumbers = true
        addSummary = "Scanning gallery numbers..."

        Task.detached(priority: .userInitiated) {
            let numbers = Self.hitomiGalleryNumbers(in: root)
            await MainActor.run {
                self.isCopyingGalleryNumbers = false
                guard !numbers.isEmpty else {
                    self.addSummary = "No gallery numbers found"
                    return
                }

                let pasteboard = NSPasteboard.general
                pasteboard.clearContents()
                self.addSummary = pasteboard.setString(numbers.joined(separator: "\n"), forType: .string)
                    ? "Copied \(numbers.count) gallery ID\(numbers.count == 1 ? "" : "s")"
                    : "Copy failed"
            }
        }
    }

    nonisolated static func browserSourceURL(for source: String) -> URL? {
        guard let url = URL(string: source.trimmed),
              let scheme = url.scheme?.lowercased(),
              scheme == "http" || scheme == "https" else {
            return nil
        }
        return url
    }

