    func saveProxySettings() {
        guard persistProxySettingsForUse() else { return }
        addSummary = proxyEnabled ? "프록시 저장됨" : "프록시 꺼짐"
    }

    func refreshPublicIP() {
        guard !isRefreshingPublicIP else { return }
        guard persistProxySettingsForUse() else {
            publicIPStatus = "프록시 확인 실패: 잘못된 프록시 URL"
            return
        }
        let lookupURL = Self.publicIPLookupURL()
        let settings = NetworkSettings.load()
        isRefreshingPublicIP = true
        publicIPStatus = Self.publicIPCheckingStatus(settings: settings, lookupURL: lookupURL)

        Task { [weak self] in
            do {
                let text = try await HTTPClient.shared.string(from: lookupURL)
                let ip = try Self.publicIPAddress(from: text)
                self?.publicIPStatus = Self.publicIPStatusText(ip: ip, settings: settings, lookupURL: lookupURL)
                self?.addSummary = "공인 IP 업데이트됨"
            } catch {
                self?.publicIPStatus = Self.publicIPFailureStatus(
                    settings: settings,
                    lookupURL: lookupURL,
                    errorDescription: error.localizedDescription
                )
                self?.addSummary = "공인 IP 확인 실패"
            }
            self?.isRefreshingPublicIP = false
        }
    }

    nonisolated static func publicIPLookupURL(environment: [String: String] = ProcessInfo.processInfo.environment) -> URL {
        if let value = environment["HITOMI_NATIVE_PUBLIC_IP_URL"]?.trimmed,
           !value.isEmpty,
           let url = URL(string: value) {
            return url
        }
        return URL(string: "https://api.ipify.org?format=text")!
    }

    nonisolated static func publicIPAddress(from text: String) throws -> String {
        let trimmed = text.trimmed
        if let data = trimmed.data(using: .utf8),
           let object = try? JSONSerialization.jsonObject(with: data) as? [String: Any],
           let value = object["ip"] as? String,
           let normalized = normalizedPublicIPAddress(value) {
            return normalized
        }

        for token in trimmed.split(whereSeparator: { $0.isWhitespace || $0 == "," || $0 == "\"" }) {
            if let normalized = normalizedPublicIPAddress(String(token)) {
                return normalized
            }
        }

        throw NativeDownloadError.unsupported("No public IP address was found.")
    }

    nonisolated static func publicIPCheckingStatus(settings: NetworkSettings, lookupURL: URL) -> String {
        if let proxy = settings.proxyArgument(for: lookupURL) {
            return "\(proxyDisplayName(proxy)) 경유 공인 IP 확인 중..."
        }
        if settings.proxyEnabled && settings.bypassesProxy(for: lookupURL) {
            return "직접 공인 IP 확인 중 (프록시 제외)..."
        }
        return "직접 공인 IP 확인 중..."
    }

    nonisolated static func publicIPStatusText(ip: String, settings: NetworkSettings, lookupURL: URL) -> String {
        if let proxy = settings.proxyArgument(for: lookupURL) {
            return "프록시 공인 IP \(ip) · \(proxyDisplayName(proxy))"
        }
        if settings.proxyEnabled && settings.bypassesProxy(for: lookupURL) {
            return "직접 공인 IP \(ip) (프록시 제외)"
        }
        return "직접 공인 IP \(ip)"
    }

    nonisolated static func publicIPFailureStatus(
        settings: NetworkSettings,
        lookupURL: URL,
        errorDescription: String
    ) -> String {
        if let proxy = settings.proxyArgument(for: lookupURL) {
            return "프록시 공인 IP 확인 실패 · \(proxyDisplayName(proxy)): \(errorDescription)"
        }
        if settings.proxyEnabled && settings.bypassesProxy(for: lookupURL) {
            return "직접 공인 IP 확인 실패 (프록시 제외): \(errorDescription)"
        }
        return "직접 공인 IP 확인 실패: \(errorDescription)"
    }

    private nonisolated static func normalizedPublicIPAddress(_ value: String) -> String? {
        let normalized = value.trimmed.trimmingCharacters(in: CharacterSet(charactersIn: "[](){}<>"))
        guard !normalized.isEmpty else { return nil }
        if normalized.range(of: #"^([0-9]{1,3}\.){3}[0-9]{1,3}$"#, options: .regularExpression) != nil {
            let pieces = normalized.split(separator: ".").compactMap { Int($0) }
            return pieces.count == 4 && pieces.allSatisfy { (0...255).contains($0) } ? normalized : nil
        }
        if normalized.contains(":"),
           normalized.range(of: #"^[A-Fa-f0-9:.%]+$"#, options: .regularExpression) != nil {
            return normalized
        }
        return nil
    }

    private nonisolated static func proxyDisplayName(_ proxy: String) -> String {
        guard let components = URLComponents(string: proxy),
              let scheme = components.scheme,
              let host = components.host else {
            return proxy
        }
        var text = "\(scheme)://\(host)"
        if let port = components.port {
            text += ":\(port)"
        }
        return text
    }

