    @discardableResult
    private func pauseAria2Job(at index: Int, persist: Bool = true) -> Bool {
        guard jobs.indices.contains(index),
              jobs[index].status == .downloading,
              let control = aria2RuntimeProcesses[jobs[index].id],
              !aria2RuntimePausedJobIDs.contains(jobs[index].id),
              control.suspend() else {
            return false
        }

        let jobID = jobs[index].id
        aria2RuntimePausedJobIDs.insert(jobID)
        jobs[index].message = "aria2c paused"
        jobs[index].metadata["aria2_runtime_paused"] = "true"
        if persist {
            persistQueue()
        }
        return true
    }

    @discardableResult
    private func resumeAria2Job(at index: Int, persist: Bool = true) -> Bool {
        guard jobs.indices.contains(index),
              jobs[index].status == .downloading,
              let control = aria2RuntimeProcesses[jobs[index].id],
              aria2RuntimePausedJobIDs.contains(jobs[index].id),
              control.resume() else {
            return false
        }

        let jobID = jobs[index].id
        aria2RuntimePausedJobIDs.remove(jobID)
        jobs[index].message = "Running aria2c"
        jobs[index].metadata["aria2_runtime_paused"] = "false"
        if persist {
            persistQueue()
        }
        return true
    }

    private func cleanupAria2RuntimeControl(for jobID: UUID) {
        aria2RuntimeProcesses.removeValue(forKey: jobID)
        aria2RuntimePausedJobIDs.remove(jobID)
        aria2RuntimeRPCSessions.removeValue(forKey: jobID)
    }

    @discardableResult
    private func applyAria2RuntimeLimitsJob(at index: Int, downloadLimit: String, uploadLimit: String, persist: Bool = true) async -> Bool {
        guard jobs.indices.contains(index),
              jobs[index].status == .downloading,
              let session = aria2RuntimeRPCSessions[jobs[index].id],
              aria2RuntimeProcesses[jobs[index].id]?.isRunning == true,
              !aria2RuntimePausedJobIDs.contains(jobs[index].id) else {
            return false
        }

        let jobID = jobs[index].id
        do {
            let applied = try await Aria2RPCClient.changeSpeedLimits(
                session: session,
                downloadLimit: downloadLimit,
                uploadLimit: uploadLimit
            )
            guard let currentIndex = jobs.firstIndex(where: { $0.id == jobID }) else { return false }
            let down = applied["max_download_limit"] ?? ""
            let up = applied["max_upload_limit"] ?? ""
            jobs[currentIndex].metadata["max_download_limit"] = down
            jobs[currentIndex].metadata["max_upload_limit"] = up
            jobs[currentIndex].metadata["runtime_max_download_limit"] = down
            jobs[currentIndex].metadata["runtime_max_upload_limit"] = up
            jobs[currentIndex].metadata["aria2_runtime_limit_error"] = ""
            jobs[currentIndex].message = Self.aria2RuntimeLimitMessage(downloadLimit: down, uploadLimit: up)
            if persist {
                persistQueue()
            }
            return true
        } catch {
            guard let currentIndex = jobs.firstIndex(where: { $0.id == jobID }) else { return false }
            jobs[currentIndex].metadata["aria2_runtime_limit_error"] = error.localizedDescription
            jobs[currentIndex].message = "aria2 limit update failed"
            if persist {
                persistQueue()
            }
            return false
        }
    }

    private nonisolated static func aria2RuntimeLimitMessage(downloadLimit: String, uploadLimit: String) -> String {
        let parts = [
            downloadLimit.isEmpty ? nil : "down \(downloadLimit)",
            uploadLimit.isEmpty ? nil : "up \(uploadLimit)"
        ].compactMap { $0 }
        return parts.isEmpty ? "aria2c limits cleared" : "aria2c limits: \(parts.joined(separator: ", "))"
    }

    @discardableResult
    private func applyAria2RuntimeFileSelectionJob(at index: Int, selectedFiles: String, persist: Bool = true) async -> Bool {
        guard jobs.indices.contains(index),
