            jobs[currentIndex].metadata["runtime_selected_files"] = files
            jobs[currentIndex].metadata["aria2_runtime_file_selection_error"] = ""
            jobs[currentIndex].message = Self.aria2RuntimeFileSelectionMessage(selectedFiles: files)
            if persist {
                persistQueue()
            }
            return true
        } catch {
            guard let currentIndex = jobs.firstIndex(where: { $0.id == jobID }) else { return false }
