            jobs[currentIndex].message = "aria2 file selection update failed"
            if persist {
                persistQueue()
            }
            return false
        }
    }

    private nonisolated static func aria2RuntimeFileSelectionMessage(selectedFiles: String) -> String {
        selectedFiles.isEmpty ? "aria2c files unchanged" : "aria2c files: \(selectedFiles)"
    }

    @discardableResult
    private func applyAria2RuntimeSeedingJob(
        at index: Int,
        seedTimeMinutes: String,
        seedRatio: String,
        persist: Bool = true
    ) async -> Bool {
        guard jobs.indices.contains(index),
              jobs[index].status == .downloading,
              let session = aria2RuntimeRPCSessions[jobs[index].id],
              aria2RuntimeProcesses[jobs[index].id]?.isRunning == true,
              !aria2RuntimePausedJobIDs.contains(jobs[index].id) else {
            return false
        }

        let jobID = jobs[index].id
        do {
            let applied = try await Aria2RPCClient.changeSeeding(
                session: session,
                seedTimeMinutes: seedTimeMinutes,
                seedRatio: seedRatio
            )
            guard let currentIndex = jobs.firstIndex(where: { $0.id == jobID }) else { return false }
            let seedTime = applied["seed_time_minutes"] ?? "0"
            let ratio = applied["seed_ratio"] ?? ""
            jobs[currentIndex].metadata["seed_time_minutes"] = seedTime
            jobs[currentIndex].metadata["seed_ratio"] = ratio
            jobs[currentIndex].metadata["runtime_seed_time_minutes"] = seedTime
            jobs[currentIndex].metadata["runtime_seed_ratio"] = ratio
            jobs[currentIndex].metadata["aria2_runtime_seed_error"] = ""
            jobs[currentIndex].message = Self.aria2RuntimeSeedingMessage(seedTimeMinutes: seedTime, seedRatio: ratio)
            if persist {
                persistQueue()
            }
            return true
        } catch {
            guard let currentIndex = jobs.firstIndex(where: { $0.id == jobID }) else { return false }
            jobs[currentIndex].metadata["aria2_runtime_seed_error"] = error.localizedDescription
            jobs[currentIndex].message = "aria2 seeding update failed"
            if persist {
                persistQueue()
            }
            return false
        }
    }

    private nonisolated static func aria2RuntimeSeedingMessage(seedTimeMinutes: String, seedRatio: String) -> String {
        let parts = [
            "seed \(seedTimeMinutes)m",
            seedRatio.isEmpty ? nil : "ratio \(seedRatio)"
        ].compactMap { $0 }
        return "aria2c seeding: \(parts.joined(separator: ", "))"
    }

    @discardableResult
    private func loadAria2PeersJob(at index: Int) async -> [Aria2PeerEntry]? {
        guard jobs.indices.contains(index),
              jobs[index].status == .downloading,
              let session = aria2RuntimeRPCSessions[jobs[index].id],
              aria2RuntimeProcesses[jobs[index].id]?.isRunning == true,
              !aria2RuntimePausedJobIDs.contains(jobs[index].id) else {
            aria2PeerEntries = []
            aria2PeerSummary = "No running aria2 job for peers"
            addSummary = "No running aria2 job for peers"
            return nil
        }

        let jobID = jobs[index].id
        do {
            let peers = try await Aria2RPCClient.peerEntries(session: session)
            guard let currentIndex = jobs.firstIndex(where: { $0.id == jobID }) else { return nil }
            aria2PeerEntries = peers
            aria2PeerSummary = Self.aria2PeerSummary(for: peers)
            jobs[currentIndex].metadata["aria2_peer_count"] = String(peers.count)
            jobs[currentIndex].metadata["aria2_runtime_peer_error"] = ""
            addSummary = peers.isEmpty ? "aria2 peers empty" : "aria2 peers updated"
            persistQueue()
            return peers
        } catch {
            guard let currentIndex = jobs.firstIndex(where: { $0.id == jobID }) else { return nil }
            aria2PeerEntries = []
            aria2PeerSummary = "Peer list failed: \(error.localizedDescription)"
            jobs[currentIndex].metadata["aria2_runtime_peer_error"] = error.localizedDescription
            addSummary = "aria2 peer list failed"
            persistQueue()
            return nil
        }
    }

    private nonisolated static func aria2PeerSummary(for peers: [Aria2PeerEntry]) -> String {
        guard !peers.isEmpty else { return "No aria2 peers" }
        let prefix = peers.prefix(4).map(\.summary).joined(separator: ", ")
        let suffix = peers.count > 4 ? ", ..." : ""
        return "\(peers.count) peers: \(prefix)\(suffix)"
    }

    func previewAria2Files() {
        persistExternalToolPaths()
        let urls = extractURLs(from: inputText)
        guard let source = urls.first,
              let url = URL(string: source.trimmed),
              aria2Bridge.canResolve(url) else {
            aria2FileEntries = []
            aria2FileListSummary = "Paste a magnet or .torrent URL"
            return
        }

        let bridge = aria2Bridge
        let headers = requestOptions(for: url)
        aria2FileEntries = []
        aria2FileListSummary = "Reading torrent file list"

        Task { [weak self] in
            _ = await self?.loadAria2FileEntries(from: url, bridge: bridge, headers: headers, jobID: nil)
        }
    }

    @discardableResult
    private func loadAria2FileEntriesJob(at index: Int) async -> [Aria2FileEntry]? {
        guard jobs.indices.contains(index),
              let url = aria2URL(for: jobs[index]) else {
            aria2FileEntries = []
            aria2FileListSummary = "No torrent source for file list"
            addSummary = "No torrent source for file list"
            return nil
        }

        let job = jobs[index]
        let bridge = aria2Bridge
        let headers = requestOptions(for: url)
        return await loadAria2FileEntries(from: url, bridge: bridge, headers: headers, jobID: job.id)
    }

    @discardableResult
    private func loadAria2FileEntries(
        from url: URL,
        bridge: Aria2Bridge,
        headers: HTTPRequestOptions,
        jobID: UUID?
    ) async -> [Aria2FileEntry]? {
        do {
            let entries = try await bridge.listFiles(url: url, headers: headers)
            aria2FileEntries = entries
            aria2FileListSummary = Self.aria2FileListSummary(for: entries)
            if let jobID,
               let currentIndex = jobs.firstIndex(where: { $0.id == jobID }) {
                jobs[currentIndex].metadata["aria2_file_count"] = String(entries.count)
                jobs[currentIndex].metadata["aria2_file_list_error"] = ""
                persistQueue()
            }
            addSummary = "aria2 files listed"
            return entries
        } catch {
            aria2FileEntries = []
            aria2FileListSummary = "File list failed: \(error.localizedDescription)"
            if let jobID,
               let currentIndex = jobs.firstIndex(where: { $0.id == jobID }) {
                jobs[currentIndex].metadata["aria2_file_list_error"] = error.localizedDescription
                persistQueue()
            }
            addSummary = "aria2 file list failed"
            return nil
        }
    }

    private func aria2URL(for job: DownloadJob) -> URL? {
        let source = job.source.trimmed
        guard !source.isEmpty,
              let url = URL(string: source),
              aria2Bridge.canResolve(url) else {
            return nil
        }
        return url
    }

