        }
    }

    private func persistAutoRecordSettings() {
        autoRecordURLsText = normalizedAutoRecordURLsText(from: autoRecordURLsText)
        let interval = Self.normalizedAutoRecordIntervalMinutes(from: autoRecordIntervalMinutesString)
        autoRecordIntervalMinutesString = String(interval)
        UserDefaults.standard.set(autoRecordEnabled, forKey: "autoRecordEnabled")
        UserDefaults.standard.set(autoRecordPaused, forKey: "autoRecordPaused")
        UserDefaults.standard.set(autoRecordURLsText, forKey: "autoRecordURLsText")
        UserDefaults.standard.set(interval, forKey: "autoRecordIntervalMinutes")
    }

    private func syncAutoRecordMonitor() {
        autoRecordTask?.cancel()
        autoRecordTask = nil

        guard autoRecordEnabled else {
            isAutoRecordChecking = false
            autoRecordStatus = "자동 녹화 꺼짐"
            return
        }
        guard !autoRecordPaused else {
            isAutoRecordChecking = false
            autoRecordStatus = "자동 녹화 일시 정지"
            return
        }

        autoRecordStatus = "자동 녹화 대기 중"
        autoRecordTask = Task { [weak self] in
            while !Task.isCancelled {
                _ = await MainActor.run {
                    self?.performAutoRecordCheck(startQueueIfNeeded: true)
                }

                let delay = await MainActor.run { () -> UInt64 in
                    guard let self else { return Self.autoRecordIntervalNanoseconds(fromMinutes: 10) }
                    return Self.autoRecordIntervalNanoseconds(from: self.autoRecordIntervalMinutesString)
                }
                do {
                    try await Task.sleep(nanoseconds: delay)
                } catch {
                    break
                }
            }
        }
    }

    @discardableResult
    private func performAutoRecordCheck(startQueueIfNeeded: Bool) -> Int {
        guard !isAutoRecordChecking else { return 0 }
        guard autoRecordEnabled else {
            autoRecordStatus = "자동 녹화 꺼짐"
            return 0
        }
        guard !autoRecordPaused else {
            autoRecordStatus = "자동 녹화 일시 정지"
            return 0
        }

        let urls = autoRecordURLs()
        guard !urls.isEmpty else {
            autoRecordStatus = "자동 녹화 URL 필요"
            return 0
        }

        isAutoRecordChecking = true
        autoRecordStatus = "자동 녹화 확인 중..."
        defer { isAutoRecordChecking = false }

        let newJobs = jobsForAdding(
            urls,
            metadata: [
                "auto_record": "true",
                "recording": "true"
            ],
            titleSuffix: " [Auto]"
        )
        let added = newJobs.count
        if added > 0 {
            insertAddedJobsAtTop(newJobs)
            persistQueue()
            autoRecordStatus = "자동 녹화 \(added)개 대기열 추가"
            addSummary = "자동 녹화: \(added)개 대기열 추가"
            if startQueueIfNeeded, queueTask == nil {
                startQueue(addingInput: false)
            }
        } else {
            autoRecordStatus = addSummary.trimmed.isEmpty
                ? "자동 녹화 확인: 새 URL 없음"
                : "자동 녹화 확인: \(addSummary)"
        }
        return added
    }

    private func autoRecordURLs() -> [String] {
        extractMonitorableURLs(from: autoRecordURLsText)
    }

    private func normalizedAutoRecordURLsText(from raw: String) -> String {
        var seen = Set<String>()
        return extractMonitorableURLs(from: raw)
            .filter { seen.insert($0).inserted }
            .joined(separator: "\n")
    }

    nonisolated static func normalizedAutoRecordIntervalMinutes(from raw: String) -> Int {
        let minutes = autoRecordIntervalMinutes(from: raw) ?? 10
        return min(1_440, max(1, Int(ceil(minutes))))
    }

    nonisolated static func autoRecordIntervalNanoseconds(from raw: String) -> UInt64 {
        autoRecordIntervalNanoseconds(fromMinutes: normalizedAutoRecordIntervalMinutes(from: raw))
    }

    private nonisolated static func autoRecordIntervalMinutes(from raw: String) -> Double? {
        let value = raw.trimmed.lowercased()
        guard !value.isEmpty else { return nil }

        if value.contains(":") {
            return durationSeconds(from: value).map { $0 / 60 }
        }
        if value.range(of: #"[a-z]"#, options: .regularExpression) != nil {
            return compoundDurationSeconds(from: value).map { $0 / 60 }
        }
        guard let minutes = Double(value), minutes >= 0 else {
            return nil
        }
        return minutes
    }

    private nonisolated static func autoRecordIntervalNanoseconds(fromMinutes minutes: Int) -> UInt64 {
        UInt64(minutes) * 60 * 1_000_000_000
    }

    nonisolated static func normalizedM3U8SegmentDelayMilliseconds(from raw: String) -> Int {
        let value = Int(raw.trimmed) ?? 0
        return min(60_000, max(0, value))
    }

    nonisolated static func m3u8SegmentRateLimitNanoseconds(from raw: String) -> UInt64 {
        UInt64(normalizedM3U8SegmentDelayMilliseconds(from: raw)) * 1_000_000
    }

