    func sourceArchiveMode(for sourceID: String) -> SourceArchiveMode {
        let normalized = DownloadSourceFolderProfile.normalizedSourceID(sourceID)
        if let mode = sourceArchiveModes[normalized] {
            return mode
        }
        if DownloadSourceFolderProfile.isSettingsSourceID(normalized) {
            return .pass
        }
        guard archiveCompletedFolders else { return .pass }
        return archiveFileFormat == .cbz ? .cbz : .zip
    }

    func sourceArchiveDeletesOriginal(for sourceID: String) -> Bool {
        let normalized = DownloadSourceFolderProfile.normalizedSourceID(sourceID)
        if let deleteOriginal = sourceArchiveDeleteOriginal[normalized] {
            return deleteOriginal
        }
        if DownloadSourceFolderProfile.isSettingsSourceID(normalized) {
            return false
        }
        return archiveCompletedFolders && deleteOriginalFolderAfterArchiving
    }

