    func setArchiveCompletedFolders(_ enabled: Bool) {
        archiveCompletedFolders = enabled
        if !enabled {
            deleteOriginalFolderAfterArchiving = false
        }
        let mode: SourceArchiveMode = enabled
            ? (archiveFileFormat == .cbz ? .cbz : .zip)
            : .pass
        for profile in sourceFolderProfiles where profile.supportsFolderArchive {
            sourceArchiveModes[profile.id] = mode
        }
        persistArchiveSettings()
        persistSourceArchiveSettings()
        addSummary = enabled ? "\(archiveFileFormat.label) archive on" : "Archive folders off"
    }

    func setArchiveFileFormat(_ format: ArchiveFileFormat) {
        archiveFileFormat = format
        let mode: SourceArchiveMode = format == .cbz ? .cbz : .zip
        for profile in sourceFolderProfiles
            where profile.supportsFolderArchive && sourceArchiveMode(for: profile.id) != .pass {
            sourceArchiveModes[profile.id] = mode
        }
        persistArchiveSettings()
        persistSourceArchiveSettings()
        addSummary = "Archive format: \(format.label)"
    }

    func setDeleteOriginalFolderAfterArchiving(_ enabled: Bool) {
        deleteOriginalFolderAfterArchiving = enabled && archiveCompletedFolders
        for profile in sourceFolderProfiles
            where profile.supportsFolderArchive && sourceArchiveMode(for: profile.id) != .pass {
            sourceArchiveDeleteOriginal[profile.id] = deleteOriginalFolderAfterArchiving
        }
        persistArchiveSettings()
        persistSourceArchiveSettings()
        addSummary = deleteOriginalFolderAfterArchiving ? "Delete after archive on" : "Delete after archive off"
    }

