    func scanDuplicateImages() {
        guard !isScanningDuplicateImages else { return }
        let roots = duplicateImageScanRootURLs()
        let similarityPercent = duplicateImageSimilarityPercent
        let excludeSameSource = duplicateImageExcludeSameSource
        duplicateImageGroups = []
        duplicateImageSummary = "Scanning images..."
        isScanningDuplicateImages = true

        Task.detached(priority: .userInitiated) {
            do {
                let groups = try Self.duplicateImageGroups(
                    in: roots,
                    similarityPercent: similarityPercent,
                    excludeSameSource: excludeSameSource
                )
                await MainActor.run {
                    self.duplicateImageGroups = groups
                    let selection = Self.duplicateImageSelection(
                        current: self.selectedDuplicateImagePath,
                        groups: groups,
                        minimumSimilarityPercent: similarityPercent
                    )
                    self.selectedDuplicateImagePath = selection.selectedPath
                    self.autoSelectedDuplicateImagePath = selection.autoSelectedPath
                    self.isScanningDuplicateImages = false
                    self.duplicateImageSummary = Self.duplicateImageSummary(
                        for: groups,
                        autoSelectedPath: selection.autoSelectedPath
                    )
                }
            } catch {
                await MainActor.run {
                    self.duplicateImageGroups = []
                    self.selectedDuplicateImagePath = ""
                    self.autoSelectedDuplicateImagePath = ""
                    self.isScanningDuplicateImages = false
                    self.duplicateImageSummary = "Duplicate scan failed: \(error.localizedDescription)"
                }
            }
        }
    }

