    func importCookies() {
        let panel = NSOpenPanel()
        panel.canChooseFiles = true
        panel.canChooseDirectories = false
        panel.allowsMultipleSelection = false
        panel.allowedContentTypes = [.plainText, .text]

        guard panel.runModal() == .OK, let url = panel.url else { return }

        Task {
            do {
                let text = try String(contentsOf: url, encoding: .utf8)
                let result = await CookieStore.shared.importText(text)
                await MainActor.run {
                    self.cookieSummary = "\(result.imported) cookies"
                    if result.skipped > 0 {
                        self.cookieSummary += ", \(result.skipped) skipped"
                    }
                }
            } catch {
                await MainActor.run {
                    self.cookieSummary = "Cookie import failed"
                }
            }
        }
    }

    func importBrowserCookies() {
        let panel = NSOpenPanel()
        panel.canChooseFiles = true
        panel.canChooseDirectories = false
        panel.allowsMultipleSelection = false
        panel.message = "Choose a Firefox cookies.sqlite file or Chromium Cookies database."

        guard panel.runModal() == .OK, let url = panel.url else { return }

        Task {
            do {
                let result = try await CookieStore.shared.importBrowserDatabase(from: url)
                await MainActor.run {
                    self.cookieSummary = "\(result.imported) \(result.browserName) cookies"
                    let skipped = result.skipped + result.encryptedSkipped
                    if skipped > 0 {
                        self.cookieSummary += ", \(skipped) skipped"
                    }
                }
            } catch {
                await MainActor.run {
                    self.cookieSummary = "Browser cookie import failed"
                }
            }
        }
    }

