        Task {
            do {
                let result = try await CookieStore.shared.importDetectedBrowserDatabases()
                await MainActor.run {
                    self.cookieSummary = Self.browserCookieSummary(imported: result.imported, skipped: result.skipped)
                    if result.profilesScanned > 1 {
                        self.cookieSummary += " from \(result.profilesScanned) profiles"
