    nonisolated static func jobAccessReaction(for job: DownloadJob) -> JobAccessReaction? {
        let authenticationKey = explicitAuthenticationProviderKey(for: job)
        if let authenticationKey {
            return .login(provider: authenticationProviderName(for: authenticationKey, job: job))
        }

        let message = [job.message, job.metadata["last_error"] ?? ""]
            .joined(separator: " ")
            .trimmed
            .lowercased()
        let cookieFlag = ["cookie_required", "cookies_required", "cookie_expired"].contains { key in
            guard let value = job.metadata[key]?.trimmed.lowercased() else { return false }
            return ["1", "true", "yes", "on", "required", "expired"].contains(value)
        }
        let needsAttention = [
            "required", "waiting", "missing", "not found", "expired", "update", "refresh", "needed",
            "필요", "대기", "없", "만료", "업데이트"
        ].contains { message.contains($0) }

        if cookieFlag || ((message.contains("cookie") || message.contains("쿠키")) && needsAttention) {
            return .cookies
        }
        if (message.contains("login") || message.contains("authentication") || message.contains("로그인")) &&
            needsAttention {
            let providerKey = inferredAuthenticationProviderKey(for: job)
            let provider = authenticationProviderName(for: providerKey ?? "", job: job)
            return .login(provider: provider)
        }
        return nil
    }

    func openAccessHelp(for job: DownloadJob) {
        let current = jobs.first(where: { $0.id == job.id }) ?? job
        guard let reaction = Self.jobAccessReaction(for: current) else {
            addSummary = "No login or cookie action for this job"
            return
        }

        switch reaction {
        case .cookies:
            settingsWindowFilter = ""
            openSettingsWindow(category: .network)
            addSummary = "Update cookies in Network settings"
        case .login:
            let authenticationKey =
                Self.explicitAuthenticationProviderKey(for: current) ??
                Self.inferredAuthenticationProviderKey(for: current)
            guard let url = Self.loginBrowserURL(for: current, authenticationKey: authenticationKey) else {
                addSummary = "No login URL for this job"
                return
            }
            openLoginBrowser(url: url, authenticationKey: authenticationKey)
        }
    }

    private func openLoginBrowser(url: URL, authenticationKey: String?) {
        switch authenticationKey {
        case "pixiv":
            presentPixivLoginBrowser()
            addSummary = "Pixiv login browser opened"
            return
        case "chzzk":
            presentChzzkLoginBrowser()
            addSummary = "Chzzk login browser opened"
            return
        case "naver-cafe":
            presentNaverCafeLoginBrowser()
            addSummary = "Naver Cafe login browser opened"
            return
        case "twitter":
            presentTwitterLoginBrowser()
            addSummary = "Twitter/X login browser opened"
            return
        case "pornhub-premium":
            presentPornhubLoginBrowser()
            addSummary = "Pornhub Premium login browser opened"
            return
        case "arcalive":
            presentArcaliveLoginBrowser(loginURL: Self.arcaliveLoginURL)
            addSummary = "Arcalive login browser opened"
            return
        default:
            break
        }

        if Self.isPixivWebURL(url) {
            presentPixivLoginBrowser()
            addSummary = "Pixiv login browser opened"
            return
        }
        if Self.isChzzkWebURL(url) {
            presentChzzkLoginBrowser()
            addSummary = "Chzzk login browser opened"
            return
        }
        if Self.isNaverCafeWebURL(url) {
            presentNaverCafeLoginBrowser()
            addSummary = "Naver Cafe login browser opened"
            return
        }
        if Self.isTwitterWebURL(url) {
            presentTwitterLoginBrowser()
            addSummary = "Twitter/X login browser opened"
            return
        }
        if Self.isPornhubPremiumWebURL(url) {
            presentPornhubLoginBrowser()
            addSummary = "Pornhub Premium login browser opened"
            return
        }
        if Self.isArcaliveWebURL(url) {
            presentArcaliveLoginBrowser(loginURL: url)
            addSummary = "Arcalive login browser opened"
            return
        }

#if TESTING
        if let testingLoginBrowserOpenHandler {
            testingLoginBrowserOpenHandler(url)
            addSummary = "Login browser opened"
            return
        }
#endif
        LoginBrowserWindowController.open(url: url) { [weak self] imported, skipped in
            guard let self else { return }
            self.cookieSummary = Self.browserCookieSummary(imported: imported, skipped: skipped)
            self.addSummary = imported > 0 ? "Login cookies saved" : "No login cookies found"
        }
        addSummary = "Login browser opened"
    }

    private func presentTwitterLoginBrowser() {
        let loginURL = Self.twitterLoginURL
#if TESTING
        if let testingLoginBrowserOpenHandler {
            testingLoginBrowserOpenHandler(loginURL)
            return
        }
#endif
        LoginBrowserWindowController.open(
            url: loginURL,
            reuseKey: "twitter-login",
            autoImportPolicy: .twitterSession
        ) { [weak self] imported, skipped in
            self?.handleTwitterLoginCookiesImported(imported: imported, skipped: skipped)
        }
    }

    private func handleTwitterLoginCookiesImported(imported: Int, skipped: Int) {
        cookieSummary = Self.browserCookieSummary(imported: imported, skipped: skipped)

        Task { @MainActor [weak self] in
            guard let self else { return }
            async let authTokenValue = CookieStore.shared.cookieValue(named: "auth_token", for: Self.twitterCookieURL)
            async let csrfValue = CookieStore.shared.cookieValue(named: "ct0", for: Self.twitterCookieURL)
            let (authToken, csrf) = await (authTokenValue, csrfValue)
            guard authToken?.trimmed.isEmpty == false, csrf?.trimmed.isEmpty == false else {
                self.addSummary = "Twitter/X login cookies not found"
                return
            }
            let waitingCount = self.twitterLoginContinuations.count
            if waitingCount == 0 {
                self.addSummary = "Twitter/X login saved"
            } else {
                self.addSummary = waitingCount == 1
                    ? "Twitter/X login saved - retrying download"
                    : "Twitter/X login saved - retrying \(waitingCount) downloads"
            }
            self.resumeAllTwitterLoginWaits()
        }
    }

    private func waitForTwitterLogin(at index: Int) async {
        guard jobs.indices.contains(index) else { return }
        let jobID = jobs[index].id
        jobs[index].status = .resolving
        jobs[index].message = "Waiting for Twitter/X login"
        jobs[index].metadata["authentication_waiting"] = "twitter"
        persistQueue()
        addSummary = "Twitter/X login required"

        await withTaskCancellationHandler {
            await withCheckedContinuation { continuation in
                if Task.isCancelled {
                    continuation.resume()
                    return
                }
                if let previous = twitterLoginContinuations.updateValue(continuation, forKey: jobID) {
                    previous.resume()
                }
                presentTwitterLoginBrowser()
            }
        } onCancel: {
            Task { @MainActor [weak self] in
                self?.resumeTwitterLoginWait(for: jobID)
            }
        }

        if let currentIndex = jobs.firstIndex(where: { $0.id == jobID }) {
            jobs[currentIndex].metadata.removeValue(forKey: "authentication_waiting")
            if jobs[currentIndex].status != .cancelled {
                jobs[currentIndex].message = "Reading Twitter/X media"
            }
            persistQueue()
        }
    }

    private func resumeTwitterLoginWait(for jobID: UUID) {
        twitterLoginContinuations.removeValue(forKey: jobID)?.resume()
    }

    private func resumeAllTwitterLoginWaits() {
        let continuations = Array(twitterLoginContinuations.values)
        twitterLoginContinuations.removeAll()
        continuations.forEach { $0.resume() }
    }

#if TESTING
    func testingNotifyTwitterLoginCookiesImported(imported: Int, skipped: Int = 0) {
        handleTwitterLoginCookiesImported(imported: imported, skipped: skipped)
    }

    func testingResumeTwitterLoginWaits() {
        resumeAllTwitterLoginWaits()
    }
#endif

