    nonisolated static func loginBrowserURL(inputText: String, jobs: [DownloadJob]) -> URL? {
        if let url = firstWebURL(from: inputText) {
            return url
        }
        for job in jobs {
            if let url = URL(string: normalizedInputToken(job.source.trimmed)),
               let scheme = url.scheme?.lowercased(),
               scheme == "http" || scheme == "https" {
                return url
            }
        }
        return URL(string: "https://hitomi.la")
    }

    private nonisolated static func loginBrowserURL(
        for job: DownloadJob,
        authenticationKey: String?
    ) -> URL? {
        switch authenticationKey {
        case "pixiv": return pixivLoginURL
        case "chzzk": return chzzkLoginURL
        case "naver-cafe": return naverCafeLoginURL
        case "twitter": return twitterLoginURL
        case "pornhub-premium": return pornhubPremiumLoginURL
        case "arcalive": return arcaliveLoginURL
        default:
            return firstWebURL(from: job.source)
        }
    }

    private nonisolated static func explicitAuthenticationProviderKey(for job: DownloadJob) -> String? {
        let explicit = (job.metadata["authentication_waiting"] ?? "").trimmed.lowercased()
        if ["pixiv", "chzzk", "naver-cafe", "twitter", "pornhub-premium", "arcalive"].contains(explicit) {
            return explicit
        }
        return nil
    }

    private nonisolated static func inferredAuthenticationProviderKey(for job: DownloadJob) -> String? {
        guard let url = firstWebURL(from: job.source) else { return nil }
        if isPixivWebURL(url) { return "pixiv" }
        if isChzzkWebURL(url) { return "chzzk" }
        if isNaverCafeWebURL(url) { return "naver-cafe" }
        if isTwitterWebURL(url) { return "twitter" }
        if isPornhubPremiumWebURL(url) { return "pornhub-premium" }
        if isArcaliveWebURL(url) { return "arcalive" }
        return nil
    }

    private nonisolated static func authenticationProviderName(
        for key: String,
        job: DownloadJob
    ) -> String {
        switch key {
        case "pixiv": return "Pixiv"
        case "chzzk": return "Chzzk"
        case "naver-cafe": return "Naver Cafe"
        case "twitter": return "Twitter/X"
        case "pornhub-premium": return "Pornhub Premium"
        case "arcalive": return "Arcalive"
        default:
            let site = (job.metadata["site"] ?? "").trimmed
            if !site.isEmpty { return site }
            return firstWebURL(from: job.source)?.host ?? ""
        }
    }

