    private nonisolated static func isPixivWebURL(_ url: URL) -> Bool {
        guard let host = url.host?.lowercased() else { return false }
        return host == "pixiv.net" || host.hasSuffix(".pixiv.net") ||
            host == "pixiv.test" || host.hasSuffix(".pixiv.test")
    }

    private nonisolated static func isChzzkWebURL(_ url: URL) -> Bool {
        guard let host = url.host?.lowercased() else { return false }
        return host == "chzzk.naver.com" || host.hasSuffix(".chzzk.naver.com") ||
            host == "chzzk.naver.test" || host.hasSuffix(".chzzk.naver.test") ||
            host == "nid.naver.com" || host.hasSuffix(".nid.naver.com")
    }

    private nonisolated static func isNaverCafeWebURL(_ url: URL) -> Bool {
        guard let host = url.host?.lowercased() else { return false }
        return host == "cafe.naver.com" || host.hasSuffix(".cafe.naver.com") ||
            host == "cafe.naver.test" || host.hasSuffix(".cafe.naver.test")
    }

    private nonisolated static func isTwitterWebURL(_ url: URL) -> Bool {
        guard let host = url.host?.lowercased() else { return false }
        return host == "x.com" || host.hasSuffix(".x.com") ||
            host == "twitter.com" || host.hasSuffix(".twitter.com") ||
            host == "x.test" || host.hasSuffix(".x.test") ||
            host == "twitter.test" || host.hasSuffix(".twitter.test")
    }

    private nonisolated static func isPornhubPremiumWebURL(_ url: URL) -> Bool {
        guard let host = url.host?.lowercased() else { return false }
        return host == "pornhubpremium.com" || host.hasSuffix(".pornhubpremium.com") ||
            host == "pornhubpremium.net" || host.hasSuffix(".pornhubpremium.net") ||
            host == "pornhubpremium.org" || host.hasSuffix(".pornhubpremium.org")
    }

    private nonisolated static func isArcaliveWebURL(_ url: URL) -> Bool {
        guard let host = url.host?.lowercased() else { return false }
        return host == "arca.live" || host.hasSuffix(".arca.live") ||
            host == "arca.test" || host.hasSuffix(".arca.test")
    }

    private nonisolated static func firstWebURL(from text: String) -> URL? {
        for rawLine in text.components(separatedBy: .newlines) {
            let normalized = normalizedInputToken(rawLine.trimmed)
            guard let url = URL(string: normalized),
                  let scheme = url.scheme?.lowercased(),
                  scheme == "http" || scheme == "https" else {
                continue
            }
            return url
        }
        return nil
    }

    private nonisolated static func browserCookieSummary(imported: Int, skipped: Int) -> String {
        skipped > 0
            ? "브라우저 쿠키 \(imported)개 · 건너뜀 \(skipped)개"
            : "브라우저 쿠키 \(imported)개"
    }

    private nonisolated static func storedCookieSummary(count: Int) -> String {
        count == 0 ? "쿠키 없음" : "쿠키 \(count)개"
    }

    private func refreshCookieSummary() async {
