    func revealOutput(for job: DownloadJob) {
        let outputPath = repairedOutputPath(for: job)
        guard let url = Self.revealURL(forOutputPath: outputPath) else { return }
        NSWorkspace.shared.activateFileViewerSelecting([url])
    }

    func outputRevealURLs(startingAt job: DownloadJob) -> [URL] {
        var seenPaths = Set<String>()
        return contextualJobs(startingAt: job).compactMap { selected -> URL? in
            let outputPath = repairedOutputPath(for: selected)
            guard let existing = QueueThumbnailProvider.existingOutputURL(
                forOutputPath: outputPath,
                destinationPath: destinationPath
            ), let url = Self.revealURL(forOutputPath: existing.path) else {
                return nil
            }
            let key = url.resolvingSymlinksInPath().standardizedFileURL.path
            guard seenPaths.insert(key).inserted else { return nil }
            return url
        }
    }

    func revealOutputs(startingAt job: DownloadJob) {
        let urls = outputRevealURLs(startingAt: job)
        guard !urls.isEmpty else {
            addSummary = "No output folder found"
            return
        }
        NSWorkspace.shared.activateFileViewerSelecting(urls)
        addSummary = urls.count == 1 ? "Output revealed" : "Outputs revealed for \(urls.count) jobs"
    }

    func canRevealOutputs(startingAt job: DownloadJob) -> Bool {
        contextualJobs(startingAt: job).contains { selected in
            let output = QueueThumbnailProvider.existingOutputURL(
                forOutputPath: selected.outputPath,
                destinationPath: destinationPath
            )
            return output.flatMap { Self.revealURL(forOutputPath: $0.path) } != nil
        }
    }

    func openFirstOutputFile(for job: DownloadJob) {
        let outputPath = repairedOutputPath(for: job)
        guard let url = Self.firstOutputOpenURL(forOutputPath: outputPath) else {
            addSummary = "No output file found"
            return
        }
        NSWorkspace.shared.open(url)
        addSummary = "Output file opened"
    }

    func openArchiveOutput(for job: DownloadJob) {
        if let artifact = JobArchiveArtifact.existing(for: job) {
            NSWorkspace.shared.open(artifact.url)
            addSummary = "\(artifact.format.label) archive opened"
            return
        }

        if let fallback = Self.firstRetainedArchiveOutputURL(for: job) {
            NSWorkspace.shared.open(fallback)
            addSummary = "Archive missing; downloaded file opened"
            return
        }

        addSummary = "No archive or downloaded file found"
    }

    nonisolated static func firstRetainedArchiveOutputURL(
        for job: DownloadJob,
        fileManager: FileManager = .default
    ) -> URL? {
        var candidatePaths: [String] = []
        if let archivedFolderPath = job.metadata["archived_folder_path"]?.trimmed,
           !archivedFolderPath.isEmpty {
            candidatePaths.append(archivedFolderPath)
        }

        let outputURL = URL(fileURLWithPath: job.outputPath.trimmed)
        if ArchiveFileFormat(rawValue: outputURL.pathExtension.lowercased()) != nil {
            candidatePaths.append(outputURL.deletingPathExtension().path)
        }

        var checkedPaths = Set<String>()
        for path in candidatePaths {
            let normalizedPath = URL(fileURLWithPath: path).standardizedFileURL.path
            guard checkedPaths.insert(normalizedPath).inserted,
                  let output = firstOutputOpenURL(
                    forOutputPath: normalizedPath,
                    fileManager: fileManager
                  ) else {
                continue
            }
            return output
        }
        return nil
    }

    func openFirstOutputFiles(startingAt job: DownloadJob) {
        let urls = contextualJobs(startingAt: job).compactMap { selected -> URL? in
            let outputPath = repairedOutputPath(for: selected)
            return Self.firstOutputOpenURL(forOutputPath: outputPath)
        }
        guard !urls.isEmpty else {
            addSummary = "No output file found"
            return
        }
        if urls.count > 10 {
            let alert = NSAlert()
            alert.alertStyle = .warning
            alert.messageText = AppLocalization.format(
                "Open the first file for %@ tasks.",
                language: interfaceLanguage,
                String(urls.count)
            )
            alert.informativeText = AppLocalization.text("계속하시겠습니까?", language: interfaceLanguage)
            alert.addButton(withTitle: AppLocalization.text("열기", language: interfaceLanguage))
            alert.addButton(withTitle: AppLocalization.text("취소", language: interfaceLanguage))
            guard alert.runModal() == .alertFirstButtonReturn else { return }
        }
        for url in urls {
            NSWorkspace.shared.open(url)
        }
        addSummary = urls.count == 1
            ? "Output file opened"
            : "First output file opened for \(urls.count) jobs"
    }

    func canOpenFirstOutputFile(for job: DownloadJob) -> Bool {
        guard let output = QueueThumbnailProvider.existingOutputURL(
            forOutputPath: job.outputPath,
            destinationPath: destinationPath
        ) else {
            return false
        }
        return Self.firstOutputOpenURL(forOutputPath: output.path) != nil
    }

    func canOpenFirstOutputFiles(startingAt job: DownloadJob) -> Bool {
        contextualJobs(startingAt: job).contains { canOpenFirstOutputFile(for: $0) }
    }

    func contextualJobs(startingAt job: DownloadJob) -> [DownloadJob] {
        guard jobs.contains(where: {
            $0.id == job.id && !Self.isPendingQueueRemoval($0)
        }) else {
            return []
        }
        let targetIDs = selectedJobIDs.contains(job.id) ? selectedJobIDs : Set([job.id])
        return jobs.filter {
            targetIDs.contains($0.id) && !Self.isPendingQueueRemoval($0)
        }
    }

    private func repairedOutputPath(for job: DownloadJob) -> String {
        guard let output = QueueThumbnailProvider.existingOutputURL(
            forOutputPath: job.outputPath,
            destinationPath: destinationPath
        ) else {
            return job.outputPath
        }
        guard output.path != job.outputPath,
              let index = jobs.firstIndex(where: { $0.id == job.id }) else {
            return output.path
        }
        jobs[index].outputPath = output.path
        persistQueue()
        return output.path
    }

    func createPDF(for job: DownloadJob) {
        guard let index = jobs.firstIndex(where: { $0.id == job.id }) else { return }
        do {
            let pdfURL = try Self.createPDF(fromOutputPath: jobs[index].outputPath, title: jobs[index].title)
            jobs[index].metadata["pdf_path"] = pdfURL.path
            jobs[index].metadata["pdf_created_at"] = ISO8601DateFormatter().string(from: Date())
            jobs[index].message = "PDF created"
            persistQueue()
            addSummary = "PDF created: \(pdfURL.lastPathComponent)"
        } catch {
            addSummary = "PDF failed: \(error.localizedDescription)"
        }
    }

    func canCreatePDF(for job: DownloadJob) -> Bool {
        Self.pdfImageSources(fromOutputPath: job.outputPath).isEmpty == false
    }

    func openOutputBrowserView(for job: DownloadJob) {
        guard canOpenOutputBrowserView(for: job) else {
            addSummary = "No browser-viewable output"
            return
        }
        guard ensureHTTPAPIAvailableForBrowserView(),
              let url = Self.browserViewURL(
                baseURLString: httpAPIBaseURLString(),
                jobID: job.id,
                password: httpAPIPassword
              ) else {
            addSummary = "Browser view unavailable"
            return
        }

        NSWorkspace.shared.open(url)
        addSummary = "Browser view opened"
    }

    func openOutputBrowserView(startingAt job: DownloadJob) {
        openOutputBrowserView(for: contextualJobs(startingAt: job))
    }

    func openOutputBrowserView(for selectedJobs: [DownloadJob]) {
        let selectedIDs = Set(selectedJobs.map(\.id))
        let viewableJobs = jobs.filter { selectedIDs.contains($0.id) && canOpenOutputBrowserView(for: $0) }
        guard !viewableJobs.isEmpty else {
            addSummary = "No browser-viewable output"
            return
        }
        guard ensureHTTPAPIAvailableForBrowserView(),
              let url = Self.browserViewURL(
                baseURLString: httpAPIBaseURLString(),
                jobIDs: viewableJobs.map(\.id),
                password: httpAPIPassword
              ) else {
            addSummary = "Browser view unavailable"
            return
        }

        NSWorkspace.shared.open(url)
        addSummary = viewableJobs.count == 1 ? "Browser view opened" : "Browser view opened for \(viewableJobs.count) jobs"
    }

    func canOpenOutputBrowserView(for job: DownloadJob) -> Bool {
        !apiOutputFiles(for: job).isEmpty
    }

    func canOpenOutputBrowserView(for selectedJobs: [DownloadJob]) -> Bool {
        selectedJobs.contains { canOpenOutputBrowserView(for: $0) }
    }

    func canOpenOutputBrowserView(startingAt job: DownloadJob) -> Bool {
        canOpenOutputBrowserView(for: contextualJobs(startingAt: job))
    }

    private func resolvedOutputPath(for job: DownloadJob) -> String {
        QueueThumbnailProvider.existingOutputURL(
            forOutputPath: job.outputPath,
            destinationPath: destinationPath
        )?.path ?? job.outputPath
    }

    private func resolvedOutputDeletionCandidates(for job: DownloadJob) -> [OutputDeletionCandidate] {
        var resolvedJob = job
        resolvedJob.outputPath = resolvedOutputPath(for: job)
        return Self.outputDeletionCandidates(for: resolvedJob)
    }

    func canDeleteOutput(for job: DownloadJob) -> Bool {
        !isActive(job.status) && !job.isLocked && !resolvedOutputDeletionCandidates(for: job).isEmpty
    }

    func canDeleteOutputsAndJobs(startingAt job: DownloadJob) -> Bool {
        return contextualJobs(startingAt: job).contains { selected in
            !selected.isLocked &&
                !Self.isPendingQueueRemoval(selected)
        }
    }

    func canMoveOutput(for job: DownloadJob) -> Bool {
        !isActive(job.status) &&
            !job.isLocked &&
            !imageConversionJobIDs.contains(job.id) &&
            !resolvedOutputDeletionCandidates(for: job).isEmpty
    }

    func canMoveOutputs(for selectedJobs: [DownloadJob]) -> Bool {
        selectedJobs.contains { canMoveOutput(for: $0) }
    }

    func canMoveOutputs(startingAt job: DownloadJob) -> Bool {
        canMoveOutputs(for: contextualJobs(startingAt: job))
    }

    func beginMovingOutputs(startingAt job: DownloadJob) {
        beginMovingOutputs(for: contextualJobs(startingAt: job))
    }

    func beginMovingOutput(for job: DownloadJob) {
        guard let current = jobs.first(where: { $0.id == job.id }) else { return }
        guard !isActive(current.status) else {
            addSummary = "Cancel active jobs before moving output"
            return
        }
        guard !current.isLocked else {
            addSummary = "Unlock job before moving output"
            return
        }
        guard !imageConversionJobIDs.contains(current.id) else {
            addSummary = "Wait for image conversion before moving output"
            return
        }
        guard !resolvedOutputDeletionCandidates(for: current).isEmpty else {
            addSummary = "No output files found"
            return
        }

        let panel = NSOpenPanel()
        panel.title = "Move Output"
        panel.message = "Choose a destination folder for this output."
        panel.prompt = "Move"
        panel.canChooseFiles = false
        panel.canChooseDirectories = true
        panel.canCreateDirectories = true
        panel.allowsMultipleSelection = false
        panel.directoryURL = URL(fileURLWithPath: destinationPath, isDirectory: true)

        guard panel.runModal() == .OK, let destination = panel.url else { return }
        moveOutputs(for: [current], to: destination)
    }

    func beginMovingOutputs(for selectedJobs: [DownloadJob]) {
        let selectedIDs = Set(selectedJobs.map(\.id))
        let current = jobs.filter { selectedIDs.contains($0.id) }
        guard !current.isEmpty else { return }
        guard canMoveOutputs(for: current) else {
            if current.contains(where: { isActive($0.status) }) {
                addSummary = "Cancel active jobs before moving output"
            } else if current.contains(where: \.isLocked) {
                addSummary = "Unlock job before moving output"
            } else if current.contains(where: { imageConversionJobIDs.contains($0.id) }) {
                addSummary = "Wait for image conversion before moving output"
            } else {
                addSummary = "No movable output found"
            }
            return
        }

        let panel = NSOpenPanel()
        panel.title = "Move Selected Outputs"
        panel.message = "Choose a destination folder for selected outputs."
        panel.prompt = "Move"
        panel.canChooseFiles = false
        panel.canChooseDirectories = true
        panel.canCreateDirectories = true
        panel.allowsMultipleSelection = false
        panel.directoryURL = URL(fileURLWithPath: destinationPath, isDirectory: true)

        guard panel.runModal() == .OK, let destination = panel.url else { return }
        moveOutputs(for: current, to: destination)
    }

    func moveOutputs(for selectedJobs: [DownloadJob], to destinationDirectory: URL) {
        let selectedIDs = Set(selectedJobs.map(\.id))
        guard !selectedIDs.isEmpty else { return }

        let indexes = jobs.indices.filter { selectedIDs.contains(jobs[$0].id) }
        guard !indexes.isEmpty else { return }

        var movedJobCount = 0
        var movedItemCount = 0
        var skippedCount = 0
        var failedJobCount = 0
        var blockedMessage: String?
        var firstFailureDescription: String?
        var didChange = false
        let movedAt = ISO8601DateFormatter().string(from: Date())

        for index in indexes {
            guard jobs.indices.contains(index) else { continue }

            if isActive(jobs[index].status) {
                blockedMessage = blockedMessage ?? "Cancel active jobs before moving output"
                skippedCount += 1
                continue
            }
            if jobs[index].isLocked {
                blockedMessage = blockedMessage ?? "Unlock job before moving output"
                skippedCount += 1
                continue
            }
            if imageConversionJobIDs.contains(jobs[index].id) {
                blockedMessage = blockedMessage ?? "Wait for image conversion before moving output"
                skippedCount += 1
                continue
            }

            let resolvedPath = resolvedOutputPath(for: jobs[index])
            var resolvedJob = jobs[index]
            resolvedJob.outputPath = resolvedPath
            let candidates = Self.outputDeletionCandidates(for: resolvedJob)
            guard !candidates.isEmpty else {
                skippedCount += 1
                continue
            }

            do {
                let result = try Self.moveOutputCandidates(
                    candidates,
                    originalOutputPath: resolvedPath,
                    to: destinationDirectory
                )
                guard !result.items.isEmpty else {
                    skippedCount += 1
                    continue
                }

                if let primaryOutputPath = result.primaryOutputPath {
                    jobs[index].outputPath = primaryOutputPath
                }
                jobs[index].metadata["output_moved_at"] = movedAt
                jobs[index].metadata["output_moved_to"] = destinationDirectory.path
                jobs[index].metadata.removeValue(forKey: "output_move_error")
                jobs[index].message = "\(result.items.count) output item(s) moved"
                movedJobCount += 1
                movedItemCount += result.items.count
                didChange = true
            } catch {
                failedJobCount += 1
                firstFailureDescription = firstFailureDescription ?? error.localizedDescription
                jobs[index].metadata["output_move_error"] = error.localizedDescription
                jobs[index].message = "Output move failed: \(error.localizedDescription)"
                didChange = true
            }
        }

        if didChange {
            persistQueue()
        }
        if failedJobCount > 0, movedJobCount > 0 {
            addSummary = "\(movedItemCount) output item(s) moved for \(movedJobCount) job(s); \(failedJobCount) failed"
        } else if failedJobCount > 0 {
            addSummary = "Output move failed: \(firstFailureDescription ?? "Unknown error")"
        } else if movedJobCount > 0 {
            addSummary = "\(movedItemCount) output item(s) moved for \(movedJobCount) job(s)"
        } else if let blockedMessage {
            addSummary = blockedMessage
        } else if skippedCount > 0 {
            addSummary = "Output already in selected folder"
        } else {
            addSummary = "No movable output found"
        }
    }

    func beginDeletingOutput(for job: DownloadJob, removeJobAfterDeletion: Bool = false) {
        guard let current = jobs.first(where: { $0.id == job.id }) else { return }
        guard !isActive(current.status) else {
            addSummary = "Cancel active jobs before deleting output"
            return
        }
        guard !current.isLocked else {
            addSummary = "Unlock job before deleting output"
            return
        }

        let candidates = resolvedOutputDeletionCandidates(for: current)
        guard !candidates.isEmpty else {
            addSummary = "No output files found"
            return
        }

        outputDeletionJob = current
        outputDeletionJobIDs = [current.id]
        outputDeletionCandidates = candidates
        removeJobAfterOutputDeletion = removeJobAfterDeletion
        showingOutputDeletionConfirmation = true
    }

    func beginDeletingOutputs(
        startingAt job: DownloadJob,
        removeJobsAfterDeletion: Bool = true
    ) {
        guard removeJobsAfterDeletion else {
            beginDeletingOutput(for: job)
            return
        }
        let selected = contextualJobs(startingAt: job)
        let removable = selected.filter {
            !$0.isLocked &&
                !Self.isPendingQueueRemoval($0)
        }
        guard !removable.isEmpty else {
            if selected.contains(where: \.isLocked) {
                addSummary = "Unlock jobs before deleting output"
            } else {
                addSummary = "No removable jobs selected"
            }
            return
        }

        var seenPaths = Set<String>()
        var candidates: [OutputDeletionCandidate] = []
        for candidate in removable.flatMap({ resolvedOutputDeletionCandidates(for: $0) }) {
            let key = URL(fileURLWithPath: candidate.path)
                .resolvingSymlinksInPath()
                .standardizedFileURL
                .path
            guard seenPaths.insert(key).inserted else { continue }
            candidates.append(candidate)
        }

        outputDeletionJob = removable.first
        outputDeletionJobIDs = removable.map(\.id)
        outputDeletionCandidates = candidates
        removeJobAfterOutputDeletion = true
        showingOutputDeletionConfirmation = true
    }

    var pendingOutputDeletionJobCount: Int {
        let pending = Set(outputDeletionJobIDs)
        return jobs.lazy.filter { pending.contains($0.id) }.count
    }

    var outputDeletionConfirmationMessage: String {
        guard removeJobAfterOutputDeletion else {
            return AppLocalization.text(
                "Choose downloaded output to move to the Trash. The task will remain in the list.",
                language: interfaceLanguage
            )
        }

        let pending = Set(outputDeletionJobIDs)
        let selected = jobs.filter { pending.contains($0.id) }
        let heading: String
        heading = selected.count == 1
            ? AppLocalization.text(
                "Move all downloaded output to the macOS Trash and remove this task from the list.",
                language: interfaceLanguage
            )
            : AppLocalization.format(
                "Move downloaded output for %@ selected tasks to the macOS Trash and remove them from the list.",
                language: interfaceLanguage,
                String(selected.count)
            )
        let activeNote: String
        if selected.contains(where: { isActive($0.status) }) {
            activeNote = AppLocalization.text(
                "\nActive downloads will be cancelled immediately. Output downloaded so far will be moved to the Trash before removal.",
                language: interfaceLanguage
            )
        } else {
            activeNote = ""
        }
        let titles = selected.prefix(10).map { job in
            "• \(job.title.trimmed.isEmpty ? job.source : job.title)"
        }.joined(separator: "\n")
        let remainder = selected.count > 10 ? "\n• ..." : ""
        return titles.isEmpty ? "\(heading)\(activeNote)" : "\(heading)\n\(titles)\(remainder)\(activeNote)"
    }

    func cancelDeletingOutput() {
        outputDeletionJob = nil
        outputDeletionJobIDs = []
        outputDeletionCandidates = []
        removeJobAfterOutputDeletion = false
        showingOutputDeletionConfirmation = false
    }

    func trashOutputCandidates(_ candidateIDs: Set<String>) {
#if TESTING
        testingTrashedResultURLs = []
#endif
        if removeJobAfterOutputDeletion {
            trashOutputsAndRemovePendingJobs()
            cancelDeletingOutput()
            return
        }

        guard let job = outputDeletionJob,
              let index = jobs.firstIndex(where: { $0.id == job.id }) else {
            cancelDeletingOutput()
            return
        }
        guard !isActive(jobs[index].status) else {
            addSummary = "Cancel active jobs before deleting output"
            cancelDeletingOutput()
            return
        }
        guard !jobs[index].isLocked else {
            addSummary = "Unlock job before deleting output"
            cancelDeletingOutput()
            return
        }

        let selected = outputDeletionCandidates.filter { candidateIDs.contains($0.id) }
        guard !selected.isEmpty else {
            cancelDeletingOutput()
            return
        }
        let pendingIDs = Set(outputDeletionJobIDs.isEmpty ? [job.id] : outputDeletionJobIDs)
        guard !selected.contains(where: {
            isOutputDeletionCandidateShared($0, excludingJobIDs: pendingIDs)
        }) else {
            addSummary = "Downloaded output is shared with another queue job. Job kept."
            cancelDeletingOutput()
            return
        }

        do {
            let result = try trashOutputDeletionCandidates(selected)
            if jobs.indices.contains(index) {
                if !result.resolvedPaths.isEmpty {
                    updateOutputPathAfterDeletingCandidates(at: index, trashedPaths: result.resolvedPaths)
                    jobs[index].metadata["output_deleted_at"] = ISO8601DateFormatter().string(from: Date())
                }

                if result.failures.isEmpty {
                    if result.trashedItemCount > 0 {
                        jobs[index].message = "\(result.trashedItemCount) output item(s) moved to Trash"
                        addSummary = "\(result.trashedItemCount) output item(s) moved to Trash"
                    } else {
                        jobs[index].message = "Downloaded output was already missing"
                        addSummary = "Downloaded output was already missing"
                    }
                } else {
                    let failedCount = result.failures.count
                    jobs[index].metadata["output_delete_partial_at"] = ISO8601DateFormatter().string(from: Date())
                    jobs[index].metadata["output_delete_failed_count"] = String(failedCount)
                    jobs[index].message = "\(result.trashedItemCount) output item(s) moved; \(failedCount) failed"
                    addSummary = "\(result.trashedItemCount) output item(s) moved to Trash; \(failedCount) failed"
                }
                persistQueue()
            }
        } catch {
            addSummary = "Output delete failed: \(error.localizedDescription)"
        }
        cancelDeletingOutput()
    }

    private func trashOutputsAndRemovePendingJobs() {
        let pendingIDs = outputDeletionJobIDs.isEmpty
            ? outputDeletionJob.map { [$0.id] } ?? []
            : outputDeletionJobIDs
        guard !pendingIDs.isEmpty else { return }

        let result = trashOutputsAndRemoveJobs(withIDs: pendingIDs)
        updateOutputRemovalSummary(result, requestedCount: pendingIDs.count)
    }

    private func trashOutputsAndRemoveJobs(withIDs pendingIDs: [UUID]) -> JobOutputRemovalResult {
        var result = JobOutputRemovalResult()
        var didChange = false
        var removableJobIDs = Set<UUID>()
        let deletedAt = ISO8601DateFormatter().string(from: Date())
        let pendingIDSet = Set(pendingIDs)
        let shouldDeferSelectedOutputDeletion = pendingIDs.contains { jobID in
            guard let job = jobs.first(where: { $0.id == jobID }) else { return false }
            return isActive(job.status) ||
                processingJobIDs.contains(jobID) ||
                runningJobTasks[jobID] != nil
        }

        for jobID in pendingIDs {
            guard let index = jobs.firstIndex(where: { $0.id == jobID }) else { continue }
            if jobs[index].isLocked {
                result.keptJobCount += 1
                continue
            }
            if shouldDeferSelectedOutputDeletion {
                jobs[index].metadata[Self.pendingQueueOutputDeletionMetadataKey] = "true"
                removableJobIDs.insert(jobs[index].id)
                result.deferredOutputDeletionCount += 1
                didChange = true
                continue
            }

            let candidates = resolvedOutputDeletionCandidates(for: jobs[index])
            guard !candidates.isEmpty else {
                removableJobIDs.insert(jobs[index].id)
                didChange = true
                continue
            }
            if candidates.contains(where: {
                isOutputDeletionCandidateShared($0, excludingJobIDs: pendingIDSet)
            }) {
                result.failedItemCount += 1
                result.keptJobCount += 1
                jobs[index].metadata["output_delete_partial_at"] = deletedAt
                jobs[index].metadata["output_delete_failed_count"] = "1"
                jobs[index].message = "Output is shared with another queue job"
                didChange = true
                continue
            }

            do {
                let trashResult = try trashOutputDeletionCandidates(candidates)
                result.trashedItemCount += trashResult.trashedItemCount
                if trashResult.failures.isEmpty {
                    removableJobIDs.insert(jobs[index].id)
                    didChange = true
                    continue
                }

                if !trashResult.resolvedPaths.isEmpty {
                    updateOutputPathAfterDeletingCandidates(at: index, trashedPaths: trashResult.resolvedPaths)
                    jobs[index].metadata["output_deleted_at"] = deletedAt
                }
                let failures = trashResult.failures.count
                result.failedItemCount += failures
                result.keptJobCount += 1
                jobs[index].metadata["output_delete_partial_at"] = deletedAt
                jobs[index].metadata["output_delete_failed_count"] = String(failures)
                jobs[index].message = "\(trashResult.trashedItemCount) output item(s) moved; \(failures) failed"
                didChange = true
            } catch {
                result.failedItemCount += 1
                result.keptJobCount += 1
                jobs[index].metadata["output_delete_partial_at"] = deletedAt
                jobs[index].metadata["output_delete_failed_count"] = "1"
                jobs[index].message = "Output delete failed: \(error.localizedDescription)"
                didChange = true
            }
        }

        if !removableJobIDs.isEmpty {
            let removable = jobs.filter { removableJobIDs.contains($0.id) }
            result.removedJobCount = removeJobsFromQueue(removable)
        } else if didChange {
            persistQueue()
        }
        return result
    }

    private func updateOutputRemovalSummary(_ result: JobOutputRemovalResult, requestedCount: Int) {
        if result.failedItemCount > 0 {
            if requestedCount == 1 {
                addSummary = "\(result.trashedItemCount) output item(s) moved to Trash; \(result.failedItemCount) failed. Job kept."
            } else {
                addSummary = "\(result.removedJobCount) job(s) removed, \(result.trashedItemCount) output item(s) moved to Trash; \(result.failedItemCount) failed and \(result.keptJobCount) job(s) kept"
            }
        } else if result.removedJobCount == 1 {
            addSummary = result.trashedItemCount > 0
                ? "Job removed and \(result.trashedItemCount) output item(s) moved to Trash"
                : "Job removed; downloaded output was already missing"
        } else if result.removedJobCount > 1 {
            addSummary = "\(result.removedJobCount) jobs removed and \(result.trashedItemCount) output item(s) moved to Trash"
        } else if result.keptJobCount > 0 {
            addSummary = "Cancel active jobs or unlock them before deleting output"
        }
    }

    private func isOutputDeletionCandidateShared(
        _ candidate: OutputDeletionCandidate,
        excludingJobIDs: Set<UUID>
    ) -> Bool {
        let candidatePath = URL(fileURLWithPath: candidate.path)
            .resolvingSymlinksInPath()
            .standardizedFileURL
            .path
        let candidatePrefix = candidatePath.hasSuffix("/") ? candidatePath : candidatePath + "/"

        return jobs.contains { job in
            guard !excludingJobIDs.contains(job.id),
                  let output = QueueThumbnailProvider.existingOutputURL(
                    forOutputPath: job.outputPath,
                    destinationPath: destinationPath
                  ) else {
                return false
            }
            let outputPath = output.resolvingSymlinksInPath().standardizedFileURL.path
            let outputPrefix = outputPath.hasSuffix("/") ? outputPath : outputPath + "/"
            return outputPath == candidatePath ||
                outputPath.hasPrefix(candidatePrefix) ||
                candidatePath.hasPrefix(outputPrefix)
        }
    }

    nonisolated static func revealURL(forOutputPath path: String, fileManager: FileManager = .default) -> URL? {
        let value = path.trimmed
        guard !value.isEmpty else { return nil }

        let output = URL(fileURLWithPath: value)
        if fileManager.fileExists(atPath: output.path) {
            return output
        }

        return archiveSiblingURL(forMissingOutput: output, fileManager: fileManager) ?? output
    }

    private nonisolated static func archiveSiblingURL(forMissingOutput output: URL, fileManager: FileManager) -> URL? {
        for ext in ["zip", "cbz", "rar", "7z"] {
            let candidate = output.appendingPathExtension(ext)
            if fileManager.fileExists(atPath: candidate.path) {
                return candidate
            }
        }
        return nil
    }

    nonisolated static func firstOutputOpenURL(
        forOutputPath path: String,
        fileManager: FileManager = .default
    ) -> URL? {
        let value = path.trimmed
        guard !value.isEmpty else { return nil }

        let output = URL(fileURLWithPath: value)
        var isDirectory: ObjCBool = false
        if fileManager.fileExists(atPath: output.path, isDirectory: &isDirectory) {
            if !isDirectory.boolValue {
                return fileManager.isReadableFile(atPath: output.path) ? output : nil
            }

            if let firstFile = firstReadableFile(in: output, fileManager: fileManager) {
                return firstFile
            }

            return archiveSiblingURL(forMissingOutput: output, fileManager: fileManager)
        }

        return archiveSiblingURL(forMissingOutput: output, fileManager: fileManager)
    }

    @discardableResult
    nonisolated static func createPDF(
        fromOutputPath path: String,
        title: String,
        fileManager: FileManager = .default
    ) throws -> URL {
        let images = pdfImageSources(fromOutputPath: path, fileManager: fileManager)
        guard !images.isEmpty else {
            throw NativeDownloadError.noFiles
        }

        let output = pdfOutputURL(fromOutputPath: path, title: title, fileManager: fileManager)
        try AppPaths.ensureDirectory(output.deletingLastPathComponent())

        guard let consumer = CGDataConsumer(url: output as CFURL) else {
            throw NativeDownloadError.unsupported("PDF output could not be opened.")
        }
        guard let context = CGContext(consumer: consumer, mediaBox: nil, nil) else {
            throw NativeDownloadError.unsupported("PDF context could not be created.")
        }

        var written = 0
        var archiveDataCache: [URL: Data] = [:]
        for image in images {
            guard let source = try pdfCGImageSource(for: image, archiveDataCache: &archiveDataCache),
                  let image = CGImageSourceCreateImageAtIndex(source, 0, nil) else {
                continue
            }

            let page = CGRect(x: 0, y: 0, width: max(1, image.width), height: max(1, image.height))
            context.beginPDFPage([kCGPDFContextMediaBox as String: page] as CFDictionary)
            context.setFillColor(CGColor(gray: 1, alpha: 1))
            context.fill(page)
            context.draw(image, in: page)
            context.endPDFPage()
            written += 1
        }

        context.closePDF()

        guard written > 0 else {
            try? fileManager.removeItem(at: output)
            throw NativeDownloadError.noFiles
        }

        return output
    }

    nonisolated static func pdfImageFiles(fromOutputPath path: String, fileManager: FileManager = .default) -> [URL] {
        let value = path.trimmed
        guard !value.isEmpty else { return [] }

        let root = URL(fileURLWithPath: value)
        var isDirectory = ObjCBool(false)
        guard fileManager.fileExists(atPath: root.path, isDirectory: &isDirectory) else {
            return []
        }

        if !isDirectory.boolValue {
            return isPDFImageFile(root) ? [root] : []
        }

        guard let enumerator = fileManager.enumerator(
            at: root,
            includingPropertiesForKeys: [.isRegularFileKey],
            options: [.skipsHiddenFiles, .skipsPackageDescendants],
            errorHandler: { _, _ in true }
        ) else {
            return []
        }

        var files: [URL] = []
        for case let url as URL in enumerator {
            guard isPDFImageFile(url),
                  let values = try? url.resourceValues(forKeys: [.isRegularFileKey]),
                  values.isRegularFile == true else {
                continue
            }
            files.append(url)
        }

        return files.sorted { $0.path.localizedStandardCompare($1.path) == .orderedAscending }
    }

    private struct PDFImageSource {
        var sortKey: String
        var fileURL: URL?
        var archiveURL: URL?
        var archiveEntry: ZipArchiveReader.Entry?
    }

    private nonisolated static func pdfImageSources(fromOutputPath path: String, fileManager: FileManager = .default) -> [PDFImageSource] {
        let value = path.trimmed
        guard !value.isEmpty else { return [] }

        let root = URL(fileURLWithPath: value)
        var isDirectory = ObjCBool(false)
        if !fileManager.fileExists(atPath: root.path, isDirectory: &isDirectory) {
            if let archive = archiveSiblingURL(forMissingOutput: root, fileManager: fileManager) {
                return pdfArchiveImageSources(from: archive)
            }
            return []
        }

        if !isDirectory.boolValue {
            if isPDFImageFile(root) {
                return [PDFImageSource(sortKey: root.lastPathComponent, fileURL: root)]
            }
            return isArchiveOutputFile(root) ? pdfArchiveImageSources(from: root) : []
        }

        return pdfImageFiles(fromOutputPath: path, fileManager: fileManager).map { url in
            let relative = relativePDFSortKey(for: url, under: root)
            return PDFImageSource(sortKey: relative, fileURL: url)
        }
    }

    private nonisolated static func pdfArchiveImageSources(from archive: URL) -> [PDFImageSource] {
        guard let entries = try? ZipArchiveReader.entries(in: archive) else { return [] }
        return entries
            .filter { $0.isReadable && isPDFImageEntryName($0.name) }
            .sorted { $0.name.localizedStandardCompare($1.name) == .orderedAscending }
            .map { entry in
                PDFImageSource(sortKey: entry.name, archiveURL: archive, archiveEntry: entry)
            }
    }

    private nonisolated static func pdfCGImageSource(
        for image: PDFImageSource,
        archiveDataCache: inout [URL: Data]
    ) throws -> CGImageSource? {
        if let fileURL = image.fileURL {
            return CGImageSourceCreateWithURL(fileURL as CFURL, nil)
        }

        guard let archiveURL = image.archiveURL,
              let archiveEntry = image.archiveEntry else {
            return nil
        }

        let archiveData: Data
        if let cached = archiveDataCache[archiveURL] {
            archiveData = cached
        } else {
            archiveData = try Data(contentsOf: archiveURL)
            archiveDataCache[archiveURL] = archiveData
        }

        let data = try ZipArchiveReader.data(for: archiveEntry, inArchiveData: archiveData)
        return CGImageSourceCreateWithData(data as CFData, nil)
    }

    private nonisolated static func relativePDFSortKey(for file: URL, under root: URL) -> String {
        let rootPath = root.resolvingSymlinksInPath().path
        let prefix = rootPath.hasSuffix("/") ? rootPath : rootPath + "/"
        let path = file.resolvingSymlinksInPath().path
        return path.hasPrefix(prefix) ? String(path.dropFirst(prefix.count)) : file.lastPathComponent
    }

    private nonisolated static func pdfOutputURL(fromOutputPath path: String, title: String, fileManager: FileManager) -> URL {
        let value = path.trimmed
        let output = URL(fileURLWithPath: value.isEmpty ? AppPaths.defaultDownloadDirectory.path : value)
        var isDirectory = ObjCBool(false)
        let exists = fileManager.fileExists(atPath: output.path, isDirectory: &isDirectory)
        let parent = output.deletingLastPathComponent()
        let fallbackName = exists && isDirectory.boolValue ? output.lastPathComponent : (output.lastPathComponent as NSString).deletingPathExtension
        let rawName = title.trimmed.isEmpty ? fallbackName : title
        return AppPaths.uniqueFileURL(in: parent, filename: "\(rawName.sanitizedFilename(maxLength: 120)).pdf")
    }

    private nonisolated static func isPDFImageFile(_ url: URL) -> Bool {
        pdfImageExtensions.contains(url.pathExtension.lowercased())
    }

    private nonisolated static func isPDFImageEntryName(_ name: String) -> Bool {
        pdfImageExtensions.contains(URL(fileURLWithPath: name).pathExtension.lowercased())
    }

    private nonisolated static func firstReadableFile(in folder: URL, fileManager: FileManager) -> URL? {
        guard let enumerator = fileManager.enumerator(
            at: folder,
            includingPropertiesForKeys: [.isRegularFileKey],
            options: [.skipsHiddenFiles]
        ) else {
            return nil
        }

        let folderResolved = folder.resolvingSymlinksInPath()
        let folderPrefix = folderResolved.path.hasSuffix("/") ? folderResolved.path : folderResolved.path + "/"
        var files: [(url: URL, relativePath: String)] = []

        for case let file as URL in enumerator {
            let resolved = file.resolvingSymlinksInPath()
            var isDirectory: ObjCBool = false
            guard fileManager.fileExists(atPath: resolved.path, isDirectory: &isDirectory),
                  !isDirectory.boolValue,
                  fileManager.isReadableFile(atPath: resolved.path),
                  resolved.path.hasPrefix(folderPrefix) else {
                continue
            }
            let relativePath = String(resolved.path.dropFirst(folderPrefix.count))
            files.append((resolved, relativePath))
        }

        return files
            .sorted { $0.relativePath.localizedStandardCompare($1.relativePath) == .orderedAscending }
            .first?
            .url
    }

    nonisolated static func outputDeletionCandidates(
        for job: DownloadJob,
        fileManager: FileManager = .default
    ) -> [OutputDeletionCandidate] {
        let path = job.outputPath.trimmed
        guard !path.isEmpty else { return [] }

        let output = URL(fileURLWithPath: path)
        var candidates: [OutputDeletionCandidate] = []
        var seenPaths = Set<String>()

        func append(_ url: URL, preferredKind: OutputDeletionCandidateKind? = nil) {
            var isDirectory: ObjCBool = false
            guard fileManager.fileExists(atPath: url.path, isDirectory: &isDirectory) else { return }
            let resolvedPath = url.resolvingSymlinksInPath().standardizedFileURL.path
            guard !seenPaths.contains(resolvedPath) else { return }
            seenPaths.insert(resolvedPath)

            let kind = preferredKind ?? outputDeletionCandidateKind(for: url, isDirectory: isDirectory.boolValue)
            candidates.append(OutputDeletionCandidate(path: url.path, kind: kind))
        }

        append(output)
        if archiveExtensions.contains(output.pathExtension.lowercased()) {
            append(output.deletingPathExtension(), preferredKind: .folder)
        } else {
            for archive in archiveSiblingURLs(for: output, fileManager: fileManager) {
                append(archive, preferredKind: .archive)
            }
        }

        return candidates
    }

    nonisolated static func moveOutputCandidates(
        _ candidates: [OutputDeletionCandidate],
        originalOutputPath: String,
        to destinationDirectory: URL,
        fileManager: FileManager = .default
    ) throws -> OutputMoveResult {
        let operations = try outputMoveOperations(
            for: candidates,
            originalOutputPath: originalOutputPath,
            destinationDirectory: destinationDirectory,
            fileManager: fileManager
        )

        var movedItems: [OutputMoveItem] = []
        var primaryOutputPath: String?

        for operation in operations {
            if operation.isNoOp {
                if operation.isPrimary {
                    primaryOutputPath = operation.source.path
                }
                continue
            }

            try fileManager.moveItem(at: operation.source, to: operation.destination)
            movedItems.append(OutputMoveItem(
                originalPath: operation.source.path,
                movedPath: operation.destination.path,
                kind: operation.kind
            ))
            if operation.isPrimary {
                primaryOutputPath = operation.destination.path
            }
        }

        if primaryOutputPath == nil {
            primaryOutputPath = movedItems.first?.movedPath
        }

        return OutputMoveResult(items: movedItems, primaryOutputPath: primaryOutputPath)
    }

    private nonisolated static func outputMoveOperations(
        for candidates: [OutputDeletionCandidate],
        originalOutputPath: String,
        destinationDirectory: URL,
        fileManager: FileManager
    ) throws -> [OutputMoveOperation] {
        let destination = try normalizedOutputMoveDestination(destinationDirectory, fileManager: fileManager)
        let destinationResolved = destination.resolvingSymlinksInPath().standardizedFileURL
        let original = URL(fileURLWithPath: originalOutputPath).standardizedFileURL
        let originalResolved = original.resolvingSymlinksInPath().standardizedFileURL
        var reservedPaths = Set<String>()
        var operations: [OutputMoveOperation] = []

        for candidate in candidates {
            let source = URL(fileURLWithPath: candidate.path).standardizedFileURL
            var isDirectory: ObjCBool = false
            guard fileManager.fileExists(atPath: source.path, isDirectory: &isDirectory) else { continue }

            let sourceResolved = source.resolvingSymlinksInPath().standardizedFileURL
            guard isSafeOutputMoveSource(sourceResolved) else {
                throw NativeDownloadError.unsupported("Refusing to move \(source.lastPathComponent).")
            }
            if isDirectory.boolValue && isOutputMoveDestination(destinationResolved, inside: sourceResolved) {
                throw NativeDownloadError.unsupported("Choose a folder outside \(source.lastPathComponent).")
            }

            let target = uniqueOutputMoveDestination(
                for: source,
                isDirectory: isDirectory.boolValue,
                in: destination,
                reservedPaths: reservedPaths,
                fileManager: fileManager
            )
            let sourcePath = source.standardizedFileURL.path
            let targetPath = target.standardizedFileURL.path
            let isNoOp = sourcePath == targetPath
            if !isNoOp {
                reservedPaths.insert(targetPath)
            }

            let isPrimary = sourcePath == original.path
                || sourceResolved.path == originalResolved.path
            operations.append(OutputMoveOperation(
                source: source,
                destination: target,
                kind: candidate.kind,
                isPrimary: isPrimary,
                isNoOp: isNoOp
            ))
        }

        return operations
    }

    @discardableResult
    private nonisolated static func normalizedOutputMoveDestination(
        _ destinationDirectory: URL,
        fileManager: FileManager
    ) throws -> URL {
        let destination = destinationDirectory.standardizedFileURL
        try AppPaths.ensureDirectory(destination)

        var isDirectory: ObjCBool = false
        guard fileManager.fileExists(atPath: destination.path, isDirectory: &isDirectory),
              isDirectory.boolValue else {
            throw NativeDownloadError.unsupported("Destination is not a folder.")
        }
        return destination
    }

    private nonisolated static func uniqueOutputMoveDestination(
        for source: URL,
        isDirectory: Bool,
        in destinationDirectory: URL,
        reservedPaths: Set<String>,
        fileManager: FileManager
    ) -> URL {
        let safeName = source.lastPathComponent.sanitizedFilename()
        let sourcePath = source.standardizedFileURL.path

        func isUnavailable(_ url: URL) -> Bool {
            let path = url.standardizedFileURL.path
            if path == sourcePath {
                return false
            }
            return reservedPaths.contains(path) || fileManager.fileExists(atPath: path)
        }

        if isDirectory {
            var candidate = destinationDirectory.appendingPathComponent(safeName, isDirectory: true)
            var counter = 2
            while isUnavailable(candidate) {
                candidate = destinationDirectory.appendingPathComponent("\(safeName) \(counter)", isDirectory: true)
                counter += 1
            }
            return candidate
        }

        let base = (safeName as NSString).deletingPathExtension
        let ext = (safeName as NSString).pathExtension
        var candidate = destinationDirectory.appendingPathComponent(safeName)
        var counter = 2
        while isUnavailable(candidate) {
            let name = ext.isEmpty ? "\(base) \(counter)" : "\(base) \(counter).\(ext)"
            candidate = destinationDirectory.appendingPathComponent(name)
            counter += 1
        }
        return candidate
    }

    private nonisolated static func isSafeOutputMoveSource(_ url: URL) -> Bool {
        let path = url.standardizedFileURL.path
        guard path != "/" else { return false }
        return !url.lastPathComponent.trimmed.isEmpty
    }

    private nonisolated static func isOutputMoveDestination(_ destination: URL, inside source: URL) -> Bool {
        let destinationPath = destination.standardizedFileURL.path
        let sourcePath = source.standardizedFileURL.path
        let sourcePrefix = sourcePath.hasSuffix("/") ? sourcePath : sourcePath + "/"
        return destinationPath == sourcePath || destinationPath.hasPrefix(sourcePrefix)
    }

    private nonisolated static func archiveSiblingURLs(for output: URL, fileManager: FileManager) -> [URL] {
        archiveExtensions.map { output.appendingPathExtension($0) }
            .filter { fileManager.fileExists(atPath: $0.path) }
    }

    private nonisolated static func outputDeletionCandidateKind(for url: URL, isDirectory: Bool) -> OutputDeletionCandidateKind {
        if isDirectory { return .folder }
        if archiveExtensions.contains(url.pathExtension.lowercased()) { return .archive }
        return .file
    }

    private nonisolated static let archiveExtensions = ["zip", "cbz", "rar", "7z"]
    private nonisolated static let hitomiGalleryInfoFilenames = Set(["gallery-info.txt", "hitomi_gallery_info.txt", "hitomi-gallery-info.txt"])
    private nonisolated static let pdfImageExtensions = Set(["jpg", "jpeg", "png", "webp", "gif", "tif", "tiff", "bmp", "heic", "heif", "avif"])

    nonisolated static func browserViewURL(baseURLString: String, jobID: UUID, password: String, mode: String = "") -> URL? {
        browserViewURL(baseURLString: baseURLString, jobIDs: [jobID], password: password, mode: mode)
    }

    nonisolated static func browserViewURL(baseURLString: String, jobIDs: [UUID], password: String, mode: String = "") -> URL? {
        guard !jobIDs.isEmpty else { return nil }
        let value = baseURLString.trimmed
        guard !value.isEmpty, var components = URLComponents(string: value) else { return nil }
        if components.scheme == nil {
            components.scheme = "http"
        }
        if components.host == nil {
            components.host = "127.0.0.1"
        }
        components.path = "/view"

        let uniqueIDs = orderedUniqueJobIDs(jobIDs)
        var queryItems = [
            uniqueIDs.count == 1
                ? URLQueryItem(name: "uid", value: uniqueIDs[0].uuidString)
                : URLQueryItem(name: "uids", value: uniqueIDs.map(\.uuidString).joined(separator: ","))
        ]
        let password = password.trimmed
        if !password.isEmpty {
            queryItems.append(URLQueryItem(name: "pw", value: password))
        }
        let mode = mode.trimmed
        if !mode.isEmpty {
            queryItems.append(URLQueryItem(name: "mode", value: mode))
        }
        components.queryItems = queryItems
        return components.url
    }

    nonisolated static func textViewerURL(baseURLString: String, jobID: UUID, fileIndex: Int?, password: String) -> URL? {
        let value = baseURLString.trimmed
        guard !value.isEmpty, var components = URLComponents(string: value) else { return nil }
        if components.scheme == nil {
            components.scheme = "http"
        }
        if components.host == nil {
            components.host = "127.0.0.1"
        }
        components.path = "/text"

        var queryItems = [URLQueryItem(name: "uid", value: jobID.uuidString)]
        if let fileIndex {
            queryItems.append(URLQueryItem(name: "index", value: "\(fileIndex)"))
        }
        let password = password.trimmed
        if !password.isEmpty {
            queryItems.append(URLQueryItem(name: "pw", value: password))
        }
        components.queryItems = queryItems
        return components.url
    }

    nonisolated static func browserHelperURL(baseURLString: String, targetURL: URL, password: String) -> URL? {
        let value = baseURLString.trimmed
        guard !value.isEmpty, var components = URLComponents(string: value) else { return nil }
        if components.scheme == nil {
            components.scheme = "http"
        }
        if components.host == nil {
            components.host = "127.0.0.1"
        }
        components.path = "/browser"

        var queryItems = [URLQueryItem(name: "url", value: targetURL.absoluteString)]
        let password = password.trimmed
        if !password.isEmpty {
            queryItems.append(URLQueryItem(name: "pw", value: password))
        }
        components.queryItems = queryItems
        return components.url
    }

    private nonisolated static func orderedUniqueJobIDs(_ jobIDs: [UUID]) -> [UUID] {
        var seen = Set<UUID>()
        var unique: [UUID] = []
        for id in jobIDs where seen.insert(id).inserted {
            unique.append(id)
        }
        return unique
    }

    private func ensureHTTPAPIAvailableForBrowserView() -> Bool {
        if httpAPIServer != nil {
            return true
        }

        startHTTPAPIServer()
        return httpAPIServer != nil
    }

    private func httpAPIBaseURLString() -> String {
        let status = httpAPIStatus.trimmed
        if status.hasPrefix("http://") || status.hasPrefix("https://") {
            return status
        }

        let port = httpAPIPortString.trimmed.isEmpty ? "8110" : httpAPIPortString.trimmed
        return "http://127.0.0.1:\(port)"
    }

    private struct OutputTrashResult {
        var resolvedPaths = Set<String>()
        var trashedItemCount = 0
        var failures: [String] = []
    }

    private struct JobOutputRemovalResult {
        var removedJobCount = 0
        var keptJobCount = 0
        var trashedItemCount = 0
        var failedItemCount = 0
        var deferredOutputDeletionCount = 0
    }

    private func trashOutputDeletionCandidates(_ candidates: [OutputDeletionCandidate]) throws -> OutputTrashResult {
        var prepared: [(candidate: OutputDeletionCandidate, url: URL, safetyURL: URL)] = []
        for candidate in candidates {
            let url = URL(fileURLWithPath: candidate.path).standardizedFileURL
            let safetyURL = url.resolvingSymlinksInPath()
            guard isSafeOutputDeletionURL(safetyURL) else {
                throw NativeDownloadError.unsupported("Refusing to delete \(url.lastPathComponent).")
            }
            prepared.append((candidate, url, safetyURL))
        }

        var result = OutputTrashResult()
        let fileManager = FileManager.default
        for item in prepared {
            if !fileManager.fileExists(atPath: item.url.path) {
                result.resolvedPaths.insert(item.url.path)
                result.resolvedPaths.insert(item.safetyURL.standardizedFileURL.path)
                continue
            }

            do {
                let resultingURL = try trashOutputItem(at: item.url)
#if TESTING
                if let resultingURL {
                    testingTrashedResultURLs.append(resultingURL)
                }
#endif
                result.trashedItemCount += 1
                result.resolvedPaths.insert(item.url.path)
                result.resolvedPaths.insert(item.safetyURL.standardizedFileURL.path)
            } catch {
                if !fileManager.fileExists(atPath: item.url.path) {
                    result.resolvedPaths.insert(item.url.path)
                    result.resolvedPaths.insert(item.safetyURL.standardizedFileURL.path)
                } else {
                    result.failures.append("\(item.candidate.filename): \(error.localizedDescription)")
                }
            }
        }
        return result
    }

    private func trashOutputItem(at url: URL) throws -> URL? {
#if TESTING
        if let handler = testingTrashItemHandler {
            return try handler(url)
        }
#endif
        var resultingURL: NSURL?
        try FileManager.default.trashItem(at: url, resultingItemURL: &resultingURL)
        return resultingURL as URL?
    }

    private func isSafeOutputDeletionURL(_ url: URL) -> Bool {
        let path = url.standardizedFileURL.path
        guard path != "/" else { return false }
        guard !url.lastPathComponent.trimmed.isEmpty else { return false }

        let destination = URL(fileURLWithPath: destinationPath, isDirectory: true)
            .resolvingSymlinksInPath()
            .standardizedFileURL
            .path
        guard path != destination else { return false }
        return true
    }

    private func updateOutputPathAfterDeletingCandidates(at index: Int, trashedPaths: Set<String>) {
        guard jobs.indices.contains(index) else { return }
        let rawPath = jobs[index].outputPath
        let currentURL = URL(fileURLWithPath: rawPath)
        let currentPaths = Set([
            rawPath,
            currentURL.standardizedFileURL.path,
            currentURL.resolvingSymlinksInPath().standardizedFileURL.path
        ])
        guard !FileManager.default.fileExists(atPath: rawPath) ||
                !trashedPaths.isDisjoint(with: currentPaths) else {
            return
        }

        if let replacement = resolvedOutputDeletionCandidates(for: jobs[index]).first {
            jobs[index].outputPath = replacement.path
        } else {
            jobs[index].outputPath = ""
        }
    }

    func startQueue(addingInput: Bool = true) {
        if addingInput {
            addURLs()
        }
        isQueueEnabled = true
        guard queueTask == nil else { return }
        guard jobs.contains(where: { $0.status == .queued }) else { return }

        if ProcessInfo.processInfo.environment["HITOMI_NATIVE_DESTINATION_PATH"]?.trimmed.isEmpty != false {
            UserDefaults.standard.set(destinationPath, forKey: "destinationPath")
        }
        UserDefaults.standard.set(outputSubfolderMode.rawValue, forKey: "outputSubfolderMode")
        UserDefaults.standard.set(selectedSourceFolderID, forKey: "selectedSourceFolderID")
        persistSourceFolderNames()
        UserDefaults.standard.set(folderNameTemplate.trimmed, forKey: "folderNameTemplate")
        UserDefaults.standard.set(fileNameTemplate.trimmed, forKey: "fileNameTemplate")
        persistSourceFileNameTemplates()
        UserDefaults.standard.set(recordingFileNameTemplate.trimmed, forKey: "recordingFileNameTemplate")
        persistArchiveSettings()
        persistAutoRemoveFinishedJobsSetting()
        persistAutoRemoveHookCommand()
        persistShowDownloadDateSetting()
        persistNumberPlaylistFilesSetting()
        persistIncompleteRetrySettings()
        UserDefaults.standard.set(Self.normalizedJobConcurrency(jobConcurrency), forKey: "jobConcurrency")
        UserDefaults.standard.set(concurrency, forKey: "concurrency")
        UserDefaults.standard.set(preferWebP, forKey: "preferWebP")
        UserDefaults.standard.set(eHentaiSourceMode.rawValue, forKey: "eHentaiSourceMode")
        UserDefaults.standard.set(preferOriginalEHentaiImages, forKey: "preferOriginalEHentaiImages")
        UserDefaults.standard.set(preferJapaneseEHentaiTitle, forKey: "preferJapaneseEHentaiTitle")
        UserDefaults.standard.set(preferJapaneseEHentaiTitle, forKey: "ehenJapanese")
        persistImageConversionFormat()
        UserDefaults.standard.set(saveHitomiGalleryInfoText, forKey: "saveHitomiGalleryInfoText")
        UserDefaults.standard.set(skipDuplicates, forKey: "skipDuplicates")
        UserDefaults.standard.set(lowPowerMode, forKey: "lowPowerMode")
        UserDefaults.standard.set(showDuplicateImageThumbnails, forKey: "showDuplicateImageThumbnails")
        UserDefaults.standard.set(duplicateImageSimilarityPercent, forKey: "duplicateImageSimilarityPercent")
        UserDefaults.standard.set(appAppearanceMode.rawValue, forKey: "appAppearanceMode")
        if selectedPythonThemeKey.isEmpty {
            UserDefaults.standard.removeObject(forKey: "selectedPythonThemeKey")
        } else {
            UserDefaults.standard.set(selectedPythonThemeKey, forKey: "selectedPythonThemeKey")
        }
        UserDefaults.standard.set(uiScale.rawValue, forKey: "uiScale")
        UserDefaults.standard.set(queueViewMode.rawValue, forKey: "queueViewMode")
        UserDefaults.standard.set(queueThumbnailsHidden, forKey: "queueThumbnailsHidden")
