        UserDefaults.standard.set(floatingMonitorOpacity, forKey: "floatingMonitorOpacity")
        persistAppShortcutAssignments()
        persistJobStatusColorSettings()
        UserDefaults.standard.set(clipboardMonitorEnabled, forKey: "clipboardMonitorEnabled")
        UserDefaults.standard.set(startDownloadsOnPaste, forKey: "startDownloadsOnPaste")
        UserDefaults.standard.set(launchAtLoginEnabled, forKey: LaunchAtLoginSettings.enabledKey)
        persistCompletionAlertSettings()
        persistSleepPreventionSetting()
        persistHistorySettings()
        UserDefaults.standard.set(youtubePreferredLanguage.trimmed, forKey: "youtubePreferredLanguage")
        UserDefaults.standard.set(youtubeDownloadThumbnail, forKey: "youtubeDownloadThumbnail")
        UserDefaults.standard.set(youtubeReversePlaylist, forKey: "youtubeReversePlaylist")
        UserDefaults.standard.set(
            youtubeUseUploadDateForFileModificationTime,
            forKey: "youtubeUseUploadDateForFileModificationTime"
        )
        persistYouTubeSubtitleSettings()
        UserDefaults.standard.set(youtubeEmbedChapters, forKey: "youtubeEmbedChapters")
        UserDefaults.standard.set(youtubePreferEnhancedBitrate, forKey: "youtubePreferEnhancedBitrate")
        persistYouTubeVideoCodecSort()
        persistYouTubePreferredResolution()
        persistYouTubePreferredAudioLanguage()
        UserDefaults.standard.set(instagramIncludeStories, forKey: "instagramIncludeStories")
        persistSOOPPreferredResolution()
        persistPixivUgoiraFileFormat()
        persistM3U8Settings()
        persistAutoRecordSettings()
        persistExternalToolPaths()
        persistFFmpegTranscodeOptions()
        persistAria2Options()
        guard persistProxySettingsForUse() else {
            isRunning = false
            return
        }
        refreshDiskSpaceWarning(showAlert: true)

        activeQueueOrderIDs = jobs.map(\.id)
        isRunning = true
        recordActivity("Queue started (\(jobs.filter { $0.status == .queued }.count) queued, \(jobs.count) total)", category: "Queue")
        syncSleepPreventionAssertion()
        resetQueueRunAlertState()
        queueTask = Task { [weak self] in
            guard let self else { return }
            await self.runQueue()
            await MainActor.run {
                self.releaseSleepPreventionAssertion()
                self.isRunning = false
                self.queueTask = nil
                self.flushPendingQueueRemovals()
                self.normalizeActiveQueueOrder()
                self.persistQueue()
                self.runQueuedJobsIfEnabled()
            }
        }
    }

    func pauseQueue() {
        guard isQueueEnabled else { return }
        isQueueEnabled = false
        let message = isRunning ? "Queue paused after active jobs" : "Queue paused"
        addSummary = message
        recordActivity(message, category: "Queue")
    }

    func resumeQueue() {
        let wasPaused = !isQueueEnabled
        isQueueEnabled = true
        if wasPaused {
            addSummary = "Queue resumed"
            recordActivity("Queue resumed", category: "Queue")
        }
        runQueuedJobsIfEnabled()
    }

    func toggleQueueEnabled() {
        if isQueueEnabled {
            pauseQueue()
        } else {
            resumeQueue()
        }
    }

    func runQueuedJobsIfEnabled() {
        guard isQueueEnabled,
              queueTask == nil,
              jobs.contains(where: { $0.status == .queued }) else {
            return
        }
        startQueue(addingInput: false)
    }

    private func launchJobTask(id: UUID) -> Task<Void, Never> {
        runningJobTasks[id]?.cancel()
        let task = Task { @MainActor [weak self] in
            guard let self else { return }
            await self.processJob(id: id)
        }
        runningJobTasks[id] = task
        return task
    }

    private func cancelRunningJob(_ jobID: UUID) {
        runningJobTasks[jobID]?.cancel()
        resumePixivLoginWait(for: jobID)
        resumeChzzkLoginWait(for: jobID)
        resumeNaverCafeLoginWait(for: jobID)
        resumeTwitterLoginWait(for: jobID)
        resumePornhubLoginWait(for: jobID)
        resumeArcaliveLoginWait(for: jobID)
        aria2RuntimeProcesses[jobID]?.terminate()
        ffmpegRuntimeProcesses[jobID]?.terminate()
        ytdlpRuntimeProcesses[jobID]?.terminate()
    }

    private func cancelAllRunningJobTasks() {
        runningJobTasks.values.forEach { $0.cancel() }
        aria2RuntimeProcesses.values.forEach { $0.terminate() }
        ffmpegRuntimeProcesses.values.forEach { $0.terminate() }
        ytdlpRuntimeProcesses.values.forEach { $0.terminate() }
    }

    func canStopLiveRecording(for job: DownloadJob) -> Bool {
        guard let current = jobs.first(where: { $0.id == job.id }),
              isActive(current.status) else {
            return false
        }
        let nativeHLSIsActive = Self.liveHLSMetadataIsTrue(current.metadata["live_active"]) &&
            Self.liveHLSMetadataIsTrue(current.metadata["live_polling"])
        let ytdlpIsActive = Self.liveHLSMetadataIsTrue(current.metadata["ytdlp_live"]) &&
            ytdlpRuntimeProcesses[current.id]?.isRunning == true
        guard nativeHLSIsActive || ytdlpIsActive else { return false }
        return !Self.liveHLSMetadataIsTrue(current.metadata[Self.liveStopRequestedMetadataKey])
    }

    func stopLiveRecording(for job: DownloadJob) {
        guard let index = jobs.firstIndex(where: { $0.id == job.id }),
              canStopLiveRecording(for: jobs[index]) else {
            addSummary = AppLocalization.text(
                "No live recording can be stopped",
                language: interfaceLanguage
            )
            return
        }

        jobs[index].metadata[Self.liveStopRequestedMetadataKey] = "true"
        jobs[index].metadata["live_stop_requested_at"] = ISO8601DateFormatter().string(from: Date())
        jobs[index].metadata["transfer_active"] = "false"
        jobs[index].message = "Stopping recording"
        jobs[index].recordMessage(jobs[index].message)
        if Self.liveHLSMetadataIsTrue(jobs[index].metadata["ytdlp_live"]) {
            jobs[index].metadata["ytdlp_stop_requested"] = "true"
            _ = ytdlpRuntimeProcesses[jobs[index].id]?.interrupt()
        }
        addSummary = AppLocalization.text(
            "Finishing live recording",
            language: interfaceLanguage
        )
        persistQueue()
    }

    func cancelQueue() {
        let wasRunning = queueTask != nil
        queueTask?.cancel()
        cancelAllRunningJobTasks()
        resumeAllPixivLoginWaits()
        resumeAllChzzkLoginWaits()
        resumeAllNaverCafeLoginWaits()
        resumeAllTwitterLoginWaits()
        resumeAllPornhubLoginWaits()
        resumeAllArcaliveLoginWaits()
        if !wasRunning {
            normalizeActiveQueueOrder()
            isRunning = false
            releaseSleepPreventionAssertion()
        }
        recordActivity("Queue cancelled", category: "Queue")
        cancelAllScheduledRestarts()
        for index in jobs.indices where jobs[index].status == .queued || jobs[index].status == .resolving || jobs[index].status == .downloading {
            markCancelled(index, persist: false)
        }
        persistQueue()
    }

    private func runQueue() async {
        let taskLimit = Self.normalizedJobConcurrency(jobConcurrency)
        guard taskLimit > 1 else {
            await runQueueSequentially()
            return
        }
        await runQueueConcurrently(taskLimit: taskLimit)
    }

    private func runQueueSequentially() async {
        while isQueueEnabled,
              let index = queueOrderedJobIndices.reversed().first(where: { jobs[$0].status == .queued }) {
            if Task.isCancelled { return }
#if TESTING
            testingJobScheduledHandler?(jobs[index])
#endif
            let task = launchJobTask(id: jobs[index].id)
            await task.value
            if Task.isCancelled { return }
        }
        if isQueueEnabled, !jobs.contains(where: { $0.status == .queued }) {
            handleQueueRunCompleted()
        }
    }

    private func runQueueConcurrently(taskLimit: Int) async {
        defersAutoRemoveUntilQueueEnd = true
        defer { defersAutoRemoveUntilQueueEnd = false }

        await withTaskGroup(of: UUID?.self) { group in
            var runningCount = 0
            var rescanScheduled = false

            @MainActor
            func launchNextQueuedJob() async -> Bool {
                guard isQueueEnabled,
                      !Task.isCancelled,
                      let reservation = reserveNextQueuedJobForConcurrentRun() else {
                    return false
                }

                runningCount += 1
                let task = launchJobTask(id: reservation.id)
                group.addTask {
                    await task.value
                    return reservation.id
                }
                return true
            }

            func scheduleRescanIfNeeded() {
                guard runningCount > 0,
                      runningCount < taskLimit,
                      !rescanScheduled,
                      !Task.isCancelled else { return }
                rescanScheduled = true
                group.addTask {
                    try? await Task.sleep(nanoseconds: 100_000_000)
                    return nil
                }
            }

            while runningCount < taskLimit {
                guard await launchNextQueuedJob() else { break }
            }
            scheduleRescanIfNeeded()

            while runningCount > 0 {
                guard let event = await group.next() else { break }
                if event == nil {
                    rescanScheduled = false
                } else {
                    runningCount -= 1
                }

                if Task.isCancelled {
                    group.cancelAll()
                    break
                }

                while runningCount < taskLimit {
                    guard await launchNextQueuedJob() else { break }
                }
                scheduleRescanIfNeeded()
            }
            group.cancelAll()
        }

        if isQueueEnabled,
           !Task.isCancelled,
           !jobs.contains(where: { $0.status == .queued }) {
            await flushDeferredAutoRemoveFinishedJobs()
            handleQueueRunCompleted()
        }
    }

    private func reserveNextQueuedJobForConcurrentRun() -> (index: Int, id: UUID)? {
        let hasActiveArcaliveJob = jobs.contains { job in
            (job.status == .resolving || job.status == .downloading) &&
                Self.isArcaliveQueueSource(job.source)
        }
        guard let index = queueOrderedJobIndices.reversed().first(where: { candidate in
            let job = jobs[candidate]
            guard job.status == .queued else { return false }
            return !hasActiveArcaliveJob || !Self.isArcaliveQueueSource(job.source)
        }) else { return nil }
        let jobID = jobs[index].id
#if TESTING
        testingJobScheduledHandler?(jobs[index])
#endif
        jobs[index].status = .resolving
        jobs[index].message = "Waiting for task slot"
        persistQueue()
        return (index, jobID)
    }

    private func processJob(id: UUID) async {
        processingJobIDs.insert(id)
        defer {
            processingJobIDs.remove(id)
            runningJobTasks.removeValue(forKey: id)
            if jobs.contains(where: Self.isPendingQueueRemoval) {
                flushPendingQueueRemovals()
                persistQueue()
            }
        }
        guard let index = jobs.firstIndex(where: { $0.id == id }) else { return }
        await processJob(at: index)
    }

    private nonisolated static func isArcaliveQueueSource(_ source: String) -> Bool {
        guard let url = URL(string: source.trimmed) else { return false }
        return ArcaliveResolver.articleID(from: url) != nil
    }

    private func processJob(at index: Int) async {
        guard jobs.indices.contains(index), jobs[index].status != .cancelled else { return }
        jobs[index].metadata.removeValue(forKey: "python_hook_download_ran")
        if let rawKeys = jobs[index].metadata["python_hook_preserved_keys"] {
            let keys = rawKeys
                .split(separator: ",")
                .map { String($0).trimmed }
                .filter { !$0.isEmpty && $0 != "python_hook_download_ran" }
            if keys.isEmpty {
                jobs[index].metadata.removeValue(forKey: "python_hook_preserved_keys")
            } else {
                jobs[index].metadata["python_hook_preserved_keys"] = keys.joined(separator: ",")
            }
        }
        do {
            let sourceURL = URL(string: jobs[index].source.trimmed)
            let context = PythonScriptBridge.hookContext(job: jobs[index], sourceURL: sourceURL)
            let hooked = try await runPythonHooks(event: .taskAboutToStart, context: context)
            applyPythonHookContext(hooked, toJobAt: index)
        } catch is CancellationError {
            markCancelled(index)
            return
        } catch PythonScriptBridgeError.taskReaction(let name, let message) {
            markFailed(index, message: message, reaction: name)
            return
        } catch PythonScriptBridgeError.retryRequested(_, let message) {
            markFailed(index, message: message, allowsIncompleteRetry: false)
            return
        } catch {
            markFailed(
                index,
                message: "Start hook failed: \(error.localizedDescription)",
                allowsIncompleteRetry: Self.failureAllowsIncompleteRetry(error)
            )
            return
        }
        await processJobCore(at: index)
    }

    private func processJobCore(at index: Int) async {
        guard jobs.indices.contains(index), jobs[index].status != .cancelled else { return }
        let source = jobs[index].source

        do {
#if TESTING
            if testingJobStartDelayNanoseconds > 0 {
                jobs[index].status = .resolving
                jobs[index].message = "Testing start delay"
                try await Task.sleep(nanoseconds: testingJobStartDelayNanoseconds)
            }
#endif
            if discordEmojiResolver.canResolve(source) {
                guard let request = DiscordEmojiResolver.request(from: source) else {
                    throw NativeDownloadError.invalidURL(source)
                }
                jobs[index].status = .resolving
                jobs[index].message = "Reading Discord emoji"
                persistQueue()
                let resolved = try await discordEmojiResolver.resolve(source)
                try await downloadResolved(resolved, sourceURL: DiscordEmojiResolver.sourceURL(for: request), jobIndex: index)
                return
            }

            guard let url = URL(string: source.trimmed), let scheme = url.scheme?.lowercased() else {
                throw NativeDownloadError.invalidURL(source)
            }

#if TESTING
            if let resolved = testingResolvedDownloads[source] {
                try await downloadResolved(resolved, sourceURL: url, jobIndex: index)
                return
            }
#endif

            if scheme == "magnet" {
                try await downloadWithAria2(url, jobIndex: index)
                return
            }

            if scheme == "file" {
                if aria2Bridge.canResolve(url) {
                    try await downloadWithAria2(url, jobIndex: index)
                    return
                }
                try await downloadLocalFile(url, jobIndex: index)
                return
            }

            guard scheme == "http" || scheme == "https" else {
                throw NativeDownloadError.unsupported("Unsupported URL scheme: \(scheme)")
            }
            let headers = requestOptions(for: url)

            if jobs[index].metadata[Self.directDownloadOverrideMetadataKey]?.trimmed.lowercased() == "file" {
                jobs[index].status = .resolving
                jobs[index].message = "Preparing direct download"
                persistQueue()
                try await downloadDirect(url, jobIndex: index, resolveHTMLMedia: false)
                return
            }

            if let message = Self.retiredDaumWebtoonUnsupportedMessage(for: url) {
                throw NativeDownloadError.unsupported(message)
            }

            if let rawType = jobs[index].metadata[OriginalInputType.metadataKey],
               let type = OriginalInputType(rawValue: rawType.lowercased()) {
                try await downloadUsingOriginalInputType(
                    type,
                    url: url,
                    headers: headers,
                    jobIndex: index
                )
                return
            }

            if Self.isAudioExtractionRequest(jobs[index].metadata) {
                guard ytdlpBridge.canResolve(url, siteRules: siteRules) else {
                    throw NativeDownloadError.unsupported("MP3 audio extraction requires a yt-dlp supported media URL.")
                }
                try await downloadWithYTDLP(url, jobIndex: index)
            } else if aria2Bridge.canResolve(url) {
                try await downloadWithAria2(url, jobIndex: index)
            } else if !pythonNativeFallbackJobIDs.contains(jobs[index].id),
                      let script = matchingPythonScriptPlugin(for: url) {
                jobs[index].status = .resolving
                jobs[index].message = "Running \(script.plugin.title)"
                persistQueue()
                do {
                    let resolved = try await PythonScriptBridge(configuredPythonPath: pythonPath).resolve(
                        plugin: script.plugin,
                        downloader: script.downloader,
                        sourceURL: url,
                        headers: headers
                    )
                    try await downloadResolved(resolved, sourceURL: url, jobIndex: index)
                } catch PythonScriptBridgeError.nativeDelegation(let feature) {
                    guard jobs.indices.contains(index) else { return }
                    let jobID = jobs[index].id
                    pythonNativeFallbackJobIDs.insert(jobID)
                    defer { pythonNativeFallbackJobIDs.remove(jobID) }
                    jobs[index].metadata["python_native_fallback"] = "true"
                    jobs[index].metadata["python_native_fallback_type"] = script.downloader.type
                    jobs[index].metadata["python_native_fallback_plugin"] = script.plugin.title
                    jobs[index].metadata["python_native_fallback_feature"] = String(feature.prefix(500))
                    jobs[index].message = "Switching to native resolver"
                    persistQueue()
                    await processJobCore(at: index)
                    return
                }
            } else if mpdResolver.canResolve(url) {
                jobs[index].status = .resolving
                jobs[index].message = "Reading DASH manifest"
                persistQueue()
                let resolved = try await mpdResolver.resolve(url, headers: headers)
                try await downloadResolved(resolved, sourceURL: url, jobIndex: index)
            } else if m3u8Resolver.canResolve(url) {
                jobs[index].status = .resolving
                jobs[index].message = "Reading M3U8 playlist"
