                persistQueue()
                let resolved = try await resolvePixivArtworkWithLogin(
                    url,
                    headers: headers,
                    jobIndex: index
                )
                try await downloadResolved(resolved, sourceURL: url, jobIndex: index)
            } else if pixivComicResolver.canResolve(url) {
                jobs[index].status = .resolving
                jobs[index].message = "Reading Pixiv Comic"
                persistQueue()
                let resolved = try await pixivComicResolver.resolve(url, headers: headers)
                try await downloadResolved(resolved, sourceURL: url, jobIndex: index)
            } else if comicWalkerResolver.canResolve(url) {
                jobs[index].status = .resolving
                jobs[index].message = "Reading ComicWalker episode"
                persistQueue()
                let resolved = try await comicWalkerResolver.resolve(
                    url,
                    headers: headers,
                    rangeExpression: jobs[index].rangeExpression
                )
                try await downloadResolved(resolved, sourceURL: url, jobIndex: index)
            } else if sankakuResolver.canResolve(url) {
                jobs[index].status = .resolving
                jobs[index].message = "Reading Sankaku media"
                persistQueue()
                let resolved = try await sankakuResolver.resolve(
                    url,
                    headers: headers,
                    assetLimit: Self.finiteAssetRangeUpperBound(jobs[index].rangeExpression)
                )
                try await downloadResolved(resolved, sourceURL: url, jobIndex: index)
            } else if booruResolver.canResolve(url) {
                jobs[index].status = .resolving
                jobs[index].message = "Reading booru metadata"
                persistQueue()
                let resolved = try await booruResolver.resolve(
                    url,
                    headers: headers,
                    assetLimit: Self.finiteAssetRangeUpperBound(jobs[index].rangeExpression)
                )
                try await downloadResolved(resolved, sourceURL: url, jobIndex: index)
            } else if let rule = matchingCustomCommandRule(for: url) {
                try await downloadWithCustomCommand(url, rule: rule, jobIndex: index)
            } else if ytdlpBridge.canResolve(url, siteRules: siteRules) {
                try await downloadWithYTDLP(url, jobIndex: index)
            } else if genericPageResolver.canResolve(url) {
                jobs[index].status = .resolving
                jobs[index].message = "Scanning page media"
                persistQueue()
                if let resolved = try await genericPageResolver.resolveIfPossible(url, headers: headers) {
                    try await downloadResolved(resolved, sourceURL: url, jobIndex: index)
                } else {
                    try await downloadDirect(url, jobIndex: index)
                }
            } else {
                try await downloadDirect(url, jobIndex: index)
            }
        } catch is CancellationError {
            guard !isManuallyFinishedJob(at: index) else { return }
            markCancelled(index)
        } catch PythonScriptBridgeError.taskReaction(let name, let message) {
            guard !isManuallyFinishedJob(at: index) else { return }
            markFailed(index, message: message, reaction: name)
        } catch PythonScriptBridgeError.retryRequested(_, let message) {
            guard !isManuallyFinishedJob(at: index) else { return }
            markFailed(index, message: message, allowsIncompleteRetry: false)
        } catch {
            guard !isManuallyFinishedJob(at: index) else { return }
            if queueRecordingAutoRetryIfNeeded(at: index, error: error) {
                return
            }
            markFailed(
                index,
                message: error.localizedDescription,
                allowsIncompleteRetry: Self.failureAllowsIncompleteRetry(error)
            )
        }
    }

