            String(progress.assetCount)
        )
        persistQueue()
    }

    private func rangedResolvedDownload(_ resolved: ResolvedDownload, jobIndex: Int) throws -> ResolvedDownload {
        guard jobs.indices.contains(jobIndex) else { return resolved }
        let range = jobs[jobIndex].rangeExpression.trimmed
        guard !range.isEmpty else { return resolved }
        guard case .files = resolved.packageMode else {
            throw NativeDownloadError.unsupported("Range is only available for multi-file downloads.")
        }

        let indexes = try Self.assetIndexes(forRangeExpression: range, total: resolved.assets.count)
        let assets = indexes.map { index -> ResolvedAsset in
            var asset = resolved.assets[index]
            asset.metadata[Self.nameTemplateIndexMetadataKey] = String(index + 1)
            return asset
        }
        guard !assets.isEmpty else {
            throw NativeDownloadError.unsupported("Range did not match any files.")
        }

        var metadata = resolved.metadata
        metadata["range"] = range
        metadata["range_total"] = String(resolved.assets.count)
        metadata["range_selected"] = String(assets.count)
        metadata["range_indexes"] = Self.compactRangeDescription(fromZeroBasedIndexes: indexes)

        return ResolvedDownload(
            title: resolved.title,
            folderName: resolved.folderName,
            assets: assets,
            packageMode: resolved.packageMode,
            metadata: metadata,
            textMergePlan: resolved.textMergePlan,
            temporaryAssetDirectories: resolved.temporaryAssetDirectories
        )
    }

    nonisolated static func isValidAssetRangeExpression(_ expression: String) -> Bool {
        do {
            _ = try assetRangeSegments(from: expression)
            return true
        } catch {
            return false
        }
    }

    nonisolated static func assetIndexes(forRangeExpression expression: String, total: Int) throws -> [Int] {
        let segments = try assetRangeSegments(from: expression)
        guard !segments.isEmpty else { return Array(0..<max(0, total)) }
        guard total > 0 else { return [] }

        var indexes: [Int] = []
        var seen = Set<Int>()
        for segment in segments {
            let rawStart = segment.start ?? 1
            let rawEnd = segment.end ?? total
            let start = max(1, rawStart)
            let end = min(total, rawEnd)
            guard start <= end else { continue }
            for page in start...end {
                let index = page - 1
                if seen.insert(index).inserted {
                    indexes.append(index)
                }
            }
        }
        guard !indexes.isEmpty else {
            throw NativeDownloadError.unsupported("Range did not match any files.")
        }
        return indexes
    }

    nonisolated static func finiteAssetRangeUpperBound(_ expression: String) -> Int? {
        guard let segments = try? assetRangeSegments(from: expression), !segments.isEmpty else {
            return nil
        }
        var upperBound = 0
        for segment in segments {
            guard let end = segment.end else { return nil }
            upperBound = max(upperBound, end)
        }
        return upperBound > 0 ? upperBound : nil
    }

    private struct AssetRangeSegment {
        var start: Int?
        var end: Int?
    }

    private nonisolated static func assetRangeSegments(from expression: String) throws -> [AssetRangeSegment] {
        let trimmed = expression.trimmed
        guard !trimmed.isEmpty else { return [] }
        let compact = trimmed
            .replacingOccurrences(of: " ", with: "")
            .replacingOccurrences(of: "\t", with: "")
            .replacingOccurrences(of: "\n", with: "")
            .replacingOccurrences(of: "\r", with: "")
        let pieces = compact
            .components(separatedBy: CharacterSet(charactersIn: ",;"))
            .filter { !$0.isEmpty }
        guard !pieces.isEmpty else {
            throw NativeDownloadError.unsupported("Invalid range.")
        }

        return try pieces.map { piece in
            if let split = rangeSplit(piece) {
                let start = try positiveRangeBound(split.0)
                let end = try positiveRangeBound(split.1)
                guard start != nil || end != nil else {
                    throw NativeDownloadError.unsupported("Invalid range.")
                }
                if let start, let end, start > end {
                    throw NativeDownloadError.unsupported("Invalid range.")
                }
                return AssetRangeSegment(start: start, end: end)
            }

            guard let page = Int(piece), page > 0 else {
                throw NativeDownloadError.unsupported("Invalid range.")
            }
            return AssetRangeSegment(start: page, end: page)
        }
    }

    private nonisolated static func rangeSplit(_ value: String) -> (String, String)? {
        for separator in ["...", "..", "~", "-"] {
            if let range = value.range(of: separator) {
                let start = String(value[..<range.lowerBound])
                let end = String(value[range.upperBound...])
                return (start, end)
            }
        }
        return nil
    }

    private nonisolated static func positiveRangeBound(_ value: String) throws -> Int? {
        guard !value.isEmpty else { return nil }
        guard let bound = Int(value), bound > 0 else {
            throw NativeDownloadError.unsupported("Invalid range.")
        }
        return bound
    }

    private nonisolated static func compactRangeDescription(fromZeroBasedIndexes indexes: [Int]) -> String {
        guard !indexes.isEmpty else { return "" }
        var pieces: [String] = []
        var start = indexes[0] + 1
        var previous = start

        for index in indexes.dropFirst().map({ $0 + 1 }) {
            if index == previous + 1 {
                previous = index
                continue
            }
            pieces.append(start == previous ? "\(start)" : "\(start)-\(previous)")
            start = index
            previous = index
        }
        pieces.append(start == previous ? "\(start)" : "\(start)-\(previous)")
        return pieces.joined(separator: ",")
    }

    private func downloadResolved(_ resolved: ResolvedDownload, sourceURL: URL, jobIndex: Int) async throws {
        guard jobs.indices.contains(jobIndex) else { return }
        var previousMetadata = jobs[jobIndex].metadata
        var resolved = resolved
        let temporaryAssetDirectories = resolved.temporaryAssetDirectories
        defer { Self.cleanupResolvedTemporaryAssetDirectories(temporaryAssetDirectories) }
        var sourceURL = sourceURL
        var hookContext = PythonScriptBridge.hookContext(job: jobs[jobIndex], sourceURL: sourceURL, resolved: resolved)
        let downloadHooksAlreadyRan = previousMetadata["python_hook_download_ran"] == "true"
        var didRunPythonDownloadHooks = false
        if !downloadHooksAlreadyRan,
           !effectivePythonHookCalls(for: .taskAboutToDownload).isEmpty {
            hookContext = try await runPythonHooks(event: .taskAboutToDownload, context: hookContext)
            resolved = try PythonScriptBridge.resolvedDownload(resolved, applying: hookContext)
            didRunPythonDownloadHooks = true
            if let hookedSourceURL = URL(string: hookContext.sourceURL.trimmed), !hookContext.sourceURL.trimmed.isEmpty {
                sourceURL = hookedSourceURL
                jobs[jobIndex].source = hookedSourceURL.absoluteString
            }
        }
        let formatType = hookContext.type?.trimmed.isEmpty == false
            ? hookContext.type!.trimmed
            : resolved.metadata["type"]?.trimmed ?? ""
        let formatNames: Set<String> = formatType.isEmpty ? [] : [formatType]
        if !downloadHooksAlreadyRan,
           !formatNames.isEmpty,
           !effectivePythonHookCalls(for: .format, matchingNames: formatNames).isEmpty {
            hookContext = PythonScriptBridge.hookContext(
                job: jobs[jobIndex],
                sourceURL: sourceURL,
                resolved: resolved
            )
            hookContext = try await runPythonHooks(
                event: .format,
                context: hookContext,
                matchingNames: formatNames
            )
            resolved = try PythonScriptBridge.resolvedDownload(resolved, applying: hookContext)
            didRunPythonDownloadHooks = true
        }
        if didRunPythonDownloadHooks {
            previousMetadata["python_hook_download_ran"] = "true"
            let hookKeys = previousMetadata["python_hook_preserved_keys", default: ""]
                .split(separator: ",")
                .map { String($0).trimmed }
                .filter { !$0.isEmpty }
            previousMetadata["python_hook_preserved_keys"] = Set(hookKeys + ["python_hook_download_ran"])
                .sorted()
                .joined(separator: ",")
        }
        resolved = applyingHeaderRules(to: resolved)
        if resolved.metadata["niconico_live_session_token"] == nil,
           resolved.metadata["range_scope"] != "collection_items" {
            resolved = try rangedResolvedDownload(resolved, jobIndex: jobIndex)
        }
        resolved.metadata = QueueThumbnailProvider.metadataByAddingThumbnail(
            resolved.metadata,
            assets: resolved.assets
        )
        let root = try outputRoot(for: sourceURL, metadata: resolved.metadata)
        let folderName = templatedFolderName(for: resolved, sourceURL: sourceURL)
        let range = jobs.indices.contains(jobIndex) ? jobs[jobIndex].rangeExpression.trimmed : ""
        let rangeTotal = resolved.metadata["range_total"].flatMap(Int.init)

        jobs[jobIndex].title = resolved.title
        jobs[jobIndex].metadata = Self.resolvedMetadataPreservingRuntimeState(
            resolved.metadata,
            previous: previousMetadata
        )
        jobs[jobIndex].metadata.removeValue(forKey: "niconico_live_session_token")
        jobs[jobIndex].resolvedFilenames = resolved.assets.map(\.filename)
        jobs[jobIndex].resolvedURLs = resolved.assets.map { $0.remoteURL.absoluteString }
        jobs[jobIndex].total = resolved.assets.count
        jobs[jobIndex].completed = 0
        jobs[jobIndex].progress = 0
        jobs[jobIndex].status = .downloading
        jobs[jobIndex].message = range.isEmpty
            ? "Downloading \(resolved.assets.count) files"
            : "Downloading \(resolved.assets.count) of \(rangeTotal ?? resolved.assets.count) files"
        jobs[jobIndex].recordMessage(jobs[jobIndex].message)
        retrySnapshots.removeValue(forKey: jobs[jobIndex].id)
        persistQueue()

        if let sessionToken = resolved.metadata["niconico_live_session_token"] {
            try await downloadNiconicoLiveStream(
                resolved,
                sessionToken: sessionToken,
                root: root,
                sourceURL: sourceURL,
                jobIndex: jobIndex
            )
            return
        }

        switch resolved.packageMode {
        case .files:
            let assets = templatedAssets(resolved.assets, title: resolved.title, sourceURL: sourceURL, metadata: resolved.metadata)
            jobs[jobIndex].resolvedFilenames = assets.map(\.filename)
            let modificationDateSpacingBase = Self.shouldSpaceOriginalModificationDates(
                sourceURL: sourceURL,
                metadata: resolved.metadata,
                assetMetadata: assets.map(\.metadata)
            ) ? Date() : nil
            let folder = AppPaths.directoryURL(in: root, name: folderName)
            try AppPaths.ensureDirectory(folder)
            jobs[jobIndex].outputPath = folder.path
            persistQueue()
            let downloadedAssets = try await downloadAssets(
                assets,
                to: folder,
                jobIndex: jobIndex,
                modificationDateSpacingBase: modificationDateSpacingBase
            )
            if jobs.indices.contains(jobIndex) {
                if let plan = resolved.textMergePlan {
                    let merged = try Self.writeMergedText(
                        plan: plan,
                        inputFiles: downloadedAssets,
                        to: folder
                    )
                    jobs[jobIndex].metadata["text_merge_output"] = merged.path
                    jobs[jobIndex].metadata["text_merge_filename"] = merged.lastPathComponent
                    jobs[jobIndex].metadata["text_merge_count"] = String(downloadedAssets.count)
                    jobs[jobIndex].metadata["postprocess"] = "text-merge"
                    persistQueue()
                }
                writeHitomiGalleryInfoTextIfNeeded(metadata: resolved.metadata, sourceURL: sourceURL, folder: folder, jobIndex: jobIndex)
                try archiveFolderIfNeeded(
                    folder,
                    sourceURL: sourceURL,
                    metadata: resolved.metadata,
                    jobIndex: jobIndex
                )
                jobs[jobIndex].status = .finished
                jobs[jobIndex].progress = 1
                jobs[jobIndex].message = "Done"
                await completeJob(at: jobIndex)
            }
        case .concatenate(let outputFilename):
            let folder = root.appendingPathComponent(".\(folderName.sanitizedFilename(maxLength: 120))-\(UUID().uuidString)", isDirectory: true)
            try AppPaths.ensureDirectory(folder)
            let outputMetadata = Self.mergedNameTemplateMetadata(
                resolved.metadata,
                assetMetadata: resolved.assets.first?.metadata ?? [:]
            )
            let outputName = templatedConcatenatedFileName(
                original: outputFilename,
                title: resolved.title,
                sourceURL: sourceURL,
                total: resolved.assets.count,
                metadata: outputMetadata,
                packageMode: resolved.packageMode
            )
            let output = AppPaths.uniqueFileURL(in: root, filename: outputName)
            jobs[jobIndex].outputPath = output.path
            jobs[jobIndex].resolvedFilenames = [output.lastPathComponent]
            persistQueue()
            if Self.shouldPollLiveHLS(resolved) {
                try await downloadLiveHLSAndConcatenate(
                    resolved,
                    tempFolder: folder,
                    output: output,
                    jobIndex: jobIndex
                )
            } else {
                try await downloadAndConcatenate(resolved.assets, tempFolder: folder, output: output, jobIndex: jobIndex)
            }
            let finalOutput = try await remuxHLSIfNeeded(output, resolved: resolved, jobIndex: jobIndex)
            applyYouTubeUploadModificationDateIfNeeded(
                to: finalOutput,
                sourceURL: sourceURL,
                metadata: resolved.metadata
            )
            if jobs.indices.contains(jobIndex) {
                let recordingWasStopped = jobs[jobIndex].metadata["live_end_reason"] == "stopped"
                jobs[jobIndex].status = .finished
                jobs[jobIndex].progress = 1
                jobs[jobIndex].message = recordingWasStopped ? "Recording stopped" : "Done"
                jobs[jobIndex].outputPath = finalOutput.path
                await completeJob(at: jobIndex)
            }
        case .mux(let videoAssets, let audioAssets, let outputFilename):
            try await downloadAndMux(
                videoAssets: videoAssets,
                audioAssets: audioAssets,
                folderName: folderName,
                outputFilename: templatedFileName(
                    original: outputFilename,
                    title: resolved.title,
                    sourceURL: sourceURL,
                    index: nil,
                    total: resolved.assets.count,
                    metadata: Self.mergedNameTemplateMetadata(
                        resolved.metadata,
                        assetMetadata: videoAssets.first?.metadata ?? audioAssets.first?.metadata ?? [:]
                    )
                ),
                root: root,
                jobIndex: jobIndex
            )
        case .grouped(let fileAssetIndexes, let concatenations):
            try await downloadGroupedPackage(
                resolved,
                fileAssetIndexes: fileAssetIndexes,
                concatenations: concatenations,
                muxes: [],
                root: root,
                folderName: folderName,
                sourceURL: sourceURL,
                jobIndex: jobIndex
            )
        case .groupedMedia(let fileAssetIndexes, let concatenations, let muxes):
            try await downloadGroupedPackage(
                resolved,
                fileAssetIndexes: fileAssetIndexes,
                concatenations: concatenations,
                muxes: muxes,
                root: root,
                folderName: folderName,
                sourceURL: sourceURL,
                jobIndex: jobIndex
            )
        }
    }

    @discardableResult
    private func downloadAssets(
        _ assets: [ResolvedAsset],
        to folder: URL,
        jobIndex: Int,
        modificationDateSpacingBase: Date? = nil
    ) async throws -> [URL] {
        let jobID = jobs[jobIndex].id
        let limit = AsyncSemaphore(value: Self.assetDownloadConcurrency(defaultValue: concurrency, assets: assets))
        let remoteSegmentConcurrency = max(1, min(24, concurrency))
        let hlsRateLimiter = HLSRequestRateLimiter(
            delayNanoseconds: Self.m3u8SegmentRateLimitNanoseconds(from: m3u8SegmentDelayMillisecondsString)
        )
        let continueHLSSegmentFailures = hlsContinueOnSegmentFailure
        let skipExistingAssetDownloads = skipDuplicates
        let imageConversionFormat = jobImageConversionFormat(for: jobs[jobIndex]) ?? imageConversionFormat
        let pythonRuntimePath = pythonPath
        let youtubeUploadDateMetadata = jobs.indices.contains(jobIndex)
            ? jobs[jobIndex].metadata
            : [:]
        let youtubeUploadDateSourceURL = jobs.indices.contains(jobIndex)
            ? URL(string: jobs[jobIndex].source)
            : nil
        let shouldApplyYouTubeUploadDate = youtubeUseUploadDateForFileModificationTime &&
            youtubeUploadDateSourceURL.map {
                YTDLPBridge.isYouTubeSource($0, metadata: youtubeUploadDateMetadata)
            } == true
        let reportsNativeByteProgress = assets.count == 1 && assets.first.map {
            Self.shouldReportNativeTransferProgress(asset: $0, jobMetadata: youtubeUploadDateMetadata)
        } == true
        let nativeTransferProgressHandler: HTTPDownloadProgressHandler? = reportsNativeByteProgress
            ? makeNativeTransferProgressHandler(jobID: jobID)
            : nil
        defer {
            if reportsNativeByteProgress,
               let currentIndex = jobs.firstIndex(where: { $0.id == jobID }) {
                jobs[currentIndex].metadata["transfer_active"] = "false"
                if jobs[currentIndex].metadata["byte_count"] == nil,
                   let total = jobs[currentIndex].metadata["total_bytes"] {
                    jobs[currentIndex].metadata["byte_count"] = total
                }
                persistQueue()
            }
        }
        var downloadedItems: [URL] = []
        var downloadedItemsByAssetIndex: [Int: URL] = [:]
        var skippedFailureCount = 0
        var skippedExistingCount = 0
        var deferredGalleryFailure: AssetDownloadFailure?

        do {
            try await withThrowingTaskGroup(of: AssetDownloadResult.self) { group in
                for (offset, asset) in assets.enumerated() {
                    group.addTask {
                        try Task.checkCancellation()
                        return try await limit.withPermit {
                            let outputFilename = Self.assetOutputFilename(asset, imageConversionFormat: imageConversionFormat)
                            let assetModificationDate = Self.assetOriginalModificationDate(asset) ??
                                (shouldApplyYouTubeUploadDate
                                    ? YTDLPBridge.youtubeUploadModificationDate(
                                        from: youtubeUploadDateMetadata.merging(asset.metadata) { _, assetValue in
                                            assetValue
                                        }
                                    )
                                    : nil)
                            if let existing = Self.existingSkippableAssetURL(
                                asset,
                                in: folder,
                                skipDuplicates: skipExistingAssetDownloads,
                                outputFilename: outputFilename
                            ) {
                                if let originalDate = assetModificationDate {
                                    try? Self.applyModificationDate(originalDate, to: existing)
                                } else if let modificationDateSpacingBase {
                                    try? Self.applyOriginalModificationDateSpacing(
                                        to: existing,
                                        baseDate: modificationDateSpacingBase,
                                        index: offset
                                    )
                                }
                                return AssetDownloadResult(assetIndex: offset, destination: existing, skippedExisting: true)
                            }

                            let destination = AppPaths.uniqueFileURL(in: folder, filename: outputFilename)
                            var downloadedDestination = destination
                            do {
                                if Self.assetUsesM3U8RateLimit(asset) {
                                    try await hlsRateLimiter.waitIfNeeded()
                                }
                                downloadedDestination = try await self.downloadAsset(
                                    asset,
                                    to: destination,
                                    remoteSegmentConcurrency: remoteSegmentConcurrency,
                                    progressHandler: nativeTransferProgressHandler
                                )
                                try Self.convertDownloadedImageIfNeeded(
                                    at: downloadedDestination,
                                    asset: asset,
                                    format: imageConversionFormat
                                )
                                if let originalDate = assetModificationDate {
                                    try? Self.applyModificationDate(originalDate, to: downloadedDestination)
                                } else if let modificationDateSpacingBase {
                                    try? Self.applyOriginalModificationDateSpacing(
                                        to: downloadedDestination,
                                        baseDate: modificationDateSpacingBase,
                                        index: offset
                                    )
                                }
                                return AssetDownloadResult(assetIndex: offset, destination: downloadedDestination)
                            } catch {
                                try? FileManager.default.removeItem(at: destination)
                                if downloadedDestination != destination {
                                    try? FileManager.default.removeItem(at: downloadedDestination)
                                }
                                let failure = AssetDownloadFailure(index: offset + 1, asset: asset, underlying: error)
                                if ((continueHLSSegmentFailures || asset.metadata["python_ignore_error"] == "true") &&
                                    Self.assetCanContinueAfterHLSFailure(asset)) ||
                                    Self.assetCanDeferGalleryFailure(asset) {
                                    return AssetDownloadResult(assetIndex: offset, skippedFailure: failure)
                                }
                                throw failure
                            }
                        }
                    }
                }

                for try await result in group {
                    try Task.checkCancellation()
                    if let destination = result.destination {
                        downloadedItems.append(destination)
                        if let assetIndex = result.assetIndex {
                            downloadedItemsByAssetIndex[assetIndex] = destination
                        }
                    }
                    if let failure = result.skippedFailure {
                        skippedFailureCount += 1
                        if Self.assetCanDeferGalleryFailure(failure.asset), deferredGalleryFailure == nil {
                            deferredGalleryFailure = failure
                        }
                        recordSkippedAssetDownloadFailure(failure, total: assets.count, jobIndex: jobIndex)
                    }
                    if result.skippedExisting {
                        skippedExistingCount += 1
                    }
                    if jobs.indices.contains(jobIndex) {
                        if reportsNativeByteProgress,
                           let destination = result.destination {
                            let downloadedBytes = Self.fileByteCount(destination)
                            jobs[jobIndex].metadata["downloaded_bytes"] = String(downloadedBytes)
                            jobs[jobIndex].metadata["total_bytes"] = jobs[jobIndex].metadata["total_bytes"] ?? String(downloadedBytes)
                            jobs[jobIndex].metadata["byte_count"] = String(downloadedBytes)
                            jobs[jobIndex].metadata["transfer_fraction"] = "1"
                        }
                        jobs[jobIndex].completed += 1
                        jobs[jobIndex].progress = Double(jobs[jobIndex].completed) / Double(max(1, jobs[jobIndex].total))
                        jobs[jobIndex].message = Self.assetProgressMessage(
                            completed: jobs[jobIndex].completed,
                            total: jobs[jobIndex].total,
                            skippedExisting: skippedExistingCount,
                            skippedFailures: skippedFailureCount
                        )
                        persistQueue()
                    }
                }
            }
        } catch let failure as AssetDownloadFailure {
            recordAssetDownloadFailure(failure, total: assets.count, jobIndex: jobIndex)
            throw failure.underlying
        }

        if let deferredGalleryFailure {
            recordAssetDownloadFailure(deferredGalleryFailure, total: assets.count, jobIndex: jobIndex)
            if jobs.indices.contains(jobIndex) {
                jobs[jobIndex].metadata["incomplete_gallery"] = "true"
                jobs[jobIndex].metadata["incomplete_file_count"] = String(skippedFailureCount)
                jobs[jobIndex].metadata["downloaded_file_count"] = String(downloadedItems.count)
                persistQueue()
            }
            throw deferredGalleryFailure.underlying
        }

        let decoratedAssets = assets.enumerated().compactMap { index, asset -> (Int, PythonSegmentDecorator)? in
            guard let decorator = asset.pythonSegmentDecorator,
                  downloadedItemsByAssetIndex[index] != nil else { return nil }
            return (index, decorator)
        }
        let decoratorGroups = Dictionary(grouping: decoratedAssets, by: { $0.1 })
        for (decorator, entries) in decoratorGroups {
            let paths = entries
                .sorted { $0.0 < $1.0 }
                .compactMap { downloadedItemsByAssetIndex[$0.0] }
            guard !paths.isEmpty else { continue }
            if jobs.indices.contains(jobIndex) {
                jobs[jobIndex].message = "Applying Python segment transform"
                persistQueue()
            }
            try await PythonScriptBridge(configuredPythonPath: pythonRuntimePath)
                .decorateSegments(paths, using: decorator)
        }

        if skippedExistingCount > 0, jobs.indices.contains(jobIndex) {
            jobs[jobIndex].metadata["skipped_existing_files"] = String(skippedExistingCount)
            jobs[jobIndex].metadata["skip_reason"] = "existing_output_files"
            persistQueue()
        }

        if downloadedItems.isEmpty && !assets.isEmpty {
            throw NativeDownloadError.noFiles
        }

        return downloadedItemsByAssetIndex
            .sorted { $0.key < $1.key }
            .map(\.value)
    }

    @discardableResult
    nonisolated static func writeMergedText(
        plan: ResolvedTextMergePlan,
        inputFiles: [URL],
        to folder: URL,
        fileManager: FileManager = .default
    ) throws -> URL {
        guard !inputFiles.isEmpty else { throw NativeDownloadError.noFiles }
        try AppPaths.ensureDirectory(folder)
        let output = AppPaths.uniqueFileURL(
            in: folder,
            filename: plan.outputFilename.sanitizedFilename(maxLength: 180)
        )
        var completed = false
        defer {
            if !completed { try? fileManager.removeItem(at: output) }
        }
        fileManager.createFile(atPath: output.path, contents: Data(plan.header.utf8))
        let writer = try FileHandle(forWritingTo: output)
        defer { try? writer.close() }
        try writer.seekToEnd()

        let separator = Data(plan.separator.utf8)
        for input in inputFiles {
            try Task.checkCancellation()
            if !separator.isEmpty {
                try writer.write(contentsOf: separator)
            }
            do {
                let reader = try FileHandle(forReadingFrom: input)
                defer { try? reader.close() }
                while true {
                    let chunk = try reader.read(upToCount: 1_048_576) ?? Data()
                    if chunk.isEmpty { break }
                    try writer.write(contentsOf: chunk)
                }
            }
        }
        completed = true
        return output
    }

    nonisolated static func cleanupResolvedTemporaryAssetDirectories(
        _ directories: [URL],
        fileManager: FileManager = .default
    ) {
        let temporaryRoot = fileManager.temporaryDirectory.standardizedFileURL
        for rawCandidate in Set(directories.map(\.standardizedFileURL)) {
            guard rawCandidate.deletingLastPathComponent() == temporaryRoot,
                  rawCandidate.lastPathComponent.hasPrefix("HitomiBadayo-") ||
                    rawCandidate.lastPathComponent.hasPrefix("HitomiNative-") else {
                continue
            }
            try? fileManager.removeItem(at: rawCandidate)
        }
    }

    nonisolated static func assetDownloadConcurrency(defaultValue: Int, assets: [ResolvedAsset]) -> Int {
        let override = assets.lazy.compactMap { asset in
            Int(asset.metadata["asset_concurrency_override"] ?? "")
        }.first { $0 > 0 }
        let cap = assets.lazy.compactMap { asset in
            Int(asset.metadata["asset_concurrency_cap"] ?? "")
        }.filter { $0 > 0 }.min() ?? 24
        return max(1, min(24, cap, override ?? defaultValue))
    }

    private func recordAssetDownloadFailure(_ failure: AssetDownloadFailure, total: Int, jobIndex: Int) {
        guard jobs.indices.contains(jobIndex) else { return }
        let message = failure.underlying.localizedDescription
        let segmentIndex = displaySegmentIndex(for: failure)
        let segmentTotal = displaySegmentTotal(for: failure, fallbackTotal: total, jobIndex: jobIndex)
        jobs[jobIndex].metadata["last_error"] = message
        jobs[jobIndex].metadata["failed_segment_index"] = String(segmentIndex)
        jobs[jobIndex].metadata["failed_segment_total"] = String(segmentTotal)
        jobs[jobIndex].metadata["failed_segment_filename"] = failure.asset.filename
        jobs[jobIndex].metadata["failed_segment_url"] = failure.asset.remoteURL.absoluteString
        jobs[jobIndex].message = "Segment \(segmentIndex) / \(segmentTotal) failed"
        persistQueue()
    }

    private func recordSkippedAssetDownloadFailure(_ failure: AssetDownloadFailure, total: Int, jobIndex: Int) {
        guard jobs.indices.contains(jobIndex) else { return }
        let message = failure.underlying.localizedDescription
        let segmentIndex = displaySegmentIndex(for: failure)
        let segmentTotal = displaySegmentTotal(for: failure, fallbackTotal: total, jobIndex: jobIndex)
        jobs[jobIndex].metadata["last_error"] = message
        jobs[jobIndex].metadata["skipped_segment_count"] = String((Int(jobs[jobIndex].metadata["skipped_segment_count"] ?? "0") ?? 0) + 1)
        jobs[jobIndex].metadata["skipped_segment_total"] = String(segmentTotal)
        appendMetadataListValue(key: "skipped_segment_indexes", value: String(segmentIndex), jobIndex: jobIndex)
        appendMetadataListValue(key: "skipped_segment_filenames", value: failure.asset.filename, jobIndex: jobIndex)
        appendMetadataListValue(key: "skipped_segment_urls", value: failure.asset.remoteURL.absoluteString, jobIndex: jobIndex)
        persistQueue()
    }

    private func displaySegmentIndex(for failure: AssetDownloadFailure) -> Int {
        if let segmentNumber = Int(failure.asset.metadata["segment_number"] ?? ""), segmentNumber > 0 {
            return segmentNumber
        }
        return failure.index
    }

    private func displaySegmentTotal(for failure: AssetDownloadFailure, fallbackTotal: Int, jobIndex: Int) -> Int {
        if let segmentTotal = Int(failure.asset.metadata["segment_total"] ?? ""), segmentTotal > 0 {
            return segmentTotal
        }
        if jobs.indices.contains(jobIndex),
           let jobSegmentCount = Int(jobs[jobIndex].metadata["segment_count"] ?? ""),
           jobSegmentCount > 0,
           Self.assetCanContinueAfterHLSFailure(failure.asset) {
            return jobSegmentCount
        }
        return fallbackTotal
    }

    private func appendMetadataListValue(key: String, value: String, jobIndex: Int) {
        guard jobs.indices.contains(jobIndex), !value.trimmed.isEmpty else { return }
        let previous = jobs[jobIndex].metadata[key]?.trimmed
        jobs[jobIndex].metadata[key] = previous?.isEmpty == false ? "\(previous!), \(value)" : value
    }

    nonisolated static func assetProgressMessage(
        completed: Int,
        total: Int,
        skippedExisting: Int,
        skippedFailures: Int
    ) -> String {
        var suffixes: [String] = []
        if skippedExisting > 0 {
            suffixes.append("\(skippedExisting) existing")
        }
        if skippedFailures > 0 {
            suffixes.append("\(skippedFailures) skipped")
        }
        let base = "\(completed) / \(total)"
        return suffixes.isEmpty ? base : "\(base), \(suffixes.joined(separator: ", "))"
    }

    nonisolated static func assetCanSkipExistingOutput(_ asset: ResolvedAsset) -> Bool {
        guard asset.decryption == nil,
              asset.xorKey == nil,
              asset.pixivGridShuffle == nil,
              asset.lezhinImageShuffle == nil,
              asset.pythonSegmentDecorator == nil,
              !assetUsesM3U8RateLimit(asset) else {
            return false
        }
        return true
    }

    nonisolated static func assetOutputFilename(_ asset: ResolvedAsset, imageConversionFormat: ImageConversionFormat) -> String {
        if assetIsPixivUgoira(asset) {
            return asset.filename
        }
        return convertedImageFilename(
            asset.filename,
            metadata: asset.metadata,
            remoteURL: asset.remoteURL,
            format: imageConversionFormat
        )
    }

    nonisolated static func convertedImageFilename(
        _ filename: String,
        metadata: [String: String] = [:],
        remoteURL: URL? = nil,
        format: ImageConversionFormat
    ) -> String {
        guard let targetExtension = format.fileExtension,
              isConvertibleImage(filename: filename, metadata: metadata, remoteURL: remoteURL) else {
            return filename
        }

        let path = filename as NSString
        let currentExtension = path.pathExtension.lowercased()
        if currentExtension == targetExtension {
            return filename
        }

        let base = path.deletingPathExtension
        if base.trimmed.isEmpty || currentExtension.isEmpty {
            return "\(filename).\(targetExtension)"
        }
        return "\(base).\(targetExtension)"
    }

    nonisolated static func convertDownloadedImageIfNeeded(
        at url: URL,
        asset: ResolvedAsset,
        format: ImageConversionFormat,
        fileManager: FileManager = .default
    ) throws {
        guard !assetIsPixivUgoira(asset) else { return }
        guard let targetExtension = format.fileExtension,
              isConvertibleImage(filename: asset.filename, metadata: asset.metadata, remoteURL: asset.remoteURL) else {
            return
        }
        if (asset.filename as NSString).pathExtension.lowercased() == targetExtension {
            return
        }
        try convertImage(at: url, to: format, fileManager: fileManager)
    }

    nonisolated static func convertOutputImages(
        forOutputPath outputPath: String,
        to format: ImageConversionFormat,
        quality: Int = 95,
        fileManager: FileManager = .default
    ) throws -> OutputImageConversionResult {
        guard let targetExtension = format.fileExtension else {
            return OutputImageConversionResult(items: [], unchangedCount: 0, primaryOutputPath: outputPath)
        }

        let value = (outputPath.trimmed as NSString).expandingTildeInPath
        guard !value.isEmpty else {
            return OutputImageConversionResult(items: [], unchangedCount: 0, primaryOutputPath: nil)
        }

        let root = URL(fileURLWithPath: value).standardizedFileURL
        var rootIsDirectory = ObjCBool(false)
        guard fileManager.fileExists(atPath: root.path, isDirectory: &rootIsDirectory) else {
            return OutputImageConversionResult(items: [], unchangedCount: 0, primaryOutputPath: nil)
        }

        let files = outputImageFiles(at: root, isDirectory: rootIsDirectory.boolValue, fileManager: fileManager)
        var items: [OutputImageConversionItem] = []
        var unchangedCount = 0
        var primaryOutputPath = root.path

        for source in files {
            let sourceExtension = source.pathExtension.lowercased()
            if sourceExtension == targetExtension {
                unchangedCount += 1
                continue
            }

            let destination = source.deletingPathExtension().appendingPathExtension(targetExtension)
            if source.standardizedFileURL == destination.standardizedFileURL {
                unchangedCount += 1
                continue
            }
            guard !fileManager.fileExists(atPath: destination.path) else {
                throw NativeDownloadError.unsupported("Image conversion destination already exists: \(destination.lastPathComponent)")
            }

            let data = try convertedImageData(at: source, to: format, quality: quality)
            let temporary = destination.deletingLastPathComponent()
                .appendingPathComponent(".\(destination.lastPathComponent).convert-\(UUID().uuidString)")
            do {
                try data.write(to: temporary, options: .atomic)
                try fileManager.moveItem(at: temporary, to: destination)
                do {
                    try fileManager.removeItem(at: source)
                } catch {
                    try? fileManager.removeItem(at: destination)
                    throw error
                }
            } catch {
                try? fileManager.removeItem(at: temporary)
                throw error
            }

            items.append(OutputImageConversionItem(
                originalPath: source.path,
                convertedPath: destination.path
            ))
            if !rootIsDirectory.boolValue {
                primaryOutputPath = destination.path
            }
        }

        return OutputImageConversionResult(
            items: items,
            unchangedCount: unchangedCount,
            primaryOutputPath: primaryOutputPath
        )
    }

    private nonisolated static func outputImageFiles(
        at root: URL,
        isDirectory: Bool,
        fileManager: FileManager
    ) -> [URL] {
        if !isDirectory {
            let ext = root.pathExtension.lowercased()
            return convertibleImageExtensions.contains(ext) && fileManager.isReadableFile(atPath: root.path)
                ? [root]
                : []
        }

        guard let enumerator = fileManager.enumerator(
            at: root,
            includingPropertiesForKeys: [.isRegularFileKey, .isReadableKey],
            options: [.skipsHiddenFiles, .skipsPackageDescendants],
            errorHandler: { _, _ in true }
        ) else {
            return []
        }

        var files: [URL] = []
        for case let file as URL in enumerator {
            let ext = file.pathExtension.lowercased()
            guard convertibleImageExtensions.contains(ext),
                  let values = try? file.resourceValues(forKeys: [.isRegularFileKey, .isReadableKey]),
                  values.isRegularFile == true,
                  values.isReadable != false else {
                continue
            }
            files.append(file)
        }
        return files.sorted { $0.path.localizedStandardCompare($1.path) == .orderedAscending }
    }

    nonisolated static func convertImage(
        at url: URL,
        to format: ImageConversionFormat,
        quality: Int = 95,
        fileManager: FileManager = .default
    ) throws {
        guard bitmapFileType(for: format) != nil else { return }
        let data = try convertedImageData(at: url, to: format, quality: quality)

        let temporary = url.deletingLastPathComponent().appendingPathComponent(".\(url.lastPathComponent).convert-\(UUID().uuidString)")
        try data.write(to: temporary, options: .atomic)
        if fileManager.fileExists(atPath: url.path) {
            try fileManager.removeItem(at: url)
        }
        try fileManager.moveItem(at: temporary, to: url)
    }

    private nonisolated static func convertedImageData(
        at url: URL,
        to format: ImageConversionFormat,
        quality: Int
    ) throws -> Data {
        guard let fileType = bitmapFileType(for: format) else {
            throw NativeDownloadError.unsupported("Image conversion format is unavailable.")
        }
        guard let source = CGImageSourceCreateWithURL(url as CFURL, nil),
              let image = CGImageSourceCreateImageAtIndex(source, 0, nil) else {
            throw NativeDownloadError.unsupported("Image conversion failed: \(url.lastPathComponent)")
        }

        let bitmap = NSBitmapImageRep(cgImage: image)
        var properties: [NSBitmapImageRep.PropertyKey: Any] = [:]
        if format == .jpeg {
            properties[.compressionFactor] = Double(max(1, min(quality, 100))) / 100
        }
        guard let data = bitmap.representation(using: fileType, properties: properties) else {
            throw NativeDownloadError.unsupported("Image conversion failed: \(url.lastPathComponent)")
        }
        return data
    }

    private nonisolated static func assetIsPixivUgoira(_ asset: ResolvedAsset) -> Bool {
        if asset.pixivUgoiraPackage != nil { return true }
        let type = metadataValue(asset.metadata, keys: ["media_type", "type"]).lowercased()
        return type == "ugoira"
    }

    nonisolated static func existingSkippableAssetURL(
        _ asset: ResolvedAsset,
        in folder: URL,
        skipDuplicates: Bool,
        outputFilename: String? = nil,
        fileManager: FileManager = .default
    ) -> URL? {
        guard skipDuplicates,
              assetCanSkipExistingOutput(asset) else {
            return nil
        }
        let filename = outputFilename ?? asset.filename
        if let existing = existingOutputFileURL(in: folder, filename: filename, fileManager: fileManager) {
            return existing
        }

        let originalExtension = (asset.filename as NSString).pathExtension.lowercased()
        let outputExtension = (filename as NSString).pathExtension.lowercased()
        guard !originalExtension.isEmpty,
              outputExtension == originalExtension else {
            return nil
        }
        let base = (filename as NSString).deletingPathExtension
        var seen = Set<String>()
        for alternative in asset.alternativeRemoteURLs {
            let ext = alternative.pathExtension.lowercased()
            guard !ext.isEmpty,
                  ext != outputExtension,
                  ext.range(of: #"^[a-z0-9]{1,8}$"#, options: .regularExpression) != nil,
                  seen.insert(ext).inserted else {
                continue
            }
            if let existing = existingOutputFileURL(
                in: folder,
                filename: "\(base).\(ext)",
                fileManager: fileManager
            ) {
                return existing
            }
        }
        return nil
    }

    private nonisolated static func bitmapFileType(for format: ImageConversionFormat) -> NSBitmapImageRep.FileType? {
        switch format {
        case .original: return nil
        case .jpeg: return .jpeg
        case .png: return .png
        case .tiff: return .tiff
        case .bmp: return .bmp
        }
    }

    private nonisolated static func isConvertibleImage(filename: String, metadata: [String: String], remoteURL: URL?) -> Bool {
        let candidates = [
            (filename as NSString).pathExtension.lowercased(),
            metadataValue(metadata, keys: ["format", "media_format", "ext", "extension"]),
            remoteURL?.pathExtension.lowercased() ?? ""
        ]
            .map { $0.lowercased().trimmed }
            .filter { !$0.isEmpty }
        if !candidates.isEmpty {
            return candidates.contains { convertibleImageExtensions.contains($0) }
        }

        let category = metadataValue(metadata, keys: ["category", "media_type", "type"]).lowercased()
        return ["image", "photo", "picture"].contains(category)
    }

    private nonisolated static let convertibleImageExtensions: Set<String> = [
        "avif", "bmp", "gif", "heic", "heif", "jpeg", "jpg", "png", "tif", "tiff", "webp"
    ]

    nonisolated static func assetUsesM3U8RateLimit(_ asset: ResolvedAsset) -> Bool {
        let type = (asset.metadata["type"] ?? "").lowercased()
        let mediaType = (asset.metadata["media_type"] ?? "").lowercased()
        return type == "hls_segment" || type == "hls_map" ||
            mediaType == "hls_segment" || mediaType == "hls_map"
    }

    nonisolated static func assetCanContinueAfterHLSFailure(_ asset: ResolvedAsset) -> Bool {
        let type = (asset.metadata["type"] ?? "").lowercased()
        let mediaType = (asset.metadata["media_type"] ?? "").lowercased()
        return type == "hls_segment" || mediaType == "hls_segment"
    }

    nonisolated static func assetCanDeferGalleryFailure(_ asset: ResolvedAsset) -> Bool {
        asset.metadata["continue_asset_failures"] == "true"
    }

    nonisolated static func shouldSpaceOriginalModificationDates(
        sourceURL: URL,
        metadata: [String: String],
        assetMetadata: [[String: String]] = []
    ) -> Bool {
        if isOriginalModificationDateSpacingHost(sourceURL.host?.lowercased() ?? "") {
            return true
        }

        let siteCandidates = [metadata] + assetMetadata
        return siteCandidates.contains { values in
            let site = metadataValue(values, keys: ["site", "handler", "extractor", "script"]).lowercased()
            return isOriginalModificationDateSpacingSite(site)
        }
    }

    nonisolated static func originalModificationDate(baseDate: Date, index: Int) -> Date {
        baseDate.addingTimeInterval(TimeInterval(max(0, index)))
    }

    nonisolated static func applyOriginalModificationDateSpacing(
        to url: URL,
        baseDate: Date,
        index: Int,
        fileManager: FileManager = .default
    ) throws {
        let date = originalModificationDate(baseDate: baseDate, index: index)
        try fileManager.setAttributes([.modificationDate: date], ofItemAtPath: url.path)
    }

    nonisolated static func assetOriginalModificationDate(_ asset: ResolvedAsset) -> Date? {
        for key in ["original_modification_time", "original_modification_timestamp"] {
            guard let raw = asset.metadata[key]?.trimmed,
                  let seconds = TimeInterval(raw),
                  seconds > 0 else {
                continue
            }
            return Date(timeIntervalSince1970: seconds > 10_000_000_000 ? seconds / 1_000 : seconds)
        }
        return nil
    }

    nonisolated static func applyModificationDate(
        _ date: Date,
        to url: URL,
        fileManager: FileManager = .default
    ) throws {
        try fileManager.setAttributes([.modificationDate: date], ofItemAtPath: url.path)
    }

    private func applyYouTubeUploadModificationDateIfNeeded(
        to url: URL,
        sourceURL: URL?,
        metadata: [String: String]
    ) {
        guard youtubeUseUploadDateForFileModificationTime,
              let sourceURL,
              YTDLPBridge.isYouTubeSource(sourceURL, metadata: metadata),
              let date = YTDLPBridge.youtubeUploadModificationDate(from: metadata) else {
            return
        }
        try? Self.applyModificationDate(date, to: url)
    }

    private nonisolated static func isOriginalModificationDateSpacingHost(_ host: String) -> Bool {
        host == "hitomi.la" ||
            host.hasSuffix(".hitomi.la") ||
            host == "e-hentai.org" ||
            host == "www.e-hentai.org" ||
            host == "exhentai.org" ||
            host == "www.exhentai.org" ||
            host == "e-hentai.test" ||
            host.hasSuffix(".e-hentai.test") ||
            host == "exhentai.test" ||
            host.hasSuffix(".exhentai.test")
    }

    private nonisolated static func isOriginalModificationDateSpacingSite(_ site: String) -> Bool {
        let normalized = site
            .replacingOccurrences(of: " ", with: "")
            .replacingOccurrences(of: "-", with: "")
            .replacingOccurrences(of: "_", with: "")
            .replacingOccurrences(of: ".", with: "")
        return normalized == "hitomi" ||
            normalized == "hitomila" ||
            normalized == "ehentai" ||
            normalized == "exhentai"
    }

    private func archiveFolderIfNeeded(
        _ folder: URL,
        sourceURL: URL,
        metadata: [String: String],
        jobIndex: Int
    ) throws {
        let behavior = archiveBehavior(for: sourceURL, metadata: metadata)
        guard behavior.archive else { return }
        guard jobs.indices.contains(jobIndex) else { return }

        jobs[jobIndex].message = "Creating \(behavior.format.label)"
        persistQueue()

        let archive = AppPaths.uniqueFileURL(
            in: folder.deletingLastPathComponent(),
            filename: "\(folder.lastPathComponent).\(behavior.format.fileExtension)"
        )
        let archived = try Self.archiveCompletedFolder(folder, to: archive, deleteOriginal: behavior.deleteOriginal)

        jobs[jobIndex].outputPath = archived.path
        jobs[jobIndex].metadata["archive_format"] = behavior.format.rawValue
        jobs[jobIndex].metadata["archive_path"] = archived.path
        jobs[jobIndex].metadata["archived_folder_path"] = folder.path
        jobs[jobIndex].metadata["archive_deleted_original"] = behavior.deleteOriginal ? "true" : "false"
        if let ruleName = behavior.ruleName {
            jobs[jobIndex].metadata["archive_setting"] = "site:\(ruleName)"
        } else {
            let sourceID = DownloadSourceFolderProfile.sourceID(for: sourceURL, metadata: metadata)
            jobs[jobIndex].metadata["archive_setting"] = DownloadSourceFolderProfile.isSettingsSourceID(sourceID)
                ? "source:\(sourceID)"
                : "global"
        }
        persistQueue()
    }

    func archiveBehavior(
        for sourceURL: URL,
        metadata: [String: String] = [:]
    ) -> (archive: Bool, deleteOriginal: Bool, ruleName: String?, format: ArchiveFileFormat) {
        if let rule = matchingArchiveRule(for: sourceURL) {
            switch rule.archiveMode {
            case .zip, .cbz:
                return (true, rule.deleteOriginalAfterArchiving, rule.name, rule.archiveMode.archiveFormat ?? .zip)
            case .none:
                return (false, false, rule.name, archiveFileFormat)
            case .default:
                break
            }
        }
        let sourceID = DownloadSourceFolderProfile.sourceID(for: sourceURL, metadata: metadata)
        let mode = sourceArchiveMode(for: sourceID)
        guard let format = mode.archiveFormat else {
            return (false, false, nil, archiveFileFormat)
        }
        return (true, sourceArchiveDeletesOriginal(for: sourceID), nil, format)
    }

    private func matchingArchiveRule(for url: URL) -> SiteRule? {
        guard url.host != nil else { return nil }
        return siteRules
            .filter { $0.archiveMode != .default }
            .sorted { $0.matchSpecificity > $1.matchSpecificity }
            .first { $0.matches(url) }
    }

    @discardableResult
    nonisolated static func archiveCompletedFolder(
        _ folder: URL,
        to archive: URL? = nil,
        deleteOriginal: Bool,
        fileManager: FileManager = .default
    ) throws -> URL {
        let destination = archive ?? AppPaths.uniqueFileURL(
            in: folder.deletingLastPathComponent(),
            filename: "\(folder.lastPathComponent).zip"
        )
        let sourcePath = folder.standardizedFileURL.path
        let destinationPath = destination.standardizedFileURL.path
        guard destinationPath != sourcePath,
              !destinationPath.hasPrefix(sourcePath.hasSuffix("/") ? sourcePath : "\(sourcePath)/") else {
            throw NativeDownloadError.unsupported("Archive destination must be outside the source folder.")
        }
        do {
            try ZipArchiveWriter.archiveDirectory(folder, to: destination, fileManager: fileManager)
        } catch {
            try? fileManager.removeItem(at: destination)
            throw error
        }
        if deleteOriginal {
            try fileManager.removeItem(at: folder)
        }
        return destination
    }

