    @discardableResult
    nonisolated static func writeHitomiGalleryInfoText(metadata: [String: String], sourceURL: URL, to folder: URL) throws -> URL? {
        guard isHitomiGalleryMetadata(metadata, sourceURL: sourceURL) else { return nil }
        try AppPaths.ensureDirectory(folder)
        let url = folder.appendingPathComponent("gallery-info.txt")
        try hitomiGalleryInfoText(metadata: metadata, sourceURL: sourceURL).write(to: url, atomically: true, encoding: .utf8)
        return url
    }

    nonisolated static func hitomiGalleryInfoText(metadata: [String: String], sourceURL: URL) -> String {
        let rows: [(String, String)] = [
            ("Title", metadataValue(metadata, keys: ["title"])),
            ("Gallery ID", metadataValue(metadata, keys: ["gallery_id", "media_id"])),
            ("Source", sourceURL.absoluteString),
            ("Site", metadataValue(metadata, keys: ["site"])),
            ("Type", metadataValue(metadata, keys: ["type", "category"])),
            ("Language", metadataValue(metadata, keys: ["language"])),
            ("Artist", metadataValue(metadata, keys: ["artist", "author", "creator"])),
            ("Group", metadataValue(metadata, keys: ["group", "circle"])),
            ("Parody", metadataValue(metadata, keys: ["parody", "series"])),
            ("Character", metadataValue(metadata, keys: ["character"])),
            ("Tags", metadataValue(metadata, keys: ["tags", "tag"])),
            ("Date", metadataValue(metadata, keys: ["date"])),
            ("Range", metadataValue(metadata, keys: ["range_indexes", "range"]))
        ]

        let body = rows
            .map { label, value in (label, value.trimmed) }
            .filter { !$0.1.isEmpty }
            .map { "\($0.0): \($0.1)" }
            .joined(separator: "\n")
        return body + "\n"
    }

    private nonisolated static func isHitomiGalleryMetadata(_ metadata: [String: String], sourceURL: URL) -> Bool {
        let site = metadataValue(metadata, keys: ["site"]).lowercased()
        if site == "hitomi" || site == "hitomi.la" {
            return true
        }
        if !metadataValue(metadata, keys: ["gallery_id"]).isEmpty,
           let host = sourceURL.host?.lowercased(),
           host == "hitomi.la" || host.hasSuffix(".hitomi.la") {
            return true
        }
        return false
    }

    nonisolated static func hitomiGalleryNumbers(in root: URL, fileManager: FileManager = .default) -> [String] {
        var isDirectory = ObjCBool(false)
        guard fileManager.fileExists(atPath: root.path, isDirectory: &isDirectory) else {
            return []
        }

        var numbers = Set<String>()
        if isDirectory.boolValue {
            numbers.formUnion(hitomiGalleryNumbers(fromOutputName: root.lastPathComponent))

            let resourceKeys: [URLResourceKey] = [.isDirectoryKey, .isRegularFileKey]
            guard let enumerator = fileManager.enumerator(
                at: root,
                includingPropertiesForKeys: resourceKeys,
                options: [.skipsHiddenFiles, .skipsPackageDescendants],
                errorHandler: { _, _ in true }
            ) else {
                return sortedGalleryNumbers(numbers)
            }

            for case let url as URL in enumerator {
                guard let values = try? url.resourceValues(forKeys: Set(resourceKeys)) else { continue }
                if values.isDirectory == true {
                    numbers.formUnion(hitomiGalleryNumbers(fromOutputName: url.lastPathComponent))
                } else if values.isRegularFile == true {
                    numbers.formUnion(hitomiGalleryNumbers(fromOutputFile: url))
                }
            }
        } else {
            numbers.formUnion(hitomiGalleryNumbers(fromOutputFile: root))
        }

        return sortedGalleryNumbers(numbers)
    }

    nonisolated static func hitomiGalleryNumbers(fromOutputName name: String) -> [String] {
        let decoded = name.removingPercentEncoding ?? name
        let normalized = decoded.replacingOccurrences(of: "\\", with: "/")
        var numbers = Set<String>()
        numbers.formUnion(hitomiGalleryNumbers(fromHitomiText: normalized, rejectsDates: false))

        let outputNamePatterns = [
            #"(?i)(?:hitomi|gallery|gal|gid|id|no|num|number|번호|번)\s*[:#._ \-]*([1-9][0-9]{3,})\b"#,
            #"(?i)(?:^|[\[(])\s*([1-9][0-9]{3,})\s*(?:[\])]|$)"#,
            #"(?i)(?:^|[\s._\-\[\(])([1-9][0-9]{4,})\s*(?:[\]\)]|$)"#
        ]

        for pattern in outputNamePatterns {
            numbers.formUnion(capturedGalleryNumbers(in: normalized, pattern: pattern, rejectsDates: true))
        }
        return sortedGalleryNumbers(numbers)
    }

    private nonisolated static func hitomiGalleryNumbers(fromOutputFile url: URL) -> [String] {
        let lowerName = url.lastPathComponent.lowercased()
        if hitomiGalleryInfoFilenames.contains(lowerName),
           let text = try? String(contentsOf: url, encoding: .utf8) {
            return hitomiGalleryNumbers(fromHitomiText: text, rejectsDates: false)
        }

        if archiveExtensions.contains(url.pathExtension.lowercased()) {
            let baseName = (url.lastPathComponent as NSString).deletingPathExtension
            return hitomiGalleryNumbers(fromOutputName: baseName)
        }

        return []
    }

    private nonisolated static func hitomiGalleryNumbers(fromHitomiText text: String, rejectsDates: Bool) -> [String] {
        let normalized = text.replacingOccurrences(of: "\\", with: "/")
        let patterns = [
            #"(?im)^\s*Gallery\s+ID\s*:\s*([0-9]+)\b"#,
            #"(?im)^\s*gallery[_\s-]*id\s*[:=]\s*([0-9]+)\b"#,
            #"hitomi\.la/(?:reader|galleries|g|lofi|mpv)/([0-9]+)(?:\.html)?\b"#,
            #"hitomi\.la/[^ \t\r\n<>"']*-([0-9]+)\.html\b"#,
            #"galleryblock/([0-9]+)"#,
            #"#-\*-[^#\r\n]*\(([0-9]+)\)"#
        ]

        var numbers = Set<String>()
        for pattern in patterns {
            numbers.formUnion(capturedGalleryNumbers(in: normalized, pattern: pattern, rejectsDates: rejectsDates))
        }
        return sortedGalleryNumbers(numbers)
    }

    private nonisolated static func capturedGalleryNumbers(in text: String, pattern: String, rejectsDates: Bool) -> [String] {
        guard let regex = try? NSRegularExpression(pattern: pattern, options: [.caseInsensitive]) else {
            return []
        }
        let range = NSRange(text.startIndex..<text.endIndex, in: text)
        return regex.matches(in: text, range: range).compactMap { match in
            guard match.numberOfRanges > 1,
                  let captureRange = Range(match.range(at: 1), in: text) else {
                return nil
            }
            return normalizedGalleryNumber(String(text[captureRange]), rejectsDates: rejectsDates)
        }
    }

    private nonisolated static func normalizedGalleryNumber(_ value: String, rejectsDates: Bool) -> String? {
        let trimmed = value.trimmed
        guard trimmed.range(of: #"^[0-9]+$"#, options: .regularExpression) != nil else {
            return nil
        }
        if rejectsDates, isLikelyCompactDate(trimmed) {
            return nil
        }
        let normalized = trimmed.drop { $0 == "0" }
        return normalized.isEmpty ? nil : String(normalized)
    }

    private nonisolated static func isLikelyCompactDate(_ value: String) -> Bool {
        guard value.count == 8,
              let year = Int(value.prefix(4)),
              let month = Int(value.dropFirst(4).prefix(2)),
              let day = Int(value.suffix(2)) else {
            return false
        }
        return (1900...2100).contains(year) && (1...12).contains(month) && (1...31).contains(day)
    }

    private nonisolated static func sortedGalleryNumbers(_ numbers: Set<String>) -> [String] {
        numbers.sorted { left, right in
            if let leftValue = Int64(left), let rightValue = Int64(right), leftValue != rightValue {
                return leftValue < rightValue
            }
            if left.count != right.count {
                return left.count < right.count
            }
            return left < right
        }
    }

    private nonisolated static func metadataValue(_ metadata: [String: String], keys: [String]) -> String {
        for key in keys {
            if let value = metadata.first(where: { $0.key.lowercased() == key.lowercased() })?.value.trimmed,
               !value.isEmpty {
                return value
            }
        }
        return ""
    }

    private nonisolated func downloadAsset(
        _ asset: ResolvedAsset,
        to destination: URL,
        remoteSegmentConcurrency: Int,
        progressHandler: HTTPDownloadProgressHandler? = nil
    ) async throws -> URL {
        let additionalHeaders = asset.additionalHeaderFields
        if asset.remoteURL.isFileURL {
            if FileManager.default.fileExists(atPath: destination.path) {
                try FileManager.default.removeItem(at: destination)
            }
            try FileManager.default.copyItem(at: asset.remoteURL, to: destination)
        } else if let decryption = asset.decryption {
            let encrypted = try await HTTPClient.shared.data(from: asset.remoteURL, referer: asset.referer, userAgent: asset.userAgent, additionalHeaders: additionalHeaders)
            let key = try await HTTPClient.shared.data(from: decryption.keyURL, referer: asset.referer, userAgent: asset.userAgent, additionalHeaders: additionalHeaders)
            let decrypted = try HLSDecrypter.decryptAES128CBC(data: encrypted, key: key, iv: decryption.iv)
            try decrypted.write(to: destination, options: .atomic)
        } else if let xorKey = asset.xorKey {
            let encrypted = try await HTTPClient.shared.data(from: asset.remoteURL, referer: asset.referer, userAgent: asset.userAgent, additionalHeaders: additionalHeaders)
            let decrypted = try ComicWalkerImageDecoder.decode(encrypted, hash: xorKey)
            try decrypted.write(to: destination, options: .atomic)
        } else if let shuffle = asset.pixivGridShuffle {
            var headers = additionalHeaders
            headers["X-Cobalt-Thumber-Parameter-Gridshuffle-Key"] = shuffle.key
            let encrypted = try await HTTPClient.shared.data(
                from: asset.remoteURL,
                referer: asset.referer,
                userAgent: asset.userAgent,
                additionalHeaders: headers
            )
            let decoded = try PixivComicImageDecoder.decode(encrypted, shuffle: shuffle)
            try decoded.write(to: destination, options: .atomic)
        } else if let shuffle = asset.lezhinImageShuffle {
            let encoded = try await HTTPClient.shared.data(
                from: asset.remoteURL,
                referer: asset.referer,
                userAgent: asset.userAgent,
                additionalHeaders: additionalHeaders
            )
            let decoded = try LezhinImageDecoder.decode(encoded, shuffle: shuffle)
            try decoded.write(to: destination, options: .atomic)
        } else if let ugoiraPackage = asset.pixivUgoiraPackage {
            let zip = try await HTTPClient.shared.data(from: asset.remoteURL, referer: asset.referer, userAgent: asset.userAgent, additionalHeaders: additionalHeaders)
            switch ugoiraPackage.outputFormat {
            case .ugoira:
                let packaged = try PixivUgoiraPackageWriter.package(originalZip: zip, package: ugoiraPackage)
                try packaged.write(to: destination, options: .atomic)
            case .gif, .webp, .png:
                try await FFmpegBridge().convertPixivUgoira(
                    originalZip: zip,
                    package: ugoiraPackage,
                    output: destination
                )
            case .zip:
                try zip.write(to: destination, options: .atomic)
            }
        } else if let segmentSize = asset.metadata["remote_segment_size"].flatMap(Int64.init),
                  segmentSize > 0 {
            try await downloadRemoteSegmentedAsset(
                asset,
                to: destination,
                segmentSize: segmentSize,
                maxConcurrency: remoteSegmentConcurrency,
                additionalHeaders: additionalHeaders
            )
        } else if let rangeStart = asset.metadata["range_start"].flatMap(Int64.init),
                  let rangeEnd = asset.metadata["range_end"].flatMap(Int64.init),
                  rangeStart >= 0,
                  rangeEnd >= rangeStart,
                  additionalHeaders["Range"] != nil {
            try await downloadByteRangeAsset(
                asset,
                to: destination,
                start: rangeStart,
                end: rangeEnd,
                additionalHeaders: additionalHeaders
            )
        } else {
            return try await downloadOrdinaryAsset(
                asset,
                to: destination,
                additionalHeaders: additionalHeaders,
                progressHandler: progressHandler
            )
        }
        return destination
    }

    private nonisolated func downloadOrdinaryAsset(
        _ asset: ResolvedAsset,
        to destination: URL,
        additionalHeaders: [String: String],
        progressHandler: HTTPDownloadProgressHandler? = nil
    ) async throws -> URL {
        if EHentaiResolver.isLazyImageAsset(asset) {
            return try await downloadLazyEHentaiAsset(
                asset,
                to: destination,
                additionalHeaders: additionalHeaders
            )
        }

        var candidates: [URL] = []
        var seen = Set<String>()
        for candidate in [asset.remoteURL] + asset.alternativeRemoteURLs {
            guard seen.insert(candidate.absoluteString).inserted else { continue }
            candidates.append(candidate)
        }

        for (index, candidate) in candidates.enumerated() {
            let output = Self.alternativeAssetDestination(
                originalDestination: destination,
                originalFilename: asset.filename,
                candidateURL: candidate,
                isAlternative: index > 0
            )
            do {
                try await HTTPClient.shared.download(
                    from: candidate,
                    to: output,
                    referer: asset.referer,
                    userAgent: asset.userAgent,
                    additionalHeaders: additionalHeaders,
                    progressHandler: progressHandler
                )
                return output
            } catch NativeDownloadError.httpStatus(let status, _) where
                (status == 403 || status == 410) && index + 1 < candidates.count {
                try? FileManager.default.removeItem(at: output)
                continue
            }
        }
        throw NativeDownloadError.noFiles
    }

    private nonisolated static func shouldReportNativeTransferProgress(
        asset: ResolvedAsset,
        jobMetadata: [String: String]
    ) -> Bool {
        let site = (asset.metadata["site"] ?? jobMetadata["site"] ?? "").trimmed.lowercased()
        let type = (asset.metadata["type"] ?? asset.metadata["media_type"] ?? "").trimmed.lowercased()
        return site.contains("chzzk") && !type.contains("segment") && !type.contains("hls")
    }

    private func makeNativeTransferProgressHandler(jobID: UUID) -> HTTPDownloadProgressHandler {
        { [weak self] update in
            Task<Void, Never> { @MainActor [weak self] in
                self?.applyNativeTransferProgress(update, jobID: jobID)
            }
        }
    }

    private func applyNativeTransferProgress(_ update: HTTPDownloadProgress, jobID: UUID) {
        guard let index = jobs.firstIndex(where: { $0.id == jobID }),
              jobs[index].status == .downloading else { return }

        jobs[index].metadata["transfer_active"] = "true"
        jobs[index].metadata["downloaded_bytes"] = String(update.downloadedBytes)
        jobs[index].metadata["last_transfer_at"] = ISO8601DateFormatter().string(from: Date())
        if let total = update.totalBytes, total > 0 {
            let fraction = min(1, max(0, Double(update.downloadedBytes) / Double(total)))
            jobs[index].metadata["total_bytes"] = String(total)
            jobs[index].metadata["transfer_fraction"] = String(fraction)
            jobs[index].progress = min(0.995, fraction)
        }
        if let speed = update.speedBytesPerSecond, speed > 0 {
            jobs[index].metadata["speed_bytes_per_second"] = String(speed)
        }
        let downloadedText = Self.byteCountText(update.downloadedBytes)
        jobs[index].message = AppLocalization.format(
            "Downloading Chzzk video · %@",
            language: interfaceLanguage,
            downloadedText
        )
        persistQueue()
    }

    private nonisolated func downloadLazyEHentaiAsset(
        _ asset: ResolvedAsset,
        to destination: URL,
        additionalHeaders: [String: String]
    ) async throws -> URL {
        let maximumAttempts = 24
        var lastError: Error?

        for attempt in 0..<maximumAttempts {
            try Task.checkCancellation()
            do {
                let resolved = try await EHentaiResolver.resolveLazyImageAsset(asset)
                let output = Self.lazyEHentaiDestination(
                    destination,
                    placeholderFilename: asset.filename,
                    resolvedFilename: resolved.filename
                )
                var headers = additionalHeaders
                for (name, value) in resolved.additionalHeaderFields {
                    headers[name] = value
                }
                try await HTTPClient.shared.download(
                    from: resolved.remoteURL,
                    to: output,
                    referer: resolved.referer,
                    userAgent: resolved.userAgent ?? asset.userAgent,
                    additionalHeaders: headers,
                    retryLimitOverride: 0
                )
                return output
            } catch {
                try Task.checkCancellation()
                lastError = error
                if !Self.shouldRetryLazyEHentaiAsset(error, attempt: attempt) {
                    throw error
                }
            }
        }

        throw lastError ?? NativeDownloadError.noFiles
    }

    private nonisolated static func lazyEHentaiDestination(
        _ destination: URL,
        placeholderFilename: String,
        resolvedFilename: String
    ) -> URL {
        let placeholderExtension = (placeholderFilename as NSString).pathExtension.lowercased()
        let resolvedExtension = (resolvedFilename as NSString).pathExtension.lowercased()
        guard !resolvedExtension.isEmpty,
              resolvedExtension != placeholderExtension,
              resolvedExtension.range(of: #"^[a-z0-9]{1,8}$"#, options: .regularExpression) != nil else {
            return destination
        }
        return destination.deletingPathExtension().appendingPathExtension(resolvedExtension)
    }

    private nonisolated static func shouldRetryLazyEHentaiAsset(_ error: Error, attempt: Int) -> Bool {
        guard attempt < 23 else { return false }
        if error is CancellationError { return false }
        if let urlError = error as? URLError, urlError.code == .cancelled { return false }
        if let nativeError = error as? NativeDownloadError {
            switch nativeError {
            case .cancelled:
                return false
            case .httpStatus(let status, _):
                if status == 401 { return false }
                if status == 404 { return attempt < 3 }
                if status == 403 { return attempt < 7 }
                return status == 408 || status == 429 || status >= 500
            default:
                return true
            }
        }
        return true
    }

    private nonisolated static func alternativeAssetDestination(
        originalDestination: URL,
        originalFilename: String,
        candidateURL: URL,
        isAlternative: Bool
    ) -> URL {
        guard isAlternative else { return originalDestination }
        let originalExtension = (originalFilename as NSString).pathExtension.lowercased()
        let destinationExtension = originalDestination.pathExtension.lowercased()
        let candidateExtension = candidateURL.pathExtension.lowercased()
        guard !candidateExtension.isEmpty,
              candidateExtension.range(of: #"^[a-z0-9]{1,8}$"#, options: .regularExpression) != nil,
              destinationExtension == originalExtension,
              candidateExtension != destinationExtension else {
            return originalDestination
        }
        let candidate = originalDestination
            .deletingPathExtension()
            .appendingPathExtension(candidateExtension)
        if FileManager.default.fileExists(atPath: candidate.path) {
            return AppPaths.uniqueFileURL(
                in: candidate.deletingLastPathComponent(),
                filename: candidate.lastPathComponent
            )
        }
        return candidate
    }

    private nonisolated func downloadRemoteSegmentedAsset(
        _ asset: ResolvedAsset,
        to destination: URL,
        segmentSize: Int64,
        maxConcurrency: Int,
        additionalHeaders: [String: String]
    ) async throws {
        try Task.checkCancellation()
        guard let totalLength = try await remoteSegmentedContentLength(
            for: asset,
            additionalHeaders: additionalHeaders
        ) else {
            try await HTTPClient.shared.download(
                from: asset.remoteURL,
                to: destination,
                referer: asset.referer,
                userAgent: asset.userAgent,
                additionalHeaders: additionalHeaders
            )
            return
        }

        let ranges = Self.remoteSegmentRanges(totalLength: totalLength, segmentSize: segmentSize)
        guard ranges.count > 1 else {
            try await HTTPClient.shared.download(
                from: asset.remoteURL,
                to: destination,
                referer: asset.referer,
                userAgent: asset.userAgent,
                additionalHeaders: additionalHeaders
            )
            return
        }

        let partFolder = destination.deletingLastPathComponent().appendingPathComponent(
            ".\(destination.lastPathComponent)-segments-\(UUID().uuidString)",
            isDirectory: true
        )
        try FileManager.default.createDirectory(at: partFolder, withIntermediateDirectories: true)
        defer { try? FileManager.default.removeItem(at: partFolder) }

        let workerCount = min(max(1, maxConcurrency), ranges.count)
        try await withThrowingTaskGroup(of: Void.self) { group in
            for workerIndex in 0..<workerCount {
                group.addTask {
                    for partIndex in stride(from: workerIndex, to: ranges.count, by: workerCount) {
                        try Task.checkCancellation()
                        let range = ranges[partIndex]
                        var headers = additionalHeaders
                        headers["Range"] = "bytes=\(range.start)-\(range.end)"
                        let partURL = partFolder.appendingPathComponent(
                            String(format: "%08d.part", partIndex)
                        )
                        try await self.downloadByteRangeAsset(
                            asset,
                            to: partURL,
                            start: range.start,
                            end: range.end,
                            additionalHeaders: headers
                        )
                    }
                }
            }
            try await group.waitForAll()
        }

        let assembled = partFolder.appendingPathComponent("assembled.tmp")
        FileManager.default.createFile(atPath: assembled.path, contents: nil)
        let writer = try FileHandle(forWritingTo: assembled)
        do {
            defer { try? writer.close() }
            for partIndex in ranges.indices {
                try Task.checkCancellation()
                let partURL = partFolder.appendingPathComponent(String(format: "%08d.part", partIndex))
                let reader = try FileHandle(forReadingFrom: partURL)
                do {
                    defer { try? reader.close() }
                    while let chunk = try reader.read(upToCount: 1_048_576), !chunk.isEmpty {
                        try writer.write(contentsOf: chunk)
                    }
                }
            }
        }

        if FileManager.default.fileExists(atPath: destination.path) {
            try FileManager.default.removeItem(at: destination)
        }
        try FileManager.default.moveItem(at: assembled, to: destination)
    }

    private nonisolated func remoteSegmentedContentLength(
        for asset: ResolvedAsset,
        additionalHeaders: [String: String]
    ) async throws -> Int64? {
        var probeHeaders = additionalHeaders
        probeHeaders["Range"] = "bytes=0-0"
        let response: HTTPURLResponse
        do {
            guard let value = try await HTTPClient.shared.head(
                from: asset.remoteURL,
                referer: asset.referer,
                userAgent: asset.userAgent,
                additionalHeaders: probeHeaders
            ) else {
                return nil
            }
            response = value
        } catch {
            try Task.checkCancellation()
            return nil
        }

        if response.statusCode == 206,
           let contentRange = response.value(forHTTPHeaderField: "Content-Range"),
           let total = Self.contentRangeTotalLength(contentRange) {
            return total
        }
        guard response.value(forHTTPHeaderField: "Accept-Ranges")?.lowercased().contains("bytes") == true else {
            return nil
        }
        if let rawLength = response.value(forHTTPHeaderField: "Content-Length"),
           let total = Int64(rawLength), total > 0 {
            return total
        }
        return response.expectedContentLength > 0 ? response.expectedContentLength : nil
    }

    nonisolated static func remoteSegmentRanges(
        totalLength: Int64,
        segmentSize: Int64
    ) -> [(start: Int64, end: Int64)] {
        guard totalLength > 0, segmentSize > 0 else { return [] }
        var ranges: [(start: Int64, end: Int64)] = []
        var start: Int64 = 0
        while start < totalLength {
            let remaining = totalLength - start
            let length = min(segmentSize, remaining)
            ranges.append((start, start + length - 1))
            start += length
        }
        return ranges
    }

    private nonisolated static func contentRangeTotalLength(_ raw: String) -> Int64? {
        guard let slash = raw.lastIndex(of: "/") else { return nil }
        let value = raw[raw.index(after: slash)...].trimmingCharacters(in: .whitespacesAndNewlines)
        guard value != "*", let total = Int64(value), total > 0 else { return nil }
        return total
    }

    private nonisolated func downloadByteRangeAsset(
        _ asset: ResolvedAsset,
        to destination: URL,
        start: Int64,
        end: Int64,
        additionalHeaders: [String: String]
    ) async throws {
        let (distance, distanceOverflowed) = end.subtractingReportingOverflow(start)
        let (expectedLength, lengthOverflowed) = distance.addingReportingOverflow(1)
        guard !distanceOverflowed, !lengthOverflowed, expectedLength > 0 else {
            throw NativeDownloadError.unsupported("Byte-range length overflowed.")
        }
        let download = try await HTTPClient.shared.downloadTemporary(
            from: asset.remoteURL,
            referer: asset.referer,
            userAgent: asset.userAgent,
            additionalHeaders: additionalHeaders
        )
        var movedTemporary = false
        defer {
            if !movedTemporary {
                try? FileManager.default.removeItem(at: download.fileURL)
            }
        }

        guard let response = download.response else {
            throw NativeDownloadError.unsupported("Byte-range download returned no HTTP response.")
        }
        let downloadedSize = Int64(
            (try download.fileURL.resourceValues(forKeys: [.fileSizeKey]).fileSize) ?? 0
        )

        if response.statusCode == 206 {
            guard downloadedSize == expectedLength else {
                throw NativeDownloadError.unsupported(
                    "Byte-range response length was \(downloadedSize), expected \(expectedLength)."
                )
            }
            if let contentRange = response.value(forHTTPHeaderField: "Content-Range")?.lowercased(),
               !contentRange.hasPrefix("bytes \(start)-\(end)/") {
                throw NativeDownloadError.unsupported("Byte-range response did not match the requested offsets.")
            }
            if FileManager.default.fileExists(atPath: destination.path) {
                try FileManager.default.removeItem(at: destination)
            }
            try FileManager.default.moveItem(at: download.fileURL, to: destination)
            movedTemporary = true
            return
        }

        guard response.statusCode == 200,
              downloadedSize > end else {
            throw NativeDownloadError.unsupported(
                "Server ignored the byte range without returning enough source data."
            )
        }

        if FileManager.default.fileExists(atPath: destination.path) {
            try FileManager.default.removeItem(at: destination)
        }
        FileManager.default.createFile(atPath: destination.path, contents: nil)
        do {
            let reader = try FileHandle(forReadingFrom: download.fileURL)
            let writer = try FileHandle(forWritingTo: destination)
            defer {
                try? reader.close()
                try? writer.close()
            }
            try reader.seek(toOffset: UInt64(start))
            var remaining = expectedLength
            while remaining > 0 {
                let requestCount = Int(min(remaining, 1_048_576))
                guard let chunk = try reader.read(upToCount: requestCount),
                      !chunk.isEmpty else {
                    throw NativeDownloadError.unsupported("Byte-range source ended before the requested offset range.")
                }
                try writer.write(contentsOf: chunk)
                remaining -= Int64(chunk.count)
            }
        } catch {
            try? FileManager.default.removeItem(at: destination)
            throw error
        }
    }

    private func downloadAndConcatenate(_ assets: [ResolvedAsset], tempFolder: URL, output: URL, jobIndex: Int) async throws {
        try await downloadAssets(assets, to: tempFolder, jobIndex: jobIndex)

        if jobs.indices.contains(jobIndex) {
            jobs[jobIndex].message = "Joining segments"
            persistQueue()
        }

        if FileManager.default.fileExists(atPath: output.path) {
            try FileManager.default.removeItem(at: output)
        }

        FileManager.default.createFile(atPath: output.path, contents: nil)
        let writer = try FileHandle(forWritingTo: output)
        defer {
            try? writer.close()
        }

        let files = try FileManager.default.contentsOfDirectory(at: tempFolder, includingPropertiesForKeys: nil)
            .sorted { $0.lastPathComponent < $1.lastPathComponent }

        for file in files {
            try Task.checkCancellation()
            let reader = try FileHandle(forReadingFrom: file)
            defer {
                try? reader.close()
            }
            while true {
                let chunk = try reader.read(upToCount: 1_048_576) ?? Data()
                if chunk.isEmpty { break }
                try writer.write(contentsOf: chunk)
            }
        }

        try? FileManager.default.removeItem(at: tempFolder)
    }

    private func downloadLiveHLSAndConcatenate(
        _ initialResolved: ResolvedDownload,
        tempFolder: URL,
        output: URL,
        jobIndex: Int
    ) async throws {
        guard let refreshContext = Self.liveHLSRefreshContext(for: initialResolved) else {
            try await downloadAndConcatenate(
                initialResolved.assets,
                tempFolder: tempFolder,
                output: output,
                jobIndex: jobIndex
            )
            return
        }

        if FileManager.default.fileExists(atPath: output.path) {
            try FileManager.default.removeItem(at: output)
        }
        FileManager.default.createFile(atPath: output.path, contents: nil)
        let writer = try FileHandle(forWritingTo: output)
        defer {
            try? writer.close()
            try? FileManager.default.removeItem(at: tempFolder)
        }

        var snapshot = initialResolved
        var isInitialSnapshot = true
        var visited = Set<String>()
        var outputOrdinal = 0
        var pollCount = 0
        var recordedSegmentCount = 0
        var recordedDuration: Double = 0
        var lastNewSegmentAt = Date()
        var lastTransferSampleAt = Date()
        var lastTransferBytes: Int64 = 0
        var pollInterval = Self.liveHLSPollInterval(from: snapshot.metadata)
        let timeout = Self.liveHLSTimeout(from: initialResolved.metadata)

        if jobs.indices.contains(jobIndex) {
            jobs[jobIndex].metadata["was_live"] = "true"
            jobs[jobIndex].metadata["live_active"] = "true"
            jobs[jobIndex].metadata["live_polling"] = "true"
            jobs[jobIndex].metadata.removeValue(forKey: Self.liveStopRequestedMetadataKey)
            jobs[jobIndex].metadata["live_playlist_url"] = refreshContext.playlistURL.absoluteString
            jobs[jobIndex].metadata["live_poll_interval"] = Self.liveHLSNumber(pollInterval)
            jobs[jobIndex].metadata["live_timeout"] = Self.liveHLSNumber(timeout)
            jobs[jobIndex].metadata["live_recorded_duration"] = "0"
            jobs[jobIndex].metadata["downloaded_bytes"] = "0"
            jobs[jobIndex].metadata["transfer_active"] = "true"
            jobs[jobIndex].metadata.removeValue(forKey: "total_bytes")
            jobs[jobIndex].metadata.removeValue(forKey: "transfer_fraction")
            jobs[jobIndex].metadata.removeValue(forKey: "duration")
            jobs[jobIndex].metadata.removeValue(forKey: "duration_seconds")
            jobs[jobIndex].progress = 0
            persistQueue()
        }

        do {
            while true {
                try Task.checkCancellation()
                if liveRecordingStopRequested(at: jobIndex) {
                    finishLiveHLSRecording(jobIndex: jobIndex, reason: "stopped", pollCount: pollCount, output: output)
                    break
                }

                let refreshedAssets = Self.preparedLiveHLSAssets(
                    snapshot.assets,
                    initialResolved: initialResolved,
                    applySiteAdjustments: !isInitialSnapshot
                )
                var batch: [ResolvedAsset] = []
                var batchIdentities: [String] = []
                for asset in refreshedAssets {
                    let identity = Self.liveHLSAssetIdentity(asset)
                    guard !visited.contains(identity), !batchIdentities.contains(identity) else { continue }
                    var numbered = asset
                    numbered.filename = Self.liveHLSFilename(for: asset, ordinal: outputOrdinal + batch.count)
                    batch.append(numbered)
                    batchIdentities.append(identity)
                }

                if !batch.isEmpty {
                    if jobs.indices.contains(jobIndex) {
                        if isInitialSnapshot {
                            jobs[jobIndex].total = batch.count
                        } else {
                            jobs[jobIndex].total += batch.count
                        }
                        jobs[jobIndex].message = "Recording live segments"
                        persistQueue()
                    }

                    let batchFolder = tempFolder.appendingPathComponent(
                        String(format: "batch-%06d", pollCount),
                        isDirectory: true
                    )
                    try AppPaths.ensureDirectory(batchFolder)
                    let downloaded: [URL]
                    do {
                        downloaded = try await downloadAssets(batch, to: batchFolder, jobIndex: jobIndex)
                        if jobs.indices.contains(jobIndex) {
                            jobs[jobIndex].message = "Appending live segments"
                            persistQueue()
                        }
                        try Self.appendFiles(downloaded, to: writer)
                        try writer.synchronize()
                    } catch {
                        try? FileManager.default.removeItem(at: batchFolder)
                        throw error
                    }
                    try? FileManager.default.removeItem(at: batchFolder)

                    visited.formUnion(batchIdentities)
                    outputOrdinal += batch.count
                    recordedSegmentCount += batch.filter { $0.metadata["type"] == "hls_segment" }.count
                    recordedDuration += batch.reduce(0) {
                        $0 + (Double($1.metadata["duration_seconds"] ?? $1.metadata["duration"] ?? "") ?? 0)
                    }
                    let now = Date()
                    let outputBytes = Self.fileByteCount(output)
                    let elapsed = max(0.001, now.timeIntervalSince(lastTransferSampleAt))
                    let speed = Int64(Double(max(0, outputBytes - lastTransferBytes)) / elapsed)
                    lastTransferSampleAt = now
                    lastTransferBytes = outputBytes
                    lastNewSegmentAt = now
                    if jobs.indices.contains(jobIndex) {
                        jobs[jobIndex].metadata["live_segment_count"] = String(recordedSegmentCount)
                        jobs[jobIndex].metadata["live_media_count"] = String(visited.count)
                        jobs[jobIndex].metadata["live_recorded_duration"] = Self.liveHLSNumber(recordedDuration)
                        jobs[jobIndex].metadata["duration_seconds"] = Self.liveHLSNumber(recordedDuration)
                        jobs[jobIndex].metadata["downloaded_bytes"] = String(outputBytes)
                        jobs[jobIndex].metadata["transfer_active"] = "true"
                        if speed > 0 {
                            jobs[jobIndex].metadata["speed_bytes_per_second"] = String(speed)
                        }
                        jobs[jobIndex].metadata["last_transfer_at"] = ISO8601DateFormatter().string(from: now)
                        jobs[jobIndex].metadata["live_snapshot_count"] = String(pollCount + 1)
                        jobs[jobIndex].metadata.removeValue(forKey: "live_last_refresh_error")
                        jobs[jobIndex].progress = 0
                        persistQueue()
                    }
                }

                if liveRecordingStopRequested(at: jobIndex) {
                    finishLiveHLSRecording(jobIndex: jobIndex, reason: "stopped", pollCount: pollCount, output: output)
                    break
                }

                if !Self.liveHLSMetadataIsTrue(snapshot.metadata["live"] ?? snapshot.metadata["is_live"]) {
                    finishLiveHLSRecording(jobIndex: jobIndex, reason: "endlist", pollCount: pollCount, output: output)
                    break
                }

                if Date().timeIntervalSince(lastNewSegmentAt) >= timeout {
                    finishLiveHLSRecording(jobIndex: jobIndex, reason: "timeout", pollCount: pollCount, output: output)
                    break
                }

                if jobs.indices.contains(jobIndex) {
                    jobs[jobIndex].message = "Waiting for live segments"
                    jobs[jobIndex].metadata.removeValue(forKey: "speed_bytes_per_second")
                    persistQueue()
                }
                guard try await waitForLiveHLSPollInterval(pollInterval, jobIndex: jobIndex) else {
                    finishLiveHLSRecording(jobIndex: jobIndex, reason: "stopped", pollCount: pollCount, output: output)
                    break
                }

                pollCount += 1
                do {
                    snapshot = try await m3u8Resolver.resolve(
                        refreshContext.playlistURL,
                        headers: refreshContext.headers,
                        additionalHeaders: refreshContext.additionalHeaders,
                        segmentReferer: refreshContext.segmentReferer
                    )
                    isInitialSnapshot = false
                    pollInterval = Self.liveHLSPollInterval(from: snapshot.metadata)
                    if jobs.indices.contains(jobIndex) {
                        jobs[jobIndex].metadata["live_poll_count"] = String(pollCount)
                        jobs[jobIndex].metadata["live_poll_interval"] = Self.liveHLSNumber(pollInterval)
                        jobs[jobIndex].metadata.removeValue(forKey: "live_last_refresh_error")
                        persistQueue()
                    }
                } catch is CancellationError {
                    throw CancellationError()
                } catch {
                    if jobs.indices.contains(jobIndex) {
                        jobs[jobIndex].metadata["live_poll_count"] = String(pollCount)
                        jobs[jobIndex].metadata["live_last_refresh_error"] = error.localizedDescription
                        jobs[jobIndex].message = "Live playlist refresh failed; retrying"
                        persistQueue()
                    }
                    if Date().timeIntervalSince(lastNewSegmentAt) >= timeout {
                        finishLiveHLSRecording(jobIndex: jobIndex, reason: "timeout", pollCount: pollCount, output: output)
                        break
                    }
                }
            }
        } catch is CancellationError {
            if jobs.indices.contains(jobIndex) {
                jobs[jobIndex].metadata["live_polling"] = "false"
                jobs[jobIndex].metadata["live_active"] = "false"
                jobs[jobIndex].metadata["live_done"] = "true"
                jobs[jobIndex].metadata["live_end_reason"] = "cancelled"
                finalizeLiveTransferMetadata(jobIndex: jobIndex, output: output)
                jobs[jobIndex].metadata.removeValue(forKey: Self.liveStopRequestedMetadataKey)
                jobs[jobIndex].metadata["live_poll_count"] = String(pollCount)
                jobs[jobIndex].metadata["live_partial_output"] = Self.fileHasContent(output) ? "true" : "false"
                persistQueue()
            }
            if !Self.fileHasContent(output) {
                try? FileManager.default.removeItem(at: output)
            }
            throw CancellationError()
        } catch {
            if jobs.indices.contains(jobIndex) {
                jobs[jobIndex].metadata["live_polling"] = "false"
                jobs[jobIndex].metadata["live_active"] = "false"
                jobs[jobIndex].metadata["live_done"] = "true"
                jobs[jobIndex].metadata["live_end_reason"] = "error"
                finalizeLiveTransferMetadata(jobIndex: jobIndex, output: output)
                jobs[jobIndex].metadata.removeValue(forKey: Self.liveStopRequestedMetadataKey)
                jobs[jobIndex].metadata["live_poll_count"] = String(pollCount)
                jobs[jobIndex].metadata["live_partial_output"] = Self.fileHasContent(output) ? "true" : "false"
                persistQueue()
            }
            if !Self.fileHasContent(output) {
                try? FileManager.default.removeItem(at: output)
            }
            throw error
        }
    }

    private func liveRecordingStopRequested(at jobIndex: Int) -> Bool {
        jobs.indices.contains(jobIndex) &&
            Self.liveHLSMetadataIsTrue(jobs[jobIndex].metadata[Self.liveStopRequestedMetadataKey])
    }

    private func waitForLiveHLSPollInterval(_ interval: TimeInterval, jobIndex: Int) async throws -> Bool {
        let deadline = Date().addingTimeInterval(max(0, interval))
        while Date() < deadline {
            try Task.checkCancellation()
            if liveRecordingStopRequested(at: jobIndex) {
                return false
            }
            let remaining = deadline.timeIntervalSinceNow
            let slice = min(0.25, max(0.01, remaining))
            try await Task.sleep(nanoseconds: UInt64(slice * 1_000_000_000))
        }
        try Task.checkCancellation()
        return !liveRecordingStopRequested(at: jobIndex)
    }

    private func finishLiveHLSRecording(jobIndex: Int, reason: String, pollCount: Int, output: URL) {
        guard jobs.indices.contains(jobIndex) else { return }
        jobs[jobIndex].metadata["live_active"] = "false"
        jobs[jobIndex].metadata["live_polling"] = "false"
        jobs[jobIndex].metadata["live_done"] = "true"
        jobs[jobIndex].metadata["live_end_reason"] = reason
        finalizeLiveTransferMetadata(jobIndex: jobIndex, output: output)
        jobs[jobIndex].metadata.removeValue(forKey: Self.liveStopRequestedMetadataKey)
        jobs[jobIndex].metadata["live_poll_count"] = String(pollCount)
        if reason == "stopped" {
            jobs[jobIndex].metadata["live_partial_output"] = Self.fileHasContent(output) ? "true" : "false"
            jobs[jobIndex].message = "Finalizing recording"
        }
        persistQueue()
    }

    private func finalizeLiveTransferMetadata(jobIndex: Int, output: URL) {
        guard jobs.indices.contains(jobIndex) else { return }
        let outputBytes = Self.fileByteCount(output)
        jobs[jobIndex].metadata["transfer_active"] = "false"
        jobs[jobIndex].metadata["downloaded_bytes"] = String(outputBytes)
        if outputBytes > 0 {
            jobs[jobIndex].metadata["byte_count"] = String(outputBytes)
        }
        jobs[jobIndex].metadata.removeValue(forKey: "speed_bytes_per_second")
        if let recorded = jobs[jobIndex].metadata["live_recorded_duration"]?.trimmed,
           !recorded.isEmpty {
            jobs[jobIndex].metadata["duration_seconds"] = recorded
            jobs[jobIndex].metadata["duration"] = recorded
        }
    }

    private nonisolated static func shouldPollLiveHLS(_ resolved: ResolvedDownload) -> Bool {
        guard (resolved.metadata["type"] == "hls" || resolved.metadata["format"] == "m3u8"),
              liveHLSMetadataIsTrue(resolved.metadata["live"] ?? resolved.metadata["is_live"]),
              !liveHLSMetadataIsTrue(resolved.metadata["vod"]),
              resolved.metadata["playlist_type"]?.trimmed.uppercased() != "VOD",
              !liveHLSMetadataIsTrue(resolved.metadata["custom_segment_urls"]),
              let rawURL = resolved.metadata["playlist_url"]?.trimmed,
              let url = URL(string: rawURL),
              let scheme = url.scheme?.lowercased(),
              scheme == "http" || scheme == "https" else {
            return false
        }
        return true
    }

    private nonisolated static func liveHLSRefreshContext(for resolved: ResolvedDownload) -> LiveHLSRefreshContext? {
        guard shouldPollLiveHLS(resolved),
              let rawURL = resolved.metadata["playlist_url"]?.trimmed,
              let playlistURL = URL(string: rawURL),
              let prototype = resolved.assets.first(where: { $0.metadata["type"] == "hls_segment" }) ?? resolved.assets.first else {
            return nil
        }
        return LiveHLSRefreshContext(
            playlistURL: playlistURL,
            headers: HTTPRequestOptions(referer: prototype.referer, userAgent: prototype.userAgent),
            additionalHeaders: prototype.additionalHeaderFields,
            segmentReferer: prototype.referer
        )
    }

    private nonisolated static func preparedLiveHLSAssets(
        _ assets: [ResolvedAsset],
        initialResolved: ResolvedDownload,
        applySiteAdjustments: Bool
    ) -> [ResolvedAsset] {
        var prepared = assets
        if applySiteAdjustments,
           initialResolved.metadata["site"]?.trimmed.lowercased() == "twitch" {
            prepared = TwitchVODResolver.adjustedLiveHLSAssetsForRefresh(prepared)
        }

        let prototypes = Dictionary(grouping: initialResolved.assets) { $0.metadata["type"] ?? "" }
        return prepared.map { asset in
            var copy = asset
            let prototype = prototypes[asset.metadata["type"] ?? ""]?.first ?? initialResolved.assets.first
            if copy.referer?.trimmed.isEmpty != false {
                copy.referer = prototype?.referer
            }
            if copy.userAgent?.trimmed.isEmpty != false {
                copy.userAgent = prototype?.userAgent
            }
            if copy.additionalHeaders.isEmpty {
                copy.additionalHeaders = prototype?.additionalHeaders ?? []
            }
            copy.pythonSegmentDecorator = prototype?.pythonSegmentDecorator
            for (key, value) in initialResolved.metadata where copy.metadata[key] == nil {
                copy.metadata[key] = value
            }
            if let prototype {
                for (key, value) in prototype.metadata where copy.metadata[key] == nil {
                    copy.metadata[key] = value
                }
            }
            return copy
        }
    }

    nonisolated static func liveHLSAssetIdentity(_ asset: ResolvedAsset) -> String {
        let type = asset.metadata["type"] ?? "hls_segment"
        let sequence = asset.metadata["media_sequence"]?.trimmed ?? ""
        let byteRange = asset.metadata["byte_range"]?.trimmed ?? ""
        var components = [type, sequence, canonicalLiveHLSURL(asset.remoteURL), byteRange]
        if type == "hls_map" {
            components.append(asset.decryption.map { canonicalLiveHLSURL($0.keyURL) } ?? "")
            components.append(asset.decryption?.iv.base64EncodedString() ?? "")
        }
        return components.joined(separator: "|")
    }

    private nonisolated static func canonicalLiveHLSURL(_ url: URL) -> String {
        guard var components = URLComponents(url: url, resolvingAgainstBaseURL: false) else {
            return url.absoluteString
        }
        components.query = nil
        components.fragment = nil
        components.user = nil
        components.password = nil
        return components.string ?? url.absoluteString
    }

    private nonisolated static func liveHLSFilename(for asset: ResolvedAsset, ordinal: Int) -> String {
        let filenameExtension = (asset.filename as NSString).pathExtension.trimmed
        let remoteExtension = asset.remoteURL.pathExtension.trimmed
        let ext = (filenameExtension.isEmpty ? (remoteExtension.isEmpty ? "ts" : remoteExtension) : filenameExtension).lowercased()
        let suffix = asset.metadata["type"] == "hls_map" ? "-map" : ""
        return String(format: "%012d%@.%@", ordinal, suffix, ext).sanitizedFilename()
    }

    private nonisolated static func liveHLSPollInterval(from metadata: [String: String]) -> TimeInterval {
        let target = Double(metadata["target_duration"]?.trimmed ?? "") ?? 10
        return min(10, max(0.1, target))
    }

    private nonisolated static func liveHLSTimeout(from metadata: [String: String]) -> TimeInterval {
        let timeout = Double(metadata["live_timeout"]?.trimmed ?? "") ?? 180
        return min(86_400, max(1, timeout))
    }

    private nonisolated static func liveHLSMetadataIsTrue(_ value: String?) -> Bool {
        guard let value = value?.trimmed.lowercased(), !value.isEmpty else { return false }
        return ["1", "true", "yes", "on"].contains(value)
    }

    private nonisolated static func liveHLSNumber(_ value: Double) -> String {
        var text = String(format: "%.3f", value)
        while text.contains(".") && text.last == "0" { text.removeLast() }
        if text.last == "." { text.removeLast() }
        return text
    }

    private nonisolated static func appendFiles(_ files: [URL], to writer: FileHandle) throws {
        for file in files.sorted(by: { $0.lastPathComponent < $1.lastPathComponent }) {
            try Task.checkCancellation()
            let reader = try FileHandle(forReadingFrom: file)
            defer { try? reader.close() }
            while true {
                let chunk = try reader.read(upToCount: 1_048_576) ?? Data()
                if chunk.isEmpty { break }
                try writer.write(contentsOf: chunk)
            }
        }
    }

    private nonisolated static func fileHasContent(_ url: URL) -> Bool {
        fileByteCount(url) > 0
    }

    private nonisolated static func fileByteCount(_ url: URL) -> Int64 {
        Int64((try? url.resourceValues(forKeys: [.fileSizeKey]).fileSize) ?? 0)
    }

    nonisolated static func youtubeCollectionVideoID(fromFilename filename: String) -> String? {
        let basename = (filename as NSString).lastPathComponent
        for pattern in [
            #"\(([0-9A-Za-z_-]{10,})\)\."#,
            #"\(([0-9A-Za-z_-]{10,})\)"#
        ] {
            guard let regex = try? NSRegularExpression(pattern: pattern),
                  let match = regex.firstMatch(
                    in: basename,
                    range: NSRange(basename.startIndex..<basename.endIndex, in: basename)
                  ),
                  match.numberOfRanges > 1,
                  let range = Range(match.range(at: 1), in: basename) else {
                continue
            }
            return String(basename[range])
        }
        return nil
    }

    private nonisolated static func youtubeCollectionExistingOutputs(
        in directory: URL,
        candidateIDs: Set<String>,
        fileManager: FileManager = .default
    ) -> [String: URL] {
        guard !candidateIDs.isEmpty,
              let contents = try? fileManager.contentsOfDirectory(
                at: directory,
                includingPropertiesForKeys: [.isDirectoryKey],
                options: [.skipsHiddenFiles]
              ) else {
            return [:]
        }

        var outputs: [String: URL] = [:]
        for url in contents.sorted(by: { $0.lastPathComponent < $1.lastPathComponent }) {
            guard (try? url.resourceValues(forKeys: [.isDirectoryKey]).isDirectory) != true else {
                continue
            }
            let filename = url.lastPathComponent
            if let id = youtubeCollectionVideoID(fromFilename: filename),
               candidateIDs.contains(id) {
                outputs[id] = url
                continue
            }
            let stem = (filename as NSString).deletingPathExtension
            if let id = candidateIDs.first(where: { candidate in
                stem == candidate ||
                    stem.hasSuffix("-\(candidate)") ||
                    stem.hasSuffix(" \(candidate)") ||
                    stem.hasSuffix("_\(candidate)")
            }) {
                outputs[id] = url
            }
        }
        return outputs
    }

    private func recordReusedYouTubeCollectionOutput(
        id: String,
        output: URL,
        assetCount: Int,
        jobIndex: Int
    ) {
        guard jobs.indices.contains(jobIndex) else { return }
        let reusedCount = (Int(jobs[jobIndex].metadata["youtube_reused_existing_outputs"] ?? "") ?? 0) + 1
        var reusedIDs = Set(
            jobs[jobIndex].metadata["youtube_reused_video_ids", default: ""]
                .split(separator: ",")
                .map(String.init)
        )
        reusedIDs.insert(id)
        jobs[jobIndex].completed = min(
            jobs[jobIndex].total,
            jobs[jobIndex].completed + max(1, assetCount)
        )
        jobs[jobIndex].progress = Double(jobs[jobIndex].completed) / Double(max(1, jobs[jobIndex].total))
        jobs[jobIndex].metadata["youtube_reused_existing_outputs"] = String(reusedCount)
        jobs[jobIndex].metadata["youtube_reused_video_ids"] = reusedIDs.sorted().joined(separator: ",")
        jobs[jobIndex].metadata["skipped_existing_files"] = String(reusedCount)
        jobs[jobIndex].metadata["skip_reason"] = "youtube_collection_video_id"
        jobs[jobIndex].metadata["last_reused_existing_output"] = output.path
        jobs[jobIndex].message = "Reused \(reusedCount) existing YouTube file\(reusedCount == 1 ? "" : "s")"
        persistQueue()
    }

    private func downloadGroupedPackage(
        _ resolved: ResolvedDownload,
        fileAssetIndexes: [Int],
        concatenations: [ResolvedConcatenationGroup],
        muxes: [ResolvedMuxGroup],
        root: URL,
        folderName: String,
        sourceURL: URL,
        jobIndex: Int
    ) async throws {
        guard jobs.indices.contains(jobIndex) else { return }
        let groupedIndexes = concatenations.flatMap(\.assetIndexes)
        let muxedIndexes = muxes.flatMap { $0.videoAssetIndexes + $0.audioAssetIndexes }
        let claimedIndexes = fileAssetIndexes + groupedIndexes + muxedIndexes
        guard !concatenations.isEmpty || !muxes.isEmpty,
              concatenations.allSatisfy({ !$0.assetIndexes.isEmpty }),
              muxes.allSatisfy({ !$0.videoAssetIndexes.isEmpty && !$0.audioAssetIndexes.isEmpty }),
              claimedIndexes.count == resolved.assets.count,
              Set(claimedIndexes).count == resolved.assets.count,
              claimedIndexes.allSatisfy({ resolved.assets.indices.contains($0) }) else {
            throw NativeDownloadError.unsupported("Invalid grouped stream download plan.")
        }

        let folder = AppPaths.directoryURL(in: root, name: folderName)
        try AppPaths.ensureDirectory(folder)
        jobs[jobIndex].outputPath = folder.path
        persistQueue()
        let youtubeCollectionIDs: Set<String>
        if resolved.metadata["extractor"] == "youtube_collection_native" {
            youtubeCollectionIDs = Set(
                resolved.assets.compactMap { asset in
                    let id = asset.metadata["collection_item_id"]?.trimmed ?? ""
                    return id.isEmpty ? nil : id
                }
            )
        } else {
            youtubeCollectionIDs = []
        }
        let existingYouTubeOutputs = Self.youtubeCollectionExistingOutputs(
            in: folder,
            candidateIDs: youtubeCollectionIDs
        )

        var orderedOutputs: [(firstAssetIndex: Int, fileAssetIndex: Int?, groupIndex: Int?, muxIndex: Int?)] =
            fileAssetIndexes.map { ($0, $0, nil, nil) }
        orderedOutputs.append(contentsOf: concatenations.enumerated().compactMap { index, group in
            guard let first = group.assetIndexes.first else { return nil }
            return (first, nil, index, nil)
        })
        orderedOutputs.append(contentsOf: muxes.enumerated().compactMap { index, group in
            guard let first = (group.videoAssetIndexes + group.audioAssetIndexes).min() else { return nil }
            return (first, nil, nil, index)
        })
        orderedOutputs.sort { $0.firstAssetIndex < $1.firstAssetIndex }

        var fileOrdinals: [Int: Int] = [:]
        var groupOrdinals: [Int: Int] = [:]
        var muxOrdinals: [Int: Int] = [:]
        for (offset, output) in orderedOutputs.enumerated() {
            if let fileAssetIndex = output.fileAssetIndex {
                fileOrdinals[fileAssetIndex] = offset + 1
            } else if let groupIndex = output.groupIndex {
                groupOrdinals[groupIndex] = offset + 1
            } else if let muxIndex = output.muxIndex {
                muxOrdinals[muxIndex] = offset + 1
            }
        }
        let outputCount = orderedOutputs.count

        if !fileAssetIndexes.isEmpty {
            let directAssets = fileAssetIndexes.map { assetIndex -> ResolvedAsset in
                var asset = resolved.assets[assetIndex]
                let metadata = Self.mergedNameTemplateMetadata(resolved.metadata, assetMetadata: asset.metadata)
                asset.filename = templatedFileName(
                    original: asset.filename,
                    title: resolved.title,
                    sourceURL: sourceURL,
                    index: fileOrdinals[assetIndex],
                    total: outputCount,
                    metadata: metadata
                )
                return asset
            }
            var pendingDirectAssets: [ResolvedAsset] = []
            for asset in directAssets {
                let id = asset.metadata["collection_item_id"]?.trimmed ?? ""
                if let existing = existingYouTubeOutputs[id], !id.isEmpty {
                    applyYouTubeUploadModificationDateIfNeeded(
                        to: existing,
                        sourceURL: sourceURL,
                        metadata: resolved.metadata.merging(asset.metadata) { _, assetValue in assetValue }
                    )
                    recordReusedYouTubeCollectionOutput(
                        id: id,
                        output: existing,
                        assetCount: 1,
                        jobIndex: jobIndex
                    )
                } else {
                    pendingDirectAssets.append(asset)
                }
            }
            if !pendingDirectAssets.isEmpty {
                jobs[jobIndex].message = "Downloading \(pendingDirectAssets.count) file\(pendingDirectAssets.count == 1 ? "" : "s")"
                persistQueue()
                _ = try await downloadAssets(pendingDirectAssets, to: folder, jobIndex: jobIndex)
            }
        }

        for (groupIndex, group) in concatenations.enumerated() {
            try Task.checkCancellation()
            guard jobs.indices.contains(jobIndex) else { return }
            let streamAssets = group.assetIndexes.map { resolved.assets[$0] }
            let groupMetadata = DownloadMetadata.clean(
                resolved.metadata.merging(group.metadata) { _, groupValue in groupValue }
            )
            let collectionItemID = groupMetadata["collection_item_id"]?.trimmed ?? ""
            if let existing = existingYouTubeOutputs[collectionItemID], !collectionItemID.isEmpty {
                applyYouTubeUploadModificationDateIfNeeded(
                    to: existing,
                    sourceURL: sourceURL,
                    metadata: groupMetadata
                )
                recordReusedYouTubeCollectionOutput(
                    id: collectionItemID,
                    output: existing,
                    assetCount: group.assetIndexes.count,
                    jobIndex: jobIndex
                )
                continue
            }
            let outputMetadata = Self.mergedNameTemplateMetadata(
                groupMetadata,
                assetMetadata: streamAssets.first?.metadata ?? [:]
            )
            let recordingTemplate = recordingFileNameTemplate.trimmed
            let templateOverride = Self.shouldUseRecordingFileNameTemplate(
                packageMode: .concatenate(outputFilename: group.outputFilename),
                metadata: groupMetadata
            ) && !recordingTemplate.isEmpty ? recordingTemplate : nil
            let outputName = templatedFileName(
                original: group.outputFilename,
                title: resolved.title,
                sourceURL: sourceURL,
                index: groupOrdinals[groupIndex],
                total: outputCount,
                metadata: outputMetadata,
                templateOverride: templateOverride
            )
            let output = AppPaths.uniqueFileURL(in: folder, filename: outputName)
            let tempFolder = folder.appendingPathComponent(
                ".stream-\(groupIndex + 1)-\(UUID().uuidString)",
                isDirectory: true
            )
            try AppPaths.ensureDirectory(tempFolder)
            defer { try? FileManager.default.removeItem(at: tempFolder) }

            jobs[jobIndex].message = "Downloading stream \(groupIndex + 1) / \(concatenations.count)"
            persistQueue()
            try await downloadAndConcatenate(streamAssets, tempFolder: tempFolder, output: output, jobIndex: jobIndex)
            let finalOutput = try await remuxGroupedHLSIfNeeded(
                output,
                metadata: groupMetadata,
                jobIndex: jobIndex
            )
            applyYouTubeUploadModificationDateIfNeeded(
                to: finalOutput,
                sourceURL: sourceURL,
                metadata: groupMetadata
            )
        }

        for (muxIndex, group) in muxes.enumerated() {
            try Task.checkCancellation()
            guard jobs.indices.contains(jobIndex) else { return }
            let videoAssets = group.videoAssetIndexes.map { resolved.assets[$0] }
            let audioAssets = group.audioAssetIndexes.map { resolved.assets[$0] }
            let groupMetadata = DownloadMetadata.clean(
                resolved.metadata.merging(group.metadata) { _, groupValue in groupValue }
            )
            let collectionItemID = groupMetadata["collection_item_id"]?.trimmed ?? ""
            if let existing = existingYouTubeOutputs[collectionItemID], !collectionItemID.isEmpty {
                applyYouTubeUploadModificationDateIfNeeded(
                    to: existing,
                    sourceURL: sourceURL,
                    metadata: groupMetadata
                )
                recordReusedYouTubeCollectionOutput(
                    id: collectionItemID,
                    output: existing,
                    assetCount: group.videoAssetIndexes.count + group.audioAssetIndexes.count,
                    jobIndex: jobIndex
                )
                continue
            }
            let outputMetadata = Self.mergedNameTemplateMetadata(
                groupMetadata,
                assetMetadata: videoAssets.first?.metadata ?? audioAssets.first?.metadata ?? [:]
            )
            let outputName = templatedFileName(
                original: group.outputFilename,
                title: resolved.title,
                sourceURL: sourceURL,
                index: muxOrdinals[muxIndex],
                total: outputCount,
                metadata: outputMetadata
            )
            let output = AppPaths.uniqueFileURL(in: folder, filename: outputName)
            try await downloadGroupedMux(
                videoAssets: videoAssets,
                audioAssets: audioAssets,
                output: output,
                groupIndex: muxIndex,
                groupCount: muxes.count,
                folder: folder,
                jobIndex: jobIndex
            )
            applyYouTubeUploadModificationDateIfNeeded(
                to: output,
                sourceURL: sourceURL,
                metadata: groupMetadata
            )
        }

        if jobs.indices.contains(jobIndex) {
            writeHitomiGalleryInfoTextIfNeeded(
                metadata: resolved.metadata,
                sourceURL: sourceURL,
                folder: folder,
                jobIndex: jobIndex
            )
            try archiveFolderIfNeeded(
                folder,
                sourceURL: sourceURL,
                metadata: resolved.metadata,
                jobIndex: jobIndex
            )
            jobs[jobIndex].status = .finished
            jobs[jobIndex].progress = 1
            jobs[jobIndex].message = "Done"
            await completeJob(at: jobIndex)
        }
    }

    private func downloadGroupedMux(
        videoAssets: [ResolvedAsset],
        audioAssets: [ResolvedAsset],
        output: URL,
        groupIndex: Int,
        groupCount: Int,
        folder: URL,
        jobIndex: Int
    ) async throws {
        let workFolder = folder.appendingPathComponent(
            ".mux-\(groupIndex + 1)-\(UUID().uuidString)",
            isDirectory: true
        )
        let videoFolder = workFolder.appendingPathComponent("video", isDirectory: true)
        let audioFolder = workFolder.appendingPathComponent("audio", isDirectory: true)
        let videoTrack = workFolder.appendingPathComponent("video-track.mp4")
        let audioTrack = workFolder.appendingPathComponent("audio-track.m4a")
        try AppPaths.ensureDirectory(videoFolder)
        try AppPaths.ensureDirectory(audioFolder)
        defer { try? FileManager.default.removeItem(at: workFolder) }

        jobs[jobIndex].message = "Downloading DASH video \(groupIndex + 1) / \(groupCount)"
        persistQueue()
        try await downloadAndConcatenate(
            videoAssets,
            tempFolder: videoFolder,
            output: videoTrack,
            jobIndex: jobIndex
        )

        guard jobs.indices.contains(jobIndex) else { return }
        jobs[jobIndex].message = "Downloading DASH audio \(groupIndex + 1) / \(groupCount)"
        persistQueue()
        try await downloadAndConcatenate(
            audioAssets,
            tempFolder: audioFolder,
            output: audioTrack,
            jobIndex: jobIndex
        )

        guard jobs.indices.contains(jobIndex) else { return }
        let transcodeOptions = ffmpegTranscodeOptionsForUse()
        jobs[jobIndex].message = transcodeOptions.enabled
            ? "Muxing and transcoding \(groupIndex + 1) / \(groupCount)"
            : "Muxing audio and video \(groupIndex + 1) / \(groupCount)"
        persistQueue()
        try await ffmpegBridge.mux(
            video: videoTrack,
            audio: audioTrack,
            output: output,
            options: transcodeOptions
        )
        let previousCount = Int(jobs[jobIndex].metadata["muxed_output_count"] ?? "0") ?? 0
        jobs[jobIndex].metadata["muxed_output_count"] = String(previousCount + 1)
        jobs[jobIndex].metadata["postprocess"] = transcodeOptions.enabled
            ? "ffmpeg-transcode"
            : "ffmpeg-mux"
        if transcodeOptions.enabled {
            jobs[jobIndex].metadata["transcoded"] = "true"
        }
        persistQueue()
    }

    private func remuxGroupedHLSIfNeeded(
        _ output: URL,
        metadata: [String: String],
        jobIndex: Int
    ) async throws -> URL {
        guard Self.shouldRemuxHLS(defaultEnabled: remuxM3U8ToMP4, metadata: metadata),
              metadata["type"] == "hls" || metadata["format"] == "m3u8" else {
            return output
        }
        guard jobs.indices.contains(jobIndex) else { return output }

        let transcodeOptions = ffmpegTranscodeOptionsForUse()
        jobs[jobIndex].message = transcodeOptions.enabled ? "Transcoding HLS stream" : "Remuxing HLS stream"
        persistQueue()
        let remuxed = AppPaths.uniqueFileURL(
            in: output.deletingLastPathComponent(),
            filename: "\(output.deletingPathExtension().lastPathComponent).mp4"
        )
        try await ffmpegBridge.remux(input: output, output: remuxed, options: transcodeOptions)
        try? FileManager.default.removeItem(at: output)

        if jobs.indices.contains(jobIndex) {
            let previousCount = Int(jobs[jobIndex].metadata["remuxed_stream_count"] ?? "0") ?? 0
            jobs[jobIndex].metadata["remuxed_stream_count"] = String(previousCount + 1)
            jobs[jobIndex].metadata["postprocess"] = transcodeOptions.enabled
                ? "ffmpeg-transcode"
                : "ffmpeg-remux"
            if transcodeOptions.enabled {
                jobs[jobIndex].metadata["transcoded"] = "true"
            }
            persistQueue()
        }
        return remuxed
    }

    private func remuxHLSIfNeeded(_ output: URL, resolved: ResolvedDownload, jobIndex: Int) async throws -> URL {
        guard Self.shouldRemuxHLS(defaultEnabled: remuxM3U8ToMP4, metadata: resolved.metadata),
              Self.isHLSDownload(resolved) else { return output }
        guard jobs.indices.contains(jobIndex) else { return output }

        let transcodeOptions = ffmpegTranscodeOptionsForUse()
        jobs[jobIndex].message = transcodeOptions.enabled ? "Transcoding HLS to MP4" : "Remuxing HLS to MP4"
        persistQueue()

        let remuxed = AppPaths.uniqueFileURL(
            in: output.deletingLastPathComponent(),
            filename: "\(output.deletingPathExtension().lastPathComponent).mp4"
        )
        try await ffmpegBridge.remux(input: output, output: remuxed, options: transcodeOptions)
        try? FileManager.default.removeItem(at: output)

        if jobs.indices.contains(jobIndex) {
            jobs[jobIndex].outputPath = remuxed.path
            jobs[jobIndex].metadata = Self.remuxedHLSMetadata(jobs[jobIndex].metadata, output: remuxed, options: transcodeOptions)
            persistQueue()
        }

        return remuxed
    }

    private nonisolated static func isHLSDownload(_ resolved: ResolvedDownload) -> Bool {
        resolved.metadata["type"] == "hls" || resolved.metadata["format"] == "m3u8"
    }

    nonisolated static func shouldRemuxHLS(defaultEnabled: Bool, metadata: [String: String]) -> Bool {
        if let required = metadata["hls_remux_required"],
           boolDirectiveValue(required) == true {
            return true
        }
        if let explicit = metadata["python_stream_post_processing"]?.trimmed.lowercased() {
            if ["true", "1", "yes", "on"].contains(explicit) {
                return true
            }
            if ["false", "0", "no", "off"].contains(explicit) {
                return false
            }
        }
        return defaultEnabled
    }

    private nonisolated static func remuxedHLSMetadata(_ metadata: [String: String], output: URL, options: FFmpegTranscodeOptions) -> [String: String] {
        var updated = metadata
        updated["basename"] = output.deletingPathExtension().lastPathComponent
        updated["container"] = "mp4"
        updated["ext"] = "mp4"
        updated["filename"] = output.lastPathComponent
        updated["format"] = "mp4"
        updated["remuxed"] = "true"
        if options.enabled {
            updated["postprocess"] = "ffmpeg-transcode"
            updated["transcoded"] = "true"
            for (key, value) in options.metadata {
                updated[key] = value
            }
        } else {
            updated["postprocess"] = "ffmpeg-remux"
        }
        return DownloadMetadata.clean(updated)
    }

    private nonisolated static func muxedDASHMetadata(_ metadata: [String: String], output: URL, options: FFmpegTranscodeOptions) -> [String: String] {
        var updated = metadata
        if let format = updated["format"], format != "mp4" {
            updated["source_format"] = format
        }
        updated["basename"] = output.deletingPathExtension().lastPathComponent
        updated["container"] = "mp4"
        updated["ext"] = "mp4"
        updated["filename"] = output.lastPathComponent
        updated["format"] = "mp4"
        updated["muxed"] = "true"
        if options.enabled {
            updated["postprocess"] = "ffmpeg-transcode"
            updated["transcoded"] = "true"
            for (key, value) in options.metadata {
                updated[key] = value
            }
        } else {
            updated["postprocess"] = "ffmpeg-mux"
        }
        return DownloadMetadata.clean(updated)
    }

    private func downloadNiconicoLiveStream(
        _ resolved: ResolvedDownload,
        sessionToken: String,
        root: URL,
        sourceURL: URL,
        jobIndex: Int
    ) async throws {
        guard jobs.indices.contains(jobIndex),
              let rawVideoURL = resolved.metadata["video_playlist_url"],
              let videoPlaylist = URL(string: rawVideoURL),
              let outputFilename = resolved.metadata["live_output_filename"]?.trimmed,
              !outputFilename.isEmpty else {
            await niconicoLiveResolver.stopSession(sessionToken)
            throw NativeDownloadError.unsupported("Niconico Live recording information is incomplete.")
        }
        let audioPlaylist = resolved.metadata["audio_playlist_url"].flatMap { raw -> URL? in
            let value = raw.trimmed
            return value.isEmpty ? nil : URL(string: value)
        }
        let outputName = templatedFileName(
            original: outputFilename,
            title: resolved.title,
            sourceURL: sourceURL,
            index: nil,
            total: 1,
            metadata: Self.mergedNameTemplateMetadata(
                resolved.metadata,
                assetMetadata: resolved.assets.first?.metadata ?? [:]
            )
        )
        let output = AppPaths.uniqueFileURL(in: root, filename: outputName)
        let prototype = resolved.assets.first
        var headers = prototype?.additionalHeaderFields ?? [:]
        if let referer = prototype?.referer?.trimmed, !referer.isEmpty {
            headers["Referer"] = referer
        }
        if let userAgent = prototype?.userAgent?.trimmed, !userAgent.isEmpty {
            headers["User-Agent"] = userAgent
        }
        let transcodeOptions = ffmpegTranscodeOptionsForUse()
        let jobID = jobs[jobIndex].id
        let processControl = ExternalProcessControl()
        ffmpegRuntimeProcesses[jobID] = processControl
        jobs[jobIndex].outputPath = output.path
        jobs[jobIndex].message = transcodeOptions.enabled
            ? "Recording and transcoding Niconico Live"
            : "Recording Niconico Live"
        jobs[jobIndex].metadata["live_active"] = "true"
        jobs[jobIndex].metadata["live_recording"] = "true"
        jobs[jobIndex].metadata["live_started_at"] = ISO8601DateFormatter().string(from: Date())
        persistQueue()

        do {
            try await ffmpegBridge.recordLiveHLS(
                videoPlaylist: videoPlaylist,
                audioPlaylist: audioPlaylist,
                output: output,
                headers: headers,
                options: transcodeOptions,
                processControl: processControl
            )
        } catch {
            ffmpegRuntimeProcesses.removeValue(forKey: jobID)
            await niconicoLiveResolver.stopSession(sessionToken)
            if jobs.indices.contains(jobIndex), jobs[jobIndex].id == jobID {
                jobs[jobIndex].metadata["live_active"] = "false"
                jobs[jobIndex].metadata["live_recording"] = "false"
                jobs[jobIndex].metadata["live_done"] = "true"
                jobs[jobIndex].metadata["live_end_reason"] = error is CancellationError ? "cancelled" : "error"
                jobs[jobIndex].metadata["live_partial_output"] = Self.fileHasContent(output) ? "true" : "false"
                persistQueue()
            }
            if !Self.fileHasContent(output) {
                try? FileManager.default.removeItem(at: output)
            }
            throw error
        }

        ffmpegRuntimeProcesses.removeValue(forKey: jobID)
        await niconicoLiveResolver.stopSession(sessionToken)
        guard jobs.indices.contains(jobIndex), jobs[jobIndex].id == jobID else { return }
        jobs[jobIndex].status = .finished
        jobs[jobIndex].completed = max(1, jobs[jobIndex].total)
        jobs[jobIndex].progress = 1
        jobs[jobIndex].message = "Done"
        jobs[jobIndex].outputPath = output.path
        jobs[jobIndex].metadata = Self.recordedNiconicoLiveMetadata(
            jobs[jobIndex].metadata,
            output: output,
            hadSeparateAudio: audioPlaylist != nil,
            options: transcodeOptions
        )
        await completeJob(at: jobIndex)
    }

    private nonisolated static func recordedNiconicoLiveMetadata(
        _ metadata: [String: String],
        output: URL,
        hadSeparateAudio: Bool,
        options: FFmpegTranscodeOptions
    ) -> [String: String] {
        var updated = metadata
        updated.removeValue(forKey: "niconico_live_session_token")
        updated["live_active"] = "false"
        updated["live_recording"] = "false"
        updated["live_done"] = "true"
        updated["live_end_reason"] = "stream_ended"
        updated["live_partial_output"] = "false"
        updated["filename"] = output.lastPathComponent
        updated["format"] = output.pathExtension.lowercased()
        updated["media_format"] = output.pathExtension.lowercased()
        updated["postprocess"] = hadSeparateAudio ? "ffmpeg-live-mux" : "ffmpeg-live-record"
        updated["muxed"] = hadSeparateAudio ? "true" : "false"
        if let size = try? output.resourceValues(forKeys: [.fileSizeKey]).fileSize {
            updated["bytes"] = String(size)
            updated["size"] = String(size)
        }
        if options.enabled {
            updated["transcoded"] = "true"
            for (key, value) in options.metadata {
                updated[key] = value
            }
        }
        return DownloadMetadata.clean(updated)
    }

    private func downloadAndMux(videoAssets: [ResolvedAsset], audioAssets: [ResolvedAsset], folderName: String, outputFilename: String, root: URL, jobIndex: Int) async throws {
        guard jobs.indices.contains(jobIndex) else { return }
        let workFolder = root.appendingPathComponent(".\(folderName.sanitizedFilename(maxLength: 120))-\(UUID().uuidString)", isDirectory: true)
        let videoFolder = workFolder.appendingPathComponent("video", isDirectory: true)
        let audioFolder = workFolder.appendingPathComponent("audio", isDirectory: true)
        let videoTrack = workFolder.appendingPathComponent("video-track.mp4")
        let audioTrack = workFolder.appendingPathComponent("audio-track.m4a")
        let output = AppPaths.uniqueFileURL(in: root, filename: outputFilename)

        try AppPaths.ensureDirectory(videoFolder)
        try AppPaths.ensureDirectory(audioFolder)
        jobs[jobIndex].outputPath = output.path
        jobs[jobIndex].message = "Downloading DASH video"
        persistQueue()

        defer {
            try? FileManager.default.removeItem(at: workFolder)
        }

        try await downloadAndConcatenate(videoAssets, tempFolder: videoFolder, output: videoTrack, jobIndex: jobIndex)

        if jobs.indices.contains(jobIndex) {
            jobs[jobIndex].message = "Downloading DASH audio"
            persistQueue()
        }
        try await downloadAndConcatenate(audioAssets, tempFolder: audioFolder, output: audioTrack, jobIndex: jobIndex)

        let transcodeOptions = ffmpegTranscodeOptionsForUse()
        if jobs.indices.contains(jobIndex) {
            jobs[jobIndex].message = transcodeOptions.enabled ? "Muxing and transcoding audio/video" : "Muxing audio and video"
            persistQueue()
            try await ffmpegBridge.mux(video: videoTrack, audio: audioTrack, output: output, options: transcodeOptions)
        } else {
            return
        }

        if jobs.indices.contains(jobIndex) {
            let metadata = jobs[jobIndex].metadata
            applyYouTubeUploadModificationDateIfNeeded(
                to: output,
                sourceURL: URL(string: jobs[jobIndex].source),
                metadata: metadata
            )
            jobs[jobIndex].status = .finished
            jobs[jobIndex].progress = 1
            jobs[jobIndex].message = "Done"
            jobs[jobIndex].metadata = Self.muxedDASHMetadata(jobs[jobIndex].metadata, output: output, options: transcodeOptions)
            await completeJob(at: jobIndex)
        }
    }

    private func downloadDirect(
        _ url: URL,
        jobIndex: Int,
        resolveHTMLMedia: Bool = true
    ) async throws {
        guard jobs.indices.contains(jobIndex) else { return }
        var url = url
        var hookedFilename: String?
        if let hooked = try await runSyntheticPythonDownloadHooks(
            sourceURL: url,
            title: (Self.directDownloadFilename(for: url) as NSString).deletingPathExtension,
            filename: Self.directDownloadFilename(for: url),
            metadata: ["type": "direct", "handler": "native"],
            jobIndex: jobIndex
        ) {
            if let hookedURL = URL(string: hooked.sourceURL.trimmed), !hooked.sourceURL.trimmed.isEmpty {
                url = hookedURL
            }
            hookedFilename = hooked.assets.first?.filename.trimmed
        }
        let root = try outputRoot(for: url)

        let provisionalName = hookedFilename?.isEmpty == false ? hookedFilename! : Self.directDownloadFilename(for: url)
        let provisionalOutputName = templatedFileName(
            original: provisionalName,
            title: (provisionalName as NSString).deletingPathExtension,
            sourceURL: url,
            index: 1,
            total: 1
        )

        jobs[jobIndex].title = provisionalOutputName
        let provisionalMetadata = Self.directDownloadMetadata(for: url, filename: provisionalName)
        jobs[jobIndex].metadata = Self.resolvedMetadataPreservingRuntimeState(
            provisionalMetadata,
            previous: jobs[jobIndex].metadata
        )
        jobs[jobIndex].total = 1
        jobs[jobIndex].completed = 0
        jobs[jobIndex].status = .downloading
        jobs[jobIndex].message = "Downloading file"
        jobs[jobIndex].outputPath = root.appendingPathComponent(provisionalOutputName).path
        persistQueue()

        if await finishExistingSingleOutputIfNeeded(
            outputName: provisionalOutputName,
            root: root,
            metadata: provisionalMetadata,
            jobIndex: jobIndex
        ) {
            return
        }

        let headers = requestOptions(for: url)
        let headResponse = try? await HTTPClient.shared.head(from: url, referer: headers.referer, userAgent: headers.userAgent)
        let segmentDirective = jobs.indices.contains(jobIndex) ? Self.directSegmentDirective(from: jobs[jobIndex].comment) : nil
        if let headResponse,
           !Self.isHTMLResponse(headResponse),
           let splitSegments = Self.directSplitSegments(from: headResponse, directive: segmentDirective) {
            let finalName = hookedFilename?.isEmpty == false ? hookedFilename! : Self.directDownloadFilename(for: url, response: headResponse)
            let outputName = templatedFileName(
                original: finalName,
                title: (finalName as NSString).deletingPathExtension,
                sourceURL: url,
                index: 1,
                total: 1
            )
            let metadata = Self.directDownloadMetadata(
                for: url,
                filename: finalName,
                response: headResponse,
                splitSegmentCount: splitSegments.count
            )
            if await finishExistingSingleOutputIfNeeded(outputName: outputName, root: root, metadata: metadata, jobIndex: jobIndex) {
                return
            }
            let destination = AppPaths.uniqueFileURL(in: root, filename: outputName)
            do {
                try await downloadDirectSegments(
                    url,
                    segments: splitSegments,
                    to: destination,
                    headers: headers,
                    jobIndex: jobIndex
                )

                if jobs.indices.contains(jobIndex) {
                    jobs[jobIndex].title = outputName
                    jobs[jobIndex].outputPath = destination.path
                    jobs[jobIndex].metadata = Self.resolvedMetadataPreservingRuntimeState(Self.directDownloadMetadata(
                        for: url,
                        filename: finalName,
                        response: headResponse,
                        byteCount: splitSegments.last.map { $0.upperBound + 1 },
                        splitSegmentCount: splitSegments.count
                    ), previous: jobs[jobIndex].metadata)
                    jobs[jobIndex].completed = splitSegments.count
                    jobs[jobIndex].progress = 1
                    jobs[jobIndex].status = .finished
                    jobs[jobIndex].message = "Done"
                    await completeJob(at: jobIndex)
                }
                return
            } catch {
                try? FileManager.default.removeItem(at: destination)
                if jobs.indices.contains(jobIndex) {
                    jobs[jobIndex].title = provisionalOutputName
                    jobs[jobIndex].metadata = Self.resolvedMetadataPreservingRuntimeState(
                        Self.directDownloadMetadata(for: url, filename: provisionalName),
                        previous: jobs[jobIndex].metadata
                    )
                    jobs[jobIndex].total = 1
                    jobs[jobIndex].completed = 0
                    jobs[jobIndex].progress = 0
                    jobs[jobIndex].message = "Downloading file"
                    jobs[jobIndex].outputPath = root.appendingPathComponent(provisionalOutputName).path
                    persistQueue()
                }
            }
        }

        if let headResponse, !Self.isHTMLResponse(headResponse) {
            let finalName = hookedFilename?.isEmpty == false ? hookedFilename! : Self.directDownloadFilename(for: url, response: headResponse)
            let outputName = templatedFileName(
                original: finalName,
                title: (finalName as NSString).deletingPathExtension,
                sourceURL: url,
                index: 1,
                total: 1
            )
            let metadata = Self.directDownloadMetadata(for: url, filename: finalName, response: headResponse)
            if await finishExistingSingleOutputIfNeeded(outputName: outputName, root: root, metadata: metadata, jobIndex: jobIndex) {
                return
            }
        }

        let temporary = root.appendingPathComponent(".direct-\(UUID().uuidString).download")
        defer {
            try? FileManager.default.removeItem(at: temporary)
        }

        let response = try await HTTPClient.shared.download(from: url, to: temporary, referer: headers.referer, userAgent: headers.userAgent)
        if resolveHTMLMedia,
           Self.isHTMLResponse(response),
           let data = try? Data(contentsOf: temporary),
           let html = String(data: data, encoding: .utf8),
           let resolved = GenericPageResolver.resolvedDownload(fromHTML: html, pageURL: url) {
            try await downloadResolved(resolved, sourceURL: url, jobIndex: jobIndex)
            return
        }

        let finalName = hookedFilename?.isEmpty == false ? hookedFilename! : Self.directDownloadFilename(for: url, response: response)
        let outputName = templatedFileName(
            original: finalName,
            title: (finalName as NSString).deletingPathExtension,
            sourceURL: url,
            index: 1,
            total: 1
        )
        let metadata = Self.directDownloadMetadata(for: url, filename: finalName, response: response, byteCount: try? temporary.resourceValues(forKeys: [.fileSizeKey]).fileSize, splitSegmentCount: nil)
        if await finishExistingSingleOutputIfNeeded(outputName: outputName, root: root, metadata: metadata, jobIndex: jobIndex) {
            return
        }
        let destination = AppPaths.uniqueFileURL(in: root, filename: outputName)
        if FileManager.default.fileExists(atPath: destination.path) {
            try FileManager.default.removeItem(at: destination)
        }
        try FileManager.default.moveItem(at: temporary, to: destination)

        if jobs.indices.contains(jobIndex) {
            jobs[jobIndex].title = outputName
            jobs[jobIndex].outputPath = destination.path
            jobs[jobIndex].metadata = Self.resolvedMetadataPreservingRuntimeState(
                Self.directDownloadMetadata(for: url, filename: finalName, response: response, byteCount: try? destination.resourceValues(forKeys: [.fileSizeKey]).fileSize, splitSegmentCount: nil),
                previous: jobs[jobIndex].metadata
            )
            jobs[jobIndex].completed = 1
            jobs[jobIndex].progress = 1
            jobs[jobIndex].status = .finished
            jobs[jobIndex].message = "Done"
            await completeJob(at: jobIndex)
        }
    }

    private func downloadLocalFile(_ url: URL, jobIndex: Int) async throws {
        guard jobs.indices.contains(jobIndex) else { return }
        let fileURL = url.standardizedFileURL
        var isDirectory: ObjCBool = false
        guard FileManager.default.fileExists(atPath: fileURL.path, isDirectory: &isDirectory) else {
            throw NativeDownloadError.unsupported("Local file is unavailable.")
        }
        if isDirectory.boolValue {
            try await downloadLocalFolder(fileURL, jobIndex: jobIndex)
            return
        }

        if Self.isLocalHTMLFile(fileURL),
           let html = Self.localHTMLString(from: fileURL),
           let resolved = GenericPageResolver.resolvedDownload(fromHTML: html, pageURL: fileURL) {
            jobs[jobIndex].status = .resolving
            jobs[jobIndex].message = "Scanning local HTML media"
            persistQueue()
            try await downloadResolved(resolved, sourceURL: fileURL, jobIndex: jobIndex)
            return
        }

        let root = try outputRoot(for: fileURL)
        let sourceFilename = Self.localFilename(for: fileURL)
        let originalFilename = Self.improvedOriginalLocalFilename(
            for: url,
            sourceFilename: sourceFilename
        )
        let originalMetadata = Self.localFileMetadata(for: fileURL, filename: originalFilename)
        let hooked = try await runSyntheticPythonDownloadHooks(
            sourceURL: fileURL,
            title: (originalFilename as NSString).deletingPathExtension,
            filename: originalFilename,
            metadata: originalMetadata,
            jobIndex: jobIndex
        )
        let filename = hooked?.assets.first?.filename.trimmed.isEmpty == false
            ? hooked!.assets[0].filename.trimmed
            : originalFilename
        let basename = (filename as NSString).deletingPathExtension
        let metadata = Self.localFileMetadata(for: fileURL, filename: filename)
        let outputName = templatedFileName(
            original: filename,
            title: basename,
            sourceURL: fileURL,
            index: 1,
            total: 1,
            metadata: metadata
        )
        let destination = AppPaths.uniqueFileURL(in: root, filename: outputName)

        jobs[jobIndex].title = outputName
        jobs[jobIndex].metadata = Self.resolvedMetadataPreservingRuntimeState(
            metadata,
            previous: jobs[jobIndex].metadata
        )
        jobs[jobIndex].total = 1
        jobs[jobIndex].completed = 0
        jobs[jobIndex].status = .downloading
        jobs[jobIndex].message = "Copying local file"
        jobs[jobIndex].outputPath = destination.path
        persistQueue()

        try FileManager.default.copyItem(at: fileURL, to: destination)

        if jobs.indices.contains(jobIndex) {
            jobs[jobIndex].completed = 1
            jobs[jobIndex].progress = 1
            jobs[jobIndex].status = .finished
            jobs[jobIndex].message = "Done"
            jobs[jobIndex].metadata = Self.resolvedMetadataPreservingRuntimeState(Self.localFileMetadata(
                for: fileURL,
                filename: filename,
                byteCount: try? destination.resourceValues(forKeys: [.fileSizeKey]).fileSize
            ), previous: jobs[jobIndex].metadata)
            await completeJob(at: jobIndex)
        }
    }

    private func downloadLocalFolder(_ folderURL: URL, jobIndex: Int) async throws {
        guard jobs.indices.contains(jobIndex) else { return }

        let root = try outputRoot(for: folderURL)
        var folderName = Self.localFolderName(for: folderURL)
        let fileCount = Self.localFolderFileCount(in: folderURL)
        let metadata = Self.localFolderMetadata(for: folderURL, folderName: folderName, fileCount: fileCount)
        if let hooked = try await runSyntheticPythonDownloadHooks(
            sourceURL: folderURL,
            title: folderName,
            filename: folderName,
            metadata: metadata,
            jobIndex: jobIndex
        ), !hooked.title.trimmed.isEmpty {
            folderName = hooked.title.trimmed
        }
        let resolved = ResolvedDownload(
            title: folderName,
            folderName: folderName,
            assets: [],
            metadata: metadata
        )
        let outputFolderName = templatedFolderName(for: resolved, sourceURL: folderURL)
        let destination = AppPaths.uniqueDirectoryURL(in: root, name: outputFolderName)

        jobs[jobIndex].title = outputFolderName
        jobs[jobIndex].metadata = Self.resolvedMetadataPreservingRuntimeState(
            metadata,
            previous: jobs[jobIndex].metadata
        )
        jobs[jobIndex].total = fileCount
        jobs[jobIndex].completed = 0
        jobs[jobIndex].status = .downloading
        jobs[jobIndex].message = "Copying local folder"
        jobs[jobIndex].outputPath = destination.path
        persistQueue()

        try AppPaths.ensureDirectory(destination.deletingLastPathComponent())
        try FileManager.default.copyItem(at: folderURL, to: destination)

        if jobs.indices.contains(jobIndex) {
            jobs[jobIndex].completed = fileCount
            jobs[jobIndex].progress = 1
            jobs[jobIndex].status = .finished
            jobs[jobIndex].message = "Done"
            jobs[jobIndex].metadata = Self.resolvedMetadataPreservingRuntimeState(
                Self.localFolderMetadata(for: folderURL, folderName: folderName, fileCount: fileCount),
                previous: jobs[jobIndex].metadata
            )
            await completeJob(at: jobIndex)
        }
    }

    @discardableResult
    func finishExistingSingleOutputIfNeeded(outputName: String, root: URL, metadata: [String: String], jobIndex: Int) async -> Bool {
        guard skipDuplicates,
              jobs.indices.contains(jobIndex),
              Self.shouldSkipExistingSingleOutput(metadata),
              let existing = Self.existingOutputFileURL(in: root, filename: outputName) else {
            return false
        }

        var updatedMetadata = metadata
        updatedMetadata["skipped_existing_file"] = "true"
        updatedMetadata["skip_reason"] = "existing_output_file"
        updatedMetadata["filename"] = existing.lastPathComponent
        updatedMetadata["basename"] = existing.deletingPathExtension().lastPathComponent
        updatedMetadata["ext"] = existing.pathExtension.lowercased()
        updatedMetadata["byte_count"] = (try? existing.resourceValues(forKeys: [.fileSizeKey]).fileSize).map(String.init) ?? updatedMetadata["byte_count"] ?? ""
        jobs[jobIndex].title = existing.lastPathComponent
        jobs[jobIndex].metadata = Self.resolvedMetadataPreservingRuntimeState(
            DownloadMetadata.clean(updatedMetadata),
            previous: jobs[jobIndex].metadata
        )
        jobs[jobIndex].total = 1
        jobs[jobIndex].completed = 1
        jobs[jobIndex].progress = 1
        jobs[jobIndex].status = .finished
        jobs[jobIndex].message = "Skipped existing file"
        jobs[jobIndex].outputPath = existing.path
        addSummary = "Skipped existing file"
        await completeJob(at: jobIndex)
        return true
    }

    nonisolated static func existingOutputFileURL(in directory: URL, filename: String, fileManager: FileManager = .default) -> URL? {
        let candidate = AppPaths.fileURL(in: directory, filename: filename)
        var isDirectory: ObjCBool = false
        guard fileManager.fileExists(atPath: candidate.path, isDirectory: &isDirectory),
              !isDirectory.boolValue else {
            return nil
        }
        return candidate
    }

    private nonisolated static func shouldSkipExistingSingleOutput(_ metadata: [String: String]) -> Bool {
        let category = metadataValue(metadata, keys: ["category"]).lowercased()
        let type = metadataValue(metadata, keys: ["type"]).lowercased()
        guard type == "direct" || type == "local_file" else { return false }
        return category == "video"
    }

    private func downloadDirectSegments(_ url: URL, segments: [DirectSplitSegment], to destination: URL, headers: HTTPRequestOptions, jobIndex: Int) async throws {
        let partFolder = destination.deletingLastPathComponent().appendingPathComponent(".direct-\(UUID().uuidString).parts")
        try FileManager.default.createDirectory(at: partFolder, withIntermediateDirectories: true)
        defer {
            try? FileManager.default.removeItem(at: partFolder)
        }

        if jobs.indices.contains(jobIndex) {
            jobs[jobIndex].title = destination.lastPathComponent
            jobs[jobIndex].outputPath = destination.path
            jobs[jobIndex].total = segments.count
            jobs[jobIndex].completed = 0
            jobs[jobIndex].progress = 0
            jobs[jobIndex].message = "Downloading 0 / \(segments.count) parts"
            persistQueue()
        }

        let limit = AsyncSemaphore(value: max(1, min(8, concurrency)))
        try await withThrowingTaskGroup(of: Void.self) { group in
            for segment in segments {
                group.addTask {
                    try Task.checkCancellation()
                    try await limit.withPermit {
                        let partURL = partFolder.appendingPathComponent(String(format: "%06d.part", segment.index))
                        let rangeHeader = "bytes=\(segment.lowerBound)-\(segment.upperBound)"
                        let response = try await HTTPClient.shared.download(
                            from: url,
                            to: partURL,
                            referer: headers.referer,
                            userAgent: headers.userAgent,
                            additionalHeaders: ["Range": rangeHeader]
                        )
                        guard response?.statusCode == 206 else {
                            throw NativeDownloadError.unsupported("Server did not honor byte range \(rangeHeader).")
                        }
                        let expectedSize = segment.upperBound - segment.lowerBound + 1
                        let actualSize = (try? partURL.resourceValues(forKeys: [.fileSizeKey]).fileSize) ?? 0
                        guard actualSize == expectedSize else {
                            throw NativeDownloadError.unsupported("Byte range \(rangeHeader) returned \(actualSize) bytes, expected \(expectedSize).")
                        }
                    }
                }
            }

            for try await _ in group {
                try Task.checkCancellation()
                if jobs.indices.contains(jobIndex) {
                    jobs[jobIndex].completed += 1
                    jobs[jobIndex].progress = Double(jobs[jobIndex].completed) / Double(max(1, jobs[jobIndex].total))
                    jobs[jobIndex].message = "Downloading \(jobs[jobIndex].completed) / \(jobs[jobIndex].total) parts"
                    persistQueue()
                }
            }
        }

        if jobs.indices.contains(jobIndex) {
            jobs[jobIndex].message = "Joining parts"
            persistQueue()
        }

        if FileManager.default.fileExists(atPath: destination.path) {
            try FileManager.default.removeItem(at: destination)
        }
        FileManager.default.createFile(atPath: destination.path, contents: nil)
        let writer = try FileHandle(forWritingTo: destination)
        defer {
            try? writer.close()
        }

        for segment in segments.sorted(by: { $0.index < $1.index }) {
            try Task.checkCancellation()
            let partURL = partFolder.appendingPathComponent(String(format: "%06d.part", segment.index))
            let reader = try FileHandle(forReadingFrom: partURL)
            defer {
                try? reader.close()
            }
            while true {
                let chunk = try reader.read(upToCount: 1_048_576) ?? Data()
                if chunk.isEmpty { break }
                try writer.write(contentsOf: chunk)
            }
        }
    }

    nonisolated static func directDownloadFilename(for url: URL) -> String {
        directDownloadFilename(for: url, response: nil)
    }

    nonisolated static func directDownloadFilename(for url: URL, response: HTTPURLResponse?) -> String {
        if let headerName = responseFilename(from: response) {
            return filenameByAppendingContentTypeExtensionIfNeeded(headerName, response: response)
        }
        if let hint = queryFilenameHint(from: url) {
            return filenameByAppendingContentTypeExtensionIfNeeded(hint, response: response)
        }
        let last = url.lastPathComponent.trimmed
        if last.isEmpty || last == "/" {
            return filenameByAppendingContentTypeExtensionIfNeeded("download", response: response)
        }
        return filenameByAppendingContentTypeExtensionIfNeeded(last, response: response)
    }

    nonisolated static func directDownloadMetadata(for url: URL, filename: String, response: HTTPURLResponse? = nil, byteCount: Int? = nil, splitSegmentCount: Int? = nil) -> [String: String] {
        let ext = (filename as NSString).pathExtension.lowercased()
        let basename = (filename as NSString).deletingPathExtension
        let host = url.host ?? ""
        let contentType = response?.value(forHTTPHeaderField: "Content-Type")?.components(separatedBy: ";").first?.trimmed ?? ""
        let contentLength = response?.value(forHTTPHeaderField: "Content-Length")?.trimmed
        let effectiveByteCount = byteCount.map(String.init) ?? contentLength ?? ""
        let segmentCount = splitSegmentCount.map(String.init) ?? ""
        return DownloadMetadata.clean([
            "series": basename,
            "category": directDownloadCategory(forExtension: ext, contentType: contentType),
            "type": "direct",
            "download_mode": (splitSegmentCount ?? 1) > 1 ? "split" : "single",
            "segment_count": segmentCount,
            "format": ext,
            "host": host,
            "site": host,
            "filename": filename,
            "basename": basename,
            "ext": ext,
            "slug": sourceSlug(from: url, fallback: basename),
            "path": url.path,
            "query": url.query ?? "",
            "url": url.absoluteString,
            "content_type": contentType,
            "content_length": contentLength ?? "",
            "byte_count": effectiveByteCount,
            "title": basename
        ])
    }

    private nonisolated static func directDownloadCategory(forExtension ext: String, contentType: String) -> String {
        let loweredContentType = contentType.lowercased()
        if loweredContentType.contains("text/html") || loweredContentType.contains("application/xhtml+xml") || ["html", "htm"].contains(ext) {
            return "page"
        }
        if loweredContentType.hasPrefix("image/") || ["jpg", "jpeg", "png", "gif", "webp", "avif", "bmp", "svg"].contains(ext) {
            return "image"
        }
        if loweredContentType.hasPrefix("video/") || ["mp4", "m4v", "mov", "webm", "mkv", "avi"].contains(ext) {
            return "video"
        }
        if loweredContentType.hasPrefix("audio/") || ["mp3", "m4a", "aac", "flac", "wav", "ogg"].contains(ext) {
            return "audio"
        }
        if loweredContentType == "application/pdf" ||
            loweredContentType == "application/epub+zip" ||
            loweredContentType == "application/msword" ||
            loweredContentType == "application/rtf" ||
            loweredContentType.hasPrefix("application/vnd.openxmlformats-officedocument.") ||
            loweredContentType.hasPrefix("application/vnd.oasis.opendocument.") ||
            ["pdf", "epub", "mobi", "azw", "azw3", "doc", "docx", "rtf", "xls", "xlsx", "ppt", "pptx", "odt", "ods", "odp", "txt", "csv"].contains(ext) {
            return "document"
        }
        if loweredContentType == "application/vnd.comicbook+zip" ||
            loweredContentType == "application/vnd.comicbook-rar" ||
            loweredContentType == "application/vnd.rar" ||
            loweredContentType == "application/x-cbr" ||
            loweredContentType == "application/x-cbz" ||
            loweredContentType == "application/x-comicbook+zip" ||
            loweredContentType == "application/x-comicbook-rar" ||
            loweredContentType == "application/gzip" ||
            loweredContentType == "application/x-gzip" ||
            loweredContentType == "application/x-tar" ||
            loweredContentType == "application/x-gtar" ||
            loweredContentType == "application/x-gtar-compressed" ||
            loweredContentType == "application/tar+gzip" ||
            loweredContentType == "application/x-compressed-tar" ||
            loweredContentType == "application/x-bzip2" ||
            loweredContentType == "application/x-xz" ||
            loweredContentType == "application/zstd" ||
            loweredContentType == "application/x-zstd" ||
            ["zip", "rar", "7z", "cbz", "cbr", "tar", "gz", "tgz", "bz2", "xz", "zst"].contains(ext) {
            return "archive"
        }
        return "file"
    }

    private nonisolated static func filenameByAppendingContentTypeExtensionIfNeeded(_ filename: String, response: HTTPURLResponse?) -> String {
        let trimmed = filename.trimmed
        guard !trimmed.isEmpty,
              (trimmed as NSString).pathExtension.trimmed.isEmpty,
              let ext = directDownloadExtension(forContentType: response?.value(forHTTPHeaderField: "Content-Type")) else {
            return trimmed
        }
        return "\(trimmed).\(ext)"
    }

    private nonisolated static func directDownloadExtension(forContentType rawContentType: String?) -> String? {
        let contentType = rawContentType?
            .components(separatedBy: ";")
            .first?
            .trimmed
            .lowercased() ?? ""
        guard !contentType.isEmpty else { return nil }

        let exact: [String: String] = [
            "image/jpeg": "jpg",
            "image/jpg": "jpg",
            "image/png": "png",
            "image/gif": "gif",
            "image/webp": "webp",
            "image/avif": "avif",
            "image/bmp": "bmp",
            "image/svg+xml": "svg",
            "video/mp4": "mp4",
            "video/mpeg": "mpg",
            "video/webm": "webm",
            "video/quicktime": "mov",
            "video/x-matroska": "mkv",
            "video/x-msvideo": "avi",
            "audio/mpeg": "mp3",
            "audio/mp3": "mp3",
            "audio/mp4": "m4a",
            "audio/aac": "aac",
            "audio/flac": "flac",
            "audio/wav": "wav",
            "audio/x-wav": "wav",
            "audio/ogg": "ogg",
            "application/pdf": "pdf",
            "application/epub+zip": "epub",
            "application/x-mobipocket-ebook": "mobi",
            "application/vnd.amazon.ebook": "azw",
            "application/msword": "doc",
            "application/vnd.openxmlformats-officedocument.wordprocessingml.document": "docx",
            "application/vnd.ms-excel": "xls",
            "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet": "xlsx",
            "application/vnd.ms-powerpoint": "ppt",
            "application/vnd.openxmlformats-officedocument.presentationml.presentation": "pptx",
            "application/vnd.oasis.opendocument.text": "odt",
            "application/vnd.oasis.opendocument.spreadsheet": "ods",
            "application/vnd.oasis.opendocument.presentation": "odp",
            "application/rtf": "rtf",
            "text/csv": "csv",
            "application/zip": "zip",
            "application/x-zip-compressed": "zip",
            "application/vnd.comicbook+zip": "cbz",
            "application/vnd.comicbook-rar": "cbr",
            "application/x-cbz": "cbz",
            "application/x-cbr": "cbr",
            "application/x-comicbook+zip": "cbz",
            "application/x-comicbook-rar": "cbr",
            "application/vnd.rar": "rar",
            "application/x-rar-compressed": "rar",
            "application/x-7z-compressed": "7z",
            "application/gzip": "gz",
            "application/x-gzip": "gz",
            "application/x-tar": "tar",
            "application/x-gtar": "tar",
            "application/x-gtar-compressed": "tgz",
            "application/tar+gzip": "tgz",
            "application/x-compressed-tar": "tgz",
            "application/x-bzip2": "bz2",
            "application/x-xz": "xz",
            "application/zstd": "zst",
            "application/x-zstd": "zst",
            "application/json": "json",
            "text/plain": "txt",
            "text/html": "html",
            "application/xhtml+xml": "xhtml"
        ]
        if let ext = exact[contentType] {
            return ext
        }
        if contentType.hasSuffix("+json") {
            return "json"
        }
        if contentType.hasSuffix("+zip") {
            return "zip"
        }
        if contentType.hasPrefix("text/") {
            return "txt"
        }
        return nil
    }

    private nonisolated static func localFileMetadata(for url: URL, filename: String, byteCount: Int? = nil) -> [String: String] {
        let ext = (filename as NSString).pathExtension.lowercased()
        let basename = (filename as NSString).deletingPathExtension
        let size = byteCount ?? (try? url.resourceValues(forKeys: [.fileSizeKey]).fileSize)
        return DownloadMetadata.clean([
            "series": basename,
            "category": directDownloadCategory(forExtension: ext, contentType: ""),
            "type": "local_file",
            "download_mode": "copy",
            "format": ext,
            "host": "local",
            "site": "local",
            "filename": filename,
            "basename": basename,
            "ext": ext,
            "slug": sourceSlug(from: url, fallback: basename),
            "path": url.path,
            "url": url.absoluteString,
            "byte_count": size.map(String.init) ?? "",
            "title": basename
        ])
    }

    private nonisolated static func localFilename(for url: URL) -> String {
        let name = url.lastPathComponent.removingPercentEncoding?.trimmed ?? url.lastPathComponent.trimmed
        return name.isEmpty ? "local-file" : name
    }

    nonisolated static func improvedOriginalLocalFilename(for url: URL, sourceFilename: String) -> String {
        let ext = (sourceFilename as NSString).pathExtension
        let stem = (sourceFilename as NSString).deletingPathExtension.sanitizedFilename(maxLength: 180)
        let digest = Insecure.MD5.hash(data: Data(url.absoluteString.utf8))
            .prefix(4)
            .map { String(format: "%02x", $0) }
            .joined()
        let suffix = " (\(digest))" + (ext.isEmpty ? "" : ".\(ext)")
        let maximumCharacters = 180
        let maximumBytes = 240
        let characterLimit = max(1, maximumCharacters - suffix.count)
        let byteLimit = max(1, maximumBytes - suffix.utf8.count)
        var cleanStem = ""
        var usedBytes = 0
        for character in stem.prefix(characterLimit) {
            let bytes = String(character).utf8.count
            guard usedBytes + bytes <= byteLimit else { break }
            cleanStem.append(character)
            usedBytes += bytes
        }
        cleanStem = cleanStem.trimmingCharacters(in: CharacterSet(charactersIn: " .-").union(.whitespacesAndNewlines))
        if cleanStem.isEmpty {
            cleanStem = "download"
        }
        return "\(cleanStem)\(suffix)".sanitizedFilename(maxLength: maximumCharacters)
    }

    private nonisolated static func localFolderName(for url: URL) -> String {
        let name = url.lastPathComponent.removingPercentEncoding?.trimmed ?? url.lastPathComponent.trimmed
        return name.isEmpty ? "local-folder" : name
    }

    private nonisolated static func localFolderFileCount(in url: URL) -> Int {
        guard let enumerator = FileManager.default.enumerator(
            at: url,
            includingPropertiesForKeys: [.isRegularFileKey],
            options: [.skipsHiddenFiles]
        ) else {
            return 0
        }
        var count = 0
        for case let file as URL in enumerator {
            let values = try? file.resourceValues(forKeys: [.isRegularFileKey])
            if values?.isRegularFile == true {
                count += 1
            }
        }
        return count
    }

    private nonisolated static func localFolderMetadata(for url: URL, folderName: String, fileCount: Int) -> [String: String] {
        DownloadMetadata.clean([
            "series": folderName,
            "category": "folder",
            "type": "local_folder",
            "download_mode": "copy",
            "host": "local",
            "site": "local",
            "filename": folderName,
            "basename": folderName,
            "slug": sourceSlug(from: url, fallback: folderName),
            "path": url.path,
            "url": url.absoluteString,
            "file_count": String(fileCount),
            "media_count": String(fileCount),
            "title": folderName
        ])
    }

    private nonisolated static func isLocalHTMLFile(_ url: URL) -> Bool {
        ["html", "htm", "xhtml"].contains(url.pathExtension.lowercased())
    }

    private nonisolated static func localHTMLString(from url: URL) -> String? {
        if let text = try? String(contentsOf: url, encoding: .utf8) {
            return text
        }
        if let text = try? String(contentsOf: url, encoding: .isoLatin1) {
            return text
        }
        return nil
    }

    private nonisolated static func isHTMLResponse(_ response: HTTPURLResponse?) -> Bool {
        let contentType = response?.value(forHTTPHeaderField: "Content-Type")?.lowercased() ?? ""
        return contentType.contains("text/html") || contentType.contains("application/xhtml+xml")
    }

    private nonisolated static func directSplitSegments(from response: HTTPURLResponse, directive: DirectSegmentDirective? = nil) -> [DirectSplitSegment]? {
        if directive?.enabled == false {
            return nil
        }

        let acceptsRanges = response.value(forHTTPHeaderField: "Accept-Ranges")?.lowercased() ?? ""
        guard acceptsRanges.contains("bytes") else { return nil }

        let encoding = response.value(forHTTPHeaderField: "Content-Encoding")?.lowercased().trimmed ?? ""
        guard encoding.isEmpty || encoding == "identity" else { return nil }

        guard let lengthText = response.value(forHTTPHeaderField: "Content-Length")?.trimmed,
              let contentLength = Int(lengthText),
              contentLength > 1 else {
            return nil
        }

        if let count = directive?.count, count > 1 {
            return directSplitSegments(contentLength: contentLength, count: count)
        }

        let chunkSize: Int
        if directive?.enabled == true, contentLength <= directSplitChunkSize {
            chunkSize = max(1, Int(ceil(Double(contentLength) / 2.0)))
        } else {
            guard contentLength > directSplitChunkSize else { return nil }
            chunkSize = directSplitChunkSize
        }
        return directSplitSegments(contentLength: contentLength, chunkSize: chunkSize)
    }

    private nonisolated static func directSplitSegments(contentLength: Int, count rawCount: Int) -> [DirectSplitSegment]? {
        let count = max(2, min(rawCount, contentLength))
        let chunkSize = max(1, Int(ceil(Double(contentLength) / Double(count))))
        return directSplitSegments(contentLength: contentLength, chunkSize: chunkSize)
    }

    private nonisolated static func directSplitSegments(contentLength: Int, chunkSize: Int) -> [DirectSplitSegment]? {
        var segments: [DirectSplitSegment] = []
        var lowerBound = 0
        var index = 1
        while lowerBound < contentLength {
            let upperBound = min(contentLength - 1, lowerBound + chunkSize - 1)
            segments.append(DirectSplitSegment(index: index, lowerBound: lowerBound, upperBound: upperBound))
            lowerBound = upperBound + 1
            index += 1
        }
        return segments.count > 1 ? segments : nil
    }

    private nonisolated static func directSegmentDirective(from comment: String) -> DirectSegmentDirective? {
        let lines = comment
            .replacingOccurrences(of: "\r\n", with: "\n")
            .replacingOccurrences(of: "\r", with: "\n")
            .components(separatedBy: "\n")

        var inSegmentBlock = false
        var directive = DirectSegmentDirective()
        var found = false

        for rawLine in lines {
            let line = rawLine.trimmed
            guard !line.isEmpty else {
                inSegmentBlock = false
                continue
            }

            let lower = line.lowercased()
            if lower.hasPrefix("segment:") || lower.hasPrefix("segment=") {
                found = true
                inSegmentBlock = true
                let separator = line.firstIndex(where: { $0 == ":" || $0 == "=" })!
                let value = String(line[line.index(after: separator)...]).trimmed
                applyDirectSegmentDirectiveValue(value, to: &directive)
                continue
            }

            if inSegmentBlock, line.contains("=") {
                applyDirectSegmentDirectiveValue(line, to: &directive)
            } else {
                inSegmentBlock = false
            }
        }

        return found ? directive.normalized : nil
    }

    private nonisolated static func applyDirectSegmentDirectiveValue(_ rawValue: String, to directive: inout DirectSegmentDirective) {
        let value = rawValue.trimmed
        guard !value.isEmpty else {
            directive.enabled = true
            return
        }

        let lower = value.lowercased()
        if ["0", "false", "no", "off", "none", "disable", "disabled"].contains(lower) {
            directive.enabled = false
            directive.count = nil
            return
        }
        if ["1", "true", "yes", "on", "enable", "enabled"].contains(lower) {
            directive.enabled = true
            return
        }
        if let count = Int(lower), count > 1 {
            directive.enabled = true
            directive.count = count
            return
        }

        let pairs = lower
            .split(separator: ",")
            .map { String($0).trimmed }
            .filter { !$0.isEmpty }
        for pair in pairs {
            guard let separator = pair.firstIndex(of: "=") else { continue }
            let key = String(pair[..<separator]).trimmed
            let value = String(pair[pair.index(after: separator)...]).trimmed
            if ["n", "count", "segments", "segment", "split"].contains(key),
               let count = Int(value),
               count > 1 {
                directive.enabled = true
                directive.count = count
            } else if ["enabled", "enable", "on"].contains(key) {
                applyDirectSegmentDirectiveValue(value, to: &directive)
            }
        }
    }

    private nonisolated static var directSplitChunkSize: Int {
        1_048_576
    }

    private nonisolated static func sourceSlug(from url: URL, fallback: String) -> String {
        let last = url.deletingPathExtension().lastPathComponent
        if !last.trimmed.isEmpty {
            return last.sanitizedFilename(maxLength: 120)
        }
        return fallback.sanitizedFilename(maxLength: 120)
    }

    private nonisolated static func responseFilename(from response: HTTPURLResponse?) -> String? {
        guard let response,
              let disposition = response.value(forHTTPHeaderField: "Content-Disposition")?.trimmed,
              !disposition.isEmpty else {
            return nil
        }
        return contentDispositionFilename(from: disposition)
    }

    private nonisolated static func contentDispositionFilename(from disposition: String) -> String? {
        let parts = contentDispositionParts(disposition)
        var fallback: String?
        var continuations: [Int: (value: String, encoded: Bool)] = [:]
        for rawPart in parts.dropFirst() {
            let part = rawPart.trimmed
            guard let separator = part.firstIndex(of: "=") else { continue }
            let key = String(part[..<separator]).trimmed.lowercased()
            var value = String(part[part.index(after: separator)...]).trimmed
            value = unquotedContentDispositionValue(value)

            if key == "filename*" {
                if let decoded = decodeRFC5987Filename(value), !decoded.isEmpty {
                    return filenameComponent(decoded, decodeLooseHeaderValue: false)
                }
            } else if key == "filename" {
                fallback = filenameComponent(value)
            } else if let continuation = filenameContinuationKey(key) {
                continuations[continuation.index] = (value, continuation.encoded)
            }
        }
        if let continued = filenameContinuationValue(continuations) {
            return continued
        }
        return fallback?.isEmpty == false ? fallback : nil
    }

    private nonisolated static func filenameContinuationKey(_ key: String) -> (index: Int, encoded: Bool)? {
        let prefix = "filename*"
        guard key.hasPrefix(prefix), key.count > prefix.count else { return nil }
        let suffixStart = key.index(key.startIndex, offsetBy: prefix.count)
        var suffix = String(key[suffixStart...])
        let encoded = suffix.hasSuffix("*")
        if encoded {
            suffix.removeLast()
        }
        guard let index = Int(suffix), index >= 0 else { return nil }
        return (index, encoded)
    }

    private nonisolated static func filenameContinuationValue(_ continuations: [Int: (value: String, encoded: Bool)]) -> String? {
        guard !continuations.isEmpty,
              let first = continuations[0] else {
            return nil
        }

        var values = [first.value]
        var hasEncodedPart = first.encoded
        var index = 1
        while let part = continuations[index] {
            values.append(part.value)
            hasEncodedPart = hasEncodedPart || part.encoded
            index += 1
        }

        let joined = values.joined()
        let decoded: String
        if hasEncodedPart {
            decoded = decodeRFC5987Filename(joined) ?? joined.removingPercentEncoding ?? joined
        } else {
            decoded = joined
        }

        let filename = filenameComponent(decoded, decodeLooseHeaderValue: !hasEncodedPart)
        return filename.isEmpty ? nil : filename
    }

    private nonisolated static func contentDispositionParts(_ disposition: String) -> [String] {
        var parts: [String] = []
        var current = ""
        var inQuotes = false
        var escaped = false

        for character in disposition {
            if escaped {
                current.append(character)
                escaped = false
                continue
            }
            if character == "\\" && inQuotes {
                current.append(character)
                escaped = true
                continue
            }
            if character == "\"" {
                inQuotes.toggle()
                current.append(character)
                continue
            }
            if character == ";", !inQuotes {
                parts.append(current)
                current.removeAll(keepingCapacity: true)
                continue
            }
            current.append(character)
        }
        parts.append(current)
        return parts
    }

    private nonisolated static func unquotedContentDispositionValue(_ value: String) -> String {
        var text = value.trimmed
        if text.count >= 2, text.first == "\"", text.last == "\"" {
            text.removeFirst()
            text.removeLast()
            var output = ""
            var escaped = false
            for character in text {
                if escaped {
                    output.append(character)
                    escaped = false
                } else if character == "\\" {
                    escaped = true
                } else {
                    output.append(character)
                }
            }
            if escaped {
                output.append("\\")
            }
            return output
        }
        if text.count >= 2, text.first == "'", text.last == "'" {
            text.removeFirst()
            text.removeLast()
        }
        return text
    }

    private nonisolated static func decodeRFC5987Filename(_ value: String) -> String? {
        let pieces = value.split(separator: "'", maxSplits: 2, omittingEmptySubsequences: false).map(String.init)
        let charset = pieces.count == 3 ? pieces[0] : "UTF-8"
        let encoded = pieces.count == 3 ? pieces[2] : value
        guard let data = percentDecodedHeaderData(encoded),
              let stringEncoding = headerStringEncoding(for: charset),
              let decoded = String(data: data, encoding: stringEncoding) else {
            return encoded.removingPercentEncoding ?? encoded
        }
        return decoded
    }

    private nonisolated static func percentDecodedHeaderData(_ value: String) -> Data? {
        let bytes = Array(value.utf8)
        var output = Data()
        var index = 0

        while index < bytes.count {
            let byte = bytes[index]
            if byte == 37,
               index + 2 < bytes.count,
               let high = hexValue(bytes[index + 1]),
               let low = hexValue(bytes[index + 2]) {
                output.append(high << 4 | low)
                index += 3
                continue
            }
            output.append(byte)
            index += 1
        }

        return output
    }

    private nonisolated static func filenameComponent(_ value: String, decodeLooseHeaderValue: Bool = true) -> String {
        let decoded = decodeLooseHeaderValue ? looseDecodedHeaderFilename(value) : value
        let normalized = decoded.replacingOccurrences(of: "\\", with: "/")
        let last = normalized.split(separator: "/", omittingEmptySubsequences: true).last.map(String.init) ?? normalized
        return last.trimmed
    }

    private nonisolated static func looseDecodedHeaderFilename(_ value: String) -> String {
        let percentDecoded = value.removingPercentEncoding ?? value
        return decodeRFC2047EncodedWords(in: percentDecoded) ?? percentDecoded
    }

    private nonisolated static func decodeRFC2047EncodedWords(in value: String) -> String? {
        guard value.contains("=?"),
              let regex = try? NSRegularExpression(pattern: #"=\?([^?]+)\?([bBqQ])\?([^?]*)\?="#) else {
            return nil
        }
        let matches = regex.matches(in: value, range: NSRange(value.startIndex..<value.endIndex, in: value))
        guard !matches.isEmpty else { return nil }

        var output = ""
        var cursor = value.startIndex
        var decodedAny = false
        var previousDecodedWord = false

        for match in matches {
            guard let fullRange = Range(match.range(at: 0), in: value) else { continue }
            let separator = value[cursor..<fullRange.lowerBound]
            let original = String(value[fullRange])
            if let charsetRange = Range(match.range(at: 1), in: value),
               let encodingRange = Range(match.range(at: 2), in: value),
               let payloadRange = Range(match.range(at: 3), in: value),
               let decoded = decodeRFC2047Word(
                charset: String(value[charsetRange]),
                encoding: String(value[encodingRange]),
                payload: String(value[payloadRange])
               ) {
                if !(previousDecodedWord && isRFC2047LinearWhitespace(separator)) {
                    output += String(separator)
                }
                output += decoded
                decodedAny = true
                previousDecodedWord = true
            } else {
                output += String(separator)
                output += original
                previousDecodedWord = false
            }
            cursor = fullRange.upperBound
        }

        output += String(value[cursor...])
        return decodedAny ? output : nil
    }

    private nonisolated static func isRFC2047LinearWhitespace(_ value: Substring) -> Bool {
        value.allSatisfy { character in
            character == " " || character == "\t" || character == "\r" || character == "\n"
        }
    }

    private nonisolated static func decodeRFC2047Word(charset: String, encoding: String, payload: String) -> String? {
        let data: Data?
        if encoding.caseInsensitiveCompare("B") == .orderedSame {
            data = Data(base64Encoded: payload)
        } else if encoding.caseInsensitiveCompare("Q") == .orderedSame {
            data = decodeRFC2047QPayload(payload)
        } else {
            data = nil
        }
        guard let data else { return nil }

        let normalizedCharset = charset
            .trimmingCharacters(in: .whitespacesAndNewlines)
            .lowercased()
            .replacingOccurrences(of: "_", with: "-")
        guard let stringEncoding = headerStringEncoding(forNormalizedCharset: normalizedCharset) else { return nil }
        return String(data: data, encoding: stringEncoding)
    }

    private nonisolated static func headerStringEncoding(for charset: String) -> String.Encoding? {
        let normalizedCharset = charset
            .trimmingCharacters(in: .whitespacesAndNewlines)
            .lowercased()
            .replacingOccurrences(of: "_", with: "-")
        return headerStringEncoding(forNormalizedCharset: normalizedCharset)
    }

    private nonisolated static func headerStringEncoding(forNormalizedCharset normalizedCharset: String) -> String.Encoding? {
        switch normalizedCharset {
        case "utf-8", "utf8":
            return .utf8
        case "us-ascii", "ascii":
            return .ascii
        case "iso-8859-1", "latin-1", "latin1":
            return .isoLatin1
        case "windows-1252", "cp1252":
            return .windowsCP1252
        case "shift-jis", "sjis", "shiftjis", "windows-31j", "cp932", "ms932":
            return .shiftJIS
        case "euc-jp", "eucjp":
            return coreFoundationHeaderStringEncoding(CFStringEncoding(CFStringEncodings.EUC_JP.rawValue))
        case "euc-kr", "euckr", "ks-c-5601-1987", "ks-c5601", "ksc5601":
            return coreFoundationHeaderStringEncoding(CFStringEncoding(CFStringEncodings.EUC_KR.rawValue))
        case "cp949", "ms949", "windows-949", "uhc":
            return coreFoundationHeaderStringEncoding(CFStringEncoding(0x0422))
        default:
            return nil
        }
    }

    private nonisolated static func coreFoundationHeaderStringEncoding(_ encoding: CFStringEncoding) -> String.Encoding {
        String.Encoding(rawValue: CFStringConvertEncodingToNSStringEncoding(encoding))
    }

    private nonisolated static func decodeRFC2047QPayload(_ payload: String) -> Data {
        let bytes = Array(payload.utf8)
        var output = Data()
        var index = 0

        while index < bytes.count {
            let byte = bytes[index]
            if byte == 95 {
                output.append(32)
                index += 1
                continue
            }
            if byte == 61,
               index + 2 < bytes.count,
               let high = hexValue(bytes[index + 1]),
               let low = hexValue(bytes[index + 2]) {
                output.append(high << 4 | low)
                index += 3
                continue
            }
            output.append(byte)
            index += 1
        }

        return output
    }

    private nonisolated static func hexValue(_ byte: UInt8) -> UInt8? {
        switch byte {
        case 48...57:
            return byte - 48
        case 65...70:
            return byte - 55
        case 97...102:
            return byte - 87
        default:
            return nil
        }
    }

    private nonisolated static func queryFilenameHint(from url: URL) -> String? {
        let items = URLComponents(url: url, resolvingAgainstBaseURL: false)?.queryItems ?? []
        for key in ["response-content-disposition", "content-disposition", "content_disposition"] {
            guard let value = items.first(where: { $0.name.lowercased() == key })?.value?.trimmed,
                  !value.isEmpty,
                  let filename = contentDispositionFilename(from: value),
                  !filename.isEmpty else {
                continue
            }
            return filename
        }

        for key in ["filename", "file", "download", "name", "title", "fn"] {
            guard let value = items.first(where: { $0.name.lowercased() == key })?.value?.trimmed,
                  !value.isEmpty else {
                continue
            }

            let clean = queryFilenameCandidate(from: value)
            if !clean.isEmpty {
                return clean
            }
        }
        return nil
    }

    private nonisolated static func queryFilenameCandidate(from value: String) -> String {
        let normalizedValue = value.replacingOccurrences(of: "\\", with: "/")
        let candidate: String
        if let nested = URL(string: normalizedValue),
           nested.scheme != nil,
           !nested.lastPathComponent.trimmed.isEmpty {
            candidate = nested.lastPathComponent
        } else if normalizedValue.contains("/") {
            candidate = normalizedValue.split(separator: "/", omittingEmptySubsequences: true).last.map(String.init) ?? normalizedValue
        } else {
            candidate = normalizedValue
        }

        return candidate
            .split(separator: "?", maxSplits: 1, omittingEmptySubsequences: true)
            .first
            .map(String.init)?
            .split(separator: "#", maxSplits: 1, omittingEmptySubsequences: true)
            .first
            .map(String.init)?
            .trimmed ?? ""
    }

    private func downloadWithYTDLP(_ url: URL, jobIndex: Int) async throws {
        guard jobs.indices.contains(jobIndex) else { return }
        var url = url
        var title = url.host ?? "yt-dlp media"
        if let hooked = try await runSyntheticPythonDownloadHooks(
            sourceURL: url,
            title: title,
            metadata: YTDLPBridge.sourceMetadata(for: url).merging(["handler": "yt-dlp"]) { current, _ in current },
            jobIndex: jobIndex
        ) {
            if let hookedURL = URL(string: hooked.sourceURL.trimmed), !hooked.sourceURL.trimmed.isEmpty {
                url = hookedURL
            }
            if !hooked.title.trimmed.isEmpty {
                title = hooked.title.trimmed
            }
        }
        let root = try outputRoot(for: url)
        let audioFormat = Self.ytdlpAudioFormat(from: jobs[jobIndex].metadata)
        let jobID = jobs[jobIndex].id
        let processControl = ExternalProcessControl()
        ytdlpRuntimeProcesses[jobID] = processControl
        ytdlpProgressStates[jobID] = YTDLPJobProgressState()
        defer {
            ytdlpRuntimeProcesses.removeValue(forKey: jobID)
            ytdlpProgressStates.removeValue(forKey: jobID)
            if let currentIndex = jobs.firstIndex(where: { $0.id == jobID }) {
                jobs[currentIndex].metadata["ytdlp_active"] = "false"
                jobs[currentIndex].metadata["transfer_active"] = "false"
            }
        }

        jobs[jobIndex].title = title
        jobs[jobIndex].total = 1
        jobs[jobIndex].completed = 0
        jobs[jobIndex].progress = 0
        jobs[jobIndex].status = .downloading
        jobs[jobIndex].message = audioFormat == nil ? "Running yt-dlp" : "Extracting MP3 audio"
        jobs[jobIndex].metadata["tool"] = "yt-dlp"
        jobs[jobIndex].metadata["handler"] = SiteRuleHandler.ytdlp.rawValue
        jobs[jobIndex].metadata["ytdlp_active"] = "true"
        jobs[jobIndex].metadata["transfer_active"] = "false"
        persistQueue()

        let rawResult = try await ytdlpBridge.download(
            url: url,
            to: root,
            headers: requestOptions(for: url),
            youtubePreferredLanguage: youtubePreferredLanguage,
            youtubePreferredResolution: youtubePreferredResolution,
            youtubePreferredAudioLanguage: youtubePreferredAudioLanguage,
            soopPreferredResolution: soopPreferredResolution,
            extractAudioFormat: audioFormat,
            writeYouTubeThumbnail: youtubeDownloadThumbnail,
            reverseYouTubePlaylist: youtubeReversePlaylist,
            numberPlaylistFiles: numberPlaylistFiles,
            writeYouTubeAutoSubtitles: youtubeDownloadAutoSubtitles,
            youtubeSubtitleLanguages: youtubeSubtitleLanguages,
            embedYouTubeChapters: youtubeEmbedChapters,
            youtubeVideoCodecSort: youtubeVideoCodecSort,
            preferYouTubeEnhancedBitrate: youtubePreferEnhancedBitrate,
            useYouTubeUploadDateForFileModificationTime: youtubeUseUploadDateForFileModificationTime,
            processControl: processControl,
            progressHandler: { [weak self] update in
                Task { @MainActor [weak self] in
                    self?.applyYTDLPRuntimeUpdate(update, jobID: jobID)
                }
            }
        )
        let result = try applyYTDLPFileTemplate(to: rawResult, sourceURL: url)
        let output = result.downloadedItems.count == 1 ? result.downloadedItems[0] : result.outputDirectory

        if jobs.indices.contains(jobIndex) {
            jobs[jobIndex].title = output.lastPathComponent
            jobs[jobIndex].outputPath = output.path
            var metadata = Self.ytdlpMetadata(for: url, title: output.lastPathComponent, result: result)
            if let audioFormat {
                metadata["media_request"] = "audio"
                metadata["audio_format"] = audioFormat
                metadata["category"] = "audio"
            }
            jobs[jobIndex].metadata = Self.resolvedMetadataPreservingRuntimeState(
                metadata,
                previous: jobs[jobIndex].metadata
            )
            jobs[jobIndex].metadata["ytdlp_active"] = "false"
            jobs[jobIndex].metadata["transfer_active"] = "false"
            if result.wasInterrupted {
                jobs[jobIndex].metadata["was_live"] = "true"
                jobs[jobIndex].metadata["live_active"] = "false"
                jobs[jobIndex].metadata["live_polling"] = "false"
                jobs[jobIndex].metadata["live_done"] = "true"
                jobs[jobIndex].metadata["live_end_reason"] = "stopped"
                jobs[jobIndex].metadata["live_partial_output"] = "true"
                jobs[jobIndex].metadata.removeValue(forKey: Self.liveStopRequestedMetadataKey)
                jobs[jobIndex].metadata.removeValue(forKey: "ytdlp_stop_requested")
            }
            jobs[jobIndex].completed = 1
            jobs[jobIndex].progress = 1
            jobs[jobIndex].status = .finished
            jobs[jobIndex].message = result.wasInterrupted ? "Recording stopped" : "Done"
            await completeJob(at: jobIndex)
        }
    }

    private func applyYTDLPRuntimeUpdate(_ update: YTDLPRuntimeUpdate, jobID: UUID) {
        guard let index = jobs.firstIndex(where: { $0.id == jobID }),
              jobs[index].status == .downloading else { return }

        var progressState = ytdlpProgressStates[jobID] ?? YTDLPJobProgressState()
        let snapshot = progressState.apply(update)
        ytdlpProgressStates[jobID] = progressState

        if let isLive = update.isLive {
            jobs[index].metadata["ytdlp_live"] = isLive ? "true" : "false"
            if isLive {
                jobs[index].metadata["live"] = "true"
                jobs[index].metadata["is_live"] = "true"
                jobs[index].metadata["was_live"] = "true"
                jobs[index].metadata["live_active"] = "true"
                jobs[index].metadata["live_polling"] = "false"
            }
            if let liveStatus = update.liveStatus {
                jobs[index].metadata["live_status"] = liveStatus
            }
            if let title = update.title?.trimmed, !title.isEmpty {
                jobs[index].title = title
            }
            persistQueue()
        }

        if let downloaded = snapshot.downloadedBytes, downloaded >= 0 {
            jobs[index].metadata["downloaded_bytes"] = String(downloaded)
        }
        if let total = snapshot.totalBytes, total > 0 {
            jobs[index].metadata["total_bytes"] = String(total)
        }
        if let speed = update.speedBytesPerSecond, speed >= 0 {
            jobs[index].metadata["speed_bytes_per_second"] = String(speed)
        }
        if let eta = update.etaSeconds, eta >= 0 {
            jobs[index].metadata["eta_seconds"] = String(eta)
        }
        if let itemFraction = snapshot.itemFraction {
            jobs[index].metadata["transfer_item_fraction"] = String(itemFraction)
        }
        jobs[index].metadata["transfer_item_index"] = String(snapshot.playlistIndex)
        jobs[index].metadata["transfer_item_count"] = String(snapshot.playlistCount)
        if let formatID = update.formatID {
            jobs[index].metadata["transfer_format_id"] = formatID
        }
        if let fraction = snapshot.fraction {
            let bounded = min(0.995, max(0, fraction))
            jobs[index].progress = max(jobs[index].progress, bounded)
            jobs[index].metadata["transfer_fraction"] = String(fraction)
        }
        if snapshot.playlistCount > 1 {
            jobs[index].total = snapshot.playlistCount
            jobs[index].completed = max(
                jobs[index].completed,
                min(snapshot.playlistCount, snapshot.playlistIndex - 1)
            )
        }

        guard update.downloadedBytes != nil || update.speedBytesPerSecond != nil ||
                update.fraction != nil || update.transferStatus != nil else {
            return
        }
        jobs[index].metadata["transfer_active"] = "true"
        jobs[index].metadata["last_transfer_at"] = ISO8601DateFormatter().string(from: Date())
        let live = Self.liveHLSMetadataIsTrue(jobs[index].metadata["ytdlp_live"])
        let base = AppLocalization.text(
            live ? "Recording YouTube live" : "Downloading with yt-dlp",
            language: interfaceLanguage
        )
        if let downloaded = snapshot.downloadedBytes, downloaded > 0 {
            jobs[index].message = "\(base) · \(Self.byteCountText(downloaded))"
        } else {
            jobs[index].message = base
        }
    }

    private func downloadWithCustomCommand(_ url: URL, rule: SiteRule, jobIndex: Int) async throws {
        guard jobs.indices.contains(jobIndex) else { return }
        var url = url
        if let hooked = try await runSyntheticPythonDownloadHooks(
            sourceURL: url,
            title: rule.name,
            metadata: ["type": "command", "handler": rule.handler.rawValue, "rule": rule.name],
            jobIndex: jobIndex
        ), let hookedURL = URL(string: hooked.sourceURL.trimmed), !hooked.sourceURL.trimmed.isEmpty {
            url = hookedURL
        }
        let root = try outputRoot(for: url)

        jobs[jobIndex].title = rule.name
        jobs[jobIndex].total = 1
        jobs[jobIndex].completed = 0
        jobs[jobIndex].progress = 0
        jobs[jobIndex].status = .downloading
        jobs[jobIndex].message = "Running \(rule.name)"
        persistQueue()

        let rawResult = try await customCommandBridge.run(url: url, rule: rule, root: root, headers: requestOptions(for: url))
        let rawOutput = rawResult.outputItems.count == 1 ? rawResult.outputItems[0] : rawResult.outputDirectory
        let declaredTitle = [rawResult.manifestTitle, rawResult.manifestMetadata["title"]]
            .compactMap { $0?.trimmed }
            .first { !$0.isEmpty }
        let title = declaredTitle ?? rawOutput.lastPathComponent
        let folderedResult = try applyCustomCommandFolderTemplate(to: rawResult, root: root, sourceURL: url, title: title, rule: rule)
        let localResult = try applyCustomCommandFileTemplate(to: folderedResult, sourceURL: url, title: title, rule: rule)
        let result = try await downloadCustomCommandRemoteAssets(localResult, sourceURL: url, title: title, rule: rule, jobIndex: jobIndex)
        let output = result.outputItems.count == 1 ? result.outputItems[0] : result.outputDirectory

        if jobs.indices.contains(jobIndex) {
            jobs[jobIndex].title = title
            jobs[jobIndex].outputPath = output.path
            jobs[jobIndex].metadata = Self.resolvedMetadataPreservingRuntimeState(
                Self.customCommandMetadata(for: url, rule: rule, title: title, result: result),
                previous: jobs[jobIndex].metadata
            )
            jobs[jobIndex].completed = 1
            jobs[jobIndex].progress = 1
            jobs[jobIndex].status = .finished
            jobs[jobIndex].message = "Done"
            await completeJob(at: jobIndex)
        }
    }

    private func downloadWithAria2(_ url: URL, jobIndex: Int) async throws {
        guard jobs.indices.contains(jobIndex) else { return }
        var url = url
        var title = url.scheme?.lowercased() == "magnet" ? "Magnet" : url.lastPathComponent
        if let hooked = try await runSyntheticPythonDownloadHooks(
            sourceURL: url,
            title: title.isEmpty ? "Torrent" : title,
            filename: url.lastPathComponent,
            metadata: ["type": url.scheme?.lowercased() == "magnet" ? "magnet" : "torrent", "handler": "aria2"],
            jobIndex: jobIndex
        ) {
            if let hookedURL = URL(string: hooked.sourceURL.trimmed), !hooked.sourceURL.trimmed.isEmpty {
                url = hookedURL
            }
            if !hooked.title.trimmed.isEmpty {
                title = hooked.title.trimmed
            }
        }
        let root = try outputRoot(for: url)
        let jobID = jobs[jobIndex].id
        let processControl = ExternalProcessControl()
        let rpcSession = Aria2RPCSession.make()
        aria2RuntimeProcesses[jobID] = processControl
        if let rpcSession {
            aria2RuntimeRPCSessions[jobID] = rpcSession
        }
        aria2RuntimePausedJobIDs.remove(jobID)
        defer {
            cleanupAria2RuntimeControl(for: jobID)
        }

        jobs[jobIndex].title = title.isEmpty ? "Torrent" : title
        jobs[jobIndex].total = 1
        jobs[jobIndex].completed = 0
        jobs[jobIndex].progress = 0
        jobs[jobIndex].status = .downloading
        jobs[jobIndex].message = "Running aria2c"
        let options = Self.aria2Options(base: aria2OptionsForUse(), comment: jobs[jobIndex].comment)
        jobs[jobIndex].metadata["tool"] = "aria2c"
        jobs[jobIndex].metadata["handler"] = "aria2"
        jobs[jobIndex].metadata["aria2_runtime_paused"] = "false"
        jobs[jobIndex].metadata["aria2_runtime_rpc"] = rpcSession == nil ? "false" : "true"
        jobs[jobIndex].metadata["selected_files"] = options.selectedFiles
        jobs[jobIndex].metadata["runtime_selected_files"] = options.selectedFiles
        jobs[jobIndex].metadata["max_download_limit"] = options.maxDownloadLimit
        jobs[jobIndex].metadata["max_upload_limit"] = options.maxUploadLimit
        jobs[jobIndex].metadata["runtime_max_download_limit"] = options.maxDownloadLimit
        jobs[jobIndex].metadata["runtime_max_upload_limit"] = options.maxUploadLimit
        jobs[jobIndex].metadata["seed_time_minutes"] = options.seedTimeMinutes
        jobs[jobIndex].metadata["seed_ratio"] = options.seedRatio
        jobs[jobIndex].metadata["runtime_seed_time_minutes"] = options.seedTimeMinutes
        jobs[jobIndex].metadata["runtime_seed_ratio"] = options.seedRatio
        persistQueue()
        let result = try await aria2Bridge.download(
            url: url,
            to: root,
            headers: requestOptions(for: url),
            options: options,
            processControl: processControl,
            rpcSession: rpcSession
        )
        let output = result.downloadedItems.count == 1 ? result.downloadedItems[0] : result.outputDirectory

        if jobs.indices.contains(jobIndex) {
            let runtimeDownloadLimit = jobs[jobIndex].metadata["runtime_max_download_limit"] ?? options.maxDownloadLimit
            let runtimeUploadLimit = jobs[jobIndex].metadata["runtime_max_upload_limit"] ?? options.maxUploadLimit
            let runtimeSelectedFiles = jobs[jobIndex].metadata["runtime_selected_files"] ?? options.selectedFiles
            let runtimeSeedTime = jobs[jobIndex].metadata["runtime_seed_time_minutes"] ?? options.seedTimeMinutes
            let runtimeSeedRatio = jobs[jobIndex].metadata["runtime_seed_ratio"] ?? options.seedRatio
            let runtimeSeedError = jobs[jobIndex].metadata["aria2_runtime_seed_error"] ?? ""
            let previewFileCount = jobs[jobIndex].metadata["aria2_file_count"] ?? ""
            let previewFileListError = jobs[jobIndex].metadata["aria2_file_list_error"] ?? ""
            let previewPeerCount = jobs[jobIndex].metadata["aria2_peer_count"] ?? ""
            let previewPeerError = jobs[jobIndex].metadata["aria2_runtime_peer_error"] ?? ""
            var metadata = Self.aria2Metadata(for: url, title: output.lastPathComponent, result: result, options: options)
            metadata["selected_files"] = runtimeSelectedFiles
            metadata["runtime_selected_files"] = runtimeSelectedFiles
            metadata["runtime_max_download_limit"] = runtimeDownloadLimit
            metadata["runtime_max_upload_limit"] = runtimeUploadLimit
            metadata["seed_time_minutes"] = runtimeSeedTime
            metadata["seed_ratio"] = runtimeSeedRatio
            metadata["runtime_seed_time_minutes"] = runtimeSeedTime
            metadata["runtime_seed_ratio"] = runtimeSeedRatio
            if !runtimeSeedError.isEmpty {
                metadata["aria2_runtime_seed_error"] = runtimeSeedError
            }
            if !previewFileCount.isEmpty {
                metadata["aria2_file_count"] = previewFileCount
            }
            if !previewFileListError.isEmpty {
                metadata["aria2_file_list_error"] = previewFileListError
            }
            if !previewPeerCount.isEmpty {
                metadata["aria2_peer_count"] = previewPeerCount
            }
            if !previewPeerError.isEmpty {
                metadata["aria2_runtime_peer_error"] = previewPeerError
            }
            jobs[jobIndex].title = output.lastPathComponent
            jobs[jobIndex].outputPath = output.path
            jobs[jobIndex].metadata = Self.resolvedMetadataPreservingRuntimeState(
                DownloadMetadata.clean(metadata),
                previous: jobs[jobIndex].metadata
            )
            jobs[jobIndex].completed = 1
            jobs[jobIndex].progress = 1
            jobs[jobIndex].status = .finished
            jobs[jobIndex].message = "Done"
            await completeJob(at: jobIndex)
        }
    }

    private func applyYTDLPFileTemplate(to result: YTDLPResult, sourceURL: URL) throws -> YTDLPResult {
        let metadata = DownloadMetadata.clean(
            YTDLPBridge.sourceMetadata(for: sourceURL)
                .merging(result.infoMetadata) { _, infoValue in infoValue }
        )
        let template = effectiveFileNameTemplate(for: sourceURL, metadata: metadata)
        guard !template.isEmpty, !result.downloadedItems.isEmpty else {
            return result
        }

        let total = result.downloadedItems.count
        let renamed = try result.downloadedItems.enumerated().map { offset, item in
            let original = item.lastPathComponent
            let fallbackTitle = (original as NSString).deletingPathExtension
            let title = metadata["media_title"] ?? metadata["title"] ?? fallbackTitle
            let outputName = templatedFileName(
                original: original,
                title: title,
                sourceURL: sourceURL,
                index: offset + 1,
                total: total,
                metadata: metadata
            )
            guard outputName != original else {
                return item
            }

            let destination = AppPaths.uniqueFileURL(in: item.deletingLastPathComponent(), filename: outputName)
            try FileManager.default.moveItem(at: item, to: destination)
            return destination
        }

        return YTDLPResult(
            outputDirectory: result.outputDirectory,
            downloadedItems: renamed,
            infoMetadata: result.infoMetadata,
            wasInterrupted: result.wasInterrupted
        )
    }

    private func applyCustomCommandFolderTemplate(to result: CustomCommandResult, root: URL, sourceURL: URL, title: String, rule: SiteRule) throws -> CustomCommandResult {
        let template = folderNameTemplate.trimmed
        let rawFolderName = result.manifestFolderName?.trimmed
        let explicitFolderName = rawFolderName?.isEmpty == false ? rawFolderName : nil
        guard !template.isEmpty || explicitFolderName != nil else {
            return result
        }

        var metadata = result.manifestMetadata
        metadata["title"] = metadata["title"] ?? title
        metadata["series"] = metadata["series"] ?? title
        metadata["tool"] = "custom-command"
        metadata["handler"] = rule.handler.rawValue
        metadata["rule"] = rule.name
        metadata["rule_host"] = rule.hostSuffix
        metadata["rule_pattern"] = rule.urlPattern ?? ""

        let targetName: String
        if !template.isEmpty {
            let context = nameTemplateContext(
                title: title,
                sourceURL: sourceURL,
                filename: explicitFolderName ?? result.outputDirectory.lastPathComponent,
                index: nil,
                total: result.outputItems.count,
                metadata: metadata
            )
            targetName = NameTemplate.folderName(
                template: template,
                fallback: explicitFolderName ?? result.outputDirectory.lastPathComponent,
                context: context
            )
        } else {
            targetName = (explicitFolderName ?? result.outputDirectory.lastPathComponent).sanitizedFilename(maxLength: 120)
        }

        guard !targetName.trimmed.isEmpty,
              targetName != result.outputDirectory.lastPathComponent else {
            return result
        }

        let oldDirectory = result.outputDirectory
        let oldResolved = oldDirectory.resolvingSymlinksInPath()
        let oldPrefix = oldResolved.path.hasSuffix("/") ? oldResolved.path : oldResolved.path + "/"
        let destination = AppPaths.uniqueDirectoryURL(in: root, name: targetName)
        try AppPaths.ensureDirectory(destination.deletingLastPathComponent())
        let remappedItems = result.outputItems.map { item -> URL in
            let resolved = item.resolvingSymlinksInPath()
            guard resolved.path.hasPrefix(oldPrefix) else {
                return destination.appendingPathComponent(item.lastPathComponent)
            }
            let relativePath = String(resolved.path.dropFirst(oldPrefix.count))
            return destination.appendingPathComponent(relativePath)
        }

        try FileManager.default.moveItem(at: oldDirectory, to: destination)
        return CustomCommandResult(
            outputDirectory: destination,
            outputItems: remappedItems,
            remoteAssets: result.remoteAssets,
            remoteVideoAssets: result.remoteVideoAssets,
            remoteAudioAssets: result.remoteAudioAssets,
            remotePackageMode: result.remotePackageMode,
            manifestTitle: result.manifestTitle,
            manifestFolderName: result.manifestFolderName,
            manifestMetadata: result.manifestMetadata
        )
    }

    private func applyCustomCommandFileTemplate(to result: CustomCommandResult, sourceURL: URL, title: String, rule: SiteRule) throws -> CustomCommandResult {
        var metadata = result.manifestMetadata
        metadata["title"] = metadata["title"] ?? title
        metadata["series"] = metadata["series"] ?? title
        metadata["tool"] = "custom-command"
        metadata["handler"] = rule.handler.rawValue
        metadata["rule"] = rule.name
        metadata["rule_host"] = rule.hostSuffix
        metadata["rule_pattern"] = rule.urlPattern ?? ""
        let template = effectiveFileNameTemplate(for: sourceURL, metadata: metadata)
        guard !template.isEmpty, !result.outputItems.isEmpty else {
            return result
        }

        let total = result.outputItems.count
        let renamed = try result.outputItems.enumerated().map { offset, item in
            let outputName = templatedFileName(
                original: item.lastPathComponent,
                title: title,
                sourceURL: sourceURL,
                index: offset + 1,
                total: total,
                metadata: metadata
            )
            guard outputName != item.lastPathComponent else {
                return item
            }

            let destination = AppPaths.uniqueFileURL(in: item.deletingLastPathComponent(), filename: outputName)
            try FileManager.default.moveItem(at: item, to: destination)
            return destination
        }

        return CustomCommandResult(
            outputDirectory: result.outputDirectory,
            outputItems: renamed,
            remoteAssets: result.remoteAssets,
            remoteVideoAssets: result.remoteVideoAssets,
            remoteAudioAssets: result.remoteAudioAssets,
            remotePackageMode: result.remotePackageMode,
            manifestTitle: result.manifestTitle,
            manifestFolderName: result.manifestFolderName,
            manifestMetadata: result.manifestMetadata
        )
    }

    private func customCommandTemplateMetadata(for result: CustomCommandResult, title: String, rule: SiteRule) -> [String: String] {
        var metadata = result.manifestMetadata
        metadata["title"] = metadata["title"] ?? title
        metadata["series"] = metadata["series"] ?? title
        metadata["tool"] = "custom-command"
        metadata["handler"] = rule.handler.rawValue
        metadata["rule"] = rule.name
        metadata["rule_host"] = rule.hostSuffix
        metadata["rule_pattern"] = rule.urlPattern ?? ""
        return DownloadMetadata.clean(metadata)
    }

    private func downloadCustomCommandRemoteAssets(_ result: CustomCommandResult, sourceURL: URL, title: String, rule: SiteRule, jobIndex: Int) async throws -> CustomCommandResult {
        guard !result.remoteAssets.isEmpty || !result.remoteVideoAssets.isEmpty || !result.remoteAudioAssets.isEmpty else {
            return result
        }

        switch result.remotePackageMode {
        case .files:
            return try await downloadCustomCommandRemoteFiles(result, sourceURL: sourceURL, title: title, rule: rule, jobIndex: jobIndex)
        case .concatenate(let outputFilename):
            return try await downloadCustomCommandRemoteConcatenate(result, outputFilename: outputFilename, sourceURL: sourceURL, title: title, rule: rule, jobIndex: jobIndex)
        case .mux(let outputFilename):
            return try await downloadCustomCommandRemoteMux(result, outputFilename: outputFilename, sourceURL: sourceURL, title: title, rule: rule, jobIndex: jobIndex)
        }
    }

    private func downloadCustomCommandRemoteFiles(_ result: CustomCommandResult, sourceURL: URL, title: String, rule: SiteRule, jobIndex: Int) async throws -> CustomCommandResult {
        let localCount = result.outputItems.count
        let total = localCount + result.remoteAssets.count
        let metadata = customCommandTemplateMetadata(for: result, title: title, rule: rule)
        let assets = result.remoteAssets.enumerated().map { offset, asset -> ResolvedAsset in
            var copy = asset
            let outputName = templatedFileName(
                original: asset.filename,
                title: title,
                sourceURL: sourceURL,
                index: localCount + offset + 1,
                total: total,
                metadata: metadata
            )
            copy.filename = outputName
            return assetWithHeaderRules(copy)
        }

        if jobs.indices.contains(jobIndex) {
            jobs[jobIndex].title = title
            jobs[jobIndex].metadata = Self.resolvedMetadataPreservingRuntimeState(
                Self.customCommandMetadata(for: sourceURL, rule: rule, title: title, result: result),
                previous: jobs[jobIndex].metadata
            )
            jobs[jobIndex].total = assets.count
            jobs[jobIndex].completed = 0
            jobs[jobIndex].progress = 0
            jobs[jobIndex].message = "Downloading \(assets.count) manifest assets"
            jobs[jobIndex].outputPath = result.outputDirectory.path
            persistQueue()
        }

        let downloadedItems = try await downloadAssets(assets, to: result.outputDirectory, jobIndex: jobIndex)
        return CustomCommandResult(
            outputDirectory: result.outputDirectory,
            outputItems: result.outputItems + downloadedItems,
            remoteAssets: [],
            remoteVideoAssets: [],
            remoteAudioAssets: [],
            remotePackageMode: .files,
            manifestTitle: result.manifestTitle,
            manifestFolderName: result.manifestFolderName,
            manifestMetadata: result.manifestMetadata
        )
    }

    private func downloadCustomCommandRemoteConcatenate(_ result: CustomCommandResult, outputFilename: String, sourceURL: URL, title: String, rule: SiteRule, jobIndex: Int) async throws -> CustomCommandResult {
        let metadata = customCommandTemplateMetadata(for: result, title: title, rule: rule)
        let outputName = templatedFileName(
            original: outputFilename,
            title: title,
            sourceURL: sourceURL,
            index: nil,
            total: result.remoteAssets.count,
            metadata: metadata
        )
        let output = AppPaths.uniqueFileURL(in: result.outputDirectory, filename: outputName)
        let tempFolder = result.outputDirectory.appendingPathComponent(".manifest-concat-\(UUID().uuidString)", isDirectory: true)
        try AppPaths.ensureDirectory(tempFolder)

        let assets = result.remoteAssets.enumerated().map { offset, asset -> ResolvedAsset in
            var copy = asset
            let safeName = asset.filename.sanitizedFilename(maxLength: 150)
            copy.filename = String(format: "%05d-%@", offset + 1, safeName)
            return assetWithHeaderRules(copy)
        }

        if jobs.indices.contains(jobIndex) {
            jobs[jobIndex].title = title
            jobs[jobIndex].metadata = Self.resolvedMetadataPreservingRuntimeState(
                Self.customCommandMetadata(for: sourceURL, rule: rule, title: title, result: result),
                previous: jobs[jobIndex].metadata
            )
            jobs[jobIndex].total = assets.count
            jobs[jobIndex].completed = 0
            jobs[jobIndex].progress = 0
            jobs[jobIndex].message = "Downloading \(assets.count) manifest segments"
            jobs[jobIndex].outputPath = result.outputDirectory.path
            persistQueue()
        }

        try await downloadAndConcatenate(assets, tempFolder: tempFolder, output: output, jobIndex: jobIndex)
        return CustomCommandResult(
            outputDirectory: result.outputDirectory,
            outputItems: result.outputItems + [output],
            remoteAssets: [],
            remoteVideoAssets: [],
            remoteAudioAssets: [],
            remotePackageMode: result.remotePackageMode,
            manifestTitle: result.manifestTitle,
            manifestFolderName: result.manifestFolderName,
            manifestMetadata: result.manifestMetadata
        )
    }

    private func downloadCustomCommandRemoteMux(_ result: CustomCommandResult, outputFilename: String, sourceURL: URL, title: String, rule: SiteRule, jobIndex: Int) async throws -> CustomCommandResult {
        guard !result.remoteVideoAssets.isEmpty else {
            throw NativeDownloadError.unsupported("Custom command manifest mux mode requires video assets.")
        }
        guard !result.remoteAudioAssets.isEmpty else {
            throw NativeDownloadError.unsupported("Custom command manifest mux mode requires audio assets.")
        }

        let metadata = customCommandTemplateMetadata(for: result, title: title, rule: rule)
        let totalAssets = result.remoteVideoAssets.count + result.remoteAudioAssets.count
        let outputName = templatedFileName(
            original: outputFilename,
            title: title,
            sourceURL: sourceURL,
            index: nil,
            total: totalAssets,
            metadata: metadata
        )
        let output = AppPaths.uniqueFileURL(in: result.outputDirectory, filename: outputName)
        let workFolder = result.outputDirectory.appendingPathComponent(".manifest-mux-\(UUID().uuidString)", isDirectory: true)
        let videoFolder = workFolder.appendingPathComponent("video", isDirectory: true)
        let audioFolder = workFolder.appendingPathComponent("audio", isDirectory: true)
        let videoTrack = workFolder.appendingPathComponent("video-track.mp4")
        let audioTrack = workFolder.appendingPathComponent("audio-track.m4a")

        try AppPaths.ensureDirectory(videoFolder)
        try AppPaths.ensureDirectory(audioFolder)
        defer {
            try? FileManager.default.removeItem(at: workFolder)
        }

        let videoAssets = result.remoteVideoAssets.enumerated().map { offset, asset -> ResolvedAsset in
            var copy = asset
            let safeName = asset.filename.sanitizedFilename(maxLength: 150)
            copy.filename = String(format: "%05d-%@", offset + 1, safeName)
            return assetWithHeaderRules(copy)
        }
        let audioAssets = result.remoteAudioAssets.enumerated().map { offset, asset -> ResolvedAsset in
            var copy = asset
            let safeName = asset.filename.sanitizedFilename(maxLength: 150)
            copy.filename = String(format: "%05d-%@", offset + 1, safeName)
            return assetWithHeaderRules(copy)
        }

        if jobs.indices.contains(jobIndex) {
            jobs[jobIndex].title = title
            jobs[jobIndex].metadata = Self.resolvedMetadataPreservingRuntimeState(
                Self.customCommandMetadata(for: sourceURL, rule: rule, title: title, result: result),
                previous: jobs[jobIndex].metadata
            )
            jobs[jobIndex].total = totalAssets
            jobs[jobIndex].completed = 0
            jobs[jobIndex].progress = 0
            jobs[jobIndex].message = "Downloading manifest video"
            jobs[jobIndex].outputPath = output.path
            persistQueue()
        }

        try await downloadAndConcatenate(videoAssets, tempFolder: videoFolder, output: videoTrack, jobIndex: jobIndex)

        if jobs.indices.contains(jobIndex) {
            jobs[jobIndex].message = "Downloading manifest audio"
            persistQueue()
        }
        try await downloadAndConcatenate(audioAssets, tempFolder: audioFolder, output: audioTrack, jobIndex: jobIndex)

        let transcodeOptions = ffmpegTranscodeOptionsForUse()
        if jobs.indices.contains(jobIndex) {
            jobs[jobIndex].message = transcodeOptions.enabled ? "Muxing and transcoding manifest audio/video" : "Muxing manifest audio and video"
            persistQueue()
        }
        try await ffmpegBridge.mux(video: videoTrack, audio: audioTrack, output: output, options: transcodeOptions)

        var manifestMetadata = result.manifestMetadata
        manifestMetadata["muxed"] = "true"
        manifestMetadata["postprocess"] = transcodeOptions.enabled ? "ffmpeg-transcode" : "ffmpeg-mux"
        if transcodeOptions.enabled {
            manifestMetadata["transcoded"] = "true"
            for (key, value) in transcodeOptions.metadata {
                manifestMetadata[key] = value
            }
        }

        return CustomCommandResult(
            outputDirectory: result.outputDirectory,
            outputItems: result.outputItems + [output],
            remoteAssets: [],
            remoteVideoAssets: [],
            remoteAudioAssets: [],
            remotePackageMode: result.remotePackageMode,
            manifestTitle: result.manifestTitle,
            manifestFolderName: result.manifestFolderName,
            manifestMetadata: manifestMetadata
        )
    }

    nonisolated static func ytdlpMetadata(for url: URL, title: String, result: YTDLPResult) -> [String: String] {
        let sourceURL = YTDLPBridge.normalizedSourceURL(for: url)
        let host = sourceURL.host ?? url.host ?? ""
        let primaryItem = ytdlpPrimaryMediaItem(in: result.downloadedItems)
        let output = result.downloadedItems.count == 1 ? primaryItem : result.outputDirectory
        let filename = output?.lastPathComponent ?? title
        let basename = (filename as NSString).deletingPathExtension
        let ext = primaryItem?.pathExtension.lowercased() ?? ""
        let sourceMetadata = YTDLPBridge.sourceMetadata(for: sourceURL)
        let category = sourceMetadata["category"] ?? externalCategory(forExtension: ext, fallback: "media")

        var metadata = DownloadMetadata.clean([
            "series": title,
            "category": category,
            "type": "yt-dlp",
            "tool": "yt-dlp",
            "handler": SiteRuleHandler.ytdlp.rawValue,
            "format": ext,
            "host": host,
            "site": host,
            "filename": filename,
            "basename": basename,
            "ext": ext,
            "slug": sourceSlug(from: sourceURL, fallback: basename.isEmpty ? host : basename),
            "path": sourceURL.path,
            "query": sourceURL.query ?? "",
            "url": sourceURL.absoluteString,
            "original_url": url.absoluteString,
            "title": title,
            "playlist_mode": YTDLPBridge.allowsPlaylist(for: sourceURL) ? "playlist" : "single",
            "item_count": String(result.downloadedItems.count),
            "output_count": String(result.downloadedItems.count),
            "output_directory": result.outputDirectory.lastPathComponent
        ])

        for (key, value) in sourceMetadata where !value.trimmed.isEmpty {
            metadata[key] = value
        }
        metadata["type"] = "yt-dlp"
        metadata["tool"] = "yt-dlp"
        metadata["handler"] = SiteRuleHandler.ytdlp.rawValue

        for (key, value) in result.infoMetadata where !value.trimmed.isEmpty {
            metadata[key] = value
        }
        if let mediaTitle = result.infoMetadata["media_title"], !mediaTitle.trimmed.isEmpty {
            metadata["title"] = mediaTitle
            metadata["series"] = mediaTitle
        }
        if let webpageURL = result.infoMetadata["webpage_url"], !webpageURL.trimmed.isEmpty {
            metadata["url"] = webpageURL
        }
        return DownloadMetadata.clean(metadata)
    }

    private nonisolated static func ytdlpPrimaryMediaItem(in items: [URL]) -> URL? {
        items.first { item in
            let category = externalCategory(forExtension: item.pathExtension.lowercased(), fallback: "")
            return category == "video" || category == "audio"
        } ?? items.first
    }

    nonisolated static func customCommandMetadata(for url: URL, rule: SiteRule, title: String, result: CustomCommandResult) -> [String: String] {
        let host = url.host ?? ""
        let output = result.outputItems.count == 1 ? result.outputItems.first : result.outputDirectory
        let filename = output?.lastPathComponent ?? title
        let basename = (filename as NSString).deletingPathExtension
        let ext = result.outputItems.first?.pathExtension.lowercased() ?? ""
        let category = externalCategory(forExtension: ext, fallback: "external")

        let protectedMetadata = DownloadMetadata.clean([
            "series": title,
            "category": category,
            "type": SiteRuleHandler.customCommand.rawValue,
            "tool": "custom-command",
            "handler": rule.handler.rawValue,
            "rule": rule.name,
            "rule_id": rule.id.uuidString,
            "rule_host": rule.hostSuffix,
            "rule_pattern": rule.urlPattern ?? "",
            "format": ext,
            "host": host,
            "site": host,
            "filename": filename,
            "basename": basename,
            "ext": ext,
            "slug": sourceSlug(from: url, fallback: basename.isEmpty ? rule.name : basename),
            "path": url.path,
            "query": url.query ?? "",
            "url": url.absoluteString,
            "title": title,
            "item_count": String(result.outputItems.count),
            "output_count": String(result.outputItems.count),
            "output_directory": result.outputDirectory.lastPathComponent,
            "remote_package_mode": result.remotePackageMode.label
        ])

        var metadata = protectedMetadata
        for (key, value) in result.manifestMetadata where !value.trimmed.isEmpty {
            metadata[key] = value
        }
        for key in ["type", "tool", "handler", "rule", "rule_id", "rule_host", "rule_pattern"] {
            if let value = protectedMetadata[key] {
                metadata[key] = value
            }
        }
        if let manifestTitle = result.manifestTitle?.trimmed, !manifestTitle.isEmpty {
            metadata["title"] = manifestTitle
        } else {
            metadata["title"] = metadata["title"] ?? title
        }
        metadata["series"] = metadata["series"] ?? metadata["title"] ?? title
        return DownloadMetadata.clean(metadata)
    }

    nonisolated static func aria2Metadata(for url: URL, title: String, result: Aria2Result, options: Aria2Options = .defaults) -> [String: String] {
        let host = url.host ?? ""
        let scheme = url.scheme?.lowercased() ?? ""
        let infoHash = torrentInfoHash(from: url)
        let output = result.downloadedItems.count == 1 ? result.downloadedItems.first : result.outputDirectory
        let filename = output?.lastPathComponent ?? title
        let basename = (filename as NSString).deletingPathExtension
        let ext = result.downloadedItems.first?.pathExtension.lowercased() ?? ""
        let displayName = torrentDisplayName(from: url)

        var metadata = [
            "series": displayName.isEmpty ? title : displayName,
            "category": "torrent",
            "type": scheme == "magnet" ? "magnet" : "torrent",
            "tool": "aria2c",
            "handler": "aria2",
            "scheme": scheme,
            "format": ext,
            "host": host,
            "site": host,
            "filename": filename,
            "basename": basename,
            "ext": ext,
            "slug": sourceSlug(from: url, fallback: displayName.isEmpty ? basename : displayName),
            "path": url.path,
            "query": url.query ?? "",
            "url": url.absoluteString,
            "title": title,
            "display_name": displayName,
            "info_hash": infoHash,
            "selected_files": options.selectedFiles,
            "seed_time_minutes": options.seedTimeMinutes,
            "seed_ratio": options.seedRatio,
            "max_download_limit": options.maxDownloadLimit,
            "max_upload_limit": options.maxUploadLimit,
            "trackers": options.trackerURLs,
            "anonymous_mode": options.anonymousMode ? "true" : "false",
            "item_count": String(result.downloadedItems.count),
            "output_count": String(result.downloadedItems.count),
            "output_directory": result.outputDirectory.lastPathComponent
        ]

        if let pieceInfo = result.torrentPieceInfo {
            metadata["torrent_piece_count"] = String(pieceInfo.pieceCount)
            metadata["torrent_piece_size"] = ByteCountFormatter.string(fromByteCount: pieceInfo.pieceLength, countStyle: .file)
            metadata["torrent_total_size"] = ByteCountFormatter.string(fromByteCount: pieceInfo.totalLength, countStyle: .file)
            metadata["torrent_piece_length"] = String(pieceInfo.pieceLength)
            metadata["torrent_total_length"] = String(pieceInfo.totalLength)
        }

        return DownloadMetadata.clean(metadata)
    }

    private nonisolated static func externalCategory(forExtension ext: String, fallback: String) -> String {
        let category = directDownloadCategory(forExtension: ext, contentType: "")
        return category == "file" ? fallback : category
    }

    private nonisolated static func torrentDisplayName(from url: URL) -> String {
        if url.scheme?.lowercased() == "magnet",
           let displayName = URLComponents(url: url, resolvingAgainstBaseURL: false)?
            .queryItems?
            .first(where: { $0.name == "dn" })?
            .value?
            .trimmed,
           !displayName.isEmpty {
            return displayName
        }

        let filename = url.deletingPathExtension().lastPathComponent.trimmed
        if !filename.isEmpty {
            return filename
        }

        return torrentInfoHash(from: url)
    }

    private nonisolated static func torrentInfoHash(from url: URL) -> String {
        guard url.scheme?.lowercased() == "magnet",
              let xt = URLComponents(url: url, resolvingAgainstBaseURL: false)?
                .queryItems?
                .first(where: { $0.name.lowercased() == "xt" })?
                .value?
                .trimmed
                .lowercased() else {
            return ""
        }

        let prefix = "urn:btih:"
        if xt.hasPrefix(prefix) {
            return String(xt.dropFirst(prefix.count))
        }
        return xt
    }

    private func markCancelled(_ index: Int, persist: Bool = true) {
        guard jobs.indices.contains(index) else { return }
        let jobID = jobs[index].id
        if !Self.isPendingQueueRemoval(jobs[index]),
           let snapshot = retrySnapshots[jobID],
           jobs[index].status == .queued || jobs[index].status == .resolving {
            jobs[index] = restoredRetrySnapshot(snapshot)
            retrySnapshots.removeValue(forKey: jobID)
            if persist {
                persistQueue()
            }
            return
        }

        retrySnapshots.removeValue(forKey: jobID)
        jobs[index].status = .cancelled
        jobs[index].message = "Cancelled"
        jobs[index].recordMessage(jobs[index].message)
        if persist {
            persistQueue()
        }
    }

    private func markFailed(
        _ index: Int,
        message: String,
        reaction: String? = nil,
        allowsIncompleteRetry: Bool = true
    ) {
        guard jobs.indices.contains(index) else { return }
        queueRunFailedJobIDs.insert(jobs[index].id)
        recordActivity("Failed: \(jobs[index].title) - \(message)", category: "Download")
        jobs[index].status = .failed
        jobs[index].message = message
        jobs[index].recordMessage(message)
        jobs[index].metadata["last_error"] = message
        if let reaction = JobDisplayReaction(metadataValue: reaction) {
            jobs[index].metadata["reaction"] = reaction.rawValue
        }
        if Self.isPendingQueueRemoval(jobs[index]) {
            persistQueue()
            return
        }
        if scheduleFailureRetryIfNeeded(at: index, allowsIncompleteRetry: allowsIncompleteRetry) {
            return
        }
        persistQueue()
    }

    @discardableResult
    private func scheduleFailureRetryIfNeeded(
        at index: Int,
        allowsIncompleteRetry: Bool
    ) -> Bool {
        guard jobs.indices.contains(index) else { return false }
        let now = Date().timeIntervalSince1970
        if let releaseTarget = Self.releaseRetryTimestamp(for: jobs[index]),
           releaseTarget > now - 0.5 {
            return scheduleRetry(
                for: jobs[index].id,
                at: releaseTarget,
                kind: .release,
                force: true,
                delay: nil,
                announce: true,
                persist: true
            )
        }
        guard allowsIncompleteRetry, retryIncompleteAutomatically else { return false }
        return scheduleRetry(
            for: jobs[index].id,
            at: now + incompleteRetryDelay.seconds,
            kind: .incomplete,
            force: false,
            delay: incompleteRetryDelay.seconds,
            announce: true,
            persist: true
        )
    }

    nonisolated static func failureAllowsIncompleteRetry(_ error: Error) -> Bool {
        if error is CancellationError {
            return false
        }
        if let bridgeError = error as? PythonScriptBridgeError {
            if case .retryRequested = bridgeError {
                return false
            }
            return true
        }
        if let nativeError = error as? NativeDownloadError {
            switch nativeError {
            case .invalidURL, .unsupported, .missingGalleryID, .encryptedPlaylist, .cancelled:
                return false
            case .httpStatus(let status, _):
                return status == 408 || status == 425 || status == 429 || status >= 500
            case .invalidGalleryData, .noFiles, .invalidPlaylist:
                return true
            }
        }
        if let urlError = error as? URLError {
            return [
                URLError.Code.timedOut,
                .cannotFindHost,
                .cannotConnectToHost,
                .networkConnectionLost,
                .dnsLookupFailed,
                .notConnectedToInternet,
                .internationalRoamingOff,
                .callIsActive,
                .dataNotAllowed,
                .resourceUnavailable
            ].contains(urlError.code)
        }
        return true
    }

    private nonisolated static func releaseRetryTimestamp(for job: DownloadJob) -> TimeInterval? {
        for key in ["release_timestamp", "hdt_release_timestamp"] {
            guard let raw = job.metadata[key]?.trimmed, !raw.isEmpty else { continue }
            if let value = Double(raw), value.isFinite {
                return value
            }
            if let date = ISO8601DateFormatter().date(from: raw) {
                return date.timeIntervalSince1970
            }
        }
        return nil
    }

