    func testingCancelScheduledRetry(_ jobID: UUID) {
        cancelScheduledRestart(for: jobID)
        persistQueue()
    }
#endif

    @discardableResult
    private func queueRecordingAutoRetryIfNeeded(at index: Int, error: Error) -> Bool {
        guard jobs.indices.contains(index),
              !Self.isPendingQueueRemoval(jobs[index]),
              Self.shouldAutoRetryRecordingFailure(job: jobs[index]) else {
            return false
        }

        let currentRetryCount = Self.recordingAutoRetryCount(from: jobs[index].metadata)
        guard currentRetryCount < Self.maxRecordingAutoRetryCount else {
            return false
        }

        let nextRetryCount = currentRetryCount + 1
        let jobID = jobs[index].id
        cancelScheduledRestart(for: jobID)
        retrySnapshots.removeValue(forKey: jobID)
        completionAlertedJobIDs.remove(jobID)
        queueRunFinishedJobIDs.remove(jobID)
        queueRunFailedJobIDs.remove(jobID)

        jobs[index].title = jobs[index].source
        jobs[index].status = .queued
        jobs[index].progress = 0
        jobs[index].completed = 0
        jobs[index].total = 0
        jobs[index].message = "Retrying recording (\(nextRetryCount) / \(Self.maxRecordingAutoRetryCount))"
        jobs[index].outputPath = ""
        jobs[index].metadata["recording_retry_count"] = String(nextRetryCount)
        jobs[index].metadata["recording_retry_last_error"] = error.localizedDescription
        jobs[index].metadata["recording_retry_at"] = ISO8601DateFormatter().string(from: Date())
        jobs[index].metadata["last_error"] = error.localizedDescription
        addSummary = "Recording retry queued"
        persistQueue()
        return true
    }

    private nonisolated static let maxRecordingAutoRetryCount = 1

    nonisolated static func recordingAutoRetryCount(from metadata: [String: String]) -> Int {
        max(0, Int(metadata["recording_retry_count"]?.trimmed ?? "") ?? 0)
    }

    nonisolated static func resolvedMetadataPreservingRuntimeState(
        _ resolved: [String: String],
        previous: [String: String]
    ) -> [String: String] {
        var metadata = resolved
        for key in [
            "auto_record",
            Self.directDownloadOverrideMetadataKey,
            Self.pendingQueueRemovalMetadataKey,
            Self.pendingQueueOutputDeletionMetadataKey,
            "recording_retry_count",
            "recording_retry_last_error",
            "recording_retry_at",
            "python_native_fallback",
            "python_native_fallback_type",
            "python_native_fallback_plugin",
            "python_native_fallback_feature"
        ] {
            if let value = previous[key]?.trimmed, !value.isEmpty {
                metadata[key] = value
            }
        }
        if metadata["recording"] == nil,
           let value = previous["recording"]?.trimmed,
           !value.isEmpty {
            metadata["recording"] = value
        }
        let hookKeys = previous["python_hook_preserved_keys", default: ""]
            .split(separator: ",")
            .map { String($0).trimmed }
            .filter { !$0.isEmpty }
        for key in hookKeys {
            if let value = previous[key]?.trimmed, !value.isEmpty {
                metadata[key] = value
            }
        }
        if !hookKeys.isEmpty {
            metadata["python_hook_preserved_keys"] = hookKeys.joined(separator: ",")
        }
        for (key, value) in previous where key.hasPrefix("search_") && metadata[key] == nil {
            let trimmed = value.trimmed
            if !trimmed.isEmpty {
                metadata[key] = trimmed
            }
        }
        return DownloadMetadata.clean(metadata)
    }

    nonisolated static func shouldAutoRetryRecordingFailure(job: DownloadJob) -> Bool {
        let cleaned = DownloadMetadata.clean(job.metadata)
        if shouldUseRecordingFileNameTemplate(
            packageMode: .concatenate(outputFilename: ""),
            metadata: cleaned
        ) {
            return true
        }

        let source = job.source.lowercased()
        if source.contains(".m3u8") || source.contains("/live") {
            return true
        }

        let retryMarkers = [
            cleaned["auto_record"],
            cleaned["record"],
            cleaned["recording"],
            cleaned["live"]
        ].compactMap { $0?.lowercased() }

        return retryMarkers.contains { value in
            ["1", "true", "yes", "on", "live", "record", "recording"].contains(value)
        }
    }

    private func extractURLs(from text: String) -> [String] {
        text
            .components(separatedBy: .newlines)
            .flatMap { line -> [String] in
                let trimmedLine = line.trimmed
                if let hitomiURL = Self.hitomiCustomURIString(from: Self.cleanedClipboardToken(trimmedLine)) {
                    return [hitomiURL]
                }
                if let sankakuURL = Self.sankakuTagInputURLString(from: trimmedLine) {
                    return [sankakuURL]
                }
                if let booruURL = Self.booruTagInputURLString(from: trimmedLine) {
                    return [booruURL]
                }
                if let searchURL = quickSearchURLString(from: trimmedLine) {
                    return [searchURL]
                }
                return trimmedLine
                    .components(separatedBy: .whitespacesAndNewlines)
                    .map(Self.normalizedInputToken)
            }
            .filter { !$0.isEmpty }
    }

    private func extractMonitorableURLs(from text: String) -> [String] {
        extractURLs(from: text)
            .map(Self.cleanedClipboardToken)
            .filter(Self.isMonitorableURL)
    }

    private func inputItems(
        from text: String,
        monitorableOnly: Bool = false
    ) -> [(url: String, metadata: [String: String])] {
        if let task = OriginalBrowserExtensionTask.parse(text),
           let item = inputItem(from: task, monitorableOnly: monitorableOnly) {
            return [item]
        }
        if text.hasPrefix(OriginalBrowserExtensionTask.header) {
            return []
        }

        return text.components(separatedBy: .newlines).flatMap { line in
            if let task = OriginalBrowserExtensionTask.parse(line),
               let item = inputItem(from: task, monitorableOnly: monitorableOnly) {
                return [item]
            }
            if line.hasPrefix(OriginalBrowserExtensionTask.header) {
                return []
            }
            if let overrideItems = originalInputTypeOverrideItems(
                from: line,
                monitorableOnly: monitorableOnly
            ) {
                return overrideItems
            }
            return extractURLs(from: line).compactMap { raw -> (url: String, metadata: [String: String])? in
                let url = monitorableOnly ? Self.cleanedClipboardToken(raw) : raw
                guard !monitorableOnly || Self.isMonitorableURL(url) else { return nil }
                return (url, [:])
            }
        }
    }

    private func originalInputTypeOverrideItems(
        from line: String,
        monitorableOnly: Bool
    ) -> [(url: String, metadata: [String: String])]? {
        let tokens = line.components(separatedBy: .whitespacesAndNewlines).filter { !$0.isEmpty }
        guard tokens.contains(where: { OriginalInputType.prefixedInput(from: $0) != nil }) else {
            return nil
        }

        return tokens.compactMap { token -> (url: String, metadata: [String: String])? in
            let override = OriginalInputType.prefixedInput(from: token)
            let normalized = override.map {
                Self.normalizedOriginalInputPayload($0.payload, type: $0.type)
            } ?? Self.normalizedInputToken(token)
            let url = monitorableOnly ? Self.cleanedClipboardToken(normalized) : normalized
            guard !url.isEmpty,
                  !monitorableOnly || Self.isMonitorableURL(url) else {
                return nil
            }
            let metadata = override.map { [OriginalInputType.metadataKey: $0.type.rawValue] } ?? [:]
            return (url, metadata)
        }
    }

    private nonisolated static func normalizedOriginalInputPayload(
        _ payload: String,
        type: OriginalInputType
    ) -> String {
        let token = cleanedClipboardToken(payload.trimmed)
        guard !token.isEmpty else { return "" }

        if token.range(of: #"^[0-9]+$"#, options: .regularExpression) != nil {
            switch type {
            case .hitomi:
                return "https://hitomi.la/galleries/\(token).html"
            case .pixiv:
                return "https://www.pixiv.net/en/users/\(token)"
            case .hiyobi:
                return "https://hiyobi.me/reader/\(token)"
            case .ehen:
                break
            }
        }
        return normalizedInputToken(token)
    }

    private func inputItem(
        from task: OriginalBrowserExtensionTask,
        monitorableOnly: Bool
    ) -> (url: String, metadata: [String: String])? {
        let url = Self.normalizedInputToken(task.url)
        guard !url.isEmpty,
              !monitorableOnly || Self.isMonitorableURL(Self.cleanedClipboardToken(url)) else {
            return nil
        }
        return (url, task.metadata)
    }

    func clipboardCandidateURLs(from text: String) -> [String] {
        var seen = Set<String>()
        var output: [String] = []
        for url in extractURLs(from: text) {
            let key = URLIdentity.normalize(url)
            guard !key.isEmpty, !seen.contains(key) else { continue }
            seen.insert(key)
            output.append(url)
        }
        return output
    }

    private func jobsForAdding(
        _ urls: [String],
        checkHistory: Bool = true,
        metadata: [String: String] = [:],
        titleSuffix: String = "",
        promptForDuplicates: Bool = false
    ) -> [DownloadJob] {
        let items = urls.map { (url: $0, metadata: metadata) }
        return jobsForAdding(
            items,
            checkHistory: checkHistory,
            titleSuffix: titleSuffix,
            promptForDuplicates: promptForDuplicates
        )
    }

    private func jobsForAddingSearchResults(_ results: [SearchResultLink]) -> [DownloadJob] {
        let items = results.map { result in
            (
                url: result.url,
                metadata: Self.searchResultQueueMetadata(for: result)
            )
        }
        return jobsForAdding(items)
    }

    private func jobsForAdding(
        _ items: [(url: String, metadata: [String: String])],
        checkHistory: Bool = true,
        titleSuffix: String = "",
        promptForDuplicates: Bool = false
    ) -> [DownloadJob] {
        var seen = Set(jobs.compactMap { job -> String? in
            guard !Self.isTerminalOriginalLiveJob(job) else { return nil }
            return Self.duplicateKey(source: job.source, metadata: job.metadata)
        })
        let historySources = checkHistory && historyEnabled
            ? Set(history.compactMap { entry -> String? in
                guard !Self.isOriginalLiveInput(source: entry.source, metadata: entry.metadata) else { return nil }
                return Self.duplicateKey(
                    source: entry.source,
                    normalizedSource: entry.normalizedSource,
                    metadata: entry.metadata
                )
            })
            : []
        var skipped = 0
        var newJobs: [DownloadJob] = []
        var pending: [PendingDuplicateAddition] = []
        var pendingKeys = Set<String>()

        for item in items {
            let url = item.url
            let metadata = item.metadata
            let normalized = URLIdentity.normalize(url)
            guard !normalized.isEmpty else { continue }
            let duplicateKey = Self.duplicateKey(source: url, normalizedSource: normalized, metadata: metadata)

            if skipDuplicates && (seen.contains(duplicateKey) || historySources.contains(duplicateKey)) {
                skipped += 1
                if promptForDuplicates, pendingKeys.insert(duplicateKey).inserted {
                    pending.append(PendingDuplicateAddition(
                        source: url,
                        title: url + titleSuffix,
                        metadata: metadata
                    ))
                }
                continue
            }

            seen.insert(duplicateKey)
            newJobs.append(DownloadJob(source: url, title: url + titleSuffix, metadata: metadata))
        }

        if !pending.isEmpty {
            presentDuplicateAdditionConfirmation(pending, addedCount: newJobs.count)
        } else {
            addSummary = summary(added: newJobs.count, skipped: skipped)
        }
        return newJobs
    }

    var pendingDuplicateAdditionCount: Int {
        pendingDuplicateAdditions.count
    }

    func confirmDuplicateAddition() {
        let pending = pendingDuplicateAdditions
        let shouldStartQueue = pendingDuplicateAdditionStartsQueue
        pendingDuplicateAdditions = []
        pendingDuplicateAdditionStartsQueue = false
        showingDuplicateAdditionConfirmation = false
        duplicateAdditionMessage = ""
        guard !pending.isEmpty else { return }

        insertAddedJobsAtTop(pending.map {
            DownloadJob(source: $0.source, title: $0.title, metadata: $0.metadata)
        })
        addSummary = pending.count == 1
            ? "Duplicate job added again"
            : "\(pending.count) duplicate jobs added again"
        persistQueue()
        if shouldStartQueue {
            startQueue(addingInput: false)
        } else {
            runQueuedJobsIfEnabled()
        }
    }

    func cancelDuplicateAddition() {
        let count = pendingDuplicateAdditions.count
        pendingDuplicateAdditions = []
        pendingDuplicateAdditionStartsQueue = false
        showingDuplicateAdditionConfirmation = false
        duplicateAdditionMessage = ""
        if count > 0 {
            addSummary = count == 1 ? "Duplicate job skipped" : "\(count) duplicate jobs skipped"
        }
    }

    private func presentDuplicateAdditionConfirmation(
        _ pending: [PendingDuplicateAddition],
        addedCount: Int
    ) {
        pendingDuplicateAdditions = pending
        pendingDuplicateAdditionStartsQueue = false
        duplicateAdditionMessage = pending.count == 1
            ? AppLocalization.text(
                "This task has already been added. Download it again?",
                language: interfaceLanguage
            )
            : AppLocalization.format(
                "%@ tasks have already been added. Download them again?",
                language: interfaceLanguage,
                String(pending.count)
            )
        showingDuplicateAdditionConfirmation = true
        addSummary = addedCount == 0
            ? "Duplicate waiting for confirmation"
            : "\(addedCount) added, \(pending.count) duplicate waiting for confirmation"
    }

    private nonisolated static func searchResultQueueMetadata(for result: SearchResultLink) -> [String: String] {
        var metadata = result.metadata
        let title = result.title.trimmed
        if !title.isEmpty {
            metadata["search_title"] = title
            metadata["search_result_title"] = title
        }
        if let site = result.siteIdentifier?.trimmed, !site.isEmpty {
            metadata["search_site"] = metadata["search_site"] ?? site
            metadata["site"] = metadata["site"] ?? site
        }
        if !result.metadataText.trimmed.isEmpty {
            metadata["search_metadata"] = result.metadataText.trimmed
        }
        metadata["search_result"] = "true"
        metadata["search_url"] = result.url
        metadata["source_url"] = metadata["source_url"] ?? result.url
        metadata["page_url"] = metadata["page_url"] ?? result.url
        return DownloadMetadata.clean(metadata)
    }

    private nonisolated static func isAudioExtractionRequest(_ metadata: [String: String]) -> Bool {
        metadata["media_request"]?.lowercased() == "audio"
    }

    private nonisolated static func ytdlpAudioFormat(from metadata: [String: String]) -> String? {
        guard isAudioExtractionRequest(metadata) else { return nil }
        let format = metadata["audio_format"]?.trimmed.lowercased() ?? "mp3"
        return format.isEmpty ? "mp3" : format
    }

    private nonisolated static func mediaRequestMetadata(from metadata: [String: String]) -> [String: String] {
        guard isAudioExtractionRequest(metadata) else { return [:] }
        return [
            "media_request": "audio",
            "audio_format": ytdlpAudioFormat(from: metadata) ?? "mp3"
        ]
    }

    private nonisolated static func duplicateKey(
        source: String,
        normalizedSource: String? = nil,
        metadata: [String: String] = [:]
    ) -> String {
        let normalized = normalizedSource ?? URLIdentity.normalize(source)
        let request = isAudioExtractionRequest(metadata)
            ? "audio:\(ytdlpAudioFormat(from: metadata) ?? "mp3")"
            : "default"
        let originalType = metadata[OriginalInputType.metadataKey]?.lowercased() ?? ""
        return normalized + "\u{1f}" + request + "\u{1f}" + originalType
    }

    nonisolated static func isImprovedOriginalLiveInputURL(_ source: String) -> Bool {
        let value = source.trimmed
        guard let url = URL(string: value),
              let scheme = url.scheme?.lowercased(),
              scheme == "http" || scheme == "https" else {
            return false
        }

        let lowercased = value.lowercased()
        if lowercased.contains("nicovideo.jp/user/") || lowercased.contains("ch.nicovideo.jp") {
            return true
        }
        if TwitchVODResolver.liveLogin(from: url) != nil ||
            SOOPVODResolver.liveID(from: url) != nil ||
            ChzzkResolver.liveID(from: url) != nil {
            return true
        }

        guard let host = url.host?.lowercased(),
              ["youtube.com", "www.youtube.com", "m.youtube.com", "music.youtube.com", "youtube.test", "www.youtube.test"].contains(host),
              let first = url.path.split(separator: "/", omittingEmptySubsequences: true).first else {
            return false
        }
        return (String(first).removingPercentEncoding ?? String(first)).hasPrefix("@")
    }

    private nonisolated static func isTerminalOriginalLiveJob(_ job: DownloadJob) -> Bool {
        switch job.status {
        case .finished, .failed, .cancelled:
            return isOriginalLiveInput(source: job.source, metadata: job.metadata)
        case .queued, .resolving, .downloading:
            return false
        }
    }

    private nonisolated static func isOriginalLiveInput(
        source: String,
        metadata: [String: String]
    ) -> Bool {
        if isImprovedOriginalLiveInputURL(source) {
            return true
        }

        var normalized: [String: String] = [:]
        for (key, value) in metadata {
            normalized[key.lowercased()] = value.trimmed.lowercased()
        }
        for key in ["live", "is_live", "was_live"] {
            let value = normalized[key, default: ""]
            if ["1", "true", "yes", "on", "live", "is_live", "was_live", "post_live"].contains(value) {
                return true
            }
        }
        return ["live_status", "type", "category", "extractor", "extractor_key"]
            .contains { normalized[$0, default: ""].contains("live") }
    }

    private nonisolated static func normalizedHistorySource(for job: DownloadJob) -> String {
        URLIdentity.normalize(job.source)
    }

    private nonisolated static func importedQueueDocument(from data: Data) throws -> QueueImportDocument {
        let data = dataByStrippingUTF8BOM(data)
        if OriginalHDT.looksLikePackage(data) {
            let document = try OriginalHDT.decodeDocument(data)
            return QueueImportDocument(jobs: document.jobs, groups: document.groups)
        }
        let decoder = JSONDecoder()
        decoder.dateDecodingStrategy = .iso8601
        if let package = try? decoder.decode(QueueJobPackage.self, from: data) {
            return QueueImportDocument(jobs: package.jobs, groups: package.groups ?? [])
        }
        if let jobs = try? decoder.decode([DownloadJob].self, from: data) {
            return QueueImportDocument(jobs: jobs, groups: [])
        }
        if let userData = try? decoder.decode(AppUserData.self, from: data),
           !userData.queue.isEmpty || !userData.queueGroups.isEmpty {
            return QueueImportDocument(jobs: userData.queue, groups: userData.queueGroups)
        }

        let text = importedText(from: data)
        let urls = text
            .components(separatedBy: .newlines)
            .flatMap { extractURLs(fromTokenLine: $0) }
        guard !urls.isEmpty else {
            throw NativeDownloadError.unsupported("No jobs found.")
        }
        return QueueImportDocument(
            jobs: urls.map { DownloadJob(source: $0, title: $0) },
            groups: []
        )
    }

    private func normalizedImportedQueueJob(_ job: DownloadJob, existingIDs: inout Set<UUID>) -> DownloadJob? {
        var restored = Self.restoredQueueJob(job)
        let source = Self.normalizedInputToken(restored.source.trimmed)
        guard !source.isEmpty else { return nil }

        restored.source = source
        if restored.title.trimmed.isEmpty {
            restored.title = source
        }
        restored.comment = restored.comment.trimmed
        restored.rangeExpression = Self.isValidAssetRangeExpression(restored.rangeExpression) ? restored.rangeExpression.trimmed : ""
        if existingIDs.contains(restored.id) {
            restored.id = UUID()
        }
        existingIDs.insert(restored.id)
        return restored
    }

    private func moveJob(_ job: DownloadJob, offset: Int) {
        guard queueSortMode == .manual else {
            addSummary = "Use Manual queue sort before moving jobs"
            return
        }
        guard queueFilter.trimmed.isEmpty else {
            addSummary = "Clear the queue filter before moving jobs"
            return
        }
        let orderedJobs = queueOrderedJobs
        guard orderedJobs.contains(where: { $0.id == job.id }) else { return }
        let reordered = Self.jobsByMovingSelectedJobs(orderedJobs, selectedIDs: [job.id], offset: offset)
        guard reordered.map(\.id) != orderedJobs.map(\.id) else {
            addSummary = moveBlockedSummary(jobIDs: [job.id], offset: offset, orderedJobs: orderedJobs)
            return
        }

        applyQueueOrder(reordered)
        setSelectedJobIDs([job.id])
        addSummary = "Job moved"
        persistQueue()
    }

    private func moveSelectedJobs(offset: Int) {
        guard queueSortMode == .manual else {
            addSummary = "Use Manual queue sort before moving jobs"
            return
        }
        guard queueFilter.trimmed.isEmpty else {
            addSummary = "Clear the queue filter before moving jobs"
            return
        }
        guard !selectedJobIDs.isEmpty else {
            addSummary = "Select jobs to move"
            return
        }

        let orderedJobs = queueOrderedJobs
        let reordered = Self.jobsByMovingSelectedJobs(orderedJobs, selectedIDs: selectedJobIDs, offset: offset)
        guard reordered.map(\.id) != orderedJobs.map(\.id) else {
            addSummary = moveBlockedSummary(jobIDs: selectedJobIDs, offset: offset, orderedJobs: orderedJobs)
            return
        }

        applyQueueOrder(reordered)
        setSelectedJobIDs(selectedJobIDs)
        addSummary = "\(selectedJobIDs.count) selected job\(selectedJobIDs.count == 1 ? "" : "s") moved"
        persistQueue()
    }

    private func canMoveJob(at index: Int, offset: Int) -> Bool {
        guard jobs.indices.contains(index) else { return false }
        return canMoveQueueJobs([jobs[index].id], offset: offset)
    }

    private func canMoveSelectedJobs(offset: Int) -> Bool {
        canMoveQueueJobs(selectedJobIDs, offset: offset)
    }

    private func canMoveQueueJobs(_ jobIDs: Set<UUID>, offset: Int) -> Bool {
        guard queueSortMode == .manual,
              queueFilter.trimmed.isEmpty,
              !jobIDs.isEmpty else {
            return false
        }
        return Self.canMoveSelectedJobs(queueOrderedJobs, selectedIDs: jobIDs, offset: offset)
    }

    nonisolated static func canMoveSelectedJobs(_ jobs: [DownloadJob], selectedIDs: Set<UUID>, offset: Int) -> Bool {
        jobsByMovingSelectedJobs(jobs, selectedIDs: selectedIDs, offset: offset).map(\.id) != jobs.map(\.id)
    }

    nonisolated static func jobsByMovingSelectedJobs(_ jobs: [DownloadJob], selectedIDs: Set<UUID>, offset: Int) -> [DownloadJob] {
        guard !jobs.isEmpty, !selectedIDs.isEmpty, offset == -1 || offset == 1 else {
            return jobs
        }

        var reordered = jobs
        if offset < 0 {
            var index = 1
            while index < reordered.count {
                let current = reordered[index]
                let previous = reordered[index - 1]
                if selectedIDs.contains(current.id),
                   !selectedIDs.contains(previous.id),
                   current.isPinned == previous.isPinned {
                    reordered.swapAt(index, index - 1)
                }
                index += 1
            }
        } else {
            var index = reordered.count - 2
            while index >= 0 {
                let current = reordered[index]
                let next = reordered[index + 1]
                if selectedIDs.contains(current.id),
                   !selectedIDs.contains(next.id),
                   current.isPinned == next.isPinned {
                    reordered.swapAt(index, index + 1)
                }
                index -= 1
            }
        }

        return reordered
    }

    nonisolated static func jobsByMoving(
        _ jobs: [DownloadJob],
        movingIDs: Set<UUID>,
        relativeTo targetID: UUID,
        placeAfter: Bool
    ) -> [DownloadJob]? {
        guard !jobs.isEmpty,
              !movingIDs.isEmpty,
              !movingIDs.contains(targetID),
              jobs.contains(where: { $0.id == targetID }) else {
            return nil
        }

        let moving = jobs.filter { movingIDs.contains($0.id) }
        guard moving.count == movingIDs.count else { return nil }

        var remaining = jobs.filter { !movingIDs.contains($0.id) }
        guard let targetIndex = remaining.firstIndex(where: { $0.id == targetID }) else {
            return nil
        }
        let insertionIndex = targetIndex + (placeAfter ? 1 : 0)
        remaining.insert(contentsOf: moving, at: insertionIndex)
        return remaining
    }

    private func applyQueueOrder(_ reordered: [DownloadJob]) {
        if isRunning {
            activeQueueOrderIDs = reordered.map(\.id)
        } else {
            jobs = reordered
        }
    }

    private func moveBlockedSummary(
        jobIDs: Set<UUID>,
        offset: Int,
        orderedJobs: [DownloadJob]
    ) -> String {
        let indexes = orderedJobs.indices.filter { jobIDs.contains(orderedJobs[$0].id) }
        guard !indexes.isEmpty else { return "Select jobs to move" }

        for index in indexes {
            let destination = index + offset
            guard orderedJobs.indices.contains(destination),
                  !jobIDs.contains(orderedJobs[destination].id),
                  orderedJobs[index].isPinned != orderedJobs[destination].isPinned else {
                continue
            }
            return orderedJobs[index].isPinned ? "Pinned jobs stay above unpinned jobs" : "Pin job before moving above pinned jobs"
        }

        return "Selected jobs cannot move further"
    }

    private func addBookmarks(_ urls: [String]) {
        let records = urls.map { BookmarkImportRecord(title: nil, url: $0, createdAt: nil) }
        let added = addBookmarkRecords(records)
        addSummary = added == 0 ? "No new bookmarks" : "\(added) bookmarks saved"
    }

    @discardableResult
    private func mergeSearchProviders(_ imported: [SearchProvider]) -> Int {
        var existingIDs = Set(searchProviders.map(\.id))
        var existing = Set(searchProviders.map { Self.searchProviderImportKey(name: $0.name, urlTemplate: $0.urlTemplate) })
        var added = 0

        for provider in imported {
            let name = provider.name.trimmed.isEmpty ? Self.searchProviderName(forTemplate: provider.urlTemplate) : provider.name.trimmed
            let template = provider.urlTemplate.trimmed
            guard !name.isEmpty, Self.isValidSearchTemplate(template) else { continue }
            let key = Self.searchProviderImportKey(name: name, urlTemplate: template)
            guard existing.insert(key).inserted else { continue }
            let id = existingIDs.insert(provider.id).inserted ? provider.id : UUID()
            searchProviders.append(SearchProvider(id: id, name: name, urlTemplate: template, createdAt: provider.createdAt))
            added += 1
        }

        guard added > 0 else { return 0 }
        if !searchProviders.contains(where: { $0.id == selectedSearchProviderID }) {
            selectedSearchProviderID = searchProviders.first?.id ?? SearchProvider.defaultProviders[0].id
        }
        persistSearchProviders()
        return added
    }

    private nonisolated static func searchProviders(from data: Data) throws -> [SearchProvider] {
        let data = dataByStrippingUTF8BOM(data)
        let decoder = JSONDecoder()
        decoder.dateDecodingStrategy = .iso8601
        if let package = try? decoder.decode(SearchProviderPackage.self, from: data) {
            return package.providers
        }
        if let providers = try? decoder.decode([SearchProvider].self, from: data) {
            return providers
        }
        if let userData = try? decoder.decode(AppUserData.self, from: data), !userData.searchProviders.isEmpty {
            return userData.searchProviders
        }
        return searchProviders(fromText: importedText(from: data))
    }

    private nonisolated static func searchProviders(fromText text: String) -> [SearchProvider] {
        var providers: [SearchProvider] = []
        let formatter = ISO8601DateFormatter()
        var header: SearchProviderTextHeader?
        for line in text.components(separatedBy: .newlines) {
            let trimmed = line.trimmed
            guard !trimmed.isEmpty, !trimmed.hasPrefix("#") else { continue }
            let delimiter: Character = trimmed.contains("\t") ? "\t" : ","
            let fields = splitDelimited(trimmed, delimiter: delimiter)
            if let detectedHeader = searchProviderHeader(from: fields) {
                header = detectedHeader
                continue
            }

            let name: String
            let template: String
            let createdAt: Date
            if let header {
                template = value(at: header.templateIndex, in: fields).trimmed
                let rawName = header.nameIndex.map { value(at: $0, in: fields).trimmed } ?? ""
                name = rawName.isEmpty ? searchProviderName(forTemplate: template) : rawName
                createdAt = header.createdAtIndex.flatMap { formatter.date(from: value(at: $0, in: fields).trimmed) } ?? Date()
            } else if fields.count >= 2 {
                name = fields[0].trimmed
                template = fields[1].trimmed
                createdAt = fields.count >= 3 ? formatter.date(from: fields[2].trimmed) ?? Date() : Date()
            } else {
                continue
            }

            guard !template.isEmpty else { continue }
            providers.append(SearchProvider(
                id: UUID(),
                name: name.isEmpty ? searchProviderName(forTemplate: template) : name,
                urlTemplate: template,
                createdAt: createdAt
            ))
        }
        return providers
    }

    private nonisolated static func searchProviderHeader(from fields: [String]) -> SearchProviderTextHeader? {
        let normalized = fields.map(normalizedDelimitedHeader)
        guard let templateIndex = normalized.firstIndex(where: { searchProviderTemplateHeaderNames.contains($0) }) else {
            return nil
        }
        return SearchProviderTextHeader(
            nameIndex: normalized.firstIndex(where: { searchProviderNameHeaderNames.contains($0) }),
            templateIndex: templateIndex,
            createdAtIndex: normalized.firstIndex(where: { searchProviderCreatedAtHeaderNames.contains($0) })
        )
    }

