    @discardableResult
    private func mergeSearchBookmarks(_ imported: [SearchBookmark]) -> Int {
        var existingIDs = Set(searchBookmarks.map(\.id))
        var existing = Set(searchBookmarks.map { Self.searchBookmarkKey(providerName: $0.providerName, query: $0.query) })
        var added = 0

        for bookmark in imported {
            let query = bookmark.query.trimmed
            guard !query.isEmpty else { continue }
            let rawProviderName = bookmark.providerName.trimmed
            let fallbackProviderName = currentSearchProvider()?.name ?? SearchProvider.defaultProviders[0].name
            let providerName = rawProviderName.isEmpty ? fallbackProviderName : rawProviderName
            let key = Self.searchBookmarkKey(providerName: providerName, query: query)
            guard existing.insert(key).inserted else { continue }
            let provider = Self.searchProvider(matching: providerName, in: searchProviders)
            let resolvedProviderName = provider?.name ?? providerName
            let title = bookmark.title.trimmed.isEmpty
                ? Self.searchBookmarkTitle(providerName: resolvedProviderName, query: query)
                : bookmark.title.trimmed
            let id = existingIDs.insert(bookmark.id).inserted ? bookmark.id : UUID()
            searchBookmarks.append(SearchBookmark(
                id: id,
                title: title,
                providerID: provider?.id,
                providerName: resolvedProviderName,
                query: query,
                createdAt: bookmark.createdAt
            ))
            added += 1
        }

        guard added > 0 else { return 0 }
        persistSearchBookmarks()
        return added
    }

