    private nonisolated static func searchBookmarks(fromText text: String) -> [SearchBookmark] {
        var bookmarks: [SearchBookmark] = []
        let formatter = ISO8601DateFormatter()
        var header: SearchBookmarkTextHeader?
        for line in text.components(separatedBy: .newlines) {
            let trimmed = line.trimmed
            guard !trimmed.isEmpty, !trimmed.hasPrefix("#") else { continue }
            let delimiter: Character = trimmed.contains("\t") ? "\t" : ","
            let fields = splitDelimited(trimmed, delimiter: delimiter)
            if let detectedHeader = searchBookmarkHeader(from: fields) {
                header = detectedHeader
                continue
            }

            let title: String
            let providerName: String
            let query: String
            let createdAt: Date
            if let header {
                let headerQuery = value(at: header.queryIndex, in: fields).trimmed
                query = headerQuery.isEmpty && fields.count == 1 ? fields[0].trimmed : headerQuery
                title = header.titleIndex.map { value(at: $0, in: fields).trimmed } ?? ""
                providerName = header.providerIndex.map { value(at: $0, in: fields).trimmed } ?? ""
                createdAt = header.createdAtIndex.flatMap { formatter.date(from: value(at: $0, in: fields).trimmed) } ?? Date()
            } else if fields.count >= 3 {
                title = fields[0].trimmed
                providerName = fields[1].trimmed
                query = fields[2].trimmed
                createdAt = fields.count >= 4 ? formatter.date(from: fields[3].trimmed) ?? Date() : Date()
            } else if fields.count >= 2 {
                title = ""
                providerName = fields[0].trimmed
                query = fields[1].trimmed
                createdAt = Date()
            } else {
                title = ""
                providerName = ""
                query = fields.first?.trimmed ?? trimmed
                createdAt = Date()
            }
            guard !query.isEmpty else { continue }
            bookmarks.append(SearchBookmark(
                title: title,
                providerID: nil,
                providerName: providerName,
                query: query,
                createdAt: createdAt
            ))
        }
        return bookmarks
    }

