    private nonisolated static func queueFilterBookmarks(fromText text: String) -> [QueueFilterBookmark] {
        var bookmarks: [QueueFilterBookmark] = []
        let formatter = ISO8601DateFormatter()
        var header: QueueFilterBookmarkTextHeader?
        for line in text.components(separatedBy: .newlines) {
            let trimmed = line.trimmed
            guard !trimmed.isEmpty, !trimmed.hasPrefix("#") else { continue }
            let delimiter: Character = trimmed.contains("\t") ? "\t" : ","
            let fields = splitDelimited(trimmed, delimiter: delimiter)
            if let detectedHeader = queueFilterBookmarkHeader(from: fields) {
                header = detectedHeader
                continue
            }

            if let header {
                let headerQuery = value(at: header.queryIndex, in: fields).trimmed
                let query = headerQuery.isEmpty && fields.count == 1 ? fields[0].trimmed : headerQuery
                guard !query.isEmpty else { continue }
                let title = header.titleIndex.map { value(at: $0, in: fields).trimmed } ?? ""
                bookmarks.append(QueueFilterBookmark(
                    title: title.isEmpty ? queueFilterBookmarkTitle(for: query) : title,
                    query: query,
                    createdAt: header.createdAtIndex.flatMap { formatter.date(from: value(at: $0, in: fields).trimmed) } ?? Date()
                ))
            } else if fields.count >= 2 {
                let title = fields[0].trimmed
                let query = fields[1].trimmed
                guard !query.isEmpty else { continue }
                bookmarks.append(QueueFilterBookmark(
                    title: title.isEmpty ? queueFilterBookmarkTitle(for: query) : title,
                    query: query,
                    createdAt: fields.count >= 3 ? formatter.date(from: fields[2].trimmed) ?? Date() : Date()
                ))
            } else if let query = fields.first?.trimmed, !query.isEmpty {
                bookmarks.append(QueueFilterBookmark(title: queueFilterBookmarkTitle(for: query), query: query))
            } else {
                bookmarks.append(QueueFilterBookmark(title: queueFilterBookmarkTitle(for: trimmed), query: trimmed))
            }
        }
        return bookmarks
    }

    private nonisolated static func queueFilterBookmarkHeader(from fields: [String]) -> QueueFilterBookmarkTextHeader? {
        let normalized = fields.map(normalizedDelimitedHeader)
        guard let queryIndex = normalized.firstIndex(where: { queueFilterBookmarkQueryHeaderNames.contains($0) }) else {
            return nil
        }
        return QueueFilterBookmarkTextHeader(
            titleIndex: normalized.firstIndex(where: { queueFilterBookmarkTitleHeaderNames.contains($0) }),
            queryIndex: queryIndex,
            createdAtIndex: normalized.firstIndex(where: { queueFilterBookmarkCreatedAtHeaderNames.contains($0) })
        )
    }

