    private nonisolated static func normalizedDelimitedHeader(_ value: String) -> String {
        stripLeadingUnicodeBOM(value)
            .trimmed
            .trimmingCharacters(in: CharacterSet(charactersIn: "\"'"))
            .lowercased()
            .replacingOccurrences(of: " ", with: "_")
            .replacingOccurrences(of: "-", with: "_")
    }

    private nonisolated static func value(at index: Int, in fields: [String]) -> String {
