        guard cleaned.count > 48 else { return cleaned }
        return String(cleaned.prefix(45)) + "..."
    }

    @discardableResult
    private func addBookmarkRecords(_ records: [BookmarkImportRecord]) -> Int {
        var existing = Set(bookmarks.map { URLIdentity.normalize($0.url) })
        var added = 0

        for record in records {
            let normalizedURL = Self.normalizedInputToken(record.url)
            guard !normalizedURL.isEmpty else { continue }
            let normalized = URLIdentity.normalize(normalizedURL)
            guard !normalized.isEmpty, !existing.contains(normalized) else { continue }
            existing.insert(normalized)
            let title = record.title?.trimmed
            bookmarks.append(URLBookmark(
                id: UUID(),
                title: title?.isEmpty == false ? title! : bookmarkTitle(for: normalizedURL),
                url: normalizedURL,
                createdAt: record.createdAt ?? Date(),
                tags: Self.normalizedBookmarkTags(record.tags),
                note: record.note?.trimmed ?? ""
            ))
            added += 1
        }

        userData.bookmarks = bookmarks
        persistUserData()
        return added
    }

    private nonisolated static func bookmarkExportText(_ bookmarks: [URLBookmark]) -> String {
        let formatter = ISO8601DateFormatter()
        let header = "title\turl\tcreated_at\ttags\tnote"
        let rows = bookmarks.map { bookmark in
            [
                tsvField(bookmark.title),
                tsvField(bookmark.url),
                formatter.string(from: bookmark.createdAt),
                tsvField(bookmark.tags.joined(separator: ",")),
                tsvField(bookmark.note)
            ].joined(separator: "\t")
        }
        return ([header] + rows).joined(separator: "\n") + "\n"
    }

    private nonisolated static func bookmarkImportRecords(from data: Data) -> [BookmarkImportRecord] {
        let data = dataByStrippingUTF8BOM(data)
        let decoder = JSONDecoder()
        decoder.dateDecodingStrategy = .iso8601
        if let bookmarks = try? decoder.decode([URLBookmark].self, from: data) {
            return bookmarks.map { BookmarkImportRecord(title: $0.title, url: $0.url, createdAt: $0.createdAt, tags: $0.tags, note: $0.note) }
        }
        if let userData = try? decoder.decode(AppUserData.self, from: data), !userData.bookmarks.isEmpty {
            return userData.bookmarks.map { BookmarkImportRecord(title: $0.title, url: $0.url, createdAt: $0.createdAt, tags: $0.tags, note: $0.note) }
        }
        let text = importedText(from: data)
        return bookmarkImportRecords(fromText: text)
    }

    private nonisolated static func bookmarkImportRecords(fromText text: String) -> [BookmarkImportRecord] {
        let formatter = ISO8601DateFormatter()
        var records: [BookmarkImportRecord] = []
        var header: BookmarkTextHeader?

        for line in text.components(separatedBy: .newlines) {
            let trimmedLine = line.trimmed
            guard !trimmedLine.isEmpty, !trimmedLine.hasPrefix("#") else { continue }
            let fields = trimmedLine.contains("\t")
                ? splitDelimited(trimmedLine, delimiter: "\t")
                : splitDelimited(trimmedLine, delimiter: ",")
            if let detectedHeader = bookmarkHeader(from: fields) {
                header = detectedHeader
                continue
            }

            if let header {
                let rawURL = value(at: header.urlIndex, in: fields).trimmed
                let normalizedURL = normalizedInputToken(rawURL)
                guard !rawURL.isEmpty, looksLikeURL(normalizedURL) else {
                    for url in extractURLs(fromTokenLine: trimmedLine) {
                        records.append(BookmarkImportRecord(title: nil, url: url, createdAt: nil))
                    }
                    continue
                }

                let title = header.titleIndex.map { value(at: $0, in: fields).trimmed } ?? ""
                let note = header.noteIndex.map { value(at: $0, in: fields).trimmed } ?? ""
                records.append(BookmarkImportRecord(
                    title: title.isEmpty ? nil : title,
                    url: rawURL,
                    createdAt: header.createdAtIndex.flatMap { formatter.date(from: value(at: $0, in: fields).trimmed) },
                    tags: header.tagsIndex.map { bookmarkTags(from: value(at: $0, in: fields)) } ?? [],
                    note: note.isEmpty ? nil : note
                ))
                continue
            }

            let normalizedSecondField = fields.count >= 2 ? normalizedInputToken(fields[1]) : ""
            if fields.count >= 2, !looksLikeURL(normalizedInputToken(fields[0])), looksLikeURL(normalizedSecondField) {
                records.append(BookmarkImportRecord(
                    title: fields[0],
                    url: fields[1],
                    createdAt: fields.count >= 3 ? formatter.date(from: fields[2]) : nil,
                    tags: fields.count >= 4 ? bookmarkTags(from: fields[3]) : [],
                    note: fields.count >= 5 ? fields[4] : nil
                ))
            } else {
                for url in extractURLs(fromTokenLine: trimmedLine) {
                    records.append(BookmarkImportRecord(title: nil, url: url, createdAt: nil))
                }
            }
        }

        return records
    }

    private nonisolated static func bookmarkHeader(from fields: [String]) -> BookmarkTextHeader? {
        let normalized = fields.map(normalizedDelimitedHeader)
        guard let urlIndex = normalized.firstIndex(where: { bookmarkURLHeaderNames.contains($0) }) else {
            return nil
        }
        return BookmarkTextHeader(
            titleIndex: normalized.firstIndex(where: { bookmarkTitleHeaderNames.contains($0) }),
            urlIndex: urlIndex,
            createdAtIndex: normalized.firstIndex(where: { bookmarkCreatedAtHeaderNames.contains($0) }),
            tagsIndex: normalized.firstIndex(where: { bookmarkTagsHeaderNames.contains($0) }),
            noteIndex: normalized.firstIndex(where: { bookmarkNoteHeaderNames.contains($0) })
        )
    }

    private nonisolated static var bookmarkTitleHeaderNames: Set<String> {
        ["title", "name", "label", "bookmark", "bookmark_title", "url_title", "site", "제목", "이름", "사이트"]
    }

    private nonisolated static var bookmarkURLHeaderNames: Set<String> {
        ["url", "uri", "link", "href", "address", "source", "source_url", "bookmark_url", "target", "주소", "링크"]
    }

    private nonisolated static var bookmarkCreatedAtHeaderNames: Set<String> {
        ["created_at", "createdat", "created", "date", "time", "timestamp", "added_at", "addedat", "생성일", "날짜", "추가일"]
    }

    private nonisolated static var bookmarkTagsHeaderNames: Set<String> {
        ["tags", "tag", "labels", "label_tags", "categories", "category", "keywords", "keyword", "태그", "분류"]
    }

    private nonisolated static var bookmarkNoteHeaderNames: Set<String> {
        ["note", "notes", "memo", "comment", "comments", "description", "desc", "remark", "remarks", "메모", "비고", "설명", "코멘트"]
    }

    private nonisolated static func splitDelimited(_ line: String, delimiter: Character) -> [String] {
        var fields: [String] = []
        var field = ""
        var inQuotes = false
        var index = line.startIndex
        while index < line.endIndex {
            let character = line[index]
            if character == "\"" {
                let next = line.index(after: index)
                if inQuotes, next < line.endIndex, line[next] == "\"" {
                    field.append("\"")
                    index = line.index(after: next)
                    continue
                }
                inQuotes.toggle()
            } else if character == delimiter, !inQuotes {
                fields.append(field.trimmingCharacters(in: .whitespacesAndNewlines))
                field = ""
            } else {
                field.append(character)
            }
            index = line.index(after: index)
        }
        fields.append(field.trimmingCharacters(in: .whitespacesAndNewlines))
        return fields
    }

    private nonisolated static func dataByStrippingUTF8BOM(_ data: Data) -> Data {
        let utf8BOM: [UInt8] = [0xEF, 0xBB, 0xBF]
        guard data.starts(with: utf8BOM) else { return data }
        return Data(data.dropFirst(utf8BOM.count))
    }

    private nonisolated static func importedText(from data: Data) -> String {
        let bytes = Array(data.prefix(3))
        if bytes.count >= 2, bytes[0] == 0xFF, bytes[1] == 0xFE {
            let body = Data(data.dropFirst(2))
            return stripLeadingUnicodeBOM(String(data: body, encoding: .utf16LittleEndian) ?? "")
        }
        if bytes.count >= 2, bytes[0] == 0xFE, bytes[1] == 0xFF {
            let body = Data(data.dropFirst(2))
            return stripLeadingUnicodeBOM(String(data: body, encoding: .utf16BigEndian) ?? "")
        }
        let stripped = dataByStrippingUTF8BOM(data)
        let text = String(data: stripped, encoding: .utf8) ?? String(decoding: stripped, as: UTF8.self)
        return stripLeadingUnicodeBOM(text)
    }

    private nonisolated static func stripLeadingUnicodeBOM(_ value: String) -> String {
        guard value.first == "\u{FEFF}" else { return value }
        return String(value.dropFirst())
    }

    private nonisolated static func extractURLs(fromTokenLine line: String) -> [String] {
        let trimmedLine = line.trimmed
        if let hitomiURL = hitomiCustomURIString(from: cleanedClipboardToken(trimmedLine)) {
            return [hitomiURL]
        }
        if let sankakuURL = sankakuTagInputURLString(from: line) {
            return [sankakuURL]
        }
        if let booruURL = booruTagInputURLString(from: line) {
            return [booruURL]
        }
        return line
            .components(separatedBy: .whitespacesAndNewlines)
            .map(normalizedInputToken)
            .filter { !$0.isEmpty && looksLikeURL($0) }
    }

    private nonisolated static func looksLikeURL(_ value: String) -> Bool {
        let lowered = value.lowercased()
        return lowered.hasPrefix("http://") ||
            lowered.hasPrefix("https://") ||
            lowered.hasPrefix("file://") ||
            lowered.hasPrefix("magnet:") ||
            lowered.hasPrefix("discord:")
    }

    private nonisolated static func bookmarkTags(from value: String) -> [String] {
        normalizedBookmarkTags(value.components(separatedBy: CharacterSet(charactersIn: ",;")))
    }

    private nonisolated static func normalizedBookmarkTags(_ tags: [String]) -> [String] {
        var seen = Set<String>()
        return tags.compactMap { raw in
            let cleaned = raw.trimmed.trimmingCharacters(in: CharacterSet(charactersIn: "#"))
            guard !cleaned.isEmpty else { return nil }
            let key = cleaned.lowercased()
            guard seen.insert(key).inserted else { return nil }
            return cleaned
        }
    }

    private nonisolated static func tsvField(_ value: String) -> String {
        value
            .replacingOccurrences(of: "\t", with: " ")
            .replacingOccurrences(of: "\r", with: " ")
            .replacingOccurrences(of: "\n", with: " ")
    }

    private nonisolated static func siteRules(fromPackageData data: Data) throws -> [SiteRule] {
        let data = dataByStrippingUTF8BOM(data)
        let decoder = JSONDecoder()
        decoder.dateDecodingStrategy = .iso8601
        if let package = try? decoder.decode(SiteRulePackage.self, from: data) {
            return package.rules
        }
        return try decoder.decode([SiteRule].self, from: data)
    }

    private nonisolated static func siteRules(fromRuleData data: Data, sourceURL: URL? = nil) throws -> [SiteRule] {
        let data = dataByStrippingUTF8BOM(data)
        let decoder = JSONDecoder()
        decoder.dateDecodingStrategy = .iso8601
        if let package = try? decoder.decode(SiteRulePackage.self, from: data) {
            return package.rules
        }
        if let rules = try? decoder.decode([SiteRule].self, from: data) {
            return rules
        }
        if let manifest = try? decoder.decode(SiteRulePluginManifest.self, from: data) {
            return manifest.siteRules(sourceURL: sourceURL)
        }
        return try decoder.decode([SiteRulePluginRule].self, from: data).compactMap {
            $0.siteRule(pluginName: nil, sourceURL: sourceURL)
        }
    }

    private func completeJob(at index: Int) async {
        guard jobs.indices.contains(index), jobs[index].status == .finished else { return }
        jobs[index].recordMessage(jobs[index].message)
        if Self.isPendingQueueRemoval(jobs[index]) {
            jobs[index].metadata["download_completed_at"] = ISO8601DateFormatter().string(from: Date())
            persistQueue()
            return
        }
        if !effectivePythonHookCalls(for: .taskFinished).isEmpty {
            do {
                let names = apiOutputFiles(for: jobs[index]).map { $0.url.path }
                let context = PythonScriptBridge.hookContext(
                    job: jobs[index],
                    sourceURL: URL(string: jobs[index].source.trimmed),
                    names: names
                )
                let hooked = try await runPythonHooks(event: .taskFinished, context: context)
                applyPythonHookContext(hooked, toJobAt: index)
            } catch PythonScriptBridgeError.retryRequested(_, let message) {
                markFailed(index, message: message, allowsIncompleteRetry: false)
                return
            } catch {
                markFailed(
                    index,
                    message: "Finished hook failed: \(error.localizedDescription)",
                    allowsIncompleteRetry: Self.failureAllowsIncompleteRetry(error)
                )
                return
            }
        }
        await refreshOriginalInfoOutputNames(at: index)
        await enrichCompletedJobMetadata(at: index)
        await refreshCompletedJobByteCount(at: index)
        jobs[index].metadata["download_completed_at"] = ISO8601DateFormatter().string(from: Date())
        recordHistory(for: index)
        scheduleRestartIfNeeded(for: jobs[index])
        handleJobCompletionAlert(for: jobs[index])
        await autoRemoveFinishedJobIfNeeded(at: index)
        persistQueue()
    }

    private func completeManuallyFinishedJob(at index: Int) {
        guard jobs.indices.contains(index), jobs[index].status == .finished else { return }
        jobs[index].recordMessage(jobs[index].message)
        jobs[index].resolvedFilenames = OutputPreviewFileScanner.files(at: jobs[index].outputPath)
            .map(\.relativePath)
        refreshCompletedJobByteCountSynchronously(at: index)
        jobs[index].metadata["download_completed_at"] = ISO8601DateFormatter().string(from: Date())
        recordHistory(for: index)
        scheduleRestartIfNeeded(for: jobs[index])
        handleJobCompletionAlert(for: jobs[index])
        persistQueue()
    }

    private func refreshOriginalInfoOutputNames(at index: Int) async {
        guard jobs.indices.contains(index) else { return }
        let jobID = jobs[index].id
        let outputPath = jobs[index].outputPath
        let names = await Task.detached(priority: .utility) {
            OutputPreviewFileScanner.files(at: outputPath).map(\.relativePath)
        }.value
        guard !names.isEmpty,
              let currentIndex = jobs.firstIndex(where: { $0.id == jobID }),
              jobs[currentIndex].outputPath == outputPath else {
            return
        }
        jobs[currentIndex].resolvedFilenames = names
    }

    private func enrichCompletedJobMetadata(at index: Int) async {
        guard jobs.indices.contains(index) else { return }
        await enrichCompletedJobMetadata(for: jobs[index].id)
    }

    private func refreshCompletedJobByteCount(at index: Int) async {
        guard jobs.indices.contains(index) else { return }
        let jobID = jobs[index].id
        let outputPath = jobs[index].outputPath
        let byteCount = await Task.detached(priority: .utility) {
            Self.outputByteCount(forOutputPath: outputPath)
        }.value
        guard let byteCount, byteCount > 0,
              let currentIndex = jobs.firstIndex(where: { $0.id == jobID }),
              jobs[currentIndex].status == .finished,
              jobs[currentIndex].outputPath == outputPath else {
            return
        }
        applyCompletedJobByteCount(byteCount, at: currentIndex)
    }

    private func refreshCompletedJobByteCountSynchronously(at index: Int) {
        guard jobs.indices.contains(index),
              let byteCount = Self.outputByteCount(forOutputPath: jobs[index].outputPath),
              byteCount > 0 else {
            return
        }
        applyCompletedJobByteCount(byteCount, at: index)
    }

    private func applyCompletedJobByteCount(_ byteCount: Int64, at index: Int) {
        jobs[index].metadata["byte_count"] = String(byteCount)
        jobs[index].metadata["total_bytes"] = String(byteCount)
        jobs[index].metadata["size_source"] = "local-output"
    }

    private func backfillCompletedOutputMetadata() async {
        let candidates = jobs.compactMap { job -> CompletedOutputMetadataCandidate? in
            guard job.status == .finished,
                  !job.outputPath.trimmed.isEmpty else {
                return nil
            }
            let needsByteCount = !Self.hasLocalOutputByteCount(job.metadata)
            let storedOutputExists = OutputPreviewFileScanner.outputPathExists(job.outputPath)
            guard needsByteCount || !storedOutputExists else { return nil }
            return CompletedOutputMetadataCandidate(
                jobID: job.id,
                originalOutputPath: job.outputPath,
                needsByteCount: needsByteCount
            )
        }
        guard !candidates.isEmpty else { return }

        let results = await Self.completedOutputMetadataResults(
            for: candidates,
            destinationPath: destinationPath
        )
        guard !Task.isCancelled else { return }

        var updatedCount = 0
        for result in results {
            guard let index = jobs.firstIndex(where: { $0.id == result.jobID }),
                  jobs[index].status == .finished,
                  jobs[index].outputPath == result.originalOutputPath else {
                continue
            }
            var changed = false
            if jobs[index].outputPath != result.recoveredOutputPath {
                jobs[index].outputPath = result.recoveredOutputPath
                changed = true
            }
            if let byteCount = result.byteCount,
               byteCount > 0,
               !Self.hasLocalOutputByteCount(jobs[index].metadata) {
                applyCompletedJobByteCount(byteCount, at: index)
                changed = true
            }
            if changed {
                updatedCount += 1
            }
        }
        if updatedCount > 0 {
            persistQueue()
        }
    }

    private nonisolated static func completedOutputMetadataResults(
        for candidates: [CompletedOutputMetadataCandidate],
        destinationPath: String
    ) async -> [CompletedOutputMetadataResult] {
        let workerCount = min(4, candidates.count)
        return await withTaskGroup(of: [CompletedOutputMetadataResult].self) { group in
            for workerIndex in 0..<workerCount {
                group.addTask(priority: .utility) {
                    var workerResults: [CompletedOutputMetadataResult] = []
                    for candidateIndex in stride(
                        from: workerIndex,
                        to: candidates.count,
                        by: workerCount
                    ) {
                        guard !Task.isCancelled else { break }
                        let candidate = candidates[candidateIndex]
                        guard let output = QueueThumbnailProvider.existingOutputURL(
                            forOutputPath: candidate.originalOutputPath,
                            destinationPath: destinationPath
                        ) else {
                            continue
                        }
                        let byteCount = candidate.needsByteCount
                            ? outputByteCount(forOutputPath: output.path)
                            : nil
                        workerResults.append(CompletedOutputMetadataResult(
                            jobID: candidate.jobID,
                            originalOutputPath: candidate.originalOutputPath,
                            recoveredOutputPath: output.path,
                            byteCount: byteCount
                        ))
                    }
                    return workerResults
                }
            }

            var results: [CompletedOutputMetadataResult] = []
            for await workerResults in group {
                results.append(contentsOf: workerResults)
            }
            return results
        }
    }

    private nonisolated static func hasLocalOutputByteCount(_ metadata: [String: String]) -> Bool {
        metadata["size_source"]?.trimmed.lowercased() == "local-output" &&
            (metadataByteCount(metadata["byte_count"]) ?? 0) > 0
    }

    nonisolated static func outputByteCount(
        forOutputPath outputPath: String,
        fileManager: FileManager = .default
    ) -> Int64? {
        let value = outputPath.trimmed
        guard !value.isEmpty else { return nil }

        let output = URL(fileURLWithPath: (value as NSString).expandingTildeInPath)
        var isDirectory = ObjCBool(false)
        guard fileManager.fileExists(atPath: output.path, isDirectory: &isDirectory) else {
            return nil
        }
        if !isDirectory.boolValue {
            return fileManager.isReadableFile(atPath: output.path)
                ? outputFileByteCount(output)
                : nil
        }

        guard let enumerator = fileManager.enumerator(
            at: output,
            includingPropertiesForKeys: [.isRegularFileKey, .fileSizeKey],
            options: [.skipsHiddenFiles, .skipsPackageDescendants],
            errorHandler: { _, _ in true }
        ) else {
            return nil
        }

        var total: Int64 = 0
        var fileCount = 0
        for case let file as URL in enumerator {
            guard let values = try? file.resourceValues(forKeys: [.isRegularFileKey, .fileSizeKey]),
                  values.isRegularFile == true,
                  let size = values.fileSize,
                  size >= 0 else {
                continue
            }
            let (sum, overflow) = total.addingReportingOverflow(Int64(size))
            total = overflow ? Int64.max : sum
            fileCount += 1
        }
        return fileCount > 0 ? total : nil
    }

    private nonisolated static func outputFileByteCount(_ file: URL) -> Int64? {
        guard let values = try? file.resourceValues(forKeys: [.fileSizeKey]),
              let size = values.fileSize,
              size >= 0 else {
            return nil
        }
        return Int64(size)
    }

    private func enrichCompletedJobMetadata(for jobID: UUID) async {
        guard let index = jobs.firstIndex(where: { $0.id == jobID }),
              jobs[index].status == .finished,
              Self.metadataNeedsLocalDuration(jobs[index].metadata),
              let outputURL = Self.singleOutputMediaFileURL(from: URL(fileURLWithPath: jobs[index].outputPath)) else {
            return
        }

        let seconds = await MediaFileMetadataReader.durationSeconds(for: outputURL)
        guard let currentIndex = jobs.firstIndex(where: { $0.id == jobID }),
              jobs[currentIndex].status == .finished,
              Self.metadataNeedsLocalDuration(jobs[currentIndex].metadata) else {
            return
        }

        let updated = MediaFileMetadataReader.metadataByAddingDuration(
            to: jobs[currentIndex].metadata,
            seconds: seconds
        )
        if updated != jobs[currentIndex].metadata {
            jobs[currentIndex].metadata = updated
        }
    }

    nonisolated static func metadataNeedsLocalDuration(_ metadata: [String: String]) -> Bool {
        let durationKeys = ["duration_seconds", "duration", "duration_string", "duration_ms"]
        return durationKeys.allSatisfy { metadata[$0]?.trimmed.isEmpty ?? true }
    }

    nonisolated static func singleOutputMediaFileURL(from output: URL) -> URL? {
        var isDirectory: ObjCBool = false
        guard FileManager.default.fileExists(atPath: output.path, isDirectory: &isDirectory),
              !isDirectory.boolValue,
              MediaFileMetadataReader.canReadDuration(for: output) else {
            return nil
        }
        return output
    }

    nonisolated static func isRetiredDaumWebtoonURL(_ url: URL) -> Bool {
        guard let scheme = url.scheme?.lowercased(),
              scheme == "http" || scheme == "https",
              let host = url.host?.lowercased() else {
            return false
        }

        if host == "webtoon.daum.net" || host.hasSuffix(".webtoon.daum.net") {
            return true
        }

        if host == "cartoon.media.daum.net" || host.hasSuffix(".cartoon.media.daum.net") {
            let marker = "\(url.path)?\(url.query ?? "")".lowercased()
            return marker.contains("webtoon")
        }

        return false
    }

    nonisolated static func retiredDaumWebtoonUnsupportedMessage(for url: URL) -> String? {
        guard isRetiredDaumWebtoonURL(url) else { return nil }
        return "Daum Webtoon support has ended. Use the migrated Kakao Webtoon URL on webtoon.kakao.com if it is available."
    }

    private func handleJobCompletionAlert(for job: DownloadJob) {
        guard job.metadata["manual_completion"] != "true" else { return }
        guard completionAlertedJobIDs.insert(job.id).inserted else { return }
        queueRunFinishedJobIDs.insert(job.id)
        recordActivity("Finished: \(job.title)", category: "Download")

        if playSoundWhenJobCompletes {
            completionAlerts.playCompletionSound()
        }
        if notifyWhenJobCompletes {
            completionAlerts.notifyJobFinished(title: job.title, outputPath: job.outputPath)
        }
    }

    private func autoRemoveFinishedJobIfNeeded(at index: Int) async {
        guard autoRemoveFinishedJobs,
              jobs.indices.contains(index),
              !Self.isPendingQueueRemoval(jobs[index]) else {
            return
        }

        let job = jobs[index]
        if defersAutoRemoveUntilQueueEnd {
            deferredAutoRemoveJobIDs.insert(job.id)
            return
        }

        guard job.status == .finished,
              job.metadata["manual_completion"] != "true",
              configuredRestartDelaySeconds(for: job) == nil,
              Self.scheduledRetryTimestamp(for: job) == nil,
              !isProtected(job) else {
            return
        }

        do {
            try await runAutoRemoveHookIfNeeded(for: job)
        } catch {
            let message = Self.autoRemoveHookErrorMessage(error)
            if let currentIndex = jobs.firstIndex(where: { $0.id == job.id }) {
                jobs[currentIndex].message = "자동 제거 후크 실패"
                jobs[currentIndex].metadata["auto_remove_hook_error"] = message
            }
            autoRemoveHookStatus = "자동 제거 후크 실패: \(message)"
            addSummary = "자동 제거 후크 실패"
            return
        }

        guard let currentIndex = jobs.firstIndex(where: { $0.id == job.id }) else {
            return
        }
        guard jobs[currentIndex].status == .finished,
              !Self.isPendingQueueRemoval(jobs[currentIndex]),
              jobs[currentIndex].metadata["manual_completion"] != "true",
              configuredRestartDelaySeconds(for: jobs[currentIndex]) == nil,
              Self.scheduledRetryTimestamp(for: jobs[currentIndex]) == nil,
              !isProtected(jobs[currentIndex]) else {
            return
        }

        retrySnapshots.removeValue(forKey: job.id)
        completionAlertedJobIDs.remove(job.id)
        jobs.remove(at: currentIndex)
        addSummary = "Finished job auto removed"
    }

    private func flushDeferredAutoRemoveFinishedJobs() async {
        guard !deferredAutoRemoveJobIDs.isEmpty else { return }
        let deferredIDs = deferredAutoRemoveJobIDs
        deferredAutoRemoveJobIDs.removeAll()
        let wasDeferring = defersAutoRemoveUntilQueueEnd
        defersAutoRemoveUntilQueueEnd = false
        defer { defersAutoRemoveUntilQueueEnd = wasDeferring }

        let orderedIDs = jobs.map(\.id).filter { deferredIDs.contains($0) }
        for id in orderedIDs {
            guard let index = jobs.firstIndex(where: { $0.id == id }) else { continue }
            await autoRemoveFinishedJobIfNeeded(at: index)
        }
    }

    private func runAutoRemoveHookIfNeeded(for job: DownloadJob) async throws {
        let template = autoRemoveHookCommand.trimmed
        guard !template.isEmpty else {
            autoRemoveHookStatus = "자동 제거 후크 꺼짐"
            return
        }

        let context = Self.hookNameTemplateContext(for: job)
        let arguments = try Self.splitHookCommand(template).map {
            Self.expandedHookCommandToken($0, context: context)
        }
        guard let command = arguments.first, !command.trimmed.isEmpty else {
            throw NativeDownloadError.unsupported("Auto-remove hook command is empty.")
        }
        guard let executable = Self.executableURL(forHookCommand: command) else {
            throw NativeDownloadError.unsupported("Auto-remove hook executable was not found: \(command)")
        }

        try AppPaths.ensureDirectory(AppPaths.applicationSupportDirectory)
        let logURL = AppPaths.applicationSupportDirectory.appendingPathComponent("auto-remove-hook.log")
        autoRemoveHookStatus = "자동 제거 후크 실행 중"
        try await ExternalProcessRunner.run(
            executable: executable,
            arguments: Array(arguments.dropFirst()),
            logURL: logURL,
            currentDirectoryURL: Self.hookWorkingDirectory(for: job),
            failureDescription: "Auto-remove hook"
        )
        autoRemoveHookStatus = "자동 제거 후크 완료"
    }

    private nonisolated static func splitHookCommand(_ template: String) throws -> [String] {
        var result: [String] = []
        var current = ""
        var quote: Character?
        var index = template.startIndex

        func appendCurrent() {
            if !current.isEmpty {
                result.append(current)
                current = ""
            }
        }

        while index < template.endIndex {
            let character = template[index]

            if character == "\\" {
                let nextIndex = template.index(after: index)
                if nextIndex < template.endIndex {
                    current.append(template[nextIndex])
                    index = template.index(after: nextIndex)
                } else {
                    current.append(character)
                    index = nextIndex
                }
                continue
            }

            if character == "\"" || character == "'" {
                if quote == nil {
                    quote = character
                    index = template.index(after: index)
                    continue
                }
                if quote == character {
                    quote = nil
                    index = template.index(after: index)
                    continue
                }
            }

            if quote == nil && Self.isHookCommandWhitespace(character) {
                appendCurrent()
                index = template.index(after: index)
                continue
            }

            current.append(character)
            index = template.index(after: index)
        }

        guard quote == nil else {
            throw NativeDownloadError.unsupported("Auto-remove hook has an unterminated quote.")
        }

        appendCurrent()
        return result
    }

    private nonisolated static func expandedHookCommandToken(_ token: String, context: NameTemplateContext) -> String {
        NameTemplate.string(template: token, context: context)
    }

    private nonisolated static func hookNameTemplateContext(for job: DownloadJob) -> NameTemplateContext {
        let sourceURL = URL(string: job.source)
        let outputURL = job.outputPath.isEmpty ? nil : URL(fileURLWithPath: job.outputPath)
        let outputDirectory = outputURL.flatMap { hookOutputDirectory(for: $0) }
        let metadata = hookCommandMetadata(for: job, sourceURL: sourceURL, outputURL: outputURL, outputDirectory: outputDirectory)
        let safeFilename = outputURL?.lastPathComponent ?? metadata["filename"] ?? job.title
        let basename = outputURL?.deletingPathExtension().lastPathComponent ?? metadata["basename"] ?? (safeFilename as NSString).deletingPathExtension
        let ext = outputURL?.pathExtension ?? metadata["ext"] ?? ""

        return NameTemplateContext(
            title: job.title,
            site: metadata["site"] ?? "",
            host: metadata["host"] ?? "",
            date: metadata["download_completed_at"] ?? metadata["date"] ?? dateFolderName(),
            id: job.id.uuidString,
            url: job.source,
            path: sourceURL?.path ?? metadata["path"] ?? "",
            slug: metadata["slug"] ?? sourceURL?.lastPathComponent ?? "",
            query: sourceURL?.query ?? metadata["query"] ?? "",
            filename: safeFilename,
            basename: basename,
            ext: ext,
            index: nil,
            total: job.total > 0 ? job.total : nil,
            metadata: metadata
        )
    }

    private nonisolated static func hookCommandMetadata(
        for job: DownloadJob,
        sourceURL: URL?,
        outputURL: URL?,
        outputDirectory: URL?
    ) -> [String: String] {
        let host = sourceURL?.host ?? ""
        let outputPath = outputURL?.path ?? job.outputPath
        let filename = outputURL?.lastPathComponent ?? ""
        let basename = outputURL?.deletingPathExtension().lastPathComponent ?? ""
        let ext = outputURL?.pathExtension ?? ""

        var metadata = job.metadata
        let sourceID = sourceURL.flatMap(sourceIdentifierValue) ?? ""

        let replacements: [String: String] = [
            "id": job.id.uuidString,
            "job_id": job.id.uuidString,
            "source_id": sourceID,
            "url": job.source,
            "source": job.source,
            "title": job.title,
            "status": job.status.rawValue,
            "message": job.message,
            "comment": job.comment,
            "output": outputPath,
            "outputPath": outputPath,
            "outputDir": outputDirectory?.path ?? "",
            "filename": filename,
            "basename": basename,
            "ext": ext,
            "host": host,
            "site": job.metadata["site"] ?? host,
            "path": sourceURL?.path ?? "",
            "query": sourceURL?.query ?? "",
            "completed": String(job.completed),
            "total": String(job.total),
            "progress": String(job.progress),
            "format": job.metadata["format"] ?? ext
        ]

        for (key, value) in replacements {
            metadata[key] = value
        }
        return metadata
    }

    private nonisolated static func sourceIdentifierValue(for url: URL) -> String {
        let basename = url.deletingPathExtension().lastPathComponent
        if !basename.isEmpty { return basename }
        if !url.lastPathComponent.isEmpty { return url.lastPathComponent }
        return url.host ?? ""
    }

    private nonisolated static func hookWorkingDirectory(for job: DownloadJob) -> URL? {
        guard !job.outputPath.isEmpty else { return nil }
        return hookOutputDirectory(for: URL(fileURLWithPath: job.outputPath))
    }

    private nonisolated static func hookOutputDirectory(for url: URL) -> URL {
        var isDirectory: ObjCBool = false
        if FileManager.default.fileExists(atPath: url.path, isDirectory: &isDirectory), isDirectory.boolValue {
            return url
        }
        return url.deletingLastPathComponent()
    }

    private nonisolated static func executableURL(forHookCommand command: String) -> URL? {
        let fileManager = FileManager.default
        let expanded = (command as NSString).expandingTildeInPath

        if expanded.contains("/") {
            let url = URL(fileURLWithPath: expanded)
            return fileManager.isExecutableFile(atPath: url.path) ? url : nil
        }

        let paths = (ProcessInfo.processInfo.environment["PATH"] ?? "")
            .components(separatedBy: ":")
            .filter { !$0.isEmpty }

        for folder in paths {
            let candidate = URL(fileURLWithPath: folder).appendingPathComponent(expanded)
            if fileManager.isExecutableFile(atPath: candidate.path) {
                return candidate
            }
        }

        return nil
    }

    private nonisolated static func autoRemoveHookErrorMessage(_ error: Error) -> String {
        let text = String(describing: error).trimmed
        return text.isEmpty ? "unknown error" : text
    }

    private nonisolated static func isHookCommandWhitespace(_ character: Character) -> Bool {
        character.unicodeScalars.allSatisfy { CharacterSet.whitespacesAndNewlines.contains($0) }
    }

    private func resetQueueRunAlertState() {
        queueRunFinishedJobIDs.removeAll()
        queueRunFailedJobIDs.removeAll()
    }

    private func handleQueueRunCompleted() {
        let finished = queueRunFinishedJobIDs.count
        let failed = queueRunFailedJobIDs.subtracting(queueRunFinishedJobIDs).count
        guard finished + failed > 0 else {
            resetQueueRunAlertState()
            return
        }

        let summary = Self.completionQueueSummary(finished: finished, failed: failed)
        recordActivity("Queue complete: \(summary)", category: "Queue")
        if notifyWhenQueueCompletes {
            completionAlerts.notifyQueueFinished(summary: summary)
        }
        performQueueCompletionAction(summary: summary)
        resetQueueRunAlertState()
    }

    private func performQueueCompletionAction(summary: String) {
        switch queueCompletionAction {
        case .none:
            queueCompletionActionStatus = Self.queueCompletionActionStatusText(for: .none)
        case .openDestination:
            queueCompletionActionStatus = AppLocalization.format(
                "After completion: Open Folder (%@)",
                language: interfaceLanguage,
                summary
            )
            guard ProcessInfo.processInfo.environment["HITOMI_NATIVE_SKIP_QUEUE_COMPLETION_ACTION"] != "1" else { return }
            NSWorkspace.shared.open(URL(fileURLWithPath: destinationPath, isDirectory: true))
        case .quitApp:
            queueCompletionActionStatus = AppLocalization.format(
                "After completion: Quit App (%@)",
                language: interfaceLanguage,
                summary
            )
            guard ProcessInfo.processInfo.environment["HITOMI_NATIVE_SKIP_QUEUE_COMPLETION_ACTION"] != "1" else { return }
            NSApplication.shared.terminate(nil)
        }
    }

    nonisolated static func queueCompletionActionStatusText(for action: QueueCompletionAction) -> String {
        AppLocalization.format(
            "After completion: %@",
            AppLocalization.text(action == .none ? "Do Nothing" : action.label)
        )
    }

    nonisolated static func completionQueueSummary(finished: Int, failed: Int) -> String {
        let finished = max(0, finished)
        let failed = max(0, failed)
        let pieces = [
            finished > 0 ? AppLocalization.format("%@ finished", String(finished)) : nil,
            failed > 0 ? AppLocalization.format("%@ failed", String(failed)) : nil
        ].compactMap { $0 }
        return pieces.isEmpty
            ? AppLocalization.text("No completed queue tasks")
            : pieces.joined(separator: AppLocalization.text(", "))
    }

    @discardableResult
    private func markJobFinished(at index: Int) -> Bool {
        guard jobs.indices.contains(index) else { return false }
        let pausedActive = isPausedActiveJob(jobs[index])
        guard canMarkJobFinished(at: index) else {
            addSummary = jobs[index].status == .finished
                ? "Job is already finished"
                : "Pause or cancel active jobs before marking finished"
            return false
        }

        let jobID = jobs[index].id
        if pausedActive {
            terminateRuntimeControlForManualCompletion(jobID: jobID)
        }
        retrySnapshots.removeValue(forKey: jobID)
        cancelScheduledRestart(for: jobID)

        let total = max(1, jobs[index].total, jobs[index].completed)
        jobs[index].status = .finished
        jobs[index].progress = 1
        jobs[index].completed = total
        jobs[index].total = total
        jobs[index].message = "Marked finished manually"
        jobs[index].metadata.removeValue(forKey: "last_error")
        jobs[index].metadata["manual_completion"] = "true"
        if pausedActive {
            jobs[index].metadata["aria2_runtime_paused"] = "false"
        }
        jobs[index].metadata["manual_completed_at"] = ISO8601DateFormatter().string(from: Date())
        addSummary = "Job marked finished"
        completeManuallyFinishedJob(at: index)
        Task { @MainActor [weak self] in
            await self?.enrichCompletedJobMetadata(for: jobID)
            self?.persistQueue()
        }
        return true
    }

    private func canMarkJobFinished(at index: Int) -> Bool {
        guard jobs.indices.contains(index) else { return false }
        let job = jobs[index]
        guard job.status != .finished else { return false }
        if !isActive(job.status) {
            return true
        }
        return isPausedActiveJob(job)
    }

    private func isPausedActiveJob(_ job: DownloadJob) -> Bool {
        isActive(job.status) &&
            (aria2RuntimePausedJobIDs.contains(job.id) || job.metadata["aria2_runtime_paused"] == "true")
    }

    private func terminateRuntimeControlForManualCompletion(jobID: UUID) {
        aria2RuntimeProcesses[jobID]?.terminate()
        cleanupAria2RuntimeControl(for: jobID)
    }

    private func isManuallyFinishedJob(at index: Int) -> Bool {
        jobs.indices.contains(index) &&
            jobs[index].status == .finished &&
            jobs[index].metadata["manual_completion"] == "true"
    }

    func scheduleRestartIfNeeded(for job: DownloadJob) {
        guard let index = jobs.firstIndex(where: { $0.id == job.id }) else { return }
        let current = jobs[index]
        guard current.status == .finished,
              let delay = configuredRestartDelaySeconds(for: current) else {
            cancelScheduledRestart(for: current.id)
            return
        }

        let storedKind = current.metadata[Self.scheduledRetryKindMetadataKey]
            .flatMap(ScheduledRetryKind.init(rawValue:))
        let storedDelay = current.metadata[Self.scheduledRetryDelayMetadataKey]
            .flatMap(Double.init)
        let existingTarget = Self.scheduledRetryTimestamp(for: current)
        let target: TimeInterval
        if storedKind == .restart,
           let storedDelay,
           abs(storedDelay - delay) < 0.001,
           let existingTarget {
            target = existingTarget
        } else {
            target = Date().timeIntervalSince1970 + delay
        }

        _ = scheduleRetry(
            for: current.id,
            at: target,
            kind: .restart,
            force: false,
            delay: delay,
            announce: true,
            persist: true
        )
    }

    func hasScheduledRestart(for job: DownloadJob) -> Bool {
        restartTasks[job.id] != nil
    }

    func restoreScheduledRetries() {
        var changed = false
        for jobID in jobs.map(\.id) {
            changed = restoreScheduledRetryIfNeeded(for: jobID) || changed
        }
        if changed {
            persistQueue()
        }
    }

    @discardableResult
    private func restoreScheduledRetryIfNeeded(for jobID: UUID) -> Bool {
        guard let index = jobs.firstIndex(where: { $0.id == jobID }) else { return false }
        let job = jobs[index]
        if let target = Self.scheduledRetryTimestamp(for: job) {
            let kind = scheduledRetryKind(for: job)
            let delay = job.metadata[Self.scheduledRetryDelayMetadataKey].flatMap(Double.init)
            let force = Self.metadataBool(job.metadata[Self.scheduledRetryForceMetadataKey])
            return scheduleRetry(
                for: jobID,
                at: target,
                kind: kind,
                force: force,
                delay: delay,
                announce: false,
                persist: false
            )
        }

        guard job.status == .finished,
              let delay = configuredRestartDelaySeconds(for: job) else {
            return false
        }
        return scheduleRetry(
            for: jobID,
            at: Date().timeIntervalSince1970 + delay,
            kind: .restart,
            force: false,
            delay: delay,
            announce: false,
            persist: false
        )
    }

    @discardableResult
    private func scheduleRetry(
        for jobID: UUID,
        at target: TimeInterval,
        kind: ScheduledRetryKind,
        force: Bool,
        delay: TimeInterval?,
        announce: Bool,
        persist: Bool
    ) -> Bool {
        guard target.isFinite, target > 1,
              let index = jobs.firstIndex(where: { $0.id == jobID }),
              Self.isScheduledRetryEligible(jobs[index], kind: kind) else {
            return false
        }

        stopScheduledRetryTask(for: jobID)
        let originalTitle = Self.scheduledRetryOriginalTitle(for: jobs[index])
        jobs[index].metadata[Self.scheduledRetryTimestampMetadataKey] = Self.retryTimestampString(target)
        jobs[index].metadata[Self.scheduledRetryOriginalTitleMetadataKey] = originalTitle
        jobs[index].metadata[Self.scheduledRetryKindMetadataKey] = kind.rawValue
        jobs[index].metadata[Self.scheduledRetryForceMetadataKey] = force ? "true" : "false"
        if let delay {
            jobs[index].metadata[Self.scheduledRetryDelayMetadataKey] = Self.retryTimestampString(delay)
        } else {
            jobs[index].metadata.removeValue(forKey: Self.scheduledRetryDelayMetadataKey)
        }
        updateScheduledRetryCountdown(for: jobID, target: target)

        restartTasks[jobID] = Task { @MainActor [weak self] in
            while !Task.isCancelled {
                guard let self,
                      let currentIndex = self.jobs.firstIndex(where: { $0.id == jobID }),
                      let currentTarget = Self.scheduledRetryTimestamp(for: self.jobs[currentIndex]),
                      abs(currentTarget - target) < 0.001 else {
                    return
                }

                if Self.retryRemainingSeconds(target: currentTarget) <= 0 {
                    self.runScheduledRestart(for: jobID)
                    return
                }

                self.updateScheduledRetryCountdown(for: jobID, target: currentTarget)
                do {
                    try await Task.sleep(nanoseconds: 1_000_000_000)
                } catch {
                    return
                }
            }
        }

        if announce {
            addSummary = kind == .restart
                ? "Restart scheduled in \(Self.restartDelayDescription(for: max(0, target - Date().timeIntervalSince1970)))"
                : "Retry scheduled in \(Self.restartDelayDescription(for: max(0, target - Date().timeIntervalSince1970)))"
        }
        if persist {
            persistQueue()
        }
        return true
    }

    private func updateScheduledRetryCountdown(for jobID: UUID, target: TimeInterval) {
        guard let index = jobs.firstIndex(where: { $0.id == jobID }),
              let title = Self.scheduledRetryCountdownTitle(
                target: target,
                identifier: Self.scheduledRetryIdentifier(for: jobs[index])
              ) else {
            return
        }
        jobs[index].title = title
    }

    private func runScheduledRestart(for jobID: UUID) {
        guard let index = jobs.firstIndex(where: { $0.id == jobID }),
              let target = Self.scheduledRetryTimestamp(for: jobs[index]),
              Self.retryRemainingSeconds(target: target) <= 0 else {
            return
        }

        let kind = scheduledRetryKind(for: jobs[index])
        guard Self.isScheduledRetryEligible(jobs[index], kind: kind),
              kind != .restart || configuredRestartDelaySeconds(for: jobs[index]) != nil else {
            cancelScheduledRestart(for: jobID)
            persistQueue()
            return
        }

        stopScheduledRetryTask(for: jobID)
        clearScheduledRetryState(at: index, restoreTitle: true)
        queueJobForRetry(at: index)
        addSummary = kind == .restart ? "Restart timer queued job" : "Delayed retry queued job"
        persistQueue()
        startQueue(addingInput: false)
    }

    private func cancelScheduledRestart(for jobID: UUID) {
        stopScheduledRetryTask(for: jobID)
        guard let index = jobs.firstIndex(where: { $0.id == jobID }) else { return }
        clearScheduledRetryState(at: index, restoreTitle: true)
    }

    private func cancelAllScheduledRestarts() {
        restartTasks.values.forEach { $0.cancel() }
        restartTasks.removeAll()
    }

    private func stopScheduledRetryTask(for jobID: UUID) {
        restartTasks.removeValue(forKey: jobID)?.cancel()
    }

    private func clearScheduledRetryState(at index: Int, restoreTitle: Bool) {
        guard jobs.indices.contains(index) else { return }
        if restoreTitle {
            let originalTitle = Self.scheduledRetryOriginalTitle(for: jobs[index])
            if !originalTitle.trimmed.isEmpty {
                jobs[index].title = originalTitle
            }
        }
        jobs[index].metadata.removeValue(forKey: Self.scheduledRetryTimestampMetadataKey)
        jobs[index].metadata.removeValue(forKey: Self.scheduledRetryOriginalTitleMetadataKey)
        jobs[index].metadata.removeValue(forKey: Self.scheduledRetryKindMetadataKey)
        jobs[index].metadata.removeValue(forKey: Self.scheduledRetryDelayMetadataKey)
        jobs[index].metadata.removeValue(forKey: Self.scheduledRetryForceMetadataKey)
    }

    nonisolated static func restartDelaySeconds(from comment: String) -> TimeInterval? {
        OriginalRuntimeCompatibility.restartDelaySeconds(from: comment)
    }

    nonisolated static func restartDelaySeconds(for job: DownloadJob) -> TimeInterval? {
        restartDelaySeconds(from: job.comment)
            ?? restartDelaySeconds(from: job.metadata["group_comment"] ?? "")
    }

    nonisolated static func taskTagRestartDelaySeconds(
        for tags: [String],
        timers: [String: Int]
    ) -> TimeInterval? {
        TaskTagColor.normalizedRawValues(tags)
            .compactMap { timers[$0] }
            .filter { $0 > 0 }
            .min()
            .map(TimeInterval.init)
    }

    func configuredRestartDelaySeconds(for job: DownloadJob) -> TimeInterval? {
        Self.restartDelaySeconds(for: job)
            ?? Self.taskTagRestartDelaySeconds(for: job.tags, timers: taskTagRestartTimers)
    }

    nonisolated static func scheduledRetryTimestamp(for job: DownloadJob) -> TimeInterval? {
        scheduledRetryTimestamp(from: job.metadata)
    }

    nonisolated static func scheduledRetryTimestamp(from metadata: [String: String]) -> TimeInterval? {
        guard let raw = metadata[scheduledRetryTimestampMetadataKey]?.trimmed,
              let value = Double(raw),
              value.isFinite,
              value > 1 else {
            return nil
        }
        return value
    }

    nonisolated static func retryRemainingSeconds(
        target: TimeInterval,
        now: TimeInterval = Date().timeIntervalSince1970
    ) -> Int {
        max(0, Int(target - now + 0.5))
    }

    nonisolated static func scheduledRetryCountdownTitle(
        target: TimeInterval,
        now: TimeInterval = Date().timeIntervalSince1970,
        identifier: String
    ) -> String? {
        let total = retryRemainingSeconds(target: target, now: now)
        guard total > 0 else { return nil }
        let days = total / 86_400
        let hours = (total % 86_400) / 3_600
        let minutes = (total % 3_600) / 60
        let seconds = total % 60
        if days > 0 {
            return "\(days)일 \(hours)시간 \(minutes)분 \(seconds)초 뒤 다시 시작: \(identifier)"
        }
        if hours > 0 {
            return "\(hours)시간 \(minutes)분 \(seconds)초 뒤 다시 시작: \(identifier)"
        }
        if minutes > 0 {
            return "\(minutes)분 \(seconds)초 뒤 다시 시작: \(identifier)"
        }
        return "\(seconds)초 뒤 다시 시작: \(identifier)"
    }

    private nonisolated static func scheduledRetryOriginalTitle(for job: DownloadJob) -> String {
        for key in [scheduledRetryOriginalTitleMetadataKey, "title0", "original_title"] {
            if let value = job.metadata[key]?.trimmed, !value.isEmpty {
                return value
            }
        }
        return job.title.trimmed.isEmpty ? job.source : job.title
    }

    private nonisolated static func scheduledRetryIdentifier(for job: DownloadJob) -> String {
        let releaseTimestamp = [
            job.metadata["release_timestamp"],
            job.metadata["hdt_release_timestamp"]
        ].compactMap { $0?.trimmed }.first { !$0.isEmpty }
        if releaseTimestamp != nil {
            let galleryID = [
                job.metadata["gallery_id"],
                job.metadata["gallery_number"],
                job.metadata["hdt_gallery_number"],
                job.metadata["gal_num"]
            ].compactMap { $0?.trimmed }.first { !$0.isEmpty }
            if let galleryID {
                return galleryID.replacingOccurrences(of: "#-*-", with: "")
            }
        }
        return scheduledRetryOriginalTitle(for: job)
    }

    private func scheduledRetryKind(for job: DownloadJob) -> ScheduledRetryKind {
        if let raw = job.metadata[Self.scheduledRetryKindMetadataKey]?.trimmed,
           let kind = ScheduledRetryKind(rawValue: raw) {
            return kind
        }
        if job.metadata["release_timestamp"]?.trimmed.isEmpty == false ||
            job.metadata["hdt_release_timestamp"]?.trimmed.isEmpty == false {
            return .release
        }
        if job.status == .finished, configuredRestartDelaySeconds(for: job) != nil {
            return .restart
        }
        return .imported
    }

    private nonisolated static func isScheduledRetryEligible(
        _ job: DownloadJob,
        kind: ScheduledRetryKind
    ) -> Bool {
        guard job.status != .resolving, job.status != .downloading else { return false }
        if kind == .restart {
            return job.status == .finished
        }
        return true
    }

    private nonisolated static func retryTimestampString(_ value: TimeInterval) -> String {
        if value.rounded() == value,
           value >= Double(Int64.min),
           value <= Double(Int64.max) {
            return String(Int64(value))
        }
        return String(format: "%.6f", value)
            .replacingOccurrences(of: #"0+$"#, with: "", options: .regularExpression)
            .replacingOccurrences(of: #"\.$"#, with: "", options: .regularExpression)
    }

    private nonisolated static func metadataBool(_ raw: String?) -> Bool {
        guard let raw = raw?.trimmed.lowercased() else { return false }
        return ["1", "true", "yes", "on"].contains(raw)
    }

    private nonisolated static func restartDelayDescription(for seconds: TimeInterval) -> String {
        let totalSeconds = max(0, Int(seconds.rounded()))
        let hours = totalSeconds / 3_600
        let minutes = (totalSeconds % 3_600) / 60
        let seconds = totalSeconds % 60
        if hours > 0 {
            return seconds > 0 ? "\(hours)h \(minutes)m \(seconds)s" : "\(hours)h \(minutes)m"
        }
        if minutes > 0 {
            return seconds > 0 ? "\(minutes)m \(seconds)s" : "\(minutes)m"
        }
        return "\(seconds)s"
    }

    private func recordHistory(for index: Int) {
        guard jobs.indices.contains(index) else { return }
        guard historyEnabled else { return }
        let job = jobs[index]
        let normalized = Self.normalizedHistorySource(for: job)
        history.removeAll {
            Self.duplicateKey(source: $0.source, normalizedSource: $0.normalizedSource, metadata: $0.metadata) ==
                Self.duplicateKey(source: job.source, normalizedSource: normalized, metadata: job.metadata)
        }
        history.insert(DownloadHistoryEntry(
            id: UUID(),
            source: job.source,
            normalizedSource: normalized,
            title: job.title,
            outputPath: job.outputPath,
            completedAt: Date(),
            metadata: job.metadata
        ), at: 0)
        trimHistoryToLimit()
        userData.history = history
        persistUserData()
    }

    private func persistHistorySettings() {
        UserDefaults.standard.set(historyEnabled, forKey: "historyEnabled")
        let limit = normalizedHistoryLimit(from: historyLimitString)
        historyLimitString = String(limit)
        UserDefaults.standard.set(limit, forKey: "historyLimit")
    }

    private func persistCompletionAlertSettings() {
        UserDefaults.standard.set(notifyWhenJobCompletes, forKey: "notifyWhenJobCompletes")
        UserDefaults.standard.set(notifyWhenQueueCompletes, forKey: "notifyWhenQueueCompletes")
        UserDefaults.standard.set(playSoundWhenJobCompletes, forKey: "playSoundWhenJobCompletes")
        UserDefaults.standard.set(playSoundOnClipboardAdd, forKey: "playSoundOnClipboardAdd")
        UserDefaults.standard.set(queueCompletionAction.rawValue, forKey: "queueCompletionAction")
    }

    private func persistArchiveSettings() {
        UserDefaults.standard.set(archiveCompletedFolders, forKey: "archiveCompletedFolders")
        UserDefaults.standard.set(archiveFileFormat.rawValue, forKey: "archiveFileFormat")
        UserDefaults.standard.set(deleteOriginalFolderAfterArchiving && archiveCompletedFolders, forKey: "deleteOriginalFolderAfterArchiving")
        UserDefaults.standard.set(hideArchiveIndicatorWhenFileMissing, forKey: "hideArchiveIndicatorWhenFileMissing")
    }

    private func persistSourceArchiveSettings() {
        Self.persistSourceArchiveSettings(
            modes: sourceArchiveModes,
            deleteOriginal: sourceArchiveDeleteOriginal,
            defaults: .standard
        )
    }

    private static func loadSourceArchiveSettings(
        defaults: UserDefaults,
        legacyArchiveEnabled: Bool,
        legacyFormat: ArchiveFileFormat,
        legacyDeleteOriginal: Bool
    ) -> (modes: [String: SourceArchiveMode], deleteOriginal: [String: Bool], didMigrate: Bool) {
        var modes: [String: SourceArchiveMode] = [:]
        if let storedModes = defaults.dictionary(forKey: "sourceArchiveModes") {
            for (sourceID, value) in storedModes {
                guard let rawValue = value as? String,
                      let mode = SourceArchiveMode(rawValue: rawValue) else {
                    continue
                }
                modes[DownloadSourceFolderProfile.normalizedSourceID(sourceID)] = mode
            }
        }
        if let originalModes = originalArchiveModeDictionary(defaults.string(forKey: "zip_ext")) {
            for (sourceID, index) in originalModes where modes[DownloadSourceFolderProfile.normalizedSourceID(sourceID)] == nil {
                modes[DownloadSourceFolderProfile.normalizedSourceID(sourceID)] = SourceArchiveMode(originalIndex: index)
            }
        }

        var deleteOriginal: [String: Bool] = [:]
        if let storedDeleteOriginal = defaults.dictionary(forKey: "sourceArchiveDeleteOriginal") {
            for (sourceID, value) in storedDeleteOriginal {
                guard let enabled = value as? Bool else { continue }
                deleteOriginal[DownloadSourceFolderProfile.normalizedSourceID(sourceID)] = enabled
            }
        }
        if let originalDeleteOriginal = originalArchiveDeleteDictionary(defaults.string(forKey: "zip_rm")) {
            for (sourceID, enabled) in originalDeleteOriginal
                where deleteOriginal[DownloadSourceFolderProfile.normalizedSourceID(sourceID)] == nil {
                deleteOriginal[DownloadSourceFolderProfile.normalizedSourceID(sourceID)] = enabled
            }
        }

        let didMigrate = defaults.integer(forKey: "sourceArchiveSettingsVersion") < 1
        if didMigrate && legacyArchiveEnabled {
            let legacyMode: SourceArchiveMode = legacyFormat == .cbz ? .cbz : .zip
            for profile in DownloadSourceFolderProfile.settingsProfiles where profile.supportsFolderArchive {
                if modes[profile.id] == nil {
                    modes[profile.id] = legacyMode
                }
                if deleteOriginal[profile.id] == nil {
                    deleteOriginal[profile.id] = legacyDeleteOriginal
                }
            }
        }

        return (modes, deleteOriginal, didMigrate)
    }

    private static func persistSourceArchiveSettings(
        modes: [String: SourceArchiveMode],
        deleteOriginal: [String: Bool],
        defaults: UserDefaults
    ) {
        let rawModes = modes.mapValues(\.rawValue)
        let originalModes = modes.mapValues(\.originalIndex)
        defaults.set(rawModes, forKey: "sourceArchiveModes")
        defaults.set(deleteOriginal, forKey: "sourceArchiveDeleteOriginal")
        defaults.set(originalArchiveJSONString(originalModes), forKey: "zip_ext")
        defaults.set(originalArchiveJSONString(deleteOriginal), forKey: "zip_rm")
        defaults.set(1, forKey: "sourceArchiveSettingsVersion")
    }

    private static func originalArchiveModeDictionary(_ json: String?) -> [String: Int]? {
        guard let json, let data = json.data(using: .utf8) else { return nil }
        return try? JSONDecoder().decode([String: Int].self, from: data)
    }

    private static func originalArchiveDeleteDictionary(_ json: String?) -> [String: Bool]? {
        guard let json, let data = json.data(using: .utf8) else { return nil }
        return try? JSONDecoder().decode([String: Bool].self, from: data)
    }

    private static func originalArchiveJSONString<T: Encodable>(_ value: T) -> String {
        let encoder = JSONEncoder()
        encoder.outputFormatting = [.sortedKeys]
        guard let data = try? encoder.encode(value),
              let string = String(data: data, encoding: .utf8) else {
            return "{}"
        }
        return string
    }

    private func persistImageConversionFormat() {
        UserDefaults.standard.set(imageConversionFormat.rawValue, forKey: "imageConversionFormat")
    }

    private func trimHistoryToLimit() {
        let limit = normalizedHistoryLimit(from: historyLimitString)
        if history.count > limit {
            history.removeSubrange(limit..<history.count)
        }
    }

    private nonisolated static func normalizedHistoryLimit(from raw: String) -> Int {
        let value = Int(raw.trimmed) ?? 1_000
        return min(5_000, max(1, value))
    }

    private func normalizedHistoryLimit(from raw: String) -> Int {
        Self.normalizedHistoryLimit(from: raw)
    }

    nonisolated static func duplicateImageGroups(
        in root: URL,
        similarityPercent: Int = 100,
        excludeSameSource: Bool = false
    ) throws -> [DuplicateImageGroup] {
        try duplicateImageGroups(in: [root], similarityPercent: similarityPercent, excludeSameSource: excludeSameSource)
    }

    nonisolated static func duplicateImageGroups(
        in roots: [URL],
        similarityPercent: Int = 100,
        excludeSameSource: Bool = false
    ) throws -> [DuplicateImageGroup] {
        let scanRoots = normalizedDuplicateImageFolderPaths(roots.map(\.path))
            .map { URL(fileURLWithPath: $0, isDirectory: true) }
        guard !scanRoots.isEmpty else {
            throw NativeDownloadError.unsupported("Output folder is unavailable.")
        }

        for root in scanRoots {
            var isDirectory: ObjCBool = false
            guard FileManager.default.fileExists(atPath: root.path, isDirectory: &isDirectory),
                  isDirectory.boolValue else {
                throw NativeDownloadError.unsupported("Scan folder is unavailable: \(root.path)")
            }
        }

        let normalizedSimilarity = normalizedDuplicateImageSimilarityPercent(similarityPercent)
        let candidates = try scanRoots.flatMap {
            try duplicateImageCandidates(in: $0, includeVisualHash: normalizedSimilarity < 100)
        }
        var groups = try exactDuplicateImageGroups(from: candidates)
        if normalizedSimilarity < 100 {
            let existingKeys = Set(groups.map { duplicateImageFileKey($0.files) })
            groups.append(contentsOf: visualDuplicateImageGroups(
                from: candidates,
                similarityPercent: normalizedSimilarity,
                existingFileKeys: existingKeys
            ))
        }
        if excludeSameSource {
            let sourceKeys = Dictionary(uniqueKeysWithValues: candidates.map { ($0.url.path, $0.sourceKey) })
            groups = groups.compactMap { duplicateImageGroupExcludingSameSource($0, sourceKeysByPath: sourceKeys) }
        }

        return groups.sorted {
            if $0.files.count != $1.files.count { return $0.files.count > $1.files.count }
            if ($0.similarityPercent ?? 100) != ($1.similarityPercent ?? 100) {
                return ($0.similarityPercent ?? 100) > ($1.similarityPercent ?? 100)
            }
            return ($0.files.first ?? "").localizedStandardCompare($1.files.first ?? "") == .orderedAscending
        }
    }

    nonisolated static func duplicateImageFolderURL(forPath path: String, fileManager: FileManager = .default) -> URL? {
        let value = path.trimmed
        guard !value.isEmpty else { return nil }

        let url = URL(fileURLWithPath: value)
        var isDirectory = ObjCBool(false)
        if fileManager.fileExists(atPath: url.path, isDirectory: &isDirectory) {
            return isDirectory.boolValue ? url : url.deletingLastPathComponent()
        }

        let parent = url.deletingLastPathComponent()
        guard parent.path != url.path else { return nil }
        var parentIsDirectory = ObjCBool(false)
        guard fileManager.fileExists(atPath: parent.path, isDirectory: &parentIsDirectory),
              parentIsDirectory.boolValue else {
            return nil
        }
        return parent
    }

    private nonisolated static func duplicateImageSelection(
        current: String,
        groups: [DuplicateImageGroup],
        minimumSimilarityPercent: Int
    ) -> (selectedPath: String, autoSelectedPath: String) {
        let currentSelection = validDuplicateImageSelection(current: current, groups: groups)
        let autoSelection = duplicateImageAutoSelectionCandidate(
            in: groups,
            minimumSimilarityPercent: minimumSimilarityPercent
        ) ?? ""
        if !currentSelection.isEmpty {
            return (currentSelection, autoSelection)
        }
        if !autoSelection.isEmpty {
            return (autoSelection, autoSelection)
        }
        return (groups.flatMap(\.files).first ?? "", "")
    }

    private nonisolated static func validDuplicateImageSelection(current: String, groups: [DuplicateImageGroup]) -> String {
        let value = current.trimmed
        guard !value.isEmpty else { return "" }
        let files = groups.flatMap(\.files)
        return files.contains(value) ? value : ""
    }

    nonisolated static func duplicateImageAutoSelectionCandidate(
        in groups: [DuplicateImageGroup],
        minimumSimilarityPercent: Int,
        fileManager: FileManager = .default
    ) -> String? {
        let threshold = normalizedDuplicateImageSimilarityPercent(minimumSimilarityPercent)
        for group in groups where duplicateImageSimilarityPercent(for: group) >= threshold {
            if let path = duplicateImageAutoSelectionCandidate(in: group, fileManager: fileManager) {
                return path
            }
        }
        return nil
    }

    private nonisolated static func duplicateImageAutoSelectionCandidate(
        in group: DuplicateImageGroup,
        fileManager: FileManager
    ) -> String? {
        group.files.enumerated().max { lhs, rhs in
            let lhsDate = duplicateImageModificationDate(forPath: lhs.element, fileManager: fileManager)
            let rhsDate = duplicateImageModificationDate(forPath: rhs.element, fileManager: fileManager)
            if lhsDate != rhsDate {
                return lhsDate < rhsDate
            }
            return lhs.offset < rhs.offset
        }?.element
    }

    private nonisolated static func duplicateImageModificationDate(
        forPath path: String,
        fileManager: FileManager
    ) -> Date {
        let attributes = try? fileManager.attributesOfItem(atPath: path)
        return (attributes?[.modificationDate] as? Date) ?? .distantPast
    }

    private nonisolated static func duplicateImageSimilarityPercent(for group: DuplicateImageGroup) -> Int {
        min(100, max(0, group.similarityPercent ?? 100))
    }

    private nonisolated static func exactDuplicateImageGroups(from candidates: [DuplicateImageCandidate]) throws -> [DuplicateImageGroup] {
        let sameSizeCandidates = Dictionary(grouping: candidates, by: \.byteCount)
            .values
            .filter { $0.count > 1 }

        var byHash: [String: [DuplicateImageCandidate]] = [:]
        for group in sameSizeCandidates {
            for candidate in group {
                let hash = try sha256Hex(for: candidate.url)
                byHash[hash, default: []].append(candidate)
            }
        }

        return byHash.compactMap { hash, candidates -> DuplicateImageGroup? in
            guard candidates.count > 1 else { return nil }
            let files = candidates
                .map(\.url.path)
                .sorted { $0.localizedStandardCompare($1) == .orderedAscending }
            let dimensions = firstDuplicateImageDimensions(in: candidates)
            return DuplicateImageGroup(
                hash: hash,
                byteCount: candidates.first?.byteCount ?? 0,
                files: files,
                width: dimensions?.width,
                height: dimensions?.height,
                minByteCount: candidates.first?.byteCount,
                maxByteCount: candidates.first?.byteCount,
                similarityPercent: 100
            )
        }
    }

    private nonisolated static func firstDuplicateImageDimensions(in candidates: [DuplicateImageCandidate]) -> (width: Int, height: Int)? {
        if let dimensions = candidates.compactMap({ candidate -> (width: Int, height: Int)? in
            guard let width = candidate.width, let height = candidate.height else { return nil }
            return (width, height)
        }).first {
            return dimensions
        }

        for candidate in candidates {
            if let dimensions = imageDimensions(for: candidate.url) {
                return dimensions
            }
        }
        return nil
    }

    private nonisolated static func visualDuplicateImageGroups(
        from candidates: [DuplicateImageCandidate],
        similarityPercent: Int,
        existingFileKeys: Set<String>
    ) -> [DuplicateImageGroup] {
        let maxDistance = duplicateImageMaxHashDistance(for: similarityPercent)
        guard maxDistance > 0 else { return [] }
        let visualCandidates = candidates
            .filter { $0.visualHash != nil }
            .sorted { $0.url.path.localizedStandardCompare($1.url.path) == .orderedAscending }

        var groups: [DuplicateImageGroup] = []
        var usedPaths = Set<String>()
        for seed in visualCandidates {
            let seedPath = seed.url.path
            guard !usedPaths.contains(seedPath),
                  let seedHash = seed.visualHash else {
                continue
            }

            let matches = visualCandidates.compactMap { candidate -> (candidate: DuplicateImageCandidate, distance: Int)? in
                let path = candidate.url.path
                guard !usedPaths.contains(path),
                      let candidateHash = candidate.visualHash else {
                    return nil
                }
                let distance = hammingDistance(seedHash, candidateHash)
                guard distance <= maxDistance else { return nil }
                return (candidate, distance)
            }
            guard matches.count > 1 else { continue }

            let files = matches
                .map(\.candidate.url.path)
                .sorted { $0.localizedStandardCompare($1) == .orderedAscending }
            let fileKey = duplicateImageFileKey(files)
            guard !existingFileKeys.contains(fileKey) else { continue }

            files.forEach { usedPaths.insert($0) }
            let byteCounts = matches.map(\.candidate.byteCount)
            let minByteCount = byteCounts.min() ?? 0
            let maxByteCount = byteCounts.max() ?? minByteCount
            let representative = matches.first(where: {
                $0.candidate.width != nil && $0.candidate.height != nil
            })?.candidate ?? seed
            let worstDistance = matches.map(\.distance).max() ?? 0
            let groupSimilarity = visualHashSimilarityPercent(distance: worstDistance)
            groups.append(DuplicateImageGroup(
                hash: "visual-\(String(format: "%016llx", seedHash))",
                byteCount: minByteCount,
                files: files,
                width: representative.width,
                height: representative.height,
                minByteCount: minByteCount,
                maxByteCount: maxByteCount,
                similarityPercent: groupSimilarity
            ))
        }
        return groups
    }

    private nonisolated static func duplicateImageSummary(
        for groups: [DuplicateImageGroup],
        autoSelectedPath: String = ""
    ) -> String {
        guard !groups.isEmpty else {
            return "No duplicate images found"
        }
        let duplicateFileCount = groups.reduce(0) { $0 + max(0, $1.files.count - 1) }
        let base = "\(groups.count) duplicate groups, \(duplicateFileCount) extra files"
        let autoSelectedName = URL(fileURLWithPath: autoSelectedPath).lastPathComponent
        if !autoSelectedName.isEmpty {
            return "\(base). Auto-selected \(autoSelectedName)"
        }
        return base
    }

    private nonisolated static func duplicateImageCandidates(in root: URL, includeVisualHash: Bool = false) throws -> [DuplicateImageCandidate] {
        guard let enumerator = FileManager.default.enumerator(
            at: root,
            includingPropertiesForKeys: [.isRegularFileKey, .fileSizeKey],
            options: [.skipsHiddenFiles, .skipsPackageDescendants]
        ) else {
            return []
        }

        var candidates: [DuplicateImageCandidate] = []
        for case let url as URL in enumerator {
            guard duplicateImageExtensions.contains(url.pathExtension.lowercased()) else { continue }
            let values = try url.resourceValues(forKeys: [.isRegularFileKey, .fileSizeKey])
            guard values.isRegularFile == true,
                  let byteCount = values.fileSize,
                  byteCount > 0 else {
                continue
            }
            let dimensions = includeVisualHash ? imageDimensions(for: url) : nil
            candidates.append(DuplicateImageCandidate(
                url: url,
                sourceKey: duplicateImageSourceKey(forPath: url.path, root: root),
                byteCount: Int64(byteCount),
                width: dimensions?.width,
                height: dimensions?.height,
                visualHash: includeVisualHash ? visualImageHash(for: url) : nil
            ))
        }
        return candidates
    }

    private nonisolated static func normalizedDuplicateImageSimilarityPercent(_ percent: Int) -> Int {
        min(100, max(80, percent))
    }

    private nonisolated static func duplicateImageMaxHashDistance(for similarityPercent: Int) -> Int {
        let normalized = normalizedDuplicateImageSimilarityPercent(similarityPercent)
        guard normalized < 100 else { return 0 }
        return min(64, max(1, Int(ceil(Double(100 - normalized) * 64.0 / 100.0))))
    }

    private nonisolated static func visualHashSimilarityPercent(distance: Int) -> Int {
        let clampedDistance = min(64, max(0, distance))
        return min(100, max(0, Int(((64 - clampedDistance) * 100 + 32) / 64)))
    }

    private nonisolated static func hammingDistance(_ lhs: UInt64, _ rhs: UInt64) -> Int {
        (lhs ^ rhs).nonzeroBitCount
    }

    private nonisolated static func duplicateImageFileKey(_ files: [String]) -> String {
        files.sorted { $0.localizedStandardCompare($1) == .orderedAscending }.joined(separator: "\u{0}")
    }

    private nonisolated static func duplicateImageGroupExcludingSameSource(_ group: DuplicateImageGroup, sourceKeysByPath: [String: String]) -> DuplicateImageGroup? {
        var seenSources = Set<String>()
        let files = group.files
            .sorted { $0.localizedStandardCompare($1) == .orderedAscending }
            .filter { path in
                let key = sourceKeysByPath[path] ?? URL(fileURLWithPath: path).deletingLastPathComponent().path
                return seenSources.insert(key).inserted
            }
        guard files.count > 1 else { return nil }

        var pruned = group
        pruned.files = files
        return pruned
    }

    private nonisolated static func normalizedDuplicateImageFolderPaths(_ paths: [String]) -> [String] {
        var seen = Set<String>()
        var output: [String] = []
        for path in paths {
            let value = path.trimmed
            guard !value.isEmpty else { continue }
            let normalized = URL(fileURLWithPath: value, isDirectory: true).standardizedFileURL.path
            guard seen.insert(normalized).inserted else { continue }
            output.append(normalized)
        }
        return output
    }

    private nonisolated static func duplicateImageSourceKey(forPath path: String, root: URL) -> String {
        let fileURL = URL(fileURLWithPath: path).standardizedFileURL
        let parent = fileURL.deletingLastPathComponent().standardizedFileURL
        let rootURL = root.standardizedFileURL
        let rootPath = rootURL.path
        let parentPath = parent.path
        if parentPath.hasPrefix(rootPath) {
            let relative = String(parentPath.dropFirst(rootPath.count))
                .trimmingCharacters(in: CharacterSet(charactersIn: "/"))
            return "\(rootPath)\u{0}\(relative.isEmpty ? "." : relative)"
        }
        return parentPath
    }

    private nonisolated static func imageDimensions(for url: URL) -> (width: Int, height: Int)? {
        guard let source = CGImageSourceCreateWithURL(url as CFURL, nil),
              let properties = CGImageSourceCopyPropertiesAtIndex(source, 0, nil) as? [CFString: Any],
              let width = properties[kCGImagePropertyPixelWidth] as? NSNumber,
              let height = properties[kCGImagePropertyPixelHeight] as? NSNumber,
              width.intValue > 0,
              height.intValue > 0 else {
            return nil
        }
        return (width.intValue, height.intValue)
    }

    private nonisolated static func visualImageHash(for url: URL) -> UInt64? {
        guard let source = CGImageSourceCreateWithURL(url as CFURL, nil),
              let image = CGImageSourceCreateImageAtIndex(source, 0, nil) else {
            return nil
        }

        let sampleWidth = 8
        let sampleHeight = 8
        var pixels = [UInt8](repeating: 0, count: sampleWidth * sampleHeight * 4)
        return pixels.withUnsafeMutableBytes { buffer -> UInt64? in
            guard let baseAddress = buffer.baseAddress,
                  let context = CGContext(
                    data: baseAddress,
                    width: sampleWidth,
                    height: sampleHeight,
                    bitsPerComponent: 8,
                    bytesPerRow: sampleWidth * 4,
                    space: CGColorSpaceCreateDeviceRGB(),
                    bitmapInfo: CGImageAlphaInfo.premultipliedLast.rawValue | CGBitmapInfo.byteOrder32Big.rawValue
                  ) else {
                return nil
            }
            context.interpolationQuality = .high
            context.draw(image, in: CGRect(x: 0, y: 0, width: sampleWidth, height: sampleHeight))

            let bytes = buffer.bindMemory(to: UInt8.self)
            var luminanceValues: [Int] = []
            luminanceValues.reserveCapacity(sampleWidth * sampleHeight)
            for index in stride(from: 0, to: bytes.count, by: 4) {
                let red = Int(bytes[index])
                let green = Int(bytes[index + 1])
                let blue = Int(bytes[index + 2])
                luminanceValues.append((red * 299 + green * 587 + blue * 114) / 1_000)
            }

            guard !luminanceValues.isEmpty else { return nil }
            let average = luminanceValues.reduce(0, +) / luminanceValues.count
            var hash: UInt64 = 0
            for (index, value) in luminanceValues.enumerated() where value >= average {
                hash |= UInt64(1) << UInt64(index)
            }
            return hash
        }
    }

    private nonisolated static func sha256Hex(for url: URL) throws -> String {
        let handle = try FileHandle(forReadingFrom: url)
        defer {
            try? handle.close()
        }

        var hasher = SHA256()
        while true {
            let chunk = try handle.read(upToCount: 1_048_576) ?? Data()
            if chunk.isEmpty { break }
            hasher.update(data: chunk)
        }
        return hasher.finalize().map { String(format: "%02x", $0) }.joined()
    }

    private nonisolated static let duplicateImageExtensions: Set<String> = [
        "avif", "bmp", "gif", "heic", "heif", "jpeg", "jpg", "png", "tif", "tiff", "webp"
    ]

    private func summary(added: Int, skipped: Int) -> String {
        if added == 0 && skipped == 0 {
            return ""
        }
        if skipped == 0 {
            return "\(added) added"
        }
        return "\(added) added, \(skipped) duplicates skipped"
    }

    private func bookmarkTitle(for url: String) -> String {
        if let parsed = URL(string: url), let host = parsed.host, !host.isEmpty {
            let last = parsed.lastPathComponent
            return last.isEmpty ? host : "\(host)/\(last)"
        }
        if url.hasPrefix("magnet:") {
            return "Magnet"
        }
        return url
    }

    private nonisolated static func bookmarkSortTitle(_ bookmark: URLBookmark) -> String {
        let title = bookmark.title.trimmed
        return title.isEmpty ? bookmark.url : title
    }

    private func normalizedHostSuffix(_ host: String) -> String {
        SiteRule.normalizedHostSuffix(host)
    }

    private func builtSearchURL() -> URL? {
        guard let provider = currentSearchProvider() else { return nil }
        let query = searchQuery.trimmed
        guard !query.isEmpty else { return nil }
        return Self.searchURL(provider: provider, query: query)
    }

    private func currentSearchProvider() -> SearchProvider? {
        searchProviders.first(where: { $0.id == selectedSearchProviderID }) ?? searchProviders.first
    }

    private func selectHitomiSearchProvider() {
        if let provider = Self.searchProvider(matching: "hitomi", in: searchProviders) ??
            searchProviders.first(where: { $0.name.localizedCaseInsensitiveContains("hitomi") }) {
            selectedSearchProviderID = provider.id
        }
    }

    private func quickSearchURLString(from line: String) -> String? {
        guard let request = Self.quickSearchRequest(from: line) else { return nil }
        let provider: SearchProvider?
        if let key = request.providerKey {
            provider = Self.searchProvider(matching: key, in: searchProviders)
        } else {
            provider = currentSearchProvider()
        }
        guard let provider,
              let url = Self.searchURL(provider: provider, query: request.query) else {
            return nil
        }
        return url.absoluteString
    }

    nonisolated static func searchURL(provider: SearchProvider, query: String) -> URL? {
        let query = query.trimmed
        guard !query.isEmpty else { return nil }
        return URL(string: renderedSearchTemplate(provider.urlTemplate, query: query))
    }

    private nonisolated static func isValidSearchTemplate(_ template: String) -> Bool {
        guard template.contains("{query}") || template.contains("{query+}") else {
            return false
        }
        return URL(string: renderedSearchTemplate(template, query: "test query")) != nil
    }

    private nonisolated static func renderedSearchTemplate(_ template: String, query: String) -> String {
        let allowed = CharacterSet.urlQueryAllowed.subtracting(CharacterSet(charactersIn: "&+"))
        let encoded = query.addingPercentEncoding(withAllowedCharacters: allowed) ?? query
        let plusEncoded = encoded.replacingOccurrences(of: "%20", with: "+")
        return template
            .replacingOccurrences(of: "{query+}", with: plusEncoded)
            .replacingOccurrences(of: "{query}", with: encoded)
    }

    nonisolated static func quickSearchRequest(from line: String) -> (providerKey: String?, query: String)? {
        let value = line.trimmed
        guard !value.isEmpty else { return nil }

        if value.hasPrefix("?") {
            let query = String(value.dropFirst()).trimmed
            return query.isEmpty ? nil : (nil, query)
        }

        if let bracketEnd = value.firstIndex(of: "]"), value.hasPrefix("[") {
            let key = String(value[value.index(after: value.startIndex)..<bracketEnd]).trimmed
            let query = String(value[value.index(after: bracketEnd)...]).trimmed
            if !key.isEmpty, !query.isEmpty {
                return (key, query)
            }
        }

        guard let separator = value.firstIndex(of: ":") else { return nil }
        let key = String(value[..<separator]).trimmed
        let query = String(value[value.index(after: separator)...]).trimmed
        guard !key.isEmpty, !query.isEmpty, key.range(of: #"^[A-Za-z][A-Za-z0-9 _.-]*$"#, options: .regularExpression) != nil else {
            return nil
        }
        return (key, query)
    }

    private nonisolated static func searchProvider(matching rawKey: String, in providers: [SearchProvider]) -> SearchProvider? {
        let key = searchProviderKey(rawKey)
        guard !key.isEmpty else { return nil }
        if let provider = providers.first(where: { searchProviderKey($0.name) == key }) {
            return provider
        }
        if key == "yt" {
            return providers.first(where: { searchProviderKey($0.name) == "youtube" })
        }
        let matching = providers.filter { searchProviderKey($0.name).hasPrefix(key) }
        return matching.count == 1 ? matching[0] : nil
    }

    private nonisolated static func searchProvider(for bookmark: SearchBookmark, in providers: [SearchProvider]) -> SearchProvider? {
        if let id = bookmark.providerID,
           let provider = providers.first(where: { $0.id == id }) {
            return provider
        }
        return searchProvider(matching: bookmark.providerName, in: providers) ?? providers.first
    }

    private nonisolated static func searchBookmarkTitle(providerName: String, query: String) -> String {
        let prefix = providerName.trimmed.isEmpty ? "Search" : providerName.trimmed
        let trimmedQuery = query.trimmed
        let value = trimmedQuery.count > 80 ? "\(trimmedQuery.prefix(77))..." : trimmedQuery
        return "\(prefix): \(value)"
    }

    private nonisolated static func searchBookmarkKey(providerName: String, query: String) -> String {
        "\(searchProviderKey(providerName))|\(query.trimmed.lowercased())"
    }

    private nonisolated static func searchProviderKey(_ value: String) -> String {
        value.lowercased().filter { $0.isLetter || $0.isNumber }
    }

    private func matchingCustomCommandRule(for url: URL) -> SiteRule? {
        guard url.host != nil else { return nil }
        return siteRules
            .filter {
                $0.handler == .customCommand &&
                    !($0.commandTemplate?.trimmed.isEmpty ?? true)
            }
            .sorted { $0.matchSpecificity > $1.matchSpecificity }
            .first { $0.matches(url) }
    }

    func requestOptions(for url: URL, explicitReferer: String? = nil) -> HTTPRequestOptions {
        var referer = explicitReferer?.trimmed
        var userAgent: String?

        if let rule = matchingHeaderRule(for: url) {
            if let template = rule.refererTemplate?.trimmed, !template.isEmpty {
                let expanded = expandedHeaderTemplate(template, url: url).trimmed
                if !expanded.isEmpty {
                    referer = expanded
                }
            }

            if let value = rule.userAgent?.trimmed, !value.isEmpty {
                userAgent = value
            }
        }

        return HTTPRequestOptions(
            referer: (referer?.isEmpty ?? true) ? nil : referer,
            userAgent: (userAgent?.isEmpty ?? true) ? nil : userAgent
        )
    }

    private func matchingHeaderRule(for url: URL) -> SiteRule? {
        guard url.host != nil else { return nil }
        return siteRules
            .filter {
                !($0.refererTemplate?.trimmed.isEmpty ?? true) ||
                    !($0.userAgent?.trimmed.isEmpty ?? true)
            }
            .sorted { $0.matchSpecificity > $1.matchSpecificity }
            .first { $0.matches(url) }
    }

    private func applyingHeaderRules(to resolved: ResolvedDownload) -> ResolvedDownload {
        let assets = resolved.assets.map(assetWithHeaderRules)
        let packageMode: DownloadPackageMode

        switch resolved.packageMode {
        case .files:
            packageMode = .files
        case .concatenate(let outputFilename):
            packageMode = .concatenate(outputFilename: outputFilename)
        case .mux(let videoAssets, let audioAssets, let outputFilename):
            packageMode = .mux(
                videoAssets: videoAssets.map(assetWithHeaderRules),
                audioAssets: audioAssets.map(assetWithHeaderRules),
                outputFilename: outputFilename
            )
        case .grouped(let fileAssetIndexes, let concatenations):
            packageMode = .grouped(
                fileAssetIndexes: fileAssetIndexes,
                concatenations: concatenations
            )
        case .groupedMedia(let fileAssetIndexes, let concatenations, let muxes):
            packageMode = .groupedMedia(
                fileAssetIndexes: fileAssetIndexes,
                concatenations: concatenations,
                muxes: muxes
            )
        }

        return ResolvedDownload(
            title: resolved.title,
            folderName: resolved.folderName,
            assets: assets,
            packageMode: packageMode,
            metadata: resolved.metadata,
            textMergePlan: resolved.textMergePlan,
            temporaryAssetDirectories: resolved.temporaryAssetDirectories
        )
    }

    private func assetWithHeaderRules(_ asset: ResolvedAsset) -> ResolvedAsset {
        var copy = asset
        let headers = requestOptions(for: asset.remoteURL, explicitReferer: asset.referer)
        copy.referer = headers.referer
        copy.userAgent = headers.userAgent ?? asset.userAgent
        return copy
    }

    private func expandedHeaderTemplate(_ template: String, url: URL) -> String {
        let host = url.host ?? ""
        return template
            .replacingOccurrences(of: "{url}", with: url.absoluteString)
            .replacingOccurrences(of: "{host}", with: host)
            .replacingOccurrences(of: "{origin}", with: origin(for: url))
            .replacingOccurrences(of: "{scheme}", with: url.scheme ?? "")
            .replacingOccurrences(of: "{path}", with: url.path)
            .replacingOccurrences(of: "{query}", with: url.query ?? "")
    }

    private func origin(for url: URL) -> String {
        guard let scheme = url.scheme, let host = url.host else { return "" }
        let port = url.port.map { ":\($0)" } ?? ""
        return "\(scheme)://\(host)\(port)"
    }

    private func templatedFolderName(for resolved: ResolvedDownload, sourceURL: URL) -> String {
        let template = folderNameTemplate.trimmed
        guard !template.isEmpty else { return resolved.folderName.sanitizedRelativePath(maxComponentLength: 120) }
        let context = nameTemplateContext(
            title: resolved.title,
            sourceURL: sourceURL,
            filename: resolved.folderName,
            index: nil,
            total: resolved.assets.count,
            metadata: resolved.metadata
        )
        return NameTemplate.folderName(template: template, fallback: resolved.folderName, context: context)
    }

    private func templatedAssets(_ assets: [ResolvedAsset], title: String, sourceURL: URL, metadata: [String: String]) -> [ResolvedAsset] {
        let template = effectiveFileNameTemplate(for: sourceURL, metadata: metadata)
        guard !template.isEmpty else { return assets }
        let total = assets.count
        return assets.enumerated().map { offset, asset in
            var copy = asset
            let assetMetadata = Self.mergedNameTemplateMetadata(metadata, assetMetadata: asset.metadata)
            copy.filename = templatedFileName(
                original: asset.filename,
                title: title,
                sourceURL: sourceURL,
                index: Self.nameTemplateIndex(for: asset, fallback: offset + 1),
                total: total,
                metadata: assetMetadata
            )
            return copy
        }
    }

    private nonisolated static let nameTemplateIndexMetadataKey = "hitomi_native_template_index"

    private nonisolated static func nameTemplateIndex(for asset: ResolvedAsset, fallback: Int) -> Int {
        guard let rawValue = asset.metadata[nameTemplateIndexMetadataKey]?.trimmed,
              let value = Int(rawValue),
              value > 0 else {
            return fallback
        }
        return value
    }

    nonisolated static func mergedNameTemplateMetadata(_ metadata: [String: String], assetMetadata: [String: String]) -> [String: String] {
        DownloadMetadata.clean(metadata.merging(assetMetadata) { _, assetValue in assetValue })
    }

    private func templatedConcatenatedFileName(
        original: String,
        title: String,
        sourceURL: URL,
        total: Int?,
        metadata: [String: String],
        packageMode: DownloadPackageMode
    ) -> String {
        let recordingTemplate = recordingFileNameTemplate.trimmed
        let templateOverride = Self.shouldUseRecordingFileNameTemplate(packageMode: packageMode, metadata: metadata) && !recordingTemplate.isEmpty
            ? recordingTemplate
            : nil
        return templatedFileName(
            original: original,
            title: title,
            sourceURL: sourceURL,
            index: nil,
            total: total,
            metadata: metadata,
            templateOverride: templateOverride
        )
    }

    nonisolated static func shouldUseRecordingFileNameTemplate(packageMode: DownloadPackageMode, metadata: [String: String]) -> Bool {
        switch packageMode {
        case .concatenate, .grouped:
            break
        case .files, .mux, .groupedMedia:
            return false
        }
        let cleaned = DownloadMetadata.clean(metadata)
        let fields = [
            cleaned["type"],
            cleaned["media_type"],
            cleaned["format"],
            cleaned["media_format"],
            cleaned["protocol"],
            cleaned["category"],
            cleaned["live"],
            cleaned["live_status"],
            cleaned["was_live"],
            cleaned["record"],
            cleaned["recording"]
        ].compactMap { $0?.lowercased() }

        if fields.contains(where: { field in
            field == "hls" ||
                field == "m3u8" ||
                field == "live" ||
                field == "record" ||
                field == "recording" ||
                field == "is_live" ||
                field == "was_live" ||
                field.contains("livestream") ||
                field.contains("live stream")
        }) {
            return true
        }

        return ["playlist_url", "media_url", "source_url", "page_url"]
            .compactMap { cleaned[$0]?.lowercased() }
            .contains { $0.contains(".m3u8") }
    }

    private func effectiveFileNameTemplate(for sourceURL: URL, metadata: [String: String]) -> String {
        let sourceID = DownloadSourceFolderProfile.sourceID(for: sourceURL, metadata: metadata)
        return sourceFileNameTemplate(for: sourceID).trimmed
    }

    private func templatedFileName(
        original: String,
        title: String,
        sourceURL: URL,
        index: Int?,
        total: Int?,
        metadata: [String: String] = [:],
        templateOverride: String? = nil
    ) -> String {
        let override = templateOverride?.trimmed ?? ""
        let template = override.isEmpty
            ? effectiveFileNameTemplate(for: sourceURL, metadata: metadata)
            : override
        guard !template.isEmpty else { return original.sanitizedFilename(maxLength: 180) }
        let context = nameTemplateContext(
            title: title,
            sourceURL: sourceURL,
            filename: original,
            index: index,
            total: total,
            metadata: metadata
        )
        return NameTemplate.fileName(template: template, fallback: original, context: context)
    }

    private func nameTemplateContext(title: String, sourceURL: URL, filename: String, index: Int?, total: Int?, metadata: [String: String] = [:]) -> NameTemplateContext {
        let safeFilename = filename.sanitizedFilename(maxLength: 180)
        let basename = (safeFilename as NSString).deletingPathExtension
        let ext = (safeFilename as NSString).pathExtension
        let metadataSite = metadata["site"]?.trimmed ?? ""
        let metadataHost = metadata["host"]?.trimmed ?? ""
        return NameTemplateContext(
            title: title,
            site: metadataSite.isEmpty ? siteFolderName(for: sourceURL) : metadataSite,
            host: metadataHost.isEmpty ? sourceHostToken(for: sourceURL) : metadataHost,
            date: Self.templateDate(from: metadata) ?? Self.dateFolderName(),
            id: Self.templateIdentifier(from: metadata) ?? sourceIdentifier(for: sourceURL),
            url: sourceURL.absoluteString,
            path: sourcePathToken(for: sourceURL),
            slug: sourceSlugToken(for: sourceURL),
            query: sourceQueryToken(for: sourceURL),
            filename: safeFilename,
            basename: basename,
            ext: ext,
            index: index,
            total: total,
            metadata: metadata
        )
    }

    nonisolated static func templateDate(from metadata: [String: String]) -> String? {
        let dateKeys = [
            "date", "upload_date", "uploadDate",
            "published_date", "published", "published_at", "publishedAt",
            "published_time", "publishedTime", "datePublished", "date_published",
            "publishDate", "publish_date", "pubdate", "datepublished",
            "article:published_time", "article:modified_time",
            "posted", "posted_at", "postedAt",
            "created", "created_at", "createdAt", "created_time", "createdTime", "createdDate",
            "uploaded", "uploaded_at", "uploadedAt",
            "registered", "registered_at", "registeredAt",
            "firstRetrieve", "first_retrieve",
            "release_date", "reg_date", "broad_start", "write_tm", "openDate",
            "taken_at_timestamp", "taken_at", "device_timestamp", "imported_taken_at",
            "timestamp"
        ]
        for key in dateKeys {
            guard let value = templateMetadataValue(metadata, key: key) else { continue }
            if let date = normalizedTemplateDate(value) {
                return date
            }
        }
        return nil
    }

    private nonisolated static func templateMetadataValue(_ metadata: [String: String], key: String) -> String? {
        if let value = metadata[key]?.trimmed, !value.isEmpty {
            return value
        }
        if let match = metadata.first(where: { $0.key.caseInsensitiveCompare(key) == .orderedSame }),
           !match.value.trimmed.isEmpty {
            return match.value.trimmed
        }
        return nil
    }

    private nonisolated static func normalizedTemplateDate(_ raw: String) -> String? {
        let value = raw.trimmed
        guard !value.isEmpty else { return nil }

        if let match = value.range(of: #"^[0-9]{8}(?:[0-9]{6})?$"#, options: .regularExpression) {
            let digits = String(value[match])
            let year = digits.prefix(4)
            let monthStart = digits.index(digits.startIndex, offsetBy: 4)
            let dayStart = digits.index(digits.startIndex, offsetBy: 6)
            let month = digits[monthStart..<dayStart]
            let dayEnd = digits.index(digits.startIndex, offsetBy: 8)
            let day = digits[dayStart..<dayEnd]
            return "\(year)-\(month)-\(day)"
        }

        if let date = normalizedUnixTemplateDate(value) {
            return date
        }

        let pattern = #"([0-9]{4})[-./]([0-9]{1,2})[-./]([0-9]{1,2})"#
        guard let regex = try? NSRegularExpression(pattern: pattern),
              let match = regex.firstMatch(in: value, range: NSRange(value.startIndex..<value.endIndex, in: value)),
              let yearRange = Range(match.range(at: 1), in: value),
              let monthRange = Range(match.range(at: 2), in: value),
              let dayRange = Range(match.range(at: 3), in: value),
              let month = Int(value[monthRange]),
              let day = Int(value[dayRange]) else {
            return nil
        }
        return String(format: "%@-%02d-%02d", String(value[yearRange]), month, day)
    }

    private nonisolated static func normalizedUnixTemplateDate(_ raw: String) -> String? {
        let value = raw.trimmed
        let seconds: TimeInterval?
        if value.range(of: #"^1[0-9]{9}(?:\.[0-9]+)?$"#, options: .regularExpression) != nil {
            seconds = TimeInterval(value)
        } else if value.range(of: #"^1[0-9]{12}$"#, options: .regularExpression) != nil,
                  let milliseconds = TimeInterval(value) {
            seconds = milliseconds / 1000
        } else {
            seconds = nil
        }
        guard let seconds, seconds > 0 else { return nil }
        let formatter = DateFormatter()
        formatter.calendar = Calendar(identifier: .gregorian)
        formatter.locale = Locale(identifier: "en_US_POSIX")
        formatter.timeZone = TimeZone(secondsFromGMT: 0)
        formatter.dateFormat = "yyyy-MM-dd"
        return formatter.string(from: Date(timeIntervalSince1970: seconds))
    }

    nonisolated static func templateIdentifier(from metadata: [String: String]) -> String? {
        let keys = [
            "id",
            "post_id", "postID",
            "gallery_id", "galleryID",
            "video_id", "videoID",
            "clip_id", "clipID",
            "content_id", "contentID",
            "comic_id", "comicID",
            "album_id", "albumID",
            "photo_id", "photoID",
            "artwork_id", "artworkID",
            "illust_id", "illustID",
            "status_id", "statusID",
            "tweet_id", "tweetID",
            "note_id", "noteID",
            "episode_id", "episodeID",
            "chapter_id", "chapterID",
            "work_id", "workID",
            "series_id", "seriesID",
            "item_id", "itemID",
            "pin_id", "pinID",
            "thread_id", "threadID",
            "article_id", "articleID",
            "track_id", "trackID",
            "media_id", "mediaID",
            "attachment_id", "attachmentID",
            "file_id", "fileID",
            "bvid", "aid", "cid",
            "vod_id", "vodID",
            "catch_id", "catchID",
            "live_id", "liveID",
            "movie_id", "movieID",
            "claim_id", "claimID",
            "coub_id", "coubID",
            "snapshot_id", "snapshotID",
            "archive_timestamp"
        ]

        for key in keys {
            if let value = metadata[key]?.trimmed, !value.isEmpty {
                return value.sanitizedFilename(maxLength: 80)
            }
        }
        for key in keys {
            if let match = metadata.first(where: { $0.key.caseInsensitiveCompare(key) == .orderedSame }),
               !match.value.trimmed.isEmpty {
                return match.value.trimmed.sanitizedFilename(maxLength: 80)
            }
        }
        return nil
    }

    private func sourceIdentifier(for url: URL) -> String {
        let absolute = url.absoluteString
        let patterns = [
            #"hitomi\.la/(?:reader|galleries|g|lofi|mpv)/([0-9]+)"#,
            #"-([0-9]+)\.html"#,
            #"galleryblock/([0-9]+)"#,
            #"#-\*-[^#]*\(([0-9]+)\)"#
        ]

        for pattern in patterns {
            if let match = firstCapture(in: absolute, pattern: pattern) {
                return match
            }
        }

        let last = url.deletingPathExtension().lastPathComponent
        if !last.trimmed.isEmpty {
            return last.sanitizedFilename(maxLength: 80)
        }

        return siteFolderName(for: url)
    }

    private func firstCapture(in text: String, pattern: String) -> String? {
        guard let regex = try? NSRegularExpression(pattern: pattern, options: [.caseInsensitive]) else {
            return nil
        }
        let range = NSRange(text.startIndex..<text.endIndex, in: text)
        guard let match = regex.firstMatch(in: text, range: range),
              match.numberOfRanges > 1,
              let captureRange = Range(match.range(at: 1), in: text) else {
            return nil
        }
        return String(text[captureRange])
    }

    private func outputRoot(for sourceURL: URL, metadata: [String: String] = [:]) throws -> URL {
        var root = URL(fileURLWithPath: destinationPath, isDirectory: true)

        switch outputSubfolderMode {
        case .none:
            break
        case .site:
            root = AppPaths.directoryURL(
                in: root,
                name: effectiveSourceFolderName(
                    for: DownloadSourceFolderProfile.sourceID(for: sourceURL, metadata: metadata)
                )
            )
        case .date:
            root.appendPathComponent(Self.dateFolderName(), isDirectory: true)
        case .siteAndDate:
            root = AppPaths.directoryURL(
                in: root,
                name: effectiveSourceFolderName(
                    for: DownloadSourceFolderProfile.sourceID(for: sourceURL, metadata: metadata)
                )
            )
            root.appendPathComponent(Self.dateFolderName(), isDirectory: true)
        }

        try AppPaths.ensureDirectory(root)
        return root
    }

    private func effectiveSourceFolderName(for sourceID: String) -> String {
        let normalized = DownloadSourceFolderProfile.normalizedSourceID(sourceID)
        let configured = sourceFolderName(for: normalized).trimmed
        let fallback = DownloadSourceFolderProfile.defaultFolderName(for: normalized)
        return (configured.isEmpty ? fallback : configured)
            .sanitizedRelativePath(maxComponentLength: 120)
    }

    private func persistSourceFolderNames() {
        UserDefaults.standard.set(sourceFolderNames, forKey: "sourceFolderNames")
    }

    private func persistSourceFileNameTemplates() {
        let defaults = UserDefaults.standard
        defaults.set(sourceFileNameTemplates, forKey: "sourceFileNameTemplates")
        for sourceID in NameTemplate.originalSourceFileTemplateIDs {
            guard let preferenceKey = NameTemplate.originalFilePreferenceKey(for: sourceID) else {
                continue
            }
            if let template = sourceFileNameTemplates[sourceID] {
                defaults.set(template, forKey: preferenceKey)
            } else {
                defaults.removeObject(forKey: preferenceKey)
            }
        }
        if let template = sourceFileNameTemplates["hitomi"],
           let typeNumber = NameTemplate.originalHitomiFilenameTypeNumber(for: template) {
            defaults.set(typeNumber, forKey: "hitomiFilenameTypeNumber")
        }
    }

