    private func siteFolderName(for url: URL) -> String {
        if url.scheme?.lowercased() == "magnet" {
            return "magnet"
        }
        if url.scheme?.lowercased() == "file" {
            return "local"
        }
        let host = (url.host ?? "downloads")
            .replacingOccurrences(of: "^www\\.", with: "", options: .regularExpression)
        return host.sanitizedFilename(maxLength: 80)
    }

    private func sourceHostToken(for url: URL) -> String {
        if url.scheme?.lowercased() == "magnet" {
            return "magnet"
        }
        if url.scheme?.lowercased() == "file" {
            return "local"
        }
        return sanitizedTemplateToken(url.host?.lowercased() ?? siteFolderName(for: url), maxLength: 120)
    }

    private func sourcePathToken(for url: URL) -> String {
        let decodedPath = url.path.removingPercentEncoding ?? url.path
        let trimmedPath = decodedPath.trimmingCharacters(in: CharacterSet(charactersIn: "/"))
        return sanitizedTemplateToken(trimmedPath, maxLength: 180)
    }

    private func sourceSlugToken(for url: URL) -> String {
        let urlWithoutExtension = url.deletingPathExtension()
        let slug = urlWithoutExtension.lastPathComponent.removingPercentEncoding
            ?? urlWithoutExtension.lastPathComponent
        return sanitizedTemplateToken(slug, maxLength: 120)
    }

    private func sourceQueryToken(for url: URL) -> String {
        let query = url.query?.removingPercentEncoding ?? url.query ?? ""
        return sanitizedTemplateToken(query, maxLength: 180)
    }

    private func sanitizedTemplateToken(_ value: String, maxLength: Int) -> String {
        let trimmed = value.trimmed
        guard !trimmed.isEmpty else { return "" }
        return trimmed.sanitizedFilename(maxLength: maxLength)
    }

    private nonisolated static func dateFolderName(_ date: Date = Date()) -> String {
        let formatter = DateFormatter()
        formatter.locale = Locale(identifier: "en_US_POSIX")
        formatter.dateFormat = "yyyy-MM-dd"
        return formatter.string(from: date)
    }

    private func persistSearchProviders() {
        userData.searchProviders = searchProviders
        persistUserData()
    }

    private func persistSearchBookmarks() {
        userData.searchBookmarks = searchBookmarks
        persistUserData()
    }

    private func persistQueueFilterBookmarks() {
        userData.queueFilterBookmarks = queueFilterBookmarks
        persistUserData()
    }

    private func persistQueue() {
        userData.queue = queueOrderedJobs
        userData.queueGroups = queueGroups
        persistUserData()
    }

    private func persistInputTextDraft() {
        guard userData.inputTextDraft != inputText else { return }
        userData.inputTextDraft = inputText
        persistUserData()
    }

    private func persistUserData() {
        userData.queue = queueOrderedJobs
        userData.queueGroups = queueGroups
        userData.queueFilterBookmarks = queueFilterBookmarks
        userData.inputTextDraft = inputText
        if userDataStore.save(userData) {
            persistenceWarning = ""
        } else {
            let warning = "Storage warning: queue list could not be saved. Check disk space or permissions."
            if persistenceWarning != warning {
                showingStorageWarning = true
            }
            persistenceWarning = warning
            addSummary = warning
        }
    }

    private func normalizeActiveQueueOrder() {
        guard activeQueueOrderIDs != nil else { return }
        let orderedJobs = queueOrderedJobs
        activeQueueOrderIDs = nil
        jobs = orderedJobs
    }

    private func persistHTTPAPISettings() {
        httpAPIPortString = httpAPIPortString.trimmed.isEmpty ? "8110" : httpAPIPortString.trimmed
        httpAPIPassword = httpAPIPassword.trimmed
        UserDefaults.standard.set(httpAPIEnabled, forKey: "httpAPIEnabled")
        UserDefaults.standard.set(httpAPIPortString, forKey: "httpAPIPortString")
        UserDefaults.standard.set(httpAPIPassword, forKey: "httpAPIPassword")
        UserDefaults.standard.set(httpViewerLazyLoading, forKey: "httpViewerLazyLoading")
    }

    func setHTTPViewerLazyLoading(_ enabled: Bool) {
        guard httpViewerLazyLoading != enabled else { return }
        httpViewerLazyLoading = enabled
        persistHTTPAPISettings()
        addSummary = enabled ? "HTTP viewer lazy loading on" : "HTTP viewer lazy loading off"
    }

    var browserExtensionListeningPort: UInt16? {
        browserExtensionServer?.listeningPort
    }

    private func startBrowserExtensionServer() {
        stopBrowserExtensionServer()
        let portString = Self.environmentPort("HITOMI_NATIVE_BROWSER_EXTENSION_PORT")
            ?? String(BrowserExtensionServer.defaultPort)
        guard let port = UInt16(portString), port > 0 else {
            browserExtensionStatus = "Browser extension port is invalid"
            return
        }

        let server = BrowserExtensionServer(port: port) { [weak self] message in
            guard let self else { return .rejected }
            return await self.handleBrowserExtensionMessage(message)
        }
        do {
            try server.start()
            browserExtensionServer = server
            browserExtensionStatus = "ws://127.0.0.1:\(server.listeningPort ?? port)"
        } catch {
            browserExtensionStatus = "Browser extension unavailable"
            recordActivity("Browser extension server failed on port \(port)", category: "App")
        }
    }

    private func stopBrowserExtensionServer() {
        browserExtensionServer?.stop()
        browserExtensionServer = nil
        browserExtensionStatus = "Browser extension off"
    }

    private func handleBrowserExtensionMessage(_ message: String) async -> BrowserExtensionMessageResult {
        if let payload = OriginalBrowserExtensionCookiePayload.parse(message) {
            let result = await CookieStore.shared.replaceBrowserExtensionCookies(payload)
            cookieSummary = Self.browserCookieSummary(imported: result.imported, skipped: result.skipped)
            addSummary = result.imported > 0 ? "Browser extension cookies updated" : "No browser cookies found"
            return .accepted
        }

        guard OriginalBrowserExtensionTask.parse(message) != nil else {
            recordActivity("Browser extension rejected an invalid message", category: "App")
            return .rejected
        }
        let items = inputItems(from: message)
        guard !items.isEmpty else {
            recordActivity("Browser extension rejected an invalid task URL", category: "App")
            return .rejected
        }

        let newJobs = jobsForAdding(items, promptForDuplicates: true)
        if !newJobs.isEmpty {
            insertAddedJobsAtTop(newJobs)
            persistQueue()
            runQueuedJobsIfEnabled()
        }
        return .accepted
    }

    private func startHTTPAPIServer() {
        stopHTTPAPIServer()
        persistHTTPAPISettings()

        guard let portValue = UInt16(httpAPIPortString), portValue > 0 else {
            httpAPIEnabled = false
            httpAPIStatus = "잘못된 HTTP API 포트"
            addSummary = httpAPIStatus
            persistHTTPAPISettings()
            return
        }

        let server = LocalHTTPAPIServer(port: portValue) { [weak self] request in
            guard let self else {
                return LocalHTTPResponse.jsonObject(["error": "App is closing"], status: 503)
            }
            return await self.response(forAPIRequest: request)
        }

        do {
            try server.start()
            httpAPIServer = server
            httpAPIStatus = "http://127.0.0.1:\(portValue)"
        } catch {
            httpAPIEnabled = false
            httpAPIStatus = "HTTP API 시작 실패"
            addSummary = "HTTP API 시작 실패"
            persistHTTPAPISettings()
        }
    }

    private func stopHTTPAPIServer() {
        httpAPIServer?.stop()
        httpAPIServer = nil
        httpAPIStatus = "HTTP API 꺼짐"
    }

    private func response(forAPIRequest request: LocalHTTPRequest) async -> LocalHTTPResponse {
        if request.method == "OPTIONS" {
            return LocalHTTPResponse.data(Data(), contentType: "text/plain; charset=utf-8", status: 204)
        }

        if request.method == "GET", isAPIStaticAssetPath(request.path) {
            return apiStaticAssetResponse(request)
        }

        if request.path.lowercased() == "/login" || request.path.lowercased() == "/api/login" {
            return apiLoginResponse(request)
        }

        guard isAPIAuthorized(request) else {
            if request.method == "GET" && isWebUIPath(request.path) {
                return apiLoginRedirectResponse(for: request)
            }
            return LocalHTTPResponse.jsonObject(["error": "Unauthorized"], status: 401)
        }

        switch (request.method, request.path.lowercased()) {
        case ("GET", "/"):
            return LocalHTTPResponse.html(apiIndexPage(passwordQuery: request.query["pw"] ?? request.query["password"] ?? ""))
        case ("GET", "/webui"), ("GET", "/api/webui"):
            return LocalHTTPResponse.html(apiWebUI(request))
        case ("GET", "/docs"), ("GET", "/docs.html"), ("GET", "/api/docs"):
            return LocalHTTPResponse.html(apiDocsPage(passwordQuery: request.query["pw"] ?? request.query["password"] ?? ""))
        case ("GET", "/about"):
            return LocalHTTPResponse.html(apiAboutPage(request))
        case ("GET", "/api/about"):
            return LocalHTTPResponse.jsonObject(Self.appAboutObject())
        case ("GET", "/help"), ("GET", "/help.html"):
            return LocalHTTPResponse.html(apiHelpPage(request))
        case ("GET", "/api/help"):
            return LocalHTTPResponse.jsonObject(Self.appHelpObject())
        case ("GET", "/list"), ("GET", "/api/list"):
            return LocalHTTPResponse.html(apiListPage(request))
        case ("GET", "/view"), ("GET", "/api/view"),
             ("GET", "/viewer"), ("GET", "/api/viewer"),
             ("GET", "/reader"), ("GET", "/api/reader"):
            return apiViewResponse(request)
        case ("GET", "/file"), ("GET", "/api/file"),
             ("GET", "/download_file"), ("GET", "/api/download_file"),
             ("HEAD", "/file"), ("HEAD", "/api/file"),
             ("HEAD", "/download_file"), ("HEAD", "/api/download_file"):
            return apiFileResponse(request)
        case ("GET", "/thumb"), ("GET", "/api/thumb"):
            return await apiThumbResponse(request)
        case ("GET", "/events"), ("GET", "/api/events"):
            return apiEventsResponse()
        case ("GET", "/ws"), ("GET", "/api/ws"), ("GET", "/websocket"), ("GET", "/api/websocket"):
            return apiWebSocketResponse(request)
        case ("GET", "/status"), ("GET", "/api/status"):
            return LocalHTTPResponse.jsonObject(apiStatusObject())
        case ("GET", "/log"):
            return LocalHTTPResponse.html(apiLogPage(request))
        case ("GET", "/api/log"):
            return LocalHTTPResponse.jsonObject(apiLogObject(request))
        case ("POST", "/log/clear"), ("POST", "/api/log/clear"):
            return apiLogClearResponse(request)
        case ("GET", "/dirs"), ("GET", "/directories"):
            return LocalHTTPResponse.html(apiDirectoriesPage(request))
        case ("GET", "/api/dirs"), ("GET", "/api/directories"):
            return LocalHTTPResponse.jsonObject(apiDirectoriesObject(request))
        case ("GET", "/finder"):
