        case ("GET", "/api/names"):
            return apiNamesResponse(request, originalShape: false)
        case ("GET", "/types"), ("GET", "/api/types"), ("POST", "/types"), ("POST", "/api/types"):
            return LocalHTTPResponse.jsonObject(apiTypesObject(request))
        case ("GET", "/headers"), ("GET", "/api/headers"):
            return LocalHTTPResponse.jsonObject(apiHeadersObject(request))
        case ("GET", "/info"), ("GET", "/api/info"), ("GET", "/metadata"), ("GET", "/api/metadata"):
            return apiInfoResponse(request)
        case ("GET", "/pdf"), ("GET", "/api/pdf"),
             ("GET", "/pdf_converter"), ("GET", "/api/pdf_converter"),
             ("POST", "/pdf"), ("POST", "/api/pdf"),
             ("POST", "/pdf_converter"), ("POST", "/api/pdf_converter"):
            return apiPDFResponse(request)
        case ("GET", "/zip"), ("GET", "/api/zip"),
             ("GET", "/cbz"), ("GET", "/api/cbz"),
             ("GET", "/archive"), ("GET", "/api/archive"),
             ("POST", "/zip"), ("POST", "/api/zip"),
             ("POST", "/cbz"), ("POST", "/api/cbz"),
             ("POST", "/archive"), ("POST", "/api/archive"):
            return apiArchiveResponse(request)
        case ("GET", "/download"), ("GET", "/api/download"), ("POST", "/download"), ("POST", "/api/download"):
            let items = apiInputItems(from: request)
            guard !items.isEmpty else {
                return LocalHTTPResponse.jsonObject(["error": "Missing url"], status: 400)
            }
            let added = enqueueInputItems(items)
            let parameters = apiParameters(from: request)
            let shouldStart = (parameters["start"] ?? parameters["run"] ?? "1") != "0"
            if shouldStart {
                startQueue(addingInput: false)
            }
            let message = "\(added) URL\(added == 1 ? "" : "s") added"
            return LocalHTTPResponse.jsonObject([
                "ok": added > 0,
                "res": apiUsesOriginalActionShape(request) ? "ok" : message,
                "message": message,
                "added": added,
                "total": jobs.count,
                "running": isRunning
            ])
        case ("GET", "/exec_"), ("GET", "/api/exec_"), ("POST", "/exec_"), ("POST", "/api/exec_"):
            return await apiExecResponse(request)
        case ("POST", "/start"), ("POST", "/api/start"):
            startQueue(addingInput: false)
            return LocalHTTPResponse.jsonObject(["running": isRunning])
        case ("POST", "/stop"), ("POST", "/api/stop"):
            cancelQueue()
            return LocalHTTPResponse.jsonObject(["running": isRunning])
        case ("POST", "/pause"), ("POST", "/api/pause"):
            return apiAria2RuntimeControlResponse(request, pause: true)
        case ("POST", "/resume"), ("POST", "/api/resume"):
            return apiAria2RuntimeControlResponse(request, pause: false)
