             ("POST", "/aria2_file_list"), ("POST", "/api/aria2_file_list"),
             ("GET", "/aria2_files_list"), ("GET", "/api/aria2_files_list"),
             ("POST", "/aria2_files_list"), ("POST", "/api/aria2_files_list"),
             ("GET", "/show_files"), ("POST", "/show_files"),
             ("GET", "/showfiles"), ("POST", "/showfiles"):
            return await apiAria2FileListResponse(request)
        case ("GET", "/aria2_peers"), ("GET", "/api/aria2_peers"),
             ("POST", "/aria2_peers"), ("POST", "/api/aria2_peers"),
             ("GET", "/peers"), ("GET", "/api/peers"),
             ("POST", "/peers"), ("POST", "/api/peers"):
            return await apiAria2PeersResponse(request)
        case ("POST", "/clear"), ("POST", "/api/clear"):
            let removed = clearFinished()
            return LocalHTTPResponse.jsonObject([
                "count": jobs.count,
                "removed": removed,
                "removedCount": removed,
                "running": isRunning
            ])
        case ("POST", "/complete"), ("POST", "/api/complete"),
             ("POST", "/finish"), ("POST", "/api/finish"),
             ("POST", "/done"), ("POST", "/api/done"):
            return apiCompleteResponse(request)
        case ("POST", "/comment"), ("POST", "/api/comment"):
            return apiCommentResponse(request)
        case ("GET", "/save"), ("GET", "/api/save"), ("POST", "/save"), ("POST", "/api/save"):
            persistQueue()
            persistHTTPAPISettings()
            return LocalHTTPResponse.jsonObject([
                "ok": true,
                "res": "saved",
                "err": "",
                "saved": true,
                "count": jobs.count,
                "status": httpAPIStatus
            ])
        case ("POST", "/update_cookies"), ("POST", "/api/update_cookies"):
            return await apiUpdateCookiesResponse(request)
        case ("POST", "/remove"), ("POST", "/api/remove"):
            return apiRemoveResponse(request)
        case ("POST", "/delete"), ("POST", "/api/delete"):
            return apiDeleteResponse(request)
        case ("POST", "/delete_file"), ("POST", "/api/delete_file"):
            return apiDeleteFileResponse(request)
        default:
            return LocalHTTPResponse.jsonObject(["error": "Not found"], status: 404)
        }
    }

