    private func isAPIStaticAssetPath(_ path: String) -> Bool {
        let lower = path.lowercased()
        return lower == "/favicon.ico" ||
            lower == "/loading.gif" ||
            lower == "/materialize.css" ||
            lower == "/materialize.js" ||
            lower == "/jquery.js" ||
            lower == "/lazysizes.js" ||
            lower == "/hitomi.css" ||
            lower.hasPrefix("/icon/")
    }

    private func isAPIAuthorized(_ request: LocalHTTPRequest) -> Bool {
        let password = httpAPIPassword.trimmed
        guard !password.isEmpty else { return true }
        let parameters = apiParameters(from: request)
        if parameters["pw"] == password || parameters["password"] == password {
            return true
        }
        if request.headers["x-hitomi-password"] == password {
            return true
        }
        if let authorization = request.headers["authorization"],
           authorization == "Bearer \(password)" {
            return true
        }
        if let ticket = apiTicket(from: request),
           Self.apiAcceptedAuthTickets(for: password).contains(ticket) {
            return true
        }
        return false
    }

    private func apiLoginResponse(_ request: LocalHTTPRequest) -> LocalHTTPResponse {
        guard request.method == "POST" else {
            let redirect = Self.htmlEscape(request.query["redirect"] ?? "/webui")
            let placeholder = Self.htmlEscape("Password")
            return LocalHTTPResponse.html("""
            <!doctype html>
            <html><head><meta charset="utf-8"><title>Hitomi Badayo Login</title></head>
            <body style="font:14px \(Self.apiSVGFontStack);padding:24px;">
              <h1>Hitomi Badayo HTTP API</h1>
              <form action="/login" method="post">
                <input type="hidden" name="redirect" value="\(redirect)">
                <input type="password" name="pw" placeholder="\(placeholder)" autofocus>
                <button type="submit">Login</button>
              </form>
            </body></html>
            """)
        }

        let password = httpAPIPassword.trimmed
        let parameters = apiParameters(from: request)
        guard !password.isEmpty,
              parameters["pw"] == password || parameters["password"] == password else {
            return LocalHTTPResponse.jsonObject(["error": "Unauthorized"], status: 401)
        }

        let redirect = apiSafeRedirect(parameters["redirect"] ?? request.query["redirect"] ?? "/webui")
        let ticket = Self.apiAuthTicket(for: password)
        return LocalHTTPResponse(
            status: 302,
            contentType: "text/plain; charset=utf-8",
            body: Data("Redirecting".utf8),
            headers: [
                "Location": redirect,
                "Set-Cookie": "ticket=\(ticket); Path=/; HttpOnly; SameSite=Lax"
            ]
        )
    }

    private func apiLoginRedirectResponse(for request: LocalHTTPRequest) -> LocalHTTPResponse {
        let target = apiRedirectTarget(for: request)
        let location = "/login?redirect=\(Self.queryComponent(target))"
        return LocalHTTPResponse(
            status: 302,
            contentType: "text/plain; charset=utf-8",
            body: Data("Redirecting".utf8),
            headers: ["Location": location]
        )
    }

    private func apiRedirectTarget(for request: LocalHTTPRequest) -> String {
        let query = request.query
            .sorted { $0.key < $1.key }
            .flatMap { key, value -> [String] in
                value
                    .components(separatedBy: .newlines)
                    .map { "\(Self.queryComponent(key))=\(Self.queryComponent($0))" }
            }
            .joined(separator: "&")
        return query.isEmpty ? request.path : "\(request.path)?\(query)"
    }

    private func enqueueURLStrings(_ urls: [String]) -> Int {
        let newJobs = jobsForAdding(urls)
        guard !newJobs.isEmpty else { return 0 }
        insertAddedJobsAtTop(newJobs)
        persistQueue()
        return newJobs.count
    }

    private func enqueueInputItems(_ items: [(url: String, metadata: [String: String])]) -> Int {
        let newJobs = jobsForAdding(items)
        guard !newJobs.isEmpty else { return 0 }
        insertAddedJobsAtTop(newJobs)
        persistQueue()
        return newJobs.count
    }

    private func apiStatusObject() -> [String: Any] {
        let now = Date()
        let downloadSpeed = currentDownloadSpeedBytesPerSecond()
        let uploadSpeed = currentUploadSpeedBytesPerSecond()
        let downloadedSinceLaunch = downloadedSinceAppStartByteCount()
        let visibleJobs = visibleQueueOrderedJobs
        var object: [String: Any] = [
            "running": isRunning,
            "count": visibleJobs.count,
            "queued": visibleJobs.filter { $0.status == .queued }.count,
            "downloading": visibleJobs.filter { $0.status == .downloading || $0.status == .resolving }.count,
            "finished": visibleJobs.filter { $0.status == .finished }.count,
            "failed": visibleJobs.filter { $0.status == .failed }.count
        ]
        object["startedAt"] = Self.apiDateString(appStartedAt)
        object["uptimeSeconds"] = max(0, now.timeIntervalSince(appStartedAt))
        object["downloadSpeedBytesPerSecond"] = Self.apiOptionalInt64(downloadSpeed)
        object["downloadedSinceLaunchBytes"] = Self.apiOptionalInt64(downloadedSinceLaunch)
        object["uploadSpeedBytesPerSecond"] = Self.apiOptionalInt64(uploadSpeed)
        object["items"] = apiJobObjects()
        return object
    }

