    private func apiEventsResponse() -> LocalHTTPResponse {
        let data = (try? JSONSerialization.data(withJSONObject: apiStatusObject(), options: [.sortedKeys])) ?? Data("{}".utf8)
        let json = String(data: data, encoding: .utf8) ?? "{}"
        let body = """
        retry: 3000
        event: status
        data: \(json)


        """
        return LocalHTTPResponse(
            status: 200,
            contentType: "text/event-stream; charset=utf-8",
            body: Data(body.utf8),
            headers: [
                "Cache-Control": "no-cache",
                "X-Accel-Buffering": "no"
            ]
        )
    }

    private func apiWebSocketResponse(_ request: LocalHTTPRequest) -> LocalHTTPResponse {
        guard let key = request.headers["sec-websocket-key"]?.trimmed, !key.isEmpty else {
            return LocalHTTPResponse.jsonObject(["error": "Missing WebSocket key"], status: 400)
        }
        let version = request.headers["sec-websocket-version"]?.trimmed
        guard version == nil || version == "13" else {
            return LocalHTTPResponse.jsonObject(["error": "Unsupported WebSocket version"], status: 400)
        }

        let data = (try? JSONSerialization.data(withJSONObject: apiStatusObject(), options: [.sortedKeys])) ?? Data("{}".utf8)
        let json = String(data: data, encoding: .utf8) ?? "{}"
        var body = Self.webSocketTextFrame(json)
        body.append(contentsOf: [0x88, 0x00])
        return LocalHTTPResponse(
            status: 101,
            contentType: "",
            body: body,
            headers: [
                "Upgrade": "websocket",
                "Connection": "Upgrade",
                "Sec-WebSocket-Accept": Self.webSocketAcceptKey(for: key),
                "Cache-Control": "no-cache"
            ]
        )
    }

    private nonisolated static func webSocketAcceptKey(for key: String) -> String {
        let payload = Data((key.trimmed + "258EAFA5-E914-47DA-95CA-C5AB0DC85B11").utf8)
        let digest = Insecure.SHA1.hash(data: payload)
        return Data(digest).base64EncodedString()
    }

    private nonisolated static func webSocketTextFrame(_ text: String) -> Data {
        let payload = Data(text.utf8)
        var frame = Data([0x81])
        if payload.count <= 125 {
            frame.append(UInt8(payload.count))
        } else if payload.count <= UInt16.max {
            frame.append(126)
            frame.append(UInt8((payload.count >> 8) & 0xff))
            frame.append(UInt8(payload.count & 0xff))
        } else {
            frame.append(127)
            var count = UInt64(payload.count).bigEndian
            withUnsafeBytes(of: &count) { frame.append(contentsOf: $0) }
        }
        frame.append(payload)
        return frame
    }

