    private func apiItemRange(from request: LocalHTTPRequest) -> APIItemRange {
        apiRange(from: request, total: visibleQueueOrderedJobs.count)
    }

    private func apiRange(from request: LocalHTTPRequest, total: Int) -> APIItemRange {
        guard total > 0 else { return APIItemRange(range: 0..<0, total: total) }

        let hasExplicitRange = request.query["start"] != nil ||
            request.query["end"] != nil ||
            request.query["offset"] != nil ||
            request.query["from"] != nil ||
            request.query["limit"] != nil ||
            request.query["count"] != nil
        let hasPaging = request.query["p"] != nil || request.query["page"] != nil || request.query["step"] != nil
        guard hasExplicitRange || hasPaging else {
            return APIItemRange(range: 0..<total, total: total)
        }

        let pageStep = max(1, min(500, Int(request.query["step"] ?? "") ?? 50))
        let page = max(0, Int(request.query["p"] ?? request.query["page"] ?? "") ?? 0)
        let startToken = request.query["start"] ?? request.query["offset"] ?? request.query["from"]
        let start = max(0, Int(startToken ?? "") ?? (hasPaging ? page * pageStep : 0))
        let lowerBound = min(start, total)

        if let limitToken = request.query["limit"] ?? request.query["count"],
           request.query["end"] == nil,
           let limit = Int(limitToken) {
            let upperBound = min(lowerBound + max(0, limit), total)
            return APIItemRange(range: lowerBound..<upperBound, total: total)
        }

        if request.query["end"] == nil, hasPaging {
            let upperBound = min(lowerBound + pageStep, total)
            return APIItemRange(range: lowerBound..<upperBound, total: total)
        }

        let maxEnd = total - 1
        let endInclusive = min(max(0, Int(request.query["end"] ?? "") ?? maxEnd), maxEnd)
        let upperBound = lowerBound <= endInclusive ? min(endInclusive + 1, total) : lowerBound
        return APIItemRange(range: lowerBound..<upperBound, total: total)
    }

    private func apiJobObjects(in range: Range<Int>) -> [[String: Any]] {
        let orderedJobs = visibleQueueOrderedJobs
        return range.map { index in
            let job = orderedJobs[index]
            var object: [String: Any] = [
                "id": job.id.uuidString,
                "source": job.source,
                "title": job.title,
                "status": job.status.rawValue,
                "progress": job.progress,
                "completed": job.completed,
                "total": job.total,
                "message": job.message,
                "comment": job.comment,
                "range": job.rangeExpression,
                "outputPath": job.outputPath,
                "pinned": job.isPinned,
                "locked": job.isLocked,
                "runtimePaused": aria2RuntimePausedJobIDs.contains(job.id),
                "runtimeHandler": aria2RuntimeProcesses[job.id] == nil ? "" : "aria2",
                "runtimeCanLimit": canApplyAria2RuntimeLimits(for: job),
                "runtimeCanSelectFiles": canApplyAria2RuntimeFileSelection(for: job),
                "runtimeCanSeed": canApplyAria2RuntimeSeeding(for: job),
                "runtimeCanListFiles": canPreviewAria2Files(for: job),
                "runtimeCanShowPeers": canRefreshAria2Peers(for: job),
                "runtimeSelectedFiles": job.metadata["runtime_selected_files"] ?? job.metadata["selected_files"] ?? "",
                "runtimeMaxDownloadLimit": job.metadata["runtime_max_download_limit"] ?? job.metadata["max_download_limit"] ?? "",
                "runtimeMaxUploadLimit": job.metadata["runtime_max_upload_limit"] ?? job.metadata["max_upload_limit"] ?? "",
                "runtimeSeedTimeMinutes": job.metadata["runtime_seed_time_minutes"] ?? job.metadata["seed_time_minutes"] ?? "",
                "runtimeSeedRatio": job.metadata["runtime_seed_ratio"] ?? job.metadata["seed_ratio"] ?? "",
                "runtimeFileCount": job.metadata["aria2_file_count"] ?? "",
                "runtimePeerCount": job.metadata["aria2_peer_count"] ?? "",
                "metadata": job.metadata
            ]
            let legacy = OriginalHDT.lightTaskObject(
                job,
                pageCount: max(job.completed, job.total)
            )
            for (key, value) in legacy where object[key] == nil {
                object[key] = value
            }
            return object
        }
    }

    private func apiHistoryObject(_ request: LocalHTTPRequest) -> [String: Any] {
        let pairs = apiFilteredHistoryPairs(from: request)
        let rangeInfo = apiRange(from: request, total: pairs.count)
        let visible = Array(pairs[rangeInfo.range])
        let auth = apiAuthQuery(request.query["pw"] ?? request.query["password"] ?? "")
        return [
            "items": apiHistoryObjects(visible, auth: auth),
            "history": apiHistoryObjects(visible, auth: auth),
            "count": rangeInfo.range.count,
            "total": rangeInfo.total,
            "start": rangeInfo.range.lowerBound,
            "end": rangeInfo.range.isEmpty ? rangeInfo.range.lowerBound : rangeInfo.range.upperBound - 1,
            "endExclusive": rangeInfo.range.upperBound,
            "enabled": historyEnabled,
            "limit": normalizedHistoryLimit(from: historyLimitString),
            "query": apiHistoryQuery(from: request)
        ]
    }

    private func apiFilteredHistoryPairs(from request: LocalHTTPRequest) -> [(Int, DownloadHistoryEntry)] {
        let pairs: [(Int, DownloadHistoryEntry)] = history.enumerated().map { ($0.offset, $0.element) }
        let query = apiHistoryQuery(from: request).lowercased()
        guard !query.isEmpty else { return pairs }
        let terms = query.split(whereSeparator: { $0.isWhitespace }).map(String.init)
        return pairs.filter { _, entry in
            let haystack = [
                entry.source,
                entry.normalizedSource,
                entry.title,
                entry.outputPath,
                entry.metadata.keys.joined(separator: " "),
                entry.metadata.values.joined(separator: " ")
            ].joined(separator: "\n").lowercased()
            return terms.allSatisfy { haystack.contains($0) }
        }
    }

    private func apiHistoryQuery(from request: LocalHTTPRequest) -> String {
        Self.apiFirstParameterValue(in: request.query, keys: ["q", "query", "filter", "search"])?.trimmed ?? ""
    }

    private func apiHistoryObjects(_ pairs: [(Int, DownloadHistoryEntry)], auth: String) -> [[String: Any]] {
        pairs.map { index, entry in
            let enqueue = "/download?url=\(Self.queryComponent(entry.source))&start=0\(auth)"
            return [
                "index": index,
                "id": entry.id.uuidString,
                "source": entry.source,
                "normalizedSource": entry.normalizedSource,
                "title": entry.title,
                "outputPath": entry.outputPath,
                "completedAt": Self.apiDateString(entry.completedAt),
                "metadata": entry.metadata,
                "download": enqueue,
                "enqueue": enqueue
            ] as [String: Any]
        }
    }

    private func apiHistoryIndexes(from request: LocalHTTPRequest) -> [Int] {
        let parameters = apiParameters(from: request)
        let explicitIDs = parameters["ids"] ?? parameters["history_ids"] ?? parameters["historyIds"]
        if let explicitIDs {
            return apiHistoryIndexes(fromTokens: apiListValues(from: explicitIDs))
        }
        if let id = parameters["id"] ?? parameters["history_id"] ?? parameters["historyId"] {
            return apiHistoryIndexes(fromTokens: [id])
        }
        if let source = parameters["source"] ?? parameters["url"] {
            let normalized = URLIdentity.normalize(source)
            return history.indices.filter {
                history[$0].source == source ||
                    history[$0].normalizedSource == normalized ||
                    URLIdentity.normalize(history[$0].source) == normalized
            }
        }
        let query = apiHistoryQuery(from: request)
        if !query.isEmpty {
            return apiFilteredHistoryPairs(from: request).map(\.0)
        }
        if let indexes = parameters["indexes"] ?? parameters["indices"] {
            return apiHistoryIndexes(fromTokens: apiListValues(from: indexes))
        }
        if let index = parameters["index"] ?? parameters["idx"] ?? parameters["i"],
           let value = Int(index),
           history.indices.contains(value) {
            return [value]
        }
        return []
    }

    private func apiHistoryIndexes(fromTokens tokens: [String]) -> [Int] {
        var indexes: [Int] = []
        var seen = Set<Int>()
        for token in tokens {
            let value = token.trimmed
            let index: Int?
            if let uuid = UUID(uuidString: value) {
                index = history.firstIndex { $0.id == uuid }
            } else if let numeric = Int(value), history.indices.contains(numeric) {
                index = numeric
            } else {
                index = nil
            }
            guard let index, !seen.contains(index) else { continue }
            indexes.append(index)
            seen.insert(index)
        }
        return indexes
    }

    private func apiHistoryRequeueResponse(_ request: LocalHTTPRequest) -> LocalHTTPResponse {
        let indexes = apiHistoryIndexes(from: request)
        guard !indexes.isEmpty else {
            return LocalHTTPResponse.jsonObject(["error": "History entry not found"], status: 404)
        }

        let entries = indexes.map { history[$0] }
        var added = 0
        var ids: [String] = []
        for entry in entries {
            let before = jobs.count
            enqueueHistoryEntry(entry)
            let delta = jobs.count - before
            if delta > 0 {
                added += delta
                ids.append(entry.id.uuidString)
            }
        }
        let parameters = apiParameters(from: request)
        if added > 0, (parameters["start"] ?? parameters["run"] ?? "0") != "0" {
            startQueue(addingInput: false)
        }
        return LocalHTTPResponse.jsonObject([
            "ok": added > 0,
            "res": added > 0 ? "ok" : "skipped",
            "requeued": added > 0,
            "requeuedCount": added,
            "added": added,
            "id": ids.first ?? "",
            "ids": ids,
            "count": jobs.count,
            "historyCount": history.count,
            "running": isRunning
        ])
    }

    private func apiHistoryRemoveResponse(_ request: LocalHTTPRequest) -> LocalHTTPResponse {
        let indexes = apiHistoryIndexes(from: request)
        guard !indexes.isEmpty else {
            return LocalHTTPResponse.jsonObject(["error": "History entry not found"], status: 404)
        }

        let removedIDs = indexes.sorted(by: >).map { index in
            let id = history[index].id.uuidString
            history.remove(at: index)
            return id
        }
        userData.history = history
        persistUserData()
        return LocalHTTPResponse.jsonObject([
            "ok": !removedIDs.isEmpty,
            "res": !removedIDs.isEmpty ? "ok" : "skipped",
            "removed": !removedIDs.isEmpty,
            "removedCount": removedIDs.count,
            "id": removedIDs.last ?? "",
            "ids": Array(removedIDs.reversed()),
            "count": history.count
        ])
    }

    private func apiHistoryClearResponse(_ request: LocalHTTPRequest) -> LocalHTTPResponse {
        let removed = history.count
        clearHistory()
        return LocalHTTPResponse.jsonObject([
            "ok": true,
            "res": "ok",
            "cleared": true,
            "removed": removed,
            "removedCount": removed,
            "count": history.count
        ])
    }

    private func apiSearchResponse(_ request: LocalHTTPRequest) -> LocalHTTPResponse {
        let build = apiSearchBuild(from: request)
        if build.providerMissing {
            return LocalHTTPResponse.jsonObject([
                "ok": false,
                "res": "error",
                "error": "Search provider not found",
                "provider": build.providerKey
            ], status: 404)
        }
        return LocalHTTPResponse.jsonObject(apiSearchObject(request, build: build))
    }

    private func apiSearchProvidersObject(_ request: LocalHTTPRequest) -> [String: Any] {
        let password = request.query["pw"] ?? request.query["password"] ?? ""
        let auth = apiAuthQuery(password)
        let selectedID = currentSearchProvider()?.id
        var object: [String: Any] = [
            "count": searchProviders.count,
            "providers": apiSearchProviderObjects(selectedID: selectedID),
            "bookmarks": apiSearchBookmarkObjects(auth: auth),
            "bookmarkCount": searchBookmarks.count
        ]
        if let selected = currentSearchProvider() {
            object["selectedProvider"] = apiSearchProviderObject(selected, selectedID: selected.id)
        } else {
            object["selectedProvider"] = NSNull()
        }
        return object
    }

    private func apiSearchObject(
        _ request: LocalHTTPRequest,
        build: (query: String, provider: SearchProvider?, providerKey: String, providerMissing: Bool, url: URL?)
    ) -> [String: Any] {
        let password = request.query["pw"] ?? request.query["password"] ?? ""
        let auth = apiAuthQuery(password)
        let provider = build.provider
        let urlString = build.url?.absoluteString
        var object = apiSearchProvidersObject(request)
        object["ok"] = build.query.isEmpty || urlString != nil
        object["res"] = urlString == nil && !build.query.isEmpty ? "error" : "ok"
        object["query"] = build.query
        object["provider"] = provider?.name ?? build.providerKey
        object["providerID"] = provider?.id.uuidString ?? ""
        object["url"] = urlString.map { $0 as Any } ?? NSNull()
        object["searchURL"] = urlString.map { $0 as Any } ?? NSNull()
        object["enqueue"] = apiSearchEnqueueLink(query: build.query, provider: provider, auth: auth).map { $0 as Any } ?? NSNull()
        object["download"] = urlString.map { "/download?url=\(Self.queryComponent($0))&start=0\(auth)" as Any } ?? NSNull()
        return object
    }

    private func apiSearchBuild(
        from request: LocalHTTPRequest
    ) -> (query: String, provider: SearchProvider?, providerKey: String, providerMissing: Bool, url: URL?) {
        let parameters = apiParameters(from: request)
        let rawInput = Self.apiFirstParameterValue(in: parameters, keys: ["input", "text", "data"])
        let rawQuery = Self.apiFirstParameterValue(in: parameters, keys: ["q", "query", "search", "keyword", "keywords"])
        let explicitProviderKey = Self.apiFirstParameterValue(in: parameters, keys: [
            "provider", "provider_name", "providerName", "engine", "site", "name"
        ])

        var query = (rawQuery ?? rawInput ?? "").trimmed
        var parsedProviderKey: String?
        let shouldParseQuickSearch = rawQuery == nil || Self.apiTruthy(parameters["quick"])
        if shouldParseQuickSearch,
           let parsed = Self.quickSearchRequest(from: query) {
            parsedProviderKey = parsed.providerKey
            query = parsed.query
        }

        let providerKey = (explicitProviderKey ?? parsedProviderKey ?? "").trimmed
        let provider: SearchProvider?
        let providerMissing: Bool
        if providerKey.isEmpty {
            provider = currentSearchProvider()
            providerMissing = false
        } else {
            provider = Self.searchProvider(matching: providerKey, in: searchProviders)
            providerMissing = provider == nil
        }
        let url = provider.flatMap { Self.searchURL(provider: $0, query: query) }
        return (query, provider, providerKey, providerMissing, url)
    }

    private func apiSearchEnqueueResponse(_ request: LocalHTTPRequest) -> LocalHTTPResponse {
        let build = apiSearchBuild(from: request)
        if build.providerMissing {
            return LocalHTTPResponse.jsonObject([
                "ok": false,
                "res": "error",
                "error": "Search provider not found",
                "provider": build.providerKey
            ], status: 404)
        }
        guard let url = build.url else {
            return LocalHTTPResponse.jsonObject([
                "ok": false,
                "res": "error",
                "error": "Missing search query"
            ], status: 400)
        }

        let added = enqueueURLStrings([url.absoluteString])
        let parameters = apiParameters(from: request)
        let shouldStart = (parameters["start"] ?? parameters["run"] ?? "0") != "0"
        if added > 0, shouldStart {
            startQueue(addingInput: false)
        }
        let message = "\(added) URL\(added == 1 ? "" : "s") added"
        return LocalHTTPResponse.jsonObject([
            "ok": added > 0,
            "res": added > 0 ? "ok" : "skipped",
            "message": message,
            "added": added,
            "total": jobs.count,
            "running": isRunning,
            "provider": build.provider?.name ?? "",
            "providerID": build.provider?.id.uuidString ?? "",
            "query": build.query,
            "url": url.absoluteString
        ])
    }

    private func apiSearchProviderObjects(selectedID: UUID?) -> [[String: Any]] {
        searchProviders.map { apiSearchProviderObject($0, selectedID: selectedID) }
    }

    private func apiSearchProviderObject(_ provider: SearchProvider, selectedID: UUID?) -> [String: Any] {
        [
            "id": provider.id.uuidString,
            "name": provider.name,
            "urlTemplate": provider.urlTemplate,
            "createdAt": Self.apiDateString(provider.createdAt),
            "selected": provider.id == selectedID
        ]
    }

    private func apiSearchBookmarkObjects(auth: String) -> [[String: Any]] {
        searchBookmarks.map { bookmark in
            let provider = Self.searchProvider(for: bookmark, in: searchProviders)
            let url = provider.flatMap { Self.searchURL(provider: $0, query: bookmark.query) }
            return [
                "id": bookmark.id.uuidString,
                "title": bookmark.title,
                "provider": provider?.name ?? bookmark.providerName,
                "providerID": provider?.id.uuidString ?? bookmark.providerID?.uuidString ?? "",
                "query": bookmark.query,
                "createdAt": Self.apiDateString(bookmark.createdAt),
                "url": url.map { $0.absoluteString as Any } ?? NSNull(),
                "enqueue": apiSearchEnqueueLink(query: bookmark.query, provider: provider, auth: auth).map { $0 as Any } ?? NSNull()
            ] as [String: Any]
        }
    }

    private func apiSearchEnqueueLink(query: String, provider: SearchProvider?, auth: String) -> String? {
        guard let provider,
              !query.trimmed.isEmpty else {
            return nil
        }
        return "/search/enqueue?provider=\(Self.queryComponent(provider.name))&q=\(Self.queryComponent(query))&start=0\(auth)"
    }

    private func apiClipboardObject(_ request: LocalHTTPRequest, explicitText: String? = nil, source: String? = nil) -> [String: Any] {
        let input = explicitText.map { (text: $0, source: source ?? "explicit") } ?? apiClipboardInput(from: request)
        let urls = apiClipboardCandidateURLs(from: input.text)
        let monitorable = urls.filter(Self.isMonitorableURL)
        let password = request.query["pw"] ?? request.query["password"] ?? ""
        let auth = apiAuthQuery(password)
        return [
            "ok": true,
            "watch": clipboardMonitorEnabled,
            "watching": clipboardMonitorEnabled,
            "enabled": clipboardMonitorEnabled,
            "changeCount": NSPasteboard.general.changeCount,
            "source": input.source,
            "text": input.text,
            "urls": urls,
            "items": urls,
            "count": urls.count,
            "urlCount": urls.count,
            "monitorable": monitorable,
            "monitorableCount": monitorable.count,
            "inputTypes": input.text.trimmed.isEmpty ? [] : apiInputTypeObjects(from: input.text),
            "enqueue": "/clipboard/enqueue?start=0\(auth)",
            "watchAction": "/clipboard/watch\(auth)"
        ] as [String: Any]
    }

    private func apiClipboardInput(from request: LocalHTTPRequest) -> (text: String, source: String) {
        let parameters = apiParameters(from: request)
        if let value = Self.apiFirstParameterValue(in: parameters, keys: [
            "text", "input", "data", "clipboard", "url", "urls"
        ]) {
            return (value, "parameter")
        }

        let body = request.bodyText
        let contentType = request.headers["content-type"]?.lowercased() ?? ""
        if !body.trimmed.isEmpty,
           !contentType.contains("application/json"),
           !contentType.contains("application/x-www-form-urlencoded") {
            return (body, "body")
        }

        return (clipboardInputText() ?? "", "clipboard")
    }

    private func apiClipboardCandidateURLs(from text: String) -> [String] {
        clipboardCandidateURLs(from: text)
    }

    private func apiClipboardEnqueueResponse(_ request: LocalHTTPRequest) -> LocalHTTPResponse {
        let input = apiClipboardInput(from: request)
        let urls = apiClipboardCandidateURLs(from: input.text)
        guard !urls.isEmpty else {
            return LocalHTTPResponse.jsonObject([
                "ok": false,
                "res": "error",
                "error": "Missing clipboard URLs",
                "watch": clipboardMonitorEnabled,
                "count": 0
            ], status: 400)
        }

        let added = enqueueURLStrings(urls)
        let parameters = apiParameters(from: request)
        let shouldStart = (parameters["start"] ?? parameters["run"] ?? "0") != "0"
        if added > 0, shouldStart {
            startQueue(addingInput: false)
        }
        let message = "\(added) clipboard URL\(added == 1 ? "" : "s") added"
        return LocalHTTPResponse.jsonObject([
            "ok": added > 0,
            "res": added > 0 ? "ok" : "skipped",
            "message": message,
            "added": added,
            "total": jobs.count,
            "running": isRunning,
            "watch": clipboardMonitorEnabled,
            "source": input.source,
            "urls": urls
        ] as [String: Any])
    }

    private func apiClipboardWatchResponse(_ request: LocalHTTPRequest) -> LocalHTTPResponse {
        let parameters = apiParameters(from: request)
        let raw = Self.apiFirstParameterValue(in: parameters, keys: [
            "enabled", "enable", "watch", "watching", "value", "state", "on"
        ])?.lowercased()
        let enabled: Bool
        if raw == nil || raw == "toggle" {
            enabled = !clipboardMonitorEnabled
        } else {
            enabled = Self.apiTruthy(raw)
        }
        setClipboardMonitorEnabled(enabled)
        return LocalHTTPResponse.jsonObject([
            "ok": true,
            "res": "ok",
            "watch": clipboardMonitorEnabled,
            "watching": clipboardMonitorEnabled,
            "enabled": clipboardMonitorEnabled,
            "message": addSummary
        ])
    }

    private func apiBrowserObject(_ request: LocalHTTPRequest) -> [String: Any] {
        let selection = apiBrowserURLSelection(from: request)
        let password = request.query["pw"] ?? request.query["password"] ?? ""
        let auth = apiAuthQuery(password)
        guard let url = selection.url else {
            return [
                "ok": false,
                "res": "error",
                "error": "Missing browser URL",
                "url": NSNull(),
                "source": selection.source,
                "cookieSummary": cookieSummary
            ] as [String: Any]
        }
        let urlString = url.absoluteString
        return [
            "ok": true,
            "res": "ok",
            "url": urlString,
            "browserURL": urlString,
            "source": selection.source,
            "cookieSummary": cookieSummary,
            "open": "/browser/open?url=\(Self.queryComponent(urlString))\(auth)"
        ] as [String: Any]
    }

    private func apiBrowserURLSelection(from request: LocalHTTPRequest) -> (url: URL?, source: String) {
        let parameters = apiParameters(from: request)
        if let raw = Self.apiFirstParameterValue(in: parameters, keys: [
            "url", "input", "text", "address", "href", "site", "target"
        ]) {
            return (Self.firstWebURL(from: raw), "parameter")
        }
        return (Self.loginBrowserURL(inputText: inputText, jobs: jobs), inputText.trimmed.isEmpty ? "queue" : "input")
    }

    private func apiBrowserOpenResponse(_ request: LocalHTTPRequest) -> LocalHTTPResponse {
        let selection = apiBrowserURLSelection(from: request)
        guard let url = selection.url else {
            return LocalHTTPResponse.jsonObject([
                "ok": false,
                "res": "error",
                "error": "Missing browser URL"
            ], status: 400)
        }

        let parameters = apiParameters(from: request)
        let dryRun = Self.apiTruthy(parameters["dry_run"]) || Self.apiTruthy(parameters["dryRun"])
        let openValue = parameters["open"] ?? parameters["run"]
        let shouldOpen = dryRun ? false : openValue.map(Self.apiTruthy) ?? true
        if shouldOpen {
            if Self.isPixivWebURL(url) {
                presentPixivLoginBrowser()
            } else if Self.isChzzkWebURL(url) {
                presentChzzkLoginBrowser()
            } else if Self.isNaverCafeWebURL(url) {
                presentNaverCafeLoginBrowser()
            } else if Self.isTwitterWebURL(url) {
                presentTwitterLoginBrowser()
            } else if Self.isPornhubPremiumWebURL(url) {
                presentPornhubLoginBrowser()
            } else if Self.isArcaliveWebURL(url) {
                presentArcaliveLoginBrowser(loginURL: url)
            } else {
                LoginBrowserWindowController.open(url: url) { [weak self] imported, skipped in
                    guard let self else { return }
                    self.cookieSummary = Self.browserCookieSummary(imported: imported, skipped: skipped)
                    self.addSummary = imported > 0 ? "Login cookies saved" : "No login cookies found"
                }
            }
            addSummary = "Login browser opened"
        }

        return LocalHTTPResponse.jsonObject([
            "ok": true,
            "res": "ok",
            "opened": shouldOpen,
            "dryRun": !shouldOpen,
            "url": url.absoluteString,
            "source": selection.source,
            "cookieSummary": cookieSummary
        ] as [String: Any])
    }

    private func apiNamesObject() -> [String: Any] {
        [
            "count": jobs.count,
            "names": jobs.enumerated().map { index, job in
                [
                    "index": index,
                    "id": job.id.uuidString,
                    "title": job.title,
                    "source": job.source,
                    "status": job.status.rawValue,
                    "comment": job.comment,
                    "range": job.rangeExpression,
                    "pinned": job.isPinned,
                    "locked": job.isLocked
                ] as [String: Any]
            }
        ]
    }

    private func apiNamesObject(_ request: LocalHTTPRequest) -> [String: Any] {
        guard let jobIndex = apiJobIndex(from: request) else {
            return apiNamesObject()
        }

        let job = jobs[jobIndex]
        let files = apiOutputFiles(for: job)
        let fileObjects: [[String: Any]] = files.map { file in
            var object = [
                "index": file.originalIndex,
                "name": Self.apiOutputDisplayName(file),
                "relativePath": file.relativePath,
                "path": Self.apiOutputDisplayPath(file),
                "type": Self.apiMediaType(for: file.url)
            ] as [String: Any]
            if let archiveURL = file.archiveURL {
                object["archivePath"] = archiveURL.path
                object["archiveEntry"] = file.relativePath
            }
            return object
        }

        return [
            "index": jobIndex,
            "id": job.id.uuidString,
            "title": job.title,
            "source": job.source,
            "count": files.count,
            "names": files.map(\.relativePath),
            "files": fileObjects
        ]
    }

    private func apiNamesResponse(_ request: LocalHTTPRequest, originalShape: Bool) -> LocalHTTPResponse {
        if originalShape,
           apiJobIndex(from: request) != nil,
           !apiNamesWantsObjectResponse(request) {
            return LocalHTTPResponse.jsonObject(apiNamesArray(request))
        }

        return LocalHTTPResponse.jsonObject(apiNamesObject(request))
    }

    private func apiNamesArray(_ request: LocalHTTPRequest) -> [String] {
        guard let jobIndex = apiJobIndex(from: request) else { return [] }
        return apiOutputFiles(for: jobs[jobIndex]).map(\.relativePath)
    }

    private func apiNamesWantsObjectResponse(_ request: LocalHTTPRequest) -> Bool {
        let parameters = apiParameters(from: request)
        let shape = (parameters["format"] ??
            parameters["shape"] ??
            parameters["response"] ??
            parameters["mode"] ??
            "").trimmed.lowercased()
        if ["object", "dict", "map", "full", "detail", "details"].contains(shape) {
            return true
        }
        return Self.apiTruthy(parameters["object"]) ||
            Self.apiTruthy(parameters["details"]) ||
            Self.apiTruthy(parameters["files"])
    }

    private func apiUsesOriginalActionShape(_ request: LocalHTTPRequest) -> Bool {
        if request.path.lowercased().hasPrefix("/api/") {
            return false
        }

        let parameters = apiParameters(from: request)
        let shape = (parameters["format"] ??
            parameters["shape"] ??
            parameters["response"] ??
            "").trimmed.lowercased()
        if ["object", "native", "full", "detail", "details"].contains(shape) {
            return false
        }
        return !Self.apiTruthy(parameters["native"]) &&
            !Self.apiTruthy(parameters["details"])
    }

    private func apiTypesObject(_ request: LocalHTTPRequest? = nil) -> [String: Any] {
        var statusCounts: [String: Int] = [:]
        var mediaCounts: [String: Int] = [:]

        let items: [[String: Any]] = jobs.enumerated().map { index, job in
            statusCounts[job.status.rawValue, default: 0] += 1
            let files = apiOutputFiles(for: job)
            var outputTypes: [String: Int] = [:]
            for file in files {
                let type = Self.apiMediaType(for: file.url)
                outputTypes[type, default: 0] += 1
                mediaCounts[type, default: 0] += 1
            }

            let sourceURL = URL(string: job.source)
            return [
                "index": index,
                "id": job.id.uuidString,
                "title": job.title,
                "status": job.status.rawValue,
                "comment": job.comment,
                "range": job.rangeExpression,
                "pinned": job.isPinned,
                "locked": job.isLocked,
                "source": job.source,
                "scheme": sourceURL?.scheme ?? "",
                "host": sourceURL?.host ?? "",
                "outputTypes": outputTypes,
                "fileCount": files.count
            ] as [String: Any]
        }

        var result: [String: Any] = [
            "count": jobs.count,
            "statuses": statusCounts,
            "mediaTypes": mediaCounts,
            "supportedMediaTypes": ["image", "video", "audio", "document", "file"],
            "items": items
        ]

        if let request,
           let input = apiTypeInput(from: request)?.trimmed,
           !input.isEmpty {
            let inputTypes = apiInputTypeObjects(from: input)
            var seenTypes = Set<String>()
            let types = inputTypes.compactMap { $0["type"] as? String }.filter { type in
                guard !type.isEmpty, !seenTypes.contains(type) else { return false }
                seenTypes.insert(type)
                return true
            }
            result["input"] = input
            result["types"] = types
            result["inputTypes"] = inputTypes
        }

        return result
    }

    private func apiTypeInput(from request: LocalHTTPRequest) -> String? {
        let parameters = apiParameters(from: request)
        if let input = parameters["input"] ?? parameters["url"] ?? parameters["urls"],
           !input.trimmed.isEmpty {
            return input
        }

        let bodyText = request.bodyText.trimmed
        return bodyText.isEmpty ? nil : bodyText
    }

    private func apiInputTypeObjects(from input: String) -> [[String: Any]] {
        var seen = Set<String>()
        return apiInputTokens(from: input).compactMap { token -> [String: Any]? in
            let normalized = token.normalized.trimmed
            guard !normalized.isEmpty else { return nil }
            let identity = normalized.lowercased()
            guard !seen.contains(identity) else { return nil }
            seen.insert(identity)

            let url = URL(string: normalized)
            let classification = apiInputClassification(for: normalized, url: url)
            var object: [String: Any] = [
                "raw": token.raw,
                "normalized": normalized,
                "type": classification.type,
                "resolver": classification.resolver,
                "valid": classification.valid
            ]

            if let url {
                object["scheme"] = url.scheme?.lowercased() ?? ""
                object["host"] = url.host?.lowercased() ?? ""
                object["pathExtension"] = url.pathExtension.lowercased()
                object["mediaType"] = Self.apiMediaType(for: url)
            } else {
                object["scheme"] = ""
                object["host"] = ""
                object["pathExtension"] = ""
                object["mediaType"] = ""
            }

            return object
        }
    }

    private func apiInputTokens(from input: String) -> [(raw: String, normalized: String)] {
        input
            .components(separatedBy: .newlines)
            .flatMap { line -> [(raw: String, normalized: String)] in
                let trimmedLine = line.trimmed
                guard !trimmedLine.isEmpty else { return [] }
                if let hitomiURL = Self.hitomiCustomURIString(from: Self.cleanedClipboardToken(trimmedLine)) {
                    return [(trimmedLine, hitomiURL)]
                }
                if let sankakuURL = Self.sankakuTagInputURLString(from: trimmedLine) {
                    return [(trimmedLine, sankakuURL)]
                }
                if let booruURL = Self.booruTagInputURLString(from: trimmedLine) {
                    return [(trimmedLine, booruURL)]
                }
                if let searchURL = quickSearchURLString(from: trimmedLine) {
                    return [(trimmedLine, searchURL)]
                }
                return trimmedLine
                    .components(separatedBy: .whitespacesAndNewlines)
                    .map { raw in (raw, Self.normalizedInputToken(raw)) }
            }
            .filter { !$0.normalized.isEmpty }
    }

    private func apiInputClassification(for source: String, url: URL?) -> (type: String, resolver: String, valid: Bool) {
        if discordEmojiResolver.canResolve(source) {
            return ("emoji", "Discord Emoji", true)
        }

        guard let url,
              let scheme = url.scheme?.lowercased(),
              !scheme.isEmpty else {
            return ("unsupported", "unsupported", false)
        }

        if scheme == "magnet" {
            return ("torrent", "aria2", true)
        }

        if scheme == "file" {
            if aria2Bridge.canResolve(url) {
                return ("torrent", "aria2", true)
            }
            return ("file", "Local File", true)
        }

        guard scheme == "http" || scheme == "https" else {
            return ("unsupported", "unsupported", false)
        }

        if aria2Bridge.canResolve(url) {
            return ("torrent", "aria2", true)
        }
        if mpdResolver.canResolve(url) {
            return ("dash", "MPD", true)
        }
        if m3u8Resolver.canResolve(url) {
            return ("hls", "M3U8", true)
