            ("gallery", "Sankaku", { self.sankakuResolver.canResolve($0) }),
            ("gallery", "Booru", { self.booruResolver.canResolve($0) })
        ]

        if let match = resolverChecks.first(where: { $0.canResolve(url) }) {
            return (match.type, match.resolver, true)
        }

        if matchingCustomCommandRule(for: url) != nil {
            return ("custom", "Custom Command", true)
        }
        if ytdlpBridge.canResolve(url, siteRules: siteRules) {
            return ("media", "yt-dlp", true)
        }

        let mediaType = Self.apiMediaType(for: url)
        if mediaType != "file", !url.pathExtension.isEmpty {
            return (mediaType, "Direct File", true)
        }
        if genericPageResolver.canResolve(url) {
            return ("web", "Generic Page", true)
        }

        return ("file", "Direct File", true)
    }

    private func apiHeadersObject(_ request: LocalHTTPRequest) -> [String: Any] {
        let headerItems: [[String: Any]] = request.headers.keys.sorted().map { key in
            [
                "key": key,
                "name": key,
                "value": request.headers[key] ?? ""
            ]
        }
        var requestHeaders: [String: Any] = [
            "method": request.method,
            "path": request.path,
            "contentType": request.headers["content-type"] ?? "",
            "userAgent": request.headers["user-agent"] ?? "",
            "accept": request.headers["accept"] ?? "",
            "hasAuthorization": request.headers["authorization"] != nil,
            "hasPasswordHeader": request.headers["x-hitomi-password"] != nil
        ]

        if let range = request.headers["range"], !range.isEmpty {
            requestHeaders["range"] = range
        }

        return [
            "headers": request.headers,
            "items": headerItems,
            "count": headerItems.count,
            "request": requestHeaders,
            "response": [
                "contentType": "application/json; charset=utf-8",
                "cors": "http://127.0.0.1:\(httpAPIPortString)"
            ],
            "auth": [
                "passwordRequired": !httpAPIPassword.trimmed.isEmpty,
                "acceptedQueryKeys": ["pw", "password"],
                "acceptedHeaders": ["X-Hitomi-Password", "Authorization: Bearer <password>"]
            ]
        ]
    }

    private func apiUpdateCookiesResponse(_ request: LocalHTTPRequest) async -> LocalHTTPResponse {
        let cookieText = apiCookieText(from: request).trimmed
        guard !cookieText.isEmpty else {
            return LocalHTTPResponse.jsonObject(["error": "Missing cookies"], status: 400)
        }

        let result = await CookieStore.shared.importText(cookieText)
        let total = await CookieStore.shared.count
        cookieSummary = Self.storedCookieSummary(count: total)
        if result.skipped > 0 {
            cookieSummary += ", \(result.skipped) skipped"
        }

        let message = "\(result.imported) cookie\(result.imported == 1 ? "" : "s") imported"
        return LocalHTTPResponse.jsonObject([
            "ok": result.imported > 0,
            "res": apiUsesOriginalActionShape(request) ? "ok" : message,
            "message": message,
            "updated": result.imported > 0,
            "imported": result.imported,
            "skipped": result.skipped,
            "count": total
        ])
    }

    private func apiCookieText(from request: LocalHTTPRequest) -> String {
        let body = request.bodyText.trimmed
        let contentType = request.headers["content-type"]?.lowercased() ?? ""

        if (contentType.contains("application/json") || Self.apiLooksLikeJSONBody(body)),
           let jsonCookieText = Self.apiCookieText(fromJSONBody: body),
           !jsonCookieText.trimmed.isEmpty {
            return jsonCookieText
        }

        let parameters = apiParameters(from: request)
        if let value = parameters["cookies"] ?? parameters["cookie"] ?? parameters["text"] ?? parameters["data"],
           !value.trimmed.isEmpty {
            return value
        }

        guard !body.isEmpty else { return "" }

        if contentType.contains("application/json") || contentType.contains("application/x-www-form-urlencoded") {
            return ""
        }
        return body
    }

    private static func apiCookieText(fromJSONBody body: String) -> String? {
        guard !body.isEmpty,
              let data = body.data(using: .utf8),
              let object = try? JSONSerialization.jsonObject(with: data) else {
            return nil
        }
        return apiCookieText(fromJSONValue: object)
    }

    private static func apiCookieText(fromJSONValue value: Any) -> String? {
        if let string = value as? String {
            return string.trimmed.isEmpty ? nil : string
        }
        if let array = value as? [Any] {
            let lines = array.compactMap { apiCookieText(fromJSONValue: $0) }
            return lines.isEmpty ? nil : lines.joined(separator: "\n")
        }
        guard let dictionary = value as? [String: Any] else { return nil }

        if let nested = apiJSONValue(in: dictionary, keys: ["cookies", "cookie", "text", "data"]) {
            return apiCookieText(fromJSONValue: nested)
        }
        return apiCookieLine(fromJSONCookie: dictionary)
    }

    private static func apiCookieLine(fromJSONCookie dictionary: [String: Any]) -> String? {
        guard let name = apiJSONString(in: dictionary, keys: ["name", "key"]),
              !name.trimmed.isEmpty,
              let value = apiJSONString(in: dictionary, keys: ["value"], allowEmpty: true) else {
            return nil
        }

        let domain = apiJSONString(in: dictionary, keys: ["domain", "host"]) ??
            apiJSONString(in: dictionary, keys: ["url"]).flatMap { URL(string: $0)?.host } ??
            "*"
        let path = apiJSONString(in: dictionary, keys: ["path"]) ?? "/"
        let secure = apiJSONBool(in: dictionary, keys: ["secure", "isSecure"]) ?? false
        let hostOnly = apiJSONBool(in: dictionary, keys: ["hostOnly", "host_only"])
        let includeSubdomains = apiJSONBool(in: dictionary, keys: ["includeSubdomains", "include_subdomains"]) ??
            (hostOnly.map { !$0 } ?? domain.hasPrefix("."))
        let expires = apiJSONDouble(in: dictionary, keys: [
            "expirationDate",
            "expires",
            "expiry",
            "expiresAt",
            "expires_at",
            "expiration"
        ]).map { String(Int($0)) } ?? "0"
        let lineDomain = (apiJSONBool(in: dictionary, keys: ["httpOnly", "http_only"]) == true)
            ? "#HttpOnly_\(domain)"
            : domain

        return [
            lineDomain,
            includeSubdomains ? "TRUE" : "FALSE",
            path,
            secure ? "TRUE" : "FALSE",
            expires,
            name,
            value
        ].joined(separator: "\t")
    }

    private static func apiJSONValue(in dictionary: [String: Any], keys: [String]) -> Any? {
        let normalized = Set(keys.map { $0.lowercased() })
        return dictionary.first { normalized.contains($0.key.lowercased()) }?.value
    }

    private static func apiJSONString(in dictionary: [String: Any], keys: [String], allowEmpty: Bool = false) -> String? {
        guard let value = apiJSONValue(in: dictionary, keys: keys), !(value is NSNull) else {
            return nil
        }
        let string = apiParameterString(from: value)
        if !allowEmpty, string.trimmed.isEmpty {
            return nil
        }
        return string
    }

    private static func apiJSONBool(in dictionary: [String: Any], keys: [String]) -> Bool? {
        guard let value = apiJSONValue(in: dictionary, keys: keys), !(value is NSNull) else {
            return nil
        }
        if let bool = value as? Bool {
            return bool
        }
        if let number = value as? NSNumber {
            return number.boolValue
        }
        return apiTruthy(apiParameterString(from: value))
    }

    private static func apiJSONDouble(in dictionary: [String: Any], keys: [String]) -> Double? {
        guard let value = apiJSONValue(in: dictionary, keys: keys), !(value is NSNull) else {
            return nil
        }
        if let number = value as? NSNumber {
            return number.doubleValue
        }
        return Double(apiParameterString(from: value).trimmed)
    }

    private func apiInfoResponse(_ request: LocalHTTPRequest) -> LocalHTTPResponse {
        guard let jobIndex = apiJobIndex(from: request) else {
            return LocalHTTPResponse.jsonObject(["error": "Task not found"], status: 404)
        }

        let password = request.query["pw"] ?? request.query["password"] ?? ""
        let logicalIndex = queueOrderedJobIndices.firstIndex(of: jobIndex) ?? jobIndex
        let job = jobs[jobIndex]
        let info = apiJobInfoObject(job: job, index: logicalIndex, auth: apiAuthQuery(password))
        let legacy = OriginalHDT.lightTaskObject(job, pageCount: info["fileCount"] as? Int)
        var response = info
        for (key, value) in legacy where response[key] == nil {
            response[key] = value
        }
        response["item"] = legacy
        return LocalHTTPResponse.jsonObject(response)
    }

    private func apiPDFResponse(_ request: LocalHTTPRequest) -> LocalHTTPResponse {
        guard let jobIndex = apiJobIndex(from: request) else {
            return LocalHTTPResponse.jsonObject(["error": "Task not found"], status: 404)
        }

        let parameters = apiParameters(from: request)
        let requestedTitle = Self.apiFirstParameterValue(in: parameters, keys: ["title", "name", "filename"])
        let title = requestedTitle ?? jobs[jobIndex].title

        do {
            let pdfURL = try Self.createPDF(fromOutputPath: jobs[jobIndex].outputPath, title: title)
            let createdAt = ISO8601DateFormatter().string(from: Date())
            jobs[jobIndex].metadata["pdf_path"] = pdfURL.path
            jobs[jobIndex].metadata["pdf_created_at"] = createdAt
            jobs[jobIndex].message = "PDF created"
            persistQueue()

            if apiPDFWantsFile(parameters) {
                let data = try Data(contentsOf: pdfURL)
                let disposition = Self.apiTruthy(parameters["attachment"]) ? "attachment" : "inline"
                let filename = pdfURL.lastPathComponent.replacingOccurrences(of: "\"", with: "")
                return LocalHTTPResponse.data(
                    data,
                    contentType: "application/pdf",
                    headers: [
                        "Content-Disposition": "\(disposition); filename=\"\(filename)\""
                    ]
                )
            }

            let auth = apiAuthQuery(request.query["pw"] ?? request.query["password"] ?? "")
            return LocalHTTPResponse.jsonObject([
                "ok": true,
                "res": "ok",
                "created": true,
                "id": jobs[jobIndex].id.uuidString,
                "index": jobIndex,
                "path": pdfURL.path,
                "filename": pdfURL.lastPathComponent,
                "pdfPath": pdfURL.path,
                "pdfCreatedAt": createdAt,
                "download": "/pdf?uid=\(jobs[jobIndex].id.uuidString)&download=1\(auth)"
            ])
        } catch {
            return LocalHTTPResponse.jsonObject([
                "ok": false,
                "error": error.localizedDescription,
                "res": "error"
            ], status: 400)
        }
    }

    private func apiPDFWantsFile(_ parameters: [String: String]) -> Bool {
        if Self.apiTruthy(parameters["download"]) ||
            Self.apiTruthy(parameters["file"]) ||
            Self.apiTruthy(parameters["inline"]) ||
            Self.apiTruthy(parameters["raw"]) {
            return true
        }
        let format = Self.apiFirstParameterValue(in: parameters, keys: ["format", "response", "type"])?.lowercased()
        return ["pdf", "file", "download", "binary", "raw"].contains(format ?? "")
    }

    private func apiArchiveResponse(_ request: LocalHTTPRequest) -> LocalHTTPResponse {
        guard let jobIndex = apiJobIndex(from: request) else {
            return LocalHTTPResponse.jsonObject(["error": "Task not found"], status: 404)
        }

        let parameters = apiParameters(from: request)
        let defaultFormat: ArchiveFileFormat = request.path.lowercased().contains("cbz") ? .cbz : .zip
        let format = apiArchiveFormat(parameters, defaultFormat: defaultFormat)

        do {
            let result = try apiCreateArchive(forJobAt: jobIndex, format: format, parameters: parameters)
            let createdAt = ISO8601DateFormatter().string(from: Date())
            jobs[jobIndex].metadata["archive_path"] = result.url.path
            jobs[jobIndex].metadata["archive_format"] = result.format.rawValue
            jobs[jobIndex].metadata["archive_created_at"] = createdAt
            jobs[jobIndex].metadata["archive_deleted_original"] = result.deletedOriginal ? "true" : "false"
            jobs[jobIndex].message = "\(result.format.label) \(result.created ? "created" : "ready")"
            persistQueue()

            if apiArchiveWantsFile(parameters, format: result.format) {
                let data = try Data(contentsOf: result.url)
                let disposition = Self.apiTruthy(parameters["attachment"]) ? "attachment" : "inline"
                let filename = result.url.lastPathComponent.replacingOccurrences(of: "\"", with: "")
                return LocalHTTPResponse.data(
                    data,
                    contentType: "application/zip",
                    headers: [
                        "Content-Disposition": "\(disposition); filename=\"\(filename)\""
                    ]
                )
            }

            let auth = apiAuthQuery(request.query["pw"] ?? request.query["password"] ?? "")
            let path = result.format == .cbz ? "/cbz" : "/zip"
            return LocalHTTPResponse.jsonObject([
                "ok": true,
                "res": "ok",
                "created": result.created,
                "id": jobs[jobIndex].id.uuidString,
                "index": jobIndex,
                "path": result.url.path,
                "filename": result.url.lastPathComponent,
                "archivePath": result.url.path,
                "archiveFormat": result.format.rawValue,
                "archiveCreatedAt": createdAt,
                "deletedOriginal": result.deletedOriginal,
                "download": "\(path)?uid=\(jobs[jobIndex].id.uuidString)&download=1\(auth)"
            ])
        } catch {
            return LocalHTTPResponse.jsonObject([
                "ok": false,
                "error": error.localizedDescription,
                "res": "error"
            ], status: 400)
        }
    }

    private func apiArchiveFormat(_ parameters: [String: String], defaultFormat: ArchiveFileFormat) -> ArchiveFileFormat {
        let raw = Self.apiFirstParameterValue(in: parameters, keys: [
            "format", "archive_format", "archiveFormat", "ext", "extension", "type",
            "mode", "action", "cmd", "command", "function", "name"
        ])?.trimmed.lowercased() ?? ""
        switch raw {
        case "cbz", ".cbz", "create_cbz", "createcbz", "make_cbz", "makecbz", "comic", "comicbook", "comic_book", "comic-book":
            return .cbz
        case "zip", ".zip", "create_zip", "createzip", "make_zip", "makezip", "archive":
            return .zip
        default:
            return defaultFormat
        }
    }

    private func apiCreateArchive(
        forJobAt jobIndex: Int,
        format: ArchiveFileFormat,
        parameters: [String: String]
    ) throws -> (url: URL, format: ArchiveFileFormat, created: Bool, deletedOriginal: Bool) {
        let source = URL(fileURLWithPath: jobs[jobIndex].outputPath)
        var isDirectory: ObjCBool = false
        let exists = FileManager.default.fileExists(atPath: source.path, isDirectory: &isDirectory)

        if exists, !isDirectory.boolValue, ["zip", "cbz"].contains(source.pathExtension.lowercased()) {
            let existingFormat = ArchiveFileFormat(rawValue: source.pathExtension.lowercased()) ?? format
            return (source, existingFormat, false, false)
        }

        guard exists, isDirectory.boolValue else {
            throw NativeDownloadError.unsupported("Output folder was not found.")
        }

        let requestedName = Self.apiFirstParameterValue(in: parameters, keys: ["filename", "download_name", "downloadname", "name", "title"])
        let filename = apiArchiveFilename(requestedName, fallbackBaseName: source.lastPathComponent, format: format)
        let destination = AppPaths.uniqueFileURL(in: source.deletingLastPathComponent(), filename: filename)
        let deleteOriginal = apiArchiveDeletesOriginal(parameters)
        let archived = try Self.archiveCompletedFolder(source, to: destination, deleteOriginal: deleteOriginal)
        if deleteOriginal || Self.apiTruthy(parameters["replace"]) || Self.apiTruthy(parameters["set_output"]) || Self.apiTruthy(parameters["setOutput"]) {
            jobs[jobIndex].outputPath = archived.path
        }
        return (archived, format, true, deleteOriginal)
    }

    private func apiArchiveFilename(_ raw: String?, fallbackBaseName: String, format: ArchiveFileFormat) -> String {
        let fallback = "\(fallbackBaseName).\(format.fileExtension)"
        var filename = (raw?.trimmed.isEmpty == false ? raw!.trimmed : fallback).sanitizedFilename(maxLength: 180)
        let suffix = ".\(format.fileExtension)"
        if filename.lowercased().hasSuffix(".zip") || filename.lowercased().hasSuffix(".cbz") {
            filename = String(filename.dropLast(4))
        }
        return filename.isEmpty ? fallback : "\(filename)\(suffix)"
    }

    private func apiArchiveDeletesOriginal(_ parameters: [String: String]) -> Bool {
        Self.apiTruthy(Self.apiFirstParameterValue(in: parameters, keys: [
            "delete", "delete_original", "deleteOriginal", "remove_original",
            "removeOriginal", "delete_folder", "deleteFolder"
        ]))
    }

    private func apiArchiveWantsFile(_ parameters: [String: String], format: ArchiveFileFormat) -> Bool {
        if Self.apiTruthy(parameters["download"]) ||
            Self.apiTruthy(parameters["file"]) ||
            Self.apiTruthy(parameters["inline"]) ||
            Self.apiTruthy(parameters["raw"]) {
            return true
        }
        let response = Self.apiFirstParameterValue(in: parameters, keys: ["response", "return", "output"])?.lowercased()
        if ["file", "download", "binary", "raw", "archive"].contains(response ?? "") {
            return true
        }
        let type = Self.apiFirstParameterValue(in: parameters, keys: ["type"])?.lowercased()
        return type == format.fileExtension
    }

    private nonisolated static func apiCanArchiveOutputPath(_ path: String, fileManager: FileManager = .default) -> Bool {
        let value = path.trimmed
        guard !value.isEmpty else { return false }
        let output = URL(fileURLWithPath: value)
        var isDirectory: ObjCBool = false
        if fileManager.fileExists(atPath: output.path, isDirectory: &isDirectory) {
            return isDirectory.boolValue || ["zip", "cbz"].contains(output.pathExtension.lowercased())
        }
        return archiveSiblingURL(forMissingOutput: output, fileManager: fileManager) != nil
    }

    private func apiJobInfoObject(job: DownloadJob, index: Int, auth: String) -> [String: Any] {
        let files = apiOutputFiles(for: job)
        let uid = job.id.uuidString
        let imageIndexes = files.enumerated()
            .filter { Self.imageExtensions.contains($0.element.url.pathExtension.lowercased()) }
            .map(\.offset)
        let readerURL: Any = imageIndexes.isEmpty ? NSNull() : "/view?uid=\(uid)&mode=book&page=0\(auth)"

        var object: [String: Any] = [
            "index": index,
            "id": uid,
            "source": job.source,
            "title": job.title,
            "status": job.status.rawValue,
            "progress": job.progress,
            "completed": job.completed,
            "total": job.total,
            "message": job.message,
            "comment": job.comment,
            "range": job.rangeExpression,
            "outputPath": job.outputPath,
            "pinned": job.isPinned,
            "locked": job.isLocked,
            "tags": TaskTagColor.normalizedRawValues(job.tags),
            "metadata": job.metadata,
            "fileCount": files.count,
            "imageCount": imageIndexes.count,
            "files": apiFileObjects(files, uid: uid, auth: auth),
            "chapters": apiChapterObjects(files, uid: uid, auth: auth),
            "reader": [
                "available": !imageIndexes.isEmpty,
                "imageCount": imageIndexes.count,
                "imageIndexes": imageIndexes,
                "firstPage": readerURL
            ],
            "links": [
                "view": "/view?uid=\(uid)\(auth)",
                "reader": readerURL,
                "pageSelector": "/page_selector?uid=\(uid)\(auth)",
                "pageSelectorAPI": "/api/page_selector?uid=\(uid)\(auth)",
                "pdf": "/pdf?uid=\(uid)\(auth)",
                "pdfDownload": "/pdf?uid=\(uid)&download=1\(auth)",
                "zip": "/zip?uid=\(uid)\(auth)",
                "zipDownload": "/zip?uid=\(uid)&download=1\(auth)",
                "archive": "/archive?uid=\(uid)\(auth)",
                "archiveDownload": "/archive?uid=\(uid)&download=1\(auth)"
            ]
        ]

        if files.isEmpty {
            object["chapters"] = []
        }
        object["pdf"] = [
            "available": Self.pdfImageSources(fromOutputPath: job.outputPath).isEmpty == false,
            "create": "/pdf?uid=\(uid)\(auth)",
            "download": "/pdf?uid=\(uid)&download=1\(auth)"
        ]
        object["archive"] = [
            "available": Self.apiCanArchiveOutputPath(job.outputPath),
            "zip": "/zip?uid=\(uid)\(auth)",
            "zipDownload": "/zip?uid=\(uid)&download=1\(auth)",
            "cbz": "/cbz?uid=\(uid)\(auth)",
            "cbzDownload": "/cbz?uid=\(uid)&download=1\(auth)"
        ]
        return object
    }

    private func apiFileObjects(_ files: [APIOutputFile], uid: String, auth: String) -> [[String: Any]] {
        files.enumerated().map { index, file in
            let type = Self.apiMediaType(for: file.url)
            var object: [String: Any] = [
                "index": index,
                "name": Self.apiOutputDisplayName(file),
                "relativePath": file.relativePath,
                "path": Self.apiOutputDisplayPath(file),
                "type": type,
                "mimeType": Self.mimeType(for: file.url),
                "size": apiOutputFileSize(file),
                "modifiedAt": apiOutputFileModifiedDate(file).map(Self.apiDateString) ?? NSNull(),
                "file": "/file?uid=\(uid)&index=\(index)\(auth)",
                "download": "/file?uid=\(uid)&index=\(index)&download=1\(auth)",
                "view": "/view?uid=\(uid)&index=\(index)\(auth)"
            ]
            if let archiveURL = file.archiveURL {
                object["archivePath"] = archiveURL.path
                object["archiveEntry"] = file.relativePath
            }

            if type == "image" || type == "video" {
                object["thumb"] = "/thumb?uid=\(uid)&index=\(index)\(auth)"
            }

            return object
        }
    }

    private func apiChapterGroups(_ files: [APIOutputFile]) -> [APIChapterGroup] {
        var groups: [APIChapterGroup] = []
        var positions: [String: Int] = [:]

        for (index, file) in files.enumerated() {
            let parts = file.relativePath.split(separator: "/", omittingEmptySubsequences: true).map(String.init)
            let path = parts.count > 1 ? parts[0] : ""
            let key = path.isEmpty ? "__root__" : path
            let title = path.isEmpty ? "Files" : path

            if let position = positions[key] {
                groups[position].indexes.append(index)
            } else {
                positions[key] = groups.count
                groups.append(APIChapterGroup(title: title, path: path, indexes: [index]))
            }
        }

        return groups
    }

    private func apiChapterObjects(_ files: [APIOutputFile], uid: String, auth: String) -> [[String: Any]] {
        apiChapterGroups(files).enumerated().map { chapterIndex, group in
            let imageCount = group.indexes.filter { Self.imageExtensions.contains(files[$0].url.pathExtension.lowercased()) }.count
            let start = group.indexes.first ?? 0
            let end = group.indexes.last ?? 0
            let title = Self.queryComponent(group.title)
            var object: [String: Any] = [
                "index": chapterIndex,
                "title": group.title,
                "path": group.path,
                "startIndex": start,
                "endIndex": end,
                "count": group.indexes.count,
                "imageCount": imageCount,
                "fileIndexes": group.indexes,
                "view": "/view?uid=\(uid)&start=\(start)&end=\(end)\(auth)&title=\(title)",
                "chapterView": "/view?uid=\(uid)&start_chapter=\(chapterIndex)&end_chapter=\(chapterIndex)\(auth)&title=\(title)"
            ]
            if imageCount > 0 {
                object["reader"] = "/view?uid=\(uid)&mode=book&page=0&start=\(start)&end=\(end)\(auth)&title=\(title)"
                object["chapterReader"] = "/view?uid=\(uid)&mode=book&page=0&start_chapter=\(chapterIndex)&end_chapter=\(chapterIndex)\(auth)&title=\(title)"
            }
            return object
        }
    }

