    private func apiLogPage(_ request: LocalHTTPRequest) -> String {
        let password = request.query["pw"] ?? request.query["password"] ?? ""
        let standaloneAuth = apiAuthStandaloneQuery(password)
        let logText = Self.htmlEscape(activityLogText())
        let checked = (request.query["auto"] ?? request.query["refresh"] ?? "1") == "0" ? "" : " checked"
        let emptyText = activityLog.isEmpty ? #"<p class="empty">No log entries</p>"# : ""
        let passwordField = password.isEmpty ? "" : #"<input type="hidden" name="pw" value="\#(Self.htmlEscape(password))">"#

        return """
        <!doctype html>
        <html>
        <head>
          <meta charset="utf-8">
          <meta name="viewport" content="width=device-width, initial-scale=1">
          <title>Hitomi Badayo Log</title>
          <style>
            body { font: 14px \(Self.apiFontStack); margin: 0; background: #f7f7f5; color: #202124; }
            main { max-width: 1040px; margin: 0 auto; padding: 24px; }
            header { display: flex; gap: 12px; align-items: center; margin-bottom: 14px; }
            h1 { font-size: 24px; margin: 0; }
            .spacer { flex: 1; }
            label { color: #5f6368; display: inline-flex; gap: 6px; align-items: center; }
            button, a.action { font: inherit; border-radius: 6px; border: 1px solid #c8c8c8; padding: 7px 10px; background: white; color: #202124; text-decoration: none; cursor: pointer; }
            textarea { width: 100%; min-height: 62vh; box-sizing: border-box; resize: vertical; border: 1px solid #d7d9dc; border-radius: 6px; padding: 12px; background: white; color: #202124; font: 12px ui-monospace, SFMono-Regular, Menlo, monospace; line-height: 1.45; }
            .empty { color: #6b6f76; }
            nav { margin-top: 12px; display: flex; gap: 12px; }
            nav a { color: #1a73e8; text-decoration: none; }
          </style>
        </head>
        <body>
          <main>
            <header>
              <h1>Log</h1>
              <div class="spacer"></div>
              <label><input id="autoRefresh" type="checkbox"\(checked)> Auto Refresh &amp;&amp; Scroll</label>
              <form action="/log/clear\(standaloneAuth)" method="post">
                \(passwordField)
                <button type="submit">Clear</button>
              </form>
            </header>
            \(emptyText)
            <textarea id="logText" readonly>\(logText)</textarea>
            <nav>
              <a href="/webui\(standaloneAuth)">WebUI</a>
              <a href="/docs\(standaloneAuth)">Docs</a>
              <a href="/api/log\(standaloneAuth)">JSON</a>
            </nav>
          </main>
          <script>
            const logText = document.getElementById('logText');
            const autoRefresh = document.getElementById('autoRefresh');
            function scrollLog() {
              if (autoRefresh.checked) {
                logText.scrollTop = logText.scrollHeight;
              }
            }
            scrollLog();
            setInterval(function() {
              if (!autoRefresh.checked) return;
              const url = new URL(window.location.href);
              url.searchParams.set('auto', '1');
              window.location.replace(url);
            }, 2000);
          </script>
        </body>
        </html>
        """
    }

    private func apiLogClearResponse(_ request: LocalHTTPRequest) -> LocalHTTPResponse {
        clearActivityLog()
        if request.path.lowercased().hasPrefix("/api/") {
            return LocalHTTPResponse.jsonObject([
                "cleared": true,
                "count": activityLog.count
            ])
        }

        let password = apiParameters(from: request)["pw"] ?? apiParameters(from: request)["password"] ?? ""
        return LocalHTTPResponse(
            status: 302,
            contentType: "text/plain; charset=utf-8",
            body: Data("Redirecting".utf8),
            headers: ["Location": "/log\(apiAuthStandaloneQuery(password))"]
        )
    }

