    private func apiFinderPage(_ request: LocalHTTPRequest) -> String {
        let password = request.query["pw"] ?? request.query["password"] ?? ""
        let standaloneAuth = apiAuthStandaloneQuery(password)
        let field = apiFinderField(from: request)
        let mode = apiFinderMode(from: request)
        let query = request.query["q"] ?? request.query["query"] ?? request.query["search"] ?? ""
        let results = metadataFinderResults(field: field, query: query, mode: mode)
        let passwordField = password.isEmpty ? "" : #"<input type="hidden" name="pw" value="\#(Self.htmlEscape(password))">"#
        let fieldOptions = MetadataFinderField.allCases.map { option in
            let selected = option == field ? " selected" : ""
            return #"<option value="\#(option.rawValue)"\#(selected)>\#(Self.htmlEscape(option.label)) / \#(Self.htmlEscape(option.originalLabel))</option>"#
        }.joined(separator: "\n")
        let modeOptions = MetadataFinderMode.allCases.map { option in
            let selected = option == mode ? " selected" : ""
            return #"<option value="\#(option.rawValue)"\#(selected)>\#(Self.htmlEscape(option.label))</option>"#
        }.joined(separator: "\n")
        let rows = results.map { result in
            let score = result.score.map { "\($0)" } ?? ""
            return """
            <tr>
              <td>\(Self.htmlEscape(result.value))</td>
              <td>\(result.totalCount)</td>
              <td>\(result.queueCount)</td>
              <td>\(result.historyCount)</td>
              <td>\(Self.htmlEscape(score))</td>
              <td>\(Self.htmlEscape(result.sampleTitle))</td>
              <td><code>\(Self.htmlEscape(Self.metadataFinderSearchToken(result)))</code></td>
            </tr>
            """
        }.joined(separator: "\n")
        let empty = results.isEmpty ? #"<tr><td colspan="7" class="empty">No matches</td></tr>"# : ""

        return """
        <!doctype html>
        <html>
        <head>
          <meta charset="utf-8">
          <meta name="viewport" content="width=device-width, initial-scale=1">
          <title>Hitomi Badayo Finder</title>
          <style>
            body { font: 14px \(Self.apiFontStack); margin: 0; background: #f7f7f5; color: #202124; }
            main { max-width: 1080px; margin: 0 auto; padding: 24px; }
            h1 { font-size: 24px; margin: 0 0 14px; }
            form { display: flex; flex-wrap: wrap; gap: 8px; align-items: center; margin-bottom: 14px; }
            input, select, button { font: inherit; border-radius: 6px; border: 1px solid #c8c8c8; padding: 8px 10px; background: white; }
            button { background: #202124; color: white; cursor: pointer; }
            table { width: 100%; border-collapse: collapse; background: white; border: 1px solid #ddd; }
            th, td { padding: 9px 10px; border-bottom: 1px solid #eee; text-align: left; vertical-align: top; }
            th { background: #fafafa; color: #5f6368; font-weight: 600; }
            code { font-family: ui-monospace, SFMono-Regular, Menlo, monospace; }
            .empty { color: #6b6f76; text-align: center; }
            nav { margin-top: 12px; display: flex; gap: 12px; }
            nav a { color: #1a73e8; text-decoration: none; }
          </style>
        </head>
        <body>
          <main>
            <h1>Finder</h1>
            <form action="/finder" method="get">
              \(passwordField)
              <select name="field">\(fieldOptions)</select>
              <input name="q" value="\(Self.htmlEscape(query))" placeholder="Search \(Self.htmlEscape(field.label.lowercased()))">
              <select name="mode">\(modeOptions)</select>
              <button type="submit">Search</button>
            </form>
            <table>
              <thead><tr><th>Value</th><th>Total</th><th>Queue</th><th>History</th><th>Score</th><th>Sample</th><th>Token</th></tr></thead>
              <tbody>
                \(rows)
                \(empty)
              </tbody>
            </table>
            <nav>
              <a href="/webui\(standaloneAuth)">WebUI</a>
              <a href="/docs\(standaloneAuth)">Docs</a>
              <a href="/api/finder?field=\(field.rawValue)&amp;q=\(Self.queryComponent(query))&amp;mode=\(mode.rawValue)\(standaloneAuth.isEmpty ? "" : "&amp;" + String(standaloneAuth.dropFirst()))">JSON</a>
            </nav>
          </main>
        </body>
        </html>
        """
    }

