    private func apiBrowserPage(_ request: LocalHTTPRequest) -> String {
        let password = request.query["pw"] ?? request.query["password"] ?? ""
        let standaloneAuth = apiAuthStandaloneQuery(password)
        let selection = apiBrowserURLSelection(from: request)
        let urlString = selection.url?.absoluteString ?? ""
        let passwordField = password.isEmpty ? "" : #"<input type="hidden" name="pw" value="\#(Self.htmlEscape(password))">"#
        let resultHTML: String
        if let url = selection.url {
            let safeURL = Self.htmlEscape(url.absoluteString)
            resultHTML = """
            <section class="result">
              <div class="label">Login Browser URL</div>
              <a class="url" href="\(safeURL)">\(safeURL)</a>
              <div class="muted">Source: \(Self.htmlEscape(selection.source)) · Cookies: \(Self.htmlEscape(cookieSummary))</div>
            </section>
            """
        } else {
            resultHTML = #"<section class="result error">No browser URL</section>"#
        }

        return """
        <!doctype html>
        <html>
        <head>
          <meta charset="utf-8">
          <meta name="viewport" content="width=device-width, initial-scale=1">
          <title>Hitomi Badayo Browser</title>
          <style>
            body { margin: 0; background: #f5f5f3; color: #202124; font: 13px \(Self.apiFontStack); }
