              <button type="submit">Open Login Browser</button>
            </form>
            \(resultHTML)
          </main>
        </body>
        </html>
        """
    }

    private func apiClipboardPage(_ request: LocalHTTPRequest) -> String {
        let password = request.query["pw"] ?? request.query["password"] ?? ""
        let standaloneAuth = apiAuthStandaloneQuery(password)
        let input = apiClipboardInput(from: request)
        let urls = apiClipboardCandidateURLs(from: input.text)
        let passwordField = password.isEmpty ? "" : #"<input type="hidden" name="pw" value="\#(Self.htmlEscape(password))">"#
        let watchTitle = clipboardMonitorEnabled ? "Watch On" : "Watch Off"
        let watchValue = clipboardMonitorEnabled ? "0" : "1"
        let watchButton = clipboardMonitorEnabled ? "Turn Watch Off" : "Turn Watch On"
        let rowsHTML = urls.enumerated().map { index, url in
            let safeURL = Self.htmlEscape(url)
            let type = apiInputClassification(for: url, url: URL(string: url))
            let typeText = Self.htmlEscape(type.type)
            let resolverText = Self.htmlEscape(type.resolver)
            return """
            <tr>
              <td>\(index + 1)</td>
              <td><a class="url" href="\(safeURL)">\(safeURL)</a></td>
              <td>\(typeText)</td>
              <td>\(resolverText)</td>
            </tr>
            """
        }.joined(separator: "\n")
        let emptyHTML = urls.isEmpty ? #"<tr><td colspan="4" class="empty">No clipboard URLs</td></tr>"# : ""
        let textarea = Self.htmlEscape(input.text)

        return """
        <!doctype html>
        <html>
        <head>
          <meta charset="utf-8">
          <meta name="viewport" content="width=device-width, initial-scale=1">
          <title>Hitomi Badayo Clipboard</title>
          <style>
            body { margin: 0; background: #f5f5f3; color: #202124; font: 13px \(Self.apiFontStack); }
            header { display: flex; gap: 10px; align-items: center; padding: 12px 14px; background: white; border-bottom: 1px solid #ddd; position: sticky; top: 0; }
            h1 { font-size: 16px; margin: 0; }
            a { color: #1a73e8; text-decoration: none; }
            main { padding: 14px; max-width: 980px; }
            textarea, button { font: inherit; border: 1px solid #c8ccd1; border-radius: 4px; }
            textarea { width: 100%; min-height: 140px; box-sizing: border-box; padding: 9px; resize: vertical; background: white; }
            button { min-height: 30px; padding: 0 11px; background: #202124; color: white; cursor: pointer; }
            button.secondary { background: white; color: #202124; }
            table { width: 100%; border-collapse: collapse; background: white; border: 1px solid #ddd; margin-top: 12px; }
            th, td { padding: 9px 10px; border-bottom: 1px solid #eee; text-align: left; vertical-align: top; }
            th { background: #fafafa; color: #5f6368; }
            .bar { display: flex; flex-wrap: wrap; gap: 8px; align-items: center; margin: 10px 0 14px; }
            .meta { margin-left: auto; color: #5f6368; }
            .url { overflow-wrap: anywhere; }
            .empty { text-align: center; color: #5f6368; padding: 20px; }
            @media (max-width: 640px) {
              header { flex-wrap: wrap; }
              .meta { margin-left: 0; width: 100%; }
            }
          </style>
        </head>
        <body>
          <header>
            <h1>Clipboard</h1>
            <a href="/webui\(standaloneAuth)">WebUI</a>
            <a href="/list\(standaloneAuth)">List</a>
            <a href="/search\(standaloneAuth)">Search</a>
            <a href="/history\(standaloneAuth)">History</a>
            <a href="/docs\(standaloneAuth)">Docs</a>
            <span class="meta">\(urls.count) URL\(urls.count == 1 ? "" : "s") · \(watchTitle)</span>
          </header>
          <main>
            <form class="clipboard-panel" action="/clipboard/enqueue\(standaloneAuth)" method="post">
              \(passwordField)
              <textarea name="text">\(textarea)</textarea>
              <div class="bar">
                <label><input type="checkbox" name="start" value="1"> Start now</label>
                <button type="submit">Queue Clipboard</button>
              </div>
            </form>
            <form action="/clipboard/watch\(standaloneAuth)" method="post">
              \(passwordField)
              <input type="hidden" name="enabled" value="\(watchValue)">
              <button class="secondary" type="submit">\(watchButton)</button>
            </form>
            <table class="candidate-list">
              <thead><tr><th>#</th><th>URL</th><th>Type</th><th>Resolver</th></tr></thead>
              <tbody>
                \(rowsHTML)
                \(emptyHTML)
              </tbody>
            </table>
          </main>
        </body>
        </html>
        """
    }

    private func apiSearchPage(_ request: LocalHTTPRequest) -> String {
        let password = request.query["pw"] ?? request.query["password"] ?? ""
        let standaloneAuth = apiAuthStandaloneQuery(password)
        let build = apiSearchBuild(from: request)
        let selectedID = build.provider?.id ?? currentSearchProvider()?.id
        let queryValue = Self.htmlEscape(build.query)
        let passwordField = password.isEmpty ? "" : #"<input type="hidden" name="pw" value="\#(Self.htmlEscape(password))">"#
        let providerOptions = searchProviders.map { provider in
            let selected = provider.id == selectedID ? " selected" : ""
            return #"<option value="\#(Self.htmlEscape(provider.name))"\#(selected)>\#(Self.htmlEscape(provider.name))</option>"#
        }.joined(separator: "\n")

        let resultHTML: String
        if build.providerMissing {
            resultHTML = #"<section class="result error">Search provider not found: \#(Self.htmlEscape(build.providerKey))</section>"#
        } else if let url = build.url, let provider = build.provider {
            let urlString = Self.htmlEscape(url.absoluteString)
            resultHTML = """
            <section class="result">
              <div class="label">Generated URL</div>
              <a class="url" href="\(urlString)">\(urlString)</a>
              <form action="/search/enqueue\(standaloneAuth)" method="post">
                <input type="hidden" name="provider" value="\(Self.htmlEscape(provider.name))">
                <input type="hidden" name="q" value="\(queryValue)">
                <input type="hidden" name="start" value="0">
                <button type="submit">Queue Search</button>
              </form>
            </section>
            """
        } else if build.query.isEmpty {
            resultHTML = #"<section class="result muted">No search query</section>"#
        } else {
            resultHTML = #"<section class="result error">Search URL could not be built</section>"#
        }

        let bookmarkRows = searchBookmarks.map { bookmark in
            let provider = Self.searchProvider(for: bookmark, in: searchProviders)
            let providerName = provider?.name ?? bookmark.providerName
            let url = provider.flatMap { Self.searchURL(provider: $0, query: bookmark.query) }
            let title = Self.htmlEscape(bookmark.title.isEmpty ? Self.searchBookmarkTitle(providerName: providerName, query: bookmark.query) : bookmark.title)
            let query = Self.htmlEscape(bookmark.query)
            let providerText = Self.htmlEscape(providerName)
            let link = url.map { #"<a class="url" href="\#(Self.htmlEscape($0.absoluteString))">\#(Self.htmlEscape($0.absoluteString))</a>"# } ?? #"<span class="muted">Unavailable</span>"#
            return """
            <tr>
              <td><strong>\(title)</strong><div class="muted">\(providerText) · \(query)</div></td>
              <td>\(link)</td>
              <td>
                <form action="/search/enqueue\(standaloneAuth)" method="post">
                  <input type="hidden" name="provider" value="\(providerText)">
                  <input type="hidden" name="q" value="\(query)">
                  <input type="hidden" name="start" value="0">
                  <button type="submit">Queue</button>
                </form>
              </td>
            </tr>
            """
        }.joined(separator: "\n")
        let emptyBookmarks = searchBookmarks.isEmpty ? #"<tr><td colspan="3" class="empty">No saved searches</td></tr>"# : ""
        let providerRows = searchProviders.map { provider in
            """
            <tr>
              <td>\(Self.htmlEscape(provider.name))</td>
              <td><code>\(Self.htmlEscape(provider.urlTemplate))</code></td>
            </tr>
            """
        }.joined(separator: "\n")
        let emptyProviders = searchProviders.isEmpty ? #"<tr><td colspan="2" class="empty">No search providers</td></tr>"# : ""

        return """
        <!doctype html>
        <html>
        <head>
          <meta charset="utf-8">
          <meta name="viewport" content="width=device-width, initial-scale=1">
          <title>Hitomi Badayo Search</title>
          <style>
            body { margin: 0; background: #f5f5f3; color: #202124; font: 13px \(Self.apiFontStack); }
            header { display: flex; gap: 10px; align-items: center; padding: 12px 14px; background: white; border-bottom: 1px solid #ddd; position: sticky; top: 0; }
            h1 { font-size: 16px; margin: 0; }
            h2 { font-size: 14px; margin: 22px 0 8px; }
            a { color: #1a73e8; text-decoration: none; }
            main { padding: 14px; max-width: 980px; }
            input, select, button { font: inherit; min-height: 30px; border: 1px solid #c8ccd1; border-radius: 4px; background: white; }
            input, select { padding: 0 9px; }
            button { padding: 0 11px; background: #202124; color: white; cursor: pointer; }
            code { font-family: ui-monospace, SFMono-Regular, Menlo, monospace; overflow-wrap: anywhere; }
            table { width: 100%; border-collapse: collapse; background: white; border: 1px solid #ddd; }
            th, td { padding: 9px 10px; border-bottom: 1px solid #eee; text-align: left; vertical-align: top; }
            th { background: #fafafa; color: #5f6368; }
            .search-panel { display: grid; grid-template-columns: minmax(130px, 190px) minmax(180px, 1fr) auto; gap: 8px; align-items: center; }
            .result { margin-top: 12px; padding: 12px; background: white; border: 1px solid #ddd; border-radius: 6px; display: grid; gap: 8px; }
            .label, .muted { color: #5f6368; }
            .error { color: #b3261e; }
            .url { overflow-wrap: anywhere; }
            .empty { text-align: center; color: #5f6368; padding: 20px; }
            @media (max-width: 640px) {
              header { flex-wrap: wrap; }
              .search-panel { grid-template-columns: 1fr; }
            }
          </style>
        </head>
        <body>
          <header>
            <h1>Search</h1>
            <a href="/webui\(standaloneAuth)">WebUI</a>
            <a href="/list\(standaloneAuth)">List</a>
            <a href="/history\(standaloneAuth)">History</a>
            <a href="/docs\(standaloneAuth)">Docs</a>
          </header>
          <main>
            <form class="search-panel" action="/search" method="get">
              \(passwordField)
              <select name="provider">\(providerOptions)</select>
              <input type="search" name="q" value="\(queryValue)" autofocus>
              <button type="submit">Search</button>
            </form>
            \(resultHTML)
            <h2>Saved Searches</h2>
            <table class="bookmark-list">
              <thead><tr><th>Search</th><th>URL</th><th>Action</th></tr></thead>
              <tbody>
                \(bookmarkRows)
                \(emptyBookmarks)
              </tbody>
            </table>
            <h2>Providers</h2>
            <table class="provider-list">
              <thead><tr><th>Name</th><th>Template</th></tr></thead>
              <tbody>
                \(providerRows)
                \(emptyProviders)
              </tbody>
            </table>
          </main>
        </body>
        </html>
        """
    }

    private func apiHistoryPage(_ request: LocalHTTPRequest) -> String {
        let password = request.query["pw"] ?? request.query["password"] ?? ""
        let auth = apiAuthQuery(password)
        let standaloneAuth = apiAuthStandaloneQuery(password)
        let pairs = apiFilteredHistoryPairs(from: request)
        let rangeInfo = apiRange(from: request, total: pairs.count)
        let visible = Array(pairs[rangeInfo.range])
        let query = apiHistoryQuery(from: request)
        let querySuffix = query.isEmpty ? "" : "&q=\(Self.queryComponent(query))"
        let rowsHTML = visible.map { index, entry in
            let title = Self.htmlEscape(entry.title.isEmpty ? entry.source : entry.title)
            let source = Self.htmlEscape(entry.source)
            let output = Self.htmlEscape(entry.outputPath)
            let completed = Self.htmlEscape(Self.apiDateString(entry.completedAt))
            let site = Self.htmlEscape(entry.metadata["site"] ?? entry.metadata["host"] ?? "")
            let enqueue = "/download?url=\(Self.queryComponent(entry.source))&start=0\(auth)"
            let metadataHTML = site.isEmpty ? "" : #"<span class="badge">\#(site)</span>"#
            let id = entry.id.uuidString
            return """
            <tr>
              <td>\(index + 1)</td>
              <td><strong>\(title)</strong><div class="muted">\(source)</div><div class="badges">\(metadataHTML)</div></td>
              <td>\(completed)</td>
              <td class="muted">\(output)</td>
              <td>
                <a class="action" href="\(enqueue)">Queue Again</a>
                <form class="inline" action="/history/requeue\(standaloneAuth)" method="post"><input type="hidden" name="id" value="\(id)"><button type="submit">Requeue</button></form>
                <form class="inline" action="/history/remove\(standaloneAuth)" method="post"><input type="hidden" name="id" value="\(id)"><button type="submit">Remove</button></form>
              </td>
            </tr>
            """
        }.joined(separator: "\n")
        let emptyHTML = visible.isEmpty ? #"<tr><td colspan="5" class="empty">No history entries</td></tr>"# : ""
        let step = max(1, min(500, Int(request.query["step"] ?? "") ?? 50))
        let page = max(0, Int(request.query["p"] ?? request.query["page"] ?? "") ?? 0)
        let pageCount = max(1, Int(ceil(Double(max(1, rangeInfo.total)) / Double(step))))
        let previousPage = max(0, page - 1)
        let nextPage = min(pageCount - 1, page + 1)
        let pagingHTML = request.query["p"] != nil || request.query["page"] != nil || request.query["step"] != nil
            ? #"<nav><a class="action" id="prev" href="/history?p=\#(previousPage)&step=\#(step)\#(auth)\#(querySuffix)">Previous</a><span>\#(page + 1) / \#(pageCount)</span><a class="action" id="next" href="/history?p=\#(nextPage)&step=\#(step)\#(auth)\#(querySuffix)">Next</a></nav>"#
            : ""
        return """
        <!doctype html>
        <html>
        <head>
          <meta charset="utf-8">
          <meta name="viewport" content="width=device-width, initial-scale=1">
          <title>Hitomi Badayo History</title>
          <style>
            body { margin: 0; background: #f5f5f3; color: #202124; font: 13px \(Self.apiFontStack); }
            header { display: flex; gap: 10px; align-items: center; padding: 12px 14px; background: white; border-bottom: 1px solid #ddd; position: sticky; top: 0; }
            h1 { font-size: 16px; margin: 0; }
            a { color: #1a73e8; text-decoration: none; }
            button { font: inherit; min-height: 24px; padding: 0 8px; border: 1px solid #d5d8dc; border-radius: 4px; background: #fafafa; color: #1a73e8; cursor: pointer; }
            main { padding: 12px; }
            table { width: 100%; border-collapse: collapse; background: white; border: 1px solid #ddd; }
            th, td { padding: 9px 10px; border-bottom: 1px solid #eee; text-align: left; vertical-align: top; }
            th { background: #fafafa; color: #5f6368; }
            .muted { color: #5f6368; overflow-wrap: anywhere; }
            .summary { margin-left: auto; color: #5f6368; }
            .action { display: inline-flex; align-items: center; min-height: 24px; padding: 0 8px; border: 1px solid #d5d8dc; border-radius: 4px; background: #fafafa; }
            .inline { display: inline; margin-left: 6px; }
            .badges { display: flex; flex-wrap: wrap; gap: 6px; margin-top: 5px; }
            .badge { display: inline-flex; align-items: center; min-height: 20px; padding: 0 7px; border-radius: 999px; background: #eef2ff; color: #3150a3; font-size: 11px; }
            .empty { text-align: center; color: #5f6368; padding: 24px; }
            nav { display: flex; justify-content: center; align-items: center; gap: 14px; padding: 14px 0 4px; }
          </style>
        </head>
        <body>
          <header>
            <h1>History</h1>
            <a href="/webui\(standaloneAuth)">WebUI</a>
            <a href="/list\(standaloneAuth)">List</a>
            <a href="/docs\(standaloneAuth)">Docs</a>
            <form class="inline" action="/history/clear\(standaloneAuth)" method="post"><button type="submit">Clear</button></form>
            <span class="summary">\(rangeInfo.range.count) / \(rangeInfo.total) entries</span>
          </header>
          <main>
            <table class="history-list">
              <thead><tr><th>#</th><th>Task</th><th>Completed</th><th>Output</th><th>Action</th></tr></thead>
              <tbody>
                \(rowsHTML)
                \(emptyHTML)
              </tbody>
            </table>
            \(pagingHTML)
          </main>
        </body>
        </html>
        """
    }

    private func apiListPage(_ request: LocalHTTPRequest) -> String {
        let password = request.query["pw"] ?? request.query["password"] ?? ""
        let auth = apiAuthQuery(password)
        let standaloneAuth = apiAuthStandaloneQuery(password)
        let step = max(1, min(500, Int(request.query["step"] ?? "") ?? 50))
        let requestedPage = max(0, Int(request.query["p"] ?? "") ?? 0)
        let useRange = request.query["start"] != nil || request.query["end"] != nil
        let usePaging = request.query["p"] != nil || request.query["step"] != nil
        let singleMode = Self.apiTruthy(request.query["single"])
        let orderedJobs = visibleQueueOrderedJobs
        let total = orderedJobs.count
        let rangeStart = max(0, Int(request.query["start"] ?? "") ?? 0)
        let rangeEndInclusive = min(max(0, Int(request.query["end"] ?? "") ?? (total - 1)), max(0, total - 1))
        let start = useRange ? min(rangeStart, total) : (usePaging ? min(requestedPage * step, total) : 0)
        let end = useRange ? (start <= rangeEndInclusive ? min(rangeEndInclusive + 1, total) : start) : (usePaging ? min(start + step, total) : total)
        let visible = Array(orderedJobs.enumerated())[start..<end]
        let viewMode = singleMode ? "&mode=book&page=0" : ""

        let itemsHTML = visible.map { index, job in
            let uid = job.id.uuidString
            let statusClass = job.status.rawValue.lowercased()
            let progress = Int(max(0, min(100, job.progress * 100)).rounded())
            let title = Self.htmlEscape(job.title.isEmpty ? job.source : job.title)
            let source = Self.htmlEscape(job.source)
            let message = Self.htmlEscape(job.message)
            let comment = Self.htmlEscape(job.comment)
            let commentHTML = comment.isEmpty ? "" : #"<div class="comment">\#(comment)</div>"#
            let output = Self.htmlEscape(job.outputPath)
            let files = apiOutputFiles(for: job)
            let badges = apiListBadgeHTML(for: job, files: files)
            let thumb = "/thumb?uid=\(uid)\(auth)"
            let view = "/view?uid=\(uid)\(auth)\(viewMode)"
            let pdf = "/pdf?uid=\(uid)\(auth)"
            let zip = "/zip?uid=\(uid)\(auth)"
            let pdfHTML = files.contains { Self.imageExtensions.contains($0.url.pathExtension.lowercased()) }
                ? #"<a class="action" href="\#(pdf)">PDF</a>"#
                : ""
            let zipHTML = Self.apiCanArchiveOutputPath(job.outputPath)
                ? #"<a class="action" href="\#(zip)">ZIP</a>"#
                : ""
            return """
            <li class="item \(statusClass)" uid="\(uid)" data-index="\(index)">
              <div class="item-base">
                <a class="thumb" href="\(view)"><img src="\(thumb)" alt=""></a>
                <div class="body">
                  <a class="title" href="\(view)">\(title)</a>
                  <div class="actions"><a class="action" href="\(view)">View</a>\(pdfHTML)\(zipHTML)</div>
                  <div class="source">\(source)</div>
                  <div class="meta"><span>\(Self.htmlEscape(job.status.rawValue))</span><span>\(job.completed)/\(job.total)</span><span>\(progress)%</span></div>
                  \(badges)
                  <div class="progress"><span style="width:\(progress)%"></span></div>
                  <div class="message">\(message)</div>
                  \(commentHTML)
                  <div class="output">\(output)</div>
                </div>
              </div>
            </li>
            """
        }.joined(separator: "\n")

        let pageCount = usePaging ? max(1, Int(ceil(Double(total) / Double(step)))) : 1
        var paging = ""
        if usePaging {
            let lowerPage = max(0, requestedPage - 4)
            let upperPage = min(pageCount - 1, requestedPage + 4)
            let pageLinks = (lowerPage...upperPage).map { page -> String in
                let href = "/list?p=\(page)&step=\(step)\(auth)"
                let idAttribute: String
                if page == requestedPage - 1 {
                    idAttribute = #" id="prev""#
                } else if page == requestedPage + 1 {
                    idAttribute = #" id="next""#
                } else {
                    idAttribute = ""
                }
                let activeClass = page == requestedPage ? " active" : ""
                return #"<a\#(idAttribute) class="paging-item\#(activeClass)" href="\#(href)">\#(page + 1)</a>"#
            }.joined(separator: "")
            let previousFallback = requestedPage == 0 ? #"<span id="prev" class="paging-item disabled">‹</span>"# : ""
            let nextFallback = requestedPage + 1 >= pageCount ? #"<span id="next" class="paging-item disabled">›</span>"# : ""
            paging = #"<nav class="paging">\#(previousFallback)\#(pageLinks)\#(nextFallback)</nav>"#
        }

        let emptyHTML = visible.isEmpty ? #"<li class="empty">No tasks</li>"# : ""
        return """
        <!doctype html>
        <html>
        <head>
          <meta charset="utf-8">
          <meta name="viewport" content="width=device-width, initial-scale=1">
          <title>Hitomi Badayo List</title>
          <style>
            body { margin: 0; background: #f5f5f3; color: #202124; font: 13px \(Self.apiFontStack); }
            header { display: flex; gap: 10px; align-items: center; padding: 12px 14px; background: white; border-bottom: 1px solid #ddd; position: sticky; top: 0; }
            h1 { font-size: 16px; margin: 0; }
            a { color: #1a73e8; text-decoration: none; }
            .summary { margin-left: auto; color: #5f6368; }
            ul { list-style: none; margin: 0; padding: 12px; display: grid; gap: 8px; }
            .item { background: white; border: 1px solid #ddd; border-radius: 6px; overflow: hidden; }
            .item-base { display: grid; grid-template-columns: 96px minmax(0, 1fr); gap: 12px; padding: 10px; cursor: default; }
            .item-base.selected { background: #dfe9ff; }
            .thumb { width: 96px; height: 64px; background: #eef0f2; border-radius: 4px; overflow: hidden; display: block; }
            .thumb img { width: 100%; height: 100%; object-fit: cover; display: block; }
            .title { font-weight: 700; color: #202124; overflow-wrap: anywhere; }
            .actions { display: flex; flex-wrap: wrap; gap: 8px; margin-top: 5px; }
            .action { display: inline-flex; align-items: center; min-height: 22px; padding: 0 8px; border: 1px solid #d5d8dc; border-radius: 4px; background: #fafafa; color: #1a73e8; font-size: 12px; }
            .source, .message, .comment, .output { color: #5f6368; overflow-wrap: anywhere; font-size: 12px; margin-top: 3px; }
            .comment { color: #3f5f9f; white-space: pre-wrap; }
            .meta { display: flex; flex-wrap: wrap; gap: 8px; color: #5f6368; margin-top: 6px; }
            .badges { display: flex; flex-wrap: wrap; gap: 6px; margin-top: 6px; }
            .badge { display: inline-flex; align-items: center; min-height: 20px; padding: 0 7px; border-radius: 999px; background: #eef2ff; color: #3150a3; font-size: 11px; max-width: 100%; overflow-wrap: anywhere; }
            .progress { width: 100%; height: 6px; background: #e8eaed; border-radius: 999px; overflow: hidden; margin-top: 6px; }
            .progress span { display: block; height: 100%; background: #1a73e8; }
            .empty { padding: 24px; text-align: center; color: #5f6368; background: white; border: 1px solid #ddd; border-radius: 6px; }
            .paging { display: flex; justify-content: center; align-items: center; gap: 14px; padding: 12px 0 20px; }
            .paging-item { display: inline-flex; align-items: center; justify-content: center; min-width: 28px; min-height: 28px; padding: 0 8px; border: 1px solid #d5d8dc; border-radius: 4px; background: white; color: #1a73e8; }
            .paging-item.active { background: #202124; color: white; border-color: #202124; }
            .disabled { color: #9aa0a6; }
            .item-base { position: relative; transition: transform .12s ease, background .12s ease; }
            .item-base.right-swiping { box-shadow: 0 8px 18px rgba(0,0,0,.12); }
            .item-base.swipe-delete-ready { background: #ffe6e6; }
            .item-base.swipe-delete-ready::after { content: "Delete"; position: absolute; right: 12px; top: 50%; transform: translateY(-50%); color: #b3261e; font-weight: 700; }
          </style>
        </head>
        <body>
          <header>
            <h1>Hitomi Badayo</h1>
            <a href="/webui\(standaloneAuth)">WebUI</a>
            <a href="/docs\(standaloneAuth)">Docs</a>
            <span class="summary">\(useRange ? "\(visible.count) / \(total) tasks" : "\(total) tasks")</span>
          </header>
          <ul class="listWidget">
            \(itemsHTML)
            \(emptyHTML)
          </ul>
          \(paging)
          <script>
            const deleteURL = \(Self.javascriptStringLiteral("/delete\(standaloneAuth)"));
            document.addEventListener("keydown", function(event) {
              if (event.ctrlKey || event.altKey || event.shiftKey) return;
              if (event.key === "ArrowLeft") document.getElementById("prev")?.click();
              if (event.key === "ArrowRight") document.getElementById("next")?.click();
            });
            var isMouseDown = false;
            var isSelected = false;
            var rightSwipeState = null;
            var rightSwipeThreshold = 90;
            async function deleteSwipedItem(item) {
              var uid = item && item.getAttribute("uid");
              if (!uid) return;
              if (!confirm("Delete output files for this task?")) return;
              var body = new URLSearchParams();
              body.set("uid", uid);
              var response = await fetch(deleteURL, { method: "POST", body: body });
              if (response.ok) {
                location.reload();
              } else {
                alert(await response.text());
              }
            }
            function resetRightSwipe() {
              if (!rightSwipeState) return;
              var itemBase = rightSwipeState.itemBase;
              itemBase.style.transform = "";
              itemBase.classList.remove("right-swiping", "swipe-delete-ready");
              rightSwipeState = null;
            }
            function beginRightSwipe(event, itemBase) {
              rightSwipeState = {
                itemBase: itemBase,
                item: itemBase.closest(".item"),
                startX: event.clientX,
                ready: false
              };
              itemBase.classList.add("right-swiping");
              event.preventDefault();
            }
            document.querySelectorAll(".item-base").forEach(function(itemBase) {
              itemBase.addEventListener("mousedown", function(event) {
                if (event.target.closest("a, button, input, textarea, select")) return;
                if (event.button === 2) {
                  beginRightSwipe(event, itemBase);
                  return;
                }
                if (event.button !== 0) return;
                isMouseDown = true;
                itemBase.classList.toggle("selected");
                isSelected = itemBase.classList.contains("selected");
                if (window.parent && typeof window.parent.updateSelection === "function") {
                  window.parent.updateSelection();
                }
                event.preventDefault();
              });
              itemBase.addEventListener("mouseover", function(event) {
                if (!isMouseDown || event.target.closest("a, button, input, textarea, select")) return;
                itemBase.classList.toggle("selected", isSelected);
                if (window.parent && typeof window.parent.updateSelection === "function") {
                  window.parent.updateSelection();
                }
              });
            });
            document.addEventListener("mousemove", function(event) {
              if (!rightSwipeState) return;
              var delta = Math.min(0, event.clientX - rightSwipeState.startX);
              var clamped = Math.max(delta, -128);
              rightSwipeState.itemBase.style.transform = "translateX(" + clamped + "px)";
              rightSwipeState.ready = delta <= -rightSwipeThreshold;
              rightSwipeState.itemBase.classList.toggle("swipe-delete-ready", rightSwipeState.ready);
              event.preventDefault();
            });
            document.addEventListener("contextmenu", function(event) {
              if (event.target.closest(".item-base")) {
                event.preventDefault();
              }
            });
            document.addEventListener("mouseup", function() {
              isMouseDown = false;
              if (rightSwipeState) {
                var state = rightSwipeState;
                var shouldDelete = state.ready;
                resetRightSwipe();
                if (shouldDelete) {
                  deleteSwipedItem(state.item);
                }
              }
            });
          </script>
        </body>
        </html>
        """
    }

    private func apiListBadgeHTML(for job: DownloadJob, files: [APIOutputFile]) -> String {
        var badges: [String] = []
        var seen = Set<String>()

        func append(_ value: String?) {
            guard let value = value?.trimmed, !value.isEmpty else { return }
            let normalized = value.lowercased()
            guard !seen.contains(normalized) else { return }
            seen.insert(normalized)
            badges.append(value)
        }

        let metadata = job.metadata
        if job.isPinned {
            append("Pinned")
        }
        if job.isLocked {
            append("Locked")
        }
        append(Self.firstMetadataValue(metadata, keys: ["artist", "author", "creator", "uploader", "channel", "username", "user"]))
        append(Self.firstMetadataValue(metadata, keys: ["language", "category", "tag", "tags", "series", "site", "type"]))

        if !files.isEmpty {
            append("\(files.count) file\(files.count == 1 ? "" : "s")")
            if let size = apiOutputByteCount(files: files), size > 0 {
                append(Self.apiByteCountString(size))
            }
            if let date = apiOutputDate(files: files) {
                append(Self.apiListDateString(date))
            }
        } else if let date = Self.firstMetadataValue(metadata, keys: ["date", "upload_date", "published_date", "published", "created_at"]) {
            append(date)
        }

        guard !badges.isEmpty else { return "" }
        let badgeHTML = badges.prefix(8).map { "<span class=\"badge\">\(Self.htmlEscape($0))</span>" }.joined()
        return #"<div class="badges">\#(badgeHTML)</div>"#
    }

    private static func firstMetadataValue(_ metadata: [String: String], keys: [String]) -> String? {
        for key in keys {
            if let value = metadata[key]?.trimmed, !value.isEmpty {
                return value
            }
        }
        return nil
    }

    private func apiOutputByteCount(files: [APIOutputFile]) -> Int64? {
        var total: Int64 = 0
        var found = false
        for file in files {
            let size = apiOutputFileSize(file)
            total += Int64(max(0, size))
            found = true
        }
        return found ? total : nil
    }

    private func apiOutputDate(files: [APIOutputFile]) -> Date? {
        files.compactMap(apiOutputFileModifiedDate).max()
    }

    private static func apiByteCountString(_ bytes: Int64) -> String {
        let formatter = ByteCountFormatter()
        formatter.countStyle = .file
        return formatter.string(fromByteCount: bytes)
    }

    private static func apiListDateString(_ date: Date) -> String {
        let formatter = DateFormatter()
        formatter.locale = Locale(identifier: "en_US_POSIX")
        formatter.dateFormat = "yyyy-MM-dd"
        return formatter.string(from: date)
    }

