              <div class="bar">
                <label><input type="checkbox" id="startNow" checked> Start now</label>
                <button id="downButton" class="primary" type="submit" onclick="downButton(); return false;">Add URLs</button>
              </div>
            </form>
            <div class="selection-actions">
              <button type="button" onclick="clearSelection()">Clear Selection</button>
              <button type="button" onclick="pauseSelected()">Pause</button>
              <button type="button" onclick="resumeSelected()">Resume</button>
              <span id="selectionCount">0 selected</span>
            </div>
            <iframe src="\(Self.htmlEscape(listURL))" class="list-frame" onload="onLoad();" title="List"></iframe>
            <div id="content" class="empty" hidden>Loading...</div>
          </main>
          <script>
            const password = \(password);
            const HOME = \(listURLLiteral);
            function apiURL(path) {
              const url = new URL(path, location.origin);
              if (password) url.searchParams.set('pw', password);
              return url;
            }
            async function api(path, options = {}) {
              const response = await fetch(apiURL(path), options);
              if (!response.ok) throw new Error(await response.text());
              return await response.json();
            }
            function escapeText(value) {
              return String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
            }
            function renderStatus(data) {
              document.getElementById('summary').textContent = `${data.count} tasks · ${data.running ? 'running' : 'idle'}`;
              render(data.items || []);
            }
            function listFrame() {
              return document.querySelector('.list-frame');
            }
            function home() {
              listFrame().src = HOME;
            }
            function onLoad() {
              updateSelection();
            }
            function updateSelection() {
              const count = selected_uids().length;
              document.getElementById('selectionCount').textContent = `${count} selected`;
              document.querySelectorAll('.tools').forEach(tools => {
                tools.style.display = count ? 'flex' : 'none';
              });
            }
            function clearSelection() {
              const frame = listFrame();
              const doc = frame && frame.contentDocument;
              if (!doc) return;
              doc.querySelectorAll('.item-base.selected').forEach(item => item.classList.remove('selected'));
              updateSelection();
            }
            function selected_uids() {
              const frame = listFrame();
              const doc = frame && frame.contentDocument;
              if (!doc) return [];
              return Array.from(doc.querySelectorAll('.item')).filter(item => item.querySelector('.item-base.selected')).map(item => item.getAttribute('uid')).filter(Boolean);
            }
            function refreshFrame() {
              const frame = listFrame();
              if (frame && frame.contentWindow) frame.contentWindow.location.reload();
            }
            async function refresh() {
              try {
                const data = await api('/status');
                renderStatus(data);
                refreshFrame();
              } catch (error) {
                document.getElementById('content').hidden = false;
                document.getElementById('content').className = 'empty';
                document.getElementById('content').textContent = error.message;
              }
            }
            function render(items) {
              const content = document.getElementById('content');
              if (!items.length) {
                content.hidden = false;
                content.className = 'empty';
                content.textContent = 'No tasks';
                return;
              }
              content.hidden = false;
              content.className = '';
              content.innerHTML = `<table><thead><tr><th>Task</th><th>Status</th><th>Progress</th><th>Output</th><th>Actions</th></tr></thead><tbody>${items.map(item => {
                const pct = Math.max(0, Math.min(100, Math.round((item.progress || 0) * 100)));
                const viewURL = apiURL('/view');
                viewURL.searchParams.set('uid', item.id);
                const infoURL = apiURL('/info');
                infoURL.searchParams.set('uid', item.id);
                const viewLink = item.outputPath ? `<div><a href="${escapeText(viewURL.href)}" target="_blank" rel="noopener">View</a></div>` : '';
                const infoLink = `<div><a href="${escapeText(infoURL.href)}" target="_blank" rel="noopener">Info</a></div>`;
                const pdfButton = item.outputPath ? `<button onclick="taskCommand('/pdf','${escapeText(item.id)}')">PDF</button> ` : '';
                const zipButton = item.outputPath ? `<button onclick="taskCommand('/zip','${escapeText(item.id)}')">ZIP</button> ` : '';
                const canFinish = item.status !== 'Finished' && item.status !== 'Resolving' && (item.status !== 'Downloading' || item.runtimePaused);
                const finishButton = canFinish ? `<button onclick="taskCommand('/complete','${escapeText(item.id)}')">Finish</button> ` : '';
                const canPause = item.runtimeHandler === 'aria2' && item.status === 'Downloading' && !item.runtimePaused;
                const canResume = item.runtimeHandler === 'aria2' && item.status === 'Downloading' && item.runtimePaused;
                const canLimit = item.runtimeHandler === 'aria2' && item.status === 'Downloading' && item.runtimeCanLimit;
                const canSelectFiles = item.runtimeHandler === 'aria2' && item.status === 'Downloading' && item.runtimeCanSelectFiles;
                const canSeed = item.runtimeHandler === 'aria2' && item.status === 'Downloading' && item.runtimeCanSeed;
                const canListFiles = !!item.runtimeCanListFiles;
                const canShowPeers = item.runtimeHandler === 'aria2' && item.status === 'Downloading' && item.runtimeCanShowPeers;
                const pauseButton = canPause ? `<button onclick="taskCommand('/pause','${escapeText(item.id)}')">Pause</button> ` : '';
                const resumeButton = canResume ? `<button onclick="taskCommand('/resume','${escapeText(item.id)}')">Resume</button> ` : '';
                const limitButton = canLimit ? `<button onclick="aria2Limits('${escapeText(item.id)}','${escapeText(item.runtimeMaxDownloadLimit || '')}','${escapeText(item.runtimeMaxUploadLimit || '')}')">Limits</button> ` : '';
                const filesButton = canSelectFiles ? `<button onclick="aria2Files('${escapeText(item.id)}','${escapeText(item.runtimeSelectedFiles || '')}')">Files</button> ` : '';
                const seedButton = canSeed ? `<button onclick="aria2Seed('${escapeText(item.id)}','${escapeText(item.runtimeSeedTimeMinutes || '')}','${escapeText(item.runtimeSeedRatio || '')}')">Seed</button> ` : '';
                const fileListButton = canListFiles ? `<button onclick="aria2FileList('${escapeText(item.id)}')">List</button> ` : '';
                const peersButton = canShowPeers ? `<button onclick="aria2Peers('${escapeText(item.id)}')">Peers</button> ` : '';
                return `<tr>
                  <td><strong>${escapeText(item.title || item.source)}</strong><div class="source">${escapeText(item.source)}</div></td>
                  <td class="status">${escapeText(item.status)}<div class="source">${escapeText(item.message)}</div></td>
                  <td><div class="progress"><span style="width:${pct}%"></span></div><div class="source">${pct}% · ${escapeText(item.completed)}/${escapeText(item.total)}</div></td>
                  <td class="output">${viewLink}${infoLink}${escapeText(item.outputPath)}</td>
                  <td>${pauseButton}${resumeButton}${limitButton}${filesButton}${seedButton}${fileListButton}${peersButton}${pdfButton}${zipButton}${finishButton}<button onclick="taskCommand('/remove','${escapeText(item.id)}')">Remove</button> <button class="danger" onclick="taskCommand('/delete','${escapeText(item.id)}', true)">Delete</button></td>
                </tr>`;
              }).join('')}</tbody></table>`;
            }
            async function command(path) {
              await api(path, { method: 'POST' });
              await refresh();
            }
            async function postUIDCommand(path, uids) {
              if (!uids.length) return;
              await api(path, {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({'uids': uids})
              });
              clearSelection();
              await refresh();
            }
            async function remove() {
              await postUIDCommand('/remove', selected_uids());
            }
            async function delete_() {
              await postUIDCommand('/delete', selected_uids());
            }
            async function pauseSelected() {
              await postUIDCommand('/pause', selected_uids());
            }
            async function resumeSelected() {
              await postUIDCommand('/resume', selected_uids());
            }
            async function taskCommand(path, id, confirmDelete = false) {
              if (confirmDelete && !confirm('Delete output files for this task?')) return;
              const body = new URLSearchParams();
              body.set('uid', id);
              await api(path, { method: 'POST', body });
              await refresh();
            }
            async function aria2Limits(id, currentDown, currentUp) {
              const down = prompt('Download limit', currentDown || '');
              if (down === null) return;
              const up = prompt('Upload limit', currentUp || '');
              if (up === null) return;
              const body = new URLSearchParams();
              body.set('uid', id);
              body.set('down', down);
              body.set('up', up);
              await api('/aria2_limits', { method: 'POST', body });
              await refresh();
            }
            async function aria2Files(id, currentFiles) {
              const files = prompt('Torrent files', currentFiles || 'all');
              if (files === null) return;
              const body = new URLSearchParams();
              body.set('uid', id);
              body.set('files', files);
              await api('/aria2_files', { method: 'POST', body });
              await refresh();
            }
            async function aria2Seed(id, currentSeed, currentRatio) {
              const seed = prompt('Seed time minutes', currentSeed || '0');
              if (seed === null) return;
              const ratio = prompt('Seed ratio', currentRatio || '');
              if (ratio === null) return;
              const body = new URLSearchParams();
              body.set('uid', id);
              body.set('seed', seed);
              body.set('ratio', ratio);
              await api('/aria2_seed', { method: 'POST', body });
              await refresh();
            }
            async function aria2FileList(id) {
              const body = new URLSearchParams();
              body.set('uid', id);
              const data = await api('/aria2_file_list', { method: 'POST', body });
              const files = data.files || [];
              const text = files.length ? files.map(file => file.summary || `${file.index}: ${file.path}`).join('\\n') : 'No torrent files';
              alert(text);
              await refresh();
            }
            async function aria2Peers(id) {
              const body = new URLSearchParams();
              body.set('uid', id);
              const data = await api('/aria2_peers', { method: 'POST', body });
              const peers = data.peers || [];
              const text = peers.length ? peers.map(peer => peer.summary || `${peer.ip}:${peer.port}`).join('\\n') : 'No peers';
              alert(text);
              await refresh();
            }
            async function downButton() {
              const input = document.getElementById('input');
              input.focus();
              if (!input.value.trim()) return;
              await api('/download', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({'input': input.value, 'start': document.getElementById('startNow').checked ? '1' : '0'})
              });
              input.value = '';
              await refresh();
            }
            document.getElementById('addForm').addEventListener('submit', async event => {
              event.preventDefault();
              await downButton();
            });
            function connectEvents() {
              if (!window.EventSource) return false;
              const source = new EventSource(apiURL('/events').href);
              source.addEventListener('status', event => {
                try {
                  renderStatus(JSON.parse(event.data));
                } catch {
                  refresh();
                }
              });
              source.onerror = function() {};
              return true;
            }
            refresh();
            if (!connectEvents()) setInterval(refresh, 3000);
          </script>
        </body>
        </html>
        """
    }

    private func apiWebUIListURL(from request: LocalHTTPRequest, passwordQuery: String) -> String {
        var queryItems: [(String, String)] = []
        for key in ["p", "step", "single"] {
            if let value = request.query[key]?.trimmed, !value.isEmpty {
                queryItems.append((key, value))
            }
        }
        if !passwordQuery.isEmpty {
            queryItems.append(("pw", passwordQuery))
        }
        guard !queryItems.isEmpty else { return "/list" }
        let query = queryItems
            .map { "\(Self.queryComponent($0.0))=\(Self.queryComponent($0.1))" }
            .joined(separator: "&")
        return "/list?\(query)"
    }

    private func apiPageSelectorObject(_ request: LocalHTTPRequest) -> [String: Any] {
        guard let jobIndex = apiJobIndex(from: request) else {
            return apiPageSelectorIndexObject(request)
        }
        return apiPageSelectorJobObject(jobIndex: jobIndex, request: request)
    }

    private func apiPageSelectorIndexObject(_ request: LocalHTTPRequest) -> [String: Any] {
        let password = request.query["pw"] ?? request.query["password"] ?? ""
        let auth = apiAuthQuery(password)
        let items = jobs.indices.map { index -> [String: Any] in
            let job = jobs[index]
            let total = apiPageSelectorTotal(for: job)
            let selected = apiPageSelectorSelectedIndexes(range: job.rangeExpression, total: total)
            let uid = job.id.uuidString
            return [
                "index": index,
                "id": uid,
                "source": job.source,
                "title": job.title,
                "status": job.status.rawValue,
                "range": job.rangeExpression,
                "rangeExpression": job.rangeExpression,
                "total": total,
                "selectedCount": selected.count,
                "selectedRange": Self.compactRangeDescription(fromZeroBasedIndexes: selected),
                "selector": "/page_selector?uid=\(uid)\(auth)",
                "api": "/api/page_selector?uid=\(uid)\(auth)"
            ]
        }
        return [
            "ok": true,
            "count": items.count,
            "items": items
        ]
    }

    private func apiPageSelectorJobObject(jobIndex: Int, request: LocalHTTPRequest, updated: Bool = false) -> [String: Any] {
        let password = request.query["pw"] ?? request.query["password"] ?? ""
        let auth = apiAuthQuery(password)
        let job = jobs[jobIndex]
        let uid = job.id.uuidString
        let candidates = apiPageSelectorCandidates(for: job)
        let total = apiPageSelectorTotal(for: job, candidateCount: candidates.count)
        let selectedIndexes = apiPageSelectorSelectedIndexes(range: job.rangeExpression, total: total)
        let selectedSet = Set(selectedIndexes)
        let maxItems = apiPageSelectorItemLimit(from: request)
        let visibleCandidates = Array(candidates.prefix(maxItems))
        let items = visibleCandidates.map { candidate -> [String: Any] in
            var object: [String: Any] = [
                "index": candidate.index,
                "page": candidate.index + 1,
                "title": candidate.title,
                "detail": candidate.detail,
                "type": candidate.type,
                "selected": selectedSet.contains(candidate.index)
            ]
            if let file = candidate.file {
                object["relativePath"] = file.relativePath
                object["filename"] = Self.apiOutputDisplayName(file)
                object["path"] = Self.apiOutputDisplayPath(file)
                object["size"] = apiOutputFileSize(file)
                object["mimeType"] = Self.mimeType(for: file.url)
                object["file"] = "/file?uid=\(uid)&index=\(file.originalIndex)\(auth)"
                object["view"] = "/view?uid=\(uid)&index=\(file.originalIndex)\(auth)"
                if Self.imageExtensions.contains(file.url.pathExtension.lowercased()) || Self.videoExtensions.contains(file.url.pathExtension.lowercased()) {
                    object["thumb"] = "/thumb?uid=\(uid)&index=\(file.originalIndex)\(auth)"
                }
            }
            return object
        }

        return [
            "ok": true,
            "updated": updated,
            "index": jobIndex,
            "id": uid,
            "source": job.source,
            "title": job.title,
            "status": job.status.rawValue,
            "message": job.message,
            "comment": job.comment,
            "range": job.rangeExpression,
            "rangeExpression": job.rangeExpression,
            "total": total,
            "itemCount": items.count,
            "truncated": candidates.count > items.count,
            "selectedIndexes": selectedIndexes,
            "selectedPages": selectedIndexes.map { $0 + 1 },
            "selectedCount": selectedIndexes.count,
            "selectedRange": Self.compactRangeDescription(fromZeroBasedIndexes: selectedIndexes),
            "items": items,
            "selector": "/page_selector?uid=\(uid)\(auth)",
            "api": "/api/page_selector?uid=\(uid)\(auth)",
            "info": "/info?uid=\(uid)\(auth)",
            "view": "/view?uid=\(uid)\(auth)"
        ]
    }

    private func apiPageSelectorPage(_ request: LocalHTTPRequest) -> String {
        let password = request.query["pw"] ?? request.query["password"] ?? ""
        let standaloneAuth = apiAuthStandaloneQuery(password)
        let auth = apiAuthQuery(password)
        guard let jobIndex = apiJobIndex(from: request) else {
            return apiPageSelectorIndexPage(request: request, auth: auth, standaloneAuth: standaloneAuth)
        }
        return apiPageSelectorJobPage(jobIndex: jobIndex, request: request, auth: auth, standaloneAuth: standaloneAuth)
    }

    private func apiPageSelectorIndexPage(request: LocalHTTPRequest, auth: String, standaloneAuth: String) -> String {
        let rows = jobs.indices.map { index -> String in
            let job = jobs[index]
            let uid = job.id.uuidString
            let total = apiPageSelectorTotal(for: job)
            let selected = apiPageSelectorSelectedIndexes(range: job.rangeExpression, total: total)
            let title = Self.htmlEscape(job.title.isEmpty ? job.source : job.title)
            let source = Self.htmlEscape(job.source)
            let range = job.rangeExpression.trimmed.isEmpty ? "All" : job.rangeExpression
            let href = "/page_selector?uid=\(uid)\(auth)"
            return """
            <tr>
              <td><a href="\(Self.htmlEscape(href))"><strong>\(title)</strong></a><div class="source">\(source)</div></td>
              <td>\(Self.htmlEscape(job.status.rawValue))</td>
              <td>\(Self.htmlEscape(range))</td>
              <td>\(selected.count) / \(total)</td>
            </tr>
            """
        }.joined(separator: "\n")
        let table = rows.isEmpty
            ? #"<div class="empty">No tasks</div>"#
            : """
              <table class="page-selector-index">
                <thead><tr><th>Task</th><th>Status</th><th>Range</th><th>Selected</th></tr></thead>
                <tbody>\(rows)</tbody>
              </table>
              """

        return """
        <!doctype html>
        <html>
        <head>
          <meta charset="utf-8">
          <meta name="viewport" content="width=device-width, initial-scale=1">
          <title>Page Selector - Hitomi Badayo</title>
          <style>
            body { font: 14px \(Self.apiFontStack); margin: 0; background: #f7f7f5; color: #202124; }
            header { position: sticky; top: 0; z-index: 2; padding: 12px 14px; background: rgba(255,255,255,.94); border-bottom: 1px solid #ddd; backdrop-filter: blur(10px); }
            h1 { font-size: 18px; margin: 0 0 8px; }
            nav { display: flex; flex-wrap: wrap; gap: 10px; }
            main { max-width: 980px; margin: 0 auto; padding: 18px; }
            table { width: 100%; border-collapse: collapse; background: white; border: 1px solid #ddd; }
            th, td { padding: 10px 12px; border-bottom: 1px solid #eee; text-align: left; vertical-align: top; }
            th { color: #5f6368; background: #fafafa; }
            .source { color: #5f6368; overflow-wrap: anywhere; }
            .empty { padding: 24px; background: white; border: 1px solid #ddd; color: #6b6f76; text-align: center; }
            a { color: #1a73e8; text-decoration: none; }
          </style>
        </head>
        <body>
          <header>
            <h1>Page Selector</h1>
            <nav><a href="/webui\(standaloneAuth)">Queue</a><a href="/list\(standaloneAuth)">List</a><a href="/docs\(standaloneAuth)">Docs</a><a href="/api/page_selector\(standaloneAuth)">JSON</a></nav>
          </header>
          <main>
            \(table)
          </main>
        </body>
        </html>
        """
    }

    private func apiPageSelectorJobPage(jobIndex: Int, request: LocalHTTPRequest, auth: String, standaloneAuth: String) -> String {
        let password = request.query["pw"] ?? request.query["password"] ?? ""
        let job = jobs[jobIndex]
        let uid = job.id.uuidString
        let candidates = apiPageSelectorCandidates(for: job)
        let total = apiPageSelectorTotal(for: job, candidateCount: candidates.count)
        let selectedIndexes = apiPageSelectorSelectedIndexes(range: job.rangeExpression, total: total)
        let selectedSet = Set(selectedIndexes)
        let maxItems = apiPageSelectorItemLimit(from: request)
        let visibleCandidates = Array(candidates.prefix(maxItems))
        let title = Self.htmlEscape(job.title.isEmpty ? job.source : job.title)
        let source = Self.htmlEscape(job.source)
        let range = Self.htmlEscape(job.rangeExpression)
        let disabled = isActive(job.status) ? " disabled" : ""
        let rows = visibleCandidates.map { candidate -> String in
            let checked = selectedSet.contains(candidate.index) ? " checked" : ""
            let detail = candidate.detail.isEmpty ? "" : #"<div class="source">\#(Self.htmlEscape(candidate.detail))</div>"#
            let thumbHTML: String
            if let file = candidate.file,
               Self.imageExtensions.contains(file.url.pathExtension.lowercased()) {
                thumbHTML = #"<img src="/thumb?uid=\#(uid)&index=\#(file.originalIndex)\#(auth)" alt="">"#
            } else {
                thumbHTML = #"<span class="placeholder">\#(candidate.index + 1)</span>"#
            }
            return """
            <label class="page-row">
              <input type="checkbox" value="\(candidate.index + 1)"\(checked)\(disabled)>
              <span class="thumb">\(thumbHTML)</span>
              <span><strong>[ \(String(format: "%02d", candidate.index + 1)) ] \(Self.htmlEscape(candidate.title))</strong>\(detail)</span>
            </label>
            """
        }.joined(separator: "\n")
        let truncated = candidates.count > visibleCandidates.count
            ? #"<p class="muted">Showing \#(visibleCandidates.count) of \#(candidates.count) entries.</p>"#
            : ""

        return """
        <!doctype html>
        <html>
        <head>
          <meta charset="utf-8">
          <meta name="viewport" content="width=device-width, initial-scale=1">
          <title>\(title) - Page Selector</title>
          <style>
            body { font: 13px \(Self.apiFontStack); margin: 0; background: #f7f7f5; color: #202124; }
            header { position: sticky; top: 0; z-index: 2; padding: 12px 14px; background: rgba(255,255,255,.94); border-bottom: 1px solid #ddd; backdrop-filter: blur(10px); }
            h1 { font-size: 17px; margin: 0 0 4px; }
            .meta, .source, .muted { color: #5f6368; overflow-wrap: anywhere; }
            .toolbar { display: flex; flex-wrap: wrap; gap: 8px; align-items: center; margin-top: 10px; }
            .toolbar a, button { display: inline-flex; min-height: 30px; align-items: center; padding: 0 10px; border: 1px solid #d6d6d6; border-radius: 6px; background: white; color: #1a73e8; text-decoration: none; cursor: pointer; font: inherit; }
            button.primary { background: #202124; color: white; border-color: #202124; }
            button:disabled { color: #8a8a8a; cursor: default; }
            main.page-selector { max-width: 960px; margin: 0 auto; padding: 16px; }
            form.range-form { display: flex; flex-wrap: wrap; gap: 8px; align-items: center; margin-bottom: 12px; }
            input[type="text"] { min-width: min(420px, 100%); padding: 8px 10px; border-radius: 6px; border: 1px solid #c8c8c8; font: inherit; }
            .page-list { display: grid; gap: 8px; }
            .page-row { display: grid; grid-template-columns: auto 58px 1fr; gap: 10px; align-items: center; padding: 9px 10px; background: white; border: 1px solid #ddd; }
            .thumb { width: 54px; height: 54px; display: grid; place-items: center; background: #f1f3f4; overflow: hidden; }
            .thumb img { width: 100%; height: 100%; object-fit: cover; display: block; }
            .placeholder { color: #6b6f76; font-weight: 600; }
            .empty { padding: 24px; background: white; border: 1px solid #ddd; color: #6b6f76; text-align: center; }
          </style>
        </head>
        <body>
          <header>
            <h1>\(title)</h1>
            <div class="meta">\(source)</div>
            <div class="meta">Range: \(range.isEmpty ? "All" : range) · Selected \(selectedIndexes.count) / \(total)</div>
            <div class="toolbar"><a href="/page_selector\(standaloneAuth)">Page Selector</a><a href="/view?uid=\(uid)\(auth)">View</a><a href="/info?uid=\(uid)\(auth)">Info</a><a href="/api/page_selector?uid=\(uid)\(auth)">JSON</a></div>
          </header>
          <main class="page-selector">
            <form class="range-form" method="post" action="/page_selector">
              <input type="hidden" name="uid" value="\(uid)">
              \(password.isEmpty ? "" : "<input type=\"hidden\" name=\"pw\" value=\"\(Self.htmlEscape(password))\">")
              <input id="range" type="text" name="range" value="\(range)" placeholder="1-3,5">
              <button class="primary" type="submit"\(disabled)>Save</button>
              <button type="button" onclick="selectAll()"\(disabled)>All</button>
              <button type="button" onclick="selectNone()"\(disabled)>None</button>
              <button type="button" onclick="rangeFromChecks()"\(disabled)>Use Checks</button>
            </form>
            \(truncated)
            \(visibleCandidates.isEmpty ? "<div class=\"empty\">No pages</div>" : "<div class=\"page-list\">\(rows)</div>")
          </main>
          <script>
            function checks(){ return Array.from(document.querySelectorAll('.page-row input[type="checkbox"]')); }
            function compact(values){
              values = Array.from(new Set(values.map(Number).filter(v => v > 0))).sort((a,b)=>a-b);
              const ranges = [];
              for (let i = 0; i < values.length; i++) {
                const start = values[i];
                let end = start;
                while (i + 1 < values.length && values[i + 1] === end + 1) end = values[++i];
                ranges.push(start === end ? String(start) : `${start}-${end}`);
              }
              return ranges.join(',');
            }
            function rangeFromChecks(){ document.getElementById('range').value = compact(checks().filter(c => c.checked).map(c => c.value)); }
            function selectAll(){ checks().forEach(c => c.checked = true); rangeFromChecks(); }
            function selectNone(){ checks().forEach(c => c.checked = false); rangeFromChecks(); }
            checks().forEach(c => c.addEventListener('change', rangeFromChecks));
          </script>
        </body>
        </html>
        """
    }

    private func apiPageSelectorUpdateResponse(_ request: LocalHTTPRequest) -> LocalHTTPResponse {
        guard let jobIndex = apiJobIndex(from: request) else {
            return LocalHTTPResponse.jsonObject(["error": "Task not found"], status: 404)
        }
        guard !isActive(jobs[jobIndex].status) else {
            return LocalHTTPResponse.jsonObject(["error": "Active task range cannot be edited"], status: 400)
        }
        let parameters = apiParameters(from: request)
        guard let requestedRange = apiPageSelectorRequestedRange(from: parameters) else {
            return LocalHTTPResponse.jsonObject(["error": "Missing range"], status: 400)
        }
        let range = requestedRange.trimmed
        guard Self.isValidAssetRangeExpression(range) else {
            return LocalHTTPResponse.jsonObject(["error": "Invalid range"], status: 400)
        }
        let total = apiPageSelectorTotal(for: jobs[jobIndex])
        if total > 0, !range.isEmpty {
            do {
                _ = try Self.assetIndexes(forRangeExpression: range, total: total)
            } catch {
                return LocalHTTPResponse.jsonObject(["error": error.localizedDescription], status: 400)
            }
        }

        jobs[jobIndex].rangeExpression = range
        if jobs[jobIndex].status == .finished {
            scheduleRestartIfNeeded(for: jobs[jobIndex])
        } else {
            cancelScheduledRestart(for: jobs[jobIndex].id)
        }
        addSummary = range.isEmpty ? "Page range cleared" : "Page range updated"
        persistQueue()
        return LocalHTTPResponse.jsonObject(apiPageSelectorJobObject(jobIndex: jobIndex, request: request, updated: true))
    }

    private func apiPageSelectorRequestedRange(from parameters: [String: String]) -> String? {
        if Self.apiTruthy(Self.apiParameterValueAllowingEmpty(in: parameters, keys: ["all", "select_all", "selectAll"]) ?? "") {
            return ""
        }
        if Self.apiTruthy(Self.apiParameterValueAllowingEmpty(in: parameters, keys: ["clear", "reset", "none"]) ?? "") {
            return ""
        }
        guard let raw = Self.apiParameterValueAllowingEmpty(in: parameters, keys: [
            "range", "range_expression", "rangeExpression", "pages", "page",
            "selection", "selected", "indexes", "indices", "items", "value"
        ]) else {
            return nil
        }
        return raw
            .replacingOccurrences(of: "\r\n", with: ",")
            .replacingOccurrences(of: "\n", with: ",")
            .replacingOccurrences(of: "\r", with: ",")
            .trimmed
    }

    private func apiPageSelectorCandidates(for job: DownloadJob) -> [(index: Int, title: String, detail: String, type: String, file: APIOutputFile?)] {
        let files = apiOutputFiles(for: job)
        if !files.isEmpty {
            return files.map { file in
                let type = Self.apiMediaType(for: file.url)
                return (
                    index: file.originalIndex,
                    title: file.relativePath,
                    detail: type,
                    type: type,
                    file: file
                )
            }
        }

        let total = apiPageSelectorTotal(for: job, candidateCount: 0)
        guard total > 0 else { return [] }
        let limit = min(total, 2_000)
        return (0..<limit).map { index in
            (
                index: index,
                title: String(format: "Page %02d", index + 1),
                detail: "",
                type: "page",
                file: nil
            )
        }
    }

    private func apiPageSelectorTotal(for job: DownloadJob, candidateCount: Int? = nil) -> Int {
        if let candidateCount, candidateCount > 0 {
            return candidateCount
        }
        let outputCount = apiOutputFiles(for: job).count
        if outputCount > 0 {
            return outputCount
        }
        let metadataCount = [
            "range_total", "page_count", "pages", "total_pages",
            "file_count", "files", "total"
        ].compactMap { job.metadata[$0].flatMap(Int.init) }.max() ?? 0
        return max(job.total, job.completed, metadataCount)
    }

    private func apiPageSelectorSelectedIndexes(range: String, total: Int) -> [Int] {
        guard total > 0 else { return [] }
        let trimmed = range.trimmed
        guard !trimmed.isEmpty else { return Array(0..<total) }
        return (try? Self.assetIndexes(forRangeExpression: trimmed, total: total)) ?? []
    }

    private func apiPageSelectorItemLimit(from request: LocalHTTPRequest) -> Int {
        let parameters = apiParameters(from: request)
        let value = Self.apiFirstParameterValue(in: parameters, keys: ["limit", "max", "count"]).flatMap(Int.init) ?? 500
        return max(1, min(5_000, value))
    }

    private func apiTextResponse(_ request: LocalHTTPRequest) -> LocalHTTPResponse {
        guard apiTextHasJobSelector(request) else {
            return LocalHTTPResponse.jsonObject(apiTextIndexObject(request))
        }
        do {
            guard let selection = try apiTextSelection(from: request) else {
                return LocalHTTPResponse.jsonObject(["error": "Task not found"], status: 404)
            }
            return LocalHTTPResponse.jsonObject(apiTextObject(selection: selection, request: request))
        } catch {
            return LocalHTTPResponse.jsonObject(["error": error.localizedDescription], status: 400)
        }
    }

    private func apiTextPage(_ request: LocalHTTPRequest) -> String {
        let password = request.query["pw"] ?? request.query["password"] ?? ""
        let auth = apiAuthQuery(password)
        let standaloneAuth = apiAuthStandaloneQuery(password)
        guard apiTextHasJobSelector(request) else {
            return apiTextIndexPage(request: request, auth: auth, standaloneAuth: standaloneAuth)
        }

        do {
            guard let selection = try apiTextSelection(from: request) else {
                return apiMessagePage(title: "Task not found", message: "uid or job is required.")
            }
            return apiTextDetailPage(selection: selection, auth: auth, standaloneAuth: standaloneAuth)
        } catch {
            return apiMessagePage(title: "Text could not be read", message: error.localizedDescription)
        }
    }

    private func apiTextIndexObject(_ request: LocalHTTPRequest) -> [String: Any] {
        let password = request.query["pw"] ?? request.query["password"] ?? ""
        let auth = apiAuthQuery(password)
        let items = jobs.indices.compactMap { index -> [String: Any]? in
            let job = jobs[index]
            let files = apiTextCandidateFiles(for: job)
            let hasMessage = !job.message.trimmed.isEmpty || !job.comment.trimmed.isEmpty
            guard !files.isEmpty || hasMessage else { return nil }
            let uid = job.id.uuidString
            let firstFile = files.first
            let textLink = firstFile.map { "/text?uid=\(uid)&index=\($0.originalIndex)\(auth)" } ?? "/text?uid=\(uid)\(auth)"
            return [
                "id": uid,
                "job": index,
                "source": job.source,
                "title": job.title,
                "status": job.status.rawValue,
                "message": job.message,
                "comment": job.comment,
                "textFileCount": files.count,
                "firstTextFile": firstFile?.relativePath ?? "",
                "text": textLink,
                "api": firstFile.map { "/api/text?uid=\(uid)&index=\($0.originalIndex)\(auth)" } ?? "/api/text?uid=\(uid)\(auth)",
                "files": files.map { apiTextFileObject($0, jobID: uid, auth: auth) }
            ]
        }
        return [
            "ok": true,
            "count": items.count,
            "total": jobs.count,
            "items": items
        ]
    }

    private func apiTextIndexPage(request: LocalHTTPRequest, auth: String, standaloneAuth: String) -> String {
        let rows = jobs.indices.compactMap { index -> String? in
            let job = jobs[index]
            let files = apiTextCandidateFiles(for: job)
            let hasMessage = !job.message.trimmed.isEmpty || !job.comment.trimmed.isEmpty
            guard !files.isEmpty || hasMessage else { return nil }

            let uid = job.id.uuidString
            let title = Self.htmlEscape(job.title.isEmpty ? job.source : job.title)
            let source = Self.htmlEscape(job.source)
            let firstFile = files.first
            let href = firstFile.map { "/text?uid=\(uid)&index=\($0.originalIndex)\(auth)" } ?? "/text?uid=\(uid)\(auth)"
            let fileName = firstFile?.relativePath ?? (hasMessage ? "Task Messages" : "No text files")
            let fileList = files.prefix(5).map { file in
                let link = "/text?uid=\(uid)&index=\(file.originalIndex)\(auth)"
                return #"<a href="\#(Self.htmlEscape(link))">\#(Self.htmlEscape(file.relativePath))</a>"#
            }.joined(separator: " ")
            let summary = files.isEmpty ? "message/comment" : "\(files.count) text file\(files.count == 1 ? "" : "s")"
            return """
            <tr>
              <td><a href="\(Self.htmlEscape(href))"><strong>\(title)</strong></a><div class="source">\(source)</div></td>
              <td>\(Self.htmlEscape(summary))<div class="source">First: \(Self.htmlEscape(fileName))</div></td>
              <td class="files">\(fileList.isEmpty ? Self.htmlEscape(job.message.trimmed) : fileList)</td>
            </tr>
            """
        }.joined(separator: "\n")
        let table = rows.isEmpty
            ? #"<div class="empty">No text output files or task messages.</div>"#
            : """
              <table class="text-index">
                <thead><tr><th>Task</th><th>Text</th><th>Files</th></tr></thead>
                <tbody>\(rows)</tbody>
              </table>
              """

        return """
        <!doctype html>
        <html>
        <head>
          <meta charset="utf-8">
          <meta name="viewport" content="width=device-width, initial-scale=1">
          <title>Text Viewer - Hitomi Badayo</title>
          <style>
            body { font: 14px \(Self.apiFontStack); margin: 0; background: #f7f7f5; color: #202124; }
            header { position: sticky; top: 0; z-index: 2; padding: 12px 14px; background: rgba(255,255,255,.94); border-bottom: 1px solid #ddd; backdrop-filter: blur(10px); }
            h1 { font-size: 18px; margin: 0 0 8px; }
            nav { display: flex; flex-wrap: wrap; gap: 10px; }
            main { max-width: 980px; margin: 0 auto; padding: 18px; }
            table { width: 100%; border-collapse: collapse; background: white; border: 1px solid #ddd; }
            th, td { padding: 10px 12px; border-bottom: 1px solid #eee; text-align: left; vertical-align: top; }
            th { color: #5f6368; background: #fafafa; }
            .source, .files { color: #5f6368; overflow-wrap: anywhere; }
            .files a { display: inline-block; margin: 0 8px 6px 0; }
            .empty { padding: 24px; background: white; border: 1px solid #ddd; color: #6b6f76; text-align: center; }
            a { color: #1a73e8; text-decoration: none; }
          </style>
        </head>
        <body>
          <header>
            <h1>Text Viewer</h1>
            <nav><a href="/webui\(standaloneAuth)">Queue</a><a href="/list\(standaloneAuth)">List</a><a href="/docs\(standaloneAuth)">Docs</a><a href="/api/text\(standaloneAuth)">JSON</a></nav>
          </header>
          <main>
            \(table)
          </main>
        </body>
        </html>
        """
    }

    private func apiTextDetailPage(selection: APITextSelection, auth: String, standaloneAuth: String) -> String {
        let uid = selection.job.id.uuidString
        let titleText = selection.job.title.isEmpty ? selection.job.source : selection.job.title
        let title = Self.htmlEscape(titleText)
        let source = Self.htmlEscape(selection.job.source)
        let filename = selection.file?.relativePath ?? "Task Messages"
        let safeFilename = Self.htmlEscape(filename)
        let fileLink = selection.file.map { #"<a href="/file?uid=\#(uid)&index=\#($0.originalIndex)\#(auth)">Raw File</a>"# } ?? ""
        let apiLink = selection.file.map { "/api/text?uid=\(uid)&index=\($0.originalIndex)\(auth)" } ?? "/api/text?uid=\(uid)\(auth)"
        let viewLink = "/view?uid=\(uid)\(auth)"
        let truncatedHTML = selection.truncated ? #"<span class="warn">Truncated at \#(selection.bytesRead) bytes.</span>"# : ""
        let textFiles = apiTextCandidateFiles(for: selection.job)
        let otherFilesHTML = textFiles.map { file in
            let href = "/text?uid=\(uid)&index=\(file.originalIndex)\(auth)"
            let active = (selection.file?.originalIndex ?? -1) == file.originalIndex ? " active" : ""
            return #"<a class="chip\#(active)" href="\#(Self.htmlEscape(href))">\#(Self.htmlEscape(file.relativePath))</a>"#
        }.joined(separator: "\n")
        let messageHTML = [
            selection.job.message.trimmed.isEmpty ? nil : "Message: \(selection.job.message.trimmed)",
            selection.job.comment.trimmed.isEmpty ? nil : "Comment: \(selection.job.comment.trimmed)"
        ].compactMap { $0 }.map { "<p>\(Self.htmlEscape($0))</p>" }.joined(separator: "\n")

        return """
        <!doctype html>
        <html>
        <head>
          <meta charset="utf-8">
          <meta name="viewport" content="width=device-width, initial-scale=1">
          <title>\(title) - \(safeFilename)</title>
          <style>
            body { font: 13px \(Self.apiFontStack); margin: 0; background: #f7f7f5; color: #202124; }
            header { position: sticky; top: 0; z-index: 2; padding: 12px 14px; background: rgba(255,255,255,.94); border-bottom: 1px solid #ddd; backdrop-filter: blur(10px); }
            h1 { font-size: 17px; margin: 0 0 4px; }
            .meta { color: #5f6368; overflow-wrap: anywhere; }
            .toolbar, .chips { display: flex; flex-wrap: wrap; gap: 8px; align-items: center; margin-top: 10px; }
            .toolbar a, .chip { display: inline-flex; min-height: 30px; align-items: center; padding: 0 10px; border: 1px solid #d6d6d6; border-radius: 6px; background: white; text-decoration: none; color: #1a73e8; }
            .chip.active { background: #202124; color: white; border-color: #202124; }
            main { max-width: 1040px; margin: 0 auto; padding: 16px; }
            .message { color: #5f6368; background: white; border: 1px solid #ddd; padding: 10px 12px; margin-bottom: 12px; }
            .text-viewer { box-sizing: border-box; width: 100%; min-height: 58vh; margin: 0; padding: 14px; border: 1px solid #ddd; background: white; color: #202124; overflow: auto; white-space: pre-wrap; overflow-wrap: anywhere; line-height: 1.45; font: 13px ui-monospace, SFMono-Regular, Menlo, Consolas, monospace; }
            .warn { color: #a05a00; }
          </style>
        </head>
        <body>
          <header>
            <h1>\(title)</h1>
            <div class="meta">\(source)</div>
            <div class="meta">\(safeFilename) · \(selection.bytesRead) / \(selection.byteCount) bytes \(truncatedHTML)</div>
            <div class="toolbar"><a href="/text\(standaloneAuth)">Text Index</a><a href="\(Self.htmlEscape(viewLink))">All Files</a>\(fileLink)<a href="\(Self.htmlEscape(apiLink))">JSON</a></div>
          </header>
          <main>
            \(otherFilesHTML.isEmpty ? "" : "<div class=\"chips\">\(otherFilesHTML)</div>")
            \(messageHTML.isEmpty ? "" : "<section class=\"message\">\(messageHTML)</section>")
            <pre class="text-viewer">\(Self.htmlEscape(selection.text))</pre>
          </main>
        </body>
        </html>
        """
    }

    private func apiTextSelection(from request: LocalHTTPRequest) throws -> APITextSelection? {
        guard let jobIndex = apiJobIndex(from: request) else { return nil }
        let job = jobs[jobIndex]
        let allFiles = apiOutputFiles(for: job)
        let textFiles = apiTextCandidateFiles(in: allFiles)
        let selectedFile: APIOutputFile?

        if let fileIndexText = apiTextFileIndexText(from: request) {
            guard let fileIndex = Int(fileIndexText), allFiles.indices.contains(fileIndex) else {
                throw NSError(domain: "HitomiBadayo.APIText", code: 1, userInfo: [NSLocalizedDescriptionKey: "File index is out of range."])
            }
            let requested = allFiles[fileIndex]
            guard apiIsTextOutputFile(requested) else {
                throw NSError(domain: "HitomiBadayo.APIText", code: 2, userInfo: [NSLocalizedDescriptionKey: "Selected output file is not a supported text document."])
            }
            selectedFile = requested
        } else {
            selectedFile = textFiles.first
        }

        if let selectedFile {
            let limit = apiTextLimit(from: request)
            let read = try apiReadTextFile(selectedFile, limit: limit)
            return APITextSelection(
                jobIndex: jobIndex,
                job: job,
                file: selectedFile,
                text: read.text,
                bytesRead: read.bytesRead,
                byteCount: apiOutputFileSize(selectedFile),
                truncated: read.truncated,
                source: "file"
            )
        }

        let fallbackText = [
            job.message.trimmed.isEmpty ? nil : "Message: \(job.message.trimmed)",
            job.comment.trimmed.isEmpty ? nil : "Comment: \(job.comment.trimmed)"
        ].compactMap { $0 }.joined(separator: "\n\n")
        return APITextSelection(
            jobIndex: jobIndex,
            job: job,
            file: nil,
            text: fallbackText,
            bytesRead: fallbackText.utf8.count,
            byteCount: fallbackText.utf8.count,
            truncated: false,
            source: fallbackText.isEmpty ? "job" : "message"
        )
    }

    private func apiTextObject(selection: APITextSelection, request: LocalHTTPRequest) -> [String: Any] {
        let password = request.query["pw"] ?? request.query["password"] ?? ""
        let auth = apiAuthQuery(password)
        let uid = selection.job.id.uuidString
        let file = selection.file
        let fileObject: Any
        let fileIndex: Any
        if let file {
            fileObject = apiTextFileObject(file, jobID: uid, auth: auth)
            fileIndex = file.originalIndex
        } else {
            fileObject = NSNull()
            fileIndex = NSNull()
        }
        let filename = file.map { Self.apiOutputDisplayName($0) } ?? ""
        let download = file.map { "/file?uid=\(uid)&index=\($0.originalIndex)\(auth)" } ?? ""
        return [
            "ok": true,
            "id": uid,
            "job": selection.jobIndex,
            "source": selection.job.source,
            "title": selection.job.title,
            "status": selection.job.status.rawValue,
            "message": selection.job.message,
            "comment": selection.job.comment,
            "textSource": selection.source,
            "text": selection.text,
            "bytes": selection.bytesRead,
            "size": selection.byteCount,
            "truncated": selection.truncated,
            "index": fileIndex,
            "filename": filename,
            "relativePath": file?.relativePath ?? "",
            "mimeType": file.map { Self.mimeType(for: $0.url) } ?? "text/plain; charset=utf-8",
            "file": fileObject,
            "files": apiTextCandidateFiles(for: selection.job).map { apiTextFileObject($0, jobID: uid, auth: auth) },
            "download": download,
            "view": "/text?uid=\(uid)\(file.map { "&index=\($0.originalIndex)" } ?? "")\(auth)",
            "allFiles": "/view?uid=\(uid)\(auth)"
        ]
    }

    private func apiTextFileObject(_ file: APIOutputFile, jobID: String, auth: String) -> [String: Any] {
        [
            "index": file.originalIndex,
            "relativePath": file.relativePath,
            "filename": Self.apiOutputDisplayName(file),
            "path": Self.apiOutputDisplayPath(file),
            "size": apiOutputFileSize(file),
            "mediaType": Self.apiMediaType(for: file.url),
            "mimeType": Self.mimeType(for: file.url),
            "text": "/text?uid=\(jobID)&index=\(file.originalIndex)\(auth)",
            "api": "/api/text?uid=\(jobID)&index=\(file.originalIndex)\(auth)",
            "download": "/file?uid=\(jobID)&index=\(file.originalIndex)\(auth)"
        ]
    }

    private func apiTextHasJobSelector(_ request: LocalHTTPRequest) -> Bool {
        let parameters = apiParameters(from: request)
        return parameters["uid"] != nil ||
            parameters["id"] != nil ||
            parameters["uids"] != nil ||
            parameters["job"] != nil ||
            parameters["index"] != nil
    }

    private func apiTextFileIndexText(from request: LocalHTTPRequest) -> String? {
        let query = request.query
        let hasExplicitJob = query["uid"] != nil || query["id"] != nil || query["uids"] != nil || query["job"] != nil
        if !hasExplicitJob, query["index"] != nil {
            return Self.apiFirstParameterValue(in: query, keys: ["idx", "i", "file_index", "fileindex"])
        }
        return Self.apiFirstParameterValue(in: query, keys: ["index", "idx", "i", "file_index", "fileindex"])
    }

    private func apiTextCandidateFiles(for job: DownloadJob) -> [APIOutputFile] {
        apiTextCandidateFiles(in: apiOutputFiles(for: job))
    }

    private func apiTextCandidateFiles(in files: [APIOutputFile]) -> [APIOutputFile] {
        files.filter(apiIsTextOutputFile)
    }

    private func apiIsTextOutputFile(_ file: APIOutputFile) -> Bool {
        Self.documentExtensions.contains(file.url.pathExtension.lowercased())
    }

    private func apiTextLimit(from request: LocalHTTPRequest) -> Int {
        let parameters = apiParameters(from: request)
        let defaultLimit = 1_048_576
        let maxLimit = 10_485_760
        guard let token = Self.apiFirstParameterValue(in: parameters, keys: ["limit", "max", "bytes", "max_bytes", "maxbytes"]),
              let value = Int(token) else {
            return defaultLimit
        }
        return max(1, min(maxLimit, value))
    }

    private func apiReadTextFile(_ file: APIOutputFile, limit: Int) throws -> APITextReadResult {
        let maxBytes = max(1, limit)
        let data: Data
        let truncated: Bool
        if file.archiveEntry != nil {
            let fullData = try apiOutputFileData(file)
            truncated = fullData.count > maxBytes
            data = truncated ? Data(fullData.prefix(maxBytes)) : fullData
        } else {
            let handle = try FileHandle(forReadingFrom: file.url)
            defer { try? handle.close() }
            let readData = try handle.read(upToCount: maxBytes + 1) ?? Data()
            truncated = readData.count > maxBytes
            data = truncated ? Data(readData.prefix(maxBytes)) : readData
        }
        let text = String(data: data, encoding: .utf8) ?? String(decoding: data, as: UTF8.self)
        return APITextReadResult(text: text, bytesRead: data.count, truncated: truncated)
    }

    private func apiViewResponse(_ request: LocalHTTPRequest) -> LocalHTTPResponse {
        let jobIndexes = apiJobIndexes(from: request)
        guard let jobIndex = jobIndexes.first else {
            return LocalHTTPResponse.html(apiMessagePage(title: "Task not found", message: "uid is required."), status: 404)
        }

        let preferences = APIViewPreferences(query: request.query)
        if jobIndexes.count > 1, request.query["index"] == nil {
            return LocalHTTPResponse.html(
                apiMultiViewPage(jobIndexes: jobIndexes, request: request, preferences: preferences)
            )
        }

        let job = jobs[jobIndex]
        let allFiles = apiOutputFiles(for: job)
        let files = apiSortedOutputFiles(apiSelectedOutputFiles(allFiles, request: request), preferences: preferences)
        let password = request.query["pw"] ?? request.query["password"] ?? ""
        let auth = apiAuthQuery(password)
        let displayTitle = apiViewTitle(for: job, request: request)
        let title = Self.htmlEscape(displayTitle)
        let uid = job.id.uuidString
        let viewOptions = apiViewOptionQuery(from: request)
        let preferenceOptions = apiViewPreferenceOptionQuery(from: request)
        let mode = apiViewMode(from: request)

        if mode == "scroll" || mode == "reader" || (mode.isEmpty && Self.apiTruthy(request.query["scroll"])) {
            return LocalHTTPResponse.html(
                apiScrollViewPage(
                    jobIndex: jobIndex,
                    files: files,
                    auth: auth,
                    viewOptions: viewOptions,
                    preferenceOptions: preferenceOptions,
                    displayTitle: displayTitle,
                    preferences: preferences
                )
            )
        }

        if mode == "book" || Self.apiTruthy(request.query["single"]) {
            return LocalHTTPResponse.html(
                apiBookViewPage(
                    jobIndex: jobIndex,
                    files: files,
                    pageText: apiReaderPageText(from: request),
                    auth: auth,
                    viewOptions: viewOptions,
                    preferenceOptions: preferenceOptions,
                    displayTitle: displayTitle,
                    preferences: preferences
                )
            )
        }

        if let indexText = apiFileIndexText(from: request) {
            guard let selectedIndex = Int(indexText),
                  let selectedPosition = files.firstIndex(where: { $0.originalIndex == selectedIndex }) else {
                return LocalHTTPResponse.html(apiMessagePage(title: "File not found", message: "index is out of range."), status: 404)
            }
            return LocalHTTPResponse.html(
                apiFileViewPage(
                    job: job,
                    files: files,
                    selectedPosition: selectedPosition,
                    auth: auth,
                    viewOptions: viewOptions,
                    displayTitle: displayTitle,
                    preferences: preferences
                )
            )
        }

        let imageIndexes = files.enumerated()
            .filter { Self.imageExtensions.contains($0.element.url.pathExtension.lowercased()) }
            .map(\.offset)
        let readerHTML = imageIndexes.isEmpty
            ? #"<span class="nav disabled">Reader</span>"#
            : #"<a class="nav" href="/view?uid=\#(uid)&mode=book&page=0\#(auth)\#(viewOptions)">Reader</a>"#
        let scrollHTML = imageIndexes.isEmpty
            ? #"<span class="nav disabled">Scroll</span>"#
            : #"<a class="nav" href="/view?uid=\#(uid)&mode=scroll\#(auth)\#(viewOptions)">Scroll</a>"#
        let previousHTML = apiAdjacentViewJobIndex(from: jobIndex, direction: -1).map {
            #"<a class="nav" data-prev href="/view?uid=\#(jobs[$0].id.uuidString)\#(auth)\#(preferenceOptions)">Previous</a>"#
        } ?? #"<span class="nav disabled">Previous</span>"#
        let nextHTML = apiAdjacentViewJobIndex(from: jobIndex, direction: 1).map {
            #"<a class="nav" data-next href="/view?uid=\#(jobs[$0].id.uuidString)\#(auth)\#(preferenceOptions)">Next</a>"#
        } ?? #"<span class="nav disabled">Next</span>"#

        let chapterGroups = apiChapterGroups(allFiles)
        let chapterOptions = apiViewPreferenceOptionQuery(from: request)
        let selectedChapterIndex = apiSelectedChapterIndex(in: allFiles, request: request)
        let chapterNavigationHTML = apiChapterNavigationHTML(
            groups: chapterGroups,
            selectedIndex: selectedChapterIndex,
            uid: uid,
            auth: auth,
            options: chapterOptions
        )
        let chapterNavigationScript = selectedChapterIndex == nil ? "" : """
          <script>
            document.addEventListener('keydown', event => {
              if (event.ctrlKey || event.altKey || event.shiftKey || event.metaKey) return;
              if (event.key === 'ArrowLeft') {
                const previous = document.getElementById('prev');
                if (previous && previous.href) location.href = previous.href;
              }
              if (event.key === 'ArrowRight') {
                const next = document.getElementById('next');
                if (next && next.href) location.href = next.href;
              }
            });
          </script>
        """
        let chapterHTML: String
        if chapterGroups.count > 1 {
            chapterHTML = """
            <section class="chapters" aria-label="Chapters">
              \(chapterGroups.enumerated().map { _, group in
                  let chapterTitle = Self.htmlEscape(group.title)
                  let fileCount = "\(group.indexes.count) files"
                  let start = group.indexes.first ?? 0
                  let end = group.indexes.last ?? 0
                  let href = "/view?uid=\(uid)&start=\(start)&end=\(end)\(auth)\(chapterOptions)&title=\(Self.queryComponent(group.title))"
                  return "<a href=\"\(href)\"><strong>\(chapterTitle)</strong><span>\(fileCount)</span></a>"
              }.joined(separator: "\n"))
            </section>
            """
        } else {
            chapterHTML = ""
        }

        let gridHTML: String
        if imageIndexes.count > 1 {
            gridHTML = """
            <section class="gallery-grid" aria-label="Image navigation">
              \(imageIndexes.map { index in
                  let file = files[index]
                  let name = Self.htmlEscape(file.relativePath)
                  let thumbURL = "/thumb?uid=\(uid)&index=\(file.originalIndex)\(auth)"
                  let detailURL = "/view?uid=\(uid)&index=\(file.originalIndex)\(auth)\(viewOptions)"
                  return "<a href=\"\(detailURL)\"><img src=\"\(thumbURL)\" alt=\"\(name)\"><span>\(index + 1)</span></a>"
              }.joined(separator: "\n"))
            </section>
            """
        } else {
            gridHTML = ""
        }

        let fileHTML: String
        if files.isEmpty {
            fileHTML = #"<div class="empty">No output files</div>"#
        } else {
            fileHTML = files.enumerated().map { index, file in
                let fileURL = "/file?uid=\(uid)&index=\(file.originalIndex)\(auth)"
                let name = Self.htmlEscape(file.relativePath)
                let ext = file.url.pathExtension.lowercased()
                if Self.imageExtensions.contains(ext) {
                    return #"<figure id="file-\#(index)">\#(apiPageImage(src: fileURL, id: "page\(index)", alt: name, preferences: preferences))<figcaption>\#(name)</figcaption></figure>"#
                }
                if Self.videoExtensions.contains(ext) {
                    return #"<figure id="file-\#(index)"><video controls class="page" id="page\#(index)" preload="metadata" src="\#(fileURL)"></video><figcaption>\#(name)</figcaption></figure>"#
                }
                if Self.audioExtensions.contains(ext) {
                    return #"<figure id="file-\#(index)"><audio controls class="page" id="page\#(index)" src="\#(fileURL)"></audio><figcaption>\#(name)</figcaption></figure>"#
                }
                return #"<p class="file page" id="file-\#(index)" data-page-id="page\#(index)"><a href="\#(fileURL)">\#(name)</a></p>"#
            }.joined(separator: "\n")
        }

        return LocalHTTPResponse.html("""
        <!doctype html>
        <html\(preferences.htmlDirectionAttribute)>
        <head>
          <meta charset="utf-8">
          <meta name="viewport" content="width=device-width, initial-scale=1">
          <title>\(title)</title>
          <style>
            body { margin: 0; \(preferences.bodyCSS) font: 13px \(Self.apiFontStack); }
            header { position: sticky; top: 0; z-index: 2; padding: 12px 14px; \(preferences.headerCSS) backdrop-filter: blur(10px); }
            h1 { font-size: 16px; margin: 0 0 4px; }
            .meta { color: #5f6368; overflow-wrap: anywhere; }
            .toolbar { display: flex; gap: 8px; align-items: center; margin-top: 10px; }
            .nav { display: inline-flex; min-height: 30px; align-items: center; padding: 0 10px; border-radius: 6px; \(preferences.navCSS) text-decoration: none; }
            .disabled { \(preferences.disabledCSS) }
            main { max-width: 980px; margin: 0 auto; padding: 14px; }
            .chapters { display: flex; flex-wrap: wrap; gap: 8px; margin-bottom: 14px; }
            .chapters a { display: inline-flex; flex-direction: column; gap: 2px; min-width: 120px; padding: 9px 10px; border: 1px solid \(preferences.isDark ? "#333" : "#ddd"); background: \(preferences.isDark ? "#171717" : "white"); color: inherit; text-decoration: none; }
            .chapters span { color: #5f6368; font-size: 12px; }
            .chapter-nav { display: flex; flex-wrap: wrap; gap: 8px; align-items: center; margin-bottom: 14px; }
            .gallery-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(92px, 1fr)); gap: 8px; margin-bottom: 14px; }
            .gallery-grid a { position: relative; display: block; aspect-ratio: 1; overflow: hidden; border: 1px solid #ddd; background: white; color: white; }
            .gallery-grid img { width: 100%; height: 100%; object-fit: cover; background: #111; }
            .gallery-grid span { position: absolute; right: 6px; bottom: 5px; padding: 2px 5px; border-radius: 4px; background: rgba(0,0,0,.62); font-size: 11px; }
            figure { \(preferences.figureCSS) background: \(preferences.isDark ? "#171717" : "white"); border: 1px solid \(preferences.isDark ? "#333" : "#ddd"); }
            img, video { display: block; \(preferences.imageCSS) background: #111; }
            audio { width: 100%; }
            figcaption, .file { color: #5f6368; overflow-wrap: anywhere; }
            .empty { padding: 24px; background: white; border: 1px solid #ddd; text-align: center; color: #6b6f76; }
          </style>
        </head>
        <body class="view">
          <header>
            <h1>\(title)</h1>
            <div class="meta">\(Self.htmlEscape(job.source))</div>
            <div class="toolbar">\(previousHTML)<a class="nav" href="/webui\(auth.isEmpty ? "" : "?\(String(auth.dropFirst()))")">Queue</a>\(readerHTML)\(scrollHTML)\(nextHTML)</div>
          </header>
          <main>
            \(chapterNavigationHTML)
            \(chapterHTML)
            \(gridHTML)
            \(fileHTML)
          </main>
          \(Self.apiLegacyViewKeydownScript(preferences: preferences))
          \(chapterNavigationScript)
        </body>
        </html>
        """)
    }

    private func apiMultiViewPage(jobIndexes: [Int], request: LocalHTTPRequest, preferences: APIViewPreferences) -> String {
        let password = request.query["pw"] ?? request.query["password"] ?? ""
        let auth = apiAuthQuery(password)
        let viewOptions = apiViewOptionQuery(from: request)
        let requestedTitle = request.query["title"]?.trimmed ?? ""
        let title = requestedTitle.isEmpty ? "\(jobIndexes.count) Tasks" : requestedTitle
        let safeTitle = Self.htmlEscape(title)

        let sectionHTML = jobIndexes.map { jobIndex in
            let job = jobs[jobIndex]
            let uid = job.id.uuidString
            let jobTitle = Self.htmlEscape(job.title.isEmpty ? job.source : job.title)
            let source = Self.htmlEscape(job.source)
            let allFiles = apiOutputFiles(for: job)
            let files = apiSortedOutputFiles(apiSelectedOutputFiles(allFiles, request: request), preferences: preferences)
            let imageCount = files.filter { Self.imageExtensions.contains($0.url.pathExtension.lowercased()) }.count
            let summary = "\(files.count) file\(files.count == 1 ? "" : "s")\(imageCount > 0 ? ", \(imageCount) image\(imageCount == 1 ? "" : "s")" : "")"
            let readerHTML = imageCount > 0
                ? #"<a class="nav" href="/view?uid=\#(uid)&mode=book&page=0\#(auth)\#(viewOptions)">Reader</a><a class="nav" href="/view?uid=\#(uid)&mode=scroll\#(auth)\#(viewOptions)">Scroll</a>"#
                : #"<span class="nav disabled">Reader</span><span class="nav disabled">Scroll</span>"#

            let filesHTML: String
            if files.isEmpty {
                filesHTML = #"<div class="empty">No output files</div>"#
            } else {
                filesHTML = files.enumerated().map { displayIndex, file in
                    let fileURL = "/file?uid=\(uid)&index=\(file.originalIndex)\(auth)"
                    let detailURL = "/view?uid=\(uid)&index=\(file.originalIndex)\(auth)\(viewOptions)"
                    let name = Self.htmlEscape(file.relativePath)
                    let ext = file.url.pathExtension.lowercased()
                    if Self.imageExtensions.contains(ext) {
                        return #"<figure id="task-\#(uid)-file-\#(displayIndex)"><a href="\#(detailURL)">\#(apiPageImage(src: fileURL, id: "page-\(uid)-\(displayIndex)", alt: name, preferences: preferences))</a><figcaption>\#(displayIndex + 1). \#(name)</figcaption></figure>"#
                    }
                    if Self.videoExtensions.contains(ext) {
                        return #"<figure id="task-\#(uid)-file-\#(displayIndex)"><video controls class="page" id="page-\#(uid)-\#(displayIndex)" preload="metadata" src="\#(fileURL)"></video><figcaption>\#(displayIndex + 1). \#(name)</figcaption></figure>"#
                    }
                    if Self.audioExtensions.contains(ext) {
                        return #"<figure id="task-\#(uid)-file-\#(displayIndex)"><audio controls class="page" id="page-\#(uid)-\#(displayIndex)" src="\#(fileURL)"></audio><figcaption>\#(displayIndex + 1). \#(name)</figcaption></figure>"#
                    }
                    return #"<p class="file page" id="task-\#(uid)-file-\#(displayIndex)" data-page-id="page-\#(uid)-\#(displayIndex)"><a href="\#(detailURL)">\#(displayIndex + 1). \#(name)</a></p>"#
                }.joined(separator: "\n")
            }

            return """
            <section class="task-section" id="task-\(uid)">
              <header class="task-header">
                <h2>\(jobTitle)</h2>
                <div class="meta">\(source)</div>
                <div class="toolbar"><span class="summary">\(summary)</span><a class="nav" href="/view?uid=\(uid)\(auth)\(viewOptions)">Open</a>\(readerHTML)</div>
              </header>
              <div class="task-files">
                \(filesHTML)
              </div>
            </section>
            """
        }.joined(separator: "\n")

        return """
        <!doctype html>
        <html\(preferences.htmlDirectionAttribute)>
        <head>
          <meta charset="utf-8">
          <meta name="viewport" content="width=device-width, initial-scale=1">
          <title>\(safeTitle) - Hitomi Badayo</title>
          <style>
            body { margin: 0; \(preferences.bodyCSS) font: 13px \(Self.apiFontStack); }
            body > header { position: sticky; top: 0; z-index: 2; padding: 12px 14px; \(preferences.headerCSS) backdrop-filter: blur(10px); }
            h1 { font-size: 16px; margin: 0 0 4px; }
            h2 { font-size: 15px; margin: 0 0 4px; }
            .meta, .summary, figcaption, .file { color: #5f6368; overflow-wrap: anywhere; }
            .toolbar { display: flex; flex-wrap: wrap; gap: 8px; align-items: center; margin-top: 9px; }
            .nav { display: inline-flex; min-height: 30px; align-items: center; padding: 0 10px; border-radius: 6px; \(preferences.navCSS) text-decoration: none; }
            .disabled { \(preferences.disabledCSS) }
            main.multi-view { max-width: 1180px; margin: 0 auto; padding: 14px; }
            .task-section { margin: 0 0 18px; }
            .task-header { padding: 12px 0 10px; border-bottom: 1px solid \(preferences.isDark ? "#333" : "#ddd"); }
            .task-files { display: grid; grid-template-columns: repeat(auto-fill, minmax(210px, 1fr)); gap: 10px; padding-top: 12px; }
            figure { margin: 0; padding: 8px; background: \(preferences.isDark ? "#171717" : "white"); border: 1px solid \(preferences.isDark ? "#333" : "#ddd"); }
            img, video { display: block; width: 100%; height: auto; max-height: 420px; object-fit: contain; background: #111; }
            audio { width: 100%; }
            figcaption { margin-top: 7px; font-size: 12px; }
            .file, .empty { padding: 12px; background: \(preferences.isDark ? "#171717" : "white"); border: 1px solid \(preferences.isDark ? "#333" : "#ddd"); }
            a { color: #1a73e8; }
          </style>
        </head>
        <body class="view">
          <header>
            <h1>\(safeTitle)</h1>
            <div class="meta">Multi-task browser view - \(jobIndexes.count) tasks</div>
            <div class="toolbar"><a class="nav" href="/webui\(auth.isEmpty ? "" : "?\(String(auth.dropFirst()))")">Queue</a></div>
          </header>
          <main class="multi-view">
            \(sectionHTML)
          </main>
          \(Self.apiLegacyViewKeydownScript(preferences: preferences))
        </body>
        </html>
        """
    }

    private func apiSelectedOutputFiles(_ files: [APIOutputFile], request: LocalHTTPRequest) -> [APIOutputFile] {
        guard !files.isEmpty else { return [] }
        if request.query["start"] == nil,
           request.query["end"] == nil,
           let chapterRange = apiChapterRange(in: files, request: request) {
            let groups = apiChapterGroups(files)
            let selectedIndexes = Set(groups[chapterRange].flatMap(\.indexes))
            return files.filter { selectedIndexes.contains($0.originalIndex) }
        }

        let start = max(0, Int(request.query["start"] ?? "") ?? 0)
        let end = min(files.count - 1, max(0, Int(request.query["end"] ?? "") ?? (files.count - 1)))
        guard start < files.count, end >= start else { return [] }
        return Array(files[start...end])
    }

    private func apiSortedOutputFiles(_ files: [APIOutputFile], preferences: APIViewPreferences) -> [APIOutputFile] {
        guard files.count > 1 else { return files }
        guard preferences.sort != "path" || preferences.descending else { return files }

        return files.sorted { lhs, rhs in
            let comparison: ComparisonResult
            switch preferences.sort {
            case "name":
                comparison = lhs.url.lastPathComponent.localizedStandardCompare(rhs.url.lastPathComponent)
            case "date":
                comparison = Self.apiDateComparison(apiFileModificationDate(lhs.url), apiFileModificationDate(rhs.url))
            case "size":
                comparison = Self.apiNumberComparison(apiFileSize(lhs.url), apiFileSize(rhs.url))
            case "type":
                let leftType = lhs.url.pathExtension.lowercased()
                let rightType = rhs.url.pathExtension.lowercased()
                comparison = leftType == rightType
                    ? lhs.relativePath.localizedStandardCompare(rhs.relativePath)
                    : leftType.localizedStandardCompare(rightType)
            default:
                comparison = lhs.relativePath.localizedStandardCompare(rhs.relativePath)
            }

            if comparison == .orderedSame {
                return lhs.originalIndex < rhs.originalIndex
            }
            return preferences.descending ? comparison == .orderedDescending : comparison == .orderedAscending
        }
    }

    private func apiFileModificationDate(_ file: URL) -> Date {
        (try? file.resourceValues(forKeys: [.contentModificationDateKey]).contentModificationDate) ?? .distantPast
    }

    private func apiFileSize(_ file: URL) -> Int64 {
        Int64((try? file.resourceValues(forKeys: [.fileSizeKey]).fileSize) ?? 0)
    }

    private static func apiDateComparison(_ lhs: Date, _ rhs: Date) -> ComparisonResult {
        if lhs < rhs { return .orderedAscending }
        if lhs > rhs { return .orderedDescending }
        return .orderedSame
    }

    private static func apiNumberComparison(_ lhs: Int64, _ rhs: Int64) -> ComparisonResult {
        if lhs < rhs { return .orderedAscending }
        if lhs > rhs { return .orderedDescending }
        return .orderedSame
    }

    private func apiChapterRange(in files: [APIOutputFile], request: LocalHTTPRequest) -> ClosedRange<Int>? {
        let groups = apiChapterGroups(files)
        guard !groups.isEmpty else { return nil }

        if let chapter = Self.apiFirstParameterValue(in: request.query, keys: ["chapter"]),
           !chapter.isEmpty,
           let index = apiChapterIndex(from: chapter, groups: groups) {
            return index...index
        }

        let startToken = Self.apiFirstParameterValue(in: request.query, keys: ["start_chapter", "chapter_start"])
        guard let startToken,
              let start = apiChapterIndex(from: startToken, groups: groups) else {
            return nil
        }

        let endToken = Self.apiFirstParameterValue(in: request.query, keys: ["end_chapter", "chapter_end"])
        let end = endToken.flatMap { apiChapterIndex(from: $0, groups: groups) } ?? start
        let lower = min(start, end)
        let upper = max(start, end)
        return lower...upper
    }

    private func apiChapterIndex(from token: String, groups: [APIChapterGroup]) -> Int? {
        let value = token.trimmed
        guard !value.isEmpty else { return nil }
        if let index = Int(value), groups.indices.contains(index) {
            return index
        }
        return groups.firstIndex {
            $0.title.compare(value, options: [.caseInsensitive, .diacriticInsensitive]) == .orderedSame ||
                $0.path.compare(value, options: [.caseInsensitive, .diacriticInsensitive]) == .orderedSame
        }
    }

    private func apiSelectedChapterIndex(in files: [APIOutputFile], request: LocalHTTPRequest) -> Int? {
        let groups = apiChapterGroups(files)
        guard groups.count > 1 else { return nil }

        if request.query["start"] == nil,
           request.query["end"] == nil,
           let range = apiChapterRange(in: files, request: request),
           range.lowerBound == range.upperBound {
            return range.lowerBound
        }

        guard let startText = request.query["start"]?.trimmed,
              let endText = request.query["end"]?.trimmed,
              let rawStart = Int(startText),
              let rawEnd = Int(endText) else {
            return nil
        }
        let start = max(0, rawStart)
        let end = min(files.count - 1, max(0, rawEnd))
        return groups.firstIndex { group in
            group.indexes.first == start && group.indexes.last == end
        }
    }

    private func apiChapterNavigationHTML(groups: [APIChapterGroup], selectedIndex: Int?, uid: String, auth: String, options: String) -> String {
        guard groups.count > 1,
              let selectedIndex,
              groups.indices.contains(selectedIndex) else {
            return ""
        }

        func chapterURL(_ index: Int) -> String {
            let group = groups[index]
            let start = group.indexes.first ?? 0
            let end = group.indexes.last ?? 0
            return "/view?uid=\(uid)&start=\(start)&end=\(end)\(auth)\(options)&title=\(Self.queryComponent(group.title))"
        }

        let previousHTML = selectedIndex > 0
            ? #"<a class="nav" id="prev" href="\#(chapterURL(selectedIndex - 1))">Previous Chapter</a>"#
            : #"<span class="nav disabled" id="prev">Previous Chapter</span>"#
        let nextHTML = selectedIndex + 1 < groups.count
            ? #"<a class="nav" id="next" href="\#(chapterURL(selectedIndex + 1))">Next Chapter</a>"#
            : #"<span class="nav disabled" id="next">Next Chapter</span>"#
        let listURL = "/view?uid=\(uid)\(auth)\(options)"
        let currentTitle = Self.htmlEscape(groups[selectedIndex].title)
        return """
        <nav class="chapter-nav" aria-label="Chapter navigation">
          \(previousHTML)
          <a class="nav" href="\(listURL)">All Chapters</a>
          \(nextHTML)
          <span class="summary">\(currentTitle)</span>
        </nav>
        """
    }

    private func apiViewTitle(for job: DownloadJob, request: LocalHTTPRequest) -> String {
        if let title = request.query["title"]?.trimmed, !title.isEmpty {
            return title
        }
        return job.title.isEmpty ? job.source : job.title
    }

    private func apiViewOptionQuery(from request: LocalHTTPRequest) -> String {
        let passthrough: [(String, [String])] = [
            ("start", ["start"]),
            ("end", ["end"]),
            ("chapter", ["chapter"]),
            ("start_chapter", ["start_chapter", "chapter_start"]),
            ("end_chapter", ["end_chapter", "chapter_end"]),
            ("title", ["title"])
        ]
        var items: [(String, String)] = passthrough.compactMap { canonical, aliases -> (String, String)? in
            guard let value = Self.apiFirstParameterValue(in: request.query, keys: aliases), !value.isEmpty else { return nil }
            return (canonical, value)
        }
        items.append(contentsOf: APIViewPreferences(query: request.query).queryItems)
        let parts = items.map { key, value in "\(key)=\(Self.queryComponent(value))" }
        return parts.isEmpty ? "" : "&" + parts.joined(separator: "&")
    }

    private func apiViewPreferenceOptionQuery(from request: LocalHTTPRequest) -> String {
        let parts = APIViewPreferences(query: request.query).queryItems.map { key, value in
            "\(key)=\(Self.queryComponent(value))"
        }
        return parts.isEmpty ? "" : "&" + parts.joined(separator: "&")
    }

    private func apiViewMode(from request: LocalHTTPRequest) -> String {
        let raw = Self.apiFirstParameterValue(in: request.query, keys: [
            "mode",
            "view",
            "viewer",
            "reader",
            "view_mode",
            "viewmode",
            "viewer_mode",
            "viewermode",
            "page_mode",
            "pagemode",
            "reader_mode",
            "readermode"
        ])?.lowercased() ?? ""

        switch raw {
        case "book", "page", "paged", "reader", "single", "clip_viewer", "clip-viewer", "clipviewer", "image_reader", "image-reader", "imagereader", "image_viewer", "image-viewer", "imageviewer", "page_viewer", "page-viewer", "pageviewer", "one_page", "one-page", "onepage", "single_page", "single-page", "singlepage":
            return "book"
        case "all", "files", "file", "file_viewer", "file-viewer", "fileviewer", "gallery", "list", "browser", "file_browser", "file-browser", "filebrowser":
            return "files"
        case "scroll", "scroller", "continuous", "long", "vertical", "photo_scroller", "photo-scroller", "photoscroller", "long_strip", "long-strip", "longstrip", "webtoon":
            return "scroll"
        default:
            return raw
        }
    }

    private func apiReaderPageText(from request: LocalHTTPRequest) -> String? {
        Self.apiFirstParameterValue(in: request.query, keys: ["page", "p", "page_index", "pageindex"])
    }

    private func apiFileIndexText(from request: LocalHTTPRequest) -> String? {
        if apiIsViewPath(request.path),
           request.query["uid"] == nil,
           request.query["id"] == nil,
           request.query["uids"] == nil,
           request.query["job"] == nil,
           request.query["index"] != nil {
            return nil
        }
        let isThumbPath = ["/thumb", "/api/thumb"].contains(request.path.lowercased())
        if isThumbPath,
           request.query["uid"] == nil,
           request.query["id"] == nil,
           request.query["uids"] == nil,
           request.query["job"] == nil,
           request.query["index"] != nil {
            return nil
        }

        return Self.apiFirstParameterValue(in: request.query, keys: ["index", "idx", "i", "file_index", "fileindex"])
    }

    private func apiIsViewPath(_ path: String) -> Bool {
        switch path.lowercased() {
        case "/view", "/api/view", "/viewer", "/api/viewer", "/reader", "/api/reader":
            return true
        default:
            return false
        }
    }

    private func apiScrollViewPage(jobIndex: Int, files: [APIOutputFile], auth: String, viewOptions: String, preferenceOptions: String, displayTitle: String, preferences: APIViewPreferences) -> String {
        let job = jobs[jobIndex]
        let uid = job.id.uuidString
        let title = Self.htmlEscape(displayTitle)
        let imageFiles = files.enumerated()
            .filter { Self.imageExtensions.contains($0.element.url.pathExtension.lowercased()) }
        guard !imageFiles.isEmpty else {
            return apiMessagePage(title: "No images", message: "This output has no image files for scroll reader mode.")
        }

        let allFilesURL = "/view?uid=\(uid)\(auth)\(viewOptions)"
        let bookURL = "/view?uid=\(uid)&mode=book&page=0\(auth)\(viewOptions)"
        let previousHTML = apiAdjacentViewJobIndex(from: jobIndex, direction: -1).map {
            #"<a class="nav" id="prev" data-prev href="/view?uid=\#(jobs[$0].id.uuidString)&mode=scroll\#(auth)\#(preferenceOptions)">Previous Task</a>"#
        } ?? #"<span class="nav disabled" id="prev">Previous Task</span>"#
        let nextHTML = apiAdjacentViewJobIndex(from: jobIndex, direction: 1).map {
            #"<a class="nav" id="next" data-next href="/view?uid=\#(jobs[$0].id.uuidString)&mode=scroll\#(auth)\#(preferenceOptions)">Next Task</a>"#
        } ?? #"<span class="nav disabled" id="next">Next Task</span>"#
        let figuresHTML = imageFiles.enumerated().map { displayIndex, pair in
            let file = pair.element
            let name = Self.htmlEscape(file.relativePath)
            let imageURL = "/file?uid=\(uid)&index=\(file.originalIndex)\(auth)"
            let imageHTML = apiPageImage(src: imageURL, id: "page\(displayIndex)", alt: name, preferences: preferences)
            return """
            <figure id="file-\(pair.offset)">
              \(imageHTML)
              <figcaption>\(displayIndex + 1) / \(imageFiles.count) - \(name)</figcaption>
            </figure>
            """
        }.joined(separator: "\n")

        return """
        <!doctype html>
        <html\(preferences.htmlDirectionAttribute)>
        <head>
          <meta charset="utf-8">
          <meta name="viewport" content="width=device-width, initial-scale=1">
          <title>\(title) - Scroll Reader</title>
          <style>
            body { margin: 0; \(preferences.bodyCSS) font: 13px \(Self.apiFontStack); }
            header { position: sticky; top: 0; z-index: 2; padding: 10px 14px; \(preferences.headerCSS) backdrop-filter: blur(10px); }
            h1 { font-size: 15px; margin: 0 0 3px; color: \(preferences.isDark ? "white" : "#202124"); }
            .meta { color: #bdc1c6; overflow-wrap: anywhere; }
            .toolbar { display: flex; flex-wrap: wrap; gap: 8px; align-items: center; margin-top: 9px; }
            .nav { display: inline-flex; min-height: 30px; align-items: center; padding: 0 10px; border-radius: 6px; \(preferences.navCSS) text-decoration: none; }
            .disabled { \(preferences.disabledCSS) }
            main { width: min(1400px, 100%); margin: 0 auto; padding: 14px; box-sizing: border-box; }
            figure { \(preferences.figureCSS) background: \(preferences.isDark ? "#171717" : "white"); border: 1px solid \(preferences.isDark ? "#333" : "#ddd"); }
            img { display: block; \(preferences.imageCSS) \(preferences.mediaMarginCSS) background: #050505; }
            figcaption { margin-top: 10px; color: #bdc1c6; text-align: center; overflow-wrap: anywhere; }
          </style>
        </head>
        <body class="view">
          <header>
            <h1>\(title)</h1>
            <div class="meta">Scroll Reader - \(imageFiles.count) images</div>
            <div class="toolbar">\(previousHTML)<a class="nav" href="\(allFilesURL)">All Files</a><a class="nav" href="\(bookURL)">Paged Reader</a>\(nextHTML)</div>
          </header>
          <main>
            \(figuresHTML)
          </main>
          \(Self.apiLegacyViewKeydownScript(preferences: preferences))
          <script>
            document.addEventListener('keydown', event => {
              if (event.key === '\(preferences.previousKey)') {
                const previous = document.querySelector('[data-prev]');
                if (previous) location.href = previous.href;
              }
              if (event.key === '\(preferences.nextKey)') {
                const next = document.querySelector('[data-next]');
                if (next) location.href = next.href;
              }
              if (event.key === 'Escape') {
                location.href = \(Self.javascriptStringLiteral(allFilesURL));
              }
            });
            \(Self.apiWheelNavigationScript(edgeOnly: true))
          </script>
        </body>
        </html>
        """
    }

    private func apiBookViewPage(jobIndex: Int, files: [APIOutputFile], pageText: String?, auth: String, viewOptions: String, preferenceOptions: String, displayTitle: String, preferences: APIViewPreferences) -> String {
        let job = jobs[jobIndex]
        let uid = job.id.uuidString
        let title = Self.htmlEscape(displayTitle)
        let imageIndexes = files.enumerated()
            .filter { Self.imageExtensions.contains($0.element.url.pathExtension.lowercased()) }
            .map(\.offset)
        guard !imageIndexes.isEmpty else {
            return apiMessagePage(title: "No images", message: "This output has no image files for reader mode.")
        }

        let requestedPage = Int(pageText ?? "0") ?? 0
        let page = min(max(requestedPage, 0), imageIndexes.count - 1)
        let fileIndex = imageIndexes[page]
        let file = files[fileIndex]
        let name = Self.htmlEscape(file.relativePath)
        let imageURL = "/file?uid=\(uid)&index=\(file.originalIndex)\(auth)"
        let allFilesURL = "/view?uid=\(uid)\(auth)\(viewOptions)"

        let previousHTML: String
        if page > 0 {
            previousHTML = #"<a class="nav" id="prev" data-prev href="/view?uid=\#(uid)&mode=book&page=\#(page - 1)\#(auth)\#(viewOptions)">Previous Page</a>"#
        } else if let previousJob = apiAdjacentViewJobIndex(from: jobIndex, direction: -1) {
            previousHTML = #"<a class="nav" id="prev" data-prev href="/view?uid=\#(jobs[previousJob].id.uuidString)&mode=book\#(auth)\#(preferenceOptions)">Previous Task</a>"#
        } else {
            previousHTML = #"<span class="nav disabled" id="prev">Previous Page</span>"#
        }

        let nextHTML: String
        if page + 1 < imageIndexes.count {
            nextHTML = #"<a class="nav" id="next" data-next href="/view?uid=\#(uid)&mode=book&page=\#(page + 1)\#(auth)\#(viewOptions)">Next Page</a>"#
        } else if let nextJob = apiAdjacentViewJobIndex(from: jobIndex, direction: 1) {
            nextHTML = #"<a class="nav" id="next" data-next href="/view?uid=\#(jobs[nextJob].id.uuidString)&mode=book\#(auth)\#(preferenceOptions)">Next Task</a>"#
        } else {
            nextHTML = #"<span class="nav disabled" id="next">Next Page</span>"#
        }

        return """
        <!doctype html>
        <html\(preferences.htmlDirectionAttribute)>
        <head>
          <meta charset="utf-8">
          <meta name="viewport" content="width=device-width, initial-scale=1">
          <title>\(title) - Reader</title>
          <style>
            body { margin: 0; \(preferences.bodyCSS) font: 13px \(Self.apiFontStack); }
            header { position: sticky; top: 0; z-index: 2; padding: 10px 14px; \(preferences.headerCSS) backdrop-filter: blur(10px); }
            h1 { font-size: 15px; margin: 0 0 3px; color: \(preferences.isDark ? "white" : "#202124"); }
            .meta { color: #bdc1c6; overflow-wrap: anywhere; }
            .toolbar { display: flex; flex-wrap: wrap; gap: 8px; align-items: center; margin-top: 9px; }
            .nav { display: inline-flex; min-height: 30px; align-items: center; padding: 0 10px; border-radius: 6px; \(preferences.navCSS) text-decoration: none; }
            .disabled { \(preferences.disabledCSS) }
            main { min-height: calc(100vh - 90px); display: grid; place-items: center; padding: 14px; box-sizing: border-box; }
            figure { margin: 0; width: 100%; }
            img { display: block; \(preferences.imageCSS) \(preferences.mediaMarginCSS) background: #050505; }
            figcaption { margin-top: 10px; color: #bdc1c6; text-align: center; overflow-wrap: anywhere; }
          </style>
        </head>
        <body class="view">
          <header>
            <h1>\(title)</h1>
            <div class="meta">Reader \(page + 1) / \(imageIndexes.count) - \(name)</div>
            <div class="toolbar">\(previousHTML)<a class="nav" href="\(allFilesURL)">All Files</a>\(nextHTML)</div>
          </header>
          <main>
            <figure>
              \(apiPageImage(src: imageURL, id: "page\(page)", alt: name, preferences: preferences))
              <figcaption>\(name)</figcaption>
            </figure>
          </main>
          \(Self.apiLegacyViewKeydownScript(preferences: preferences))
          <script>
            document.addEventListener('keydown', event => {
              if (event.key === '\(preferences.previousKey)') {
                const previous = document.querySelector('[data-prev]');
                if (previous) location.href = previous.href;
              }
              if (event.key === '\(preferences.nextKey)' || event.key === ' ') {
                const next = document.querySelector('[data-next]');
                if (next) location.href = next.href;
              }
              if (event.key === 'Escape') {
                location.href = \(Self.javascriptStringLiteral(allFilesURL));
              }
            });
            \(Self.apiWheelNavigationScript())
          </script>
        </body>
        </html>
        """
    }

    private func apiFileViewPage(job: DownloadJob, files: [APIOutputFile], selectedPosition: Int, auth: String, viewOptions: String, displayTitle: String, preferences: APIViewPreferences) -> String {
        let uid = job.id.uuidString
        let file = files[selectedPosition]
        let title = Self.htmlEscape(displayTitle)
        let name = Self.htmlEscape(file.relativePath)
        let fileURL = "/file?uid=\(uid)&index=\(file.originalIndex)\(auth)"
        let allFilesURL = "/view?uid=\(uid)\(auth)\(viewOptions)"
        let deleteFileURL = "/delete_file?uid=\(uid)&index=\(file.originalIndex)\(auth)"
        let previousHTML = selectedPosition > 0
            ? #"<a class="nav" id="prev" data-prev href="/view?uid=\#(uid)&index=\#(files[selectedPosition - 1].originalIndex)\#(auth)\#(viewOptions)">Previous File</a>"#
            : #"<span class="nav disabled" id="prev">Previous File</span>"#
        let nextHTML = selectedPosition + 1 < files.count
            ? #"<a class="nav" id="next" data-next href="/view?uid=\#(uid)&index=\#(files[selectedPosition + 1].originalIndex)\#(auth)\#(viewOptions)">Next File</a>"#
            : #"<span class="nav disabled" id="next">Next File</span>"#
        let ext = file.url.pathExtension.lowercased()
        let mediaHTML: String
        if Self.imageExtensions.contains(ext) {
            mediaHTML = #"<figure class="detail">\#(apiPageImage(src: fileURL, id: "page\(selectedPosition)", alt: name, preferences: preferences))<figcaption>\#(name)</figcaption></figure>"#
        } else if Self.videoExtensions.contains(ext) {
            mediaHTML = #"<figure class="detail"><video controls class="page" id="page\#(selectedPosition)" autoplay preload="metadata" src="\#(fileURL)"></video><figcaption>\#(name)</figcaption></figure>"#
        } else if Self.audioExtensions.contains(ext) {
            mediaHTML = #"<figure class="detail"><audio controls class="page" id="page\#(selectedPosition)" autoplay src="\#(fileURL)"></audio><figcaption>\#(name)</figcaption></figure>"#
        } else {
            mediaHTML = #"<p class="detail-file page" data-page-id="page\#(selectedPosition)"><a href="\#(fileURL)">\#(name)</a></p>"#
        }

        return """
        <!doctype html>
        <html\(preferences.htmlDirectionAttribute)>
        <head>
          <meta charset="utf-8">
          <meta name="viewport" content="width=device-width, initial-scale=1">
          <title>\(title) - \(name)</title>
          <style>
            body { margin: 0; \(preferences.bodyCSS) font: 13px \(Self.apiFontStack); }
            header { position: sticky; top: 0; z-index: 2; padding: 10px 14px; \(preferences.headerCSS) backdrop-filter: blur(10px); }
            h1 { font-size: 15px; margin: 0 0 3px; color: \(preferences.isDark ? "white" : "#202124"); }
            .meta { color: #bdc1c6; overflow-wrap: anywhere; }
            .toolbar { display: flex; flex-wrap: wrap; gap: 8px; align-items: center; margin-top: 9px; }
            .nav { display: inline-flex; min-height: 30px; align-items: center; padding: 0 10px; border-radius: 6px; \(preferences.navCSS) text-decoration: none; border: 0; cursor: pointer; font: inherit; }
            .danger { color: #ff8a80; }
            .disabled { \(preferences.disabledCSS) }
            main { min-height: calc(100vh - 90px); display: grid; place-items: center; padding: 14px; box-sizing: border-box; }
            figure { width: 100%; max-width: 1400px; margin: 0; }
            img, video { display: block; \(preferences.imageCSS) \(preferences.mediaMarginCSS) background: #050505; }
            audio { width: min(820px, 100%); }
            figcaption, .detail-file { margin: 10px 0 0; color: #bdc1c6; text-align: center; overflow-wrap: anywhere; }
            .detail-file a { color: white; }
          </style>
        </head>
        <body class="view">
          <header>
            <h1>\(title)</h1>
            <div class="meta">\(selectedPosition + 1) / \(files.count) · \(name)</div>
            <div class="toolbar">\(previousHTML)<a class="nav" href="\(allFilesURL)">All Files</a>\(nextHTML)<button class="nav danger" type="button" onclick="deleteCurrentFile()">Delete File</button></div>
          </header>
          <main>
            \(mediaHTML)
          </main>
          \(Self.apiLegacyViewKeydownScript(preferences: preferences))
          <script>
            document.addEventListener('keydown', event => {
              if (event.key === '\(preferences.previousKey)') {
                const previous = document.querySelector('[data-prev]');
                if (previous) location.href = previous.href;
              }
              if (event.key === '\(preferences.nextKey)' || event.key === ' ') {
                const next = document.querySelector('[data-next]');
                if (next) location.href = next.href;
              }
              if (event.key === 'Escape') {
                location.href = \(Self.javascriptStringLiteral(allFilesURL));
              }
            });
            \(Self.apiWheelNavigationScript())
            async function deleteCurrentFile() {
              if (!confirm('Delete this output file?')) return;
              const response = await fetch(\(Self.javascriptStringLiteral(deleteFileURL)), { method: 'POST' });
              if (response.ok) {
                location.href = \(Self.javascriptStringLiteral(allFilesURL));
              } else {
                alert(await response.text());
              }
            }
          </script>
        </body>
        </html>
        """
    }

    private func apiPageImage(src: String, id: String, alt: String, preferences: APIViewPreferences) -> String {
        if preferences.effectiveLazyLoading(defaultValue: httpViewerLazyLoading) {
            return #"<img class="page lazyload" src="/loading.gif" data-src="\#(src)" id="\#(id)" alt="\#(alt)">"#
        }
        return #"<img class="page" src="\#(src)" id="\#(id)" alt="\#(alt)">"#
    }

    private func apiFileResponse(_ request: LocalHTTPRequest) -> LocalHTTPResponse {
        guard let file = apiRequestedFile(from: request) else {
            return LocalHTTPResponse.jsonObject(["error": "File not found"], status: 404)
        }

        do {
            let parameters = apiParameters(from: request)
            let contentType = Self.mimeType(for: file.url)
            let requestedFilename = Self.apiFirstParameterValue(in: parameters, keys: ["filename", "download_name", "downloadname", "name"])
            let filename = (requestedFilename ?? Self.apiOutputDisplayName(file)).sanitizedFilename(maxLength: 180)
            let size = apiOutputFileSize(file)
            let modifiedAt = apiOutputFileModifiedDate(file)
            let etag = Self.apiOutputFileETag(file, size: size, modifiedAt: modifiedAt)
            var headers = [
                "Accept-Ranges": "bytes",
                "Content-Disposition": Self.apiContentDisposition(
                    apiFileDisposition(for: request, parameters: parameters),
                    filename: filename
                ),
                "ETag": etag,
                "X-Content-Type-Options": "nosniff"
            ]
            if let modifiedAt {
                headers["Last-Modified"] = Self.apiHTTPHeaderDateString(modifiedAt)
            }

            if Self.apiFileNotModified(request, etag: etag, modifiedAt: modifiedAt) {
                return LocalHTTPResponse.data(Data(), contentType: contentType, status: 304, headers: headers)
            }

            if request.method == "HEAD" {
                switch Self.byteRange(from: request.headers["range"], size: size) {
                case .valid(let range):
                    var partialHeaders = headers
                    partialHeaders["Content-Range"] = "bytes \(range.lowerBound)-\(range.upperBound - 1)/\(size)"
                    partialHeaders["Content-Length"] = String(range.count)
                    return LocalHTTPResponse.data(Data(), contentType: contentType, status: 206, headers: partialHeaders)
                case .invalid:
                    var invalidHeaders = headers
                    invalidHeaders["Content-Range"] = "bytes */\(size)"
                    invalidHeaders["Content-Length"] = "0"
                    return LocalHTTPResponse.data(Data(), contentType: "text/plain; charset=utf-8", status: 416, headers: invalidHeaders)
                case .none:
                    headers["Content-Length"] = String(size)
                    return LocalHTTPResponse.data(Data(), contentType: contentType, headers: headers)
                }
            }

            let data = try apiOutputFileData(file)
            switch Self.byteRange(from: request.headers["range"], size: data.count) {
            case .valid(let range):
                let sliced = data.subdata(in: range)
                var partialHeaders = headers
                partialHeaders["Content-Range"] = "bytes \(range.lowerBound)-\(range.upperBound - 1)/\(data.count)"
                return LocalHTTPResponse.data(sliced, contentType: contentType, status: 206, headers: partialHeaders)
            case .invalid:
                var invalidHeaders = headers
                invalidHeaders["Content-Range"] = "bytes */\(data.count)"
                return LocalHTTPResponse.data(
                    Data("Requested Range Not Satisfiable".utf8),
                    contentType: "text/plain; charset=utf-8",
                    status: 416,
                    headers: invalidHeaders
                )
            case .none:
                break
            }

            return LocalHTTPResponse.data(data, contentType: contentType, headers: headers)
        } catch {
            return LocalHTTPResponse.jsonObject(["error": "File could not be read"], status: 404)
        }
    }

    private func apiFileDisposition(for request: LocalHTTPRequest, parameters: [String: String]) -> String {
        if let disposition = Self.apiFirstParameterValue(in: parameters, keys: ["disposition", "content_disposition", "contentdisposition"])?.lowercased() {
            if ["attachment", "download", "save"].contains(disposition) {
                return "attachment"
            }
            if ["inline", "view", "preview"].contains(disposition) {
                return "inline"
            }
        }
        if Self.apiTruthy(parameters["inline"]) {
            return "inline"
        }
        if Self.apiTruthy(parameters["download"]) ||
            Self.apiTruthy(parameters["attachment"]) ||
            Self.apiTruthy(parameters["save"]) {
            return "attachment"
        }
        return request.path.lowercased().contains("download_file") ? "attachment" : "inline"
    }

    private static func apiContentDisposition(_ disposition: String, filename: String) -> String {
        let mode = disposition == "attachment" ? "attachment" : "inline"
        let fallback = apiContentDispositionFallbackFilename(filename)
        let encoded = apiRFC5987Encode(filename)
        return "\(mode); filename=\"\(fallback)\"; filename*=UTF-8''\(encoded)"
    }

    private static func apiContentDispositionFallbackFilename(_ filename: String) -> String {
        let safe = filename.sanitizedFilename(maxLength: 180)
        let ascii = String(safe.unicodeScalars.map { scalar -> Character in
            if scalar.value >= 0x20,
               scalar.value < 0x7f,
               scalar.value != 0x22,
               scalar.value != 0x5c {
                return Character(scalar)
            }
            return "_"
        })
        let fallback = ascii.trimmed
        return fallback.isEmpty ? "download" : fallback
    }

    private static func apiRFC5987Encode(_ value: String) -> String {
        let allowed = Set("ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789!#$&+-.^_`|~".utf8)
        return value.utf8.map { byte in
            if allowed.contains(byte) {
                return String(UnicodeScalar(Int(byte))!)
            }
            return String(format: "%%%02X", byte)
        }.joined()
    }

    private static func apiHTTPHeaderDateString(_ date: Date) -> String {
        let formatter = DateFormatter()
        formatter.locale = Locale(identifier: "en_US_POSIX")
        formatter.timeZone = TimeZone(secondsFromGMT: 0)
        formatter.dateFormat = "EEE, dd MMM yyyy HH:mm:ss 'GMT'"
        return formatter.string(from: date)
    }

    private static func apiHTTPHeaderDate(from value: String?) -> Date? {
        guard let value = value?.trimmed, !value.isEmpty else { return nil }
        let formats = [
            "EEE, dd MMM yyyy HH:mm:ss zzz",
            "EEEE, dd-MMM-yy HH:mm:ss zzz",
            "EEE MMM d HH:mm:ss yyyy"
        ]
        for format in formats {
            let formatter = DateFormatter()
            formatter.locale = Locale(identifier: "en_US_POSIX")
            formatter.timeZone = TimeZone(secondsFromGMT: 0)
            formatter.dateFormat = format
            if let date = formatter.date(from: value) {
                return date
            }
        }
        return nil
    }

    private static func apiFileNotModified(_ request: LocalHTTPRequest, etag: String, modifiedAt: Date?) -> Bool {
        if let value = request.headers["if-none-match"]?.trimmed, !value.isEmpty {
            return apiETagHeader(value, matches: etag)
        }
        guard let modifiedAt,
              let since = apiHTTPHeaderDate(from: request.headers["if-modified-since"]) else {
            return false
        }
        return modifiedAt.timeIntervalSince1970.rounded(.down) <= since.timeIntervalSince1970.rounded(.down)
    }

    private static func apiETagHeader(_ value: String, matches etag: String) -> Bool {
        value
            .split(separator: ",")
            .map { $0.trimmingCharacters(in: .whitespacesAndNewlines) }
            .contains { candidate in
                candidate == "*" ||
                    candidate == etag ||
                    candidate.replacingOccurrences(of: "W/", with: "") == etag.replacingOccurrences(of: "W/", with: "")
            }
    }

    private static func apiOutputFileETag(_ file: APIOutputFile, size: Int, modifiedAt: Date?) -> String {
        let modified = Int64((modifiedAt?.timeIntervalSince1970 ?? 0).rounded(.down))
        let identity: String
        if let entry = file.archiveEntry {
            identity = [
                file.archiveURL?.path ?? "",
                file.relativePath,
                String(entry.crc32),
                String(entry.compressedSize),
                String(entry.uncompressedSize),
                String(entry.localHeaderOffset)
            ].joined(separator: "|")
        } else {
            identity = [
                file.url.path,
                file.relativePath
            ].joined(separator: "|")
        }
        let hash = apiFNV1a64("\(identity)|\(size)|\(modified)")
        return String(format: #"W/"%016llx""#, hash)
    }

    private static func apiFNV1a64(_ value: String) -> UInt64 {
        var hash: UInt64 = 0xcbf29ce484222325
        for byte in value.utf8 {
            hash ^= UInt64(byte)
            hash = hash &* 0x100000001b3
        }
        return hash
    }

    private func apiThumbResponse(_ request: LocalHTTPRequest) async -> LocalHTTPResponse {
        let files = apiJob(from: request).map(apiOutputFiles(for:)) ?? []
        let requested = (apiFileIndexText(from: request) != nil) ? apiRequestedFile(from: request) : nil
        let selected = requested ?? files.first { Self.imageExtensions.contains($0.url.pathExtension.lowercased()) } ?? files.first
        guard let selected else {
            return apiPlaceholderThumb(title: "No files")
        }

        let ext = selected.url.pathExtension.lowercased()
        if Self.imageExtensions.contains(ext),
           let data = try? apiOutputFileData(selected) {
            return LocalHTTPResponse.data(data, contentType: Self.mimeType(for: selected.url))
        }

        if selected.archiveEntry == nil,
           Self.videoExtensions.contains(ext),
           let data = await apiVideoThumbnailData(for: selected) {
            return LocalHTTPResponse.data(
                data,
                contentType: "image/jpeg",
                headers: ["Cache-Control": "private, max-age=3600"]
            )
        }

        return apiPlaceholderThumb(title: selected.relativePath)
    }

    private func apiVideoThumbnailData(for file: APIOutputFile) async -> Data? {
        let key = apiVideoThumbnailCacheKey(for: file.url)
        let values = try? file.url.resourceValues(forKeys: [.fileSizeKey, .contentModificationDateKey])
        let fileSize = values?.fileSize
        let modifiedAt = values?.contentModificationDate

        if let cached = apiVideoThumbnailCache[key],
           cached.matches(fileSize: fileSize, modifiedAt: modifiedAt) {
            return cached.data
        }

        guard let data = await MediaFileMetadataReader.thumbnailJPEGData(for: file.url) else {
            apiVideoThumbnailCache.removeValue(forKey: key)
            return nil
        }

        apiVideoThumbnailCache[key] = APIVideoThumbnailCacheEntry(
            fileSize: fileSize,
            modifiedAt: modifiedAt,
            data: data
        )
        pruneAPIVideoThumbnailCache(keeping: key)
        return data
    }

    private func pruneAPIVideoThumbnailCache(keeping key: String) {
        let maximumCachedVideoThumbnails = 128
        guard apiVideoThumbnailCache.count > maximumCachedVideoThumbnails else { return }
        let removableKeys = apiVideoThumbnailCache.keys.filter { $0 != key }
        for removable in removableKeys.prefix(apiVideoThumbnailCache.count - maximumCachedVideoThumbnails) {
            apiVideoThumbnailCache.removeValue(forKey: removable)
        }
    }

    private func apiVideoThumbnailCacheKey(for url: URL) -> String {
        url.standardizedFileURL.path
    }

    private func apiStaticAssetResponse(_ request: LocalHTTPRequest) -> LocalHTTPResponse {
        let lower = request.path.lowercased()
        switch lower {
        case "/loading.gif":
            let data = Data(base64Encoded: "R0lGODlhAQABAIAAAAAAAP///ywAAAAAAQABAAACAUwAOw==") ?? Data()
            return LocalHTTPResponse.data(data, contentType: "image/gif", headers: ["Cache-Control": "public, max-age=86400"])
        case "/favicon.ico":
            return apiIconAsset(name: "hitomi-native", color: request.query["color"])
        case "/materialize.css":
            return LocalHTTPResponse.text(apiMaterializeCSS(), contentType: "text/css; charset=utf-8")
        case "/hitomi.css":
            return LocalHTTPResponse.text(apiHitomiCSS(), contentType: "text/css; charset=utf-8")
        case "/materialize.js":
            return LocalHTTPResponse.text(apiMaterializeJSStub(), contentType: "application/javascript; charset=utf-8")
        case "/jquery.js":
            return LocalHTTPResponse.text(apiJQueryStub(), contentType: "application/javascript; charset=utf-8")
        case "/lazysizes.js":
            return LocalHTTPResponse.text(apiLazySizesStub(), contentType: "application/javascript; charset=utf-8")
        default:
            guard lower.hasPrefix("/icon/") else {
                return LocalHTTPResponse.jsonObject(["error": "Not found"], status: 404)
            }
            let rawName = String(request.path.dropFirst("/icon/".count))
            return apiIconAsset(name: rawName, color: request.query["color"])
        }
    }

    private func apiIconAsset(name rawName: String, color rawColor: String?) -> LocalHTTPResponse {
        let name = rawName
            .split(separator: "/", omittingEmptySubsequences: true)
            .joined(separator: "-")
            .replacingOccurrences(of: "[^A-Za-z0-9_-]", with: "", options: .regularExpression)
        let iconName = name.isEmpty ? "item" : name
        let color = Self.apiIconColor(rawColor)
        let label = Self.apiIconLabel(iconName)
        let svg = """
        <svg xmlns="http://www.w3.org/2000/svg" width="64" height="64" viewBox="0 0 64 64" role="img" aria-label="\(Self.htmlEscape(iconName))">
          <rect width="64" height="64" rx="14" fill="\(color)"/>
          <circle cx="32" cy="32" r="20" fill="rgba(255,255,255,.16)"/>
          <text x="32" y="39" text-anchor="middle" font-family="\(Self.apiSVGFontStack)" font-size="18" font-weight="700" fill="#fff">\(Self.htmlEscape(label))</text>
        </svg>
        """
        return LocalHTTPResponse.data(Data(svg.utf8), contentType: "image/svg+xml; charset=utf-8", headers: ["Cache-Control": "public, max-age=86400"])
    }

