    private func apiAdjacentViewJobIndex(from index: Int, direction: Int) -> Int? {
        guard direction != 0 else { return nil }
        let orderedIndices = queueOrderedJobIndices
        guard let logicalIndex = orderedIndices.firstIndex(of: index) else { return nil }
        var candidate = logicalIndex + direction
        while orderedIndices.indices.contains(candidate) {
            let physicalIndex = orderedIndices[candidate]
            if !apiOutputFiles(for: jobs[physicalIndex]).isEmpty {
                return physicalIndex
            }
            candidate += direction
        }
        return nil
    }

    private func apiCommentResponse(_ request: LocalHTTPRequest) -> LocalHTTPResponse {
        guard let jobIndex = apiJobIndex(from: request) else {
            return LocalHTTPResponse.jsonObject(["error": "Task not found"], status: 404)
        }

        let parameters = apiParameters(from: request)
        let comment = (parameters["comment"] ?? parameters["text"] ?? parameters["value"] ?? request.bodyText).trimmed
        jobs[jobIndex].comment = comment
        if jobs[jobIndex].status == .finished {
            scheduleRestartIfNeeded(for: jobs[jobIndex])
        } else {
            cancelScheduledRestart(for: jobs[jobIndex].id)
        }
        persistQueue()
        return LocalHTTPResponse.jsonObject([
            "updated": true,
            "id": jobs[jobIndex].id.uuidString,
            "comment": jobs[jobIndex].comment
        ])
    }

    private func apiExecResponse(_ request: LocalHTTPRequest) async -> LocalHTTPResponse {
        let parameters = apiParameters(from: request)
        guard let action = apiExecAction(from: parameters) else {
            return LocalHTTPResponse.jsonObject([
                "error": "Missing action",
                "acceptedKeys": ["action", "command", "cmd", "f", "function", "name"],
                "supported": Self.apiExecSupportedActions
            ], status: 400)
        }

        switch action {
        case "start":
            startQueue(addingInput: false)
            return LocalHTTPResponse.jsonObject([
                "ok": true,
                "action": "start",
                "running": isRunning,
                "count": jobs.count
            ])
        case "stop":
            cancelQueue()
            return LocalHTTPResponse.jsonObject([
                "ok": true,
                "action": "stop",
                "running": isRunning,
                "count": jobs.count
            ])
        case "save":
            persistQueue()
            persistHTTPAPISettings()
            return LocalHTTPResponse.jsonObject([
                "ok": true,
                "action": "save",
                "res": "saved",
                "err": "",
                "saved": true,
                "count": jobs.count,
                "status": httpAPIStatus
            ])
        case "clear":
            let removed = clearFinished()
            return LocalHTTPResponse.jsonObject([
                "ok": true,
                "action": "clear",
                "removed": removed,
                "removedCount": removed,
                "count": jobs.count,
                "running": isRunning
            ])
        case "complete":
            return apiCompleteResponse(request)
        case "pdf":
            return apiPDFResponse(request)
        case "archive":
            return apiArchiveResponse(request)
        case "comment":
            return apiCommentResponse(request)
        case "remove":
            return apiRemoveResponse(request)
        case "delete":
            return apiDeleteResponse(request)
        case "pause":
            return apiAria2RuntimeControlResponse(request, pause: true)
        case "resume":
            return apiAria2RuntimeControlResponse(request, pause: false)
        case "aria2_limits":
            return await apiAria2RuntimeLimitsResponse(request)
        case "aria2_files":
            return await apiAria2RuntimeFileSelectionResponse(request)
        case "aria2_seed":
            return await apiAria2RuntimeSeedingResponse(request)
        case "aria2_file_list":
            return await apiAria2FileListResponse(request)
        case "aria2_peers":
            return await apiAria2PeersResponse(request)
        case "update_cookies":
            return await apiUpdateCookiesResponse(request)
        case "download":
            let items = apiInputItems(from: request)
            guard !items.isEmpty else {
                return LocalHTTPResponse.jsonObject(["error": "Missing url"], status: 400)
            }
            let added = enqueueInputItems(items)
            let shouldStart = (parameters["start"] ?? parameters["run"] ?? "1") != "0"
            if shouldStart {
                startQueue(addingInput: false)
            }
            let message = "\(added) URL\(added == 1 ? "" : "s") added"
            return LocalHTTPResponse.jsonObject([
                "ok": added > 0,
                "action": "download",
                "res": apiUsesOriginalActionShape(request) ? "ok" : message,
                "message": message,
                "added": added,
                "total": jobs.count,
                "running": isRunning
            ])
        default:
            return LocalHTTPResponse.jsonObject([
                "error": "Unsupported action",
                "action": action,
                "supported": Self.apiExecSupportedActions
            ], status: 400)
        }
    }

    private func apiExecAction(from parameters: [String: String]) -> String? {
        let raw = [
            parameters["action"],
            parameters["command"],
            parameters["cmd"],
            parameters["f"],
            parameters["function"],
            parameters["name"]
        ]
            .compactMap { $0?.trimmed }
            .first { !$0.isEmpty } ?? ""
        guard !raw.isEmpty else { return nil }

        let normalized = raw
            .lowercased()
            .replacingOccurrences(of: "-", with: "_")
            .replacingOccurrences(of: " ", with: "_")
            .replacingOccurrences(of: ".", with: "_")
        switch normalized {
        case "start", "run", "resume_queue", "start_queue":
            return "start"
        case "stop", "cancel", "abort", "stop_queue", "cancel_queue":
            return "stop"
        case "save", "persist":
            return "save"
        case "clear", "clear_finished", "clear_done", "clear_completed":
            return "clear"
        case "complete", "finish", "done", "mark_finished", "manual_complete":
            return "complete"
        case "pdf", "create_pdf", "createpdf", "pdf_converter", "pdfconverter", "convert_pdf", "convertpdf", "make_pdf", "makepdf", "to_pdf", "topdf":
            return "pdf"
        case "zip", "create_zip", "createzip", "make_zip", "makezip", "archive", "create_archive", "createarchive", "pack", "package", "cbz", "create_cbz", "createcbz":
            return "archive"
        case "comment", "memo", "note", "set_comment":
            return "comment"
        case "remove", "remove_task", "remove_tasks":
            return "remove"
        case "delete", "delete_task", "delete_tasks", "delete_output":
            return "delete"
        case "pause", "pause_task", "pause_tasks":
            return "pause"
        case "resume", "resume_task", "resume_tasks":
            return "resume"
        case "aria2_limits", "aria2_limit", "limits", "limit", "speed", "speed_limit", "set_speed", "set_limit":
            return "aria2_limits"
        case "aria2_files", "aria2_file", "aria2_select", "select_file", "select_files", "files", "file_priority", "priority", "set_files":
            return "aria2_files"
        case "aria2_seed", "aria2_seeding", "seed", "seeding", "set_seed", "set_seed_time", "set_seedings", "setseedings":
            return "aria2_seed"
        case "aria2_file_list", "aria2_files_list", "show_files", "showfiles", "list_files", "list_torrent_files", "torrent_files":
            return "aria2_file_list"
        case "aria2_peers", "aria2_peer", "peers", "peer", "show_peers", "show_peer":
            return "aria2_peers"
        case "update_cookies", "cookies", "cookie", "set_cookies":
            return "update_cookies"
        case "download", "add", "add_url", "add_urls", "enqueue":
            return "download"
        default:
            return normalized
        }
    }

    private nonisolated static let apiExecSupportedActions = [
        "start",
        "stop",
        "save",
        "clear",
        "complete",
        "pdf",
        "archive",
        "comment",
        "remove",
        "delete",
        "pause",
        "resume",
        "aria2_limits",
        "aria2_files",
        "aria2_seed",
        "aria2_file_list",
        "aria2_peers",
        "update_cookies",
        "download"
    ]

    private func apiAria2RuntimeControlResponse(_ request: LocalHTTPRequest, pause: Bool) -> LocalHTTPResponse {
        let indexes = apiJobIndexes(from: request)
        guard !indexes.isEmpty else {
            return LocalHTTPResponse.jsonObject(["error": "Task not found"], status: 404)
        }

        var ids: [String] = []
        var skipped = 0
        for index in indexes {
            let changed = pause
                ? pauseAria2Job(at: index, persist: false)
                : resumeAria2Job(at: index, persist: false)
            if changed {
                ids.append(jobs[index].id.uuidString)
            } else {
                skipped += 1
            }
        }

        if !ids.isEmpty {
            persistQueue()
        }

        let key = pause ? "paused" : "resumed"
        return LocalHTTPResponse.jsonObject([
            key: !ids.isEmpty,
            "\(key)Count": ids.count,
            "skippedCount": skipped,
            "id": ids.first ?? "",
            "ids": ids,
            "count": jobs.count
        ])
    }

    private func apiAria2RuntimeLimitsResponse(_ request: LocalHTTPRequest) async -> LocalHTTPResponse {
        let indexes = apiJobIndexes(from: request)
        guard !indexes.isEmpty else {
            return LocalHTTPResponse.jsonObject(["error": "Task not found"], status: 404)
        }

        let parameters = apiParameters(from: request)
        let downloadLimit = parameters["down"] ??
            parameters["download"] ??
            parameters["download_limit"] ??
            parameters["max_download_limit"] ??
            aria2MaxDownloadLimit
        let uploadLimit = parameters["up"] ??
            parameters["upload"] ??
            parameters["upload_limit"] ??
            parameters["max_upload_limit"] ??
            aria2MaxUploadLimit

        var ids: [String] = []
        var skipped = 0
        let targetIDs = indexes.compactMap { jobs.indices.contains($0) ? jobs[$0].id : nil }
        for jobID in targetIDs {
            guard let index = jobs.firstIndex(where: { $0.id == jobID }) else {
                skipped += 1
                continue
            }
            if await applyAria2RuntimeLimitsJob(at: index, downloadLimit: downloadLimit, uploadLimit: uploadLimit, persist: false) {
                ids.append(jobID.uuidString)
            } else {
                skipped += 1
            }
        }

        if !ids.isEmpty {
            persistQueue()
        }

        let normalizedDownload = Aria2Options.normalizedLimit(downloadLimit)
        let normalizedUpload = Aria2Options.normalizedLimit(uploadLimit)
        return LocalHTTPResponse.jsonObject([
            "updated": !ids.isEmpty,
            "updatedCount": ids.count,
            "skippedCount": skipped,
            "id": ids.first ?? "",
            "ids": ids,
            "down": normalizedDownload,
            "up": normalizedUpload,
            "maxDownloadLimit": normalizedDownload,
            "maxUploadLimit": normalizedUpload,
            "count": jobs.count
        ])
    }

