    private func apiAria2FileListResponse(_ request: LocalHTTPRequest) async -> LocalHTTPResponse {
        let indexes = apiJobIndexes(from: request)
        guard !indexes.isEmpty else {
            return LocalHTTPResponse.jsonObject(["error": "Task not found"], status: 404)
        }

        var ids: [String] = []
        var allFiles: [[String: Any]] = []
        var fileGroups: [[String: Any]] = []
        var skipped = 0
        let targetIDs = indexes.compactMap { jobs.indices.contains($0) ? jobs[$0].id : nil }
        for jobID in targetIDs {
            guard let index = jobs.firstIndex(where: { $0.id == jobID }) else {
                skipped += 1
                continue
            }
            guard let entries = await loadAria2FileEntriesJob(at: index) else {
                skipped += 1
                continue
            }
            let objects = entries.map(Self.apiAria2FileEntryObject)
            ids.append(jobID.uuidString)
            allFiles.append(contentsOf: objects)
            fileGroups.append([
                "id": jobID.uuidString,
                "fileCount": objects.count,
                "files": objects
            ])
        }

        return LocalHTTPResponse.jsonObject([
            "ok": !ids.isEmpty,
            "updated": !ids.isEmpty,
            "id": ids.first ?? "",
            "ids": ids,
            "fileCount": allFiles.count,
            "files": allFiles,
            "items": allFiles,
            "fileGroups": fileGroups,
            "skippedCount": skipped,
            "summary": aria2FileListSummary,
            "count": jobs.count
        ])
    }

    private nonisolated static func apiAria2FileEntryObject(_ entry: Aria2FileEntry) -> [String: Any] {
        [
            "index": entry.index,
            "path": entry.path,
            "length": entry.length,
            "selected": entry.selected.map { $0 as Any } ?? NSNull(),
            "summary": entry.length.isEmpty ? "\(entry.index): \(entry.path)" : "\(entry.index): \(entry.path) (\(entry.length))"
        ]
    }

