            "id": ids.first ?? "",
            "ids": ids,
            "peerCount": allPeers.count,
            "peers": allPeers,
            "items": allPeers,
            "peerGroups": peerGroups,
            "skippedCount": skipped,
            "count": jobs.count
        ])
    }

    private nonisolated static func apiAria2PeerObject(_ peer: Aria2PeerEntry) -> [String: Any] {
        [
            "id": peer.id,
            "peerId": peer.peerID,
            "ip": peer.ip,
            "port": peer.port,
            "endpoint": peer.endpoint,
            "downloadSpeed": peer.downloadSpeed,
            "uploadSpeed": peer.uploadSpeed,
            "seeder": peer.seeder,
            "amChoking": peer.amChoking,
            "peerChoking": peer.peerChoking,
            "summary": peer.summary
        ]
    }

    private func apiCompleteResponse(_ request: LocalHTTPRequest) -> LocalHTTPResponse {
        let indexes = apiJobIndexes(from: request)
        guard !indexes.isEmpty else {
            return LocalHTTPResponse.jsonObject(["error": "Task not found"], status: 404)
        }
        guard indexes.allSatisfy({ canMarkJobFinished(at: $0) }) else {
            return LocalHTTPResponse.jsonObject(["error": "Active task cannot be marked finished"], status: 400)
        }

        var ids: [String] = []
        for index in indexes {
            if markJobFinished(at: index) {
                ids.append(jobs[index].id.uuidString)
            }
        }
        return LocalHTTPResponse.jsonObject([
            "completed": !ids.isEmpty,
            "completedCount": ids.count,
            "id": ids.first ?? "",
            "ids": ids,
            "count": jobs.count
        ])
    }

    private func apiRemoveResponse(_ request: LocalHTTPRequest) -> LocalHTTPResponse {
        let indexes = apiJobIndexes(from: request)
        guard !indexes.isEmpty else {
            return LocalHTTPResponse.jsonObject(["error": "Task not found"], status: 404)
        }
        let selected = indexes.map { jobs[$0] }
        guard selected.allSatisfy({ !$0.isLocked }) else {
            return LocalHTTPResponse.jsonObject(["error": "Locked task cannot be removed"], status: 400)
        }

        let cancelledCount = selected.filter {
            isActive($0.status) ||
                processingJobIDs.contains($0.id) ||
                runningJobTasks[$0.id] != nil
        }.count
        let removedIDs = selected.map { $0.id.uuidString }
        let removedCount = removeJobsFromQueue(selected)
        let message = "\(removedIDs.count) task\(removedIDs.count == 1 ? "" : "s") removed"
        addSummary = cancelledCount > 0
            ? "\(message); \(cancelledCount) active transfer\(cancelledCount == 1 ? "" : "s") cancelled"
            : message
        return LocalHTTPResponse.jsonObject([
            "ok": removedCount > 0,
            "res": apiUsesOriginalActionShape(request) ? "ok" : message,
            "message": message,
            "removed": removedCount > 0,
            "removedCount": removedCount,
            "cancelledCount": cancelledCount,
            "id": removedIDs.first ?? "",
            "ids": removedIDs,
            "count": visibleQueueOrderedJobs.count
        ])
    }

    private func apiDeleteResponse(_ request: LocalHTTPRequest) -> LocalHTTPResponse {
        let indexes = apiJobIndexes(from: request)
        guard !indexes.isEmpty else {
            return LocalHTTPResponse.jsonObject(["error": "Task not found"], status: 404)
        }
        let selected = indexes.map { jobs[$0] }
        guard selected.allSatisfy({ !$0.isLocked }) else {
            return LocalHTTPResponse.jsonObject(["error": "Locked task cannot be deleted"], status: 400)
        }

        let cancelledCount = selected.filter {
            isActive($0.status) ||
                processingJobIDs.contains($0.id) ||
                runningJobTasks[$0.id] != nil
        }.count
        let ids = selected.map { $0.id.uuidString }
        let result = trashOutputsAndRemoveJobs(withIDs: selected.map(\.id))
        let deletionPending = selected.contains { selectedJob in
            jobs.first(where: { $0.id == selectedJob.id }).map {
                Self.isPendingQueueOutputDeletion($0)
            } == true
        }
        let deleteAccepted = result.removedJobCount > 0 && result.failedItemCount == 0
        let message = deletionPending
            ? "\(result.removedJobCount) task\(result.removedJobCount == 1 ? "" : "s") removed; active output cleanup pending"
            : "\(result.removedJobCount) task\(result.removedJobCount == 1 ? "" : "s") removed, \(result.trashedItemCount) output\(result.trashedItemCount == 1 ? "" : "s") moved to Trash"
        addSummary = message
        return LocalHTTPResponse.jsonObject([
            "ok": deleteAccepted,
            "res": apiUsesOriginalActionShape(request) ? "ok" : message,
            "message": message,
            "deleted": result.trashedItemCount > 0 || deletionPending,
            "deleteAccepted": deleteAccepted,
            "removed": result.removedJobCount > 0,
            "deletedCount": result.trashedItemCount,
            "removedCount": result.removedJobCount,
            "cancelledCount": cancelledCount,
            "failedCount": result.failedItemCount,
            "keptCount": result.keptJobCount,
            "deletionPending": deletionPending,
            "id": ids.first ?? "",
            "ids": ids,
            "count": visibleQueueOrderedJobs.count
        ])
    }

    private func apiDeleteFileResponse(_ request: LocalHTTPRequest) -> LocalHTTPResponse {
        guard let jobIndex = apiJobIndex(from: request) else {
            return LocalHTTPResponse.jsonObject(["error": "Task not found"], status: 404)
        }
        guard !isActive(jobs[jobIndex].status) else {
            return LocalHTTPResponse.jsonObject(["error": "Active task file cannot be deleted"], status: 400)
        }
        guard !jobs[jobIndex].isLocked else {
            return LocalHTTPResponse.jsonObject(["error": "Locked task file cannot be deleted"], status: 400)
        }
        guard let file = apiRequestedFile(from: request) else {
            return LocalHTTPResponse.jsonObject(["error": "File not found"], status: 404)
        }
        guard file.archiveEntry == nil else {
            return LocalHTTPResponse.jsonObject(["error": "Archive entries cannot be deleted"], status: 400)
        }

        do {
            let path = file.url.path
            try FileManager.default.removeItem(at: file.url)
            let remaining = apiOutputFiles(for: jobs[jobIndex]).count
            persistQueue()
            return LocalHTTPResponse.jsonObject([
                "deleted": true,
                "uid": jobs[jobIndex].id.uuidString,
                "index": file.originalIndex,
                "path": path,
                "relativePath": file.relativePath,
                "remainingFileCount": remaining
            ])
        } catch {
            return LocalHTTPResponse.jsonObject(["error": error.localizedDescription], status: 400)
        }
    }

    private func deleteOutput(for job: DownloadJob) throws -> Bool {
        let path = job.outputPath.trimmed
        guard !path.isEmpty else { return false }

        let output = URL(fileURLWithPath: path).resolvingSymlinksInPath()
        var isDirectory: ObjCBool = false
        guard FileManager.default.fileExists(atPath: output.path, isDirectory: &isDirectory) else {
            return false
        }

        try FileManager.default.removeItem(at: output)
        return true
    }

    private func apiRequestedFile(from request: LocalHTTPRequest) -> APIOutputFile? {
        guard let job = apiJob(from: request) else { return nil }
        let files = apiOutputFiles(for: job)
        guard !files.isEmpty else { return nil }
        let index = Int(apiFileIndexText(from: request) ?? "0") ?? 0
        guard files.indices.contains(index) else { return nil }
        return files[index]
    }

    private func apiJobIndex(from request: LocalHTTPRequest) -> Int? {
        apiJobIndexes(from: request).first
    }

    private func apiJobIndexes(from request: LocalHTTPRequest) -> [Int] {
        let parameters = apiParameters(from: request)
        if let uids = parameters["uids"] {
            var indexes: [Int] = []
            var seen = Set<Int>()
            for token in apiListValues(from: uids) {
                guard let index = apiJobIndex(fromToken: token), !seen.contains(index) else { continue }
                indexes.append(index)
                seen.insert(index)
            }
            return indexes
        }

        if let uid = parameters["uid"] ?? parameters["id"] {
            return apiJobIndex(fromToken: uid).map { [$0] } ?? []
        }

        if let indexToken = parameters["job"],
           let index = Int(indexToken),
           let physicalIndex = queuePhysicalIndex(forLogicalIndex: index) {
            return [physicalIndex]
        }

        if apiAllowsJobIndexAlias(request),
           let indexToken = parameters["index"],
           let index = Int(indexToken),
           let physicalIndex = queuePhysicalIndex(forLogicalIndex: index) {
            return [physicalIndex]
        }

        return []
    }

    private func apiAllowsJobIndexAlias(_ request: LocalHTTPRequest) -> Bool {
        switch request.path.lowercased() {
        case "/file", "/api/file", "/delete_file", "/api/delete_file":
            return false
        default:
            return true
        }
    }

    private func apiJobIndex(fromToken token: String) -> Int? {
        let value = token.trimmed
        guard !value.isEmpty else { return nil }
        if let uuid = UUID(uuidString: value),
           let index = jobs.firstIndex(where: {
               $0.id == uuid && !Self.isPendingQueueRemoval($0)
           }) {
            return index
        }
        if let index = Int(value) {
            return queuePhysicalIndex(forLogicalIndex: index)
        }
        return nil
    }

    private func queuePhysicalIndex(forLogicalIndex index: Int) -> Int? {
        let orderedIndices = visibleQueueOrderedJobIndices
        guard orderedIndices.indices.contains(index) else { return nil }
        return orderedIndices[index]
    }

    private func apiJob(from request: LocalHTTPRequest) -> DownloadJob? {
        apiJobIndex(from: request).map { jobs[$0] }
    }

    private func apiOutputFiles(for job: DownloadJob) -> [APIOutputFile] {
        guard !job.outputPath.trimmed.isEmpty else { return [] }
        let root = URL(fileURLWithPath: job.outputPath)
        let manager = FileManager.default
        var isDirectory: ObjCBool = false
        guard manager.fileExists(atPath: root.path, isDirectory: &isDirectory) else { return [] }

        let rootResolved = root.resolvingSymlinksInPath()
        if !isDirectory.boolValue {
            if Self.isArchiveOutputFile(rootResolved),
               let archiveFiles = apiArchiveOutputFiles(for: rootResolved),
               !archiveFiles.isEmpty {
                return archiveFiles
            }
            guard isReadableOutputFile(rootResolved, under: rootResolved) else { return [] }
            return [APIOutputFile(url: rootResolved, relativePath: root.lastPathComponent, originalIndex: 0)]
        }

        guard let enumerator = manager.enumerator(
            at: root,
            includingPropertiesForKeys: [.isRegularFileKey],
            options: [.skipsHiddenFiles]
        ) else {
            return []
        }

        let rootPrefix = rootResolved.path.hasSuffix("/") ? rootResolved.path : rootResolved.path + "/"
        var files: [APIOutputFile] = []
        for case let file as URL in enumerator {
            let resolved = file.resolvingSymlinksInPath()
            guard isReadableOutputFile(resolved, under: rootResolved),
                  resolved.path.hasPrefix(rootPrefix) else {
                continue
            }
            let relative = String(resolved.path.dropFirst(rootPrefix.count))
            files.append(APIOutputFile(url: resolved, relativePath: relative))
        }

        return files
            .sorted { $0.relativePath.localizedStandardCompare($1.relativePath) == .orderedAscending }
            .enumerated()
            .map { offset, file in
                APIOutputFile(url: file.url, relativePath: file.relativePath, originalIndex: offset)
            }
    }

    private func apiArchiveOutputFiles(for archive: URL) -> [APIOutputFile]? {
        guard let entries = try? ZipArchiveReader.entries(in: archive) else { return nil }
        let visible = entries.filter { entry in
            entry.isReadable && Self.isArchiveViewerEntry(entry.name)
        }
        guard !visible.isEmpty else { return nil }

        return visible
            .sorted { $0.name.localizedStandardCompare($1.name) == .orderedAscending }
            .enumerated()
            .map { offset, entry in
                APIOutputFile(
                    url: archive.appendingPathComponent(entry.name),
                    relativePath: entry.name,
                    originalIndex: offset,
                    archiveURL: archive,
                    archiveEntry: entry
                )
            }
    }

    private nonisolated static func isArchiveOutputFile(_ url: URL) -> Bool {
        ["zip", "cbz"].contains(url.pathExtension.lowercased())
    }

    private static func isArchiveViewerEntry(_ name: String) -> Bool {
        let ext = URL(fileURLWithPath: name).pathExtension.lowercased()
        return imageExtensions.contains(ext) ||
            videoExtensions.contains(ext) ||
            audioExtensions.contains(ext) ||
            documentExtensions.contains(ext) ||
            ext == "pdf"
    }

    private func apiOutputFileData(_ file: APIOutputFile) throws -> Data {
        if let archiveURL = file.archiveURL,
           let archiveEntry = file.archiveEntry {
            return try ZipArchiveReader.data(for: archiveEntry, in: archiveURL)
        }
        return try Data(contentsOf: file.url)
    }

    private func apiOutputFileSize(_ file: APIOutputFile) -> Int {
        if let entry = file.archiveEntry {
            return entry.uncompressedSize > UInt64(Int.max) ? Int.max : Int(entry.uncompressedSize)
        }
        return (try? file.url.resourceValues(forKeys: [.fileSizeKey]).fileSize) ?? 0
    }

    private func apiOutputFileModifiedDate(_ file: APIOutputFile) -> Date? {
        let url = file.archiveURL ?? file.url
        return try? url.resourceValues(forKeys: [.contentModificationDateKey]).contentModificationDate
    }

    private static func apiOutputDisplayName(_ file: APIOutputFile) -> String {
        if file.archiveEntry != nil {
            return URL(fileURLWithPath: file.relativePath).lastPathComponent
        }
        return file.url.lastPathComponent
    }

    private static func apiOutputDisplayPath(_ file: APIOutputFile) -> String {
        if let archiveURL = file.archiveURL {
            return "\(archiveURL.path)#\(file.relativePath)"
        }
        return file.url.path
    }

    private func isReadableOutputFile(_ file: URL, under root: URL) -> Bool {
        let manager = FileManager.default
        var isDirectory: ObjCBool = false
        guard manager.fileExists(atPath: file.path, isDirectory: &isDirectory), !isDirectory.boolValue else {
            return false
        }
        guard manager.isReadableFile(atPath: file.path) else { return false }
        if file == root { return true }
        return file.path.hasPrefix(root.path.hasSuffix("/") ? root.path : root.path + "/")
    }

