    private func apiAuthQuery(_ password: String) -> String {
        guard !password.isEmpty,
              let encoded = password.addingPercentEncoding(withAllowedCharacters: .urlQueryAllowed) else {
            return ""
        }
        return "&pw=\(encoded)"
    }

    private func apiAuthStandaloneQuery(_ password: String) -> String {
        guard !password.isEmpty,
              let encoded = password.addingPercentEncoding(withAllowedCharacters: .urlQueryAllowed) else {
            return ""
        }
        return "?pw=\(encoded)"
    }

    private func apiInputItems(from request: LocalHTTPRequest) -> [(url: String, metadata: [String: String])] {
        let parameters = apiParameters(from: request)
        if let input = parameters["input"], OriginalBrowserExtensionTask.parse(input) != nil {
            return inputItems(from: input)
        }
        if let url = parameters["url"] ?? parameters["urls"] {
            return inputItems(from: url)
        }
        if let input = parameters["input"] {
            return inputItems(from: input)
        }

        let body = request.bodyText.trimmed
        if Self.apiLooksLikeJSONBody(body) {
            let items = apiInputItems(fromJSONBody: body)
            if !items.isEmpty {
                return items
            }
        }

        if !body.isEmpty {
            return inputItems(from: request.bodyText)
        }

        return []
    }

    private func apiInputItems(fromJSONBody body: String) -> [(url: String, metadata: [String: String])] {
        guard let data = body.data(using: .utf8),
              let object = try? JSONSerialization.jsonObject(with: data) else {
            return []
        }
        return apiInputItems(fromJSONValue: object)
    }

    private func apiInputItems(fromJSONValue value: Any) -> [(url: String, metadata: [String: String])] {
        if let string = value as? String {
            return inputItems(from: string)
        }
        if let array = value as? [Any] {
            return array.flatMap { apiInputItems(fromJSONValue: $0) }
        }
        guard let dictionary = value as? [String: Any] else { return [] }
        let keys = ["input", "url", "urls", "text"]
        return keys.flatMap { key in
            dictionary[key].map { apiInputItems(fromJSONValue: $0) } ?? []
        }
    }

    private nonisolated static func apiTruthy(_ value: String?) -> Bool {
        guard let normalized = value?.trimmed.lowercased(), !normalized.isEmpty else {
            return false
        }
        return !["0", "false", "no", "off", "none"].contains(normalized)
    }

    private nonisolated static func apiFirstParameterValue(in parameters: [String: String], keys: [String]) -> String? {
        for key in keys {
            if let value = parameters[key]?.trimmed, !value.isEmpty {
                return value
            }
            let normalizedKey = apiNormalizedParameterKey(key)
            if let pair = parameters.first(where: { apiNormalizedParameterKey($0.key) == normalizedKey }),
               !pair.value.trimmed.isEmpty {
                return pair.value.trimmed
            }
        }
        return nil
    }

    private nonisolated static func apiParameterValueAllowingEmpty(in parameters: [String: String], keys: [String]) -> String? {
        for key in keys {
            if let value = parameters[key] {
                return value
            }
            let normalizedKey = apiNormalizedParameterKey(key)
            if let pair = parameters.first(where: { apiNormalizedParameterKey($0.key) == normalizedKey }) {
                return pair.value
            }
        }
        return nil
    }

    private nonisolated static func apiNormalizedParameterKey(_ key: String) -> String {
        key.unicodeScalars
            .filter { CharacterSet.alphanumerics.contains($0) }
            .map { String($0).lowercased() }
            .joined()
    }

    private func apiParameters(from request: LocalHTTPRequest) -> [String: String] {
        var parameters = request.query
        let bodyText = request.bodyText
        let contentType = request.headers["content-type"]?.lowercased() ?? ""
        let looksLikeJSON = Self.apiLooksLikeJSONBody(bodyText)

        if contentType.contains("application/json") || looksLikeJSON {
            if let data = bodyText.data(using: .utf8),
               let object = try? JSONSerialization.jsonObject(with: data) as? [String: Any] {
                for (key, value) in object {
                    Self.mergeAPIParameter(key, Self.apiParameterString(from: value), into: &parameters)
                }
                return parameters
            }
        }

        if contentType.contains("application/json") {
            return parameters
        }

        if contentType.contains("application/x-www-form-urlencoded") || bodyText.contains("=") {
            for pair in bodyText.components(separatedBy: "&") {
                let parts = pair.components(separatedBy: "=")
                guard let key = parts.first, !key.isEmpty else { continue }
                let value = parts.dropFirst().joined(separator: "=")
                Self.mergeAPIParameter(Self.formDecode(key), Self.formDecode(value), into: &parameters)
            }
        }

        return parameters
    }

    private static func apiLooksLikeJSONBody(_ bodyText: String) -> Bool {
        let body = bodyText.trimmed
        return body.hasPrefix("{") || body.hasPrefix("[")
    }

    private func apiTicket(from request: LocalHTTPRequest) -> String? {
        if let ticket = request.query["ticket"]?.trimmed, !ticket.isEmpty {
            return ticket
        }
        guard let cookie = request.headers["cookie"] else { return nil }
        for part in cookie.components(separatedBy: ";") {
            let pair = part.split(separator: "=", maxSplits: 1, omittingEmptySubsequences: false)
            guard pair.count == 2,
                  String(pair[0]).trimmed.lowercased() == "ticket" else {
                continue
            }
            let value = String(pair[1]).trimmed
            return value.isEmpty ? nil : value
        }
        return nil
    }

    private func apiSafeRedirect(_ raw: String) -> String {
        let fallback = "/webui"
        let value = raw.trimmed.isEmpty ? fallback : raw.trimmed
        guard value.hasPrefix("/"),
              !value.hasPrefix("//"),
              !value.lowercased().hasPrefix("/\\") else {
            return fallback
        }
        return value
    }

    private func apiListValues(from text: String) -> [String] {
        text
            .replacingOccurrences(of: ",", with: "\n")
            .split(whereSeparator: \.isNewline)
            .map { String($0).trimmed }
            .filter { !$0.isEmpty }
    }

    nonisolated static func apiAuthTicket(for password: String) -> String {
        var data = Data("#hiotmi".utf8)
        data.append(Data(password.utf8))
        let digest = Insecure.MD5.hash(data: data)
        return digest.map { String(format: "%02x", $0) }.joined()
    }

    private nonisolated static func apiAcceptedAuthTickets(for password: String) -> Set<String> {
        [
            apiAuthTicket(for: password),
            apiSHA256AuthTicket(for: password)
        ]
    }

    private nonisolated static func apiSHA256AuthTicket(for password: String) -> String {
        let digest = SHA256.hash(data: Data((password + "#hiotmi").utf8))
        return digest.map { String(format: "%02x", $0) }.joined()
    }

    private static func mergeAPIParameter(_ key: String, _ value: String, into parameters: inout [String: String]) {
        guard !key.isEmpty else { return }
        if let existing = parameters[key], !existing.isEmpty {
            parameters[key] = existing + "\n" + value
        } else {
            parameters[key] = value
        }
    }

    private static func apiParameterString(from value: Any) -> String {
        if let string = value as? String {
            return string
        }
        if let array = value as? [Any] {
            return array.map(apiParameterString(from:)).joined(separator: "\n")
        }
        if value is NSNull {
            return ""
        }
        return String(describing: value)
    }

    private static func formDecode(_ value: String) -> String {
        value
            .replacingOccurrences(of: "+", with: " ")
            .removingPercentEncoding ?? value
    }

    private static func queryComponent(_ value: String) -> String {
        var allowed = CharacterSet.urlQueryAllowed
        allowed.remove(charactersIn: "&=+?#")
        return value.addingPercentEncoding(withAllowedCharacters: allowed) ?? value
    }

    private static func javascriptStringLiteral(_ value: String) -> String {
        let data = (try? JSONSerialization.data(withJSONObject: [value], options: [])) ?? Data(#"[""]"#.utf8)
        let encoded = String(data: data, encoding: .utf8) ?? #"[""]"#
        return String(encoded.dropFirst().dropLast())
    }

    private static func apiLegacyViewKeydownScript(preferences: APIViewPreferences) -> String {
        """
        <script>
          function refresh_preview(){
            var stamp = Date.now().toString();
            var updated = false;
            function refreshedURL(value){
              try {
                var url = new URL(value, location.href);
                url.searchParams.set("refresh", stamp);
                return url.pathname + url.search + url.hash;
              } catch (error) {
                return value;
              }
            }
            document.querySelectorAll("img.page, video.page, audio.page").forEach(function(element){
              ["src", "data-src"].forEach(function(attribute){
                var value = element.getAttribute(attribute);
                if (!value || value.indexOf("/loading.gif") >= 0) return;
                element.setAttribute(attribute, refreshedURL(value));
                updated = true;
              });
              if (element.tagName === "VIDEO" || element.tagName === "AUDIO") element.load();
            });
            if (!updated) location.reload();
          }
          function keydown(e){
            var key = e.keyCode || e.which;
            var alt = e.altKey;
            var ctrl = e.ctrlKey;
            var shift = e.shiftKey;
            var meta = e.metaKey;
            if (key == 116 || ((ctrl || meta) && key == 82)) {
              e.preventDefault();
              refresh_preview();
              return;
            }
            if (ctrl || alt || shift) return;
            var prev = document.getElementById("prev") || document.querySelector("[data-prev]");
            var next = document.getElementById("next") || document.querySelector("[data-next]");
            if (key == \(preferences.previousKeyCode) && prev) prev.click();
            if (key == \(preferences.nextKeyCode) && next) next.click();
          }
          document.addEventListener("keydown", keydown, false);
        </script>
        """
    }

    private static func apiWheelNavigationScript(edgeOnly: Bool = false) -> String {
        """
        (() => {
          const edgeOnly = \(edgeOnly ? "true" : "false");
          const threshold = 90;
          let accumulated = 0;
          let lastDirection = 0;

          function interactiveTarget(target) {
            return target?.closest?.('a, button, input, textarea, select, audio, video, [contenteditable="true"]');
          }

          function canNavigate(direction) {
            if (!edgeOnly) return true;
            const scroller = document.scrollingElement || document.documentElement;
            const atTop = scroller.scrollTop <= 2;
            const atBottom = Math.ceil(scroller.scrollTop + window.innerHeight) >= scroller.scrollHeight - 2;
            return direction < 0 ? atTop : atBottom;
          }

          function navigate(direction) {
            const link = document.querySelector(direction < 0 ? '[data-prev]' : '[data-next]');
            if (!link || !link.href) return false;
            location.href = link.href;
            return true;
          }

          document.addEventListener('wheel', event => {
            if (event.ctrlKey || event.altKey || event.metaKey || event.shiftKey) return;
            if (interactiveTarget(event.target)) return;
            const primaryDelta = Math.abs(event.deltaY) >= Math.abs(event.deltaX) ? event.deltaY : event.deltaX;
            if (Math.abs(primaryDelta) < 1) return;
            const direction = primaryDelta > 0 ? 1 : -1;
            if (!canNavigate(direction)) {
              accumulated = 0;
              lastDirection = direction;
              return;
            }
            if (direction !== lastDirection) accumulated = 0;
            accumulated += primaryDelta;
            lastDirection = direction;
            if (Math.abs(accumulated) < threshold) return;
            if (navigate(direction)) event.preventDefault();
            accumulated = 0;
          }, { passive: false });
        })();
        """
    }

    private static let imageExtensions: Set<String> = ["jpg", "jpeg", "png", "gif", "webp", "avif", "bmp", "heic", "heif"]
    private static let videoExtensions: Set<String> = ["mp4", "m4v", "mov", "webm", "mkv", "avi", "wmv", "flv", "ts"]
    private static let audioExtensions: Set<String> = ["mp3", "m4a", "aac", "wav", "flac", "ogg", "opus"]
    private static let documentExtensions: Set<String> = ["txt", "log", "md", "html", "htm", "json", "xml", "csv"]

    private static func apiMediaType(for url: URL) -> String {
        let ext = url.pathExtension.lowercased()
        if imageExtensions.contains(ext) { return "image" }
        if videoExtensions.contains(ext) { return "video" }
        if audioExtensions.contains(ext) { return "audio" }
        if documentExtensions.contains(ext) { return "document" }
        return "file"
    }

    private nonisolated static func apiDateString(_ date: Date) -> String {
        ISO8601DateFormatter().string(from: date)
    }

    private static func mimeType(for url: URL) -> String {
        switch url.pathExtension.lowercased() {
        case "jpg", "jpeg": return "image/jpeg"
        case "png": return "image/png"
        case "gif": return "image/gif"
        case "webp": return "image/webp"
        case "avif": return "image/avif"
        case "bmp": return "image/bmp"
        case "heic": return "image/heic"
        case "heif": return "image/heif"
        case "mp4", "m4v": return "video/mp4"
        case "mov": return "video/quicktime"
        case "webm": return "video/webm"
        case "mkv": return "video/x-matroska"
        case "avi": return "video/x-msvideo"
        case "wmv": return "video/x-ms-wmv"
        case "flv": return "video/x-flv"
        case "ts": return "video/mp2t"
        case "mp3": return "audio/mpeg"
        case "m4a", "aac": return "audio/aac"
        case "wav": return "audio/wav"
        case "flac": return "audio/flac"
        case "ogg", "opus": return "audio/ogg"
        case "html", "htm": return "text/html; charset=utf-8"
        case "txt", "log": return "text/plain; charset=utf-8"
        case "json": return "application/json"
        case "pdf": return "application/pdf"
        case "zip", "cbz": return "application/zip"
        default: return "application/octet-stream"
        }
    }

    private static func apiIconColor(_ raw: String?) -> String {
        let value = (raw ?? "1a73e8")
            .trimmingCharacters(in: CharacterSet(charactersIn: "#"))
            .filter { $0.isHexDigit }
        guard [3, 4, 6, 8].contains(value.count) else {
            return "#1a73e8"
        }
        return "#\(value)"
    }

    private static func apiIconLabel(_ name: String) -> String {
        let lower = name.lowercased()
        let labels: [String: String] = [
            "home": "H",
            "renew": "R",
            "delete": "D",
            "close": "X",
            "down": "DL",
            "folder_open": "F",
            "folder-open": "F",
            "pin": "P",
            "lock": "L",
            "music": "M",
            "live": "LV"
        ]
        if let label = labels[lower] {
            return label
        }
        let cleaned = lower.replacingOccurrences(of: "fav-", with: "")
        let initials = cleaned
            .split(separator: "-", omittingEmptySubsequences: true)
            .prefix(2)
            .compactMap { $0.first }
            .map { String($0).uppercased() }
            .joined()
        return initials.isEmpty ? "HN" : initials
    }

    private enum APIByteRange {
        case none
        case invalid
        case valid(Range<Int>)
    }

    private static func byteRange(from header: String?, size: Int) -> APIByteRange {
        guard let header, header.lowercased().hasPrefix("bytes=") else { return .none }
        guard size > 0 else { return .invalid }
        let value = String(header.dropFirst("bytes=".count))
        guard !value.contains(",") else { return .invalid }
        let parts = value.split(separator: "-", omittingEmptySubsequences: false)
        guard parts.count == 2 else { return .invalid }

        if parts[0].isEmpty, let suffixLength = Int(parts[1]), suffixLength > 0 {
            let start = max(0, size - suffixLength)
            return .valid(start..<size)
        }

        guard let start = Int(parts[0]), start >= 0, start < size else { return .invalid }
        let end = parts[1].isEmpty ? size - 1 : min(Int(parts[1]) ?? (size - 1), size - 1)
        guard end >= start else { return .invalid }
        return .valid(start..<(end + 1))
    }

    private static func htmlEscape(_ value: String) -> String {
        value
            .replacingOccurrences(of: "&", with: "&amp;")
            .replacingOccurrences(of: "<", with: "&lt;")
            .replacingOccurrences(of: ">", with: "&gt;")
            .replacingOccurrences(of: "\"", with: "&quot;")
            .replacingOccurrences(of: "'", with: "&#39;")
    }

    private func persistProxySettingsForUse() -> Bool {
        if proxyEnabled {
            guard let normalized = NetworkSettings.normalizedProxyURLString(proxyURLString) else {
                addSummary = "Enter a valid proxy URL"
                return false
            }
            proxyURLString = normalized
        }

        proxyBypassList = NetworkSettings.normalizedBypassList(proxyBypassList)
        NetworkSettings(proxyEnabled: proxyEnabled, proxyURLString: proxyURLString, proxyBypassList: proxyBypassList).save()
        return true
    }

    private func startClipboardMonitor() {
        stopClipboardMonitor()
        lastClipboardChangeCount = NSPasteboard.general.changeCount
        scanClipboardForURLs(force: true)
        let timer = Timer(timeInterval: 1.0, repeats: true) { [weak self] _ in
            Task { @MainActor in
                self?.scanClipboardForURLs()
            }
        }
        RunLoop.main.add(timer, forMode: .common)
        clipboardTimer = timer
    }

    private func stopClipboardMonitor() {
        clipboardTimer?.invalidate()
        clipboardTimer = nil
    }

    private func scanClipboardForURLs(force: Bool = false) {
        let pasteboard = NSPasteboard.general
        processClipboardSnapshot(pasteboard.string(forType: .string), changeCount: pasteboard.changeCount, force: force)
    }

    @discardableResult
    func processClipboardSnapshot(_ text: String?, changeCount: Int, force: Bool = false) -> Int {
        guard force || changeCount != lastClipboardChangeCount else { return 0 }
        lastClipboardChangeCount = changeCount
        guard let text, !text.trimmed.isEmpty else { return 0 }
        let added = enqueueClipboardText(text)
        if added > 0 {
            if playSoundOnClipboardAdd {
                completionAlerts.playClipboardSound()
            }
            addSummary = "\(added) clipboard URLs added"
        }
        return added
    }

