    private nonisolated static func sankakuTagInputURLString(from raw: String) -> String? {
        let token = raw.trimmed.trimmingCharacters(in: CharacterSet(charactersIn: "<>\"'(){},;"))
        guard !token.isEmpty else { return nil }
        let pattern = #"^\[(chan|idol|www|app)\]\s+(.+)$"#
        guard let regex = try? NSRegularExpression(pattern: pattern, options: [.caseInsensitive]) else {
            return nil
        }
        let range = NSRange(token.startIndex..<token.endIndex, in: token)
        guard let match = regex.firstMatch(in: token, range: range),
              let sectionRange = Range(match.range(at: 1), in: token),
              let tagsRange = Range(match.range(at: 2), in: token) else {
            return nil
        }
        let sectionName = String(token[sectionRange]).lowercased()
        let tags = String(token[tagsRange]).trimmed
        guard let section = SankakuSection(rawValue: sectionName) else { return nil }
        return SankakuResolver.tagSearchURLString(section: section, tags: tags)
    }

    private nonisolated static func booruTagInputURLString(from raw: String) -> String? {
        let token = raw.trimmed.trimmingCharacters(in: CharacterSet(charactersIn: "<>\"'(){},;"))
        guard !token.isEmpty else { return nil }

        let bracketPattern = #"^\[(danbooru|gelbooru|rule34|yande(?:re)?)\]\s+(.+)$"#
        if let regex = try? NSRegularExpression(pattern: bracketPattern, options: [.caseInsensitive]) {
            let range = NSRange(token.startIndex..<token.endIndex, in: token)
            if let match = regex.firstMatch(in: token, range: range),
               let providerRange = Range(match.range(at: 1), in: token),
               let tagsRange = Range(match.range(at: 2), in: token),
               let provider = booruProvider(named: String(token[providerRange])) {
                return booruTagSearchURLString(provider: provider, tags: String(token[tagsRange]))
            }
        }

        let lowercased = token.lowercased()
        let prefixes = [
            ("danbooru:", BooruProvider.danbooru),
            ("danbooru/", BooruProvider.danbooru),
            ("gelbooru:", BooruProvider.gelbooru),
            ("gelbooru/", BooruProvider.gelbooru),
            ("rule34:", BooruProvider.rule34),
            ("rule34/", BooruProvider.rule34),
            ("yande:", BooruProvider.yandere),
            ("yande/", BooruProvider.yandere),
            ("yandere:", BooruProvider.yandere),
            ("yandere/", BooruProvider.yandere)
        ]
        guard let match = prefixes.first(where: { lowercased.hasPrefix($0.0) }) else {
            return nil
        }
        return booruTagSearchURLString(provider: match.1, tags: String(token.dropFirst(match.0.count)))
    }

    private nonisolated static func booruProvider(named raw: String) -> BooruProvider? {
        switch raw.lowercased() {
        case "danbooru":
            return .danbooru
        case "gelbooru":
            return .gelbooru
        case "rule34":
            return .rule34
        case "yande", "yandere":
            return .yandere
        default:
            return nil
        }
    }

    private nonisolated static func booruTagSearchURLString(provider: BooruProvider, tags rawTags: String) -> String? {
        let encodedTags = booruEncodedTags(rawTags)
        guard !encodedTags.isEmpty else { return nil }
        switch provider {
        case .danbooru:
            return "https://danbooru.donmai.us/posts?tags=\(encodedTags)"
        case .gelbooru:
            return "https://gelbooru.com/index.php?page=post&s=list&tags=\(encodedTags)"
        case .rule34:
            return "https://rule34.xxx/index.php?page=post&s=list&tags=\(encodedTags)"
        case .yandere:
            return "https://yande.re/post?tags=\(encodedTags)"
        }
    }

    private nonisolated static func booruEncodedTags(_ rawTags: String) -> String {
        var tags = rawTags.trimmed
        if let decoded = tags.removingPercentEncoding {
            tags = decoded
        }
        tags = tags.replacingOccurrences(of: #"\s+"#, with: "+", options: .regularExpression)
        while tags.contains("++") {
            tags = tags.replacingOccurrences(of: "++", with: "+")
        }
        tags = tags.trimmingCharacters(in: CharacterSet(charactersIn: "+"))
        var allowed = CharacterSet.alphanumerics
        allowed.insert(charactersIn: "-._~+:")
        return tags.addingPercentEncoding(withAllowedCharacters: allowed) ?? tags
    }

    private nonisolated static func isTorrentInfoHash(_ token: String) -> Bool {
        token.range(of: #"^[A-Fa-f0-9]{40}$"#, options: .regularExpression) != nil
    }

    private nonisolated static func looksLikeBareWebURL(_ token: String) -> Bool {
        guard !token.contains("\\"),
              !token.hasPrefix("/"),
              !token.hasPrefix("."),
              !token.contains("@") else {
            return false
        }

        let host = token
            .split(separator: "/", maxSplits: 1, omittingEmptySubsequences: true)
            .first?
            .split(separator: "?", maxSplits: 1, omittingEmptySubsequences: true)
            .first?
            .split(separator: "#", maxSplits: 1, omittingEmptySubsequences: true)
            .first
            .map(String.init) ?? ""
        guard !host.isEmpty else { return false }

        let hostWithoutPort = host.split(separator: ":", maxSplits: 1).first.map(String.init) ?? host
        if hostWithoutPort.lowercased() == "localhost" { return true }
        guard hostWithoutPort.contains("."),
              hostWithoutPort.range(of: #"^[A-Za-z0-9-]+(\.[A-Za-z0-9-]+)+$"#, options: .regularExpression) != nil else {
            return false
        }

        let knownTLDs: Set<String> = [
            "app", "biz", "cc", "cn", "co", "com", "dev", "edu", "fm", "gg",
            "gov", "io", "jp", "kr", "la", "me", "net", "org", "site", "test",
            "tv", "uk", "us", "wiki", "xyz"
        ]
        let tld = hostWithoutPort.split(separator: ".").last.map { String($0).lowercased() } ?? ""
        return knownTLDs.contains(tld)
    }

    private static func isMonitorableURL(_ text: String) -> Bool {
        guard let url = URL(string: text), let scheme = url.scheme?.lowercased() else {
            return false
        }
        return scheme == "http" || scheme == "https" || scheme == "magnet" || scheme == "file"
    }

    private static func restoredQueueJob(_ job: DownloadJob) -> DownloadJob {
        var restored = job
        if restored.status == .resolving || restored.status == .downloading {
            restored.title = restored.source
            restored.status = .queued
            restored.progress = 0
            restored.completed = 0
            restored.total = 0
            restored.message = "Restored after relaunch"
            restored.outputPath = ""
        }
        return restored
    }

    private nonisolated static func isPendingQueueRemoval(_ job: DownloadJob) -> Bool {
        job.metadata[pendingQueueRemovalMetadataKey]?.trimmed.lowercased() == "true"
    }

    private nonisolated static func isPendingQueueOutputDeletion(_ job: DownloadJob) -> Bool {
        job.metadata[pendingQueueOutputDeletionMetadataKey]?.trimmed.lowercased() == "true"
    }

    private func restoredRetrySnapshot(_ snapshot: DownloadJob) -> DownloadJob {
        var restored = snapshot
        restored.message = restored.message.trimmed.isEmpty ? "Retry cancelled; restored previous state" : restored.message
        return restored
    }

    private func isActive(_ status: JobStatus) -> Bool {
        status == .resolving || status == .downloading
    }

    private func isRetryableIncompleteJob(_ job: DownloadJob) -> Bool {
        guard !isActive(job.status), !isFoldedQueueJob(job) else { return false }
        if job.status == .failed || job.status == .cancelled {
            return true
        }
        return job.status == .finished && job.total > 0 && job.completed < job.total
    }

    private func isRemovableCompletedJob(_ job: DownloadJob) -> Bool {
        job.status == .finished &&
            (job.total <= 0 || job.completed >= job.total) &&
            !isProtected(job) &&
            !isFoldedQueueJob(job)
    }

    private func isRemovableFinishedJob(_ job: DownloadJob) -> Bool {
        !isProtected(job) && (job.status == .finished || job.status == .failed || job.status == .cancelled)
    }

    private func isFoldedQueueJob(_ job: DownloadJob) -> Bool {
        guard let groupID = jobGroupID(for: job),
              let group = queueGroups.first(where: { $0.id == groupID }) else {
            return false
        }
        return !group.isExpanded
    }

    private func isProtected(_ job: DownloadJob) -> Bool {
        job.isLocked
    }
}

actor AsyncSemaphore {
    private var value: Int
    private var waiters: [CheckedContinuation<Void, Never>] = []

    init(value: Int) {
        self.value = max(1, value)
    }

    func wait() async {
        if value > 0 {
            value -= 1
            return
        }

        await withCheckedContinuation { continuation in
            waiters.append(continuation)
        }
    }

    func signal() {
        if waiters.isEmpty {
            value += 1
        } else {
            waiters.removeFirst().resume()
        }
    }

    func withPermit<T: Sendable>(
        _ operation: @Sendable () async throws -> T
    ) async throws -> T {
        await wait()
        do {
            try Task.checkCancellation()
            let result = try await operation()
            signal()
            return result
        } catch {
            signal()
            throw error
        }
    }
}
